app.MapGet("/api/master/{cat}", async (string cat, AppDbContext db, ITenantContext t, string? q) =>
{
    var query = db.Masters.Where(m => m.OrgId == t.OrgId && m.Category == cat);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(m => m.Code.Contains(q) || m.Name.Contains(q));
    var items = await query.OrderBy(m => m.Code).Select(m => new { m.Code, m.Name, m.ParentCode, m.Status }).ToListAsync();
    return Results.Ok(new { category = cat, count = items.Count, items });
}).RequireAuthorization();

// Category có cha bắt buộc (audit 2026-09-03 — FrmDistrict cần ProvinceCode, FrmProvince cần AreaCode; bỏ sót ở lần port đầu tiên).
// audit 2026-09-03: "Certificate" cần scope theo SMType (Mst_SalesManType) — nguồn FrmCertificate.cs cột
// SMType + FrmCreateSalesMan lọc chứng chỉ theo SMType đã chọn (lueSMType_EditValueChanged → dvCer.RowFilter SMType).
var MasterParentRule = new Dictionary<string, string> { ["District"] = "Province", ["Province"] = "__Area__", ["Certificate"] = "__SalesManType__" };

app.MapPost("/api/master/{cat}", async (string cat, MasterDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Code) || string.IsNullOrWhiteSpace(dto.Name))
        return Results.BadRequest(new { error = "Cần Code và Name." });
    var code = dto.Code.Trim().ToUpperInvariant();
    string? parentCode = string.IsNullOrWhiteSpace(dto.ParentCode) ? null : dto.ParentCode.Trim().ToUpperInvariant();
    if (MasterParentRule.TryGetValue(cat, out var parentCat))
    {
        if (parentCode is null) return Results.BadRequest(new { error = $"Category '{cat}' cần ParentCode." });
        bool parentExists = parentCat == "__Area__"
            ? await db.Areas.AnyAsync(a => a.OrgId == t.OrgId && a.AreaCode == parentCode)
            : parentCat == "__SalesManType__"
            ? await db.SalesManTypes.AnyAsync(s => s.OrgId == t.OrgId && s.SMType == parentCode)
            : await db.Masters.AnyAsync(m => m.OrgId == t.OrgId && m.Category == parentCat && m.Code == parentCode);
        if (!parentExists) return Results.BadRequest(new { error = $"ParentCode '{parentCode}' không tồn tại." });
    }
    var m = await db.Masters.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Category == cat && x.Code == code);
    if (m is null) { m = new MasterItem { OrgId = t.OrgId, Category = cat, Code = code, Name = dto.Name.Trim(), ParentCode = parentCode, Status = dto.Status ?? "1" }; db.Masters.Add(m); }
    else { m.Name = dto.Name.Trim(); m.ParentCode = parentCode; m.Status = dto.Status ?? m.Status; }
    await db.SaveChangesAsync();
    return Results.Ok(new { category = cat, m.Code, m.Name, m.ParentCode, m.Status });
}).RequireAuthorization();

app.MapDelete("/api/master/{cat}/{code}", async (string cat, string code, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var m = await db.Masters.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Category == cat && x.Code == code);
    if (m is null) return Results.NotFound(new { cat, code });
    db.Masters.Remove(m); await db.SaveChangesAsync();
    return Results.Ok(new { deleted = code });
}).RequireAuthorization();

// ===== 🔴 #232 ĐỊA ĐIỂM GIAO HÀNG — `Mst_DeliveryLocation` (TCMotor DMSCarSv/TST) =====
// Màn: `Views/TST/FrmMst_DeliveryLocationMng.cs` (525 dòng, tra cứu + mở màn tạo) và
//      `FrmMst_DeliveryLocation.cs` (278 dòng, nhập liệu). Tầng service `Mst_DeliveryLocationService.cs`
//      (Get/Add/Update/Delete) → WS `WSCarSv.asmx.cs:39369` → biz `BizCarSv.Master.cs:11256`
//      (hàm làm việc thật là `Mst_DeliveryLocation_GetX` :11108).
// BƯỚC 3B: `BizCarSv.Master.cs` md5 `90585079` (12871 dòng) — KHỚP laptop và máy 150 (đã đo ở #227).
//
// 🔴 KHOÁ LÀ CẶP (DeliveryLocationCode, DealerCode) — xem chú thích entity.
// 🔴 BỐN bộ lọc của nguồn (`SqlUtils.BuildClause`, :11202-11205): DeliveryLocationCode · DealerCode ·
//    DeliveryLocationName · FlagActive. Tầng service bọc `%…%` cho **mã** và **tên**
//    (`GenLikeCondition2Percent`) nhưng để `=` cho DealerCode và FlagActive (`GenEqualCondition2`)
//    ⇒ mã và tên khớp CHỨA, hai cái kia khớp CHÍNH XÁC. Giữ đúng bất đối xứng này.
// ⚠️ Nguồn nối `inner join Mst_Dealer` để lấy `DealerName` ⇒ địa điểm trỏ tới đại lý KHÔNG tồn tại sẽ
//    **bị loại khỏi kết quả** (không phải left join). Giữ đúng.
//
// 🔴 LỖI CỦA NGUỒN — ĐÃ SỬA, có ghi lại: `#tbl_..._Filter_Draft` chỉ `select distinct DeliveryLocationCode`
//    (thiếu DealerCode) rồi bước cuối join lại `on t.DeliveryLocationCode = mdl.DeliveryLocationCode` —
//    cũng thiếu DealerCode. Vì khoá là CẶP, hai đại lý trùng mã sẽ làm kết quả **NỞ DÒNG**, và lọc theo
//    `DealerCode` (chỉ áp ở bước Draft) **không cứu được** vì join cuối đã kéo lại mọi đại lý.
//    Bản port lọc và khớp theo ĐỦ CẶP. Đây là sai lệch CỐ Ý so với nguồn, dựa trên chính khoá mà
//    `_Update`/`_Delete`/`CheckDB` của nguồn dùng.
app.MapGet("/api/deliverylocations", async (AppDbContext db, ITenantContext t,
    string? deliveryLocationCode, string? dealerCode, string? deliveryLocationName, string? flagActive) =>
{
    var qy = from d in db.DeliveryLocations.Where(x => x.OrgId == t.OrgId)
             join dl in db.Dealers.Where(x => x.OrgId == t.OrgId) on d.DealerCode equals dl.DealerCode
             select new { d, dealerName = dl.DealerName };

    // khớp CHỨA (nguồn bọc %…%)
    if (!string.IsNullOrWhiteSpace(deliveryLocationCode))
        qy = qy.Where(x => x.d.DeliveryLocationCode.ToLower().Contains(deliveryLocationCode!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(deliveryLocationName))
        qy = qy.Where(x => x.d.DeliveryLocationName.ToLower().Contains(deliveryLocationName!.Trim().ToLower()));
    // khớp CHÍNH XÁC (nguồn dùng GenEqualCondition2)
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.d.DealerCode == dealerCode!.Trim());
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.d.FlagActive == flagActive!.Trim());

    var items = await qy.OrderBy(x => x.d.DeliveryLocationCode).ThenBy(x => x.d.DealerCode)
        .Select(x => new { x.d.DeliveryLocationCode, x.d.DealerCode, x.dealerName,
                           x.d.DeliveryLocationName, x.d.FlagActive, x.d.LogLUDateTime, x.d.LogLUBy })
        .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Thêm/sửa — port `Mst_DeliveryLocation_Add` (BizCarSv.Master.cs:11386) và `_Update`.
// NĂM guard của `_Add`, port đủ:
//  1. `DeliveryLocationCode` rỗng ⇒ `Add_InvalidDeliveryLocationCode`
//  2. `DealerCode` rỗng ⇒ `Add_InvalidDealerCode`
//  3. `Mst_Dealer_CheckDB(FlagExist=Yes, FlagActiveList=Active)` ⇒ đại lý phải TỒN TẠI **và ĐANG HOẠT ĐỘNG**
//  4. `Mst_DeliveryLocation_CheckDB(code, dealerCode, FlagExistToCheck = **No**)` ⇒ cặp khoá **không được trùng**
//  5. Tên rỗng ⇒ lỗi; tên **> 200 ký tự** ⇒ lỗi ("Tên địa điểm không được nhập quá dài!")
// ⚠️ `_Add` đặt `FlagActive = Active` CỨNG (không nhận từ client); chỉ `_Update` mới đổi được cờ.
app.MapPost("/api/deliverylocations", async (DeliveryLocationDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.DeliveryLocationCode ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    var name = (dto.DeliveryLocationName ?? "").Trim();
    if (code.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã địa điểm giao hàng." });
    // 🔴 #249 GUARD KÝ TỰ ĐẶC BIỆT — `FrmMst_DeliveryLocation.cs` kiểm `regex.IsMatch(deliveryLocationCode)`.
    //    #232 port màn này mà BỎ SÓT guard; sweep "màn nào dùng regex của lớp cha" mới lộ ra.
    // #257: dùng ĐÚNG hằng của nguồn `MSG_WARNING_KEYSPE_DELIVERYLOCATIONCODE` (Constants.cs:40) =
    //   "Mã **địa điểm** không được phép chứa các ký tự đặc biệt" — #249 tôi tự chế thành
    //   "Mã địa điểm **giao hàng**…", sai chữ so với nguồn.
    if (HasSpecialChar(code))
        return Results.BadRequest(new { error = "Mã địa điểm không được phép chứa các ký tự đặc biệt", code });
    if (dealer.Length == 0) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    if (name.Length == 0) return Results.BadRequest(new { error = "Chưa nhập tên địa điểm giao hàng." });
    if (name.Length > 200) return Results.BadRequest(new { error = "Tên địa điểm không được nhập quá dài!" });

    var d = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer);
    if (d is null) return Results.BadRequest(new { error = $"Đại lý {dealer} không tồn tại." });
    if (d.FlagActive != "1") return Results.BadRequest(new { error = $"Đại lý {dealer} đang ngừng hoạt động." });

    var row = await db.DeliveryLocations.FirstOrDefaultAsync(
        x => x.OrgId == t.OrgId && x.DeliveryLocationCode == code && x.DealerCode == dealer);
    var isNew = row is null;
    if (row is null)
    {
        row = new DeliveryLocation { OrgId = t.OrgId, DeliveryLocationCode = code, DealerCode = dealer };
        db.DeliveryLocations.Add(row);
        row.FlagActive = "1";   // _Add đặt cứng Active; client không đổi được lúc tạo
    }
    else if (!string.IsNullOrWhiteSpace(dto.FlagActive))
    {
        row.FlagActive = dto.FlagActive!.Trim();   // chỉ _Update mới nhận cờ
    }
    row.DeliveryLocationName = name;
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { row.DeliveryLocationCode, row.DealerCode, row.DeliveryLocationName,
                            row.FlagActive, row.LogLUDateTime, row.LogLUBy, created = isNew });
}).RequireAuthorization();

// Xoá — nguồn `Mst_DeliveryLocation_Delete` truyền ĐỦ CẶP (code, dealerCode).
app.MapDelete("/api/deliverylocations/{dealerCode}/{code}", async (
    string dealerCode, string code, AppDbContext db, ITenantContext t) =>
{
    dealerCode = dealerCode.Trim(); code = code.Trim();
    var row = await db.DeliveryLocations.FirstOrDefaultAsync(
        x => x.OrgId == t.OrgId && x.DeliveryLocationCode == code && x.DealerCode == dealerCode);
    if (row is null) return Results.NotFound(new { dealerCode, code });
    db.DeliveryLocations.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = code, dealerCode });
}).RequireAuthorization();

// ===== Đại lý (Mst_Dealer) — port 1:1 FrmDealer =====
app.MapGet("/api/dealers", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var query = db.Dealers.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(d => d.DealerCode.Contains(q) || d.DealerName.Contains(q));
    var items = await query.OrderBy(d => d.DealerCode).Select(d => new
    { d.DealerCode, d.DealerName, d.DealerType, d.BUCode, d.BuPattern, d.ProvinceCode, d.Address, d.Phone, d.Fax, d.Email, d.TaxCode,
      d.FlagDirect, d.FlagActive, d.FlagDealerHTC, d.OrgHCCID, d.NetworkHCCID, d.DealerScale,   // #349 §12 d.MRKAMCode, d.DealerPhoneNo, d.DealerFaxNo, d.CompanyName, d.CompanyAddress, d.ShowroomAddress,
      d.GarageAddress, d.GarageManagerPhoneNo, d.GarageFaxNo, d.DirectorName, d.DirectorPhoneNo, d.DirectorEmail,
      d.SalesManagerName, d.SalesManagerPhoneNo, d.SalesManagerEmail, d.GarageManagerName, d.GarageManagerEmail,
      d.ContactName, d.Signer, d.SignerPosition, d.CtrNoSigner, d.CtrNoSignerPosition, d.Remark, d.HTCStaffInCharge,
      d.DealerAddress01, d.DealerAddress02, d.DealerAddress03, d.DealerAddress04, d.DealerAddress05,
      d.FlagTCG, d.FlagOrdTCG, d.FlagAutoLXX, d.FlagAutoMapVIN, d.FlagAutoSOAppr, d.Status }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Khớp gviewDb_ValidatingEditor gốc: ProvinceCode/BUCode/BuPattern/DealerName bắt buộc.
app.MapPost("/api/dealers", async (DealerDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode) || string.IsNullOrWhiteSpace(dto.DealerName))
        return Results.BadRequest(new { error = "Cần DealerCode và DealerName." });
    if (string.IsNullOrWhiteSpace(dto.ProvinceCode) || string.IsNullOrWhiteSpace(dto.BUCode) || string.IsNullOrWhiteSpace(dto.BuPattern))
        return Results.BadRequest(new { error = "Cần ProvinceCode, BUCode và BuPattern." });
    var code = dto.DealerCode.Trim().ToUpperInvariant();
    var d = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == code);
    if (d is null) { d = new Dealer { OrgId = t.OrgId, DealerCode = code }; db.Dealers.Add(d); }
    d.DealerName = dto.DealerName.Trim(); d.DealerType = dto.DealerType; d.BUCode = dto.BUCode; d.BuPattern = dto.BuPattern; d.ProvinceCode = dto.ProvinceCode;
    d.Address = dto.Address; d.Phone = dto.Phone; d.Fax = dto.Fax; d.Email = dto.Email; d.TaxCode = dto.TaxCode;
    d.FlagDirect = dto.FlagDirect; d.FlagActive = dto.FlagActive; d.DealerScale = dto.DealerScale;
    d.FlagDealerHTC = dto.FlagDealerHTC;   // #335 §12
    // ===== 🔴 #349 HAI MÃ ĐỊNH DANH HCC của đại lý =====
    // Trong **mọi** cây nguồn, `OrgHCCID`/`NetworkHCCID` chỉ xuất hiện ở mệnh đề ĐỌC
    //   (`md.OrgHCCID OrgID`, `md.NetworkHCCID NetworkID` — `BizCarSv.HCC.cs:76`, `BizHTC.HCC.cs:367`…)
    //   để dựng payload gửi HCC; **không có câu GHI nào**. Chúng là **dữ liệu master** của đại lý,
    //   nhập qua màn danh mục chứ không do nghiệp vụ sinh ra.
    // ⇒ Thiếu đường ghi thì payload HCC **vĩnh viễn rỗng hai trường định danh** — tích hợp không chạy được.
    //   Đưa vào chính cổng master đại lý (cùng cách đã làm với `FlagDealerHTC` ở #335), KHÔNG phải
    //   tự chế luật nghiệp vụ: đây là ô nhập danh mục như `50` trường master khác của endpoint này.
    d.OrgHCCID = dto.OrgHCCID; d.NetworkHCCID = dto.NetworkHCCID;
    d.DealerPhoneNo = dto.DealerPhoneNo; d.DealerFaxNo = dto.DealerFaxNo; d.CompanyName = dto.CompanyName; d.CompanyAddress = dto.CompanyAddress;
    d.ShowroomAddress = dto.ShowroomAddress; d.GarageAddress = dto.GarageAddress; d.GarageManagerPhoneNo = dto.GarageManagerPhoneNo; d.GarageFaxNo = dto.GarageFaxNo;
    d.DirectorName = dto.DirectorName; d.DirectorPhoneNo = dto.DirectorPhoneNo; d.DirectorEmail = dto.DirectorEmail;
    d.SalesManagerName = dto.SalesManagerName; d.SalesManagerPhoneNo = dto.SalesManagerPhoneNo; d.SalesManagerEmail = dto.SalesManagerEmail;
    d.GarageManagerName = dto.GarageManagerName; d.GarageManagerEmail = dto.GarageManagerEmail;
    d.ContactName = dto.ContactName; d.Signer = dto.Signer; d.SignerPosition = dto.SignerPosition; d.CtrNoSigner = dto.CtrNoSigner; d.CtrNoSignerPosition = dto.CtrNoSignerPosition;
    d.Remark = dto.Remark; d.HTCStaffInCharge = dto.HTCStaffInCharge;
    d.DealerAddress01 = dto.DealerAddress01; d.DealerAddress02 = dto.DealerAddress02; d.DealerAddress03 = dto.DealerAddress03; d.DealerAddress04 = dto.DealerAddress04; d.DealerAddress05 = dto.DealerAddress05;
    d.FlagTCG = dto.FlagTCG; d.FlagOrdTCG = dto.FlagOrdTCG; d.FlagAutoLXX = dto.FlagAutoLXX; d.FlagAutoMapVIN = dto.FlagAutoMapVIN; d.FlagAutoSOAppr = dto.FlagAutoSOAppr;
    d.Status = dto.Status ?? "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DealerCode, d.DealerName, d.Status });
}).RequireAuthorization();

// Import hàng loạt data thật từ Mst_Dealer (SQL nguồn 2010.HTC) — dedupe theo DealerCode.
app.MapPost("/api/import/dealers", async (List<ImportDealerRowDto> rows, AppDbContext db, ITenantContext t) =>
{
    if (rows is null || rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu import." });
    int added = 0, updated = 0;
    foreach (var r in rows)
    {
        if (string.IsNullOrWhiteSpace(r.DealerCode)) continue;
        var code = r.DealerCode.Trim().ToUpperInvariant();
        var d = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == code);
        if (d is null) { d = new Dealer { OrgId = t.OrgId, DealerCode = code }; db.Dealers.Add(d); added++; } else updated++;
        d.DealerName = r.DealerName ?? d.DealerName; d.DealerType = r.DealerType; d.BUCode = r.BUCode; d.BuPattern = r.BuPattern; d.ProvinceCode = r.ProvinceCode;
        d.DealerPhoneNo = r.DealerPhoneNo; d.DealerFaxNo = r.DealerFaxNo; d.CompanyName = r.CompanyName; d.CompanyAddress = r.CompanyAddress; d.ShowroomAddress = r.ShowroomAddress;
        d.TaxCode = r.TaxCode; d.DirectorName = r.DirectorName; d.DirectorPhoneNo = r.DirectorPhoneNo; d.DirectorEmail = r.DirectorEmail;
        d.ContactName = r.ContactName; d.FlagDirect = r.FlagDirect; d.FlagActive = r.FlagActive; d.DealerScale = r.DealerScale; d.Remark = r.Remark;
        d.Status = r.FlagActive == "0" ? "0" : "1";
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added, updated, total = rows.Count });
}).RequireAuthorization();

app.MapDelete("/api/dealers/{code}", async (string code, AppDbContext db, ITenantContext t) =>
