    var cars = (dto.Cars ?? new List<BankBillCarDto>()).Where(c => !string.IsNullOrWhiteSpace(c.Vin)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
