        x.OS_HDDT_RefNo, x.PaymentMethodCode, x.TotalValInvoice, x.TotalValVAT, x.TotalValPmt,
        x.ValGoodsNotTaxable, x.ValGoodsNotChargeTax, x.ValGoodsVAT5, x.ValVAT5, x.ValGoodsVAT10, x.ValVAT10,
        x.CurrencyCode, x.CurrencyRate,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Nhận MÃ TRA CỨU do hệ HDDT cấp về.
app.MapPost("/api/vatinvoices/{code}/hddt", async (
    string code, VatHddtDto dto, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var v = await db.VatInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == code);
    if (v is null) return Results.NotFound(new { code });

    // Nguồn chỉ đẩy hoá đơn đã có số; hoá đơn chưa duyệt/đã huỷ thì không đẩy.
    if (v.VatHTCStatus != "F")
        return Results.BadRequest(new { error = $"Chỉ đẩy HDDT cho hoá đơn đã duyệt (đang: {v.VatHTCStatus})." });
    if (string.IsNullOrWhiteSpace(v.HTCInvoiceNo))
        return Results.BadRequest(new { error = "Hoá đơn chưa được gán số — chưa đẩy HDDT được." });

    var invCode = (dto.OS_HDDT_InvoiceCode ?? "").Trim();
    if (invCode.Length == 0)
        return Results.BadRequest(new { error = "Chưa có mã tra cứu do hệ HDDT cấp (không được tự sinh)." });
    // Đã có mã tra cứu thì KHÔNG ghi đè — tránh mất vết hoá đơn đã phát hành trên cổng HDDT.
    if (!string.IsNullOrWhiteSpace(v.OS_HDDT_InvoiceCode))
        return Results.BadRequest(new { error = $"Hoá đơn đã có mã tra cứu HDDT ({v.OS_HDDT_InvoiceCode})." });

    v.OS_HDDT_InvoiceCode = invCode;
    if (!string.IsNullOrWhiteSpace(dto.OS_HDDT_RefNo)) v.OS_HDDT_RefNo = dto.OS_HDDT_RefNo!.Trim();
    v.HddtSyncedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { v.HTCInvoiceCode, v.OS_HDDT_InvoiceCode, v.OS_HDDT_RefNo, v.HddtSyncedAt });
}).RequireAuthorization();

var vatStatusNames = new Dictionary<string, string>
{
    ["P"] = "Chờ duyệt",
    ["F"] = "Đã duyệt / đã phát hành",
    ["C"] = "Đã huỷ",
    ["R"] = "Bị từ chối",
};

app.MapGet("/api/vatinvoices/statuses", () => Results.Ok(new
{
    statuses = vatStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Mã theo TConst.Stage của nguồn. Nguồn TÁCH 'duyệt' và 'gán số hoá đơn' thành 2 bước.",
})).RequireAuthorization();

// 🔴 GÁN SỐ HOÁ ĐƠN — bước RIÊNG của nguồn (Biz.HTC.WH.cs:123182), port cũ gộp vào "issue".
// Luật quan trọng nhất: **SỐ hoá đơn phải ĐỒNG BIẾN với NGÀY hoá đơn** trong cùng ký hiệu:
//   - so với hoá đơn có số LIỀN DƯỚI: ngày mới KHÔNG được sớm hơn ngày của nó;
//   - so với hoá đơn có số LIỀN TRÊN: ngày mới KHÔNG được muộn hơn ngày của nó.
// Port cũ không có luật này ⇒ phát hành được hoá đơn số lớn mang ngày lùi về trước.
app.MapPost("/api/vatinvoices/{code}/invoiceno", async (
    string code, VatInvoiceNoDto dto, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var v = await db.VatInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == code);
    if (v is null) return Results.NotFound(new { code });

    var noStr = (dto.HTCInvoiceNo ?? "").Trim();
    if (noStr.Length == 0) return Results.BadRequest(new { error = "Chưa nhập số hoá đơn." });
    if (!decimal.TryParse(noStr, out var noVal))
        return Results.BadRequest(new { error = "Số hoá đơn phải là số (nguồn so sánh bằng giá trị số)." });

    // 🔴 #274 ĐỘ DÀI: nguồn `if (strHTCInvoiceNo.Length < 7) throw ..._HTCInvoiceNoInvalidLength`,
    //   kèm dòng cũ bị comment `//if (strHTCInvoiceNo.Length != 7)` và ghi chú *"20180308 nới luật check số
    //   hoá đơn"* ⇒ luật ĐANG CHẠY là **tối thiểu 7**, KHÔNG phải đúng 7. Port theo dòng đang chạy.
    if (noStr.Length < 7)
        return Results.BadRequest(new { error = "Số hoá đơn phải có ít nhất 7 ký tự.", htcInvoiceNo = noStr });
    if (dto.HTCInvoiceDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày hoá đơn." });
    var idCode = string.IsNullOrWhiteSpace(dto.InvoiceIDCode) ? v.InvoiceIDCode : dto.InvoiceIDCode!.Trim();
    if (string.IsNullOrWhiteSpace(idCode)) return Results.BadRequest(new { error = "Chưa có ký hiệu hoá đơn." });
    var day = dto.HTCInvoiceDate.Value.Date;

    // 🔴 #274 TRÙNG SỐ HOÁ ĐƠN — nguồn `..._HTCInvoiceNoExist` (:9190). Port cũ thiếu hẳn.
    //   Cùng phạm vi với phép tìm liền kề: cùng ký hiệu + cùng loại + chưa bị huỷ/từ chối.
    var noExists = await db.VatInvoices.AnyAsync(x => x.OrgId == t.OrgId && x.InvoiceIDCode == idCode
        && x.InvoiceIDType == "HTC" && x.HTCInvoiceCode != code && x.HTCInvoiceNo == noStr
        && x.VatHTCStatus != "R" && x.VatHTCStatus != "C");
    if (noExists)
        return Results.BadRequest(new { error = "Số hoá đơn đã tồn tại trong cùng ký hiệu.", htcInvoiceNo = noStr, invoiceIDCode = idCode });

    // Cùng ký hiệu, khác chính nó, đã có số + ngày.
    // 🔴 #274 BỔ SUNG HAI ĐIỀU KIỆN LỌC của nguồn (:9262-9268) mà port cũ THIẾU:
    //   `and vt.InvoiceIDType = 'HTC'` và `and vt.VatHTCStatus not in ('R','C')`.
    //   Thiếu vế trạng thái là lỗi THẬT: một hoá đơn **đã huỷ/bị từ chối** vẫn được coi là "hàng xóm" và
    //   **chặn oan** ngày của hoá đơn đang lập. Hoá đơn đã huỷ thì không còn ràng buộc thứ tự ngày nữa.
    var siblings = await db.VatInvoices
        .Where(x => x.OrgId == t.OrgId && x.InvoiceIDCode == idCode && x.HTCInvoiceCode != code
                    && x.InvoiceIDType == "HTC"
                    && x.VatHTCStatus != "R" && x.VatHTCStatus != "C"
                    && x.HTCInvoiceNo != "" && x.HTCInvoiceDate != null)
        .Select(x => new { x.HTCInvoiceNo, x.HTCInvoiceDate }).ToListAsync();

    var parsed = siblings
        .Select(x => new { ok = decimal.TryParse(x.HTCInvoiceNo, out var n), no = decimal.TryParse(x.HTCInvoiceNo, out var n2) ? n2 : 0m, date = x.HTCInvoiceDate!.Value.Date })
        .Where(x => x.ok).ToList();

    var canDuoi = parsed.Where(x => x.no < noVal).OrderByDescending(x => x.no).FirstOrDefault();
    if (canDuoi != null && day < canDuoi.date)
        return Results.BadRequest(new { error = $"Ngày hoá đơn ({day:yyyy-MM-dd}) không được sớm hơn ngày của hoá đơn số liền dưới ({canDuoi.no}, {canDuoi.date:yyyy-MM-dd})." });

    var canTren = parsed.Where(x => x.no > noVal).OrderBy(x => x.no).FirstOrDefault();
    if (canTren != null && day > canTren.date)
        return Results.BadRequest(new { error = $"Ngày hoá đơn ({day:yyyy-MM-dd}) không được muộn hơn ngày của hoá đơn số liền trên ({canTren.no}, {canTren.date:yyyy-MM-dd})." });

    v.HTCInvoiceNo = noStr; v.InvoiceIDCode = idCode; v.HTCInvoiceDate = dto.HTCInvoiceDate;
    await db.SaveChangesAsync();
    return Results.Ok(new { v.HTCInvoiceCode, v.HTCInvoiceNo, v.InvoiceIDCode, v.HTCInvoiceDate, status = v.VatHTCStatus });
}).RequireAuthorization();

// 🔴 DUYỆT hoá đơn — CHỈ từ "P" (nguồn: myCheck_VAT_HTCInvoice với strStatusListToCheck = Stage.Pending).
app.MapPost("/api/vatinvoices/{code}/approve", async (
    string code, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    code = code.Trim().ToUpperInvariant();
    var v = await db.VatInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == code);
    if (v is null) return Results.NotFound(new { code });
    if (v.VatHTCStatus != "P") return Results.BadRequest(new { error = $"Chỉ duyệt được hoá đơn đang chờ duyệt (đang: {v.VatHTCStatus})." });
    // 🔴 #194 CASCADE DÒNG CHI TIẾT — nguồn `VAT_HTCInvoiceApproveX` (BizHTC.HDDTIntergration.cs:5562,
    //    **bản máy 150**; md5 laptop `b61052b7` ≠ 150 `2933a7fa`, bản 150 mới hơn 93 dòng ⇒ canonical).
    //    Lệnh này chạm 4 bảng ở nguồn; port cũ chỉ chạm header ⇒ dòng chi tiết đứng yên ở "P" mãi mãi.
    var whoAp = user.Identity?.Name ?? "system";
    var nowAp = DateTime.Now;
    v.VatHTCStatus = "F";
    v.ApprovedDate = nowAp; v.ApprovedBy = whoAp;
    var carsAp = await db.VatInvoiceCars.Where(c => c.OrgId == t.OrgId && c.VatInvoiceId == v.Id).ToListAsync();
    foreach (var c in carsAp)
    { c.HTCStatusDetail = "F"; c.ApprovedDate = nowAp; c.ApprovedBy = whoAp; c.LogLUDateTime = nowAp; c.LogLUBy = whoAp; }
    await db.SaveChangesAsync();
    return Results.Ok(new { v.HTCInvoiceCode, status = v.VatHTCStatus, v.ApprovedDate, v.ApprovedBy, detailRows = carsAp.Count });
}).RequireAuthorization();

// 🔴 HUỶ DUYỆT — CHỈ từ "F" (nguồn dùng CHUNG hàm với cờ FlagUnapprove; huỷ đưa về Stage.Cancel).
app.MapPost("/api/vatinvoices/{code}/unapprove", async (
    string code, string? reason, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    code = code.Trim().ToUpperInvariant();
    var v = await db.VatInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == code);
    if (v is null) return Results.NotFound(new { code });
    if (v.VatHTCStatus != "F") return Results.BadRequest(new { error = $"Chỉ huỷ được hoá đơn đã duyệt (đang: {v.VatHTCStatus})." });
    // 🔴 #194: nhánh `!bApprove` của nguồn đặt dòng chi tiết = "C" và **CHỈ ghi LogLU\***,
    //    KHÔNG ghi `ApprovedDate`/`ApprovedBy` trên dòng — khác hẳn nhánh duyệt. Giữ đúng sự khác biệt đó.
    var whoUn = user.Identity?.Name ?? "system";
    var nowUn = DateTime.Now;
    v.VatHTCStatus = "C";
    if (!string.IsNullOrWhiteSpace(reason)) v.DeleteReason = reason!.Trim();
    v.ApprovedDate = nowUn; v.ApprovedBy = whoUn;
    var carsUn = await db.VatInvoiceCars.Where(c => c.OrgId == t.OrgId && c.VatInvoiceId == v.Id).ToListAsync();
    foreach (var c in carsUn) { c.HTCStatusDetail = "C"; c.LogLUDateTime = nowUn; c.LogLUBy = whoUn; }
    await db.SaveChangesAsync();
    return Results.Ok(new { v.HTCInvoiceCode, status = v.VatHTCStatus, v.DeleteReason, detailRows = carsUn.Count });
}).RequireAuthorization();

// TỪ CHỐI hoá đơn chờ duyệt — nguồn có mã "R" (SQL lọc `not in ('R','C')`).
// ⚠️ #194: `VAT_HTCInvoiceApproveX` CHỈ có hai nhánh `bApprove` (F) và `!bApprove` (C) — **không có nhánh R**.
//    Vì vậy KHÔNG cascade dòng chi tiết ở đây (không bịa hành vi nguồn không có); ghi nợ: cần tìm lệnh nào
//    thực sự đặt "R" rồi đối chiếu riêng.
app.MapPost("/api/vatinvoices/{code}/reject", async (
    string code, string? reason, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    code = code.Trim().ToUpperInvariant();
    var v = await db.VatInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == code);
    if (v is null) return Results.NotFound(new { code });
    if (v.VatHTCStatus != "P") return Results.BadRequest(new { error = $"Chỉ từ chối được hoá đơn đang chờ duyệt (đang: {v.VatHTCStatus})." });
    if (string.IsNullOrWhiteSpace(reason)) return Results.BadRequest(new { error = "Từ chối phải ghi lý do." });
    v.VatHTCStatus = "R"; v.DeleteReason = reason!.Trim();
    v.ApprovedDate = DateTime.Now; v.ApprovedBy = user.Identity?.Name ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { v.HTCInvoiceCode, status = v.VatHTCStatus, v.DeleteReason });
}).RequireAuthorization();

// Xóa/điều chỉnh HĐ đã phát hành: Issued -> Deleted (bắt buộc lý do).
app.MapPost("/api/vatinvoices/{code}/delete", async (string code, string? reason, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var v = await db.VatInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.HTCInvoiceCode == code);
    if (v is null) return Results.NotFound(new { code });
    if (v.VatHTCStatus != "F") return Results.BadRequest(new { error = "Chỉ xóa được hóa đơn đã duyệt/phát hành." });
    if (string.IsNullOrWhiteSpace(reason)) return Results.BadRequest(new { error = "Chưa nhập lý do xóa hóa đơn." });
    v.VatHTCStatus = "C"; v.DeleteReason = reason!.Trim();   // nguồn dùng Stage.Cancel
    await db.SaveChangesAsync();
    return Results.Ok(new { v.HTCInvoiceCode, status = v.VatHTCStatus, v.DeleteReason });
}).RequireAuthorization();

// ===== Công văn gia hạn bảo lãnh (GrtClaimExt — port 1:1 FrmMngGrtClaimPM, cụm Bank) =====
app.MapGet("/api/grtclaimexts", async (AppDbContext db, ITenantContext t, string? dealer, string? no, string? sign) =>
{
    var q = db.GrtClaimExts.Where(g => g.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(g => g.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(no)) q = q.Where(g => g.GrtClaimExtNo.Contains(no!));
    if (!string.IsNullOrWhiteSpace(sign)) q = q.Where(g => g.SignStatus == sign);
    var items = await q.OrderByDescending(g => g.Id).Take(500).Select(g => new
    {
        g.GrtClaimExtNo, g.DealerCode, g.NumberOfGuaranteeExt, g.TotalCarNoStart, g.SignStatus, g.FileName, g.SignDateTime, g.SignBy, g.CreatedAt, g.CreatedBy,
        g.Remark, g.CancelDateTime, g.CancelBy, g.LUDateTime, g.LUBy,   // #191 §12: cột mới phải chiếu ở CẢ GET
        cars = db.GrtClaimExtCars.Count(c => c.OrgId == t.OrgId && c.GrtClaimExtId == g.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/grtclaimexts", async (GrtClaimExtDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có xe gia hạn bảo lãnh." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "CVGH" + DateTime.Now.ToString("yyMMddHHmmss");
    var g2 = new GrtClaimExt { OrgId = t.OrgId, GrtClaimExtNo = no, DealerCode = dto.DealerCode.Trim(), NumberOfGuaranteeExt = dto.NumberOfGuaranteeExt <= 0 ? 1 : dto.NumberOfGuaranteeExt, TotalCarNoStart = cars.Count, SignStatus = "P" };
    // #191 parity: nguồn `_SaveX_New20200522` ghi kèm CreatedBy/Remark/LU*/LogLU* ngay khi tạo.
    var whoNew = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var nowNew = DateTime.Now;
    g2.CreatedBy = whoNew; g2.Remark = (dto.Remark ?? "").Trim();
    g2.LUDateTime = nowNew; g2.LUBy = whoNew; g2.LogLUDateTime = nowNew; g2.LogLUBy = whoNew;
    db.GrtClaimExts.Add(g2); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.GrtClaimExtCars.Add(new GrtClaimExtCar { OrgId = t.OrgId, GrtClaimExtId = g2.Id, CarId = c.CarId ?? "", VIN = c.VIN.Trim().ToUpperInvariant(), GuaranteeNo = c.GuaranteeNo ?? "", SignStatusDtl = "P" });
    await db.SaveChangesAsync();
    return Results.Ok(new { g2.GrtClaimExtNo, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/grtclaimexts/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.GrtClaimExts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimExtNo == no);
    if (g is null) return Results.NotFound(new { no });
    var cars = await db.GrtClaimExtCars.Where(c => c.OrgId == t.OrgId && c.GrtClaimExtId == g.Id)
        .Select(c => new { c.CarId, c.VIN, c.GuaranteeNo, c.SignStatusDtl, c.LogLUDateTime, c.LogLUBy }).ToListAsync();
    return Results.Ok(new { g.GrtClaimExtNo, g.DealerCode, g.SignStatus, g.FileName, g.Remark, g.CancelDateTime, g.CancelBy, count = cars.Count, cars });
}).RequireAuthorization();

// Ký công văn gia hạn (upload file đã ký). Guard idempotent theo FileName (đã ký thì không ký lại).
app.MapPost("/api/grtclaimexts/{no}/sign", async (string no, GrtClaimExtSignDto body, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.GrtClaimExts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimExtNo == no);
    if (g is null) return Results.NotFound(new { no });
    if (string.IsNullOrWhiteSpace(body.FileName)) return Results.BadRequest(new { error = "Chưa có file ký." });
    if (!string.IsNullOrWhiteSpace(g.FileName)) return Results.BadRequest(new { error = "Công văn đã được ký (đã có file), không ký lại." });
    // 🔴 #191: nguồn `_SignX`(3201) đặt `GrtClaimExtStatus = Approved ("A")` — KHÔNG phải "S";
    //    ghi kèm `SignBy`, `Remark`, `LU*`, `LogLU*`, và `GrtClaimExtStatusDtl` của CHI TIẾT theo header.
    //    (Guard trạng thái của nguồn ở đây cũng CHẾT CÂM — xem ghi chú ở `/cancel`; giữ guard idempotent
    //     theo FileName mà port cũ đã có, vì nó chặn thật.)
    var whoSign = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var nowSign = DateTime.Now;
    g.FileName = body.FileName.Trim(); g.SignDateTime = nowSign; g.SignBy = whoSign; g.SignStatus = "A";
    g.Remark = (body.Remark ?? g.Remark ?? "").Trim();
    g.LUDateTime = nowSign; g.LUBy = whoSign; g.LogLUDateTime = nowSign; g.LogLUBy = whoSign;
    var cars = await db.GrtClaimExtCars.Where(c => c.OrgId == t.OrgId && c.GrtClaimExtId == g.Id).ToListAsync();
    foreach (var c in cars) { c.SignStatusDtl = "A"; c.LogLUDateTime = nowSign; c.LogLUBy = whoSign; }
    await db.SaveChangesAsync();
    return Results.Ok(new { g.GrtClaimExtNo, signStatus = g.SignStatus, g.FileName, signedCars = cars.Count });
}).RequireAuthorization();

// ===== #191 Huỷ công văn gia hạn bảo lãnh — `Pmt_GrtClaimExt_Cancel` (LỆNH CÒN THIẾU HẲN) =====
// Nguồn: `TERP.BizHTC/Biz.HTC.PaymentGrtExt.cs` — `_CancelX`(4159) / `_Cancel`(4379);
//   họ hàng: `_SaveX_New20200522`(1297) · `_SaveX_New20201210`(2007) · `_SignX`(3201) · `_CheckDB`(25).
// BƯỚC 3B: md5 CẢ FILE `fc962972` KHỚP 2 máy — dù TÊN THƯ MỤC KHÁC NHAU
//   (laptop: `ERP.V15.DataWH.Release.20220125` · máy 150: `ERP.V15.DataWH.Release.2025`).
//
// 🔴 TWIN (loại mới): HAI đường ghi cùng bảng dùng HAI phiên bản `SaveX` KHÁC NHAU, **cả hai đều LIVE**:
//   · nhập tay  : WS64 `Pmt_GrtClaimExt_Save_New20200522` → `_SaveX_New20200522`;
//   · tự sinh   : WS64 `Pmt_GrtClaimExt_GenAuto_New20201210` → `_GenAutoX_New20201210` → `_SaveX_New20201210`.
//   ⇒ "hàm version cao hơn = hàm sống" là SAI ở đây; phải trace THEO TỪNG ĐƯỜNG.
//   Cả cụm `Pmt_GrtClaimExt_*` CHỈ có ở WS 64-bit; WS 32-bit không có lệnh nào.
//
// 🔴 GUARD CHẾT CÂM CỦA NGUỒN (giữ nguyên hành vi, chỉ ghi rõ — cùng cách xử lý ở #189):
//   `_CheckDB(..., strFlagExistToCheck, strStatusListToCheck, ...)`: tham số 1 CHỈ so với `Flag.Active`("1")
//   / `Flag.Inactive`("0"); tham số 2 mới là danh sách trạng thái. `_CancelX`(4211) truyền
//   `GrtClaimExtStatus.Approved`("A") vào **tham số 1** và để tham số 2 RỖNG ⇒ không nhánh nào khớp
//   ⇒ **không kiểm gì cả**: huỷ được ở MỌI trạng thái, và cũng KHÔNG kiểm bản ghi có tồn tại.
//   `_SignX`(3259) mắc y hệt với `Pending`("P"). Cách dùng ĐÚNG (`Flag.Yes`) nằm ở 3532 và 3922.
//   ⇒ Port giữ đúng hành vi nguồn: KHÔNG chặn theo trạng thái. (NotFound ở đây là do tra cứu bản ghi,
//     không phải guard của nguồn.)
//
// 🔴 TAXONOMY (`TConst.GrtClaimExtStatus`, Const.Main.DMS40.cs:81): `P` Pending → `A` Approved → `C` Cancel.
//   Port cũ dùng `"S"` cho ĐÃ KÝ — SAI TỪ VỰNG (không có "S" trong nguồn); đã đổi + migration `S → A`.
// Nguồn ghi khi huỷ: `GrtClaimExtStatus="C"`, `Remark`, `CancelDateTime`, `CancelBy`, `LUDateTime/LUBy`,
//   `LogLUDateTime/LogLUBy`; và **cập nhật CHI TIẾT** `Pmt_GrtClaimExtDtl.GrtClaimExtStatusDtl = "C"`
//   + `LogLUDateTime/LogLUBy` (join qua `GrtClaimExtNo`). Ghi song song `_dbMain` và `_dbWH` (nợ dual-write).
app.MapPost("/api/grtclaimexts/{no}/cancel", async (string no, GrtClaimExtCancelDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.GrtClaimExts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimExtNo == no);
    if (g is null) return Results.NotFound(new { no });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    g.SignStatus = "C";                       // cột `GrtClaimExtStatus` của nguồn
    g.Remark = (dto.Remark ?? "").Trim();     // nguồn ghi ĐÈ Remark bằng chuỗi truyền vào (kể cả rỗng)
    g.CancelDateTime = now; g.CancelBy = who;
    g.LUDateTime = now; g.LUBy = who;
    g.LogLUDateTime = now; g.LogLUBy = who;

    var cars = await db.GrtClaimExtCars.Where(c => c.OrgId == t.OrgId && c.GrtClaimExtId == g.Id).ToListAsync();
    foreach (var c in cars) { c.SignStatusDtl = "C"; c.LogLUDateTime = now; c.LogLUBy = who; }

    await db.SaveChangesAsync();
    return Results.Ok(new { g.GrtClaimExtNo, status = g.SignStatus, g.Remark, g.CancelDateTime, g.CancelBy, cancelledCars = cars.Count });
}).RequireAuthorization();

// Xóa công văn gia hạn (port 1:1 FrmQLCVanGiaHan_PhatHanhBL btnDelete_Click) — chỉ khi SignStatus=P (chưa ký).
app.MapDelete("/api/grtclaimexts/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.GrtClaimExts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GrtClaimExtNo == no);
    if (g is null) return Results.NotFound(new { no });
    if (g.SignStatus != "P") return Results.BadRequest(new { error = "Trạng thái công văn không hợp lệ!" });
    db.GrtClaimExtCars.RemoveRange(db.GrtClaimExtCars.Where(c => c.OrgId == t.OrgId && c.GrtClaimExtId == g.Id));
    db.GrtClaimExts.Remove(g);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = no });
}).RequireAuthorization();

