// Patch 1 field GD (audit old->new). field = dealDate|plateNo|salesType|warrantyNo|customerCode|verifyStatus.
app.MapPost("/api/deals/records/{dealNo}/patch", async (string dealNo, DealPatchDto dto, AppDbContext db, ITenantContext t) =>
{
    dealNo = dealNo.Trim();
    var r = await db.DealRecords.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == dealNo);
    if (r is null) return Results.NotFound(new { dealNo });
    var field = (dto.Field ?? "").Trim();
    if (field is not ("dealDate" or "plateNo" or "salesType" or "warrantyNo" or "customerCode" or "verifyStatus")) return Results.BadRequest(new { error = "Field không hợp lệ (dealDate|plateNo|salesType|warrantyNo|customerCode|verifyStatus)." });
    if (string.IsNullOrWhiteSpace(dto.Value)) return Results.BadRequest(new { error = "Chưa nhập giá trị mới." });
    string oldVal;
    switch (field)
    {
        case "dealDate":
            if (!DateTime.TryParse(dto.Value, out var newDate)) return Results.BadRequest(new { error = "Ngày giao dịch không hợp lệ." });
            oldVal = r.DealDate?.ToString("yyyy-MM-dd") ?? ""; r.DealDate = newDate; break;
        case "plateNo": oldVal = r.PlateNo; r.PlateNo = dto.Value.Trim(); break;
        case "salesType": oldVal = r.SalesType; r.SalesType = dto.Value.Trim(); break;
        case "warrantyNo": oldVal = r.WarrantyNo; r.WarrantyNo = dto.Value.Trim(); break;
        case "customerCode": oldVal = r.CustomerCode; r.CustomerCode = dto.Value.Trim(); break;
        default: oldVal = r.VerifyStatus; r.VerifyStatus = dto.Value.Trim(); break;
    }
    r.UpdatedAt = DateTime.Now;
    db.DealPatchLogs.Add(new DealPatchLog { OrgId = t.OrgId, DealRecordId = r.Id, DealNo = dealNo, Field = field, OldValue = oldVal, NewValue = dto.Value.Trim() });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.DealNo, field, oldValue = oldVal, newValue = dto.Value.Trim() });
}).RequireAuthorization();

app.MapGet("/api/deals/records/{dealNo}/history", async (string dealNo, AppDbContext db, ITenantContext t) =>
{
    dealNo = dealNo.Trim();
    var logs = await db.DealPatchLogs.Where(l => l.OrgId == t.OrgId && l.DealNo == dealNo)
        .OrderByDescending(l => l.Id).Take(200).Select(l => new { l.Field, l.OldValue, l.NewValue, l.PatchedAt }).ToListAsync();
    return Results.Ok(new { dealNo, count = logs.Count, logs });
}).RequireAuthorization();

// ===== HOÁ ĐƠN TCG (VAT_TCGInvoice + Detail) =====
// 🔴 TWIN đã trace kỹ (bảng này được ghi ở BỐN file khác nhau — không chọn theo file, phải theo WS):
//    WS 32-bit (WSHTC.cs:34444) gọi `..._New20181119`, WS 64-bit (WSHTC.64:46231) gọi
//    `VAT_TCGInvoiceCreate_New20201210` ở FILE KHÁC: HDDTIntergration/BizHTC.HDDTIntergration.cs:20115
//    → `VAT_TCGInvoiceCreateX_20201210` (14549). Canonical = bản 64-bit/2020 (mới hơn 2 năm).
// 🔴 `VatTCGStatus` KHÔNG dùng "A"/"R": tạo = "P", **duyệt = "F"** (Stage.Finished),
//    **không duyệt = "C"** (Stage.Cancel) — `VAT_TCGInvoiceApproveX` (19061, dòng +132).
// 🔴 Số hoá đơn (`TCGInvoiceNo`/`TCGInvoiceDate`) và mã HĐĐT (`OS_HDDT_*`) nguồn để **NULL lúc tạo**,
//    chỉ điền về sau — port giữ đúng, không sinh số ngay khi tạo.
// ⚠️ Nguồn ghi song song `_dbMain` + `_dbWH` — nợ `_dbWH` chung fleet.
app.MapGet("/api/tcginvoices", async (AppDbContext db, ITenantContext t, string? code, string? status, string? refNo) =>
{
    var qy = db.VatTcgInvoices.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(code)) qy = qy.Where(x => x.TCGInvoiceCode == code);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.VatTCGStatus == status);
    if (!string.IsNullOrWhiteSpace(refNo)) qy = qy.Where(x => x.RefNo == refNo);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.TCGInvoiceCode, x.SourceInvoiceCode, x.InvoiceAdjType, x.InvoiceIDType, x.RefNo,
        x.VatTCGStatus, x.TCGInvoiceNo, x.TCGInvoiceDate, x.OS_HDDT_InvoiceCode, x.OS_HDDT_RefNo,
        x.VAT, x.FlagView, x.TInvoiceCode, x.FlagImport,
        x.CreatedDate, x.CreatedBy, x.ApprovedDate, x.ApprovedBy, x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    var codes = items.Select(i => i.TCGInvoiceCode).ToList();
    var dtls = await db.VatTcgInvoiceDetails.Where(d => d.OrgId == t.OrgId && codes.Contains(d.TCGInvoiceCode))
        .Select(d => new
        {
            d.TCGInvoiceCode, d.VIN, d.TCGUnitPrice, d.TCGVAT, d.TInvoicePrice,
            d.BrandName, d.CarType, d.CustomsClearanceDate,
            d.InvoiceNoFactory, d.InvoiceFactorySearch, d.ProductionMonth,
            d.TCGStatusDetail, d.LogLUDateTime, d.LogLUBy,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, details = dtls });
}).RequireAuthorization();

app.MapPost("/api/tcginvoices/create", async (TcgInvoiceCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.TCGInvoiceCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã hoá đơn TCG rỗng." });
    if (await db.VatTcgInvoices.AnyAsync(x => x.OrgId == t.OrgId && x.TCGInvoiceCode == code))
        return Results.BadRequest(new { error = $"Hoá đơn {code} đã tồn tại." });
    var rows = (dto.Details ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng chi tiết rỗng." });
    var seen = new HashSet<string>();
    foreach (var r in rows)
        if (!seen.Add(r.VIN!.Trim().ToUpperInvariant()))
            return Results.BadRequest(new { error = $"VIN {r.VIN} bị lặp trong hoá đơn." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    db.VatTcgInvoices.Add(new VatTcgInvoice
    {
        OrgId = t.OrgId, TCGInvoiceCode = code,
        SourceInvoiceCode = dto.SourceInvoiceCode, InvoiceAdjType = dto.InvoiceAdjType,
        InvoiceIDType = dto.InvoiceIDType, RefNo = dto.RefNo,
        VatTCGStatus = "P",
        // 🔴 Nguồn để NULL lúc tạo — số hoá đơn và mã HĐĐT chỉ có về sau.
        TCGInvoiceNo = null, TCGInvoiceDate = null,
        OS_HDDT_InvoiceCode = null, OS_HDDT_RefNo = null,
        VAT = dto.VAT, FlagView = dto.FlagView, TInvoiceCode = dto.TInvoiceCode, FlagImport = dto.FlagImport,
        CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who,
    });
    foreach (var r in rows)
        db.VatTcgInvoiceDetails.Add(new VatTcgInvoiceDetail
        {
            OrgId = t.OrgId, TCGInvoiceCode = code, VIN = r.VIN!.Trim().ToUpperInvariant(),
            TCGUnitPrice = r.TCGUnitPrice, TCGVAT = r.TCGVAT,
            TInvoicePrice = 0m, // 🔴 nguồn LUÔN ghi 0 khi tạo, không lấy từ đầu vào
            BrandName = r.BrandName, CarType = r.CarType,
            CustomsClearanceDate = r.CustomsClearanceDate,
            InvoiceNoFactory = r.InvoiceNoFactory, InvoiceFactorySearch = r.InvoiceFactorySearch,
            ProductionMonth = r.ProductionMonth,
            TCGStatusDetail = "P", LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { code, details = rows.Count, status = "P" });
}).RequireAuthorization();

// 🔴 Duyệt → "F" (Finished), từ chối → "C" (Cancel). Nguồn dùng CHUNG một hàm, cờ `bApprove` quyết định.
app.MapPost("/api/tcginvoices/approve", async (TcgInvoiceApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.TCGInvoiceCode ?? "").Trim();
    var row = await db.VatTcgInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TCGInvoiceCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có hoá đơn {code}." });
    if (row.VatTCGStatus != "P")
        return Results.BadRequest(new { error = $"Hoá đơn đang '{row.VatTCGStatus}', chỉ duyệt được khi 'P'." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var approve = dto.Approve != false;
    row.VatTCGStatus = approve ? "F" : "C";
    row.ApprovedDate = now; row.ApprovedBy = who;
    row.LogLUDateTime = now; row.LogLUBy = who;
    // Số hoá đơn chỉ được điền khi DUYỆT (nguồn sinh qua Seq_PrintVAT — xem /api/seqcommon/get TCGIV).
    if (approve && !string.IsNullOrWhiteSpace(dto.TCGInvoiceNo))
    {
        row.TCGInvoiceNo = dto.TCGInvoiceNo!.Trim();
        row.TCGInvoiceDate = dto.TCGInvoiceDate ?? now;
    }
    var dtls = await db.VatTcgInvoiceDetails.Where(d => d.OrgId == t.OrgId && d.TCGInvoiceCode == code).ToListAsync();
    foreach (var d in dtls) { d.TCGStatusDetail = row.VatTCGStatus; d.LogLUDateTime = now; d.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { code, status = row.VatTCGStatus, row.TCGInvoiceNo, detailsSynced = dtls.Count });
}).RequireAuthorization();

// Xoá cả hoá đơn (nguồn `VAT_TCGInvoiceDelete`) — chỉ khi còn "P".
app.MapPost("/api/tcginvoices/delete", async (TcgInvoiceKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.TCGInvoiceCode ?? "").Trim();
    var row = await db.VatTcgInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TCGInvoiceCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có hoá đơn {code}." });
    if (row.VatTCGStatus != "P")
        return Results.BadRequest(new { error = $"Hoá đơn đang '{row.VatTCGStatus}', chỉ xoá được khi 'P'." });
    var dtls = await db.VatTcgInvoiceDetails.Where(d => d.OrgId == t.OrgId && d.TCGInvoiceCode == code).ToListAsync();
    db.VatTcgInvoiceDetails.RemoveRange(dtls);
    db.VatTcgInvoices.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = code, detailsDeleted = dtls.Count });
}).RequireAuthorization();

// Xoá MỘT dòng xe khỏi hoá đơn (nguồn `VAT_TCGInvoiceDetailDelete`).
app.MapPost("/api/tcginvoices/detail-delete", async (TcgInvoiceDetailKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.TCGInvoiceCode ?? "").Trim();
    var vin = (dto.VIN ?? "").Trim().ToUpperInvariant();
    var head = await db.VatTcgInvoices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TCGInvoiceCode == code);
    if (head is null) return Results.NotFound(new { error = $"Không có hoá đơn {code}." });
    if (head.VatTCGStatus != "P")
        return Results.BadRequest(new { error = $"Hoá đơn đang '{head.VatTCGStatus}', chỉ sửa được khi 'P'." });
    var row = await db.VatTcgInvoiceDetails.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.TCGInvoiceCode == code && d.VIN == vin);
    if (row is null) return Results.NotFound(new { error = $"Hoá đơn {code} không có VIN {vin}." });
    db.VatTcgInvoiceDetails.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = $"{code}/{vin}" });
}).RequireAuthorization();

// ===== Hợp đồng ngoại (CT_ContractOversea) · L/C (CT_LC) · Proforma Invoice
// (Ord_PerformanceInvoice + Detail) — port 1:1 `ContractContractOverseaCreate`(32211)/`Delete`(32497),
// `ContractLCCreate`(33077)/`Delete`(33273), 2010.HTC Biz.HTC.WH.cs.
// TWIN: cả WS 32-bit lẫn 64-bit CÙNG bản `_New20181119`. =====
// 🔴 Bảng hợp đồng ngoại chỉ có 3 cột nghiệp vụ — nội dung thật nằm ở `Ord_PerformanceInvoiceDetail`.
//    MỘT lệnh Create ghi CẢ HAI bảng và **gán `ContractNo` xuống từng dòng PI** (dòng 32485-32486)
//    ⇒ dòng PI chưa gắn hợp đồng thì `ContractNo` rỗng; đó là cách phân biệt PI đã/chưa vào hợp đồng.
// ⚠️ Tên bảng nguồn là "Performance" nhưng nghiệp vụ là **Proforma** Invoice — giữ nguyên tên nguồn.
// ⚠️ Nguồn ghi song song `_dbMain` + `_dbWH` — nợ `_dbWH` chung fleet; RBAC `CheckHTCDirect` chưa port.
app.MapGet("/api/contractoverseas", async (AppDbContext db, ITenantContext t, string? contractNo) =>
{
    var qy = db.CtContractOverseas.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(contractNo)) qy = qy.Where(x => x.ContractNo == contractNo);
    var items = await qy.OrderByDescending(x => x.Id).Take(500)
        .Select(x => new { x.ContractNo, x.CreatedDate, x.CreatedBy }).ToListAsync();
    var nos = items.Select(i => i.ContractNo).ToList();
    var lines = await db.OrdPerformanceInvoiceDetails
        .Where(d => d.OrgId == t.OrgId && d.ContractNo != null && nos.Contains(d.ContractNo))
        .Select(d => new
        {
            d.ContractNo, d.RefNo, d.LCTemp, d.SpecCode, d.ModelCode, d.ColorCode,
            d.WorkOrderNo, d.PortCode, d.PlantCode, d.Quantity,
        }).ToListAsync();
    var lcs = await db.CtLcs.Where(x => x.OrgId == t.OrgId && nos.Contains(x.ContractNo))
        .Select(x => new { x.LCNo, x.ContractNo, x.BankName, x.CreatedDate, x.CreatedBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, piLines = lines, lcs });
}).RequireAuthorization();

// 🔴 Ký hợp đồng ngoại: tạo bản ghi hợp đồng VÀ gán ContractNo xuống các dòng PI được chọn.
app.MapPost("/api/contractoverseas/create", async (CtContractOverseaCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.ContractNo ?? "").Trim();
    // Guard nguồn: MinLengthCode = 5 (TConst.HTCConst, Const.Main.cs:322).
    if (no.Length < 5) return Results.BadRequest(new { error = "Số hợp đồng ngắn hơn MinLengthCode (5)." });
    if (await db.CtContractOverseas.AnyAsync(x => x.OrgId == t.OrgId && x.ContractNo == no))
        return Results.BadRequest(new { error = $"Hợp đồng {no} đã tồn tại." });
    var refs = (dto.PiRefNos ?? new()).Select(r => (r ?? "").Trim()).Where(r => r.Length > 0).Distinct().ToList();
    // Guard nguồn: bảng chi tiết đầu vào KHÔNG được rỗng.
    if (refs.Count == 0) return Results.BadRequest(new { error = "Bảng dòng Proforma Invoice rỗng." });

    var lines = await db.OrdPerformanceInvoiceDetails
        .Where(d => d.OrgId == t.OrgId && refs.Contains(d.RefNo)).ToListAsync();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không tìm thấy dòng PI nào theo danh sách gửi lên." });
    // Dòng đã thuộc hợp đồng khác thì không gán lại — giữ ngữ nghĩa "ContractNo rỗng = chưa vào hợp đồng".
    var taken = lines.Where(d => !string.IsNullOrWhiteSpace(d.ContractNo) && d.ContractNo != no)
                     .Select(d => $"{d.RefNo}→{d.ContractNo}").Distinct().ToList();
    if (taken.Count > 0)
        return Results.BadRequest(new { error = $"Có dòng PI đã thuộc hợp đồng khác: {string.Join(", ", taken.Take(10))}." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.CtContractOverseas.Add(new CtContractOversea
    {
        OrgId = t.OrgId, ContractNo = no, CreatedDate = DateTime.Now, CreatedBy = who,
    });
    foreach (var d in lines) d.ContractNo = no; // 🔴 nguồn gán xuống từng dòng PI
    await db.SaveChangesAsync();
    return Results.Ok(new { contractNo = no, piLinesLinked = lines.Count });
}).RequireAuthorization();

// Xoá hợp đồng ngoại — gỡ luôn ContractNo khỏi các dòng PI để chúng trở lại trạng thái "chưa vào hợp đồng".
app.MapPost("/api/contractoverseas/delete", async (CtContractOverseaKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var no = (dto.ContractNo ?? "").Trim();
    var row = await db.CtContractOverseas.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ContractNo == no);
    if (row is null) return Results.NotFound(new { error = $"Không có hợp đồng {no}." });
    if (await db.CtLcs.AnyAsync(x => x.OrgId == t.OrgId && x.ContractNo == no))
        return Results.BadRequest(new { error = $"Hợp đồng {no} đã có L/C, không xoá được." });
    var lines = await db.OrdPerformanceInvoiceDetails.Where(d => d.OrgId == t.OrgId && d.ContractNo == no).ToListAsync();
    foreach (var d in lines) d.ContractNo = null;
    db.CtContractOverseas.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = no, piLinesUnlinked = lines.Count });
}).RequireAuthorization();

// ⚠️ Route là `/api/ctlcs`, KHÔNG phải `/api/lcs`: `/api/lcs` đã thuộc L/C của DMSales.Foton
//    (entity `LettersOfCredit`, ~dòng 21400) — BẢNG KHÁC HẲN với `CT_LC` của 2010.HTC, không được gộp.
app.MapGet("/api/ctlcs", async (AppDbContext db, ITenantContext t, string? lcNo, string? contractNo) =>
{
    var qy = db.CtLcs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(lcNo)) qy = qy.Where(x => x.LCNo == lcNo);
    if (!string.IsNullOrWhiteSpace(contractNo)) qy = qy.Where(x => x.ContractNo == contractNo);
    var items = await qy.OrderByDescending(x => x.Id)
        .Select(x => new { x.LCNo, x.ContractNo, x.BankName, x.CreatedDate, x.CreatedBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/ctlcs/create", async (CtLcCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var lcNo = (dto.LCNo ?? "").Trim();
    var no = (dto.ContractNo ?? "").Trim();
    if (lcNo.Length < 1) return Results.BadRequest(new { error = "Số L/C rỗng." });
    if (await db.CtLcs.AnyAsync(x => x.OrgId == t.OrgId && x.LCNo == lcNo))
        return Results.BadRequest(new { error = $"L/C {lcNo} đã tồn tại." });
    if (!await db.CtContractOverseas.AnyAsync(x => x.OrgId == t.OrgId && x.ContractNo == no))
        return Results.BadRequest(new { error = $"Hợp đồng ngoại {no} không tồn tại." });
    db.CtLcs.Add(new CtLc
    {
        OrgId = t.OrgId, LCNo = lcNo, ContractNo = no, BankName = dto.BankName,
        CreatedDate = DateTime.Now,
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { lcNo, contractNo = no });
}).RequireAuthorization();

// Nguồn `ContractLCDelete` là XOÁ THẬT (`Rows[0].Delete()`).
app.MapPost("/api/ctlcs/delete", async (CtLcKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var lcNo = (dto.LCNo ?? "").Trim();
    var row = await db.CtLcs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.LCNo == lcNo);
    if (row is null) return Results.NotFound(new { error = $"Không có L/C {lcNo}." });
    db.CtLcs.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = lcNo });
}).RequireAuthorization();

// Proforma Invoice — phần đầu + dòng. `ContractNo` của dòng do lệnh ký hợp đồng ngoại gán, KHÔNG nhận ở đây.
app.MapGet("/api/performanceinvoices", async (AppDbContext db, ITenantContext t, string? refNo, string? modelCode, bool? unlinkedOnly) =>
{
    var qy = db.OrdPerformanceInvoices.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(refNo)) qy = qy.Where(x => x.RefNo == refNo);
    if (!string.IsNullOrWhiteSpace(modelCode)) qy = qy.Where(x => x.ModelCode == modelCode);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.RefNo, x.ModelCode, x.OrderMonth, x.ProductionMonth, x.ExpectedMonth,
        x.FlagAutoPL, x.CreatedDate, x.CreatedBy,
    }).ToListAsync();
    var refs = items.Select(i => i.RefNo).ToList();
    var dq = db.OrdPerformanceInvoiceDetails.Where(d => d.OrgId == t.OrgId && refs.Contains(d.RefNo));
    // Tiện dụng: chỉ lấy dòng CHƯA vào hợp đồng nào.
    if (unlinkedOnly == true) dq = dq.Where(d => d.ContractNo == null || d.ContractNo == "");
    var details = await dq.Select(d => new
    {
        d.RefNo, d.LCTemp, d.SpecCode, d.ModelCode, d.ColorCode,
        d.WorkOrderNo, d.PortCode, d.PlantCode, d.Quantity, d.ContractNo,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, details });
}).RequireAuthorization();

app.MapPost("/api/performanceinvoices/create", async (OrdPiCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var refNo = (dto.RefNo ?? "").Trim();
    if (refNo.Length < 1) return Results.BadRequest(new { error = "Số PI rỗng." });
    if (await db.OrdPerformanceInvoices.AnyAsync(x => x.OrgId == t.OrgId && x.RefNo == refNo))
        return Results.BadRequest(new { error = $"PI {refNo} đã tồn tại." });
    var rows = dto.Details ?? new();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng dòng PI rỗng." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.OrdPerformanceInvoices.Add(new OrdPerformanceInvoice
    {
        OrgId = t.OrgId, RefNo = refNo, ModelCode = dto.ModelCode,
        OrderMonth = dto.OrderMonth, ProductionMonth = dto.ProductionMonth, ExpectedMonth = dto.ExpectedMonth,
        FlagAutoPL = dto.FlagAutoPL, CreatedDate = DateTime.Now, CreatedBy = who,
    });
    foreach (var r in rows)
        db.OrdPerformanceInvoiceDetails.Add(new OrdPerformanceInvoiceDetail
        {
            OrgId = t.OrgId, RefNo = refNo, LCTemp = r.LCTemp,
            SpecCode = r.SpecCode, ModelCode = r.ModelCode, ColorCode = r.ColorCode,
            WorkOrderNo = r.WorkOrderNo, PortCode = r.PortCode, PlantCode = r.PlantCode,
            Quantity = r.Quantity,
            ContractNo = null, // 🔴 chỉ lệnh ký hợp đồng ngoại mới gán cột này
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { refNo, details = rows.Count });
}).RequireAuthorization();

// ===== Danh mục MÀN HÌNH / CHỨC NĂNG (Sys_Object) — mảnh cuối của bộ RBAC =====
// Cột theo `mySql_GetClauseColumnForSysObjectInfo` (2010.HTC BizHTC.Common.cs:1547).
// 🔴 Bảng này KHÔNG có hàm ghi trong biz nguồn (danh mục tĩnh do DBA nạp) — MiniHTC vẫn mở endpoint
//    ghi để nạp danh mục, đây là điểm KHÁC nguồn và đã ghi rõ trong comment entity.
// 🔴 `ObjectType` (TConst.SysObjectType, Const.Main.cs:166): WS · WSFUNC · APP · MENU · SCR · BTN
//    ⇒ phân quyền xuống tới TỪNG NÚT, không chỉ từng màn hình. (`BIZFUNC` bị comment trong nguồn.)
// 🔴 `ObjectCodeParent` tạo cây APP → MENU → SCR → BTN.
string[] SysObjectTypes = { "WS", "WSFUNC", "APP", "MENU", "SCR", "BTN" };

app.MapGet("/api/sysobjects", async (AppDbContext db, ITenantContext t, string? objectCode, string? objectType, string? parent, string? flagActive) =>
{
    var qy = db.SysObjects.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(objectCode)) qy = qy.Where(x => x.ObjectCode == objectCode);
    if (!string.IsNullOrWhiteSpace(objectType)) qy = qy.Where(x => x.ObjectType == objectType);
    if (!string.IsNullOrWhiteSpace(parent)) qy = qy.Where(x => x.ObjectCodeParent == parent);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
    var items = await qy.OrderBy(x => x.ObjectType).ThenBy(x => x.ObjectCode).Select(x => new
    {
        x.ObjectCode, x.ObjectType, x.ObjectName, x.ObjectCodeParent, x.ObjectCodeExec,
        x.PhysicalAssembly, x.PhysicalClass, x.FlagExecModal, x.PartnerCode, x.FlagActive,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/sysobjects/save", async (SysObjectSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.ObjectCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã đối tượng rỗng." });
    var type = (dto.ObjectType ?? "").Trim().ToUpperInvariant();
    if (type.Length > 0 && !SysObjectTypes.Contains(type))
        return Results.BadRequest(new { error = $"Loại đối tượng không hợp lệ. Cho phép: {string.Join(", ", SysObjectTypes)}." });
    var parent = (dto.ObjectCodeParent ?? "").Trim();
    // Cây phân cấp: khai báo cha thì cha phải có thật (nguồn dựng cây qua ObjectCodeParent).
    if (parent.Length > 0 && parent != code
        && !await db.SysObjects.AnyAsync(x => x.OrgId == t.OrgId && x.ObjectCode == parent))
        return Results.BadRequest(new { error = $"Đối tượng cha {parent} không tồn tại." });
    if (parent == code) return Results.BadRequest(new { error = "Đối tượng không thể là cha của chính nó." });

    var row = await db.SysObjects.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ObjectCode == code);
    var isNew = row is null;
    if (isNew) { row = new SysObject { OrgId = t.OrgId, ObjectCode = code }; db.SysObjects.Add(row); }
    row!.ObjectType = type.Length > 0 ? type : row.ObjectType;
    row.ObjectName = dto.ObjectName;
    row.ObjectCodeParent = parent.Length > 0 ? parent : null;
    row.ObjectCodeExec = dto.ObjectCodeExec;
    row.PhysicalAssembly = dto.PhysicalAssembly;
    row.PhysicalClass = dto.PhysicalClass;
    row.FlagExecModal = dto.FlagExecModal;
    row.PartnerCode = dto.PartnerCode;
    row.FlagActive = string.IsNullOrWhiteSpace(dto.FlagActive) ? "1" : dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.ObjectCode, created = isNew });
}).RequireAuthorization();

// ===== Map PHÂN QUYỀN: nhóm↔người dùng (Map_SG_SU) và nhóm↔màn hình (Map_SG_SO) =====
// Port 1:1 `SysSaveMapSysGroupSysUser_New20181119` (Biz.HTC.WH.cs:16421) và
// `SysSaveMapSysGroupSysObject_New20181119` (16587). TWIN: cả WS 32-bit lẫn 64-bit CÙNG bản.
// 🔴 Cả hai lưu theo kiểu **XOÁ TRẮNG THEO NHÓM rồi CHÈN LẠI**: bảng gửi lên phải là TOÀN BỘ
//    thành viên / quyền của nhóm đó. Gửi thiếu = MẤT quyền của phần không gửi. Đây là ngữ nghĩa
//    "thay thế trọn bộ", không phải "thêm dần" — port giữ nguyên và ghi rõ trong phản hồi API.
// 🔴 Nguồn ép `PartnerCode = "DESKTOPAPPHTC"` (TConst.Sys_Partner.Desktop) cho mọi dòng ghi vào.
// ⚠️ C0-bug10: nhánh Map_SG_SO của nguồn dựng WHERE bằng NỐI CHUỖI (SQL injection) trong khi nhánh
//    Map_SG_SU dùng `BuildClauseConditionList` an toàn. MiniHTC tham số hoá qua EF, không nhân bản.
string SysPartnerDesktop = "DESKTOPAPPHTC"; // TConst.Sys_Partner.Desktop

app.MapGet("/api/sysgroupusers", async (AppDbContext db, ITenantContext t, string? groupCode, string? userCode) =>
{
    var qy = db.MapSysGroupSysUsers.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(groupCode)) qy = qy.Where(x => x.GroupCode == groupCode);
    if (!string.IsNullOrWhiteSpace(userCode)) qy = qy.Where(x => x.UserCode == userCode);
    var items = await qy.OrderBy(x => x.GroupCode).ThenBy(x => x.UserCode)
        .Select(x => new { x.GroupCode, x.UserCode, x.PartnerCode }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// 🔴 THAY THẾ TRỌN BỘ thành viên của (các) nhóm nêu trong `GroupCodes`.
app.MapPost("/api/sysgroupusers/save", async (MapSgSuSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    var groups = (dto.GroupCodes ?? new()).Select(g => (g ?? "").Trim()).Where(g => g.Length > 0).Distinct().ToList();
    if (groups.Count == 0) return Results.BadRequest(new { error = "Chưa chỉ định nhóm cần lưu." });
    var rows = (dto.Rows ?? new())
        .Where(r => !string.IsNullOrWhiteSpace(r.GroupCode) && !string.IsNullOrWhiteSpace(r.UserCode)).ToList();
    // Mọi dòng gửi lên phải thuộc đúng các nhóm đang lưu — tránh ghi lén sang nhóm khác.
    var stray = rows.Select(r => r.GroupCode!.Trim()).Where(g => !groups.Contains(g)).Distinct().ToList();
    if (stray.Count > 0)
        return Results.BadRequest(new { error = $"Có dòng thuộc nhóm ngoài danh sách lưu: {string.Join(", ", stray)}." });

    var old = await db.MapSysGroupSysUsers.Where(x => x.OrgId == t.OrgId && groups.Contains(x.GroupCode)).ToListAsync();
    db.MapSysGroupSysUsers.RemoveRange(old);
    var seen = new HashSet<string>();
    var added = 0;
    foreach (var r in rows)
    {
        var key = $"{r.GroupCode!.Trim()}|{r.UserCode!.Trim()}";
        if (!seen.Add(key)) continue; // bỏ trùng trong chính bảng đầu vào
        db.MapSysGroupSysUsers.Add(new MapSysGroupSysUser
        {
            OrgId = t.OrgId, GroupCode = r.GroupCode!.Trim(), UserCode = r.UserCode!.Trim(),
            PartnerCode = SysPartnerDesktop, // nguồn ép giá trị này, không lấy từ đầu vào
        });
        added++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { groups, removed = old.Count, added, note = "Thay thế trọn bộ thành viên của các nhóm nêu trên." });
}).RequireAuthorization();

app.MapGet("/api/sysgroupobjects", async (AppDbContext db, ITenantContext t, string? groupCode, string? objectCode) =>
{
    var qy = db.MapSysGroupSysObjects.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(groupCode)) qy = qy.Where(x => x.GroupCode == groupCode);
    if (!string.IsNullOrWhiteSpace(objectCode)) qy = qy.Where(x => x.ObjectCode == objectCode);
    var items = await qy.OrderBy(x => x.GroupCode).ThenBy(x => x.ObjectCode)
        .Select(x => new { x.GroupCode, x.ObjectCode, x.PartnerCode }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// 🔴 THAY THẾ TRỌN BỘ quyền màn hình của MỘT nhóm (nguồn nhận đúng một `strGroupCodeList` cho nhánh này).
app.MapPost("/api/sysgroupobjects/save", async (MapSgSoSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    var group = (dto.GroupCode ?? "").Trim();
    if (group.Length < 1) return Results.BadRequest(new { error = "Chưa chỉ định nhóm." });
    var codes = (dto.ObjectCodes ?? new()).Select(c => (c ?? "").Trim()).Where(c => c.Length > 0).Distinct().ToList();

    var old = await db.MapSysGroupSysObjects.Where(x => x.OrgId == t.OrgId && x.GroupCode == group).ToListAsync();
    db.MapSysGroupSysObjects.RemoveRange(old);
    foreach (var c in codes)
        db.MapSysGroupSysObjects.Add(new MapSysGroupSysObject
        {
            OrgId = t.OrgId, GroupCode = group, ObjectCode = c, PartnerCode = SysPartnerDesktop,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { group, removed = old.Count, added = codes.Count, note = "Thay thế trọn bộ quyền màn hình của nhóm." });
}).RequireAuthorization();

// Tiện tra cứu: quyền màn hình HIỆU LỰC của một người dùng = hợp của mọi nhóm người đó thuộc về.
// (Nguồn có hàm riêng `SysGetMapSysUserSysObjectForCurrentUser` — đây là bản rút gọn theo dữ liệu đã port.)
// 🔴 Quyền HIỆU LỰC của một người dùng. Nguồn KHÔNG có bảng `Map_SU_SO` vật lý — quyền là **DẪN XUẤT**
// qua chuỗi join `Sys_User → Map_SG_SU → Map_SG_SO → Sys_Object`
// (`mySys_GetMapSysUserSysObject`, 2010.HTC BizHTC.System.cs:84; `dt_Map_SU_SO` chỉ là tên DataTable kết quả).
// #121 nâng cấp bản rút gọn của #120: nay join thật sang `Sys_Object` và **lọc theo `so.FlagActive`
// + `so.ObjectType`** đúng như ba mệnh đề `BuildClauseConditionList` của nguồn (dòng 163-165).
app.MapGet("/api/sysusers/{userCode}/objects", async (string userCode, AppDbContext db, ITenantContext t, string? objectType, string? flagActive) =>
{
    userCode = userCode.Trim();
    var groups = await db.MapSysGroupSysUsers.Where(x => x.OrgId == t.OrgId && x.UserCode == userCode)
        .Select(x => x.GroupCode).Distinct().ToListAsync();
    var codes = await db.MapSysGroupSysObjects.Where(x => x.OrgId == t.OrgId && groups.Contains(x.GroupCode))
        .Select(x => x.ObjectCode).Distinct().ToListAsync();
    var qy = db.SysObjects.Where(x => x.OrgId == t.OrgId && codes.Contains(x.ObjectCode));
    if (!string.IsNullOrWhiteSpace(objectType)) qy = qy.Where(x => x.ObjectType == objectType);
    // Nguồn lọc `so.FlagActive`; mặc định chỉ trả đối tượng đang hoạt động.
    var fa = string.IsNullOrWhiteSpace(flagActive) ? "1" : flagActive!;
    if (fa != "*") qy = qy.Where(x => x.FlagActive == fa);
    var objects = await qy.OrderBy(x => x.ObjectType).ThenBy(x => x.ObjectCode).Select(x => new
    {
        x.ObjectCode, x.ObjectType, x.ObjectName, x.ObjectCodeParent, x.FlagExecModal, x.FlagActive,
    }).ToListAsync();
    // Mã có trong map nhưng KHÔNG có trong danh mục — dấu hiệu danh mục thiếu dòng.
    var orphan = codes.Except(objects.Select(o => o.ObjectCode)).ToList();
    return Results.Ok(new { userCode, groups, count = objects.Count, objects, orphanCodes = orphan });
}).RequireAuthorization();

// ===== Người dùng / nhóm hệ thống (Sys_User, Sys_Group — port 1:1 `SysSaveUser`(16095) /
// `SysResetUserPassword`(15970) / `CommonChangeUserPassword`(30) / `SysSaveGroup`(16285),
// 2010.HTC Biz.HTC.WH.cs). TWIN: cả WS 32-bit lẫn 64-bit CÙNG bản `_New20181119`. =====
// 🔴 Luật `PasswordTemplate` = "********" (`TConst.HTCConst`, Const.Main.cs:321): mật khẩu gửi lên
//    ĐÚNG BẰNG chuỗi mẫu ⇒ nguồn LOẠI cột UserPassword khỏi danh sách ghi, tức KHÔNG đổi mật khẩu.
//    Port giữ nguyên: form che mật khẩu vẫn lưu được các trường khác.
// 🔴 KHÁC BIỆT CÓ CHỦ ĐÍCH (C0-bug9): nguồn lưu mật khẩu PLAINTEXT và so sánh trực tiếp
//    (`StringEqual(strPasswordOld, Rows[0]["UserPassword"])`). MiniHTC lưu **SHA-256**.
string PasswordTemplate = "********"; // TConst.HTCConst.PasswordTemplate
static string HashPwd(string raw) =>
    Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(raw)));

app.MapGet("/api/sysusers", async (AppDbContext db, ITenantContext t, string? userCode, string? dealerCode, string? flagActive) =>
{
    var qy = db.SysUsers.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(userCode)) qy = qy.Where(x => x.UserCode == userCode);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
    // KHÔNG trả cột mật khẩu ra ngoài, kể cả dạng hash.
    var items = await qy.OrderBy(x => x.UserCode).Select(x => new
    {
        x.UserCode, x.UserName, x.PartnerCode, x.DealerCode, x.BankCode,
        x.TransporterCode, x.InsCompanyCode, x.FlagSysAdmin, x.FlagSysViewer, x.FlagActive,
        HasPassword = x.UserPasswordHash != null,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/sysusers/save", async (SysUserSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.UserCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã người dùng rỗng." });
    // ===== 🔴 #254 UserCode — guard ký tự đặc biệt (bản đồ regex #249) =====
    // Nguồn DMSCarSv `Views/Auth/FrmMngUser.cs:422` (md5 `c58f3de5` — KHỚP 2 máy):
    //   `if (this.regex.IsMatch(strUserCodeToCheck)) ShowWarningMsgBox(MSG_WARNING_USERCODE_NOTSPE)`
    // Thông điệp gọi tên CẢ HAI thứ: "không được nhập **tiếng việt** hoặc chứa các ký tự đặc biệt"
    //   — đúng với pattern `[^a-zA-Z0-9._-]` vốn coi chữ có dấu là ký tự đặc biệt.
    // ⚠️ Ở nguồn, guard này nằm TRONG `try { … } catch (Exception){}` **nuốt lỗi** (:416-428):
    //    cột `User_Code` thiếu hay lỗi ép kiểu thì guard **im lặng bỏ qua**. Port KHÔNG nuốt lỗi.
    if (HasSpecialChar(code))
        return Results.BadRequest(new { error = "Mã người dùng không được nhập tiếng việt hoặc chứa các ký tự đặc biệt" });
    var row = await db.SysUsers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.UserCode == code);
    var isNew = row is null;
    if (isNew)
    {
        row = new SysUser { OrgId = t.OrgId, UserCode = code };
        db.SysUsers.Add(row);
    }
    row!.UserName = dto.UserName;
    row.PartnerCode = dto.PartnerCode;
    row.DealerCode = dto.DealerCode;
    row.BankCode = dto.BankCode;
    row.TransporterCode = dto.TransporterCode;
    row.InsCompanyCode = dto.InsCompanyCode;
    row.FlagSysAdmin = dto.FlagSysAdmin;
    row.FlagSysViewer = dto.FlagSysViewer;
    row.FlagActive = string.IsNullOrWhiteSpace(dto.FlagActive) ? "1" : dto.FlagActive!;
    // 🔴 Luật PasswordTemplate: đúng bằng chuỗi mẫu ⇒ GIỮ NGUYÊN mật khẩu cũ.
    var pwd = dto.UserPassword;
    if (!string.IsNullOrEmpty(pwd) && pwd != PasswordTemplate) row.UserPasswordHash = HashPwd(pwd);
    else if (isNew && string.IsNullOrEmpty(pwd))
        return Results.BadRequest(new { error = "Người dùng mới phải có mật khẩu." });
    await db.SaveChangesAsync();
    return Results.Ok(new { row.UserCode, created = isNew, passwordChanged = !string.IsNullOrEmpty(pwd) && pwd != PasswordTemplate });
}).RequireAuthorization();

// Xoá người dùng — nguồn 2010.HTC xử lý nhánh `DataRowState.Deleted` bằng `SaveData(dtDeleted)`, tức XOÁ THẬT.
//
// ===== 🔴 #254 HAI HỆ, HAI CÁCH XOÁ KHÁC NHAU — không được gộp =====
// · **2010.HTC** (nguồn của endpoint này): xoá THẬT bản ghi.
// · **TCMotor DMSCarSv** `FrmMngUser.cs:451-455`: nhánh `EditStatus.ITEM_VALUE_STT_DELETE` đặt
//   `dtRow[TblCommon.FlagActive] = "0"` rồi `SetModified()` ⇒ **XOÁ MỀM**, bản ghi vẫn còn.
// ⇒ Giữ mặc định = xoá thật (đúng nguồn của endpoint), thêm cờ `soft` cho đường DMSCarSv.
//   KHÔNG đổi mặc định: làm thế sẽ sai với hệ 2010.HTC vốn đang đúng.
app.MapPost("/api/sysusers/delete", async (SysUserKeyDto dto, AppDbContext db, ITenantContext t, bool? soft) =>
{
    var code = (dto.UserCode ?? "").Trim();

    // ===== 🔴 #257 CẤM XOÁ NGƯỜI DÙNG "sysadmin" =====
    // Nguồn `Views/Auth/FrmMngUser.cs:385-389` (md5 `c58f3de5` — KHỚP 2 máy):
    //     `if (strUserCode.ToUpper().Equals("SYSADMIN")) { ShowWarningMsgBox(MSG_WARNING_USER_SYSADMIN_NOTDELETE); return; }`
    //   `MSG_WARNING_USER_SYSADMIN_NOTDELETE` = "Không được phép xóa người dùng 'sysadmin'".
    // 🔴 So sánh **KHÔNG phân biệt hoa/thường** (nguồn `ToUpper()`) ⇒ "SysAdmin", "sysadmin" đều bị chặn.
    // ⚠️ Guard nằm ở `btnDelete_Click` nên áp cho **CẢ HAI** đường xoá (thật và mềm) — port cũng vậy.
    // ⚠️ Comment "// Không delete user current" (:395) **GÂY HIỂU NHẦM**: đoạn dưới nó chỉ gỡ dòng
    //    CHƯA LƯU khỏi lưới (`gviewUser.DeleteRow`), KHÔNG phải luật "không xoá user đang đăng nhập".
    //    Đã đọc kỹ — KHÔNG port thành guard.
    if (string.Equals(code, "SYSADMIN", StringComparison.OrdinalIgnoreCase))
        return Results.BadRequest(new { error = "Không được phép xóa người dùng 'sysadmin'" });

    var row = await db.SysUsers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.UserCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có người dùng {code}." });
    if (soft == true)
    {
        // đường DMSCarSv: chỉ tắt cờ, giữ bản ghi
        row.FlagActive = "0";
        await db.SaveChangesAsync();
        return Results.Ok(new { deactivated = code, flagActive = row.FlagActive, mode = "soft (DMSCarSv)" });
    }
    db.SysUsers.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = code, mode = "hard (2010.HTC)" });
}).RequireAuthorization();

// Đặt lại mật khẩu (nguồn `SysResetUserPassword`) — quản trị đặt mật khẩu mới cho người khác.
app.MapPost("/api/sysusers/reset-password", async (SysUserResetPwdDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.UserCode ?? "").Trim();
    var pwd = dto.PasswordReset ?? "";
    if (pwd.Length < 1) return Results.BadRequest(new { error = "Mật khẩu mới rỗng." });
    var row = await db.SysUsers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.UserCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có người dùng {code}." });
    row.UserPasswordHash = HashPwd(pwd);
    await db.SaveChangesAsync();
    return Results.Ok(new { row.UserCode, reset = true });
}).RequireAuthorization();

// Tự đổi mật khẩu (nguồn `CommonChangeUserPassword`): phải khớp mật khẩu CŨ mới cho đổi.
app.MapPost("/api/sysusers/change-password", async (SysUserChangePwdDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.UserCode ?? "").Trim();
    var row = await db.SysUsers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.UserCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có người dùng {code}." });
    // Nguồn: `if (!StringEqual(strPasswordOld, Rows[0]["UserPassword"])) throw` — so plaintext.
    // Ở đây so HASH, cùng ngữ nghĩa "phải đúng mật khẩu cũ".
    if (row.UserPasswordHash != HashPwd(dto.PasswordOld ?? ""))
        return Results.BadRequest(new { error = "Mật khẩu cũ không đúng." });
    var pwdNew = dto.PasswordNew ?? "";
    if (pwdNew.Length < 1) return Results.BadRequest(new { error = "Mật khẩu mới rỗng." });
    row.UserPasswordHash = HashPwd(pwdNew);
    await db.SaveChangesAsync();
    return Results.Ok(new { row.UserCode, changed = true });
}).RequireAuthorization();

app.MapGet("/api/sysgroups", async (AppDbContext db, ITenantContext t, string? groupCode, string? flagActive) =>
{
    var qy = db.SysGroups.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(groupCode)) qy = qy.Where(x => x.GroupCode == groupCode);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
    var items = await qy.OrderBy(x => x.GroupCode).Select(x => new
    { x.GroupCode, x.GroupName, x.PartnerCode, x.FlagActive, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// 🔴 Nguồn lưu nhóm bằng `SaveData("Sys_Group", dt)` KHÔNG truyền alColumnEffective ⇒ ghi TOÀN BỘ cột.
app.MapPost("/api/sysgroups/save", async (SysGroupSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.GroupCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã nhóm rỗng." });
    var row = await db.SysGroups.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GroupCode == code);
    var isNew = row is null;
    if (isNew) { row = new SysGroup { OrgId = t.OrgId, GroupCode = code }; db.SysGroups.Add(row); }
    row!.GroupName = dto.GroupName;
    row.PartnerCode = dto.PartnerCode;
    row.FlagActive = string.IsNullOrWhiteSpace(dto.FlagActive) ? "1" : dto.FlagActive!;
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { row.GroupCode, created = isNew });
}).RequireAuthorization();

// ===== Ba master còn nợ: Mst_Bank · Mst_District · Mst_DealerSalesType =====
// Nguồn: `Mst_Bank_CheckDB` (Biz.HTC.WH.cs:355) · tra `Mst_District` (Biz.HTC.WH.hkt.cs:9076) ·
// `Mst_DealerSalesType_CheckDB` (BizHTC.DealerSales.cs:138).
// Ba master này đã chặn guard ở #92 (tỉnh/huyện biên bản giao xe), #94 và #98 (mã ngân hàng,
// loại hình bán) — khi đó tôi ghi nợ thay vì bịa master rỗng; nay bổ sung để mở khoá.
// 🔴 `Mst_District` khoá là CẶP (ProvinceCode, DistrictCode) — nguồn luôn lọc đồng thời cả hai.
// 🔴 `Mst_DealerSalesType`: guard nguồn tra theo CẶP (SalesType, FlagActive) trong cùng một lệnh,
//    nên loại hình đã ngưng bị coi là KHÔNG TỒN TẠI, không phải "tồn tại nhưng khoá".
app.MapGet("/api/mstbanks", async (AppDbContext db, ITenantContext t, string? bankCode, string? parent, string? flagActive) =>
{
    var qy = db.MstBanks.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(bankCode)) qy = qy.Where(x => x.BankCode == bankCode);
    if (!string.IsNullOrWhiteSpace(parent)) qy = qy.Where(x => x.BankCodeParent == parent);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
    var items = await qy.OrderBy(x => x.BankCode)
        .Select(x => new { x.BankCode, x.BankName, x.BankCodeParent, x.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/mstbanks", async (MstBankDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.BankCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã ngân hàng rỗng." });
    if (await db.MstBanks.AnyAsync(x => x.OrgId == t.OrgId && x.BankCode == code))
        return Results.BadRequest(new { error = $"Ngân hàng {code} đã tồn tại." });
    var parent = (dto.BankCodeParent ?? "").Trim();
    // Có khai báo ngân hàng mẹ thì mẹ phải tồn tại (cấu trúc cha–con của master này).
    if (parent.Length > 0 && !await db.MstBanks.AnyAsync(x => x.OrgId == t.OrgId && x.BankCode == parent))
        return Results.BadRequest(new { error = $"Ngân hàng mẹ {parent} không tồn tại." });
    db.MstBanks.Add(new MstBank
    {
        OrgId = t.OrgId, BankCode = code, BankName = dto.BankName,
        BankCodeParent = parent.Length > 0 ? parent : null,
        FlagActive = string.IsNullOrWhiteSpace(dto.FlagActive) ? "1" : dto.FlagActive!,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { bankCode = code });
}).RequireAuthorization();

// ===== 🔴 #227 DANH MỤC TỈNH/THÀNH — `Mst_Province_Get` (BizCarSv.Master.cs:8588) =====
// Màn dùng: `Views/Customer/FrmCustomerDetailInfo.cs` (1059 dòng, DMSCarSv) nạp tỉnh (144) và huyện (161)
//   để đổ combobox địa chỉ khách hàng. BƯỚC 3B: md5 CẢ FILE `90585079` (12871 dòng) KHỚP 2 máy.
// 🔴 GAP: MiniHTC đã có `/api/mstdistricts` (huyện) nhưng **thiếu hẳn bảng TỈNH** — chỉ dùng `ProvinceCode`
//    làm tham số lọc ở vài báo cáo, không có danh mục để tra tên. Nay bổ sung entity + DbSet + Seeder + API.
// Nguồn lọc theo 6 cột (`BuildClause`): ProvinceCode · ProvinceName · FlagActive · CreatedDate · CreatedBy ·
//   `AreaCode` — cả sáu đều là cột thật của bảng (nguồn `select mpg.*`).
// ⚠️ `BuildClause` với chuỗi rỗng = **bỏ hẳn điều kiện** (luật `C0-trecentesimusvicesimusquartus`)
//    ⇒ không truyền tham số nghĩa là lấy TẤT CẢ, kể cả bản ghi đã tắt.
app.MapGet("/api/mstprovinces", async (AppDbContext db, ITenantContext t,
    string? provinceCode, string? provinceName, string? areaCode, string? flagActive) =>
{
    var qy = db.MstProvinces.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(provinceCode)) qy = qy.Where(x => x.ProvinceCode == provinceCode!.Trim());
    if (!string.IsNullOrWhiteSpace(areaCode)) qy = qy.Where(x => x.AreaCode == areaCode!.Trim());
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive!.Trim());
    if (!string.IsNullOrWhiteSpace(provinceName))
        qy = qy.Where(x => x.ProvinceName != null && x.ProvinceName.ToLower().Contains(provinceName!.Trim().ToLower()));

    var items = await qy.OrderBy(x => x.ProvinceName).Take(500)
        .Select(x => new { x.Id, x.ProvinceCode, x.ProvinceName, x.AreaCode, x.FlagActive, x.CreatedDate, x.CreatedBy })
        .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/mstprovinces", async (MstProvinceDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.ProvinceCode ?? "").Trim();
    if (code.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã tỉnh/thành." });
    var row = await db.MstProvinces.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ProvinceCode == code);
    var isNew = row is null;
    if (row is null)
    {
        row = new MstProvince { OrgId = t.OrgId, ProvinceCode = code,
                                CreatedDate = DateTime.Now,
                                CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system" };
        db.MstProvinces.Add(row);
    }
    // upsert: cả HAI nhánh cùng gán bộ cột nghiệp vụ (luật `C0-trecentesimustricesimusseptimus`).
    row.ProvinceName = dto.ProvinceName;
    row.AreaCode = dto.AreaCode;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!.Trim();
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.ProvinceCode, row.ProvinceName, row.AreaCode, row.FlagActive, created = isNew });
}).RequireAuthorization();

