        .GroupBy(c => c.GrtClaimId).Select(g => new { g.Key, cars = g.Count(), amount = g.Sum(x => x.UnitPrice) }).ToListAsync();
    var m = dtlAgg.ToDictionary(x => x.Key, x => (x.cars, x.amount));
    int Cars(long id) => m.TryGetValue(id, out var v) ? v.cars : 0;
