// ===== Báo cáo hợp đồng bán lẻ (port 1:1 báo cáo Dlr_Contract) — tái dùng DlrContract + DlrContractDetail =====
app.MapGet("/api/report/dlrcontract", async (AppDbContext db, ITenantContext t, string? dealer, string? salesType, string? status, string? salesman, DateTime? from, DateTime? to) =>
{
    var q = db.DlrContracts.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(salesType)) q = q.Where(c => c.SalesType == salesType);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (!string.IsNullOrWhiteSpace(salesman)) q = q.Where(c => c.SalesManCode == salesman);
    if (from is not null) q = q.Where(c => c.SignDate >= from.Value.Date);
    if (to is not null) q = q.Where(c => c.SignDate < to.Value.Date.AddDays(1));
    var cons = await q.ToListAsync();
    var ids = cons.Select(c => c.Id).ToHashSet();
    var dtlAgg = await db.DlrContractDetails.Where(l => l.OrgId == t.OrgId && ids.Contains(l.ContractId))
        .GroupBy(l => l.ContractId).Select(g => new { g.Key, qty = g.Sum(x => x.Qty), total = g.Sum(x => x.TotalAmountAfterVAT) }).ToListAsync();
    var m = dtlAgg.ToDictionary(x => x.Key, x => (x.qty, x.total));
    int Qty(long id) => m.TryGetValue(id, out var v) ? v.qty : 0;
    decimal Total(long id) => m.TryGetValue(id, out var v) ? v.total : 0;
    var byDealer = cons.GroupBy(c => string.IsNullOrEmpty(c.DealerCode) ? "(chưa rõ)" : c.DealerCode)
        .Select(g => new { dealerCode = g.Key, count = g.Count(), qty = g.Sum(c => Qty(c.Id)), amount = g.Sum(c => Total(c.Id)), active = g.Count(c => c.Status == "Active") }).OrderByDescending(x => x.amount).ToList();
    var bySalesType = cons.GroupBy(c => string.IsNullOrEmpty(c.SalesType) ? "(chưa rõ)" : c.SalesType).Select(g => new { salesType = g.Key, count = g.Count(), qty = g.Sum(c => Qty(c.Id)), amount = g.Sum(c => Total(c.Id)) }).OrderByDescending(x => x.amount).ToList();
    var bySalesman = cons.Where(c => !string.IsNullOrEmpty(c.SalesManCode)).GroupBy(c => c.SalesManCode).Select(g => new { salesManCode = g.Key, count = g.Count(), amount = g.Sum(c => Total(c.Id)) }).OrderByDescending(x => x.amount).ToList();
    var detail = cons.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.DlrContractNo, c.DlrContractNoUser, c.DealerCode, c.SalesManCode, c.SalesType, c.CustomerName, c.Status,
        qty = Qty(c.Id), amount = Total(c.Id), signDate = c.SignDate.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = cons.Count, totalQty = cons.Sum(c => Qty(c.Id)), totalAmount = cons.Sum(c => Total(c.Id)),
        active = cons.Count(c => c.Status == "Active"), byDealer, bySalesType, bySalesman, detail });
}).RequireAuthorization();

// ===== Báo cáo CRM: lượt khách thăm & lái thử (port 1:1 báo cáo CtmVisit/DriveTest) — tái dùng CtmVisit + DriveTest =====
app.MapGet("/api/report/crm", async (AppDbContext db, ITenantContext t, string? dealer, string? model, DateTime? from, DateTime? to) =>
{
    var vq = db.CtmVisits.Where(v => v.OrgId == t.OrgId);
    var dq = db.DriveTests.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) { vq = vq.Where(v => v.DealerCode == dealer); dq = dq.Where(d => d.DealerCode == dealer); }
    if (!string.IsNullOrWhiteSpace(model)) { vq = vq.Where(v => v.ModelCode == model); dq = dq.Where(d => d.TestModelCode == model); }
    if (from is not null) dq = dq.Where(d => d.DriveDate >= from.Value.Date);
    if (to is not null) dq = dq.Where(d => d.DriveDate < to.Value.Date.AddDays(1));
    var visits = await vq.ToListAsync();
    var drives = await dq.ToListAsync();
    string GenderLabel(string g) => g == "1" ? "Nữ" : g == "0" ? "Nam" : "(chưa rõ)";
    var visitByDealer = visits.GroupBy(v => string.IsNullOrEmpty(v.DealerCode) ? "(chưa rõ)" : v.DealerCode).Select(g => new { dealerCode = g.Key, visits = g.Count() }).OrderByDescending(x => x.visits).ToList();
    var visitByGender = visits.GroupBy(v => GenderLabel(v.Gender)).Select(g => new { gender = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var visitByAge = visits.GroupBy(v => string.IsNullOrEmpty(v.RangeAge) ? "(chưa rõ)" : v.RangeAge).Select(g => new { rangeAge = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var visitByModel = visits.GroupBy(v => string.IsNullOrEmpty(v.ModelCode) ? "(chưa rõ)" : v.ModelCode).Select(g => new { modelCode = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var driveByModel = drives.GroupBy(d => string.IsNullOrEmpty(d.TestModelCode) ? "(chưa rõ)" : d.TestModelCode).Select(g => new { modelCode = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var driveByType = drives.GroupBy(d => string.IsNullOrEmpty(d.DriverTestType) ? "(chưa rõ)" : d.DriverTestType).Select(g => new { driveType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    // Tỉ lệ chuyển đổi thăm -> lái thử
    var convRate = visits.Count > 0 ? Math.Round(drives.Count * 100.0 / visits.Count, 1) : 0;
    return Results.Ok(new { totalVisits = visits.Count, totalDrives = drives.Count, conversionRatePct = convRate,
        visitByDealer, visitByGender, visitByAge, visitByModel, driveByModel, driveByType });
}).RequireAuthorization();

// ===== Báo cáo xe đang thế chấp (port 1:1 báo cáo BankCarMortage) — tái dùng BankCarMortage =====
app.MapGet("/api/report/mortgage", async (AppDbContext db, ITenantContext t, string? mortageBank, string? dealer, string? guaranteeType, string? active) =>
{
    var q = db.BankCarMortages.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mortageBank)) q = q.Where(m => m.MortageBankCode == mortageBank);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(m => m.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(guaranteeType)) q = q.Where(m => m.GuaranteeType == guaranteeType);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(m => m.FlagActive == active);
    var recs = await q.ToListAsync();
    var byBank = recs.GroupBy(m => string.IsNullOrEmpty(m.MortageBankCode) ? "(chưa rõ)" : m.MortageBankCode)
        .Select(g => new { mortageBank = g.Key, count = g.Count(), active = g.Count(x => x.FlagActive == "1"), released = g.Count(x => x.FlagActive != "1") }).OrderByDescending(x => x.count).ToList();
    var byDealer = recs.GroupBy(m => string.IsNullOrEmpty(m.DealerCode) ? "(chưa rõ)" : m.DealerCode).Select(g => new { dealerCode = g.Key, count = g.Count(), active = g.Count(x => x.FlagActive == "1") }).OrderByDescending(x => x.count).ToList();
    string GtLabel(string g) => g == "1" ? "NH phát hành" : "NH giám sát";
    var byGrtType = recs.GroupBy(m => GtLabel(m.GuaranteeType)).Select(g => new { guaranteeType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    string RangeLabel(string r) => r switch { "DlvThisWeek" => "Trong tuần", "DlvNextWeek" => "Tuần tới", _ => "Giao ngay" };
    var byRange = recs.Where(m => m.FlagActive == "1").GroupBy(m => RangeLabel(m.DeliveryRangeType)).Select(g => new { range = g.Key, count = g.Count() }).ToList();
    var detail = recs.OrderByDescending(m => m.Id).Take(500).Select(m => new
    {
        m.VIN, m.DealerCode, m.MortageBankCode, m.BankCode, m.ModelCode, guaranteeType = GtLabel(m.GuaranteeType), deliveryRange = RangeLabel(m.DeliveryRangeType), m.FlagActive
    }).ToList();
    return Results.Ok(new { total = recs.Count, active = recs.Count(m => m.FlagActive == "1"), released = recs.Count(m => m.FlagActive != "1"), byBank, byDealer, byGrtType, byRange, detail });
}).RequireAuthorization();

// ===== Báo cáo đơn hàng nâng cấp (port 1:1 báo cáo Upgrade Order) — tái dùng UpgradeOrder =====
app.MapGet("/api/report/upgradeorder", async (AppDbContext db, ITenantContext t, string? dealer, string? month, string? type, string? status) =>
{
    var q = db.UpgradeOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(month)) q = q.Where(o => o.OrderMonth == month);
    if (!string.IsNullOrWhiteSpace(type)) q = q.Where(o => o.OrderType == type);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(o => o.Status == status);
    var recs = await q.ToListAsync();
    var byDealer = recs.GroupBy(o => string.IsNullOrEmpty(o.DealerCode) ? "(chưa rõ)" : o.DealerCode)
        .Select(g => new { dealerCode = g.Key, orders = g.Count(), qty = g.Sum(x => x.TotalQty), approved = g.Count(x => x.Status == "Approved") }).OrderByDescending(x => x.qty).ToList();
    var byMonth = recs.GroupBy(o => string.IsNullOrEmpty(o.OrderMonth) ? "(chưa rõ)" : o.OrderMonth)
        .Select(g => new { month = g.Key, orders = g.Count(), qty = g.Sum(x => x.TotalQty) }).OrderBy(x => x.month).ToList();
    var byType = recs.GroupBy(o => string.IsNullOrEmpty(o.OrderType) ? "(chưa rõ)" : o.OrderType).Select(g => new { orderType = g.Key, orders = g.Count(), qty = g.Sum(x => x.TotalQty) }).OrderByDescending(x => x.qty).ToList();
    var byPolicy = recs.GroupBy(o => string.IsNullOrEmpty(o.OrderPolicy) ? "(chưa rõ)" : o.OrderPolicy).Select(g => new { policy = g.Key, orders = g.Count(), qty = g.Sum(x => x.TotalQty) }).OrderByDescending(x => x.qty).ToList();
    var byStatus = recs.GroupBy(o => o.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = recs.OrderByDescending(o => o.Id).Take(500).Select(o => new { o.OrderNo, o.DealerCode, o.OrderMonth, o.OrderType, o.OrderPolicy, o.TotalQty, o.Status }).ToList();
    return Results.Ok(new { total = recs.Count, totalQty = recs.Sum(o => o.TotalQty), approved = recs.Count(o => o.Status == "Approved"), byDealer, byMonth, byType, byPolicy, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo tiến độ sản xuất (port 1:1 báo cáo WO_Schedule) — tái dùng WoSchedule + WoScheduleLine =====
app.MapGet("/api/report/production", async (AppDbContext db, ITenantContext t, string? model, string? status) =>
{
    var sq = db.WoSchedules.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) sq = sq.Where(s => s.Status == status);
    var schedules = await sq.ToListAsync();
    var ids = schedules.Select(s => s.Id).ToHashSet();
    var lq = db.WoScheduleLines.Where(l => l.OrgId == t.OrgId && ids.Contains(l.WoScheduleId));
    if (!string.IsNullOrWhiteSpace(model)) lq = lq.Where(l => l.ModelCode == model);
    var lines = await lq.ToListAsync();
    int Pct(int prod, int ord) => ord > 0 ? (int)Math.Round(prod * 100.0 / ord) : 0;
    var byModel = lines.GroupBy(l => string.IsNullOrEmpty(l.ModelCode) ? "(chưa rõ)" : l.ModelCode)
        .Select(g => { int ord = g.Sum(x => x.QtyOrder); int prod = g.Sum(x => x.QtyProduct); int rem = g.Sum(x => x.QtyRemain);
            return new { modelCode = g.Key, qtyOrder = ord, qtyProduct = prod, qtyRemain = rem, completePct = Pct(prod, ord) }; })
        .OrderByDescending(x => x.qtyRemain).ToList();
    var totOrder = lines.Sum(l => l.QtyOrder); var totProduct = lines.Sum(l => l.QtyProduct); var totRemain = lines.Sum(l => l.QtyRemain);
    var byStatus = schedules.GroupBy(s => s.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = lines.OrderByDescending(l => l.QtyRemain).Take(500).Select(l => new
    {
        l.WorkOrderNo, l.ModelCode, l.SpecCode, l.ColorCode, l.QtyOrder, l.QtyProduct, l.QtyRemain, completePct = Pct(l.QtyProduct, l.QtyOrder)
    }).ToList();
    return Results.Ok(new { schedules = schedules.Count, lines = lines.Count, totalOrder = totOrder, totalProduct = totProduct, totalRemain = totRemain,
        overallPct = Pct(totProduct, totOrder), byModel, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo chi phí tài chính (port 1:1 báo cáo DMS40_FnExp_Calc) — tái dùng FnExpCalc + FnExpCalcLine =====
app.MapGet("/api/report/fnexp", async (AppDbContext db, ITenantContext t, string? dealer, string? status, DateTime? from, DateTime? to) =>
{
    var q = db.FnExpCalcs.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (from is not null) q = q.Where(c => c.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(c => c.CreatedAt < to.Value.Date.AddDays(1));
    var recs = await q.ToListAsync();
    var ids = recs.Select(c => c.Id).ToHashSet();
    var lineCount = await db.FnExpCalcLines.Where(l => l.OrgId == t.OrgId && ids.Contains(l.FnExpCalcId))
        .GroupBy(l => l.FnExpCalcId).Select(g => new { g.Key, cars = g.Count(), pd = g.Sum(x => x.PDAmount) }).ToListAsync();
    var m = lineCount.ToDictionary(x => x.Key, x => (x.cars, x.pd));
    int Cars(long id) => m.TryGetValue(id, out var v) ? v.cars : 0;
    decimal Pd(long id) => m.TryGetValue(id, out var v) ? v.pd : 0;
    var byDealer = recs.GroupBy(c => string.IsNullOrEmpty(c.DealerCode) ? "(chưa rõ)" : c.DealerCode)
        .Select(g => new { dealerCode = g.Key, count = g.Count(), cars = g.Sum(c => Cars(c.Id)), fnExp = g.Sum(c => c.TotalFnExp), pd = g.Sum(c => Pd(c.Id)),
            avgRate = g.Any() ? Math.Round(g.Average(c => c.FnExpPercent), 2) : 0 }).OrderByDescending(x => x.fnExp).ToList();
    var byStatus = recs.GroupBy(c => c.Status).Select(g => new { status = g.Key, count = g.Count(), fnExp = g.Sum(x => x.TotalFnExp) }).OrderByDescending(x => x.count).ToList();
    var detail = recs.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.CaNo, c.DealerCode, c.FnExpPercent, c.TotalFnExp, cars = Cars(c.Id), pd = Pd(c.Id), c.Status, createdAt = c.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = recs.Count, totalFnExp = recs.Sum(c => c.TotalFnExp), totalPd = recs.Sum(c => Pd(c.Id)),
        approved = recs.Count(c => c.Status == "Approved"), byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo tiến độ nhận xe trên lệnh xuất (port 1:1 báo cáo BankDO) — tái dùng BankDeliveryOrder + BankDoCar =====
app.MapGet("/api/report/bankdo", async (AppDbContext db, ITenantContext t, string? dealer, string? status) =>
{
    var q = db.BankDeliveryOrders.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(d => d.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(d => d.Status == status);
    var dos = await q.ToListAsync();
    var ids = dos.Select(d => d.Id).ToHashSet();
    var carAgg = await db.BankDoCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.DeliveryOrderId))
        .GroupBy(c => c.DeliveryOrderId).Select(g => new { g.Key, cars = g.Count(), confirmed = g.Count(x => x.ConfirmStatus == "1") }).ToListAsync();
    var m = carAgg.ToDictionary(x => x.Key, x => (x.cars, x.confirmed));
    int Cars(long id) => m.TryGetValue(id, out var v) ? v.cars : 0;
    int Confirmed(long id) => m.TryGetValue(id, out var v) ? v.confirmed : 0;
    int Pct(int c, int tot) => tot > 0 ? (int)Math.Round(c * 100.0 / tot) : 0;
    var byDealer = dos.GroupBy(d => string.IsNullOrEmpty(d.DealerCode) ? "(chưa rõ)" : d.DealerCode)
        .Select(g => { int cars = g.Sum(d => Cars(d.Id)); int conf = g.Sum(d => Confirmed(d.Id));
            return new { dealerCode = g.Key, orders = g.Count(), cars, confirmed = conf, remain = cars - conf, confirmedPct = Pct(conf, cars) }; })
        .OrderByDescending(x => x.remain).ToList();
    var byStatus = dos.GroupBy(d => d.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var totCars = dos.Sum(d => Cars(d.Id)); var totConf = dos.Sum(d => Confirmed(d.Id));
    var detail = dos.OrderByDescending(d => d.Id).Take(500).Select(d => new
    {
        d.DONo, d.DealerCode, d.SOCode, d.Status, cars = Cars(d.Id), confirmed = Confirmed(d.Id), remain = Cars(d.Id) - Confirmed(d.Id), confirmedPct = Pct(Confirmed(d.Id), Cars(d.Id))
    }).ToList();
    return Results.Ok(new { total = dos.Count, totalCars = totCars, totalConfirmed = totConf, totalRemain = totCars - totConf, overallPct = Pct(totConf, totCars), byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo yêu cầu vận chuyển (port 1:1 báo cáo TransportRequest) — tái dùng TransportRequest + TransportReqCar =====
app.MapGet("/api/report/transport", async (AppDbContext db, ITenantContext t, string? transporter, string? dealer, string? status, DateTime? from, DateTime? to) =>
{
    var q = db.TransportRequests.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(transporter)) q = q.Where(r => r.TransporterCode == transporter);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    if (from is not null) q = q.Where(r => r.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(r => r.CreatedAt < to.Value.Date.AddDays(1));
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var carAgg = await db.TransportReqCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.ReqId))
        .GroupBy(c => c.ReqId).Select(g => new { g.Key, cars = g.Count() }).ToListAsync();
    var m = carAgg.ToDictionary(x => x.Key, x => x.cars);
    int Cars(long id) => m.TryGetValue(id, out var v) ? v : 0;
    var byTransporter = reqs.GroupBy(r => string.IsNullOrEmpty(r.TransporterCode) ? "(chưa rõ)" : r.TransporterCode)
        .Select(g => new { transporterCode = g.Key, count = g.Count(), cars = g.Sum(r => Cars(r.Id)), approved = g.Count(r => r.Status == "Approved") }).OrderByDescending(x => x.cars).ToList();
    var byDealer = reqs.GroupBy(r => string.IsNullOrEmpty(r.DealerCode) ? "(chưa rõ)" : r.DealerCode).Select(g => new { dealerCode = g.Key, count = g.Count(), cars = g.Sum(r => Cars(r.Id)) }).OrderByDescending(x => x.cars).ToList();
    var byStatus = reqs.GroupBy(r => r.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = reqs.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.TranspReqNo, r.DealerCode, r.TransporterCode, r.TransContractNo, cars = Cars(r.Id), r.Status, createdAt = r.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = reqs.Sum(r => Cars(r.Id)), approved = reqs.Count(r => r.Status == "Approved"), byTransporter, byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo đơn đặt hàng sản xuất (port 1:1 báo cáo MnfPl_Order) — tái dùng MnfPlOrder + MnfPlOrderDtl =====
app.MapGet("/api/report/mnfplorder", async (AppDbContext db, ITenantContext t, string? ordType, string? model, string? status) =>
{
    var oq = db.MnfPlOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(ordType)) oq = oq.Where(o => o.OrdType == ordType);
    if (!string.IsNullOrWhiteSpace(status)) oq = oq.Where(o => o.Status == status);
    var orders = await oq.ToListAsync();
    var ids = orders.Select(o => o.Id).ToHashSet();
    var lq = db.MnfPlOrderDtls.Where(l => l.OrgId == t.OrgId && ids.Contains(l.MnfPlOrderId));
    if (!string.IsNullOrWhiteSpace(model)) lq = lq.Where(l => l.ModelCode == model);
    var lines = await lq.ToListAsync();
    var byModel = lines.GroupBy(l => string.IsNullOrEmpty(l.ModelCode) ? "(chưa rõ)" : l.ModelCode)
        .Select(g => new { modelCode = g.Key, lines = g.Count(), qty = g.Sum(x => x.Quantity) }).OrderByDescending(x => x.qty).ToList();
    var byType = orders.GroupBy(o => string.IsNullOrEmpty(o.OrdType) ? "(chưa rõ)" : o.OrdType).Select(g => new { ordType = g.Key, orders = g.Count() }).OrderByDescending(x => x.orders).ToList();
    var byStatus = orders.GroupBy(o => o.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    // group line qty per order
    var qtyByOrder = lines.GroupBy(l => l.MnfPlOrderId).ToDictionary(g => g.Key, g => (lines: g.Count(), qty: g.Sum(x => x.Quantity)));
    var detail = orders.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.OrderNo, o.OrdType, o.Status,
        lines = qtyByOrder.TryGetValue(o.Id, out var v) ? v.lines : 0,
        qty = qtyByOrder.TryGetValue(o.Id, out var v2) ? v2.qty : 0
    }).ToList();
    return Results.Ok(new { orders = orders.Count, lines = lines.Count, totalQty = lines.Sum(l => l.Quantity), sent = orders.Count(o => o.Status == "Sent"), byModel, byType, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo đề nghị giao tài liệu (ĐNGT) (port 1:1 báo cáo CarDocRequest) — tái dùng CarDocRequest + CarDocRequestCar =====
app.MapGet("/api/report/cardocreq", async (AppDbContext db, ITenantContext t, string? dealer, string? status, DateTime? from, DateTime? to) =>
{
