        .Select(g => new { dealerCode = g.Key, count = g.Count(), cars = g.Sum(r => Cars(r.Id)), done = g.Count(r => r.Status == "Done"), rejected = g.Count(r => r.Status == "Rejected") }).OrderByDescending(x => x.cars).ToList();
