app.MapPost("/api/bankaccounts", async (BankAccountDto dto, AppDbContext db, ITenantContext t) =>
{
    // audit 2026-09-03: nguồn (btnSave_Click, Excel-row validate) bắt buộc AccountName/BankCode/DealerCode/FlagAccGrtClaim
    // — port trước chỉ check AccountNo, và dedupe chỉ theo AccountNo (nguồn dùng khóa hỗn hợp AccountNo+BankCode, xem
    // BankAccountKey trong FrmMstAccountBank.cs — 1 số TK có thể lặp lại ở NH khác).
    if (string.IsNullOrWhiteSpace(dto.AccountNo)) return Results.BadRequest(new { error = "Số tài khoản không được trống!" });
    if (string.IsNullOrWhiteSpace(dto.AccountName)) return Results.BadRequest(new { error = "Tên tài khoản không được để trống" });
    if (string.IsNullOrWhiteSpace(dto.BankCode)) return Results.BadRequest(new { error = "Mã ngân hàng không được để trống" });
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Mã đại lý không được để trống" });
    if (string.IsNullOrWhiteSpace(dto.FlagAccGrtClaim) || (dto.FlagAccGrtClaim != "0" && dto.FlagAccGrtClaim != "1"))
        return Results.BadRequest(new { error = "Cờ TK Công văn không hợp lệ!" });
    var acc = dto.AccountNo.Trim(); var bankCode = dto.BankCode.Trim();
    if (await db.BankAccounts.AnyAsync(a => a.OrgId == t.OrgId && a.AccountNo == acc && a.BankCode == bankCode))
        return Results.BadRequest(new { error = $"Tài khoản import '{acc}' thuộc ngân hàng '{bankCode}' đã tồn tại!" });
    var a2 = new BankAccount { OrgId = t.OrgId, AccountNo = acc, AccountName = dto.AccountName, BankCode = bankCode, DealerCode = dto.DealerCode, FlagAccGrtClaim = dto.FlagAccGrtClaim, FlagActive = "1" };
    db.BankAccounts.Add(a2); await db.SaveChangesAsync();
    return Results.Ok(new { a2.AccountNo });
}).RequireAuthorization();

app.MapPost("/api/bankaccounts/{acc}/toggle", async (string acc, AppDbContext db, ITenantContext t) =>
{
    acc = acc.Trim();
    var a = await db.BankAccounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AccountNo == acc);
    if (a is null) return Results.NotFound(new { acc });
    a.FlagActive = a.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { a.AccountNo, flagActive = a.FlagActive });
}).RequireAuthorization();

// ===== 🔴 #228 BẢNG GIÁ GỬI TIN — `Mst_PriceSend_Get` (SMS.V10/SMS.Biz/BizSMS.MasterData.cs:851) =====
// Màn gốc: `Views/SMS/FrmSMSPriceDealer.cs` (194 dòng, TCMotor DMSCarSv) — đại lý XEM bảng giá gửi tin.
// ⚠️ Màn **CHỈ ĐỌC**: `FrmParam_Load` đặt `btnLuu/btnThem/btnEdit/btnReload/btnDelete.Visible = false` và
//    thân `btnLuu_Click` **rỗng** ⇒ không có lệnh ghi nào để port. Đã quét CẢ gateway `SMS.WS/App_Code/WSSMS.cs`:
//    chỉ có `Mst_PriceSend_Get` + `Mst_PriceSend_GetEx01`, **không tồn tại lệnh Create/Update/Delete** trong
//    toàn bộ SMS.V10 (bảng giá do NCC/DBA nạp thẳng vào DB) ⇒ CỐ Ý không thêm POST (không bịa lệnh ghi).
//
// BƯỚC 3B: hệ `SMS.V10` **CHỈ tồn tại trên máy 150**, laptop KHÔNG có ⇒ đã đọc bản 150.
//    `BizSMS.MasterData.cs` md5 `1bf83667` (1258 dòng).
//
// 🔴 Cột thật lấy từ `SqlUtils.BuildColumns` của biz (KHÔNG lấy từ lớp hằng `TblMst_PriceSend` phía client —
//    lớp đó chỉ liệt kê 5/8 cột, THIẾU `BATCHTYPE`/`LUDTIME`/`LUBY`):
//    COSTTYPE · SUPPLIERCODE · TELCOCODE · BATCHTYPE · EFFECTDATE · UNITPRICE · LUDTIME · LUBY
//    + 3 cột enrich qua left join: MCTCOSTTYPENAME · MSSUPPLIERNAME · MTCTELCONAME.
// Client truyền cả 5 bộ lọc = chuỗi RỖNG và `strLimitColList = "*"` ⇒ **lấy TOÀN BỘ bảng, đủ cột**.
// Nguồn `order by mps.CostType asc`.
app.MapGet("/api/smspricesends", async (AppDbContext db, ITenantContext t,
    string? costType, string? supplierCode, string? telCoCode, string? batchType) =>
{
    var qy = db.SmsPriceSends.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(costType)) qy = qy.Where(x => x.CostType == costType!.Trim());
    if (!string.IsNullOrWhiteSpace(supplierCode)) qy = qy.Where(x => x.SupplierCode == supplierCode!.Trim());
    if (!string.IsNullOrWhiteSpace(telCoCode)) qy = qy.Where(x => x.TelCoCode == telCoCode!.Trim());
    if (!string.IsNullOrWhiteSpace(batchType)) qy = qy.Where(x => x.BatchType == batchType!.Trim());

    var items = await qy.OrderBy(x => x.CostType).ThenBy(x => x.SupplierCode).ThenBy(x => x.TelCoCode)
        .ThenByDescending(x => x.EffectDate)
        .Select(x => new { x.Id, x.CostType, x.SupplierCode, x.TelCoCode, x.BatchType, x.EffectDate,
                           x.UnitPrice, x.LuDTime, x.LuBy, x.CostTypeName, x.SupplierName, x.TelCoName })
        .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// 🔴 GIÁ ĐANG HIỆU LỰC — port 1:1 khối `#tbl_Mst_PriceSend_Effect` (BizSMS.SMS.cs:279-295), là chỗ DUY NHẤT
//    trong nguồn thực sự CHỌN giá để tính tiền lô tin:
//      `inner join (select CostType, SupplierCode, TelCoCode, Max(EffectDate) …`
//       `where EffectDate <= @strDateEffect group by CostType, SupplierCode, TelCoCode)`
//    ⇒ giá hiệu lực = dòng có `EffectDate` LỚN NHẤT nhưng **≤ ngày mốc**, nhóm theo BỘ BA
//      (CostType, SupplierCode, TelCoCode).
// 🔴 HAI BẪY của quy tắc này:
//  1. Ngày mốc là `Sms_Batch.EffectDTime` — **ngày hiệu lực của LÔ TIN**, KHÔNG phải ngày hiện tại.
//     ⇒ tham số `effectDate` bắt buộc do gọi truyền vào; mặc định `DateTime.Now` chỉ là tiện dụng.
//  2. `BatchType` **KHÔNG** nằm trong `group by` lẫn điều kiện join ⇒ giá **không** đổi theo loại lô
//     (CSKH/QC), dù bảng có cột đó. Đừng "sửa cho hợp lý" thành lọc theo BatchType.
app.MapGet("/api/smspricesends/effective", async (AppDbContext db, ITenantContext t,
    string? costType, string? supplierCode, string? telCoCode, DateTime? effectDate) =>
{
    var mark = effectDate ?? DateTime.Now;
    var qy = db.SmsPriceSends.Where(x => x.OrgId == t.OrgId && x.EffectDate <= mark);
    if (!string.IsNullOrWhiteSpace(costType)) qy = qy.Where(x => x.CostType == costType!.Trim());
    if (!string.IsNullOrWhiteSpace(supplierCode)) qy = qy.Where(x => x.SupplierCode == supplierCode!.Trim());
    if (!string.IsNullOrWhiteSpace(telCoCode)) qy = qy.Where(x => x.TelCoCode == telCoCode!.Trim());

    var rows = await qy.ToListAsync();
    var items = rows
        .GroupBy(x => new { x.CostType, x.SupplierCode, x.TelCoCode })   // đúng group by của nguồn
        .Select(g => g.OrderByDescending(x => x.EffectDate).First())     // Max(EffectDate)
        .OrderBy(x => x.CostType).ThenBy(x => x.SupplierCode).ThenBy(x => x.TelCoCode)
        .Select(x => new { x.CostType, x.SupplierCode, x.TelCoCode, x.BatchType, x.EffectDate,
                           x.UnitPrice, x.CostTypeName, x.SupplierName, x.TelCoName })
        .ToList();
    return Results.Ok(new
    {
        markDate = mark, count = items.Count, items,
        note = "Ngày mốc phải là ngày hiệu lực của LÔ TIN (Sms_Batch.EffectDTime), không phải ngày gửi.",
    });
}).RequireAuthorization();

// ===== 🔴 #230 BRANDNAME CỦA TÀI KHOẢN — `Acc_BrandName_Get` (BizSMS.Account.cs:1729) =====
// Màn dùng: `Views/SMS/FrmSendSMSAdvertisement.cs` (:238) và `FrmSendSMSOther.cs` (:238) đổ combo người gửi;
//   `SMS_Batch_Send` (SmsOutService.cs:133) lấy dòng ĐẦU TIÊN để ghi vào `Sms_Send.BranchName`.
// BƯỚC 3B: hệ `SMS.V10` CHỈ có trên máy 150 ⇒ đọc bản 150; `BizSMS.Account.cs` md5 `0135096b` (2753 dòng).
// Cột: BRANDNAME (khoá — nguồn `select distinct abn.BrandName`) · ACCOUNTCODE · LUDTIME · LUBY.
//
// 🔴 HÀNG RÀO DỮ LIỆU THEO TÀI KHOẢN (khác hẳn #228): nguồn thay
//    `zzzzClauseWhere_FilterAbilityOfUser` = `(abn.AccountCode = @strAccountCode) and` khi **KHÔNG** phải SA,
//    `-- Nothing.` khi LÀ SA. Trong khi `Mst_PriceSend_Get` để `-- Nothing.` ở **cả hai** nhánh (bảng giá
//    ai cũng xem được). ⇒ Cùng một khuôn hàm sinh mã nhưng hàng rào quyền KHÁC NHAU, phải đọc từng hàm.
app.MapGet("/api/smsbrandnames", async (AppDbContext db, ITenantContext t, string? accountCode, string? brandName) =>
{
    var qy = db.SmsBrandNames.Where(x => x.OrgId == t.OrgId);

    // Áp đúng hàng rào của nguồn: tài khoản KHÔNG phải SysAdmin thì chỉ thấy brandname của chính nó.
    var code = accountCode?.Trim();
    if (!string.IsNullOrWhiteSpace(code))
    {
        var acc = await db.SmsAccounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AccountCode == code);
        var isSa = acc != null && acc.FlagSysAdmin == "1";
        if (!isSa) qy = qy.Where(x => x.AccountCode == code);
    }
    if (!string.IsNullOrWhiteSpace(brandName)) qy = qy.Where(x => x.BrandName == brandName!.Trim());

    var items = await qy.OrderBy(x => x.BrandName)      // nguồn: order by abn.BrandName asc
        .Select(x => new { x.Id, x.BrandName, x.AccountCode, x.LuDTime, x.LuBy })
        .ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        note = "Không truyền accountCode = xem tất cả (tương ứng tài khoản SysAdmin của nguồn).",
    });
}).RequireAuthorization();

// ⚠️ CỐ Ý không có POST: gateway `SMS.WS/App_Code/WSSMS.cs` chỉ khai `Acc_BrandName_Get` (dòng 621) và
//    `Acc_Balance_Get` (dòng 551) — không có lệnh ghi nào cho hai bảng này. Số dư chỉ đổi qua
