})).RequireAuthorization();

// Ước tính tiền TRƯỚC khi gửi (không ghi gì).
app.MapPost("/api/smssends/estimate", (SmsEstimateDto dto) =>
{
    var content = dto.Content?.Trim() ?? "";
    if (content.Length == 0) return Results.BadRequest(new { error = "Chưa có nội dung SMS." });
    var isAnsi = dto.FlagANSI ?? SmsCost.DetectAnsi(content);
    var pieces = SmsCost.Split(content, isAnsi);
    var perPiece = pieces.Select(x => SmsCost.Parts(x.Length, isAnsi, dto.BatchType, dto.TelCo)).ToList();
    var parts = perPiece.Sum();
    var recipients = Math.Max(1, dto.RecipientCount ?? 1);
    return Results.Ok(new
    {
        contentLength = content.Length, isAnsi, messages = pieces.Count, partsPerRecipient = parts,
        partsPerMessage = perPiece, recipients,
        unitPrice = dto.UnitPrice, totalParts = parts * recipients, totalCost = dto.UnitPrice * parts * recipients,
    });
}).RequireAuthorization();

app.MapGet("/api/smssends", async (AppDbContext db, ITenantContext t, string? mobile, string? status, string? batch) =>
{
    var q = db.SmsSends.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mobile)) q = q.Where(x => x.Mobile.Contains(mobile!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(batch)) q = q.Where(x => x.BatchNo == batch);
    var items = await q.OrderByDescending(x => x.Id).Take(500)
        .Select(x => new { x.BatchNo, x.Mobile, x.SmsType, x.Contents, x.Status, x.InvalidMobile,
            x.FlagANSI, x.TelCo, x.BatchType, x.CostType, x.ProjectCode, x.UnitPrice, x.MsgParts, x.Cost, x.TryCount,
            sendDate = x.SendDate.ToString("yyyy-MM-dd HH:mm") }).ToListAsync();
    return Results.Ok(new { count = items.Count, sent = items.Count(i => i.Status == "F"), invalid = items.Count(i => i.InvalidMobile),
        totalParts = items.Sum(i => i.MsgParts), totalCost = items.Sum(i => i.Cost), items });
}).RequireAuthorization();

// Gửi SMS: nội dung = smsType (mẫu) hoặc content trực tiếp; SĐT = danh sách mobiles và/hoặc toAllCustomers.
app.MapPost("/api/smssends", async (SmsSendDto dto, AppDbContext db, ITenantContext t) =>
{
    var content = dto.Content?.Trim() ?? "";
    string? smsType = null;
    if (!string.IsNullOrWhiteSpace(dto.SmsType))
    {
        smsType = dto.SmsType.Trim().ToUpperInvariant();
        // #299: mẫu là của TỪNG đại lý ⇒ ưu tiên mẫu của đại lý gửi, không có thì lấy mẫu không gán đại lý.
        var dealerSend = dto.DealerCode?.Trim().ToUpperInvariant();
        var tpl = await db.SmsTemplates.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SmsType == smsType
                      && x.FlagActive == "1" && x.DealerCode == dealerSend)
                  ?? await db.SmsTemplates.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SmsType == smsType
                      && x.FlagActive == "1" && x.DealerCode == null);
        if (tpl is null) return Results.BadRequest(new { error = $"Không tìm thấy mẫu SMS đang bật cho loại {smsType}." });
        content = tpl.SmsBody;
    }
    if (string.IsNullOrWhiteSpace(content)) return Results.BadRequest(new { error = "Chưa có nội dung SMS (chọn mẫu hoặc nhập nội dung)." });
    var mobiles = new List<string>(dto.Mobiles ?? new());
    if (dto.ToAllCustomers == true)
    {
        var custMobiles = await db.ServiceCustomers.Where(c => c.OrgId == t.OrgId && c.Mobile != null && c.Mobile != "").Select(c => c.Mobile!).ToListAsync();
        mobiles.AddRange(custMobiles);
    }
    if (mobiles.Count == 0) return Results.BadRequest(new { error = "Chưa có số điện thoại nhận." });
    // 🔴 Luật tiền của nguồn: nội dung dài bị CHIA thành nhiều tin (tối đa 6 phần/tin),
    // và mỗi tin tính tiền theo SỐ PHẦN chứ không phải 1 tin = 1 tiền.
    var batchType = string.IsNullOrWhiteSpace(dto.BatchType) ? "CSKH" : dto.BatchType!.Trim().ToUpperInvariant();
    if (batchType != "CSKH" && batchType != "QC")
        return Results.BadRequest(new { error = "Loại lô không hợp lệ (chỉ CSKH hoặc QC)." });
    var costType = string.IsNullOrWhiteSpace(dto.CostType) ? "NM" : dto.CostType!.Trim().ToUpperInvariant();
    if (costType != "NM" && costType != "BN")
        return Results.BadRequest(new { error = "Loại chi phí không hợp lệ (chỉ NM hoặc BN)." });
    var telCo = string.IsNullOrWhiteSpace(dto.TelCo) ? null : dto.TelCo!.Trim().ToUpperInvariant();
    if (telCo != null && telCo != "VIETTEL" && telCo != "MOBIFONE" && telCo != "VINAPHONE" && telCo != "VIETNAMOBILE")
        return Results.BadRequest(new { error = "Nhà mạng không hợp lệ." });
    if (dto.UnitPrice < 0) return Results.BadRequest(new { error = "Đơn giá không được âm." });
    var isAnsi = dto.FlagANSI ?? SmsCost.DetectAnsi(content);
    var no = "SMS" + DateTime.Now.ToString("yyMMddHHmmss");

    // 🔴 #229 Ngữ cảnh người nhận: nguồn lưu 7 cặp (A10..A16) và thay biến nội dung THEO TỪNG NGƯỜI
    //    (`SmsUtil.RefineContentSmsSend(content, CusName, PlateNo)` — SmsOutService.cs:146).
    //    ⇒ tra khách theo số ĐT một lần, rồi lấy xe đầu tiên của khách để có biển số.
    var ctxRows = await (from c in db.ServiceCustomers.Where(x => x.OrgId == t.OrgId && x.Mobile != null && x.Mobile != "")
                         join car in db.ServiceCars.Where(x => x.OrgId == t.OrgId) on c.CusCode equals car.CusID into gj
                         from car in gj.DefaultIfEmpty()
                         select new { c.Mobile, c.CusCode, c.CusName, c.Address,
                                      carId = car != null ? car.FrameNo : null,
                                      plateNo = car != null ? car.PlateNo : null,
                                      tradeMark = car != null ? car.TradeMark : null,
                                      modelCode = car != null ? car.ModelCode : null }).ToListAsync();
    var ctx = new Dictionary<string, SmsCtx>();
    foreach (var r in ctxRows)
    {
        var key = StdPhoneVn(r.Mobile);
        if (key is not null && !ctx.ContainsKey(key))
            ctx[key] = new SmsCtx(r.CusCode, r.CusName, r.Address, r.carId, r.plateNo, r.tradeMark, r.modelCode);
    }

    // 🔴 #229 ĐẦU LÔ: nguồn LUÔN tạo 1 dòng `Sms_Batch` cùng lúc với các dòng gửi (RefineSave).
    //    `EffectStatus` = "P"; `Remark` bị SMS_Batch_Send ghi đè bằng hằng "BrandName" (SmsOutService.cs:99).
    //    `ContentsTemplate` ghép bằng "|": <loại người gửi>[|<loại báo giá>|<nội dung>].
    var senderKind = string.IsNullOrWhiteSpace(dto.SenderKind) ? "BrandName" : dto.SenderKind!.Trim();
    var batch = new SmsBatch
    {
        OrgId = t.OrgId, BatchId = no, AccountCode = dto.AccountCode, BatchType = batchType,
        ContentsTemplate = string.IsNullOrWhiteSpace(dto.SmsType) ? senderKind : $"{senderKind}|{smsType}|{content}",
        EffectDTime = dto.EffectDTime ?? DateTime.Now,   // mốc chọn giá hiệu lực (#228), KHÔNG phải ngày gửi
        EffectStatus = "P",
        Remark = "BrandName",
        CreatedBy = dto.CreatedBy,
    };
    db.SmsBatches.Add(batch);

    int queued = 0, invalid = 0, seqSend = 0;
    var invalids = new List<string>();
    var seen = new HashSet<string>();
    var msgPerRecipient = new List<int>();
    foreach (var m in mobiles)
    {
        var std = StdPhoneVn(m);
        if (std is null)
        {
            // Số sai định dạng: nguồn coi là lô lỗi (Reject), kèm cờ riêng để biết lỗi do SỐ chứ không do gửi.
            invalid++; invalids.Add(m);
            db.SmsSends.Add(new SmsSend { OrgId = t.OrgId, BatchNo = no, Mobile = m ?? "", SmsType = smsType, Contents = content, Status = "R", InvalidMobile = true,
                FlagANSI = isAnsi, TelCo = telCo, BatchType = batchType, CostType = costType, ProjectCode = dto.ProjectCode });
            continue;
        }
        if (!seen.Add(std)) continue; // bỏ trùng số trong lô

        ctx.TryGetValue(std, out var who);
        // 🔴 THAY BIẾN TRƯỚC, CHIA PHẦN SAU: thay {@FullName}/{@PlateNo} làm ĐỔI ĐỘ DÀI nội dung,
        //    mà độ dài mới là thứ quyết định số phần tin ⇒ quyết định TIỀN. Port cũ chia phần trên
        //    nội dung MẪU (còn nguyên biến) nên tính sai tiền khi tên/biển số dài.
        var body = RefineSmsContent(content, who?.CusName, who?.PlateNo);
        var pieces = SmsCost.Split(body, isAnsi);
        msgPerRecipient.Add(pieces.Count);

        // ⚠️ Nguồn tạo lô ở trạng thái "P" (chờ gửi) rồi mới gửi bất đồng bộ — KHÔNG đánh dấu đã gửi ngay.
        foreach (var piece in pieces)
        {
            var parts = SmsCost.Parts(piece.Length, isAnsi, batchType, telCo);
            db.SmsSends.Add(new SmsSend
            {
                OrgId = t.OrgId, BatchNo = no, Mobile = std, SmsType = smsType, Contents = piece, Status = "P",
                FlagANSI = isAnsi, TelCo = telCo, BatchType = batchType, CostType = costType,
                ProjectCode = dto.ProjectCode, UnitPrice = dto.UnitPrice,
                MsgParts = parts, Cost = dto.UnitPrice * parts,
                // SendId tuần tự trong lô — nguồn dùng CUtils.TidNext(batchId, ref seq).
                SendId = $"{no}-{++seqSend:D5}",
                SupplierPhoneNo = dto.SupplierPhoneNo,
                // Gửi bằng đầu số ⇒ nguồn ghi chuỗi RỖNG (không phải null) cho BranchName.
                BranchName = senderKind == "BrandName" ? dto.BrandName : "",
                FlagReply = "0",
                CusID = who?.CusCode, CusName = who?.CusName,
                Address = who?.Address, CarID = who?.CarId,
                PlateNo = who?.PlateNo,
                // A15 của nguồn ghép "TradeMarkCode|ModelName"; chỉ ghi khi có ít nhất một vế.
                TradeMarkModel = who is null || (who.TradeMark is null && who.ModelCode is null)
                                 ? null : $"{who.TradeMark}|{who.ModelCode}",
                SendType = smsType,
            });
            queued++;
        }
    }
    // Tiền ước tính của lô = tổng tiền các dòng chờ gửi (nguồn: Sum(UnitPrice * MyPartCount)).
    await db.SaveChangesAsync();
    var totalParts = await db.SmsSends.Where(x => x.OrgId == t.OrgId && x.BatchNo == no && !x.InvalidMobile).SumAsync(x => x.MsgParts);
    batch.CostInit = dto.UnitPrice * totalParts;
    await db.SaveChangesAsync();
    return Results.Ok(new { batchNo = no, queued, invalid, invalids, contentLength = content.Length,
        isAnsi, messagesPerRecipient = msgPerRecipient.Count == 0 ? 0 : msgPerRecipient.Max(),
        totalParts, totalCost = batch.CostInit,
        batch = new { batch.BatchId, batch.BatchType, batch.ContentsTemplate, batch.EffectDTime, batch.EffectStatus, batch.CostInit } });
}).RequireAuthorization();

// 🔴 Trạng thái gửi SMS theo ĐÚNG nguồn (TConst.SmsStage) — port cũ chỉ có 2/6 (Sent|Invalid).
var smsStageNames = new Dictionary<string, string>
{
    ["N"] = "Null",
    ["P"] = "Chờ gửi",
    ["G"] = "Đang gửi",
    ["C"] = "Huỷ",
    ["F"] = "Gửi xong",
    ["R"] = "Gửi lỗi / từ chối",
};

// Ánh xạ giá trị port CŨ → mã nguồn, giữ dữ liệu đã tạo đọc được.
var smsLegacyStatusMap = new Dictionary<string, string> { ["Sent"] = "F", ["Invalid"] = "R" };

app.MapGet("/api/smssends/statuses", () => Results.Ok(new
{
    statuses = smsStageNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    legacyMap = smsLegacyStatusMap.Select(kv => new { legacy = kv.Key, code = kv.Value }),
    note = "Nguồn tạo lô ở P (chờ gửi) rồi gửi bất đồng bộ; kết thúc F (xong) hoặc R (lỗi)."
})).RequireAuthorization();

// Danh sách ĐẦU LÔ (Sms_Batch) — kèm tiền thực tế tính lại từ các dòng đã gửi xong.
app.MapGet("/api/smsbatches", async (AppDbContext db, ITenantContext t, string? effectStatus, string? batchType) =>
{
    var qy = db.SmsBatches.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(effectStatus)) qy = qy.Where(x => x.EffectStatus == effectStatus!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(batchType)) qy = qy.Where(x => x.BatchType == batchType!.Trim().ToUpperInvariant());

    var items = await qy.OrderByDescending(x => x.CreatedDTime).Take(500)
        .Select(x => new { x.BatchId, x.AccountCode, x.BatchType, x.ContentsTemplate, x.EffectDTime,
                           x.EffectStatus, x.Remark, x.CostInit, x.CostActual, x.CreatedDTime, x.CreatedBy,
                           x.CancelDTime, x.CancelBy,
                           // MYCOUNT_* của nguồn là cột TÍNH, không lưu — đếm tại chỗ.
                           countPending = db.SmsSends.Count(s => s.OrgId == t.OrgId && s.BatchNo == x.BatchId && s.Status == "P"),
                           countProgress = db.SmsSends.Count(s => s.OrgId == t.OrgId && s.BatchNo == x.BatchId && s.Status == "G"),
                           countFinish = db.SmsSends.Count(s => s.OrgId == t.OrgId && s.BatchNo == x.BatchId && s.Status == "F"),
                           countReject = db.SmsSends.Count(s => s.OrgId == t.OrgId && s.BatchNo == x.BatchId && s.Status == "R") })
        .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Cập nhật kết quả gửi của cả lô (bộ gửi SMS gọi lại sau khi xử lý xong).
app.MapPost("/api/smssends/{batchNo}/status", async (
    string batchNo, SmsBatchStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    batchNo = batchNo.Trim().ToUpperInvariant();
    var target = (dto.ToStatus ?? "").Trim().ToUpperInvariant();
    if (!smsStageNames.ContainsKey(target))
        return Results.BadRequest(new { error = $"Trạng thái hợp lệ: {string.Join(", ", smsStageNames.Keys)}" });

    var rows = await db.SmsSends.Where(x => x.OrgId == t.OrgId && x.BatchNo == batchNo).ToListAsync();
    if (rows.Count == 0) return Results.NotFound(new { batchNo });

    var updated = 0;
    var exceededTry = 0;   // #353: số dòng bị bỏ qua vì vượt hạn mức thử lại
    foreach (var row in rows)
    {
        var current = smsLegacyStatusMap.TryGetValue(row.Status, out var mapped) ? mapped : row.Status;
        // Số sai định dạng đã chốt lỗi từ đầu — không đổi theo kết quả gửi của lô.
        if (row.InvalidMobile) continue;
        // Đã kết thúc (F/C) thì không đổi nữa.
        if (current is "F" or "C") continue;

        // ===== 🔴 #353 BỘ ĐẾM SỐ LẦN THỬ GỬI — khai mà chưa nối =====
        // Nguồn `BizSMS.SMSBackground.cs` (hệ `SMS.V10`, **CHỈ có trên máy 150** — đúng cảnh báo 3B):
        //   chọn tin để gửi:  `and (t.TryCount <= @nTryCountMax)`  (`:450`, `:470`, `:538`)
        //   mỗi lần thử:      `, (t.TryCount + 1) TryCount`        (`:829`, `:1019`, `:1337`, `:1528`)
        // ⚠️ Ở nguồn bộ đếm nằm trên bảng **`Tmp_SupplierSmsStatus`** (trạng thái phía NHÀ CUNG CẤP),
        //   KHÔNG phải `Sms_Send`. MiniHTC gộp hai bảng làm một ⇒ cột `TryCount` nằm trên `SmsSend`.
        //   Gộp thì được, nhưng bộ đếm **chưa bao giờ được tăng** và `TryCountMax` (đã lộ ra ở
        //   `/api/smssends/costinfo`) **chưa bao giờ được dùng làm chặn** ⇒ tin lỗi có thể thử lại vô hạn
        //   mà sổ vẫn ghi 0 lần. Cùng loại "cơ chế khai mà không nối" với vế đóng HCC ở #351.
        //
        // 🔴 Chỉ đếm lần thử THẬT SỰ GỬI: chuyển sang `G` (đang gửi) hoặc `F` (xong) là một lượt thử;
        //   `C` (huỷ) / `R` (từ chối) là quyết định hành chính, không phải một lần gửi.
        if (target is "G" or "F")
        {
            if (row.TryCount > SmsCost.TryCountMax)
            {
                exceededTry++;
                continue;   // vượt hạn mức thử ⇒ bộ gửi của nguồn KHÔNG chọn nữa
            }
            row.TryCount += 1;
        }

        row.Status = target; updated++;

        // 🔴 #231 CHỐT TIỀN THỰC khi lô gửi xong: nguồn đặt `ss.CostActual = t.UnitPrice * t.MyPartCount`
        //    (BizSMS.SMS.cs:262) — trước đó `CostActual` vẫn là 0, chỉ có `CostInit` (ở đây là `Cost`).
        //    Lô bị từ chối/huỷ thì KHÔNG chốt tiền.
        if (target == "F") row.CostActual = row.UnitPrice * row.MsgParts;
        else if (target is "C" or "R") row.CostActual = 0m;
    }

    // Đầu lô: EffectStatus đi theo kết quả, và CostActual của lô = tổng tiền thực các dòng.
    var hdr = await db.SmsBatches.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BatchId == batchNo);
    if (hdr is not null)
    {
        hdr.EffectStatus = target;
        hdr.CostActual = rows.Sum(x => x.CostActual);
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { batchNo, status = target, statusName = smsStageNames[target], updated, total = rows.Count,
                            costActual = hdr?.CostActual,
                            // #353: so dong bi bo qua vi vuot han muc thu lai (TryCountMax).
                            exceededTry,
                            tryCountMax = SmsCost.TryCountMax });
}).RequireAuthorization();

// ===== 🔴 #231 HUỶ LÔ TIN NHẮN — `Sms_Batch_Cancel` (SMS.V10/SMS.Biz/BizSMS.SMS.cs:1464 →
//        `mySms_Batch_Cancel_Exec` :101). Màn gốc: `Views/SMS/FrmSMSMng.cs:388` `btnCancelSMS_Click`
//        → `SmsOutService.SMS_Batch_Cancel(batchId, userCode)` (SmsOutService.cs:45).
// BƯỚC 3B: hệ `SMS.V10` CHỈ có trên máy 150; `BizSMS.SMS.cs` md5 `1d5bc4b2` (2717 dòng).
//
// NĂM luật của nguồn, port đủ:
//  1. 🔴 GUARD TRẠNG THÁI: `mySms_Batch_Check(..., strEffectStatusListToCheck = TConst.Stage.Pending)`
//     ⇒ **chỉ huỷ được lô đang "P" (chờ gửi)**. Lô đang gửi/đã xong/đã huỷ đều bị chặn.
//  2. 🔴 GUARD QUYỀN: không phải SysAdmin thì `AccountCode` của LÔ phải trùng tài khoản gọi,
//     khác ⇒ `Sms_Batch_Cancel_AccessDeny`.
//  3. Đầu lô: `EffectStatus = 'C'` + `CancelDTime` + `CancelBy`.
//  4. 🔴 TIỀN HOÀN = `Sum(ss.CostActual)` — tiền **THỰC đã trừ**, KHÔNG phải `CostInit`; sau đó các dòng gửi
//     bị đặt `SendStatus = 'C'` và `CostActual = 0.0`. Lô còn ở "P" thì thường CostActual = 0 ⇒ hoàn 0.
//  5. 🔴 Chỉ ghi giao dịch hoàn khi `dblCostRefund > 0`, và gọi `myAcc_Transaction_Exec` với
//     `bCheckDebitOverdraft = false` (nạp tiền thì KHÔNG kiểm thấu chi — xem #230),
//     `TRefType = TConst.TransactionRefType.SmsCancel`, `TRefCode = BatchId`, `Remark = "BatchId={id}"`.
app.MapPost("/api/smsbatches/{batchId}/cancel", async (
    string batchId, SmsBatchCancelDto dto, AppDbContext db, ITenantContext t) =>
{
    batchId = batchId.Trim();
    var hdr = await db.SmsBatches.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BatchId == batchId);
    if (hdr is null) return Results.NotFound(new { batchId });

    // (1) chỉ huỷ được lô đang chờ gửi
    if (hdr.EffectStatus != "P")
        return Results.BadRequest(new { error = $"Chỉ huỷ được lô đang chờ gửi (lô này đang \"{hdr.EffectStatus}\").",
                                        effectStatus = hdr.EffectStatus });

    // (2) hàng rào quyền theo tài khoản sở hữu lô
    var caller = dto.AccountCode?.Trim();
    if (!string.IsNullOrWhiteSpace(caller))
    {
        var acc = await db.SmsAccounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AccountCode == caller);
        var isSa = acc != null && acc.FlagSysAdmin == "1";
        if (!isSa && !string.Equals(hdr.AccountCode, caller, StringComparison.OrdinalIgnoreCase))
            return Results.Json(new { error = "Không có quyền huỷ lô của tài khoản khác.",
                                      accountCodeOwner = hdr.AccountCode }, statusCode: 403);
    }

    var sends = await db.SmsSends.Where(x => x.OrgId == t.OrgId && x.BatchNo == batchId).ToListAsync();

    // (4) tiền hoàn lấy từ CostActual (tiền THỰC), tính TRƯỚC khi đưa về 0
    var refund = sends.Sum(x => x.CostActual);
    foreach (var s in sends) { s.Status = "C"; s.CostActual = 0m; }

    // (3) đầu lô
    hdr.EffectStatus = "C";
    hdr.CancelDTime = DateTime.Now;
    hdr.CancelBy = dto.PerformBy;
    hdr.CostActual = 0m;

    // (5) hoàn tiền — chỉ khi > 0, và KHÔNG kiểm thấu chi vì đây là chiều NẠP
    decimal? balanceAfter = null;
    if (refund > 0 && !string.IsNullOrWhiteSpace(hdr.AccountCode))
    {
        var owner = await db.SmsAccounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AccountCode == hdr.AccountCode);
        if (owner is not null)
        {
            owner.Balance += refund;
            balanceAfter = owner.Balance;
            db.SmsAccountTxs.Add(new SmsAccountTx
            {
                OrgId = t.OrgId, SmsAccountId = owner.Id,
                TRefType = "SmsCancel",          // TConst.TransactionRefType.SmsCancel
                Value = refund, BalanceAfter = owner.Balance,
                Note = $"BatchId={batchId}",     // đúng Remark của nguồn
            });
        }
    }

    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        batchId, effectStatus = hdr.EffectStatus, cancelDTime = hdr.CancelDTime, cancelBy = hdr.CancelBy,
        cancelledSends = sends.Count, refund, balanceAfter,
        note = "Tiền hoàn lấy từ CostActual của các dòng gửi; lô còn ở \"P\" thì CostActual thường = 0.",
    });
}).RequireAuthorization();

// ===== Gửi email + log (EmailSend — port 1:1 FrmSendEmail, TCMotor) — tích hợp EmailTemplate + ServiceCustomer =====
// Kiểm tra định dạng email cơ bản (giống ràng buộc gửi mail WinForm): có @ + tên miền có dấu chấm.
// ===== 🔴 #251 REGEX EMAIL — port ĐÚNG biểu thức của nguồn, thay cho suy luận cũ =====
// Nguồn: `Views/SendEmail/FrmSendEmail.cs:379` (và :741 cho tô màu ô lỗi) — md5 `75cbc7ea`, KHỚP 2 máy:
//     `new Regex(@"\w+([-+.']\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*")`
//   `checkMailTo()` đếm số dòng có `IsMatch == false`; >0 ⇒ báo
//   "Địa chỉ mail không hợp lệ. Đề nghị kiểm tra lại."
//
// 🔴 ĐÍNH CHÍNH BẢN ĐỒ #249: tôi gộp 2 màn SendEmail vào danh sách "dùng regex của lớp cha `FrmMdiBase`".
//    SAI — hai màn này khai **regex CỤC BỘ** và **NGƯỢC NGHĨA**:
//      · regex lớp cha `[^a-zA-Z0-9._-]`: `IsMatch == true` ⇒ **CÓ ký tự đặc biệt** ⇒ LỖI.
//      · regex email ở đây:             `IsMatch == true` ⇒ **HỢP LỆ**.
//    Vá theo bản đồ mà không đọc thì sẽ **chặn sạch mọi email** (email luôn chứa `@` nên luôn khớp
//    regex lớp cha).
//
// 🔴 BA khác biệt so với hàm suy luận cũ của tôi — đều theo nguồn:
//  1. Nguồn dùng `IsMatch` **KHÔNG anchor** (`^…$`) ⇒ **khớp một phần là đủ**: chuỗi `"abc def@x.com"`
//     vẫn hợp lệ. Hàm cũ chặn vì có khoảng trắng ⇒ chặt hơn nguồn.
//  2. Phần trước `@` cho phép `- + . '` (dấu nháy đơn) — hàm cũ không xét.
//  3. Tên miền bắt buộc có ít nhất một dấu chấm — điểm này hàm cũ làm đúng.
static bool IsValidEmail(string? raw)
{
    if (string.IsNullOrWhiteSpace(raw)) return false;
    // giữ NGUYÊN biểu thức của nguồn, kể cả việc không anchor
    return System.Text.RegularExpressions.Regex.IsMatch(
        raw, @"\w+([-+.']\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*");
}

// 🔴 #300 Nhãn `TypeEmail` có HAI biến thể trong cùng file nguồn:
//   `SendMail.cs:1300/1540/1815` (+2) — **không `else`** ⇒ mã lạ ra nhãn NULL;
//   `SendMail.cs:5315` và `:5502`     — **`else N'Không xác định'`** ⇒ mã lạ ra "Không xác định".
//   Hai màn tra cùng cột mà một bên để trống, một bên ghi "Không xác định". Hàm này theo bản CÓ else vì
//   nó là bản dùng cho hàng đợi tự động (`Temp_Email_Get`/`_Get_Detail`).
static string EmailTypeLabelAuto(string? v) => v switch
{
    "1" => "Thông báo chiến dịch", "2" => "Nhắc bảo dưỡng", "3" => "Mừng sinh nhật",
    "4" => "Hẹn khách hàng", "5" => "Khuyến mại", "6" => "Thông báo sửa xong", "7" => "Khác",
    _ => "Không xác định",
};

app.MapGet("/api/emailsends", async (AppDbContext db, ITenantContext t, string? email, string? status, string? batch) =>
{
    var q = db.EmailSends.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(email)) q = q.Where(x => x.Email.Contains(email!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(batch)) q = q.Where(x => x.BatchNo == batch);
    var items = await q.OrderByDescending(x => x.Id).Take(500)
        .Select(x => new { x.BatchNo, x.Email, x.EmailType, x.Subject, x.Status, x.InvalidEmail,
            x.FromAddress, x.CusId, x.IsAuto, x.DealerCode, x.FileAttachment, x.UserName, x.Note,
            sendDate = x.SendDate.ToString("yyyy-MM-dd HH:mm") }).ToListAsync();
    return Results.Ok(new { count = items.Count, sent = items.Count(i => i.Status == "1"), pending = items.Count(i => i.Status == "0" && !i.InvalidEmail), invalid = items.Count(i => i.InvalidEmail), items });
}).RequireAuthorization();

// Gửi email: tiêu đề/nội dung = emailType (mẫu) hoặc subject+body trực tiếp; người nhận = emails và/hoặc toAllCustomers.
app.MapPost("/api/emailsends", async (EmailSendDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var subject = dto.Subject?.Trim() ?? "";
    var body = dto.Body?.Trim() ?? "";
    string? emailType = null;
    if (!string.IsNullOrWhiteSpace(dto.EmailType))
    {
        emailType = dto.EmailType.Trim().ToUpperInvariant();
        var tpl = await db.EmailTemplates.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TempType == emailType && x.FlagActive == "1");
        if (tpl is null) return Results.BadRequest(new { error = $"Không tìm thấy mẫu email đang bật cho loại {emailType}." });
        subject = tpl.TempSubject ?? ""; body = tpl.TempBody;
    }
    if (string.IsNullOrWhiteSpace(subject)) return Results.BadRequest(new { error = "Chưa có tiêu đề email (chọn mẫu hoặc nhập tiêu đề)." });
    if (string.IsNullOrWhiteSpace(body)) return Results.BadRequest(new { error = "Chưa có nội dung email." });
    var emails = new List<string>(dto.Emails ?? new());
    if (dto.ToAllCustomers == true)
    {
        var custEmails = await db.ServiceCustomers.Where(c => c.OrgId == t.OrgId && c.Email != null && c.Email != "").Select(c => c.Email!).ToListAsync();
        emails.AddRange(custEmails);
    }
    if (emails.Count == 0) return Results.BadRequest(new { error = "Chưa có địa chỉ email nhận." });
    var no = "EML" + DateTime.Now.ToString("yyMMddHHmmss");
    // 🔴 Nguồn ghi HEADER LÔ (Email_BatchSendEmail) trước, mang ngày hiệu lực / người gửi / file đính kèm cả lô.
    var whoEB = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var nowEB = DateTime.Now;
    db.EmailBatches.Add(new EmailBatch
    {
        OrgId = t.OrgId, BatchNo = no, DealerCode = dto.DealerCode,
        EffectDate = dto.EffectDate ?? DateTime.Now, SendBy = dto.SendBy, AttachmentName = dto.AttachmentName,
        // #143 parity DMS40_Email_BatchSendEmail: 6 cột nguồn ghi mà port cũ thiếu.
        ConfigCode = dto.ConfigCode, TEmailCode = dto.TEmailCode, WSPath = dto.WSPath,
        BatchStatus = "P", LogLUDateTime = nowEB, LogLUBy = whoEB,
    });
    // #143: CC / BCC / file đính kèm — ba bảng con nguồn có mà port cũ THIẾU HẲN.
    // ⚠️ CC ghi vào BẢNG CC. Nguồn có một biến HỎNG `zzzzClauseInsertDMS40_Email_BatchSendEmailCC_zSave`
    //    (thiếu dấu gạch dưới sau "Insert") ghi CC vào bảng **To**; biến đó KHÔNG được ghép vào câu lệnh
    //    cuối nên là BIẾN CHẾT — bộ cột ở đây lấy theo `_Job_SaveX` (bản sạch).
    foreach (var e in (dto.Cc ?? new List<string>()).Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct())
        db.EmailBatchCcs.Add(new EmailBatchCc { OrgId = t.OrgId, BatchNo = no, EmailCode = e, BatchStatusCC = "P", LogLUDateTime = nowEB, LogLUBy = whoEB });
    foreach (var e in (dto.Bcc ?? new List<string>()).Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct())
        db.EmailBatchBccs.Add(new EmailBatchBcc { OrgId = t.OrgId, BatchNo = no, EmailCode = e, BatchStatusBCC = "P", LogLUDateTime = nowEB, LogLUBy = whoEB });
    foreach (var f in (dto.Files ?? new List<string>()).Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct())
        db.EmailBatchFileAttaches.Add(new EmailBatchFileAttach { OrgId = t.OrgId, BatchNo = no, FilePath = f, BatchStatusFA = "P", LogLUDateTime = nowEB, LogLUBy = whoEB });
    int queued = 0, invalid = 0;
    var invalids = new List<string>();
    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var e in emails)
    {
        // #251: thông điệp của nguồn khi có dòng email sai — "Địa chỉ mail không hợp lệ. Đề nghị kiểm tra lại."
        //   (nguồn ĐẾM số dòng sai rồi báo MỘT lần; port vẫn ghi từng dòng lỗi để tra được dòng nào).
        if (!IsValidEmail(e)) { invalid++; invalids.Add(e); db.EmailSends.Add(new EmailSend { OrgId = t.OrgId, BatchNo = no, Email = e ?? "", EmailType = emailType,
            Subject = subject, Body = body, Status = "0", InvalidEmail = true,
            FromAddress = dto.FromAddress, DealerCode = dto.DealerCode, UserName = dto.SendBy,
            IsAuto = dto.IsAuto == true ? "1" : "0", Note = "Địa chỉ email sai định dạng." }); continue; }
        var std = e.Trim();
        if (!seen.Add(std)) continue; // bỏ trùng email trong lô
        // ⚠️ Xếp vào hàng đợi ở "0" (chưa gửi) — nguồn chỉ cập nhật "1" SAU KHI gửi xong.
        db.EmailSends.Add(new EmailSend { OrgId = t.OrgId, BatchNo = no, Email = std, EmailType = emailType,
            Subject = subject, Body = body, Status = "0",
            FromAddress = dto.FromAddress, CusId = null, DealerCode = dto.DealerCode, UserName = dto.SendBy,
            IsAuto = dto.IsAuto == true ? "1" : "0", FileAttachment = dto.AttachmentName });
        queued++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { batchNo = no, queued, invalid, invalids, subject, status = "0",
        note = "Lô mới ở trạng thái chờ gửi — gọi POST /api/emailsends/{batchNo}/status khi gửi xong." });
}).RequireAuthorization();

// 🔴 Bộ gửi cập nhật kết quả lô email — port cũ KHÔNG có bước này (đánh dấu "đã gửi" ngay lúc tạo).
// Nguồn cập nhật cờ "1" sau khi gửi xong (BizCarSv.SendMail.cs:616).
app.MapPost("/api/emailsends/{batchNo}/status", async (
    string batchNo, EmailBatchStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    var no = batchNo.Trim();
    var rows = await db.EmailSends.Where(x => x.OrgId == t.OrgId && x.BatchNo == no && !x.InvalidEmail).ToListAsync();
    if (rows.Count == 0) return Results.NotFound(new { batchNo = no });
    var to = (dto.Status ?? "").Trim();
    if (to != "0" && to != "1")
        return Results.BadRequest(new { error = "Trạng thái chỉ nhận '0' (chưa gửi) hoặc '1' (đã gửi)." });

    var changed = 0;
    foreach (var r in rows)
    {
        // Không đụng dòng đã chốt "đã gửi" — tránh ghi đè kết quả.
        if (r.Status == "1") continue;
        r.Status = to;
        if (!string.IsNullOrWhiteSpace(dto.Note)) r.Note = dto.Note;
        if (to == "1") r.SendDate = DateTime.Now;
        changed++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { batchNo = no, status = to, changed, skippedAlreadySent = rows.Count - changed });
}).RequireAuthorization();

// 🔴 #300 BA trạng thái, không phải hai — theo báo cáo LIVE `Email_ReportCusReceivedEmail` (:4630).
//   Khối **KHÔNG có `else`** ⇒ whitelist: mã lạ / NULL cho ra nhãn NULL (ô trống), KHÔNG gộp về "Lỗi".
var emailSendStatusNames = new Dictionary<string, string>
{
    ["0"] = "Chưa gửi", ["1"] = "Thành công", ["2"] = "Thất bại",
};
static string? EmailSendStatusLabel(Dictionary<string, string> m, string? v)
    => v is not null && m.TryGetValue(v, out var n) ? n : null;

// 🔴 #300 Bảng mã của `Email_SendEmailAutoTemp` — **KHÁC HẲN**: số, có mã ÂM, và có `else`.
//   `Temp_Email_Get_Detail` (:5497) viết `when 1` / `when -1` / `when 0` **không nháy**, rồi `else N'Lỗi'`.
//   ⇒ blacklist: NULL và mọi mã lạ hiện **"Lỗi"**, không phải ô trống. Hai bảng email, hai từ vựng.
var emailAutoTempStatusNames = new Dictionary<string, string>
{
    ["1"] = "Thành công", ["-1"] = "Thất bại", ["0"] = "Chưa gửi",
};
static string EmailAutoTempStatusLabel(Dictionary<string, string> m, string? v)
    => v is not null && m.TryGetValue(v, out var n) ? n : "Lỗi";

app.MapGet("/api/emailsends/statuses", () => Results.Ok(new
{
    statuses = emailSendStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Ba trạng thái theo báo cáo LIVE. Mã lạ/NULL ⇒ nhãn rỗng (nguồn KHÔNG có nhánh else). "
         + "Địa chỉ sai định dạng nằm ở cờ riêng invalidEmail.",
    autoTempStatuses = emailAutoTempStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    autoTempNote = "Bảng Email_SendEmailAutoTemp dùng SỐ (có mã -1) và CÓ nhánh else ⇒ mã lạ/NULL hiện \"Lỗi\".",
})).RequireAuthorization();

// ===== #300 HÀNG ĐỢI NGƯỜI NHẬN của lô gửi tự động (Email_SendEmailAutoTemp) =====
app.MapGet("/api/emailautotemps", async (AppDbContext db, ITenantContext t,
    string? batchId, string? dealer, string? typeEmail, string? status) =>
{
    var qy = db.EmailSendAutoTemps.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(batchId)) qy = qy.Where(x => x.BatchId == batchId);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(typeEmail)) qy = qy.Where(x => x.TypeEmail == typeEmail);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.Status == status);
    var rows = await qy.OrderByDescending(x => x.Id).Take(500).ToListAsync();
    var items = rows.Select(x => new
    {
        autoTempId = x.Id, x.BatchId, x.DealerCode, x.CusID, x.CusEmail, x.Subject,
        x.TypeEmail, newTypeEmail = EmailTypeLabelAuto(x.TypeEmail),
        x.ConfigAutoID, x.SendType, x.Remark, x.CurrentDate, x.Status,
        statusText = EmailAutoTempStatusLabel(emailAutoTempStatusNames, x.Status),
        createdDate = x.CreatedDate,
    }).ToList();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/emailautotemps", async (EmailAutoTempDto dto, AppDbContext db, ITenantContext t) =>
{
    // ⚠️ Nguồn `_Create` KHÔNG bắt buộc trường nào — rỗng thì ghi DBNull. Không tự thêm chặn (luật #299).
    var r = new EmailSendAutoTemp
    {
        OrgId = t.OrgId, BatchId = dto.BatchId,
        DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(),
        CusID = dto.CusID, CusEmail = dto.CusEmail, Subject = dto.Subject, Body = dto.Body,
        CurrentDate = dto.CurrentDate, TypeEmail = dto.TypeEmail, ConfigAutoID = dto.ConfigAutoID,
        Status = dto.Status, SendType = dto.SendType, Remark = dto.Remark,
    };
    db.EmailSendAutoTemps.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { autoTempId = r.Id, r.BatchId, r.Status,
        statusText = EmailAutoTempStatusLabel(emailAutoTempStatusNames, r.Status) });
}).RequireAuthorization();

// #300 `_Update`: nguồn đưa ĐÚNG 10 cột vào `alEffectiveColumn` (:4214-4223) — **`BatchId` và `Remark`
//   KHÔNG nằm trong đó** ⇒ sửa dòng KHÔNG đổi được lô, cũng không ghi đè được ghi chú.
app.MapPut("/api/emailautotemps/{id:long}", async (long id, EmailAutoTempDto dto, AppDbContext db, ITenantContext t) =>
{
    var r = await db.EmailSendAutoTemps.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (r is null) return Results.NotFound(new { autoTempId = id });
    r.DealerCode = dto.DealerCode?.Trim().ToUpperInvariant();
    r.CusID = dto.CusID; r.Body = dto.Body; r.Subject = dto.Subject;
    r.CurrentDate = dto.CurrentDate; r.TypeEmail = dto.TypeEmail; r.ConfigAutoID = dto.ConfigAutoID;
    r.Status = dto.Status; r.CusEmail = dto.CusEmail; r.SendType = dto.SendType;
    await db.SaveChangesAsync();
    return Results.Ok(new { autoTempId = r.Id, r.Status,
        statusText = EmailAutoTempStatusLabel(emailAutoTempStatusNames, r.Status),
        note = "BatchId và Remark KHÔNG sửa được — đúng alEffectiveColumn của nguồn." });
}).RequireAuthorization();

// ===== #300 TỔNG HỢP MỘT LÔ — nguồn `Temp_Email_Get` (`SendMail.cs:5307-5327`) =====
// 🔴 Nguồn trả `0 SoLuongLoi` — **hằng số 0 gõ thẳng vào SQL**, nên cột "số lượng lỗi" trên màn
//   **luôn bằng 0** dù có bao nhiêu mail hỏng. Tác giả **không giải thích** ⇒ theo lệ #272/#275 KHÔNG bắt
//   chước cái sai câm: ở đây đếm THẬT từ `EmailSend.Status == "2"` và trả kèm `errorCountSourceAlwaysZero`
//   để ai đối chiếu với WinForm biết vì sao hai bên lệch.
app.MapGet("/api/emailbatches/{batchId}/summary", async (string batchId, AppDbContext db, ITenantContext t) =>
{
    var recipients = await db.EmailSendAutoTemps.CountAsync(x => x.OrgId == t.OrgId && x.BatchId == batchId);
    var sends = await db.EmailSends.Where(x => x.OrgId == t.OrgId && x.BatchNo == batchId).ToListAsync();
    var failed = sends.Count(x => x.Status == "2");
    return Results.Ok(new
    {
        batchId,
        soLuongKhachHang = recipients,
        soLuongDaGui = sends.Count,
        // Nguồn: recipients − sends (KHÔNG xét trạng thái) ⇒ giữ đúng phép trừ đó.
        soLuongChuaGui = recipients - sends.Count,
        soLuongLoi = failed,
        errorCountSourceAlwaysZero = true,
        note = "Nguồn gõ cứng SoLuongLoi = 0; ở đây đếm thật theo EmailSend.Status = '2' (Thất bại).",
    });
}).RequireAuthorization();

// ===== #153 parity: ĐỊNH MỨC TỒN TỐI THIỂU — bảng đầu + HAI BẢNG CON THẬT =====
// Nguồn: DMS40/0.01.Master.cs (csproj 122) — St_MinInvBalance_AddX (10130) ghi 3 bảng tại
//        10468 / 10501 / 10520; _UpdateX (11686) XOÁ rồi GHI LẠI cả hai bảng con.
// 🔴 Chỉ có ở WS 64-bit (_Add / _Get / _Update / _DeleteMulti).
// 🔴 GAP đã vá: port cũ gộp danh sách spec/đại lý thành CHUỖI (ModelList/SpecMix/DealerList) trong khi
//    nguồn dùng hai BẢNG CON — nên không lọc/join được theo spec hay đại lý. Nay có bảng thật;
//    ba cột chuỗi giữ lại để đọc dữ liệu cũ, KHÔNG ghi mới.
app.MapGet("/api/mininvbalances/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.MinInvBalances.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StMinInvNo == no);
    if (h is null) return Results.NotFound(new { no });
    var specs = await db.StMinInvBalanceSpecs.Where(x => x.OrgId == t.OrgId && x.StMinInvNo == no)
        .OrderBy(x => x.SpecCode).Select(x => new { x.SpecCode, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    var dealers = await db.StMinInvBalanceDealers.Where(x => x.OrgId == t.OrgId && x.StMinInvNo == no)
        .OrderBy(x => x.DealerCode).Select(x => new { x.DealerCode, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { header = new { h.StMinInvNo, h.TotalQty, h.FlagAllDealer, h.CreateDTime, h.CreateBy,
        h.InactiveDTime, h.InactiveBy, h.Remark, h.FlagActive, h.LogLUDateTime, h.LogLUBy },
        specs, dealers,
        note = h.FlagAllDealer == "1" ? "FlagAllDealer='1' ⇒ áp cho TẤT CẢ đại lý, bảng đại lý để rỗng." : null });
}).RequireAuthorization();

// Tạo định mức — port 1:1 `St_MinInvBalance_AddX`.
// Ba guard của nguồn:
//   (1) `TotalQty` phải **> 0** (nguồn: `if (nTotalQty <= 0) throw`), đọc bằng Convert.ToInt32;
//   (2) mã định mức phải CHƯA tồn tại — `St_MinInvBalance_CheckDB(…, TConst.Flag.Inactive)`;
//   (3) 🔴 `FlagAllDealer = "0"` ⇒ bảng đại lý PHẢI có ít nhất 1 dòng (0.01.Master.cs:11767);
//       `= "1"` ⇒ áp cho tất cả, bảng con để rỗng.
app.MapPost("/api/mininvbalances/full", async (MinInvBalanceFullDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (dto.TotalQty <= 0) return Results.BadRequest(new { error = "Tổng số lượng định mức phải > 0." });
    var allDealer = (dto.FlagAllDealer ?? "0").Trim() == "1" ? "1" : "0";
    var specs = (dto.Specs ?? new()).Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).Distinct().ToList();
    var dealers = (dto.Dealers ?? new()).Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).Distinct().ToList();
    if (specs.Count == 0) return Results.BadRequest(new { error = "Định mức phải có ít nhất 1 spec." });
    if (allDealer == "0" && dealers.Count == 0)
        return Results.BadRequest(new { error = "FlagAllDealer='0' thì phải chọn ít nhất 1 đại lý (guard nguồn)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var no = "MIN" + now.ToString("yyMMddHHmmss");
    db.MinInvBalances.Add(new MinInvBalance { OrgId = t.OrgId, StMinInvNo = no, TotalQty = dto.TotalQty,
        FlagAllDealer = allDealer, CreateDTime = now, CreateBy = who, Remark = dto.Remark,
        FlagActive = "1", LogLUDateTime = now, LogLUBy = who });
    foreach (var s in specs)
        db.StMinInvBalanceSpecs.Add(new StMinInvBalanceSpec { OrgId = t.OrgId, StMinInvNo = no, SpecCode = s,
            LogLUDateTime = now, LogLUBy = who });
    if (allDealer == "0")
        foreach (var d in dealers)
            db.StMinInvBalanceDealers.Add(new StMinInvBalanceDealer { OrgId = t.OrgId, StMinInvNo = no, DealerCode = d,
                LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { stMinInvNo = no, dto.TotalQty, flagAllDealer = allDealer,
        specs = specs.Count, dealers = allDealer == "1" ? 0 : dealers.Count });
}).RequireAuthorization();

// Sửa — port 1:1 `_UpdateX`: XOÁ rồi GHI LẠI cả hai bảng con (0.01.Master.cs:11851/11894), không sửa từng dòng.
app.MapPut("/api/mininvbalances/{no}/full", async (string no, MinInvBalanceFullDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.MinInvBalances.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StMinInvNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (dto.TotalQty <= 0) return Results.BadRequest(new { error = "Tổng số lượng định mức phải > 0." });
    var allDealer = (dto.FlagAllDealer ?? h.FlagAllDealer).Trim() == "1" ? "1" : "0";
    var specs = (dto.Specs ?? new()).Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).Distinct().ToList();
    var dealers = (dto.Dealers ?? new()).Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).Distinct().ToList();
    if (specs.Count == 0) return Results.BadRequest(new { error = "Định mức phải có ít nhất 1 spec." });
    if (allDealer == "0" && dealers.Count == 0)
        return Results.BadRequest(new { error = "FlagAllDealer='0' thì phải chọn ít nhất 1 đại lý (guard nguồn)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    h.TotalQty = dto.TotalQty; h.FlagAllDealer = allDealer;
    if (dto.Remark is not null) h.Remark = dto.Remark;
    h.LogLUDateTime = now; h.LogLUBy = who;
    db.StMinInvBalanceSpecs.RemoveRange(await db.StMinInvBalanceSpecs.Where(x => x.OrgId == t.OrgId && x.StMinInvNo == no).ToListAsync());
    db.StMinInvBalanceDealers.RemoveRange(await db.StMinInvBalanceDealers.Where(x => x.OrgId == t.OrgId && x.StMinInvNo == no).ToListAsync());
    foreach (var s in specs)
        db.StMinInvBalanceSpecs.Add(new StMinInvBalanceSpec { OrgId = t.OrgId, StMinInvNo = no, SpecCode = s,
            LogLUDateTime = now, LogLUBy = who });
    if (allDealer == "0")
        foreach (var d in dealers)
            db.StMinInvBalanceDealers.Add(new StMinInvBalanceDealer { OrgId = t.OrgId, StMinInvNo = no, DealerCode = d,
                LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { stMinInvNo = no, specs = specs.Count, dealers = allDealer == "1" ? 0 : dealers.Count,
        note = "Nguồn xoá sạch 2 bảng con rồi ghi lại — không sửa từng dòng." });
}).RequireAuthorization();

// Ngừng hiệu lực — nguồn có cặp InactiveDTime/InactiveBy TÁCH RIÊNG khỏi LogLU*.
app.MapPost("/api/mininvbalances/{no}/inactivate", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.MinInvBalances.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StMinInvNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.FlagActive == "0") return Results.BadRequest(new { error = "Định mức đã ngừng hiệu lực." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    h.FlagActive = "0"; h.InactiveDTime = now; h.InactiveBy = who;
    h.LogLUDateTime = now; h.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StMinInvNo, h.FlagActive, h.InactiveDTime, h.InactiveBy });
}).RequireAuthorization();

