        h.CreatedBy, h.UpdateDTime, h.UpdateBy, h.LogLUDateTime, h.LogLUBy }, count = lines.Count, lines });
}).RequireAuthorization();

app.MapPost("/api/orderplanhtmv", async (OrderPlanHtmvDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var flag = (dto.FlagIsMonth ?? "1").Trim();
    if (flag is not ("1" or "0")) return Results.BadRequest(new { error = "FlagIsMonth = \"1\" (kỳ theo tháng) | \"0\"." });
    var lines = (dto.Lines ?? new()).Where(x => !string.IsNullOrWhiteSpace(x.SpecCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Kế hoạch phải có ít nhất 1 dòng spec." });
    var dupe = lines.GroupBy(x => x.SpecCode.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe is not null) return Results.BadRequest(new { error = $"Spec {dupe.Key} bị trùng trong kế hoạch." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var no = "ORP" + now.ToString("yyMMddHHmmss");
    db.OrdOrderPlanHtmvs.Add(new OrdOrderPlanHtmv { OrgId = t.OrgId, OrderPlanNo = no,
        PeriodDate = dto.PeriodDate ?? now, FlagIsMonth = flag, CreatedDate = now, CreatedBy = who,
        LogLUDateTime = now, LogLUBy = who });
    foreach (var l in lines)
        db.OrdOrderPlanHtmvDetails.Add(new OrdOrderPlanHtmvDetail { OrgId = t.OrgId, OrderPlanNo = no,
            SpecCode = l.SpecCode.Trim().ToUpperInvariant(), ModelCode = l.ModelCode,
            QtyBOApp = l.QtyBOApp, QtySalesOrderP = l.QtySalesOrderP, QtyStock = l.QtyStock,
            QtyBOHTMV = l.QtyBOHTMV, QtyStockDealer = l.QtyStockDealer, QtySalesOrderPlan = l.QtySalesOrderPlan,
            QtySalesOrder = l.QtySalesOrder, QtyHTMVApp = l.QtyHTMVApp, LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { orderPlanNo = no, periodDate = dto.PeriodDate ?? now, flagIsMonth = flag, specs = lines.Count });
}).RequireAuthorization();

// Sửa số liệu kế hoạch. Nguồn `_Update` KHÔNG xoá-ghi lại mà chỉ update từng dòng
// (trong cả hàm không có `delete`/`insert` nào) và ghi cặp UpdateDTime/UpdateBy ở bảng đầu.
app.MapPut("/api/orderplanhtmv/{no}", async (string no, OrderPlanHtmvUpdDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.OrdOrderPlanHtmvs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPlanNo == no);
    if (h is null) return Results.NotFound(new { no });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var rows = await db.OrdOrderPlanHtmvDetails.Where(x => x.OrgId == t.OrgId && x.OrderPlanNo == no).ToListAsync();
    int changed = 0; var unknown = new List<string>();
    foreach (var l in dto.Lines ?? new())
    {
        var spec = (l.SpecCode ?? "").Trim().ToUpperInvariant();
        var row = rows.FirstOrDefault(x => x.SpecCode == spec);
        if (row is null) { unknown.Add(spec); continue; }   // nguồn chỉ SỬA, không thêm dòng mới
        row.ModelCode = l.ModelCode ?? row.ModelCode;
        row.QtyBOApp = l.QtyBOApp; row.QtySalesOrderP = l.QtySalesOrderP; row.QtyStock = l.QtyStock;
        row.QtyBOHTMV = l.QtyBOHTMV; row.QtyStockDealer = l.QtyStockDealer;
        row.QtySalesOrderPlan = l.QtySalesOrderPlan; row.QtySalesOrder = l.QtySalesOrder;
        row.QtyHTMVApp = l.QtyHTMVApp; row.LogLUDateTime = now; row.LogLUBy = who; changed++;
    }
    h.UpdateDTime = now; h.UpdateBy = who; h.LogLUDateTime = now; h.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.OrderPlanNo, changed, unknownSpecs = unknown });
}).RequireAuthorization();

// ===== #144: BỘ QUY ĐỔI SPEC MỚI ATMV (Mst_ATMV_NewSpec + Dtl) =====
// Nguồn: DMS40/0.01.Master.cs (csproj 122) — _Add (512) / _Update (965). Chỉ có ở WS 64-bit.
app.MapGet("/api/atmvnewspecs", async (AppDbContext db, ITenantContext t, string? flagActive) =>
{
    var q = db.MstAtmvNewSpecs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new {
        x.ATMVNSCode, x.CreateDTime, x.CreateBy, x.FlagActive, x.LogLUDateTime, x.LogLUBy,
        specs = db.MstAtmvNewSpecDtls.Count(d => d.OrgId == t.OrgId && d.ATMVNSCode == x.ATMVNSCode) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/atmvnewspecs/{code}", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var h = await db.MstAtmvNewSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ATMVNSCode == code);
    if (h is null) return Results.NotFound(new { code });
    var lines = await db.MstAtmvNewSpecDtls.Where(x => x.OrgId == t.OrgId && x.ATMVNSCode == code)
        .OrderBy(x => x.SpecCode).Select(x => new { x.SpecCode, x.EffDateStart, x.EffDateEnd, x.QtyMap,
            x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { header = new { h.ATMVNSCode, h.CreateDTime, h.CreateBy, h.FlagActive,
        h.LogLUDateTime, h.LogLUBy }, count = lines.Count, lines });
}).RequireAuthorization();

app.MapPost("/api/atmvnewspecs", async (AtmvNewSpecDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.ATMVNSCode ?? "").Trim().ToUpperInvariant();
    if (code.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã bộ quy đổi." });
    // guard nguồn: Mst_ATMV_NewSpec_CheckDB(..., TConst.Flag.Inactive) ⇒ mã phải CHƯA tồn tại.
    if (await db.MstAtmvNewSpecs.AnyAsync(x => x.OrgId == t.OrgId && x.ATMVNSCode == code))
        return Results.Conflict(new { error = $"Mã bộ quy đổi {code} đã tồn tại." });
    var lines = (dto.Lines ?? new()).Where(x => !string.IsNullOrWhiteSpace(x.SpecCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Bộ quy đổi phải có ít nhất 1 spec." });
    // guard nguồn (0.01.Master.cs:177…): CẢ HAI mốc hiệu lực đều BẮT BUỘC.
    var bad = lines.FirstOrDefault(x => x.EffDateStart is null || x.EffDateEnd is null);
    if (bad is not null) return Results.BadRequest(new { error = $"Spec {bad.SpecCode}: phải có cả ngày bắt đầu và ngày kết thúc hiệu lực." });
    var rev = lines.FirstOrDefault(x => x.EffDateEnd < x.EffDateStart);
    if (rev is not null) return Results.BadRequest(new { error = $"Spec {rev.SpecCode}: ngày kết thúc nhỏ hơn ngày bắt đầu." });
    var dupe = lines.GroupBy(x => x.SpecCode.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe is not null) return Results.BadRequest(new { error = $"Spec {dupe.Key} bị trùng." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    db.MstAtmvNewSpecs.Add(new MstAtmvNewSpec { OrgId = t.OrgId, ATMVNSCode = code, CreateDTime = now,
        CreateBy = who, FlagActive = "1", LogLUDateTime = now, LogLUBy = who });   // nguồn tạo luôn ở "1"
    foreach (var l in lines)
        db.MstAtmvNewSpecDtls.Add(new MstAtmvNewSpecDtl { OrgId = t.OrgId, ATMVNSCode = code,
            SpecCode = l.SpecCode.Trim().ToUpperInvariant(),
            // nguồn chuẩn hoá bằng StdDate ⇒ lưu NGÀY, bỏ phần giờ.
            EffDateStart = l.EffDateStart!.Value.Date, EffDateEnd = l.EffDateEnd!.Value.Date,
            QtyMap = l.QtyMap, LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { code, specs = lines.Count, flagActive = "1" });
}).RequireAuthorization();

// ===== #189 Thiết lập spec ATMV mới — `Mst_ATMV_NewSpec_Update` (field-mask, CHỈ ĐỂ TẮT) =====
// Nguồn: `TERP.BizHTC/DMS40/0.01.Master.cs:965` (csproj 122).
// BƯỚC 3B: md5 CẢ FILE `c690f1f1` KHỚP 2 máy. Đã liệt kê ranh giới hàm: 965 → 1164.
//
// 🔴 Cách tìm ra: GIAO của hai danh sách — 36 hàm field-mask (#184) × danh sách `/toggle` (#188).
//    `Mst_ATMV_NewSpec_Update` là hàm field-mask, và MiniHTC có `/atmvnewspecs/{code}/toggle`.
//
// 🔴 HAI GUARD RẤT ĐẶC BIỆT, port cũ không có cái nào:
//  1. `Update_InvalidFlagActive` — **lệnh này CHỈ ĐỂ TẮT**: đặt `FlagActive = "1"` (hoặc để rỗng) là LỖI.
//     Nguồn viết `if (bUpd_FlagActive && string.IsNullOrEmpty(strFlagActive) || strFlagActive == Flag.Active)`.
//     ⚠️ Thiếu ngoặc ⇒ theo ưu tiên toán tử là `(A && B) || C`: nhánh `C` (`= "1"`) **ném lỗi kể cả khi
//        mask RỖNG**. Giữ nguyên đúng nguồn (cùng cách xử lý guard `&&`/`||` lệch ở #166), ghi rõ ở đây.
//  2. 🔴 **"Port check 1: Tại 1 thời điểm chỉ có 1 thiết lập active=1"** — SAU khi ghi, nguồn đếm lại
//     toàn bảng `where FlagActive = '1'`; nếu `> 1` thì **ném lỗi** (giao dịch rollback).
//     Đây là ràng buộc DUY NHẤT TOÀN BẢNG, không phải guard trên một dòng.
//
// ⚠️ `/toggle` đã có **BẬT được** cờ — trái luật nguồn. Giữ `/toggle` cho UI nhưng thêm chặn bật
//    khi đã có bản khác đang active, và bổ sung `/update` là lệnh 1:1 với nguồn
//    (luật `C0-ducentesimussexagesimusoctavus`: toggle không thay được _Update).
app.MapPost("/api/atmvnewspecs/{code}/update", async (string code, AtmvNewSpecUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    code = code.Trim().ToUpperInvariant();
    var h = await db.MstAtmvNewSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ATMVNSCode == code);
    if (h is null) return Results.NotFound(new { code });

    var mask = (dto.FtColsUpd ?? "").ToUpperInvariant();
    var updFlag = mask.Contains("MST_ATMV_NEWSPEC.FLAGACTIVE");
    var f = (dto.FlagActive ?? "").Trim();

    // Guard (1) — port đúng biểu thức nguồn `(bUpd && rỗng) || f == "1"`.
    if ((updFlag && f.Length == 0) || f == "1")
        return Results.BadRequest(new { error = "Lệnh này chỉ dùng để TẮT thiết lập (FlagActive = \"0\")." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (updFlag) h.FlagActive = f;
    h.LogLUDateTime = DateTime.Now; h.LogLUBy = who;
    await db.SaveChangesAsync();

    // Guard (2) — "Port check 1": sau khi ghi, toàn bảng chỉ được có TỐI ĐA MỘT dòng FlagActive = '1'.
    var activeCount = await db.MstAtmvNewSpecs.CountAsync(x => x.OrgId == t.OrgId && x.FlagActive == "1");
    if (activeCount > 1)
        return Results.BadRequest(new { error = $"Đang có {activeCount} thiết lập ATMV cùng hiệu lực — tại một thời điểm chỉ được MỘT.", activeCount });

    return Results.Ok(new { h.ATMVNSCode, h.FlagActive, updatedFlagActive = updFlag, h.LogLUDateTime, h.LogLUBy, activeCount });
}).RequireAuthorization();

app.MapPost("/api/atmvnewspecs/{code}/toggle", async (string code, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    code = code.Trim().ToUpperInvariant();
    var h = await db.MstAtmvNewSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ATMVNSCode == code);
    if (h is null) return Results.NotFound(new { code });
    var turningOn = h.FlagActive != "1";
    // 🔴 #189: nguồn ràng buộc "tại 1 thời điểm chỉ có 1 thiết lập active=1" (Port check 1,
    //    DMS40/0.01.Master.cs:1090). `/toggle` cũ BẬT được vô tội vạ ⇒ vi phạm ràng buộc toàn bảng.
    if (turningOn && await db.MstAtmvNewSpecs.AnyAsync(x => x.OrgId == t.OrgId && x.FlagActive == "1"))
        return Results.BadRequest(new { error = "Đã có thiết lập ATMV đang hiệu lực — tại một thời điểm chỉ được MỘT." });
    h.FlagActive = turningOn ? "1" : "0";
    h.LogLUDateTime = DateTime.Now; h.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.ATMVNSCode, h.FlagActive });
}).RequireAuthorization();

// #143: chi tiết một lô — trả CẢ BỐN nhánh người nhận/đính kèm của nguồn.
app.MapGet("/api/emailbatches/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var h = await db.EmailBatches.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BatchNo == no);
    if (h is null) return Results.NotFound(new { no });
    return Results.Ok(new
    {
        header = new { h.BatchNo, h.DealerCode, h.EffectDate, h.SendBy, h.AttachmentName, h.CreatedAt,
            h.ConfigCode, h.TEmailCode, h.WSPath, h.BatchStatus, h.LogLUDateTime, h.LogLUBy },
        to = await db.EmailSends.Where(x => x.OrgId == t.OrgId && x.BatchNo == no)
            .Select(x => new { x.Email, x.Status, x.InvalidEmail }).ToListAsync(),
        cc = await db.EmailBatchCcs.Where(x => x.OrgId == t.OrgId && x.BatchNo == no)
            .Select(x => new { x.EmailCode, x.BatchStatusCC, x.LogLUDateTime, x.LogLUBy }).ToListAsync(),
        bcc = await db.EmailBatchBccs.Where(x => x.OrgId == t.OrgId && x.BatchNo == no)
            .Select(x => new { x.EmailCode, x.BatchStatusBCC, x.LogLUDateTime, x.LogLUBy }).ToListAsync(),
        files = await db.EmailBatchFileAttaches.Where(x => x.OrgId == t.OrgId && x.BatchNo == no)
            .Select(x => new { x.FilePath, x.BatchStatusFA, x.LogLUDateTime, x.LogLUBy }).ToListAsync()
    });
}).RequireAuthorization();

// #143: hàng chờ thật của worker — lô còn "P" VÀ đã tới giờ hẹn (nguồn dùng EffectDate để hẹn giờ).
app.MapGet("/api/emailbatches/pending", async (AppDbContext db, ITenantContext t, int? take) =>
{
    var now = DateTime.Now;
    var items = await db.EmailBatches
        .Where(x => x.OrgId == t.OrgId && x.BatchStatus == "P" && (x.EffectDate == null || x.EffectDate <= now))
        .OrderBy(x => x.EffectDate).ThenBy(x => x.Id).Take(take ?? 100)
        .Select(x => new { x.BatchNo, x.ConfigCode, x.TEmailCode, x.WSPath, x.EffectDate, x.DealerCode }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// #143: đánh dấu đã gửi. Nguồn đặt "A" ở bảng đầu VÀ ở trạng thái riêng của TỪNG bảng con
// (BatchStatusTo/CC/BCC/FA — bốn cột khác tên nhưng chung bảng mã TConst.BatchStatus).
// ⚠️ Nhánh To ở MiniHTC là `EmailSend`, dùng CỜ "1"/"0" chứ không phải bảng mã chữ — giữ đúng
//    từ vựng của từng tầng, không đồng hoá.
app.MapPost("/api/emailbatches/{no}/sent", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var h = await db.EmailBatches.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BatchNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.BatchStatus != "P") return Results.BadRequest(new { error = $"Lô đang \"{h.BatchStatus}\", chỉ đánh dấu gửi cho lô còn \"P\"." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    h.BatchStatus = "A"; h.LogLUDateTime = now; h.LogLUBy = who;
    var sent = 0;
    foreach (var x in await db.EmailSends.Where(x => x.OrgId == t.OrgId && x.BatchNo == no && x.Status == "0" && !x.InvalidEmail).ToListAsync())
    { x.Status = "1"; sent++; }
    foreach (var x in await db.EmailBatchCcs.Where(x => x.OrgId == t.OrgId && x.BatchNo == no).ToListAsync())
    { x.BatchStatusCC = "A"; x.LogLUDateTime = now; x.LogLUBy = who; }
    foreach (var x in await db.EmailBatchBccs.Where(x => x.OrgId == t.OrgId && x.BatchNo == no).ToListAsync())
    { x.BatchStatusBCC = "A"; x.LogLUDateTime = now; x.LogLUBy = who; }
    foreach (var x in await db.EmailBatchFileAttaches.Where(x => x.OrgId == t.OrgId && x.BatchNo == no).ToListAsync())
    { x.BatchStatusFA = "A"; x.LogLUDateTime = now; x.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.BatchNo, status = h.BatchStatus, toMarkedSent = sent });
}).RequireAuthorization();

app.MapGet("/api/emailbatches", async (AppDbContext db, ITenantContext t, string? dealer) =>
{
    var qy = db.EmailBatches.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer);
    var items = await qy.OrderByDescending(x => x.Id).Take(500)
        .Select(x => new { x.Id, x.BatchNo, x.DealerCode, x.EffectDate, x.SendBy, x.AttachmentName, x.CreatedAt,
            // #143 parity DMS40_Email_BatchSendEmail.
            x.ConfigCode, x.TEmailCode, x.WSPath, x.BatchStatus, x.LogLUDateTime, x.LogLUBy,
            to = db.EmailSends.Count(y => y.OrgId == t.OrgId && y.BatchNo == x.BatchNo),
            cc = db.EmailBatchCcs.Count(y => y.OrgId == t.OrgId && y.BatchNo == x.BatchNo),
            bcc = db.EmailBatchBccs.Count(y => y.OrgId == t.OrgId && y.BatchNo == x.BatchNo),
            files = db.EmailBatchFileAttaches.Count(y => y.OrgId == t.OrgId && y.BatchNo == x.BatchNo) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== Cấu hình gửi email tự động (EmailAutoConfig — port 1:1 FrmAutoSendConfig, TCMotor) =====
app.MapGet("/api/emailautoconfigs", async (AppDbContext db, ITenantContext t) =>
{
    var items = await db.EmailAutoConfigs.Where(c => c.OrgId == t.OrgId).OrderBy(c => c.EmailType)
        .Select(c => new { c.Id, c.EmailType, c.AutoTime, startDate = c.StartDate, endDate = c.EndDate, c.SendMode, c.Description, c.FlagActive }).ToListAsync();
    return Results.Ok(new { items });
}).RequireAuthorization();

app.MapPost("/api/emailautoconfigs", async (EmailAutoConfigDto dto, AppDbContext db, ITenantContext t) =>
{
    var type = (dto.EmailType ?? "").Trim().ToUpperInvariant();
    if (type == "") return Results.BadRequest(new { error = "Thiếu loại email." });
    var time = (dto.AutoTime ?? "").Trim();
    // Validate giờ HH:mm (giống WinForm bắt buộc chọn giờ).
    if (!System.Text.RegularExpressions.Regex.IsMatch(time, @"^([01]\d|2[0-3]):[0-5]\d$"))
        return Results.BadRequest(new { error = "Giờ gửi không hợp lệ (định dạng HH:mm)." });
    if (dto.StartDate.HasValue && dto.EndDate.HasValue && dto.EndDate < dto.StartDate)
        return Results.BadRequest(new { error = "Ngày kết thúc phải sau ngày bắt đầu." });
    var c = await db.EmailAutoConfigs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.EmailType == type);
    if (c is null) { c = new EmailAutoConfig { OrgId = t.OrgId, EmailType = type }; db.EmailAutoConfigs.Add(c); }
    c.AutoTime = time; c.StartDate = dto.StartDate; c.EndDate = dto.EndDate;
    c.SendMode = dto.SendMode; c.Description = dto.Description; c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Id, c.EmailType, c.AutoTime });
}).RequireAuthorization();

app.MapPost("/api/emailautoconfigs/{id}/toggle", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.EmailAutoConfigs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    c.FlagActive = c.FlagActive == "1" ? "0" : "1"; c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Id, c.FlagActive });
}).RequireAuthorization();

