// ===== Trạng thái phiếu kho: bộ ĐẦY ĐỦ theo nguồn (TConst.Ser_Inv_StockIn / Ser_Inv_StockOut) =====
// 🔴 Port cũ chỉ có 2/5: Draft → Confirmed. Nguồn có 5, trong đó HAI trạng thái mang nghĩa HUỶ:
//   1 Pending (mới tạo) · 2 Executing (tiến hành) · 3 Finished (kết thúc = "đã duyệt")
//   4 Adjustment (điều chỉnh — nguồn ghi rõ "coi như huỷ") · 5 Reject (huỷ)
// Mọi báo cáo kho của nguồn đều lọc `status = 3` hoặc `not in ('4','5')` ⇒ 4/5 bị loại khỏi số liệu.
var stockDocStatusSourceCodes = new Dictionary<string, string>
{
    ["Draft"] = "1",        // Pending — mới tạo
    ["Executing"] = "2",    // Tiến hành
    ["Confirmed"] = "3",    // Finished — kết thúc (giá trị port cũ đang dùng cho "đã duyệt")
    ["Adjustment"] = "4",   // Điều chỉnh — COI NHƯ HUỶ
    ["Rejected"] = "5",     // Huỷ
};

// Hai trạng thái bị LOẠI khỏi mọi báo cáo kho (nguồn: `not in ('4','5')`).
string[] stockDocVoidStatuses = { "Adjustment", "Rejected" };

app.MapGet("/api/stockdocs/statuses", () => Results.Ok(new
{
    statuses = stockDocStatusSourceCodes.Select(kv => new { status = kv.Key, sourceCode = kv.Value }),
    voidStatuses = stockDocVoidStatuses,
    note = "Adjustment(4) và Rejected(5) bị loại khỏi mọi báo cáo kho; Confirmed(3) mới là 'đã duyệt'."
})).RequireAuthorization();

/// <summary>Kiểm trạng thái đích khi huỷ/điều chỉnh phiếu kho — dùng chung cho phiếu nhập và phiếu xuất.</summary>
static string? ValidateStockDocVoidTarget(string[] voidStatuses, string currentStatus, string? targetStatus)
{
    var target = (targetStatus ?? "").Trim();
    if (!voidStatuses.Contains(target))
        return $"Trạng thái hợp lệ: {string.Join(", ", voidStatuses)}.";
    // Đã ở trạng thái huỷ rồi thì thôi; đã duyệt thì phải điều chỉnh chứ không huỷ thẳng.
    if (voidStatuses.Contains(currentStatus)) return "Phiếu đã ở trạng thái huỷ/điều chỉnh.";
    if (currentStatus == "Confirmed" && target == "Rejected")
        return "Phiếu đã duyệt — dùng Adjustment (điều chỉnh) thay vì huỷ thẳng.";
    return null;
}

// Huỷ / điều chỉnh PHIẾU NHẬP. Nếu phiếu đã duyệt (đã cộng tồn) thì phải TRỪ LẠI tồn.
app.MapPost("/api/servicestockins/{no}/void", async (
    string no, StockDocVoidDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.ServiceStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });
    var error = ValidateStockDocVoidTarget(stockDocVoidStatuses, h.Status, dto.ToStatus);
    if (error is not null) return Results.BadRequest(new { error });

    var reverted = 0;
    if (h.Status == "Confirmed")
    {
        // Phiếu nhập đã duyệt thì đã CỘNG tồn ⇒ điều chỉnh phải TRỪ lại, nếu không tồn kho sẽ dôi ảo.
        var lines = await db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId && l.ServiceStockInId == h.Id).ToListAsync();
        foreach (var l in lines)
        {
            var part = await db.ServiceParts.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PartCode == l.PartCode);
            if (part is not null) { part.Quantity -= l.Quantity; reverted++; }
        }
    }
    h.Status = dto.ToStatus!.Trim();
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockInNo, status = h.Status, sourceCode = stockDocStatusSourceCodes[h.Status], partsReverted = reverted });
}).RequireAuthorization();

// Huỷ / điều chỉnh PHIẾU XUẤT. Nếu phiếu đã duyệt (đã trừ tồn) thì phải CỘNG LẠI tồn.
app.MapPost("/api/servicestockouts/{no}/void", async (
    string no, StockDocVoidDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.ServiceStockOuts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockOutNo == no);
    if (h is null) return Results.NotFound(new { no });
    var error = ValidateStockDocVoidTarget(stockDocVoidStatuses, h.Status, dto.ToStatus);
    if (error is not null) return Results.BadRequest(new { error });

    var reverted = 0;
    if (h.Status == "Confirmed")
    {
        // Phiếu xuất đã duyệt thì đã TRỪ tồn ⇒ điều chỉnh phải CỘNG lại.
        var lines = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && l.ServiceStockOutId == h.Id).ToListAsync();
        foreach (var l in lines)
        {
            var part = await db.ServiceParts.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PartCode == l.PartCode);
            if (part is not null) { part.Quantity += l.Quantity; reverted++; }
        }
    }
    h.Status = dto.ToStatus!.Trim();
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockOutNo, status = h.Status, sourceCode = stockDocStatusSourceCodes[h.Status], partsReverted = reverted });
}).RequireAuthorization();

// ===== Nhập phụ tùng nợ từ Excel (port 1:1 FrmImportSerPartOO — TCMotor DMSCarSv/Services) =====
// Nguồn: btnImportExcel_Click (validate) + btnSave_Click (gọi partService.SerPartOOCreate từng dòng).
// ⚠️ Excel gốc đọc bằng ExcelImport.Query(file, "A2") ⇒ HEADER Ở DÒNG 2, không phải dòng 1.
//    Client phải parse Excel rồi POST danh sách dòng vào đây (API nhận JSON, không nhận file .xls).
// Đặc tính quan trọng của nguồn: validate TOÀN BỘ các dòng TRƯỚC, chỉ 1 dòng sai là DỪNG HẲN,
// không lưu dòng nào (all-or-nothing) — tránh nhập nửa vời.
app.MapPost("/api/servicepartoos/import", async (
    ImportPartOORequest request,
    AppDbContext database,
    ITenantContext tenant) =>
{
    var importRows = request.Rows ?? new List<ImportPartOORowDto>();
    // Nguồn: file rỗng → "File excel import không có dữ liệu"
    if (importRows.Count == 0)
        return Results.BadRequest(new { error = "File excel import không có dữ liệu" });

    // --- Pha 1: validate TẤT CẢ các dòng (không ghi gì xuống DB) ---
    foreach (var row in importRows)
    {
        var validationError = ValidatePartOOImportRow(row);
        if (validationError is not null) return Results.BadRequest(new { error = validationError });
    }

    // --- Pha 2: mã phụ tùng phải TỒN TẠI trong hệ thống (nguồn tra Mst_Part theo danh sách PartCode) ---
    var importedPartCodes = importRows
        .Select(row => row.PartCode.Trim().ToUpperInvariant())
        .Distinct()
        .ToList();
    var knownPartCodes = await database.ServiceParts
        .Where(part => part.OrgId == tenant.OrgId && importedPartCodes.Contains(part.PartCode))
        .Select(part => part.PartCode)
        .ToListAsync();

    if (knownPartCodes.Count == 0)
        return Results.BadRequest(new { error = "Danh sách phụ tùng import không có trong hệ thống" });

    var knownPartCodeSet = knownPartCodes.ToHashSet();
    var missingPartCode = importedPartCodes.FirstOrDefault(code => !knownPartCodeSet.Contains(code));
    if (missingPartCode is not null)
        return Results.BadRequest(new { error = $"Mã phụ tùng '{missingPartCode}' không có trong hệ thống!" });

    // --- Pha 3: mọi dòng hợp lệ → tạo phụ tùng nợ (nguồn gọi SerPartOOCreate từng dòng) ---
    var createdCount = 0;
    foreach (var row in importRows)
    {
        database.ServicePartOOs.Add(new ServicePartOO
        {
            OrgId = tenant.OrgId,
            OONo = $"OO-{DateTime.Now:yyMMddHHmmss}-{createdCount + 1:D3}",
            PartCode = row.PartCode.Trim().ToUpperInvariant(),
            PlateNo = row.OOPlateNo.Trim().ToUpperInvariant(),
            QtyNeeded = decimal.Parse(row.SoLuongNo.Trim()),
            QtyFulfilled = string.IsNullOrWhiteSpace(row.SoLuongTra) ? 0 : decimal.Parse(row.SoLuongTra.Trim()),
            LoaiXe = row.LoaiXe,
            CVDV = row.CVDV,
            Note = row.GhiChu,
            DealerCode = request.DealerCode?.Trim().ToUpperInvariant(),
            NgayDatHang = ParseOptionalDate(row.NgayDatHang),
            NgayVeDuKien = ParseOptionalDate(row.NgayVeDuKien),
            NgayHenTra = ParseOptionalDate(row.NgayHenTra),
            Status = "Open"
        });
        createdCount++;
    }
    await database.SaveChangesAsync();

    return Results.Ok(new { imported = createdCount, message = "Đã tạo phụ tùng nợ thành công" });
}).RequireAuthorization();

// ===== Phụ tùng nợ/chờ giao theo xe (ServicePartOO — port 1:1 FrmNewSerPartOO/FrmMngSerPartOO, TCMotor) =====
app.MapGet("/api/servicepartoos", async (AppDbContext db, ITenantContext t, string? part, string? plate, string? status) =>
{
    var query = db.ServicePartOOs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(part)) query = query.Where(x => x.PartCode.Contains(part!.ToUpper()) || (x.PartName != null && x.PartName.Contains(part!)));
    if (!string.IsNullOrWhiteSpace(plate)) query = query.Where(x => x.PlateNo == plate);
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500)
        .Select(x => new
        {
            x.OONo, x.PartCode, x.PartName, x.PlateNo, x.QtyNeeded, x.QtyFulfilled,
            remaining = x.QtyNeeded - x.QtyFulfilled, x.Note, x.Status,
            // GAP đã vá: 6 cột TblSer_Part_OO trước đây không được trả về
            x.LoaiXe, x.CVDV, x.DealerCode, x.NgayDatHang, x.NgayVeDuKien, x.NgayHenTra,
            createdAt = x.CreatedAt.ToString("yyyy-MM-dd")
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, openCount = items.Count(i => i.Status == "Open"), items });
}).RequireAuthorization();

// Tạo phiếu nợ phụ tùng (SL nợ > 0).
app.MapPost("/api/servicepartoos", async (ServicePartOODto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.PartCode)) return Results.BadRequest(new { error = "Chưa nhập mã phụ tùng." });
    if (string.IsNullOrWhiteSpace(dto.PlateNo)) return Results.BadRequest(new { error = "Chưa nhập biển số xe." });
    if (dto.QtyNeeded <= 0) return Results.BadRequest(new { error = "Số lượng nợ phải lớn hơn 0." });
    var no = "OO" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new ServicePartOO
    {
        OrgId = t.OrgId, OONo = no, PartCode = dto.PartCode.Trim().ToUpperInvariant(), PartName = dto.PartName,
        PlateNo = dto.PlateNo.Trim(), QtyNeeded = dto.QtyNeeded, QtyFulfilled = 0, Note = dto.Note, Status = "Open",
        // GAP đã vá: nhận đủ 6 cột TblSer_Part_OO
        LoaiXe = dto.LoaiXe, CVDV = dto.CVDV, DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(),
        NgayDatHang = dto.NgayDatHang, NgayVeDuKien = dto.NgayVeDuKien, NgayHenTra = dto.NgayHenTra
    };
    db.ServicePartOOs.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.OONo });
}).RequireAuthorization();

// Giao phụ tùng (cấn trừ SL nợ; không vượt SL còn thiếu; đủ -> Fulfilled).
app.MapPost("/api/servicepartoos/{no}/fulfill", async (string no, ServicePartFulfillDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var x = await db.ServicePartOOs.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.OONo == no);
    if (x is null) return Results.NotFound(new { no });
    if (x.Status == "Fulfilled") return Results.BadRequest(new { error = "Phiếu đã giao đủ." });
    if (dto.Qty <= 0) return Results.BadRequest(new { error = "Số lượng giao phải lớn hơn 0." });
    var remaining = x.QtyNeeded - x.QtyFulfilled;
    if (dto.Qty > remaining) return Results.BadRequest(new { error = $"Số lượng giao vượt số còn thiếu ({remaining})." });
    x.QtyFulfilled += dto.Qty;
    if (x.QtyFulfilled >= x.QtyNeeded) x.Status = "Fulfilled";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.OONo, qtyFulfilled = x.QtyFulfilled, remaining = x.QtyNeeded - x.QtyFulfilled, status = x.Status });
}).RequireAuthorization();

// ===== Nhập phụ tùng hàng loạt từ Excel (port 1:1 FrmImportPart, TCMotor) — tái dùng ServicePart =====
app.MapPost("/api/serviceparts/import", async (ServicePartImportDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = dto.Rows ?? new();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào để nhập." });
    var errors = new List<object>();
    // Phát hiện trùng mã trong lô nhập — nguồn `MSG_WARNING_DUPLICATE_PARTCODE` = "Mã phụ tùng trùng nhau".
    // ===== 🔴 #256 CỐ Ý KHÔNG thêm guard ký tự đặc biệt ở đây =====
    // Bản đồ regex #249 liệt kê `FrmImportPart.cs` là màn "dùng `regex.IsMatch`". Nhưng mở ra đọc
    // (:110-114) thì **cả khối guard BỊ COMMENT**:
    //     `//if (this.regex.IsMatch(strPartCode))`
    //     `//{ Util.ShowWarningMsgBox(ErrorMessage.MSG_WARNING_KEYSPE_PARTCODE); return; }`
    // ⇒ nguồn **cố ý tắt** kiểm ký tự đặc biệt cho import PHỤ TÙNG (khác `FrmImportService` vốn còn SỐNG,
    //   và khác `FrmPartPriceImport` cũng còn SỐNG). Thêm guard ở đây = **chặt hơn nguồn**, chặn nhầm
    //   mã phụ tùng hợp lệ của NCC. Giữ nguyên, không vá. (md5 `cbd2ec62` — KHỚP 2 máy.)
    var seen = new HashSet<string>();
    int created = 0, updated = 0;
    for (int i = 0; i < rows.Count; i++)
    {
        var r = rows[i];
        var line = i + 1;
        var code = (r.PartCode ?? "").Trim().ToUpperInvariant();
        if (string.IsNullOrEmpty(code)) { errors.Add(new { line, error = "Thiếu mã phụ tùng." }); continue; }
        if (string.IsNullOrWhiteSpace(r.PartName)) { errors.Add(new { line, code, error = "Thiếu tên phụ tùng." }); continue; }
        if (r.Price < 0 || r.MinQuantity < 0) { errors.Add(new { line, code, error = "Giá/tồn tối thiểu không hợp lệ." }); continue; }
        if (!seen.Add(code)) { errors.Add(new { line, code, error = "Mã phụ tùng bị trùng trong file nhập." }); continue; }
        var ex = await db.ServiceParts.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PartCode == code);
        if (ex is not null)
        {
            ex.PartName = r.PartName; ex.Unit = r.Unit; ex.Price = r.Price; ex.MinQuantity = r.MinQuantity; ex.FlagActive = "1";
            updated++;
        }
        else
        {
            db.ServiceParts.Add(new ServicePart { OrgId = t.OrgId, PartCode = code, PartName = r.PartName, Unit = r.Unit, Price = r.Price, MinQuantity = r.MinQuantity, FlagActive = "1" });
            created++;
        }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = rows.Count, created, updated, errorCount = errors.Count, errors });
}).RequireAuthorization();

// ===== Xe khách trong hệ thống dịch vụ (ServiceCar — port 1:1 FrmCarInfo, TCMotor) =====
app.MapGet("/api/servicecars", async (AppDbContext db, ITenantContext t, string? q, string? model, string? active) =>
{
    var query = db.ServiceCars.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.FrameNo.Contains(q!.ToUpper()) || (x.PlateNo != null && x.PlateNo.Contains(q!)) || (x.CusName != null && x.CusName.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(model)) query = query.Where(x => x.ModelCode == model);
    if (!string.IsNullOrWhiteSpace(active)) query = query.Where(x => x.FlagActive == active);
    var items = await query.OrderBy(x => x.FrameNo).Take(500).Select(x => new
    {
        x.FrameNo, x.PlateNo, x.EngineNo, x.ModelCode, x.ColorCode, x.TradeMark, x.ProductYear, x.CurrentKm, x.CusName, x.CusMobile, x.FlagActive,
        x.MemberCarID, x.DealerCode, x.CusID,
        // #222 §12: 8 trường mới phải chiếu ở CẢ GET
        x.CarID, x.SalesCarID, x.DateBuyCar, x.InsNo, x.InsContractNo, x.InsStartDate, x.InsFinishedDate, x.Note,
        x.PlateColorCode,   // #332 §12
        x.SerialNo, x.BatteryNo, x.ProductionCode,                                    // #333 §12
        x.CusConfirmedWarrantyDate, x.WarrantyExpiresDate, x.WarrantyKM,              // #333 §12
        warrantyRegistrationDate = x.WarrantyRegistrationDate.HasValue                // #334 §12
            ? x.WarrantyRegistrationDate.Value.ToString("yyyy-MM-dd") : "",
        warrantyDate = x.WarrantyDate.HasValue ? x.WarrantyDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴 #333 MA TRẬN KÊNH ⇄ CỘT của họ `ProcessSaveCar01` (`BizCarSv.Customer.cs`) =====
// **NĂM WebMethod LIVE** trong `WSCarSv.asmx.cs`, mỗi cái dùng một biến thể riêng ghi **cùng bảng `Ser_Car`**:
//   `SerCustomerCarSalesCreate_New20180817` (:20859) → `…_New20180817`
//   `SerCustomerCarSalesCreate_SBHOnline`   (:20936) → `…_SBHOnline`
//   `SerCustomerCarSync_FromPDI`            (:34830) → `…_FromPDI` **và** `…_FromPDIExt`
//   `CarSv_Ser_CustomerCar_SalesCreate_New20180622` (:37005) ┐ **cùng** dùng `…_New20180622`
//   `CarSv_Ser_CustomerCar_MBSCreate`               (:37099) ┘
//   Bản trần `ProcessSaveCar01` chỉ được gọi từ `WSCarSv.cs` (KHÔNG phải codebehind `.asmx.cs`) ⇒ chết.
//
// Cột NGOÀI 12 cột chung — không kênh nào ghi đủ:
//   kênh          | Serial | Battery | ModelID | 3 cột bảo hành | ProductionCode | Created* | LogLU*
//   N20180817     |   ✔    |    ✔    |    –    |       –        |       –        |    –     |   –
//   SBHOnline     |   ✔    |    ✔    |    –    |       ✔        |       –        |    –     |   –
//   FromPDI       |   ✔    |    ✔    |    ✔    |       –        |       –        |    ✔     |   –
//   FromPDIExt    |   ✔    |    ✔    |    –    |       –        |       –        |    –     |   –  (SQL update)
//   N20180622     |   –    |    –    |    ✔    |       –        |       ✔        |    –     |   ✔
//
// 🔴 `_New20180622` là biến thể **NGÀY MỚI NHẤT** nhưng lại là bản LIVE **DUY NHẤT KHÔNG** ghi
//   `SerialNo`/`BatteryNo` — thêm một lần "mới nhất = đầy đủ nhất" là SAI. Nó còn phục vụ **hai** WebMethod.
// ⚠️ `FromPDIExt` ghi bằng **SQL `update … set t.SerialNo/t.BatteryNo`**, không qua DataTable ⇒ máy quét
//   đếm cột theo `["X"] =` trả về **0 cột** cho nó. Bốn dạng ghi cột (lệ #314) vẫn còn hiệu lực.
// ⚠️ `VIN` **không phải cột ghi**: nguồn dùng `row["VIN"]` làm **cột ĐẦU VÀO** rồi gán
//   `newRow["FrameNo"] = row["VIN"]`. Mẫu quét `\["X"\]\s*=` bắt nhầm cả `row["VIN"] ==` (so sánh)
//   ⇒ đã siết thành `=[^=]`. Cùng loại lỗi đếm với #310/#314.
//
// ===== 🔴 #334 ĐƯỜNG **SỬA** XE — `ProcessUpdateCar*` (`BizCarSv.zzzzCode.cs`) =====
// TRACE TWIN theo ĐƯỜNG GỌI (lệ #332), **hai** bản còn sống trong codebehind `WSCarSv.asmx.cs`:
//   `Ser_Customer_Update01_New20220926` (:7515)  → `ProcessUpdateCar_New20220926`  ⇒ **24 cột**
//   `OS_Ser_Customer_Update01`          (:36073) → `ProcessUpdateCar_New20210802`  ⇒ **21 cột**
//   Hai bản CHẾT: `Ser_Customer_Update01` (chỉ gọi từ `WSCarSv.cs`, **không** phải codebehind) và
//     `…_New20180619` (chỉ còn trong ảnh chụp cũ `.asmx.20210208/.20210412.cs`).
//
// 🔴 Ba cột kênh **OS (đối tác)** KHÔNG sửa được, kênh nội bộ thì có:
//   `PlateColorCode` · `WarrantyExpiresDate` · `WarrantyKM`
//   ⇒ đối tác gọi OS API không bao giờ đổi được màu biển và hạn bảo hành mở rộng. Cùng bảng `Ser_Car`.
//   (Trùng mô-típ #332/#333: **một bảng, mỗi kênh một tập cột**.)
//
// ✅ ĐÃ KIỂM `alColumnEffective`: khác #331 (nơi danh sách để RỖNG = biến chết), hai bản này **có nạp**
//   danh sách, nên tập cột lưu thật = giao của (cột được gán) ∩ (danh sách hiệu lực). Đã trích cả hai
//   và chúng **trùng khít** tập cột gán (24 và 21) ⇒ không có cột nào bị âm thầm loại. Ghi lại vì nếu
//   lệch thì mọi con số cột ở trên đều sai.
//
// 🔴 RỖNG = **XOÁ** ở đường sửa: nguồn viết `if (!IsEmpty(x)) { ghi } else { ghi DBNull }` cho
//   `ProductYear` · `WarrantyRegistrationDate` · `PlateColorCode` … ⇒ gửi lên rỗng là **xoá giá trị cũ**,
//   KHÁC nhóm "rỗng = giữ nguyên" của lịch hẹn (#323). Port gán thẳng `ex.X = dto.X` ⇒ cùng kết quả.
// ⚠️ `WarrantyRegistrationDate` nguồn `Convert.ToDateTime(...).ToString("yyyy-MM-dd")` ⇒ **CẮT còn NGÀY**.
//
// Upsert theo số khung (VIN). Guard km không giảm (chỉ tăng hoặc giữ).
app.MapPost("/api/servicecars", async (ServiceCarDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.FrameNo)) return Results.BadRequest(new { error = "Chưa nhập số khung (VIN)." });
    if (dto.CurrentKm < 0) return Results.BadRequest(new { error = "Số km không hợp lệ." });
    var vin = dto.FrameNo.Trim().ToUpperInvariant();
    var ex = await db.ServiceCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.FrameNo == vin);
    if (ex is not null)
    {
        if (dto.CurrentKm < ex.CurrentKm) return Results.BadRequest(new { error = $"Số km mới ({dto.CurrentKm}) không được nhỏ hơn số km hiện tại ({ex.CurrentKm})." });
        ex.PlateNo = dto.PlateNo; ex.EngineNo = dto.EngineNo; ex.ModelCode = dto.ModelCode; ex.ColorCode = dto.ColorCode; ex.TradeMark = dto.TradeMark; ex.ProductYear = dto.ProductYear; ex.CurrentKm = dto.CurrentKm; ex.WarrantyDate = dto.WarrantyDate; ex.CusName = dto.CusName; ex.CusMobile = dto.CusMobile; ex.FlagActive = "1";
        // 🔴 #223: sweep hai-nhánh phát hiện `CusID`/`DealerCode` CHỈ được gán khi TẠO MỚI ⇒ sửa xe đã có
        //    thì hai trường này không bao giờ đổi được. Nguồn `CarUpdate` CÓ gửi cả hai
        //    (`_serCar.CusID`, `_serCar.DealerCode` — MstCarService.cs:109) ⇒ phải cập nhật.
        //    Riêng `MemberCarID` KHÔNG nằm trong `CarUpdate`: nó có lệnh RIÊNG
        //    (`CarSv_SerCarUpdate_MemberCarID` → `POST /api/servicecars/{frameNo}/membercar`)
        //    nên CỐ Ý chỉ gán lúc tạo mới — không phải bỏ sót.
        ex.CusID = dto.CusID; ex.DealerCode = dto.DealerCode;
        // ===== #222 parity: 8 trường còn thiếu của `CarUpdate` (tầng service) =====
        ex.CarID = dto.CarID;
        ex.SalesCarID = dto.SalesCarID;
        ex.DateBuyCar = dto.DateBuyCar;
        ex.InsNo = dto.InsNo;
        ex.InsContractNo = dto.InsContractNo;
        ex.InsStartDate = dto.InsStartDate;
        ex.InsFinishedDate = dto.InsFinishedDate;
        ex.Note = dto.Note;
        ex.PlateColorCode = dto.PlateColorCode;   // #332 §12
        // ===== 🔴 #333 BẤT ĐỐI XỨNG TẠO/SỬA CỦA NGUỒN — port CÓ CHỦ ĐÍCH khác nguồn =====
        // `ProcessSaveCar01_SBHOnline` ghi ba cột bảo hành ở nhánh **TẠO**, nhưng ở nhánh **SỬA**
        //   cả khối bị **comment** (`//20210408`):
        //     `//if (!StringUtils.IsEmpty(row["CusConfirmedWarrantyDate"]…)) { … }`
        //   ⇒ sửa xe thì ba cột bảo hành **rơi im lặng**, người dùng không được báo gì.
        //   Không có chú thích giải thích ⇒ là sót, không phải luật (lệ #272/#275) ⇒ web GHI cả khi sửa,
        //   và trả `warrantyFieldsUpdatedWebOnly` để lệch với WinForm là lệch **nhìn thấy được**.
        ex.SerialNo = dto.SerialNo; ex.BatteryNo = dto.BatteryNo;
        ex.ProductionCode = dto.ProductionCode;
        var warrantyTouched = dto.CusConfirmedWarrantyDate is not null
            || dto.WarrantyExpiresDate is not null || dto.WarrantyKM is not null;
        ex.CusConfirmedWarrantyDate = dto.CusConfirmedWarrantyDate;
        ex.WarrantyExpiresDate = dto.WarrantyExpiresDate;
        ex.WarrantyKM = dto.WarrantyKM;
        // #334 §12: cả hai bản LIVE của đường sửa đều ghi `WarrantyRegistrationDate`, nhưng cổng upsert
        //   này chưa hề gán nó (trước nay chỉ đặt được qua `POST /api/servicecars/warranty-reg-batch`).
        //   Nguồn cắt còn NGÀY ⇒ `.Date`.
        ex.WarrantyRegistrationDate = dto.WarrantyRegistrationDate?.Date;
        await db.SaveChangesAsync();
        return Results.Ok(new
        {
            ex.FrameNo, updated = true,
            warrantyFieldsUpdatedWebOnly = warrantyTouched,
            warrantyNote = warrantyTouched
                ? "Nguồn KHÔNG ghi ba cột bảo hành khi SỬA (khối bị comment 20210408); web có ghi."
                : null,
        });
    }
    var r = new ServiceCar { OrgId = t.OrgId, FrameNo = vin, PlateNo = dto.PlateNo, EngineNo = dto.EngineNo, ModelCode = dto.ModelCode, ColorCode = dto.ColorCode, TradeMark = dto.TradeMark, ProductYear = dto.ProductYear, CurrentKm = dto.CurrentKm, WarrantyDate = dto.WarrantyDate, CusName = dto.CusName, CusMobile = dto.CusMobile,
        MemberCarID = dto.MemberCarID, DealerCode = dto.DealerCode, CusID = dto.CusID, FlagActive = "1",
        // #222 parity: 8 trường của `CarUpdate`
        CarID = dto.CarID, SalesCarID = dto.SalesCarID, DateBuyCar = dto.DateBuyCar, InsNo = dto.InsNo, InsContractNo = dto.InsContractNo, InsStartDate = dto.InsStartDate, InsFinishedDate = dto.InsFinishedDate, Note = dto.Note,
        PlateColorCode = dto.PlateColorCode,   // #332 §12
        // #333 §12 — sáu cột của họ `ProcessSaveCar01`.
        SerialNo = dto.SerialNo, BatteryNo = dto.BatteryNo, ProductionCode = dto.ProductionCode,
        CusConfirmedWarrantyDate = dto.CusConfirmedWarrantyDate,
        WarrantyExpiresDate = dto.WarrantyExpiresDate, WarrantyKM = dto.WarrantyKM,
        WarrantyRegistrationDate = dto.WarrantyRegistrationDate?.Date };   // #334 §12, cắt còn NGÀY
    db.ServiceCars.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.FrameNo, updated = false });
}).RequireAuthorization();

// 🔴 GÁN MÃ XE HỘI VIÊN (Loyalty) cho xe dịch vụ — port `CarSv_SerCarUpdate_MemberCarID`
// (`DMS-Loyalty/DMS/TERP.BizDMS/Biz.zzzz.iNOS.CarSv.cs:2630-2770`, hệ CHỈ có trên máy 150).
app.MapPost("/api/servicecars/{frameNo}/membercar", async (
    string frameNo, ServiceCarMemberDto dto, AppDbContext db, ITenantContext t) =>
{
    var fn = frameNo.Trim().ToUpperInvariant();
    var dealer = (dto.DealerCode ?? "").Trim();
    var cus = (dto.CusID ?? "").Trim();
    var mem = (dto.MemberCarID ?? "").Trim();
    if (dealer.Length == 0) return Results.BadRequest(new { error = "Chưa có mã đại lý." });
    if (cus.Length == 0) return Results.BadRequest(new { error = "Chưa có mã khách hàng." });
    if (mem.Length == 0) return Results.BadRequest(new { error = "Chưa có mã xe hội viên." });

    // Guard 1 (nguồn): mã xe hội viên KHÔNG được đã gán cho xe khác ĐANG HOẠT ĐỘNG trong CÙNG đại lý.
    var dup = await db.ServiceCars.AnyAsync(x => x.OrgId == t.OrgId && x.FlagActive == "1"
        && x.MemberCarID == mem && x.DealerCode == dealer && x.FrameNo != fn);
    if (dup) return Results.BadRequest(new { error = $"Mã xe hội viên {mem} đã được gán cho xe khác của đại lý {dealer}." });

    // Guard 2 (nguồn): xe phải tồn tại theo BỘ BA đại lý + số khung + khách hàng.
    var car = await db.ServiceCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.DealerCode == dealer && x.FrameNo == fn && x.CusID == cus);
    if (car is null)
        return Results.NotFound(new { error = "Không tìm thấy xe theo đại lý + số khung + mã khách hàng.", dealer, frameNo = fn, cusID = cus });

    car.MemberCarID = mem;
    await db.SaveChangesAsync();
    return Results.Ok(new { car.FrameNo, car.DealerCode, car.CusID, car.MemberCarID });
}).RequireAuthorization();

app.MapPost("/api/servicecars/{vin}/toggle", async (string vin, AppDbContext db, ITenantContext t) =>
{
    vin = vin.Trim().ToUpperInvariant();
    var x = await db.ServiceCars.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.FrameNo == vin);
    if (x is null) return Results.NotFound(new { vin });
    x.FlagActive = x.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.FrameNo, flagActive = x.FlagActive });
}).RequireAuthorization();

// ===== Báo giá sửa chữa (ServiceQuotation — port 1:1 FrmQuotation, TCMotor) =====
app.MapGet("/api/servicequotations", async (AppDbContext db, ITenantContext t, string? q, string? status) =>
{
    var query = db.ServiceQuotations.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.QuoteNo.Contains(q!) || (x.RONo != null && x.RONo.Contains(q!)) || (x.PlateNo != null && x.PlateNo.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.QuoteNo, x.RONo, x.Vin, x.PlateNo, x.CusName, x.LaborTotal, x.PartTotal, x.Discount, x.VatAmount, x.GrandTotal, x.Status,
        // GAP đã vá: phần bảo hiểm trước đây không được trả về
        x.HasInsuranceItem, x.InsuranceDeductible, x.InsuranceTotal
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalValue = items.Sum(i => i.GrandTotal), items });
}).RequireAuthorization();

// Tạo báo giá: dòng công (giờ tt × đơn giá × hệ số) + dòng phụ tùng (SL × đơn giá), mỗi dòng cộng VAT; trừ chiết khấu.
app.MapPost("/api/servicequotations", async (ServiceQuotationDto dto, AppDbContext db, ITenantContext t) =>
{
    var labors = dto.Labors ?? new();
    var parts = dto.Parts ?? new();
    if (labors.Count == 0 && parts.Count == 0) return Results.BadRequest(new { error = "Báo giá phải có ít nhất 1 dòng công hoặc phụ tùng." });
    decimal laborBase = 0, partBase = 0, vatAmt = 0;
    var laborRows = new List<ServiceQuotationLabor>();
    foreach (var l in labors)
    {
        if (string.IsNullOrWhiteSpace(l.SerCode)) return Results.BadRequest(new { error = "Có dòng công thiếu mã CV." });
        var factor = l.Factor <= 0 ? 1 : l.Factor;
        var baseAmt = l.ActManHour * l.Price * factor;
        var amt = Math.Round(baseAmt * (1 + l.Vat / 100), 2);
        laborBase += baseAmt; vatAmt += amt - baseAmt;
        laborRows.Add(new ServiceQuotationLabor
        {
            OrgId = t.OrgId, SerCode = l.SerCode.Trim(), SerName = l.SerName, StdManHour = l.StdManHour,
            ActManHour = l.ActManHour, Factor = factor, Price = l.Price, Vat = l.Vat, Amount = amt,
            // GAP đã vá: phân loại chi phí + phần bảo hiểm chi trả (2 cột lưới gốc bị bỏ sót)
            ExpenseType = (l.ExpenseType ?? "").Trim(), InsurancePrice = l.InsurancePrice
        });
    }
    var partRows = new List<ServiceQuotationPart>();
    foreach (var p in parts)
    {
        if (string.IsNullOrWhiteSpace(p.PartCode)) return Results.BadRequest(new { error = "Có dòng phụ tùng thiếu mã." });
        var baseAmt = p.Quantity * p.Price;
        var amt = Math.Round(baseAmt * (1 + p.Vat / 100), 2);
        partBase += baseAmt; vatAmt += amt - baseAmt;
        partRows.Add(new ServiceQuotationPart
        {
            OrgId = t.OrgId, PartCode = p.PartCode.Trim(), PartName = p.PartName,
            Quantity = p.Quantity, Price = p.Price, Vat = p.Vat, Amount = amt,
            // GAP đã vá: phân loại chi phí + phần bảo hiểm chi trả (2 cột lưới gốc bị bỏ sót)
            ExpenseType = (p.ExpenseType ?? "").Trim(), InsurancePrice = p.InsurancePrice
        });
    }
    var discount = dto.Discount < 0 ? 0 : dto.Discount;
    var grand = laborBase + partBase + vatAmt - discount;
    if (grand < 0) return Results.BadRequest(new { error = "Chiết khấu vượt tổng giá trị báo giá." });

    // 🔴 GAP đã vá — luật checkInsuranceDeductible() của FrmQuotation:
    // "Mức khấu trừ bảo hiểm" CHỈ áp dụng khi báo giá có ÍT NHẤT 1 dòng ExpenseType = ROInsurance
    // (quét CẢ lưới công LẪN lưới phụ tùng). Không có dòng bảo hiểm → ô bị ẩn ⇒ mức khấu trừ phải = 0.
    const string InsuranceExpenseType = "ROInsurance";
    var hasInsuranceItem =
        laborRows.Any(labor => string.Equals(labor.ExpenseType, InsuranceExpenseType, StringComparison.OrdinalIgnoreCase)) ||
        partRows.Any(part => string.Equals(part.ExpenseType, InsuranceExpenseType, StringComparison.OrdinalIgnoreCase));

    var insuranceDeductible = dto.InsuranceDeductible < 0 ? 0 : dto.InsuranceDeductible;
    if (!hasInsuranceItem && insuranceDeductible > 0)
        return Results.BadRequest(new { error = "Báo giá không có dòng bảo hiểm, không nhập được mức khấu trừ bảo hiểm." });

    // Tổng phần bảo hiểm = tiền các dòng có ExpenseType = ROInsurance (dùng cho báo cáo/đối soát BH).
    var insuranceTotal =
        laborRows.Where(labor => string.Equals(labor.ExpenseType, InsuranceExpenseType, StringComparison.OrdinalIgnoreCase)).Sum(labor => labor.Amount) +
        partRows.Where(part => string.Equals(part.ExpenseType, InsuranceExpenseType, StringComparison.OrdinalIgnoreCase)).Sum(part => part.Amount);

    var no = "QT" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new ServiceQuotation { OrgId = t.OrgId, QuoteNo = no, RONo = dto.RONo, Vin = dto.Vin, PlateNo = dto.PlateNo, CusName = dto.CusName,
        LaborTotal = laborBase, PartTotal = partBase, Discount = discount, VatAmount = Math.Round(vatAmt, 2), GrandTotal = Math.Round(grand, 2), Status = "Draft", Note = dto.Note,
        // GAP đã vá: phần bảo hiểm của báo giá
        HasInsuranceItem = hasInsuranceItem, InsuranceDeductible = insuranceDeductible, InsuranceTotal = Math.Round(insuranceTotal, 2) };
    db.ServiceQuotations.Add(h); await db.SaveChangesAsync();
    foreach (var l in laborRows) { l.ServiceQuotationId = h.Id; db.ServiceQuotationLabors.Add(l); }
    foreach (var p in partRows) { p.ServiceQuotationId = h.Id; db.ServiceQuotationParts.Add(p); }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.QuoteNo, h.LaborTotal, h.PartTotal, h.VatAmount, h.GrandTotal });
}).RequireAuthorization();

app.MapGet("/api/servicequotations/{id}/detail", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.ServiceQuotations.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var labors = await db.ServiceQuotationLabors.Where(x => x.OrgId == t.OrgId && x.ServiceQuotationId == id)
        .Select(x => new { x.SerCode, x.SerName, x.StdManHour, x.ActManHour, x.Factor, x.Price, x.Vat, x.Amount }).ToListAsync();
    var parts = await db.ServiceQuotationParts.Where(x => x.OrgId == t.OrgId && x.ServiceQuotationId == id)
        .Select(x => new { x.PartCode, x.PartName, x.Quantity, x.Price, x.Vat, x.Amount }).ToListAsync();
    return Results.Ok(new { h.QuoteNo, h.RONo, h.PlateNo, h.CusName, h.LaborTotal, h.PartTotal, h.Discount, h.VatAmount, h.GrandTotal, h.Status, labors, parts });
}).RequireAuthorization();

app.MapPost("/api/servicequotations/{id}/status", async (long id, ServiceQuotationStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    var h = await db.ServiceQuotations.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var s = (dto.Status ?? "").Trim();
    if (s != "Draft" && s != "Approved" && s != "Cancelled") return Results.BadRequest(new { error = "Trạng thái không hợp lệ." });
    if (h.Status == "Approved" && s == "Draft") return Results.BadRequest(new { error = "Báo giá đã duyệt không thể quay lại Nháp." });
    h.Status = s; await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.Status });
}).RequireAuthorization();

// ===== Thống kê bảo hành theo chiều (report tái-dùng ServiceWarrantyClaim — port 1:1 FrmChartWarrantyDealer/Month + FrmTK_WarrantyModel, TCMotor) =====
// dimension: dealer | month | type. Đếm số ĐN + tổng tiền + số đã chấp thuận, gộp theo chiều.
app.MapGet("/api/report/warranty-stats", async (AppDbContext db, ITenantContext t, string? dimension, DateTime? fromDate, DateTime? toDate) =>
{
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId);
    if (fromDate.HasValue) q = q.Where(x => x.CreatedAt >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.CreatedAt < toDate.Value.Date.AddDays(1));
    var claims = await q.Select(x => new { x.DealerCode, x.WarrantyType, x.Amount, x.Status, x.CreatedAt }).ToListAsync();
    var dim = (dimension ?? "dealer").Trim().ToLowerInvariant();
    var keyed = claims.Select(c => new
    {
        key = dim == "month" ? c.CreatedAt.ToString("yyyy-MM") : dim == "type" ? (c.WarrantyType ?? "(không loại)") : (c.DealerCode ?? "(không rõ)"),
        c.Amount, c.Status
    });
    var rows = keyed.GroupBy(c => c.key).Select(g => new
    {
        key = g.Key, claims = g.Count(), totalAmount = g.Sum(x => x.Amount),
        accepted = g.Count(x => x.Status == "Accepted"), acceptedAmount = g.Where(x => x.Status == "Accepted").Sum(x => x.Amount)
    }).OrderByDescending(r => r.totalAmount).ToList();
    return Results.Ok(new { dimension = dim, count = rows.Count, totalClaims = claims.Count, grandAmount = rows.Sum(r => r.totalAmount), rows });
}).RequireAuthorization();

// ===== Báo cáo chiến dịch marketing (report tái-dùng ServiceCampaign — port 1:1 FrmReportCamMarketingHTC/FrmCamExportRpt, TCMotor) =====
app.MapGet("/api/report/campaign-marketing", async (AppDbContext db, ITenantContext t, string? status) =>
{
    var q = db.ServiceCampaigns.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    var cams = await q.OrderByDescending(x => x.Id).Select(x => new { x.Id, x.CamNo, x.CamName, x.ConditionDealer, x.Status, x.StartDate, x.EndDate }).ToListAsync();
    var partAgg = await db.ServiceCampaignParts.Where(p => p.OrgId == t.OrgId)
        .GroupBy(p => p.ServiceCampaignId)
        .Select(g => new { camId = g.Key, parts = g.Count(), avgDiscount = g.Average(x => x.PercentDiscount), maxDiscount = g.Max(x => x.PercentDiscount) }).ToListAsync();
    var pMap = partAgg.ToDictionary(x => x.camId, x => x);
    var rows = cams.Select(c => {
        pMap.TryGetValue(c.Id, out var pa);
        return new { c.CamNo, c.CamName, c.ConditionDealer, c.Status,
            startDate = c.StartDate.HasValue ? c.StartDate.Value.ToString("yyyy-MM-dd") : "",
            endDate = c.EndDate.HasValue ? c.EndDate.Value.ToString("yyyy-MM-dd") : "",
            parts = pa?.parts ?? 0, avgDiscount = pa != null ? Math.Round(pa.avgDiscount, 1) : 0m, maxDiscount = pa?.maxDiscount ?? 0m };
    }).ToList();
    var byStatus = cams.GroupBy(c => c.Status).Select(g => new { status = g.Key, count = g.Count() }).ToList();
    return Results.Ok(new { count = rows.Count, active = cams.Count(c => c.Status == "Active"), byStatus, rows });
}).RequireAuthorization();

// ===== Báo cáo bảo hành gửi DMS (report tái-dùng ServiceWarrantyClaim — port 1:1 FrmRpt_DMSSer_Rpt_DMSClaim, TCMotor) =====
// Các ĐN đã gửi lên DMS (Sent trở đi) + phân loại theo trạng thái duyệt + tỉ lệ chấp thuận.
app.MapGet("/api/report/dms-claim", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId && x.Status != "Pending"); // đã gửi DMS
    if (fromDate.HasValue) q = q.Where(x => x.CreatedAt >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.CreatedAt < toDate.Value.Date.AddDays(1));
    var claims = await q.Select(x => new { x.ClaimNo, x.DealerCode, x.Vin, x.PlateNo, x.WarrantyType, x.Amount, x.Status }).ToListAsync();
    var byStatus = claims.GroupBy(c => c.Status).Select(g => new { status = g.Key, count = g.Count(), amount = g.Sum(x => x.Amount) }).ToList();
    var accepted = claims.Count(c => c.Status == "Accepted");
    var decided = claims.Count(c => c.Status == "Accepted" || c.Status == "Rejected");
    var acceptRate = decided > 0 ? Math.Round((decimal)accepted / decided * 100, 1) : 0m;
    var rows = claims.OrderByDescending(c => c.Amount).Select(c => new { c.ClaimNo, c.DealerCode, c.Vin, c.PlateNo, c.WarrantyType, c.Amount, c.Status }).ToList();
    return Results.Ok(new { count = claims.Count, totalAmount = claims.Sum(c => c.Amount), accepted, acceptRate, byStatus, rows });
}).RequireAuthorization();

// ===== Báo cáo bảo hành theo phụ tùng chính (report tái-dùng ServiceWarrantyClaim — port 1:1 FrmReportWarranty_MainPart, TCMotor/Warranty) =====
// Top phụ tùng xuất hiện trong đề nghị bảo hành: số ĐN + tổng tiền + số đã chấp thuận theo mã PT.
app.MapGet("/api/report/warranty-by-part", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate, int? top) =>
{
    var n = top is > 0 and <= 200 ? top.Value : 30;
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId && x.PartCode != null && x.PartCode != "");
    if (fromDate.HasValue) q = q.Where(x => x.CreatedAt >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.CreatedAt < toDate.Value.Date.AddDays(1));
    var claims = await q.Select(x => new { x.PartCode, x.Amount, x.Status }).ToListAsync();
    var rows = claims.GroupBy(c => c.PartCode!).Select(g => new
    {
        partCode = g.Key, claims = g.Count(), totalAmount = g.Sum(x => x.Amount),
        accepted = g.Count(x => x.Status == "Accepted"), acceptedAmount = g.Where(x => x.Status == "Accepted").Sum(x => x.Amount)
    }).OrderByDescending(r => r.claims).ThenByDescending(r => r.totalAmount).Take(n).ToList();
    return Results.Ok(new { count = rows.Count, totalClaims = claims.Count, grandAmount = rows.Sum(r => r.totalAmount), rows });
}).RequireAuthorization();

// ===== Báo cáo yêu cầu bảo hành TCG (report tái-dùng WarrantyClaimTC — port 1:1 FrmClaimReport, 2010.HTC/Report) =====
// Thống kê YCBH theo trạng thái + theo đại lý + tỉ lệ chấp thuận, lọc khoảng ngày.
app.MapGet("/api/report/tcg-warranty-claim", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate, string? dealer) =>
{
    var q = db.WarrantyClaims.Where(x => x.OrgId == t.OrgId);
    if (fromDate.HasValue) q = q.Where(x => x.CreatedAt >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.CreatedAt < toDate.Value.Date.AddDays(1));
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    var claims = await q.Select(x => new { x.DealerCode, x.Status }).ToListAsync();
    var byStatus = claims.GroupBy(c => c.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var byDealer = claims.GroupBy(c => c.DealerCode).Select(g => new
    {
        dealerCode = g.Key, total = g.Count(),
        approved = g.Count(x => x.Status == "Approved" || x.Status == "Paid"), rejected = g.Count(x => x.Status == "Rejected")
    }).OrderByDescending(x => x.total).ToList();
    var decided = claims.Count(c => c.Status == "Approved" || c.Status == "Paid" || c.Status == "Rejected");
    var accepted = claims.Count(c => c.Status == "Approved" || c.Status == "Paid");
    return Results.Ok(new { total = claims.Count, accepted, acceptRate = decided > 0 ? Math.Round((decimal)accepted / decided * 100, 1) : 0m, byStatus, byDealer });
}).RequireAuthorization();

// ===== Báo cáo hợp đồng đại lý (report tái-dùng DealerContract + DealerContractDetail — port 1:1 FrmContractReportForDealer, 2010.HTC/Report) =====
// Gộp HĐ đại lý theo đại lý = số HĐ + số xe + tổng giá trị (đơn giá), lọc trạng thái.
app.MapGet("/api/report/dealer-contracts", async (AppDbContext db, ITenantContext t, string? dealer, string? status) =>
{
    var q = db.DealerContracts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    var contracts = await q.Select(x => new { x.Id, x.DealerCode, x.Status }).ToListAsync();
    var cids = contracts.Select(c => c.Id).ToHashSet();
    var details = await db.DealerContractDetails.Where(x => x.OrgId == t.OrgId).Select(x => new { x.DealerContractId, x.UnitPrice }).ToListAsync();
    var detByC = details.Where(x => cids.Contains(x.DealerContractId)).GroupBy(x => x.DealerContractId)
        .ToDictionary(g => g.Key, g => new { cars = g.Count(), value = g.Sum(x => x.UnitPrice) });
    var rows = contracts.GroupBy(c => c.DealerCode ?? "(không rõ)").Select(g =>
    {
        int cars = 0; decimal val = 0;
        foreach (var c in g) if (detByC.TryGetValue(c.Id, out var v)) { cars += v.cars; val += v.value; }
        return new { dealerCode = g.Key, contracts = g.Count(), cars, totalValue = val };
    }).OrderByDescending(r => r.totalValue).ToList();
    return Results.Ok(new { count = rows.Count, totalContracts = rows.Sum(r => r.contracts), totalCars = rows.Sum(r => r.cars), grandValue = rows.Sum(r => r.totalValue), rows });
}).RequireAuthorization();

// ===== Báo cáo bán hàng đại lý (retail) (report tái-dùng DealerDeal + DealerDealDetail — port 1:1 FrmBanHangDL, 2010.HTC/Report) =====
// Bán lẻ đại lý→khách: gộp theo đại lý = số HĐ + số xe + tổng giá trị (giá sau VAT), lọc khoảng ngày lập HĐ.
app.MapGet("/api/report/dealer-retail-sales", async (AppDbContext db, ITenantContext t, string? dealer, DateTime? fromDate, DateTime? toDate) =>
{
    var q = db.DealerDeals.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (fromDate.HasValue) q = q.Where(x => x.DealDate >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.DealDate < toDate.Value.Date.AddDays(1));
    var deals = await q.Select(x => new { x.Id, x.DealerCode }).ToListAsync();
    var dealIds = deals.Select(d => d.Id).ToHashSet();
    var details = await db.DealerDealDetails.Where(x => x.OrgId == t.OrgId).Select(x => new { x.DealId, x.PriceAFVAT }).ToListAsync();
    var detByDeal = details.Where(x => dealIds.Contains(x.DealId)).GroupBy(x => x.DealId)
        .ToDictionary(g => g.Key, g => new { cars = g.Count(), value = g.Sum(x => x.PriceAFVAT) });
    var rows = deals.GroupBy(d => d.DealerCode ?? "(không rõ)").Select(g =>
    {
        int cars = 0; decimal val = 0;
        foreach (var d in g) if (detByDeal.TryGetValue(d.Id, out var v)) { cars += v.cars; val += v.value; }
        return new { dealerCode = g.Key, deals = g.Count(), cars, totalValue = val };
    }).OrderByDescending(r => r.totalValue).ToList();
    return Results.Ok(new { count = rows.Count, totalDeals = rows.Sum(r => r.deals), totalCars = rows.Sum(r => r.cars), grandValue = rows.Sum(r => r.totalValue), rows });
}).RequireAuthorization();

// ===== Báo cáo gợi ý đặt hàng (report tái-dùng SalesOrder + SalesOrderLine — port 1:1 FrmBCGoiYDatHang, 2010.HTC/Sales) =====
// Gợi ý SL đặt = TB nhu cầu tháng (tổng SL đặt N tháng gần nhất / N) × hệ số; gom theo đại lý + model.
app.MapGet("/api/report/order-suggestion", async (AppDbContext db, ITenantContext t, int? months, decimal? factor, string? dealer) =>
{
    var n = months is > 0 and <= 24 ? months.Value : 6;
    var f = factor is > 0 and <= 6 ? factor.Value : 1m;
    var cutoff = DateTime.Today.AddMonths(-n);
    var soIds = db.SalesOrders.Where(o => o.OrgId == t.OrgId && o.CreatedAt >= cutoff && (o.Status == "A1" || o.Status == "A2" || o.Status == "P"));
    if (!string.IsNullOrWhiteSpace(dealer)) soIds = soIds.Where(o => o.DealerCode == dealer);
    var lines = await (from l in db.SalesOrderLines.Where(x => x.OrgId == t.OrgId)
                       join o in soIds on l.SalesOrderId equals o.Id
                       select new { o.DealerCode, l.ModelCode, l.SpecCode, l.RequestedQuantity }).ToListAsync();
    var rows = lines.GroupBy(x => new { x.DealerCode, x.ModelCode, spec = x.SpecCode ?? "" })
        .Select(g => {
            var total = g.Sum(x => x.RequestedQuantity);
            var avg = Math.Round((decimal)total / n, 1);
            return new { g.Key.DealerCode, g.Key.ModelCode, spec = g.Key.spec, totalQty = total, avgMonthly = avg, suggestOrder = (int)Math.Ceiling(avg * f) };
        }).OrderBy(r => r.DealerCode).ThenByDescending(r => r.totalQty).ToList();
    return Results.Ok(new { months = n, factor = f, count = rows.Count, totalSuggest = rows.Sum(r => r.suggestOrder), rows });
}).RequireAuthorization();

// ===== Báo cáo doanh thu dịch vụ (report tái-dùng ServiceInvoice — port 1:1 FrmAccTotalRevenue + FrmSer_InvReportRevenueRpt, TCMotor) =====
// Gộp hóa đơn theo tháng: tiền hàng (subtotal) + VAT − chiết khấu = tổng; tách đã thu (Paid) vs chưa thu.
app.MapGet("/api/report/service-revenue", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var q = db.ServiceInvoices.Where(x => x.OrgId == t.OrgId);
    if (fromDate.HasValue) q = q.Where(x => x.CreatedAt >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.CreatedAt < toDate.Value.Date.AddDays(1));
    var invs = await q.Select(x => new { x.SubTotal, x.VatAmount, x.DiscountAmount, x.TotalAmount, x.Status, x.CreatedAt }).ToListAsync();
    var byMonth = invs.GroupBy(x => x.CreatedAt.ToString("yyyy-MM")).Select(g => new
    {
        month = g.Key, invoices = g.Count(),
        subTotal = g.Sum(x => x.SubTotal), vat = g.Sum(x => x.VatAmount), discount = g.Sum(x => x.DiscountAmount), total = g.Sum(x => x.TotalAmount),
        paid = g.Where(x => x.Status == "Paid").Sum(x => x.TotalAmount), unpaid = g.Where(x => x.Status != "Paid").Sum(x => x.TotalAmount)
    }).OrderByDescending(x => x.month).ToList();
    return Results.Ok(new
    {
        totalInvoices = invs.Count,
        grandTotal = invs.Sum(x => x.TotalAmount), grandSubTotal = invs.Sum(x => x.SubTotal), grandVat = invs.Sum(x => x.VatAmount),
        grandPaid = invs.Where(x => x.Status == "Paid").Sum(x => x.TotalAmount), grandUnpaid = invs.Where(x => x.Status != "Paid").Sum(x => x.TotalAmount),
        byMonth
    });
}).RequireAuthorization();

// ===== KPI dịch vụ tổng hợp (report tái-dùng RepairOrder + ServiceInvoice — port 1:1 FrmReportKPI/FrmReportCollectiveDisplay_KPI/FrmRpt_Correct_Repair_Rate, TCMotor) =====
app.MapGet("/api/report/service-kpi", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var qro = db.RepairOrders.Where(x => x.OrgId == t.OrgId);
    if (fromDate.HasValue) qro = qro.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) qro = qro.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date <= toDate.Value.Date);
    var ros = await qro.Select(x => x.Status).ToListAsync();
    var totalRO = ros.Count;
    var finished = ros.Count(s => s == "Finished");
    var byStatus = ros.GroupBy(s => s).Select(g => new { status = g.Key, count = g.Count() }).ToList();
    // Tỉ lệ hoàn tất (giao xe) — proxy cho "sửa đúng, hoàn thành".
    var correctRate = totalRO > 0 ? Math.Round((decimal)finished / totalRO * 100, 1) : 0m;

    var qinv = db.ServiceInvoices.Where(x => x.OrgId == t.OrgId);
    if (fromDate.HasValue) qinv = qinv.Where(x => x.CreatedAt >= fromDate.Value.Date);
    if (toDate.HasValue) qinv = qinv.Where(x => x.CreatedAt < toDate.Value.Date.AddDays(1));
    var invs = await qinv.Select(x => new { x.TotalAmount, x.Status }).ToListAsync();
    var paidInv = invs.Where(i => i.Status == "Paid").ToList();
    var revenue = paidInv.Sum(i => i.TotalAmount);
    var avgTicket = paidInv.Count > 0 ? Math.Round(revenue / paidInv.Count, 0) : 0m;

    return Results.Ok(new
    {
        totalRO, finished, correctRate, byStatus,
        totalInvoices = invs.Count, paidInvoices = paidInv.Count, revenue, avgTicket,
        unpaidInvoices = invs.Count(i => i.Status != "Paid")
    });
}).RequireAuthorization();

// ===== Tần suất dịch vụ theo xe (port 1:1 `FrmRpt_Vehicle_Service_Frequency`, TCMotor) =====
// Mỗi VIN: số lượt vào xưởng + khoảng cách TB (ngày) giữa các lượt liên tiếp (chỉ xe >=2 lượt mới có tần suất).
//
// ===== 🔴 #376 ĐỐI CHIẾU BẢN GỐC ↔ BẢN `_WH` (hai hàm song sinh, KHÁC NHAU HƠN LÀ ĐỔI CSDL) =====
// Nguồn có cặp `Rpt_Vehicle_Service_Frequency` (`:6845`) / `…_WH` (`:7080`), và cặp
// `Rpt_Correct_Repair_Rate` (`:6440`) / `…_WH` (`:6643`). Diff từng dòng cho thấy **ba** khác biệt thật:
//
// 🔴 1. **BA CSDL, không phải hai**: `Rpt_Vehicle_Service_Frequency` chạy trên `_dbDealer` (**DB đại lý**),
//    `Rpt_Correct_Repair_Rate` chạy trên `_dbMain`, còn cả hai bản `_WH` chạy trên `_dbWH`.
//    ⇒ Đừng giả định 'bản thường = Main'; phải đọc đúng đối tượng `_db*` mà hàm gọi.
// 🔴 2. **BỘ LỌC KHÁC NHAU giữa hai bản**: ở `Rpt_Correct_Repair_Rate` dòng
//    `and (sr.ReceptionFNo is not null or sr.ReceptionFNo != '')` bị **COMMENT** trong bản thường
//    nhưng **ĐANG CHẠY** trong bản `_WH` ⇒ hai báo cáo cùng tên trả **tập dòng khác nhau**.
//    ⚠️ Bản thân điều kiện đó **viết sai phép logic**: dùng `or` nên chuỗi RỖNG vẫn lọt
//      (`'' is not null` = TRUE). Muốn loại cả NULL lẫn rỗng phải là `and`. Giữ 1:1: chỉ loại NULL.
// 🔴 3. **CHỖ GIỮ DANH MỤC MODEL KHÁC NHAU**: bản thường `left join [@strDBName_CommonCenter].[dbo].Ser_MST_Model`,
//    bản `_WH` `left join Ser_MST_Model` (bảng cục bộ).
//    ⚠️ Và placeholder `@strDBName_CommonCenter` được **gán bằng `_strConfig_DBName_Main`** — tên nói
//      'CommonCenter' nhưng giá trị là **DB Main**. Lại một cái tên nói dối (cùng lệ #375).
//
// MiniHTC dùng một CSDL nên không tái hiện được ba-CSDL; `scope` chỉ tái hiện **khác biệt BỘ LỌC**
// và trả kèm ghi chú để không ai tưởng port thiếu.
app.MapGet("/api/report/vehicle-frequency", async (AppDbContext db, ITenantContext t, int? minVisits,
    string? scope, string? dealers, DateTime? from, DateTime? to) =>
{
    var minV = minVisits is > 0 ? minVisits.Value : 2;
    var wh = (scope ?? "main").Trim().ToLowerInvariant() == "wh";

    var codes = (dealers ?? "").Split('|', StringSplitOptions.RemoveEmptyEntries)
        .Select(x => x.Trim().ToUpperInvariant()).Where(x => x.Length > 0).ToList();

    var qy = db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.Vin != null && x.Vin != "" && x.CheckInDate.HasValue);
    if (codes.Count > 0) qy = qy.Where(x => x.DealerCode != null && codes.Contains(x.DealerCode));
    if (from is not null) qy = qy.Where(x => x.CheckInDate >= from);
    if (to is not null) qy = qy.Where(x => x.CheckInDate <= to);
    // Chỉ bản _WH bật bộ lọc này; và đúng nguồn thì nó CHỈ loại NULL (phép `or` làm rỗng vẫn lọt).
    if (wh) qy = qy.Where(x => x.ReceptionFNo != null);

    var ros = await qy.Select(x => new { x.Vin, x.CusName, x.CheckInDate }).ToListAsync();
    var rows = ros.GroupBy(x => x.Vin!).Select(g =>
    {
        var dates = g.Select(x => x.CheckInDate!.Value.Date).OrderBy(d => d).ToList();
        double avgGap = 0;
        if (dates.Count >= 2)
        {
            double sum = 0;
            for (int i = 1; i < dates.Count; i++) sum += (dates[i] - dates[i - 1]).TotalDays;
            avgGap = Math.Round(sum / (dates.Count - 1), 1);
        }
        return new { vin = g.Key, cusName = g.Select(x => x.CusName).FirstOrDefault(x => x != null),
            visits = dates.Count, firstVisit = dates.First().ToString("yyyy-MM-dd"), lastVisit = dates.Last().ToString("yyyy-MM-dd"), avgGapDays = avgGap };
    }).Where(r => r.visits >= minV).OrderByDescending(r => r.visits).ThenBy(r => r.avgGapDays).ToList();
    return Results.Ok(new
    {
        minVisits = minV, count = rows.Count,
        avgVisits = rows.Count > 0 ? Math.Round(rows.Average(r => (double)r.visits), 1) : 0,
        rows,
        scope = wh ? "wh" : "main",
        dealerFilter = codes,
        receptionFilterApplied = wh,
        filterDivergenceNote = "Bộ lọc `ReceptionFNo` bị COMMENT ở bản thường nhưng ĐANG CHẠY ở bản _WH "
            + "⇒ hai báo cáo cùng tên trả tập dòng khác nhau.",
        brokenConditionNote = "Nguồn viết `(x is not null or x <> '')` — dùng `or` nên chuỗi RỖNG vẫn lọt; "
            + "chỉ NULL bị loại. Giữ nguyên 1:1, không tự sửa thành `and`.",
        threeDatabasesNote = "Nguồn: bản này chạy trên DB ĐẠI LÝ, Rpt_Correct_Repair_Rate chạy trên Main, "
            + "cả hai bản _WH chạy trên WH. MiniHTC một CSDL nên không tái hiện được.",
        commonCenterNameLieNote = "Placeholder @strDBName_CommonCenter được gán bằng _strConfig_DBName_Main "
            + "— tên nói CommonCenter nhưng giá trị là DB Main.",
    });
}).RequireAuthorization();

// ===== 🔴 #311 KHẢ NĂNG CUNG ỨNG PHỤ TÙNG — viết lại theo nguồn `Rpt_AbilitySupplyParts` =====
// Nguồn: `BizCarSv.Inventory.Report.cs:8303` (LIVE). 🆕 Đến được nhờ rà **17 hit "lệch trục"** của sweep
//   `top 1` (#308/#310): ba cặp `select f.StockOutID/StockOutTime … order by f.StockOutNo asc` nằm trong
//   báo cáo này.
//
// ⚠️ Bản cũ ở đây là **HÀNG TỰ CHẾ**: gom `ServicePartOO` theo mã PT rồi chia ra %,. Nguồn KHÔNG làm vậy —
//   nó đi từ **LỆNH SỬA CHỮA** → lệnh xuất kho → **bảng nối** (#294) → phiếu xuất, rồi tính đáp ứng.
//
// 🔴 BỐN điểm nguồn mà bản tự chế sai hẳn:
//  1. **Lọc RO là BLACKLIST, không phải whitelist.** Nguồn: `t.Status NOT IN (Wait4Part, HasPart,
//     NotResponding, RejectRO)` ⇒ **LOẠI** bốn trạng thái đó, giữ mọi trạng thái còn lại (kể cả mã lạ).
//     Đọc lướt rất dễ hiểu ngược thành "chỉ lấy bốn trạng thái này".
//  2. **Kỳ báo cáo theo THÁNG** (`strPeriodMonth`) lọc trên `CreatedDate` của LỆNH, từ ngày đầu đến ngày
//     cuối tháng — không phải khoảng ngày tuỳ ý.
//  3. **Phiếu xuất đại diện = phiếu ĐẦU TIÊN theo SỐ**, không phải mới nhất:
//     `select top 1 f.StockOutID … where f.Status = '3' order by f.StockOutNo **asc**`.
//     ⚠️ `StockOutNo` là **CHUỖI** ⇒ sắp tăng dần theo chuỗi, chỉ đúng thứ tự thời gian nếu cách đánh số
//       giữ được thứ tự từ điển. Đây là giả định của nguồn, giữ nguyên và ghi lại.
//     ⚠️ Nguồn viết **HAI subquery giống hệt** (một lấy `StockOutID`, một lấy `StockOutTime`) cùng `order by`
//       ⇒ hai giá trị chắc chắn cùng một dòng. Port lấy một lần rồi tách ra.
//  4. **Tỉ lệ đáp ứng là CHUỖI "đã/cần"**, KHÔNG phải phần trăm: `CONCAT(ResponseQuantityTotal, '/',
//     RequestQuantityTotal)`. Có **HAI** tỉ lệ khác nhau: theo **mã phụ tùng** và theo **LỆNH**.
//     Bản cũ trả `fillRate` % ⇒ khác hẳn con số người dùng quen đọc.
//
// 📌 Đã kiểm và KHÔNG phải lỗi: `f.Status = '@strStatusFinish'` trông giống bẫy **[BAKE-PARAM-MIX]**
//   (nháy bao quanh tham số), nhưng `@strStatusFinish` được **bake** bằng `StringUtils.Replace` với
//   `TConst.Ser_Inv_StockOut.Finished` = `"3"` (`:8779`) ⇒ thành `'3'`, hợp lệ.
//
// 📌 NỢ ĐÃ KHAI: nguồn còn tham số `strRespondType` và bảng `…NotResponse` (chi tiết PT **không** đáp ứng,
//   có nhánh `case when h.ResponseQuantity is null then t.NotResponseQuantity else h.NotResponseQuantity`).
//   Port lượt này làm **hai tỉ lệ + danh sách đáp ứng/không đáp ứng theo mã PT**; nhánh RespondType chưa làm.
app.MapGet("/api/report/part-supply-ability", async (AppDbContext db, ITenantContext t,
    string? periodMonth, string? dealer, string? partCode) =>
{
    // Kỳ: mặc định tháng hiện tại. Nguồn lọc CreatedDate của LỆNH trong [đầu tháng, cuối tháng].
    var baseMonth = DateTime.TryParse((periodMonth ?? "") + "-01", out var pm) ? pm : new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1);
    var monthFrom = new DateTime(baseMonth.Year, baseMonth.Month, 1);
    var monthTo = monthFrom.AddMonths(1);

    // 1. LỆNH trong kỳ — BLACKLIST bốn trạng thái (đúng nguồn: NOT IN).
    var excluded = new[] { "Wait4Part", "HasPart", "NotResponding", "Rejected" };
    var roQuery = db.RepairOrders.Where(r => r.OrgId == t.OrgId
        && r.CreatedAt >= monthFrom && r.CreatedAt < monthTo
        && !excluded.Contains(r.Status));
    if (!string.IsNullOrWhiteSpace(dealer)) roQuery = roQuery.Where(r => r.DealerCode == dealer!.Trim().ToUpperInvariant());
    var ros = await roQuery.Select(r => new { r.Id, r.RONo }).ToListAsync();
    var roIds = ros.Select(x => x.Id).ToList();
    var roNos = ros.Select(x => x.RONo).ToList();

    // 2. Lệnh xuất kho của các lệnh đó → bảng nối (#294) → phiếu xuất ĐÃ KẾT THÚC ("3").
    var orders = await db.SerStockOutOrders
        .Where(o => o.OrgId == t.OrgId && o.RONo != null && roNos.Contains(o.RONo))
        .Select(o => new { o.Id, o.RONo }).ToListAsync();
    var orderIds = orders.Select(o => o.Id).ToList();

    var links = await (from lk in db.SerStockOutOrderStockOuts
                       join so in db.PartStockOuts on lk.StockOutId equals so.Id
                       where lk.OrgId == t.OrgId && so.OrgId == t.OrgId
                             && orderIds.Contains(lk.StockOutOrderId)
                             && so.Status == "3"                       // TConst.Ser_Inv_StockOut.Finished
                       select new { lk.StockOutOrderId, so.Id, so.StockOutNo, so.StockOutDate, so.StockOutDateTime })
                      .ToListAsync();
    // Phiếu ĐẠI DIỆN của mỗi lệnh xuất: ĐẦU TIÊN theo SỐ (chuỗi) tăng dần — đúng nguồn.
    var firstByOrder = links.GroupBy(x => x.StockOutOrderId)
        .ToDictionary(g => g.Key, g => g.OrderBy(x => x.StockOutNo, StringComparer.Ordinal).First());

    // 3. Dòng phụ tùng: cần (theo lệnh xuất) vs đã xuất (theo phiếu đại diện).
    var needLines = await db.SerStockOutOrderLines
        .Where(l => l.OrgId == t.OrgId && orderIds.Contains(l.OrderId)).ToListAsync();
    var doneStockOutIds = firstByOrder.Values.Select(v => v.Id).ToList();
    var doneLines = await db.PartStockOutLines
        .Where(l => l.OrgId == t.OrgId && doneStockOutIds.Contains(l.StockOutId)).ToListAsync();

    if (!string.IsNullOrWhiteSpace(partCode))
    {
        var pc = partCode!.Trim().ToUpperInvariant();
        needLines = needLines.Where(l => l.PartCode == pc).ToList();
        doneLines = doneLines.Where(l => l.PartCode == pc).ToList();
    }

    var needByPart = needLines.GroupBy(l => l.PartCode).ToDictionary(g => g.Key, g => g.Sum(x => x.OrderQuantity));
    // PartStockOutLine dung cot Quantity (khac SerStockOutOrderLine dung OrderQuantity).
    var doneByPart = doneLines.GroupBy(l => l.PartCode).ToDictionary(g => g.Key, g => g.Sum(x => x.Quantity));

    var byPart = needByPart.Keys.Union(doneByPart.Keys).OrderBy(k => k).Select(pc =>
    {
        var need = needByPart.TryGetValue(pc, out var n) ? n : 0m;
        var done = doneByPart.TryGetValue(pc, out var d) ? d : 0m;
        return new
        {
            partCode = pc,
            requestQuantity = need, responseQuantity = done,
            notResponseQuantity = need - done > 0 ? need - done : 0m,
            // ⚠️ CHUỖI "đã/cần" đúng nguồn, KHÔNG phải phần trăm.
            responseRateByPartCode = done.ToString("0.##") + "/" + need.ToString("0.##"),
            responded = done > 0,
        };
    }).ToList();

    // 4. Tỉ lệ theo LỆNH: số lệnh có phiếu xuất đã kết thúc / tổng số lệnh trong kỳ.
    var respondedOrderIds = firstByOrder.Keys.ToHashSet();
    var roResponded = orders.Where(o => respondedOrderIds.Contains(o.Id)).Select(o => o.RONo).Distinct().Count();
    var roQuantity = ros.Count;

    return Results.Ok(new
    {
        periodMonth = monthFrom.ToString("yyyy-MM"),
        roQuantity, roResponseQuantity = roResponded,
        responseRateByRO = roResponded + "/" + roQuantity,
        count = byPart.Count,
        responded = byPart.Where(x => x.responded),
        notResponded = byPart.Where(x => !x.responded),
        rows = byPart,
        note = "Tỉ lệ là CHUỖI \"đã/cần\" đúng nguồn, KHÔNG phải %. Lọc lệnh là BLACKLIST (loại "
             + "Wait4Part/HasPart/NotResponding/Rejected). Phiếu xuất đại diện = ĐẦU TIÊN theo SỐ (chuỗi) tăng dần.",
        debtNote = "Chưa port: tham số RespondType và nhánh NotResponseQuantity hai tầng của nguồn.",
    });
}).RequireAuthorization();

// #311 Bản CŨ (tự chế, gom ServicePartOO theo mã PT rồi ra %). GIỮ ở route riêng để không vỡ client đang
//   dùng, nhưng KHÔNG còn là "port 1:1" — con số khác hẳn nguồn.
app.MapGet("/api/report/part-supply-ability-legacy", async (AppDbContext db, ITenantContext t) =>
{
    var agg = await db.ServicePartOOs.Where(x => x.OrgId == t.OrgId)
        .GroupBy(x => x.PartCode)
        .Select(g => new { partCode = g.Key, needed = g.Sum(x => x.QtyNeeded), fulfilled = g.Sum(x => x.QtyFulfilled), orders = g.Count(), openOrders = g.Count(x => x.Status == "Open") })
        .ToListAsync();
    var rows = agg.Select(a => new { a.partCode, a.needed, a.fulfilled, backorder = a.needed - a.fulfilled, a.orders, a.openOrders,
            fillRate = a.needed > 0 ? Math.Round(a.fulfilled / a.needed * 100, 1) : 100m })
        .OrderBy(r => r.fillRate).ThenByDescending(r => r.backorder).ToList();
    var totNeed = rows.Sum(r => r.needed); var totFill = rows.Sum(r => r.fulfilled);
    return Results.Ok(new { count = rows.Count, totalNeeded = totNeed, totalFulfilled = totFill,
        overallFillRate = totNeed > 0 ? Math.Round(totFill / totNeed * 100, 1) : 100m, rows });
}).RequireAuthorization();

// ===== Khách lâu không quay lại (report tái-dùng RepairOrder — port 1:1 FrmReportCustomerNotBack, TCMotor) =====
// Xe/khách có lần vào xưởng gần nhất cách đây > N tháng (mặc định 6) — cần chăm sóc kéo về.
app.MapGet("/api/report/customer-notback", async (AppDbContext db, ITenantContext t, int? months) =>
{
    var n = months is > 0 and <= 60 ? months.Value : 6;
    var cutoff = DateTime.Today.AddMonths(-n);
    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.CheckInDate.HasValue)
        .Select(x => new { x.Vin, x.CusName, x.LicensePlate, x.CheckInDate }).ToListAsync();
    var rows = ros.GroupBy(x => new { vin = x.Vin ?? "", cus = x.CusName ?? "", plate = x.LicensePlate ?? "" })
        .Select(g => new { g.Key.vin, cusName = g.Key.cus, plateNo = g.Key.plate, visits = g.Count(), lastVisit = g.Max(x => x.CheckInDate!.Value) })
        .Where(r => r.lastVisit < cutoff)
        .OrderBy(r => r.lastVisit)
        .Select(r => new { r.vin, r.cusName, r.plateNo, r.visits, lastVisit = r.lastVisit.ToString("yyyy-MM-dd"), daysSince = (int)(DateTime.Today - r.lastVisit.Date).TotalDays })
        .ToList();
    return Results.Ok(new { months = n, count = rows.Count, rows });
}).RequireAuthorization();

// ===== Phụ tùng luân chuyển chậm (report tái-dùng ServicePart + ServiceStockOut — port 1:1 FrmRpt_SlowRotationParts, TCMotor) =====
// PT còn tồn nhưng SL xuất N tháng gần nhất thấp/bằng 0 — ứ đọng vốn.
app.MapGet("/api/report/slow-rotation-parts", async (AppDbContext db, ITenantContext t, int? months) =>
{
    var n = months is > 0 and <= 36 ? months.Value : 6;
    var cutoff = DateTime.Today.AddMonths(-n);
    var outIds = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed" && o.StockOutDate.HasValue && o.StockOutDate >= cutoff).Select(o => o.Id);
    var outByPart = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && outIds.Contains(l.ServiceStockOutId))
        .GroupBy(l => l.PartCode).Select(g => new { partCode = g.Key, qty = g.Sum(x => x.Quantity) }).ToListAsync();
    var outMap = outByPart.ToDictionary(x => x.partCode, x => x.qty);
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId && p.FlagActive == "1" && p.Quantity > 0)
        .Select(p => new { p.PartCode, p.PartName, p.Unit, p.Quantity, p.Cost }).ToListAsync();
    var rows = parts.Select(p => {
        var outQ = outMap.TryGetValue(p.PartCode, out var v) ? v : 0m;
        return new { p.PartCode, p.PartName, p.Unit, stock = p.Quantity, soldInPeriod = outQ, stockValue = p.Quantity * p.Cost };
    }).Where(r => r.soldInPeriod == 0 || r.soldInPeriod < r.stock * 0.1m)  // xuất < 10% tồn hoặc không xuất
      .OrderByDescending(r => r.stockValue).ToList();
    return Results.Ok(new { months = n, count = rows.Count, tiedUpValue = rows.Sum(r => r.stockValue), rows });
}).RequireAuthorization();

// ===== Xe còn hạn bảo hành (report tái-dùng ServiceCar — port 1:1 FrmTK_XeConHanBaoHanh, TCMotor) =====
app.MapGet("/api/report/cars-under-warranty", async (AppDbContext db, ITenantContext t, int? soonDays) =>
{
    var soon = soonDays is > 0 and <= 365 ? soonDays.Value : 30;
    var today = DateTime.Today;
    var cars = await db.ServiceCars.Where(v => v.OrgId == t.OrgId && v.WarrantyDate.HasValue && v.WarrantyDate.Value >= today)
        .Select(v => new { v.FrameNo, v.PlateNo, v.ModelCode, v.CusName, v.WarrantyDate }).ToListAsync();
    var rows = cars.Select(v => new { v.FrameNo, v.PlateNo, v.ModelCode, v.CusName,
            warrantyDate = v.WarrantyDate!.Value.ToString("yyyy-MM-dd"), daysLeft = (int)(v.WarrantyDate.Value.Date - today).TotalDays })
        .OrderBy(v => v.daysLeft).ToList();
    return Results.Ok(new { count = rows.Count, expiringSoon = rows.Count(r => r.daysLeft <= soon), soonDays = soon, rows });
}).RequireAuthorization();

// ===== Bảng theo dõi tiến độ sửa chữa (report tái-dùng RepairOrder — port 1:1 FrmDealerHistoryShareMng/Display, TCMotor) =====
// Danh sách RO theo trạng thái tiến độ + đếm theo từng trạng thái (bảng điều hành xưởng).
app.MapGet("/api/report/ro-status-board", async (AppDbContext db, ITenantContext t, string? status, DateTime? fromDate, DateTime? toDate) =>
{
    var q = db.RepairOrders.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (fromDate.HasValue) q = q.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date <= toDate.Value.Date);
    var rows = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.RONo, x.LicensePlate, x.Vin, x.CusName, x.CusRequest, x.Status, x.CusWaiting,
        checkInDate = x.CheckInDate.HasValue ? x.CheckInDate.Value.ToString("yyyy-MM-dd") : "",
        planedDelivery = x.PlanedDeliveryDate.HasValue ? x.PlanedDeliveryDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    // Đếm theo mọi trạng thái trong phạm vi ngày (không phụ thuộc filter status).
    var qAll = db.RepairOrders.Where(x => x.OrgId == t.OrgId);
    if (fromDate.HasValue) qAll = qAll.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) qAll = qAll.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date <= toDate.Value.Date);
    var byStatus = await qAll.GroupBy(x => x.Status).Select(g => new { status = g.Key, count = g.Count() }).ToListAsync();
    return Results.Ok(new { count = rows.Count, byStatus, rows });
}).RequireAuthorization();

// ===== Báo cáo đếm lượt khách dịch vụ (report tái-dùng RepairOrder — port 1:1 FrmReportCountCus/_OnlyHTC/_ToHTC, TCMotor) =====
// Đếm số lượt vào xưởng (RO) theo từng xe/khách; phân loại khách mới (1 lượt) vs quay lại (>1 lượt); lọc khoảng ngày check-in.
app.MapGet("/api/report/customer-visits", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate, string? kind) =>
{
    var q = db.RepairOrders.Where(x => x.OrgId == t.OrgId);
    if (fromDate.HasValue) q = q.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) q = q.Where(x => x.CheckInDate.HasValue && x.CheckInDate.Value.Date <= toDate.Value.Date);
    var ros = await q.Select(x => new { x.Vin, x.CusName, x.CheckInDate }).ToListAsync();
    var grouped = ros.GroupBy(x => new { vin = x.Vin ?? "", cus = x.CusName ?? "" }).Select(g => new
    {
        vin = g.Key.vin, cusName = g.Key.cus, visits = g.Count(),
        lastVisit = g.Max(x => x.CheckInDate).HasValue ? g.Max(x => x.CheckInDate)!.Value.ToString("yyyy-MM-dd") : ""
    }).ToList();
    // kind: new (1 lượt) | returning (>1 lượt) | all
    var k = (kind ?? "all").Trim().ToLowerInvariant();
    var rows = (k == "new" ? grouped.Where(r => r.visits == 1)
             : k == "returning" ? grouped.Where(r => r.visits > 1)
             : grouped).OrderByDescending(r => r.visits).ToList();
    return Results.Ok(new
    {
        totalCustomers = grouped.Count, totalVisits = grouped.Sum(r => r.visits),
        newCustomers = grouped.Count(r => r.visits == 1), returningCustomers = grouped.Count(r => r.visits > 1),
        count = rows.Count, rows
    });
}).RequireAuthorization();

// ===== Ngày đăng ký bảo hành theo VIN (ServiceCar.WarrantyRegistrationDate — port 1:1 FrmHTCSearch/UpdateWarrantyRegistrationDate, TCMotor) =====
// Tìm xe + ngày đăng ký BH (lọc frame/biển số; onlyMissing=true chỉ xe chưa có ngày ĐK).
app.MapGet("/api/servicecars/warranty-reg", async (AppDbContext db, ITenantContext t, string? frame, string? plate, bool? onlyMissing) =>
{
    var q = db.ServiceCars.Where(v => v.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(frame)) q = q.Where(v => v.FrameNo.Contains(frame!));
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(v => v.PlateNo != null && v.PlateNo.Contains(plate!));
    if (onlyMissing == true) q = q.Where(v => v.WarrantyRegistrationDate == null);
    var items = await q.OrderBy(v => v.FrameNo).Take(500).Select(v => new
    {
        v.FrameNo, v.PlateNo, v.ModelCode, v.CusName,
        warrantyRegDate = v.WarrantyRegistrationDate.HasValue ? v.WarrantyRegistrationDate.Value.ToString("yyyy-MM-dd") : "",
        warrantyDate = v.WarrantyDate.HasValue ? v.WarrantyDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, withReg = items.Count(i => i.warrantyRegDate != ""), items });
}).RequireAuthorization();

// Cập nhật hàng loạt ngày đăng ký BH theo số khung (Excel: FrameNo + ngày). Validate frame tồn tại + ngày hợp lệ + không tương lai.
app.MapPost("/api/servicecars/warranty-reg-batch", async (List<WarrantyRegRowDto> rows, AppDbContext db, ITenantContext t) =>
{
    if (rows is null || rows.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào." });
    int updated = 0, errorCount = 0; var errors = new List<object>();
    int line = 0;
    foreach (var r in rows)
    {
        line++;
        var frame = (r.FrameNo ?? "").Trim();
        if (frame == "") { errorCount++; errors.Add(new { line, error = "Thiếu số khung." }); continue; }
        if (!DateTime.TryParse(r.WarrantyRegDate, out var d)) { errorCount++; errors.Add(new { line, frame, error = "Ngày không hợp lệ." }); continue; }
        if (d.Date > DateTime.Today) { errorCount++; errors.Add(new { line, frame, error = "Ngày đăng ký không được ở tương lai." }); continue; }
        var car = await db.ServiceCars.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.FrameNo == frame);
        if (car is null) { errorCount++; errors.Add(new { line, frame, error = "Không tìm thấy xe (số khung)." }); continue; }
        car.WarrantyRegistrationDate = d.Date; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = rows.Count, updated, errorCount, errors });
}).RequireAuthorization();

// ===== Danh mục phụ tùng dịch vụ (ServicePart — port 1:1 FrmPart/FrmPartSearch, TCMotor) =====
app.MapGet("/api/serviceparts", async (AppDbContext db, ITenantContext t, string? q, string? group, string? active) =>
{
    var query = db.ServiceParts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.PartCode.Contains(q!.ToUpper()) || (x.PartName != null && x.PartName.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(group)) query = query.Where(x => x.PartGroupCode == group);
    if (!string.IsNullOrWhiteSpace(active)) query = query.Where(x => x.FlagActive == active);
    var items = await query.OrderBy(x => x.PartCode).Take(500)
        .Select(x => new { x.PartCode, x.PartName, x.EngName, x.Unit, x.Price, x.Cost, x.Location, x.Quantity, x.MinQuantity, x.PartGroupCode, x.Model, x.Note, x.FlagActive,
            lowStock = x.Quantity < x.MinQuantity }).ToListAsync();
    return Results.Ok(new { count = items.Count, lowStockCount = items.Count(i => i.lowStock), items });
}).RequireAuthorization();

// Upsert theo mã phụ tùng.
app.MapPost("/api/serviceparts", async (ServicePartDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.PartCode)) return Results.BadRequest(new { error = "Chưa nhập mã phụ tùng." });
    if (string.IsNullOrWhiteSpace(dto.PartName)) return Results.BadRequest(new { error = "Chưa nhập tên phụ tùng." });
    if (dto.Price < 0 || dto.Cost < 0) return Results.BadRequest(new { error = "Giá/chi phí không hợp lệ." });
    // #252: `Views/Services/FrmPart.cs` cũng kiểm `regex.IsMatch(txtMaDV.Text)`, nhưng ở màn này
    //   `txtMaDV` bind vào **`PartCode`** (:260, :279) ⇒ thông điệp "Mã phụ tùng…" ở đây là ĐÚNG nghĩa.
    if (HasSpecialChar(dto.PartCode.Trim()))
        return Results.BadRequest(new { error = "Mã phụ tùng không được phép chứa các ký tự đặc biệt" });
    var code = dto.PartCode.Trim().ToUpperInvariant();
    var ex = await db.ServiceParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PartCode == code);
    if (ex is not null)
    {
        ex.PartName = dto.PartName; ex.EngName = dto.EngName; ex.Unit = dto.Unit; ex.Price = dto.Price; ex.Cost = dto.Cost; ex.Location = dto.Location; ex.Quantity = dto.Quantity; ex.MinQuantity = dto.MinQuantity; ex.PartGroupCode = dto.PartGroupCode; ex.Model = dto.Model; ex.Note = dto.Note; ex.FlagActive = "1";
        await db.SaveChangesAsync();
        return Results.Ok(new { ex.PartCode, updated = true });
    }
    // ===== 🔴 #261 12 CỘT bổ sung của `TblSerMSTPart` (DbDefine.cs:663-693) =====
    // Sweep "lớp `Tbl*` có hằng nằm SAU DÒNG TRỐNG" (sinh từ #260): lớp này có **khối chính 18 hằng**
    // + **khối phụ 7 hằng** (:684-692). Port cũ thiếu 5 cột khối chính và **cả 7** cột khối phụ.
    // ⚠️ `TSTPrice`/`TSTPriceBefore` là **cặp giá hiện tại / giá trước** — thiếu vế sau thì không đối chiếu
    //    được biến động giá NCC. `FlagInTST` cho biết PT có trong danh mục TST hay không.
    // ⚠️ `InventoryQuantity` KHÁC `Quantity` (hai cột riêng trong cùng lớp hằng).
    var r = new ServicePart { OrgId = t.OrgId, PartCode = code, PartName = dto.PartName, EngName = dto.EngName, Unit = dto.Unit, Price = dto.Price, Cost = dto.Cost, Location = dto.Location, Quantity = dto.Quantity, MinQuantity = dto.MinQuantity, PartGroupCode = dto.PartGroupCode, Model = dto.Model, Note = dto.Note, FlagActive = "1",
        PartID = dto.PartID, PartTypeID = dto.PartTypeID, DealerCode = dto.DealerCode,
        VAT = dto.VAT, InventoryQuantity = dto.InventoryQuantity,
        TotalPrice = dto.TotalPrice, BalanceLocationId = dto.BalanceLocationId, FreqUsed = dto.FreqUsed,
        PriceEffect = dto.PriceEffect, TSTPrice = dto.TSTPrice, TSTPriceBefore = dto.TSTPriceBefore,
        FlagInTST = dto.FlagInTST };
    db.ServiceParts.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.PartCode, updated = false });
}).RequireAuthorization();

// ===== 🔴 #374 XOÁ MASTER PHỤ TÙNG (`Ser_Mst_Part_Delete`, `Service.cs:4482`) =====
// Guard: phụ tùng **đang được tham chiếu ở BẤT KỲ đâu** thì không cho xoá. Nguồn chạy MỘT câu lệnh
// trả về **5 bảng kết quả** (mỗi bảng một nơi tham chiếu) rồi `foreach` qua **tất cả** các bảng —
// bảng nào có dòng là ném lỗi `Ser_Part_NotDelete`. Vì chỉ hỏi "có tồn tại không", `select top 1`
// **không** `order by` ở đây là **vô hại** (đúng loại guard).
// Năm nơi tham chiếu: `Ser_ROPartItems` · `Ser_ServicePackagePartItems` ·
//   `Ser_Inv_StockOutOrderDetail` · `Ser_Inv_StockInDetail` · `Ser_ROWarrantyReportPartItems`.
//
// 🔴 **PHẠM VI KIỂM ≠ PHẠM VI XOÁ** — lỗ hổng thật của nguồn:
//   Guard chạy trên `_dbDealer`, nhưng lệnh xoá chạy trên `_dbMain` **và** `_dbWH`, còn `_dbDealer`
//   thì **chỉ xoá khi** `bNeedTransaction_Dealer`. ⇒ Phụ tùng chỉ được tham chiếu ở Main/WH mà không
//   có ở DB đại lý vẫn **qua được guard** rồi bị xoá khỏi Main/WH.
// 🔴 **GUARD CÓ THỂ ĐẬU VÌ LÝ DO SAI**: bảng tạm `#tbl_part` dựng từ `ser_mst_part` **trên DB đại lý**.
//   Phụ tùng không tồn tại ở DB đại lý ⇒ `#tbl_part` RỖNG ⇒ mọi `join` không ra dòng nào ⇒ guard đậu
//   **rỗng tuếch**, rồi vẫn xoá ở Main/WH.
// ⚠️ Nguồn khai `dtROPartItems` và `dtROServicePackagePartItems` rồi **không dùng đến** — biến chết;
//   vòng lặp duyệt hết mọi bảng nên hai biến đó thừa.
// 📌 MiniHTC dùng MỘT cơ sở dữ liệu ⇒ không tái hiện được lệch phạm vi; kiểm và xoá cùng một chỗ,
//   và trả cờ `scopeDivergenceNote` để không ai tưởng đã port thiếu.
app.MapDelete("/api/serviceparts/{code}", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = (code ?? "").Trim().ToUpperInvariant();
    var part = await db.ServiceParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PartCode == code);
    if (part is null) return Results.NotFound(new { code });

    // Năm nơi tham chiếu — ĐÚNG thứ tự của nguồn.
    var used = new List<string>();
    if (await db.RoPartItems.AnyAsync(x => x.OrgId == t.OrgId && x.PartCode == code))
        used.Add("Ser_ROPartItems (dòng phụ tùng của lệnh sửa chữa)");
    if (await db.ServicePackageParts.AnyAsync(x => x.OrgId == t.OrgId && x.PartCode == code))
        used.Add("Ser_ServicePackagePartItems (gói dịch vụ)");
    if (await db.SerStockOutOrderLines.AnyAsync(x => x.OrgId == t.OrgId && x.PartCode == code))
        used.Add("Ser_Inv_StockOutOrderDetail (dòng lệnh xuất)");
    if (await db.PartStockInLines.AnyAsync(x => x.OrgId == t.OrgId && x.PartCode == code))
        used.Add("Ser_Inv_StockInDetail (dòng phiếu nhập)");
    if (await db.WarrantyClaimPartItems.AnyAsync(x => x.OrgId == t.OrgId && x.PartCode == code))
        used.Add("Ser_ROWarrantyReportPartItems (dòng phụ tùng của BCBH)");

    if (used.Count > 0)
        return Results.BadRequest(new
        {
            error = "Ser_Part_NotDelete",
            message = "Phụ tùng đang được tham chiếu, không xoá được.",
            code, referencedIn = used,
        });

    db.ServiceParts.Remove(part);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        code, deleted = true,
        checkedTables = 5,
        scopeDivergenceNote = "Nguồn KIỂM trên DB đại lý nhưng XOÁ trên Main + WH (đại lý chỉ khi có giao dịch) "
            + "⇒ phụ tùng chỉ tham chiếu ở Main/WH vẫn qua guard. MiniHTC một CSDL nên kiểm và xoá cùng phạm vi.",
        vacuousGuardNote = "Nguồn dựng #tbl_part từ DB đại lý: phụ tùng không có ở đó ⇒ guard đậu rỗng tuếch.",
    });
}).RequireAuthorization();

// ===== 🔴 #375 TIÊU ĐỀ BÁO CÁO theo đại lý (`Mst_ReportHeader`) =====
// Nguồn có **BA nơi đọc cùng bảng này, ba hành vi khác nhau** — không thể port thành một hàm:
//   1. `Mst_ReportHeader_Get`      (`Service.Report.cs:83`)  — `select top 1 rpt.*`, DB **Main**
//   2. `Mst_ReportHeader_Getnew`   (`Service.Report.cs:196`) — `select top 1` + **ĐỔI NHÃN CỘT**, DB **Main**
//   3. `SerMasterInitGet`          (`Master.cs:7811`)        — **KHÔNG `top 1`** (trả cả danh sách),
//      đọc từ **CSDL CommonCenter** `[@strDBName_CommonCenter]`. `Service01.cs:13289` cũng đọc CommonCenter.
//   ⇒ Cùng một tên bảng nhưng **hai CSDL khác nhau** và **một dòng vs cả danh sách**.
//
// 🔴 **TÊN CỘT NÓI DỐI, LẦN NÀY LÀ CỘT BỊ DÙNG LẠI**: bản (2) và (3) đổi nhãn khi trả về:
//   `DealerName → info1` · `CompanyName → info2` · `CompanyAddress → info3` · `Website → info4`
//   🔴 `Showroom1 → Tel` · `Showroom2 → Fax` · `Showroom3 → Mobile`
//   ⇒ Ba cột mang tên 'phòng trưng bày' thực chất chứa **số điện thoại / fax / di động**. Ai đọc
//     thẳng CSDL sẽ hiểu sai hoàn toàn. Giữ tên cột theo nguồn, nhưng nêu rõ ở entity và output.
// 🔴 `top 1` **không** `order by` trong khi bộ lọc là **DANH SÁCH đại lý** (`BuildClauseConditionList`,
//   ngăn cách `|`) ⇒ truyền nhiều đại lý thì nhận **tiêu đề của MỘT đại lý tuỳ ý**, và biểu mẫu sẽ được
//   in với **thư đầu của đại lý khác**. Giữ 1:1 nhưng trả cờ để lộ ra.
// ⚠️ Bản (1) viết marker khoá dòng **thiếu dấu đóng**: `--//[mylock` (2 chỗ), trong khi bản (2) viết đúng
//   `--//[mylock]` ⇒ bộ hậu xử lý rowlock **không nhận ra** hai bảng của bản (1).
app.MapGet("/api/reportheaders", async (AppDbContext db, ITenantContext t, string? dealers) =>
{
    // Bộ lọc danh sách đại lý ngăn cách bằng "|" — đúng quy ước BuildClauseConditionList của nguồn.
    var codes = (dealers ?? "").Split('|', StringSplitOptions.RemoveEmptyEntries)
        .Select(x => x.Trim().ToUpperInvariant()).Where(x => x.Length > 0).ToList();

    var q0 = db.ReportHeaders.Where(x => x.OrgId == t.OrgId);
    if (codes.Count > 0) q0 = q0.Where(x => codes.Contains(x.DealerCode));

    // Hành vi (3): trả CẢ DANH SÁCH, có đổi nhãn cột.
    var rows = await q0.OrderBy(x => x.DealerCode).Select(x => new
    {
        x.DealerCode,
        info1 = x.DealerName, info2 = x.CompanyName, info3 = x.CompanyAddress, info4 = x.Website,
        Tel = x.Showroom1, Fax = x.Showroom2, Mobile = x.Showroom3,
    }).ToListAsync();

    return Results.Ok(new
    {
        count = rows.Count, items = rows,
        dealerFilter = codes,
        aliasNote = "info1..4 = DealerName/CompanyName/CompanyAddress/Website; Tel/Fax/Mobile = Showroom1/2/3.",
        repurposedColumnsNote = "Ba cột tên Showroom1/2/3 THỰC CHẤT chứa điện thoại/fax/di động — tên cột trong CSDL nói dối.",
        sourceDbNote = "Nguồn của hành vi này đọc từ CSDL CommonCenter; hai hàm Service.Report đọc từ DB Main.",
    });
}).RequireAuthorization();

// Hành vi (1)+(2): `top 1` KHÔNG `order by` trên một DANH SÁCH đại lý.
app.MapGet("/api/reportheaders/one", async (AppDbContext db, ITenantContext t, string? dealers, string? shape) =>
{
    var codes = (dealers ?? "").Split('|', StringSplitOptions.RemoveEmptyEntries)
        .Select(x => x.Trim().ToUpperInvariant()).Where(x => x.Length > 0).ToList();

    var q0 = db.ReportHeaders.Where(x => x.OrgId == t.OrgId);
    if (codes.Count > 0) q0 = q0.Where(x => codes.Contains(x.DealerCode));

    var all = await q0.ToListAsync();
    var one = all.FirstOrDefault();          // đúng nghĩa "top 1 không order by"
    if (one is null) return Results.Ok(new { found = false, dealerFilter = codes });

    var labeled = (shape ?? "labeled").Trim().ToLowerInvariant() != "raw";
    object payload = labeled
        ? new
          {
              one.DealerCode,
              info1 = one.DealerName, info2 = one.CompanyName, info3 = one.CompanyAddress, info4 = one.Website,
              Tel = one.Showroom1, Fax = one.Showroom2, Mobile = one.Showroom3,
          }
        : new
          {
              one.DealerCode, one.DealerName, one.CompanyName, one.CompanyAddress,
              one.Website, one.Showroom1, one.Showroom2, one.Showroom3,
          };

    var distinctDealers = all.Select(x => x.DealerCode).Distinct().Count();
    return Results.Ok(new
    {
        found = true, header = payload,
        shape = labeled ? "labeled (Mst_ReportHeader_Getnew)" : "raw (Mst_ReportHeader_Get)",
        matchedCount = all.Count, distinctDealers,
        // Nhiều đại lý khớp ⇒ nguồn trả tiêu đề của MỘT đại lý tuỳ ý.
        ambiguous = distinctDealers > 1,
        ambiguousNote = distinctDealers > 1
            ? "Bộ lọc khớp nhiều đại lý nhưng nguồn dùng `top 1` KHÔNG `order by` ⇒ biểu mẫu có thể in thư đầu của ĐẠI LÝ KHÁC."
            : null,
        mylockNote = "Bản Mst_ReportHeader_Get viết marker `--//[mylock` THIẾU dấu đóng ⇒ hậu xử lý rowlock bỏ sót.",
    });
}).RequireAuthorization();

// #375 §12: đường GHI cho tiêu đề báo cáo (nguồn sửa bằng màn master riêng).
app.MapPost("/api/reportheaders", async (ReportHeaderDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    if (code.Length == 0) return Results.BadRequest(new { error = "DealerCode bắt buộc." });

    var row = await db.ReportHeaders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == code);
    if (row is null)
    {
        row = new ReportHeader { OrgId = t.OrgId, DealerCode = code };
        db.ReportHeaders.Add(row);
    }
    row.DealerName = dto.DealerName; row.CompanyName = dto.CompanyName;
    row.CompanyAddress = dto.CompanyAddress; row.Website = dto.Website;
    row.Showroom1 = dto.Showroom1; row.Showroom2 = dto.Showroom2; row.Showroom3 = dto.Showroom3;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.DealerCode, saved = true });
}).RequireAuthorization();

app.MapPost("/api/serviceparts/{code}/toggle", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var x = await db.ServiceParts.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.PartCode == code);
    if (x is null) return Results.NotFound(new { code });
    x.FlagActive = x.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.PartCode, flagActive = x.FlagActive });
}).RequireAuthorization();

// ===== Nhóm phụ tùng phân cấp (PartGroup — port 1:1 FrmPartGroup, TCMotor) =====
app.MapGet("/api/partgroups", async (AppDbContext db, ITenantContext t, string? q, string? parent, string? active) =>
{
    var query = db.PartGroups.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.GroupCode.Contains(q!.ToUpper()) || (x.GroupName != null && x.GroupName.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(parent)) query = query.Where(x => x.ParentCode == parent);
    if (!string.IsNullOrWhiteSpace(active)) query = query.Where(x => x.FlagActive == active);
    var all = await query.OrderBy(x => x.OrderId).ThenBy(x => x.GroupCode).Take(1000).ToListAsync();
    var nameMap = await db.PartGroups.Where(x => x.OrgId == t.OrgId).ToDictionaryAsync(x => x.GroupCode, x => x.GroupName);
    var items = all.Select(x => new
    {
        x.GroupCode, x.GroupName, x.ParentCode,
        parentName = !string.IsNullOrEmpty(x.ParentCode) && nameMap.TryGetValue(x.ParentCode, out var pn) ? pn : null,
        x.OrderId, x.FlagActive
    }).ToList();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Upsert theo mã nhóm (guard: nhóm cha phải tồn tại + không tự trỏ chính nó).
app.MapPost("/api/partgroups", async (PartGroupDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.GroupCode)) return Results.BadRequest(new { error = "Chưa nhập mã nhóm." });
    if (string.IsNullOrWhiteSpace(dto.GroupName)) return Results.BadRequest(new { error = "Chưa nhập tên nhóm." });
    var code = dto.GroupCode.Trim().ToUpperInvariant();
    var parent = string.IsNullOrWhiteSpace(dto.ParentCode) ? null : dto.ParentCode.Trim().ToUpperInvariant();
    if (parent == code) return Results.BadRequest(new { error = "Nhóm cha không được trùng chính nó." });
    if (parent != null && !await db.PartGroups.AnyAsync(x => x.OrgId == t.OrgId && x.GroupCode == parent))
        return Results.BadRequest(new { error = $"Nhóm cha {parent} không tồn tại." });
    var ex = await db.PartGroups.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GroupCode == code);
    if (ex is not null)
    {
        ex.GroupName = dto.GroupName; ex.ParentCode = parent; ex.OrderId = dto.OrderId; ex.FlagActive = "1";
        await db.SaveChangesAsync();
        return Results.Ok(new { ex.GroupCode, updated = true });
    }
    var r = new PartGroup { OrgId = t.OrgId, GroupCode = code, GroupName = dto.GroupName, ParentCode = parent, OrderId = dto.OrderId, FlagActive = "1" };
    db.PartGroups.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.GroupCode, updated = false });
}).RequireAuthorization();

app.MapPost("/api/partgroups/{code}/toggle", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var x = await db.PartGroups.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.GroupCode == code);
    if (x is null) return Results.NotFound(new { code });
    x.FlagActive = x.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.GroupCode, flagActive = x.FlagActive });
}).RequireAuthorization();

// ===== Công nợ khách hàng dịch vụ + thu tiền (CusDebit — port 1:1 FrmCusDebitCreate/FrmCusPaymentCreate, TCMotor) =====
app.MapGet("/api/cusdebits", async (AppDbContext db, ITenantContext t, string? q, string? status) =>
{
    var query = db.CusDebits.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.DebitNo.Contains(q!) || (x.CusName != null && x.CusName.Contains(q!)) || (x.RONo != null && x.RONo.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.DebitNo, x.CusId, x.CusName, x.RONo, x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount, x.Status, x.Note,
        debitDate = x.DebitDate.HasValue ? x.DebitDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalDebit = items.Sum(i => i.DebitAmount), totalPaid = items.Sum(i => i.PaidAmount), totalBalance = items.Sum(i => i.balance), items });
}).RequireAuthorization();

// Tạo công nợ (theo RO/khách). DebitAmount > 0.
app.MapPost("/api/cusdebits", async (CusDebitDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.DebitAmount <= 0) return Results.BadRequest(new { error = "Số tiền công nợ phải lớn hơn 0." });
    var no = "CD" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new CusDebit { OrgId = t.OrgId, DebitNo = no, CusId = dto.CusId, CusName = dto.CusName, RONo = dto.RONo, DebitAmount = dto.DebitAmount, PaidAmount = 0, DebitDate = dto.DebitDate ?? DateTime.Now, Note = dto.Note, Status = "Open" };
    db.CusDebits.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.DebitNo });
}).RequireAuthorization();

app.MapGet("/api/cusdebits/{no}/payments", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.CusDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    var pays = await db.CusDebitPayments.Where(p => p.OrgId == t.OrgId && p.CusDebitId == h.Id).OrderBy(p => p.Id)
        .Select(p => new { p.PaymentAmount, p.Note, p.PaymentNo, p.DealerCode, p.PayPersonName, p.PayPersonIDCardNo, payDate = p.PayDate.HasValue ? p.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    return Results.Ok(new { h.DebitNo, h.DebitAmount, h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, h.Status, count = pays.Count, payments = pays });
}).RequireAuthorization();

// Thu tiền công nợ (không vượt số dư; đủ tiền -> Paid).
app.MapPost("/api/cusdebits/{no}/payments", async (string no, CusDebitPaymentDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.CusDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền thu phải lớn hơn 0." });
    // Guard của nguồn (checkPaymentFieldEmpty): đại lý + người nộp + CMND/CCCD + ngày thu đều BẮT BUỘC.
    // ⚠️ CusID KHÔNG bắt buộc — nguồn đã COMMENT dòng truyền strCusID vào hàm check (luật "port dòng active").
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    var balance = h.DebitAmount - h.PaidAmount;
    if (dto.PaymentAmount > balance) return Results.BadRequest(new { error = $"Số tiền thu vượt số dư công nợ ({balance})." });
    db.CusDebitPayments.Add(new CusDebitPayment { OrgId = t.OrgId, CusDebitId = h.Id, PaymentAmount = dto.PaymentAmount, PayDate = dto.PayDate ?? DateTime.Now, Note = dto.Note,
        PaymentNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss"), DealerCode = dto.DealerCode, PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
    h.PaidAmount += dto.PaymentAmount;
    if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.DebitNo, paidAmount = h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, status = h.Status });
}).RequireAuthorization();

// ===== Đề nghị bảo hành dịch vụ (ServiceWarrantyClaim — port 1:1 FrmWarrantyReportDealerSearch/HTCSearch/HTCApproved, TCMotor) =====
// ===== 🔴 #302 NHÃN TRẠNG THÁI PHIẾU ĐỀ NGHỊ BẢO HÀNH — nguồn LIVE `WarrantyReport.cs:13503` =====
//   `SENT` Chờ xem xét · `PEND` Chưa gửi · `CONF` Chờ duyệt · `ACCE` Chấp thuận B.H · `REJ` Không duyệt
//   `REVERT` HTC Hoàn trả.  **KHÔNG có nhánh `else`** ⇒ mã lạ cho ra nhãn NULL (ô trống), không gộp.
//   ⚠️ `PEND` nghĩa là **"Chưa gửi"**, KHÔNG phải "đang chờ xử lý" — dễ dịch ngược nghĩa.
var warrantyClaimStatusNames = new Dictionary<string, string>
{
    ["Sent"] = "Chờ xem xét", ["Pending"] = "Chưa gửi", ["Confirmed"] = "Chờ duyệt",
    ["Accepted"] = "Chấp thuận B.H", ["Rejected"] = "Không duyệt", ["Reverted"] = "HTC Hoàn trả",
};

// ===== 🔴 #302 CHI TIẾT PHIẾU ĐỀ NGHỊ BẢO HÀNH — LUẬT ĐỌC của bản LIVE =====
// TRACE TWIN: `Ser_ROWarrantyReport` có **BỐN** bản Get (`_GetOld` :12318 · bản trần :12605 ·
//   `_New20230220` :12973 · `_New20230417` :13388). WS `WSCarSv.asmx.cs:19855` gọi **`_New20230417`**
//   ⇒ ba bản kia CHẾT.
//
// 🔴 BẢN LIVE ĐÃ ĐỔI LUẬT ĐỌC — điểm dễ port sai nhất ở màn này:
//   Bản `_New20230220` (CHẾT) đọc thông tin xe qua `isnull(td.X, car.X)` — bản chụp của PHIẾU, dự phòng
//   là XE. Bản LIVE **bỏ hết chuỗi isnull đó** và lấy thẳng `ro.FrameNo` / `ro.PlateNo` / `ro.BatteryNo` /
//   `ro.SerialNo` / `ro.WarrantyRegistrationDate` / `ro.WarrantyExpiresDate` — tức **lấy BẢN CHỤP CỦA LỆNH
//   SỬA CHỮA**, không phải của phiếu, cũng không phải của master xe.
//   ⇒ Đi theo bản chụp của phiếu (như sweep gợi ý) là port đúng bản CHẾT. Nguồn sự thật = `ro`.
//   Cột duy nhất còn lấy từ master xe: `car.CusConfirmedWarrantyDate`.
//
// ⚠️ `WarrantyRegistrationDate` nguồn `convert(nvarchar, …, 23)` ⇒ trả **CHUỖI yyyy-MM-dd**, trong khi
//   `WarrantyExpiresDate` để nguyên datetime. Bất đối xứng có thật, giữ đúng.
//
// ⚠️ QUYẾT ĐỊNH NGHIỆP VỤ CÓ GHI LÝ DO (nên BẮT CHƯỚC, theo lệ #275): nguồn **cố ý bỏ** điều kiện
//   `and td.cusID = car.CusID` kèm chú thích *"2022-05-23. Confirm vs Ms.Đông KH ko bắt buộc phải giống
//   nhau"* ⇒ khách trên phiếu bảo hành **KHÔNG bắt buộc** là chủ xe. Ghép xe **CHỈ theo `CarID`**.
// ===== 🔴 #369 GUARD DUYỆT BCBH theo "lần thay PHỤ TÙNG CHÍNH gần nhất" =====
// Nguồn: `BizCarSv.WarrantyReport.cs` — `ROWarrantyReport_Approve_Check_CreatedDate_OtherROActualDeliveryDate`
//   (7120) và biến thể `…DeliveryDate2` (7276). Bản ở 7015 là **khối comment ⇒ luật ĐÃ CHẾT** (lệ #305).
//
// 🔴 HAI BIẾN THỂ ĐỀU LIVE, và điều kiện **NGƯỢC CHIỀU NHAU** — chọn theo loại BCBH:
//   • `XM`/`W` (5839) và `SB`/`W` (6019) → bản **2**: từ chối khi phụ tùng chính được thay
//     **TRONG VÒNG 6 tháng** VÀ xe mới chạy **DƯỚI 10.000 km**. Ý nghĩa: lần thay trước còn
//     trong hạn bảo hành của chính nó, không cho khai lại.
//   • `PT`/`S` (6065) → bản **1**: từ chối khi phụ tùng chính được thay **QUÁ 6 tháng** hoặc xe đã
//     chạy **TRÊN 10.000 km**. Ý nghĩa: bảo hành PHỤ TÙNG chỉ còn hiệu lực trong hạn đó.
//   ⇒ Đây **không phải mâu thuẫn**: hai chế độ bảo hành khác nhau trên cùng một mốc 6 tháng /
//     10.000 km. **Port chung một luật cho cả hai là sai đúng một nửa số hồ sơ.**
//
// 🔴 NHÁNH CHẾT trong bản 2 (giữ 1:1 nhưng phải biết): nguồn viết
//   `if (kmDiff < 10000 && trong6Thang) { if (trong6Thang) {…throw…} if (kmDiff < 10000) {…throw…} }`
//   ⇒ `if` trong cùng LUÔN đúng nên luôn ném trước; lỗi *"Xe chạy chưa được 10.000 KM…"* của nhánh
//     thứ hai **KHÔNG BAO GIỜ hiện ra được**. Người dùng chỉ thấy lý do 6 tháng.
//
// ⚠️ Truy vấn tìm RO gần nhất chạy trên **DB Main** và **KHÔNG lọc đại lý** — cố ý: *"Check theo VIN
//   không phân biệt đại lý"*. Lọc thêm đại lý sẽ bỏ sót lần thay ở đại lý khác.
// ⚠️ Nó là `select top 1 … order by sr.ActualDeliveryDate desc` — **có** `order by`, nên KHÔNG thuộc
//   nhóm "top 1 không tất định"; cột `order` nằm trong danh sách select, chỉ không đứng đầu.
// 📌 Đối chiếu 2 máy: md5 CẢ FILE **khác nhau** (laptop `ba1fb715` / 150 `19b741ca`) nhưng md5 **vùng
//   7120-7440** giống hệt (`42a367f1`) ⇒ khác biệt nằm ngoài guard, port an toàn.
app.MapPost("/api/warrantyclaims/{id:long}/approve-check", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });

    var violations = new List<object>();
    void Deny(string code, string desc, object? ctx = null) => violations.Add(new { code, desc, ctx });

    if (string.IsNullOrWhiteSpace(c.Km)) Deny("InvalidKM", "Số Km của BCBH trống!");

    // Phụ tùng CHÍNH của hồ sơ (PTC) — nguồn lọc đúng loại này, không phải mọi dòng phụ tùng.
    var ptcCodes = await db.WarrantyClaimPartItems
        .Where(x => x.OrgId == t.OrgId && x.ClaimId == id && x.RowPartType == "PTC")
        .Select(x => x.PartCode).Distinct().ToListAsync();

    // RO gần nhất (theo NGÀY GIAO XE) của cùng VIN có chứa một trong các PTC đó.
    // KHÔNG lọc đại lý — chủ ý của nguồn. Bỏ RO hiện tại và các RO đã từ chối.
    var roQ =
        from ro in db.RepairOrders
        join pi in db.RoPartItems on ro.Id equals pi.RoId
        where ro.OrgId == t.OrgId && pi.OrgId == t.OrgId
              && ro.Vin == c.Vin && ptcCodes.Contains(pi.PartCode)
              && ro.ActualDeliveryDate != null && ro.Status != "Rejected"
              && (c.ROID == null || ro.RONo != c.ROID)
        orderby ro.ActualDeliveryDate descending
        select new { ro.RONo, ro.Km, ro.ActualDeliveryDate };
    var other = ptcCodes.Count == 0 ? null : await roQ.FirstOrDefaultAsync();

    var isPartWarranty = c.ROWTypeCode == "PT" && c.ROWTypeDtlCode == "S";
    var rule = isPartWarranty ? "PT/S — bảo hành PHỤ TÙNG (bản 1)" : "XM|SB + W — bảo hành thường (bản 2)";

    if (other is null)
    {
        Deny("InvalidPTC", "Phụ tùng chính của BCBH không được sửa chữa gần đây!");
    }
    else
    {
        var replacedAt = other.ActualDeliveryDate!.Value;
        var submittedAt = c.CreatedAt;
        var within6Months = replacedAt.AddMonths(6) > submittedAt;
        decimal.TryParse(c.Km, out var kmNow);
        decimal.TryParse(other.Km, out var kmThen);
        var kmDiff = kmNow - kmThen;
        var ctx = new { otherRONo = other.RONo, otherKm = other.Km, replacedAt, kmDiff };

        if (string.IsNullOrWhiteSpace(other.Km))
            Deny("InvalidOtherKM", "Số KM của báo giá có phụ tùng chính gần nhất trống!", ctx);

        if (isPartWarranty)
        {
            // BẢN 1 — hết hạn thì từ chối.
            if (!within6Months)
                Deny("InvalidCreatedDate_OtherROActualDeliveryDate",
                     "Phụ tùng chính đã được thay thế hơn 6 tháng trước!", ctx);
            if (kmDiff > 10000m)
                Deny("InvalidKM", "Xe đã chạy được hơn 10,000 KM từ khi Phụ tùng chính đã được thay thế!", ctx);
        }
        else
        {
            // BẢN 2 — CÒN trong hạn của lần thay trước thì từ chối. Điều kiện là phép VÀ.
            if (!string.IsNullOrWhiteSpace(other.Km) && kmThen > kmNow)
                Deny("InvalidOtherKM", "Số KM của báo giá có phụ tùng chính gần nhất lớn hơn số KM của BCBH!", ctx);

            if (kmDiff < 10000m && within6Months)
            {
                // Nguồn còn một nhánh KM ngay sau đây nhưng KHÔNG BAO GIỜ tới được (xem chú thích trên).
                Deny("InvalidCreatedDate_OtherROActualDeliveryDate",
                     "Phụ tùng chính đã được thay thế trong 6 tháng gần đây!", ctx);
            }
        }
    }

    return Results.Ok(new
    {
        claimId = id, c.ClaimNo, c.ROWTypeCode, c.ROWTypeDtlCode,
        ruleApplied = rule,
        canApprove = violations.Count == 0,
        violations,
        ptcPartCodes = ptcCodes,
        ruleClassified = c.ROWTypeCode != null && c.ROWTypeDtlCode != null,
        ruleNote = "Hai luật NGƯỢC CHIỀU: PT/S từ chối khi ĐÃ QUÁ 6 tháng; XM|SB+W từ chối khi CÒN TRONG 6 tháng.",
        deadBranchNote = "Bản 2 của nguồn có nhánh lỗi KM không bao giờ chạy tới (if lồng luôn đúng) — "
            + "người dùng chỉ nhận được lý do 6 tháng.",
        dealerScopeNote = "Tìm RO gần nhất theo VIN trên toàn hệ, KHÔNG lọc đại lý — chủ ý của nguồn.",
    });
}).RequireAuthorization();

app.MapGet("/api/warrantyclaims/{id:long}/detail", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });

    // Lệnh sửa chữa — nguồn INNER JOIN theo `td.ROID = ro.ROID`; MiniHTC chưa có ROID trên mọi bản ghi cũ
    //   nên tra theo ROID trước, thiếu thì theo số lệnh (khai rõ, không im lặng).
    var ro = c.ROID is not null
        ? await db.RepairOrders.FirstOrDefaultAsync(r => r.OrgId == t.OrgId && r.Id.ToString() == c.ROID)
        : null;
    ro ??= c.RONo is not null
        ? await db.RepairOrders.FirstOrDefaultAsync(r => r.OrgId == t.OrgId && r.RONo == c.RONo)
        : null;

    // Xe: ghép CHỈ theo CarID (xem quyết định nghiệp vụ 2022-05-23 ở trên).
    var car = c.CarID is not null
        ? await db.ServiceCars.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.FrameNo == c.CarID)
        : null;
    var cus = c.CusID is not null
        ? await db.ServiceCustomers.FirstOrDefaultAsync(u => u.OrgId == t.OrgId && u.CusCode == c.CusID)
        : null;

    return Results.Ok(new
    {
        c.Id, c.ClaimNo, c.ROWNo, c.DealerCode, c.RONo, c.ROID, c.CusID, c.CarID,
        c.Creator, c.Assistant, c.CreatedBy, c.ApprovedBy, c.ApprovedDate,
        c.Km, c.CheckInDate, c.FinishedDate, c.CusRequest, c.CarStatus, c.StartDate,
        c.NaturalCode, c.CauseCode, c.ErrorCodeCD, c.ErrorCodePN, c.PartIDError, c.FlagReadySend,
        c.ROWTID, c.WarrantyType, c.WarrantySerCode, c.Amount, c.Description, c.HtcNote,
        c.Status,
        warrantyStatusText = warrantyClaimStatusNames.TryGetValue(c.Status, out var sn) ? sn : null,
        c.HMCApiStatus, c.SyncHMCDateTime, c.ClmRcptNo, c.HMCApiQtyA, c.ClmNoSrl,

        // --- thông tin XE lấy TỪ LỆNH SỬA CHỮA (đúng bản LIVE), KHÔNG từ master xe ---
        frameNo = ro?.Vin,
        plateNo = ro?.LicensePlate,
        batteryNo = ro?.BatteryNo,
        serialNo = ro?.SerialNo,
        // nguồn convert sang chuỗi yyyy-MM-dd; cột hết hạn để nguyên datetime
        warrantyRegistrationDate = ro?.WarrantyRegistrationDate?.ToString("yyyy-MM-dd"),
        warrantyExpiresDate = ro?.WarrantyExpiresDate,
        roCreator = ro?.Creator,

        // 🔴 #322 BẢN CHỤP TRÊN CHÍNH PHIẾU — ghi bởi `_Update_V2` nhưng hàm Get LIVE KHÔNG đọc.
        //   Trả kèm để lộ nghịch lý: nếu lệch với khối lấy từ LỆNH ở trên thì dữ liệu hai nơi đã rời nhau.
        claimSnapshot = new
        {
            c.CusName, c.CusAddress, c.CusTel, c.ModelID, c.BatteryNo, c.SerialNo,
            c.WarrantyRegistrationDate, c.WarrantyExpiresDate, c.WarrantyKM, c.Note,
        },
        snapshotDiffersFromRo = (c.BatteryNo ?? "") != (ro?.BatteryNo ?? "")
                             || (c.SerialNo ?? "") != (ro?.SerialNo ?? ""),

        // --- cột DUY NHẤT còn lấy từ master xe ---
        cusConfirmedWarrantyDate = car?.WarrantyDate,
        ownerName = cus?.CusName,

        roResolvedBy = c.ROID is not null ? "ROID" : (c.RONo is not null ? "RONo (xấp xỉ)" : null),
        note = "Thông tin xe lấy từ LỆNH SỬA CHỮA theo bản LIVE _New20230417; bản _New20230220 (đọc từ phiếu/master) đã CHẾT.",
    });
}).RequireAuthorization();

app.MapGet("/api/warrantyclaims", async (AppDbContext db, ITenantContext t, string? status, string? plate, string? vin, string? dealer) =>
{
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(x => x.PlateNo != null && x.PlateNo.Contains(plate!));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.Vin != null && x.Vin.Contains(vin!));
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.ClaimNo, x.DealerCode, x.RONo, x.Vin, x.PlateNo, x.WarrantyType, x.PartCode, x.Description, x.Amount, x.Status, x.HMCApiStatus, x.SyncHMCDateTime, x.ClmRcptNo, x.HMCApiQtyA, x.ClmNoSrl, x.HtcNote, x.WarrantySerCode, x.ApprovedDate,
        // #302 §12: cột mới có mặt ở CẢ GET lẫn POST
        x.ROWNo, x.ROID, x.CusID, x.CarID, x.Creator, x.Assistant, x.Km, x.CheckInDate, x.FinishedDate,
        // #369 §12: hai ma phan loai quyet dinh AP LUAT DUYET NAO
        x.ROWTypeCode, x.ROWTypeDtlCode,
        // #322 §12: bản chụp khách + xe (ghi bởi _Update_V2)
        x.CusName, x.CusAddress, x.CusTel, x.ModelID, x.BatteryNo, x.SerialNo,
        x.WarrantyRegistrationDate, x.WarrantyExpiresDate, x.WarrantyKM, x.Note,
        x.CusRequest, x.CarStatus, x.NaturalCode, x.CauseCode, x.StartDate, x.ROWTID,
        x.ErrorCodeCD, x.ErrorCodePN, x.FlagReadySend, x.PartIDError, x.ApprovedBy, x.CreatedBy
    }).ToListAsync();
    var withLabel = items.Select(i => new
    {
        i.Id, i.ClaimNo, i.DealerCode, i.RONo, i.Vin, i.PlateNo, i.WarrantyType, i.PartCode,
        i.Description, i.Amount, i.Status,
        warrantyStatusText = warrantyClaimStatusNames.TryGetValue(i.Status, out var wn) ? wn : null,
        i.HMCApiStatus, i.SyncHMCDateTime, i.ClmRcptNo, i.HMCApiQtyA, i.ClmNoSrl, i.HtcNote,
        i.WarrantySerCode, i.ApprovedDate,
        i.ROWNo, i.ROID, i.CusID, i.CarID, i.Creator, i.Assistant, i.Km, i.CheckInDate, i.FinishedDate,
        i.CusRequest, i.CarStatus, i.NaturalCode, i.CauseCode, i.StartDate, i.ROWTID,
        i.ErrorCodeCD, i.ErrorCodePN, i.FlagReadySend, i.PartIDError, i.ApprovedBy, i.CreatedBy,
    }).ToList();
    return Results.Ok(new { count = items.Count, totalAmount = items.Sum(i => i.Amount),
        pending = items.Count(i => i.Status == "Pending"), sent = items.Count(i => i.Status == "Sent"),
        accepted = items.Count(i => i.Status == "Accepted"), rejected = items.Count(i => i.Status == "Rejected"),
        confirmed = items.Count(i => i.Status == "Confirmed"), reverted = items.Count(i => i.Status == "Reverted"),
        items = withLabel });
}).RequireAuthorization();

// Đại lý tạo đề nghị bảo hành (theo RO). Amount >= 0; cần VIN hoặc biển số.
app.MapPost("/api/warrantyclaims", async (WarrantyClaimDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Vin) && string.IsNullOrWhiteSpace(dto.PlateNo))
        return Results.BadRequest(new { error = "Cần số khung (VIN) hoặc biển số." });
    if (dto.Amount < 0) return Results.BadRequest(new { error = "Số tiền bảo hành không được âm." });
    var no = "WC" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new ServiceWarrantyClaim { OrgId = t.OrgId, ClaimNo = no, DealerCode = dto.DealerCode, RONo = dto.RONo,
        ROWTypeCode = dto.ROWTypeCode, ROWTypeDtlCode = dto.ROWTypeDtlCode,   // #369 §12
        Vin = dto.Vin, PlateNo = dto.PlateNo, WarrantyType = dto.WarrantyType, PartCode = dto.PartCode, Description = dto.Description,
        Amount = dto.Amount, Status = "Pending", WarrantySerCode = dto.WarrantySerCode,
        // #302 §12 POST: 20 cột thật của `Ser_ROWarrantyReport` phải GÁN được, không chỉ ĐỌC được.
        //   `ROWNo` rỗng thì lấy chính `ClaimNo` — nguồn sinh số phiếu riêng, MiniHTC dùng một số.
        //   `Creator`/`CreatedBy`: nguồn có CẢ HAI cột và ghi cùng người lúc tạo.
        ROWNo = string.IsNullOrWhiteSpace(dto.ROWNo) ? no : dto.ROWNo,
        ROID = dto.ROID, CusID = dto.CusID, CarID = dto.CarID,
        Creator = dto.Creator, CreatedBy = dto.CreatedBy ?? dto.Creator, Assistant = dto.Assistant,
        Km = dto.Km, CheckInDate = dto.CheckInDate, FinishedDate = dto.FinishedDate,
        CusRequest = dto.CusRequest, CarStatus = dto.CarStatus,
        NaturalCode = dto.NaturalCode, CauseCode = dto.CauseCode, StartDate = dto.StartDate,
        ROWTID = dto.ROWTID, ErrorCodeCD = dto.ErrorCodeCD, ErrorCodePN = dto.ErrorCodePN,
        FlagReadySend = dto.FlagReadySend, PartIDError = dto.PartIDError,
        // #322 §12: gán bản chụp khách + xe.
        CusName = dto.CusName, CusAddress = dto.CusAddress, CusTel = dto.CusTel, ModelID = dto.ModelID,
        BatteryNo = dto.BatteryNo, SerialNo = dto.SerialNo,
        WarrantyRegistrationDate = dto.WarrantyRegistrationDate,
        WarrantyExpiresDate = dto.WarrantyExpiresDate,
        WarrantyKM = dto.WarrantyKM, Note = dto.Note };
    db.ServiceWarrantyClaims.Add(c); await db.SaveChangesAsync();
    // #268: nguồn ghi nhật ký NGAY KHI TẠO (2 chỗ gọi với Ser_WarrantyReport_Status.Pending,
    //   WarrantyReport.cs:2792 và :3493) ⇒ đề nghị nào cũng có dòng đầu tiên "PEND".
    db.ServiceWarrantyClaimTransactions.Add(new ServiceWarrantyClaimTransaction
    {
        OrgId = t.OrgId, ClaimId = c.Id, Creator = dto.Creator, CurrentStatus = c.Status,
        Note = dto.Description, CreatedBy = dto.Creator, LogLUDateTime = DateTime.Now, LogLUBy = dto.Creator,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Id, c.ClaimNo, c.ROWNo, c.Status,
        warrantyStatusText = warrantyClaimStatusNames.TryGetValue(c.Status, out var cn) ? cn : null });
}).RequireAuthorization();

// 🔴 TRỤC TRẠNG THÁI THỨ HAI của đề nghị bảo hành: đồng bộ sang API hãng HMC (TConst.HMCApiStatus).
// ĐỘC LẬP với luồng duyệt nội bộ (/action) — port cũ thiếu hẳn trục này.
var hmcApiStatusNames = new Dictionary<string, string>
{
    ["P"] = "Chờ gửi HMC",
    ["A"] = "Gửi thành công",
    ["R"] = "Gửi lỗi",
};

app.MapGet("/api/warrantyclaims/hmcapistatuses", () => Results.Ok(new
{
    statuses = hmcApiStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Trục ĐỘC LẬP với Status duyệt nội bộ; nguồn set 'P' ngay khi tạo đề nghị."
})).RequireAuthorization();

/// <summary>
/// Đổi số lần gửi lại thành chữ cái theo nguồn (`CUtils.SoSangChuCai`): 1→A, 2→B, …
/// Dùng cho số serial claim khi đẩy lại sang HMC.
///
/// 🔴 #270 VÁ LỖI PARITY. Nguồn thật (`TERP.Utils/Utils.cs:337` — hàm này **CHỈ CÓ TRÊN MÁY 150**,
/// laptop không có nên lượt port trước phải suy đoán):
/// <code>if (so &lt; 1 || so &gt; 26) return ""; return ((char)(so + 96)).ToString();</code>
/// ⇒ **quá 26 thì trả CHUỖI RỖNG**, KHÔNG cuộn vòng về "A". Bản port cũ dùng `% 26` nên lần gửi thứ 27
/// lại ra "A", **trùng số serial với lần thứ 2** — hai claim khác nhau cùng một `clmNoSrl` ở phía HMC.
/// (Nguồn trả chữ THƯỜNG, chỗ gọi mới `.ToUpper()`; port trả sẵn chữ hoa — cùng kết quả.)
/// </summary>
static string ResendSuffixLetter(int resendCount)
{
    if (resendCount < 1 || resendCount > 26) return "";
    return ((char)('A' + resendCount - 1)).ToString();
}

// Ghi kết quả đồng bộ HMC (bộ đẩy API gọi lại sau khi có phản hồi của hãng).
// TWIN: bản LIVE trên máy 150 là `Ser_ROWarrantyReport_SendHMCX_20260227` — bản laptop KHÔNG có hàm này.
// 🔴 JOB QUÉT ứng viên đẩy HMC — port từ bản biz CHỈ CÓ TRÊN MÁY 150 (WarrantyReport.cs:23477-23505).
// Bản laptop lọc `WarrantyStatus = 'ACCE'` (Accepted) và KHÔNG lọc hãng bảo hành; bản 150 đổi thành
// trạng thái Confirmed + CHỈ hãng HMC/HTMV. Port cũ không có job này ⇒ không có cách lấy danh sách cần đẩy.
app.MapGet("/api/warrantyclaims/hmc-pending", async (AppDbContext db, ITenantContext t, string? dealer) =>
{
    // Cửa sổ thời gian của nguồn: 3 ngày gần nhất, LÙI THÊM 5 GIỜ.
    // Lý do ghi ngay trong nguồn: "tránh job chạy lâu chạy vào sáng sớm hôm sau ==> bỏ sót BCBH".
    var fromDate = DateTime.Now.AddDays(-3).AddHours(-5).Date;

    var qy = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId
        // đại lý test của idocNet — nguồn loại trừ thẳng trong câu SQL
        && x.DealerCode != "VN101"
        // chưa đẩy (P) hoặc chưa có trạng thái đồng bộ
        && (x.HMCApiStatus == "P" || x.HMCApiStatus == "")
        // trạng thái duyệt: bản 150 đổi từ Accepted sang Confirmed
        && x.Status == "Confirmed"
        // chỉ hãng HMC/HTMV — điều kiện MỚI của bản 150
        && (x.WarrantySerCode == "HMC" || x.WarrantySerCode == "HTMV")
        && x.ApprovedDate != null && x.ApprovedDate >= fromDate);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer);

    var items = await qy.OrderBy(x => x.Id).Select(x => new
    {
        x.Id, x.ClaimNo, x.DealerCode, x.RONo, x.Vin, x.PlateNo, x.WarrantySerCode,
        x.Status, x.HMCApiStatus, x.HMCApiQtyA, x.ClmNoSrl, x.ApprovedDate,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, fromDate = fromDate.ToString("yyyy-MM-dd"), items });
}).RequireAuthorization();

app.MapPost("/api/warrantyclaims/{id}/hmcsync", async (
    long id, WarrantyHmcSyncDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var target = (dto.ToStatus ?? "").Trim().ToUpperInvariant();
    if (!hmcApiStatusNames.ContainsKey(target))
        return Results.BadRequest(new { error = $"Trạng thái hợp lệ: {string.Join(", ", hmcApiStatusNames.Keys)}" });

    // 🔴 Guard MỚI của bản _20260227: chỉ đẩy HMC khi đề nghị đang ở trạng thái duyệt "Confirmed"
    // (`CheckExistROWarrantyReport(..., Ser_WarrantyReport_Status.Confirmed, ...)`).
    if (c.Status != "Confirmed")
        return Results.BadRequest(new { error = $"Chỉ đẩy HMC khi đề nghị ở trạng thái Confirmed (đang: {c.Status})." });

    // Guard: đã gửi THÀNH CÔNG ("A") thì KHÔNG gửi lại.
    // ⚠️ Ở nguồn, ĐIỀU KIỆN CODE và COMMENT/tham số lỗi MÂU THUẪN nhau:
    //    comment + `HMCApiStatusListToCheck` ghi hợp lệ = "Pending,Fail" (chỉ cho gửi khi P hoặc R),
    //    nhưng biểu thức lại là `if (status != Success) throw`.
    //    Port theo COMMENT + danh sách hợp lệ vì đó mới khớp nghiệp vụ "đã gửi thành công thì thôi".
    //    ĐÃ FLAG trong sổ theo dõi để người xác nhận — không tự quyết là bug của nguồn.
    if (c.HMCApiStatus == "A")
        return Results.BadRequest(new { error = "Đề nghị đã đồng bộ thành công sang HMC, không gửi lại." });

    c.HMCApiStatus = target;
    c.SyncHMCDateTime = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.ClmRcptNo)) c.ClmRcptNo = dto.ClmRcptNo.Trim();

    if (target == "A")
    {
        // Chỉ lần gửi THÀNH CÔNG mới tăng đếm (nguồn: `HMCApiQtyA = iHMCApiQtyACur`).
        var previousSuccess = c.HMCApiQtyA;   // số lần đã gửi thành công TRƯỚC lần này
        c.HMCApiQtyA = previousSuccess + 1;
        // Từ lần đẩy THỨ 2 trở đi: đổi "-" trong số serial claim thành chữ cái theo số lần đã gửi.
        // Lần 1 giữ nguyên; lần 2 = A; lần 3 = B…
        var serial = (dto.ClmNoSrl ?? c.ClmNoSrl ?? "").Trim();
        if (serial.Length > 0)
            c.ClmNoSrl = previousSuccess > 0 ? serial.Replace("-", ResendSuffixLetter(previousSuccess)) : serial;
    }

    c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        c.Id, c.HMCApiStatus, statusName = hmcApiStatusNames[target],
        c.SyncHMCDateTime, c.ClmRcptNo, c.HMCApiQtyA, c.ClmNoSrl
    });
}).RequireAuthorization();

// Chuyển trạng thái theo máy trạng thái duyệt bảo hành (submit/review/approve/reject/revert).
// ===== 🔴 DÒNG PHỤ TÙNG của đề nghị bảo hành (Ser_ROWarrantyReportPartItems — 1-n, port cũ THIẾU HẲN) =====
// Nguồn: BizCarSv.WarrantyReport.cs:960-1290 (bản máy 150 canonical). Port cũ chỉ có 1 cột PartCode vô hướng.
var rowPartTypeNames = new Dictionary<string, string>
{
    ["PTC"] = "Phụ tùng chính",
    ["PTTT"] = "Phụ tùng thay thế",
    ["VTP"] = "Vật tư phụ",
};

app.MapGet("/api/warrantyclaims/rowparttypes", () => Results.Ok(new
{
    types = rowPartTypeNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Bắt buộc nhập cho mỗi dòng PT; mỗi đề nghị chỉ được ĐÚNG 1 dòng PTC.",
    partOrderTypes = new[] { new { code = "TST", name = "Mua qua đơn đặt TST" }, new { code = "OTHER", name = "Nguồn khác" } },
})).RequireAuthorization();

app.MapGet("/api/warrantyclaims/{id}/parts", async (long id, AppDbContext db, ITenantContext t) =>
{
    var items = await db.WarrantyClaimPartItems.Where(x => x.OrgId == t.OrgId && x.ClaimId == id)
        .OrderBy(x => x.Id).Select(x => new
        {
            x.Id, x.ClaimId, x.PartCode, x.PartName, x.RowPartType, x.PartOrderType, x.PartOrderNo,
            x.Quantity, x.Price, x.Factor, x.Vat, x.InsurancePrice, x.ExpenseType, x.WarrantyStatus,
            x.FlagMainPart, x.Note, x.CreatedAt, x.UpdatedAt,
            rowPartTypeName = rowPartTypeNames.ContainsKey(x.RowPartType) ? rowPartTypeNames[x.RowPartType] : x.RowPartType,
            amount = x.Quantity * x.Price * x.Factor,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalAmount = items.Sum(i => i.amount), items });
}).RequireAuthorization();

// Thêm 1 dòng phụ tùng vào đề nghị bảo hành — port ĐỦ chuỗi guard của nguồn.
app.MapPost("/api/warrantyclaims/{id}/parts", async (
    long id, WarrantyClaimPartItemDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { error = "Không tìm thấy đề nghị bảo hành." });

    var partCode = (dto.PartCode ?? "").Trim();
    if (partCode.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã phụ tùng." });

    // Guard 1 (nguồn): loại phụ tùng KHÔNG được trống và phải thuộc PTC/PTTT/VTP.
    var rowPartType = (dto.RowPartType ?? "").Trim().ToUpperInvariant();
    if (rowPartType.Length == 0)
        return Results.BadRequest(new { error = $"PT {partCode} loại phụ tùng không được trống!" });
    if (!rowPartTypeNames.ContainsKey(rowPartType))
        return Results.BadRequest(new { error = $"Loại phụ tùng không hợp lệ (chỉ PTC/PTTT/VTP), nhận: {rowPartType}." });

    // Guard 2 (nguồn, biến bCheckPTC): mỗi đề nghị chỉ được ĐÚNG 1 phụ tùng chính.
    // ⚠️ Nguồn CÓ đoạn bắt buộc phải có PTC nhưng đã COMMENT (dòng ~1285) ⇒ KHÔNG port thành ràng buộc.
    if (rowPartType == "PTC")
    {
        var hasPtc = await db.WarrantyClaimPartItems
            .AnyAsync(x => x.OrgId == t.OrgId && x.ClaimId == id && x.RowPartType == "PTC");
        if (hasPtc) return Results.BadRequest(new { error = "Báo cáo bảo hành chỉ có 1 phụ tùng chính!" });
    }

    // Guard 3 (nguồn): nguồn gốc phụ tùng bắt buộc và chỉ nhận TST/OTHER.
    var partOrderType = (dto.PartOrderType ?? "").Trim().ToUpperInvariant();
    if (partOrderType.Length == 0)
        return Results.BadRequest(new { error = "Chưa có nguồn gốc phụ tùng!" });
    if (partOrderType != "TST" && partOrderType != "OTHER")
        return Results.BadRequest(new { error = "Nguồn gốc phụ tùng không hợp lệ!" });

    var partOrderNo = (dto.PartOrderNo ?? "").Trim();
    if (partOrderType == "TST")
    {
        // Guard 4 (nguồn): TST thì số đơn hàng bắt buộc.
        if (partOrderNo.Length == 0) return Results.BadRequest(new { error = "Chưa nhập số đơn hàng!" });

        // Guard 5 (nguồn): đơn hàng phải TỒN TẠI và đã được duyệt/hoàn thành, có đúng dòng phụ tùng này.
        var order = await db.OrderParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == partOrderNo);
        // 🔴 #237 GUARD CHẾT CÂM (do #234 đổi từ vựng): guard này so với "Approved"/"Finished" trong khi
        //    #234 đã chuyển `OrderPartStatus` sang mã 1 ký tự "A"/"F" ⇒ điều kiện LUÔN ĐÚNG ⇒ **mọi số đơn
        //    hàng TST đều bị báo "không hợp lệ"**. Grep của #234 chỉ tìm `== "Finished"` nên trượt dạng `!=`.
        if (order is null || (order.OrderPartStatus != "A" && order.OrderPartStatus != "F"))
            return Results.BadRequest(new { error = "Số đơn hàng không hợp lệ!" });
        var line = await db.OrderPartLines
            .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartId == order.Id && x.PartCode == partCode);
        if (line is null) return Results.BadRequest(new { error = "Số đơn hàng không hợp lệ!" });

        // Guard 6 (nguồn): tổng SL trên MỌI đề nghị bảo hành (trừ đề nghị bị từ chối) phải <= SL duyệt của đơn.
        var usedQty = await db.WarrantyClaimPartItems
            .Where(x => x.OrgId == t.OrgId && x.ClaimId != id && x.PartOrderType == "TST"
                        && x.PartOrderNo == partOrderNo && x.PartCode == partCode)
            .Join(db.ServiceWarrantyClaims.Where(w => w.OrgId == t.OrgId && w.Status != "Rejected"),
                  x => x.ClaimId, w => w.Id, (x, w) => x.Quantity)
            .SumAsync();
        if (line.OrderQty < usedQty + dto.Quantity)
            return Results.BadRequest(new { error = $"Số lượng phụ tùng BCBH phải <= số lượng duyệt của đơn hàng (duyệt {line.OrderQty}, đã dùng {usedQty})." });

        // Guard 7 (nguồn): đơn giá BCBH phải BẰNG đơn giá của đơn hàng.
        if (line.Price != dto.Price)
            return Results.BadRequest(new { error = $"Đơn giá BCBH và đơn giá của đơn hàng phải bằng nhau (đơn hàng {line.Price})." });
    }

    if (dto.Quantity <= 0) return Results.BadRequest(new { error = "Số lượng phải lớn hơn 0." });
    if (dto.Price < 0) return Results.BadRequest(new { error = "Đơn giá không được âm." });

    var row = new WarrantyClaimPartItem
    {
        OrgId = t.OrgId, ClaimId = id, PartCode = partCode, PartName = dto.PartName,
        RowPartType = rowPartType, PartOrderType = partOrderType,
        PartOrderNo = partOrderNo.Length == 0 ? null : partOrderNo,
        Quantity = dto.Quantity, Price = dto.Price, Factor = dto.Factor <= 0 ? 1 : dto.Factor,
        Vat = dto.Vat, InsurancePrice = dto.InsurancePrice, ExpenseType = dto.ExpenseType,
        WarrantyStatus = dto.WarrantyStatus, FlagMainPart = rowPartType == "PTC" ? "1" : dto.FlagMainPart,
        Note = dto.Note,
    };
    db.WarrantyClaimPartItems.Add(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.ClaimId, row.PartCode, row.RowPartType, amount = row.Quantity * row.Price * row.Factor });
}).RequireAuthorization();

app.MapDelete("/api/warrantyclaims/{id}/parts/{lineId}", async (
    long id, long lineId, AppDbContext db, ITenantContext t) =>
{
    var row = await db.WarrantyClaimPartItems
        .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ClaimId == id && x.Id == lineId);
    if (row is null) return Results.NotFound(new { error = "Không tìm thấy dòng phụ tùng." });
    db.WarrantyClaimPartItems.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = lineId });
}).RequireAuthorization();

app.MapPost("/api/warrantyclaims/{id}/action", async (long id, WarrantyClaimActionDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var act = (dto.Action ?? "").Trim().ToLowerInvariant();
    // (action, các trạng thái nguồn hợp lệ, trạng thái đích)
    (string[] from, string to) rule = act switch
    {
        "submit"  => (new[] { "Pending", "Reverted" }, "Sent"),
        "review"  => (new[] { "Sent" }, "Confirmed"),
        "approve" => (new[] { "Confirmed" }, "Accepted"),
        "reject"  => (new[] { "Sent", "Confirmed" }, "Rejected"),
        "revert"  => (new[] { "Sent", "Confirmed" }, "Reverted"),
        _ => (Array.Empty<string>(), "")
    };
    if (rule.to == "") return Results.BadRequest(new { error = "Hành động không hợp lệ." });
    if (!rule.from.Contains(c.Status)) return Results.BadRequest(new { error = $"Không thể '{act}' khi đang ở trạng thái {c.Status}." });
    if ((act == "reject" || act == "revert") && string.IsNullOrWhiteSpace(dto.Note))
        return Results.BadRequest(new { error = "Từ chối/hoàn trả phải ghi lý do." });
    c.Status = rule.to;
    // Mốc duyệt dùng cho job đẩy HMC (nguồn lọc ApprovedDate trên đề nghị đang ở "CONF").
    if (rule.to == "Confirmed") c.ApprovedDate = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.Note)) c.HtcNote = dto.Note;
    c.UpdatedAt = DateTime.Now;

    // 🔴 #268: MỌI bước chuyển đều ghi một dòng nhật ký — nguồn gọi
    //   `ProcessSaveSerROWarrantyReportTransaction` ở **10 chỗ**, phủ hết submit/review/approve/reject/revert.
    //   `CurrentStatus` là trạng thái ĐÍCH (nguồn truyền vào chính hằng trạng thái mới).
    db.ServiceWarrantyClaimTransactions.Add(new ServiceWarrantyClaimTransaction
    {
        OrgId = t.OrgId, ClaimId = c.Id, Creator = dto.Creator, CurrentStatus = c.Status,
        Note = dto.Note, CreatedBy = dto.Creator, LogLUDateTime = DateTime.Now, LogLUBy = dto.Creator,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Id, c.Status });
}).RequireAuthorization();

// #268: đọc nhật ký chuyển trạng thái của một đề nghị (cũ nhất → mới nhất, như nguồn `order by`
//   `rt.ROWRTransactionID` ở WarrantyReport.cs:13552).
// 📌 NỢ: nguồn ghi dòng này vào **BA** DB — `_dbMain`, `_dbWH`, và `_dbDealer` khi `!bIsWSMain`
//   (WarrantyReport.cs:1735/1780/1795). MiniHTC một DB nên chỉ ghi một lần.
app.MapGet("/api/warrantyclaims/{id}/transactions", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var items = await db.ServiceWarrantyClaimTransactions
        .Where(x => x.OrgId == t.OrgId && x.ClaimId == id)
        .OrderBy(x => x.Id)
        .Select(x => new { x.Id, x.Creator, x.CurrentStatus, x.Note, x.CreatedBy,
            createdDate = x.CreatedDate.ToString("yyyy-MM-dd HH:mm:ss"), x.LogLUBy })
        .ToListAsync();
    return Results.Ok(new { claimId = id, c.ClaimNo, currentStatus = c.Status, count = items.Count, items });
}).RequireAuthorization();

// ===== Gói dịch vụ (ServicePackage — port 1:1 FrmServicePackageCreate/Search, TCMotor/Services) =====
app.MapGet("/api/servicepackages", async (AppDbContext db, ITenantContext t, string? q, string? active) =>
{
    var query = db.ServicePackages.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.PackageNo.Contains(q!) || (x.PackageName != null && x.PackageName.Contains(q!)));
    if (active == "1" || active == "0") query = query.Where(x => x.FlagActive == active);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.PackageNo, x.PackageName, x.ServiceTotal, x.PartTotal, x.GrandTotal, x.FlagActive,
        services = db.ServicePackageServices.Count(s => s.OrgId == t.OrgId && s.ServicePackageId == x.Id),
        parts = db.ServicePackageParts.Count(p => p.OrgId == t.OrgId && p.ServicePackageId == x.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Tạo/cập nhật gói theo PackageNo: thay toàn bộ dòng CV + PT, tính tổng (Price×Factor mỗi dòng).
app.MapPost("/api/servicepackages", async (ServicePackageDto dto, AppDbContext db, ITenantContext t) =>
{
    var no = (dto.PackageNo ?? "").Trim();
    if (no == "") return Results.BadRequest(new { error = "Thiếu mã gói dịch vụ." });
    var svcs = dto.Services ?? new(); var parts = dto.Parts ?? new();
    if (svcs.Count == 0 && parts.Count == 0) return Results.BadRequest(new { error = "Gói phải có ít nhất 1 dòng công hoặc phụ tùng." });
    decimal svcTotal = 0, partTotal = 0;
    var svcRows = new List<ServicePackageService>();
    foreach (var s in svcs)
    {
        if (string.IsNullOrWhiteSpace(s.SerCode)) return Results.BadRequest(new { error = "Có dòng công thiếu mã." });
        var f = s.Factor <= 0 ? 1 : s.Factor; var amt = Math.Round(s.Price * f, 2);
        svcTotal += amt;
        svcRows.Add(new ServicePackageService { OrgId = t.OrgId, SerCode = s.SerCode.Trim(), SerName = s.SerName, Price = s.Price, Factor = f, Amount = amt });
    }
    var partRows = new List<ServicePackagePart>();
    var seenP = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var p in parts)
    {
        if (string.IsNullOrWhiteSpace(p.PartCode)) return Results.BadRequest(new { error = "Có dòng PT thiếu mã." });
        if (!seenP.Add(p.PartCode.Trim())) return Results.BadRequest(new { error = "Trùng mã PT trong gói: " + p.PartCode });
        var f = p.Factor <= 0 ? 1 : p.Factor; var amt = Math.Round(p.Price * f, 2);
        partTotal += amt;
        partRows.Add(new ServicePackagePart { OrgId = t.OrgId, PartCode = p.PartCode.Trim(), PartName = p.PartName, Price = p.Price, Factor = f, Amount = amt });
    }
    var h = await db.ServicePackages.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PackageNo == no);
    if (h is null) { h = new ServicePackage { OrgId = t.OrgId, PackageNo = no }; db.ServicePackages.Add(h); }
    h.PackageName = dto.PackageName; h.ServiceTotal = svcTotal; h.PartTotal = partTotal; h.GrandTotal = svcTotal + partTotal; h.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    db.ServicePackageServices.RemoveRange(db.ServicePackageServices.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == h.Id));
    db.ServicePackageParts.RemoveRange(db.ServicePackageParts.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == h.Id));
    foreach (var s in svcRows) { s.ServicePackageId = h.Id; db.ServicePackageServices.Add(s); }
    foreach (var p in partRows) { p.ServicePackageId = h.Id; db.ServicePackageParts.Add(p); }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.PackageNo, h.ServiceTotal, h.PartTotal, h.GrandTotal });
}).RequireAuthorization();

app.MapGet("/api/servicepackages/{id}/detail", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.ServicePackages.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var svcs = await db.ServicePackageServices.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == id).Select(x => new { x.SerCode, x.SerName, x.Price, x.Factor, x.Amount }).ToListAsync();
    var parts = await db.ServicePackageParts.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == id).Select(x => new { x.PartCode, x.PartName, x.Price, x.Factor, x.Amount }).ToListAsync();
    return Results.Ok(new { h.PackageNo, h.PackageName, h.ServiceTotal, h.PartTotal, h.GrandTotal, services = svcs, parts });
}).RequireAuthorization();

