    return Results.Ok(new { row.Id, row.FlagActive });
}).RequireAuthorization();

// ===== Master phụ tùng TST (TstPart — port 1:1 FrmTST_Mst_Part, TCMotor DMSCarSv) =====
// ===== 🔴 #248 KÝ TỰ ĐẶC BIỆT — regex DÙNG CHUNG của nguồn =====
// Nguồn đặt ở **LỚP CHA** `Views/FrmMdiBase.cs:46-47`:
//     `static string pattern = "[^a-zA-Z0-9._-]"; public Regex regex = new Regex(pattern);`
// ⇒ "ký tự đặc biệt" = **mọi ký tự KHÔNG thuộc** [a-z A-Z 0-9 . _ -].
//   ⚠️ Nghĩa là **khoảng trắng** và **chữ tiếng Việt có dấu** cũng bị coi là ký tự đặc biệt.
//   ⚠️ Vì regex nằm ở lớp cha nên **mọi màn kế thừa `FrmMdiBase` đều dùng chung** — khi port màn khác
//      thấy `this.regex.IsMatch(...)` thì đây chính là quy tắc đó.
// ===== 🔴 #259 CHUẨN HOÁ CHUỖI — `Util.StandardizedString` =====
// Nguồn `TERP.HTCServiceClient/Common/Util.cs:553` (bản DMSCarSv) / `TERP.HTCClient/Common/Util.cs:597`:
//     `str = Object.ToString().Trim();`
//     `while (str.Contains("  ")) str = str.Replace("  ", " ");`
// ⇒ `Trim()` + **gộp mọi khoảng trắng liên tiếp thành MỘT**.
// ⚠️ Nguồn chỉ gộp **dấu cách đôi**, KHÔNG đụng tới tab/xuống dòng — giữ đúng, không "chuẩn hoá" thêm.
// ⚠️ Nguồn chỉ chuẩn hoá ở nhánh **HỢP LỆ** của ô (sau khi qua guard độ dài), không chuẩn hoá trước khi kiểm
//    ⇒ chuỗi 1001 ký tự có nhiều dấu cách vẫn **bị chặn**, không được rút gọn rồi cho qua.
static string StandardizeText(string? s)
{
    if (string.IsNullOrEmpty(s)) return s ?? "";
    var str = s.Trim();
    while (str.Contains("  ")) str = str.Replace("  ", " ");
    return str;
}

// ===== 🔴 #258 BIỂN SỐ XE — HAI mẫu hợp lệ của nguồn =====
// `Views/ExcelUtil/FrmImportCustomer.cs:143-149` (md5 `fb5df1f7` — KHỚP 2 máy):
//     `re1 = ^[1-9]{1}[0-9]{0,1}[A-Z]{1,2}[-]{1}[0-9]{4,5}$`   (biển thường, vd 29A-12345)
//     `re2 = ^[A-Z]{2}[-]{1}[0-9]{4,5}$`                        (biển 2 chữ, vd NG-1234)
//     `if (!re1.IsMatch(x) && !re2.IsMatch(x)) ShowMessageBox("Biển số không hợp lệ")`
// ⇒ hợp lệ khi khớp **MỘT TRONG HAI**; cả hai đều **có anchor** `^…$` (khác regex email ở #251).
// ⚠️ Mẫu chỉ chấp nhận **CHỮ HOA** và bắt buộc dấu gạch ngang.
static bool IsValidPlateNo(string? s)
{
    if (string.IsNullOrWhiteSpace(s)) return false;
    var x = s.Trim();
    return System.Text.RegularExpressions.Regex.IsMatch(x, "^[1-9]{1}[0-9]{0,1}[A-Z]{1,2}[-]{1}[0-9]{4,5}$")
        || System.Text.RegularExpressions.Regex.IsMatch(x, "^[A-Z]{2}[-]{1}[0-9]{4,5}$");
}

// ===== 🔴 #255 QUY TẮC "KÝ TỰ ĐẶC BIỆT" THỨ HAI — `StringUtils.ValidateSpecialCharacter` =====
// Nguồn `CommonUtils/CommonUtils.cs:496-503` (md5 `5de6e9b7` — KHỚP 2 máy):
//     `const string specialChars = @"()";`
//     `if (str.Contains(Environment.NewLine) || str.Contains("\n")) return true;`
//     `return str.Count(ch => specialChars.Contains(ch)) >= 1;`
// ⇒ CHỈ cấm **dấu ngoặc tròn** và **xuống dòng**. Chữ tiếng Việt, khoảng trắng, mọi ký tự khác đều
//   **CHO PHÉP** — hợp lý vì nó dùng cho TÊN và ĐỊA CHỈ, không phải cho MÃ.
// 🔴 KHÁC HẲN `HasSpecialChar` (regex lớp cha `[^a-zA-Z0-9._-]`) dù tên gọi na ná. Hai quy tắc song song;
//   dùng nhầm ⇒ hoặc chặn sạch tên tiếng Việt, hoặc để lọt dấu ngoặc.
static bool HasParenOrNewline(string? s) =>
    !string.IsNullOrEmpty(s) && (s.Contains('\n') || s.Contains('\r') || s.Contains('(') || s.Contains(')'));

// 🔴 #249: phải là LOCAL FUNCTION, không phải biến cục bộ — nhiều endpoint dùng nó nằm **TRƯỚC** chỗ này
//    trong Program.cs (vd `/api/deliverylocations` ở đầu file). Local function gọi trước khi khai đều được;
//    biến cục bộ thì không (và `static readonly` field thì CS0106 — xem #248).
static bool HasSpecialChar(string? s) =>
    !string.IsNullOrEmpty(s) && System.Text.RegularExpressions.Regex.IsMatch(s, "[^a-zA-Z0-9._-]");

// ===== 🔴 #253 ẢNH ĐÍNH KÈM LỆNH SỬA CHỮA — `FrmROAttachment` (Views/Services, 407 dòng) =====
// BƯỚC 3B: md5 `d81f1052` — KHỚP 2 máy. Tầng ghi của nguồn: `_serROAttachment.UploadFileImageV2_ForRO`
//   (đẩy file base64) rồi `SerROAttachmentUpload(strROID, ds)`; đọc bằng `SerROAttachmentGet(strROID)`.
//
// 🔴 BỐN GUARD TÊN FILE, đúng THỨ TỰ của nguồn (:319-342) — mỗi guard một THÔNG ĐIỆP riêng:
//  1. `Util.IsUnicode(item)`   ⇒ "Tên ảnh không được để tiếng việt!"
//  2. `item.Contains(" ")`     ⇒ "Tên ảnh không được để dấu cách!"
//  3. `regex.IsMatch(item)`    ⇒ "Tên ảnh không được có ký tự đặc biệt!"
//  4. `item.Length > 45`       ⇒ "Tên ảnh không được quá 45 ký tự!"
// ⚠️ Guard 3 (`[^a-zA-Z0-9._-]`) **đã bao** guard 1 và 2 (tiếng Việt và khoảng trắng đều là ký tự đặc biệt).
//    Nguồn vẫn kiểm riêng để **báo đúng lý do**; port giữ đủ 4 theo thứ tự, KHÔNG gộp.
// ⚠️ Ngưỡng **45** là của riêng màn này (cụm Services) — không suy từ 24/192/254 của cụm TST.
// ⚠️ `open.Filter` của nguồn chỉ nhận **jpg · jpeg · gif · bmp** (:307) ⇒ port kiểm phần mở rộng.
app.MapGet("/api/roattachments", async (AppDbContext db, ITenantContext t, string? roNo) =>
{
    var qy = db.RoAttachments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(roNo)) qy = qy.Where(x => x.RONo == roNo!.Trim().ToUpperInvariant());
    var items = await qy.OrderBy(x => x.Id).Take(500)
        .Select(x => new { x.Id, x.RONo, x.ImageName, x.ImagePath, x.CreatedAt,
                           // form hiển thị số LSC kèm tiền tố "LS-" (:203) — chỉ là ĐỊNH DẠNG hiển thị
                           roNoDisplay = "LS-" + x.RONo })
        .ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/roattachments", async (RoAttachmentDto dto, AppDbContext db, ITenantContext t) =>
{
    var roNo = (dto.RONo ?? "").Trim().ToUpperInvariant();
    if (roNo.Length == 0) return Results.BadRequest(new { error = "Chưa có số lệnh sửa chữa." });
    var name = (dto.ImageName ?? "").Trim();
    if (name.Length == 0) return Results.BadRequest(new { error = "Chưa chọn ảnh." });

    // --- 4 guard của nguồn, giữ NGUYÊN thứ tự và thông điệp ---
    // 1) tiếng Việt: nguồn dùng `Util.IsUnicode` ⇒ có ký tự ngoài bảng ASCII
    if (name.Any(ch => ch > 127))
        return Results.BadRequest(new { error = "Tên ảnh không được để tiếng việt!" });
    if (name.Contains(' '))
        return Results.BadRequest(new { error = "Tên ảnh không được để dấu cách!" });
    if (HasSpecialChar(name))
        return Results.BadRequest(new { error = "Tên ảnh không được có ký tự đặc biệt!" });
    if (name.Length > 45)
        return Results.BadRequest(new { error = "Tên ảnh không được quá 45 ký tự!" });

    // phần mở rộng theo `open.Filter` của nguồn
    var ext = System.IO.Path.GetExtension(name).ToLowerInvariant();
    if (ext is not (".jpg" or ".jpeg" or ".gif" or ".bmp"))
        return Results.BadRequest(new { error = "Chỉ nhận ảnh jpg, jpeg, gif, bmp.", imageName = name });

    var row = new RoAttachment { OrgId = t.OrgId, RONo = roNo, ImageName = name, ImagePath = dto.ImagePath };
    db.RoAttachments.Add(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.RONo, row.ImageName, row.ImagePath, roNoDisplay = "LS-" + row.RONo });
}).RequireAuthorization();

app.MapDelete("/api/roattachments/{id:long}", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.RoAttachments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    db.RoAttachments.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = id });
}).RequireAuthorization();

// ===== 🔴 #247 BẢNG TẠM PHỤ TÙNG TST — `TST_Mst_Part_Temp_Get` (BizCarSv.Bravo.cs:223) =====
// BƯỚC 3B: `BizCarSv.Bravo.cs` md5 `44509215` (469 dòng) — KHỚP 2 máy (đã đo ở #212).
//
// 🔴 ĐÍNH CHÍNH SWEEP #246: tôi liệt kê "5 hàm gọi `CallBravo`" và xếp `TST_Mst_Part_Temp_Get` vào đó.
//    SAI. Dòng `CallBravo(` trong file này (:374) là **ĐỊNH NGHĨA hàm**
//    (`public UtilBravo.RT_Bravo CallBravo(...)`), không phải lời gọi — bộ lọc của sweep chỉ loại
//    `static`/`private` nên định nghĩa `public` lọt lưới, rồi awk gán nhầm cho hàm `public DataSet` liền trước.
//    ⇒ Số hàm THẬT SỰ gọi Bravo là **BỐN**, và **cả bốn đã port**:
//      `Ser_Order_Part_Appr` (#246) · `TST_Mst_Part_Get01` (#245) · `Req_PartPrice_SentTST` (#239)
//      · `Ser_OrderComplain_SentTST` (#239).  Nợ "hàm Bravo thứ 5" ghi ở #246 là **không tồn tại**.
//
// Hàm này chỉ `select t.* from TST_Mst_Part_Temp` với hai bộ lọc khớp **CHÍNH XÁC**
//   (`TSTPartCode`, `TSTVieName`; rỗng = bỏ lọc — mẫu `('@x' = N'' or t.Col = '@x')`).
// ⚠️ Toàn solution DMSCarSv **KHÔNG có nơi GHI** bảng này và **không màn client nào gọi**
//    (chỉ lộ ra ở gateway `WSCarSv.asmx.cs:40231`) ⇒ dữ liệu do hệ NGOÀI nạp; đây là API phục vụ hệ ngoài.
//    Vì thế port **CHỈ đường đọc** — không bịa POST.
app.MapGet("/api/tstparts/temp", async (AppDbContext db, ITenantContext t,
    string? tstPartCode, string? tstVieName) =>
{
    var qy = db.TstPartTemps.Where(x => x.OrgId == t.OrgId);
    // khớp CHÍNH XÁC (nguồn dùng "=" chứ không phải like)
    if (!string.IsNullOrWhiteSpace(tstPartCode)) qy = qy.Where(x => x.TSTPartCode == tstPartCode!.Trim());
    if (!string.IsNullOrWhiteSpace(tstVieName)) qy = qy.Where(x => x.TSTVieName == tstVieName!.Trim());

    var items = await qy.OrderBy(x => x.TSTPartCode).Take(1000)
        .Select(x => new { x.Id, x.TSTPartCode, x.TSTVieName }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        note = "Bảng TẠM: DMSCarSv chỉ ĐỌC, dữ liệu do hệ ngoài nạp. Hai cột là bộ đã xác nhận (nguồn select *).",
    });
}).RequireAuthorization();

// ===== 🔴 #245 TRA PHỤ TÙNG TST THEO NHIỀU MÃ — `TST_Mst_Part_Get01` (BizCarSv.Service.cs:18409) =====
// Màn: `Views/TST/FrmTSTPart_Search.cs` (744 dòng, DMSCarSv/TST). BƯỚC 3B: md5 `5e5d6f20` — KHỚP 2 máy.
//
// 🔴 Ô `txtPartCodeMulti` cho nhập **NHIỀU MÃ, mỗi mã một DÒNG**; form `Split("\r\n")` rồi **nối lại bằng
//    `", "`** thành một chuỗi gửi đi (:311-327). Nếu API lỗi, nguồn báo đúng câu:
//    "Mã phụ tùng ngăn cách nhau bởi dấu phẩy!" (:18500).
//    ⇒ endpoint nhận `codes` và **tách theo cả dấu phẩy LẪN xuống dòng**, giữ đúng cách người dùng nhập.
// ⚠️ Nguồn gọi **API Bravo** (GetToken → CallBravo) chứ không query DB; MiniHTC tra bảng `TstParts` đã đồng
//    bộ sẵn (#212 `/api/tstparts/sync-all`) — nợ lớp gọi Bravo trực tiếp vẫn còn.
app.MapGet("/api/tstparts", async (AppDbContext db, ITenantContext t, string? q, string? group, bool? all,
    string? codes) =>
{
    var qry = db.TstParts.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(group)) qry = qry.Where(x => x.PartGroup == group);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.TSTPartCode.Contains(q!) || x.VieName!.Contains(q!) || x.VieNameHTC!.Contains(q!));
    if (!string.IsNullOrWhiteSpace(codes))
    {
        // tách theo dấu phẩy, xuống dòng, chấm phẩy — người dùng dán từ Excel hay gõ tay đều nhận
        var list = codes.Split(new[] { ',', '\n', '\r', ';' }, StringSplitOptions.RemoveEmptyEntries)
                        .Select(x => x.Trim().ToUpperInvariant())
                        .Where(x => x.Length > 0).Distinct().ToList();
        if (list.Count == 0)
            return Results.BadRequest(new { error = "Mã phụ tùng ngăn cách nhau bởi dấu phẩy!" });
        qry = qry.Where(x => list.Contains(x.TSTPartCode));
    }
    var items = await qry.OrderBy(x => x.TSTPartCode).Take(500).Select(x => new
    {
        x.Id, x.TSTPartCode, x.VieNameHTC, x.VieName, x.EngName, x.Unit, x.VAT, x.TSTPrice,
        x.PartGroup, x.PartType, x.FlagActive, x.LUDTime,
        // #245: 16 cột bổ sung (§12 — có ở cả GET lẫn POST)
        // ===== 🔴 #262 CỘT DB THẬT (`TblTSTMSTPart`) vs CỘT CỦA DATATABLE API (#245) =====
        // Nhóm dưới đây là **cột DB** theo lớp hằng `TblTSTMSTPart` (DbDefine.cs:695-721, md5 `d373e758`).
        x.TSTPriceBefore, x.TSTCost, x.DateEffect, x.TSTUnit,
        x.GroupCode, x.GroupName, x.TypeCode, x.TypeName,
        x.TSTWarrantyPrice, x.TSTUrgentPrice, x.UpdateBy, x.UpdateDateTime, x.LUBy,
        // Nhóm dưới là cột của **DataTable trả về từ Bravo** (#245) — giữ để không mất dữ liệu API.
        x.MinOrderQuantity,
        x.TSTPriceList, x.TSTPriceUrgent, x.TSTPriceWarranty, x.TaxRate,
        x.DongAnhStockStatus, x.CaiMepStockStatus, x.HoChiMinhStockStatus,
        x.TSTPartCodeNew, x.TSTPartCodeOld, x.Remark, x.ModelList,
        x.Length, x.Width, x.Height,
    }).ToListAsync();   // #212 §12 + #245
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/tstparts", async (TstPartDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.TSTPartCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(code)) return Results.BadRequest(new { error = "Chưa nhập mã phụ tùng TST." });
    // #249: `FrmTST_Mst_Exchange_Unit.cs` kiểm `regex.IsMatch(strTSTPartCode)` / `(tstPartCode)`
    if (HasSpecialChar(code))
        return Results.BadRequest(new { error = "Mã vật tư không được phép chứa các ký tự đặc biệt", code });
    if (dto.TSTPrice < 0 || dto.VAT < 0) return Results.BadRequest(new { error = "Giá/VAT không được âm." });
    var row = await db.TstParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TSTPartCode == code);
    if (row is null) { row = new TstPart { OrgId = t.OrgId, TSTPartCode = code }; db.TstParts.Add(row); }
    row.VieNameHTC = dto.VieNameHTC; row.VieName = dto.VieName; row.EngName = dto.EngName; row.Unit = dto.Unit; row.VAT = dto.VAT; row.TSTPrice = dto.TSTPrice; row.PartGroup = dto.PartGroup; row.PartType = dto.PartType; row.UpdatedAt = DateTime.Now;
    // #245: 16 cột bổ sung — chỉ ghi đè khi client CÓ truyền, để lệnh đồng bộ (#212) không xoá mất
    //   dữ liệu do màn nhập tay điền.
    // #262: 13 cột DB thật — chỉ ghi đè khi client CÓ truyền (giống nhóm #245).
    if (dto.TSTPriceBefore is not null) row.TSTPriceBefore = dto.TSTPriceBefore;
    if (dto.TSTCost is not null) row.TSTCost = dto.TSTCost;
    if (dto.DateEffect is not null) row.DateEffect = dto.DateEffect;
    if (dto.TSTUnit is not null) row.TSTUnit = dto.TSTUnit;
    if (dto.GroupCode is not null) row.GroupCode = dto.GroupCode;
    if (dto.GroupName is not null) row.GroupName = dto.GroupName;
    if (dto.TypeCode is not null) row.TypeCode = dto.TypeCode;
    if (dto.TypeName is not null) row.TypeName = dto.TypeName;
    if (dto.TSTWarrantyPrice is not null) row.TSTWarrantyPrice = dto.TSTWarrantyPrice;
    if (dto.TSTUrgentPrice is not null) row.TSTUrgentPrice = dto.TSTUrgentPrice;
