// ===== 🔴 #355 KHÁCH ĐỦ ĐIỀU KIỆN KHẢO SÁT J.D. POWER — `Ser_Customer_GetByJDPowerTerm` =====
// (`BizCarSv.Service01.cs:16692`; WS `WSCarSv.asmx.cs` CÓ gọi ⇒ LIVE). MiniHTC trước nay mới port
//   **master kỳ khảo sát** (CRUD), chưa có phần **dùng** cửa sổ kỳ để lọc lệnh.
//
// 🔴 LỖI TIỀM ẨN CỦA NGUỒN — cửa sổ kỳ lấy bằng **HAI truy vấn `TOP 1` ĐỘC LẬP, đều KHÔNG `order by`**:
//   `AND RO.CheckInDate >= (SELECT TOP 1 JDPStartDate FROM JDP_Mst_JDPowerTerm WHERE FlagActive='1')`
//   `AND RO.CheckInDate <= (SELECT TOP 1 JPDEndDate   FROM JDP_Mst_JDPowerTerm WHERE FlagActive='1')`
//   ⇒ Nếu có **nhiều hơn một** kỳ đang hiệu lực thì ngày ĐẦU và ngày CUỐI có thể đến từ **HAI BẢN GHI
//     KHÁC NHAU** — cửa sổ lai, không tương ứng kỳ nào cả. Nặng hơn "lấy dòng bất kỳ" thông thường.
//   ⇒ Port đọc **MỘT** bản ghi kỳ (thứ tự xác định) cho cả hai đầu, và **báo cờ** khi >1 kỳ đang hiệu lực.
// ⚠️ Chính tả nguồn: `JDPStartDate` nhưng `J**PD**EndDate` (đảo PD/DP) — giữ nguyên khi đối chiếu.
//
// Bộ lọc của nguồn:
//   `RO.Status NOT IN ('CRE','PRT','HPA','NORE','REJ')` — **danh sách ĐEN**, mã lạ vẫn được tính
//   `cus.IsActive = '1'` · `CheckInDate` trong cửa sổ kỳ
//   `ltrim(rtrim(car.TradeMarkCode)) IN ('Hyundai','HYUNDAI')` — nguồn liệt kê **hai biến thể hoa/thường**
//     vì đối chiếu chuỗi có phân biệt; port dùng so sánh không phân biệt hoa thường, kết quả bao trùm.
// ⚠️ Nguồn trả `TOP 1` (cũng không `order by`) ⇒ "một khách bất kỳ đủ điều kiện". Port giữ 1 bản ghi
//   nhưng sắp xếp xác định để gọi hai lần ra cùng kết quả.
app.MapGet("/api/jdpowerterms/eligible", async (AppDbContext db, ITenantContext t,
    string? cusCode, string? dealerCode, string? roNo) =>
{
    var terms = await db.JDPowerTerms.Where(x => x.OrgId == t.OrgId && x.FlagActive == "1")
        .OrderBy(x => x.Id).ToListAsync();
    if (terms.Count == 0)
        return Results.BadRequest(new { error = "Chưa khai kỳ khảo sát J.D. Power nào đang hiệu lực." });

    var term = terms[0];
    if (term.StartDate is null || term.EndDate is null)
        return Results.BadRequest(new { error = "Kỳ khảo sát thiếu ngày bắt đầu hoặc ngày kết thúc.", term.JDPTermCode });

    // Danh sách ĐEN đúng nguồn — dùng mã của nguồn rồi đổi sang nhãn MiniHTC.
    var blocked = new[] { "Created", "PrintedQuote", "HasPart", "NotResponding", "Rejected" };

    var qy = from r in db.RepairOrders
             join c in db.ServiceCustomers on r.CusName equals c.CusName
             where r.OrgId == t.OrgId && c.OrgId == t.OrgId
                && !blocked.Contains(r.Status)
                && c.FlagActive == "1"
                && r.CheckInDate != null
                && r.CheckInDate >= term.StartDate && r.CheckInDate <= term.EndDate
             select new { r.RONo, r.Status, r.CheckInDate, c.CusCode, c.CusName, c.DealerCode, r.Vin };

    if (!string.IsNullOrWhiteSpace(cusCode)) qy = qy.Where(x => x.CusCode == cusCode!.Trim());
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(roNo)) qy = qy.Where(x => x.RONo == roNo!.Trim().ToUpperInvariant());

    // Nguồn lọc hãng xe trên `Ser_Car.TradeMarkCode`; MiniHTC nối xe qua số khung của lệnh.
    var rows = await qy.OrderBy(x => x.RONo).Take(50).ToListAsync();
    var vins = rows.Select(x => x.Vin).ToList();
    var hyundaiVins = (await db.ServiceCars
            .Where(c => c.OrgId == t.OrgId && c.FrameNo != null && vins.Contains(c.FrameNo))
            .Select(c => new { c.FrameNo, c.TradeMark }).ToListAsync())
        .Where(c => string.Equals((c.TradeMark ?? "").Trim(), "Hyundai", StringComparison.OrdinalIgnoreCase))
        .Select(c => c.FrameNo).ToHashSet();
    var hit = rows.FirstOrDefault(x => x.Vin != null && hyundaiVins.Contains(x.Vin));

    return Results.Ok(new
    {
        term = new { term.JDPTermCode, term.JDPTermName, term.StartDate, term.EndDate },
        eligible = hit,
        found = hit is not null,
        // 🔴 Nguồn lấy ngày đầu/cuối bằng HAI `TOP 1` độc lập ⇒ nhiều kỳ hiệu lực thì cửa sổ có thể LAI.
        activeTermCount = terms.Count,
        mixedWindowRisk = terms.Count > 1,
        mixedWindowNote = terms.Count > 1
            ? "Có " + terms.Count + " kỳ đang hiệu lực. Nguồn lấy JDPStartDate và JPDEndDate bằng hai TOP 1 "
              + "ĐỘC LẬP không order by ⇒ cửa sổ của nguồn có thể ghép từ hai kỳ khác nhau. Web dùng MỘT kỳ."
            : null,
    });
}).RequireAuthorization();

// ===== 🔴 #356 LỊCH CÔNG ĐOẠN CỦA LỆNH GỬI SANG VELOCA — `OSVeloca_Ser_RO_GetByROID` =====
// (`BizCarSv.ZTemp.cs:15373`). Hệ **Veloca CHỈ có trên máy 150** (đúng cảnh báo 3B).
// Toàn bộ dữ liệu **DẪN XUẤT**, không có bảng lưu riêng: loại công việc lấy từ dòng dịch vụ của lệnh,
//   lịch công đoạn lấy từ **phân công công việc** (`Ser_AssignmentWork`).
//
// 🔴 GỘP 6 LOẠI THÀNH 3 khi báo sang Veloca (`case` trên `srsi.ROType`):
//   `BDD → SCC` · `PDI → SCC` · `SPK → SCC` · `SCC → SCC` · `SCD → SCD` · `SCS → SCS`
//   ⇒ Veloca chỉ biết **BA** nhóm; bốn loại công việc khác nhau bên trong đều hiện ra là **SCC**.
//     Đừng dùng số liệu Veloca để đối chiếu KPI theo loại (#335 đếm đủ 6 loại) — hai bên khác hạt.
// ⚠️ `case` **KHÔNG có `else`** ⇒ mã `ROType` lạ cho ra `GroupRepairType = NULL`, không phải bỏ dòng.
//
// ⚠️ MỐC THỜI GIAN đổi sang UTC bằng `DateAdd(hh, -7, …)` rồi `CONVERT(varchar, …, 20)`
//   ⇒ **trừ cứng 7 giờ** (VN = UTC+7) và định dạng `yyyy-MM-dd HH:mm:ss`. Không dùng múi giờ hệ thống:
//     máy chạy ở múi khác vẫn phải ra đúng con số này.
//
// 🔴 `top 1` KHÔNG `order by` ở nhánh "thay thế": dòng công đoạn có `GroupRepairType` **không nằm trong**
//   bảng loại công việc của lệnh sẽ được thay bằng **một loại BẤT KỲ** trong tập còn lại của cùng lệnh
//   (`select top 1 g.GroupRepairType … where g.RONoSys = t.RONoSys`).
//   ⇒ Port chọn **xác định** (thứ tự bảng chữ cái) + trả cờ `replacedType` để chỗ nào lệch còn truy được.
// ===== 🔴 #357 TIỀN THEO NGUỒN CHI TRẢ + CÔNG NỢ của lệnh (lát thứ hai của `OSVeloca_Ser_RO_GetByROID`) =====
// Nguồn tách tiền từng dòng theo `ExpenseType` rồi cộng lại:
//   `ROREPAIR`                      → `RepairAmountAfterVAT`        = `Factor×Price×Qty×(1+VAT%)`
//   `ROINSURANCE` + `InsurancePrice > 0` → `PartialRepairAmountAfterVAT`   = **`InsurancePrice`**
//                                     và `PartialInsuranceAmountAfterVAT` = **toàn dòng − InsurancePrice**
//   `ROINSURANCE` + `InsurancePrice` rỗng/0 → `FullInsuranceAmountAfterVAT` = toàn dòng
//   `ROWARRANTY` → `WarrantyAmountAfterVAT` · `LOCAL` → `LocalAmountAfterVAT`
// Tổng: `RepairAmountAfterVAT = Σ(Repair + PartialRepair)` · `InsuranceAmountAfterVAT = Σ(PartialIns + FullIns)`
//
// 🔴 MÂU THUẪN CẦN NGƯỜI NGHIỆP VỤ CHỐT — cùng cột `InsurancePrice`, hai báo cáo hiểu NGƯỢC NHAU:
//   • Ở ĐÂY: `InsurancePrice` được cộng vào **phía SỬA CHỮA** (`PartialRepair`), phần còn lại mới là bảo hiểm.
//   • Ở #342 (`ProcessGetInsuranceDebit`): `when InsurancePrice > 0 then InsurancePrice` chính là
//     **số tiền BẢO HIỂM** dùng để ghi công nợ hãng bảo hiểm.
//   ⇒ Một bên coi nó là phần KHÁCH chịu, một bên coi là phần BẢO HIỂM chịu. Tôi **KHÔNG tự chọn bên nào**:
//     port đúng công thức của TỪNG báo cáo và trả cờ `insurancePriceConventionConflict` để người có
//     nghiệp vụ đối chiếu. Tự "thống nhất" hai bên là đổi số tiền trên chứng từ thật.
//
// 🔴 CÔNG THỨC CŨ BỊ COMMENT kèm ghi chú của chính tác giả:
//   `//, (ServiceAmountAfterVAT + PartAmountAfterVAT - TotalDebitAmount) TotalValCusPmt -- 20231209. HuongTTT: Sai`
//   Bản ĐANG CHẠY: `(RepairAmountAfterVAT - TotalCusDebitAmount) TotalValCusPmt`
//   ⇒ Khác hai chỗ: dùng **RepairAmountAfterVAT** (không phải tổng dịch vụ+phụ tùng) và trừ **CHỈ nợ
//     KHÁCH** (không phải tổng nợ). Port bản active (lệ "port dòng đang chạy, không port dòng comment").
//
// ⚠️ `Ser_CusDebit` của nguồn là **MỘT bảng** phân biệt bằng `DebitType` (**'1'** = nợ khách · **'2'** = nợ
//   bảo hiểm — khớp hằng `TConst.SerDebitType.InsuranceDebit` tìm ở #342). MiniHTC tách thành **HAI**
//   entity `CusDebit` và `InsDebit` ⇒ ở đây phải cộng từ hai nguồn mới ra đúng `TotalDebitAmount`.
// ===== 🔴 #359 DÒNG CÔNG VIỆC CỦA BÁO GIÁ gửi Veloca (`Table 9` của `OSVeloca_Ser_RO_GetByROID`) =====
// 🔴 ĐÍNH CHÍNH #356: ở **cấp DÒNG** Veloca nhận **ĐỦ SÁU** loại công việc, KHÔNG gộp:
//   `BDD → BAODUONG` · `SCC → SUACHUA` · `SCD → SUACHUADONG` · `SCS → SUACHUASON`
//   `PDI → PDI` · `SPK → PHUKIEN`
//   Phép gộp 6→3 ở #356 **chỉ áp cho `Table 12` (loại công việc/lịch công đoạn)**. Hai cấp, hai hạt —
//   nói "Veloca chỉ biết 3 nhóm" là **thiếu chính xác**; đúng là *lịch công đoạn* chỉ có 3 nhóm.
//
// Đối tượng chi trả: `ROWARRANTY → BAOHANH` · `ROINSURANCE → BAOHIEM` · `ROREPAIR → KHACHHANG`
//   · `LOCAL → NOIBO`. Cả hai bảng mã đều **KHÔNG có nhánh `else`** ⇒ mã lạ ra NULL.
//
// 🔴 `Factor` MANG HAI NGHĨA tuỳ khoảng giá trị:
//   `Factor ≤ 1`  ⇒ **hệ số CHIẾT KHẤU**: `UP = Price` (giá gốc), `DiscountRate = (1 − Factor)×100`
//   `Factor > 1`  ⇒ **hệ số NHÂN GIÁ**:   `UP = Price × Factor`, `DiscountRate = 0`
//   `Factor < 0`  ⇒ `DiscountRate = 0` (chặn âm)
//   ⇒ Veloca nhận **giá GỐC + tỉ lệ chiết khấu**, không phải giá đã chiết khấu. Tiền thực vẫn là
//     `Factor × Price` nên khớp công thức KPI (#336) — chỉ khác cách TRÌNH BÀY.
//
// ⚠️ CẶP COMMENT/ACTIVE: `ValInsAfterVATService` bản cũ (bị comment) tính
//   `(Factor×Price)×(1+VAT) khi ExpenseType = ROINSURANCE`; bản **đang chạy** dùng
//   `PartialInsuranceAmountAfterVAT + FullInsuranceAmountAfterVAT` — chính phép tách đã port ở #357.
// ===== 🔴 #360 DÒNG PHỤ TÙNG của báo giá gửi Veloca (`Table 10`) =====
// 🔴 `RepairType` của dòng PHỤ TÙNG **KHÔNG lấy từ chính dòng đó** mà từ **dòng DỊCH VỤ ĐẦU TIÊN**
//   của lệnh — nguồn ghi rõ trong chú thích:
//   `select top 1 (case … end) from Ser_ROServiceItems where t.ROID = srsi.ROID order by srsi.ItemID asc`
//   `-- 20240521. HuongTTT: Lấy Loại sửa chữa đầu tiên của Dịch vụ`
//   ⇒ Lệnh vừa có bảo dưỡng vừa có sửa chữa sơn thì **MỌI dòng phụ tùng** đều mang loại của dòng dịch vụ
//     có `ItemID` nhỏ nhất. Đây là **đơn giản hoá có chủ đích của nguồn**, không phải lỗi — nhưng nếu bên
//     Veloca thống kê phụ tùng theo loại sửa chữa thì số đó **không phản ánh phụ tùng thực dùng cho loại nào**.
//   ✅ `top 1` này **CÓ `order by`** (khác 21 chỗ thiếu order by đã ghi ở sổ) ⇒ kết quả **xác định**.
//
// Khác dòng dịch vụ (#359): có thêm `Qty`, và **mọi công thức tiền đều nhân thêm `Quantity`**
//   (`ValBeforeVATPart = Price × Factor × Quantity` …) — cùng lệ #337: phụ tùng có bốn thừa số.
// `Factor` vẫn mang hai nghĩa như #359 (≤1 chiết khấu, >1 nhân giá).
// ⚠️ Lại một CẶP COMMENT/ACTIVE: `ValInsAfterVATPart` bản cũ tính thẳng theo `ROINSURANCE`; bản đang
//   chạy dùng `PartialInsuranceAmountAfterVAT + FullInsuranceAmountAfterVAT` (phép tách #357).
// ===== 🔴 #361 KỸ THUẬT VIÊN của báo giá gửi Veloca (`Table 11`) =====
// Hai dòng **bị comment kèm ngày** ở đây mang **quyết định tích hợp**, không phải rác:
//   `--, sawe.EngineerID EngineerNo   --20241204. Không dùng mã hệ thống để đồng bộ`
//     ⇒ **KHÔNG gửi mã nội bộ** (`EngineerID`) sang Veloca; phải gửi `EngineerNo` (mã nghiệp vụ).
//     MiniHTC vốn đã lưu `EngineerNo` trên `SerAssignmentWorkEngineer` nên khớp sẵn.
//   `--inner join Ser_ROServiceItemsEngineer srsie  -- 20240215.`
//     ⇒ nguồn **ĐỔI BẢNG NGUỒN**: trước lấy KTV gán theo **dòng dịch vụ**, nay lấy KTV theo **PHÂN CÔNG**
//       (`Ser_AssignmentWorkEngineer`), nối bằng `WorkType`. Port bảng nào là khác biệt thật về dữ liệu.
//
// 🔴 NỐI THEO `WorkType` ⇒ **TÍCH CHÉO**: một KTV được phân công loại SCC sẽ xuất hiện cạnh **MỌI** dòng
//   dịch vụ có `WorkType = SCC`. Lệnh có 3 dòng SCC và 2 KTV SCC ⇒ **6 dòng**. Đây là ý đồ của nguồn
//   (Veloca cần biết ai làm việc gì), nhưng **đừng đếm số dòng này ra "số KTV"**.
// ⚠️ `WorkType` dùng ở đây là bản **ĐÃ GỘP 6→3** (`#tbl_Ser_ROServiceItems_WorkType`, chú thích 20240215)
//   — cùng phép gộp của `Table 12`, KHÁC `RepairType` cấp dòng vốn giữ đủ 6 (#359).
// ===== 🔴 #362 ĐẦU LỆNH gửi Veloca (`Table 8` — bảng trung tâm của `OSVeloca_Ser_RO_GetByROID`) =====
// 🔴 `CustomerCode` — quyết định hợp nhất mã khách (`20240401`):
//   `case when sc.SalesCusID is not null and sc.SalesCusID <> '' then sc.SalesCusID else CusID end`
//   *"Dùng mã KH Sales để đồng bộ… Mục đích: 1 KH ở cả DMS và Veloca đều có 1 mã KH duy nhất"*
//   ⇒ Dùng thẳng `CusID` là **tạo trùng khách bên Veloca**. Đã thêm cột `SalesCusID` (§12).
// 🔴 `InsCode` (`20240205`): đổi từ `sr.InsNo` (số bảo hiểm trên **LỆNH**) sang `scar.InsNo` (trên **XE**).
//   Lại một cặp comment/active đổi **nguồn dữ liệu**, không phải dọn code.
// ⚠️ `TotalValAfterVATRO` (`20240124`): bản cũ **trừ** `AmountDiscountOther`, bản đang chạy **KHÔNG trừ**.
//   Giảm trừ đó chỉ vào `TotalValEnd` và `TotalValCusROAfterVAT`.
// 🔴 MIỄN THƯỜNG (`InsuranceDeductible`) là phần **KHÁCH chịu**:
//   `TotalValCusROAfterVAT = RepairAmountAfterVAT + InsuranceDeductible − AmountDiscountOther − AmountFromMC`
//   `TotalValInsROAfterVAT = InsuranceAmountAfterVAT − InsuranceDeductible` — **khớp đúng** công thức ghi
//   công nợ bảo hiểm ở #342 (nợ = tiền bảo hiểm − miễn thường).
// ⚠️ `FinishDTimeUTC` lấy `sr.FinishedDate` = lúc **SỬA XONG** (xem #340), KHÔNG phải lúc giao xe.
// ⚠️ `CusPmtDateUTC` và `PaidDTimeUTC` **cùng lấy** `PaidCreatedDate` — nguồn trả hai tên cho một mốc.
// ⚠️ `FlagRetry = sr.IsReRepair` — chính cột port ở #343; nếu không vá lượt đó thì trường này luôn rỗng.
// ===== 🔴 #363 CHĂM SÓC 72h + NHẮC BẢO DƯỠNG gửi Veloca (`Table 18` & `Table 19`) =====
// 🔴 HAI BẢNG MÃ TRẠNG THÁI KHÁC NHAU cho **cùng ba trạng thái** — trong cùng một API:
//   `Table 18` (chăm sóc 72h) dùng mã CHỮ:  `PEND → PENDING` · `CINFB → CONTACTED`
//                                            `CIFB → CONTACTED` · `REJ → CANCEL`
//   `Table 19` (nhắc bảo dưỡng) dùng mã SỐ: `'0' → PENDING` · `'1' → CONTACTED` · `'2' → CANCEL`
//   ⇒ Đừng dùng chung một hàm đổi mã cho hai bảng.
// 🔴 `CINFB` và `CIFB` (đã liên hệ CÓ / KHÔNG phản hồi) **gộp làm một** `CONTACTED`
//   ⇒ bên Veloca **không phân biệt được** khách có phản hồi hay không.
// 🔴 Trường tên `ContactDateUTC`/`ContactDTimeUTC` **KHÔNG hề đổi sang UTC**: nguồn gán thẳng
//   `scc.ContactDate`, khác hẳn các mốc khác vốn dùng `DateAdd(hh, -7, …)` (#356).
//   ⇒ **Tên trường nói dối**: hậu tố `UTC` nhưng giá trị là giờ ĐỊA PHƯƠNG. Giữ 1:1 và báo cờ,
//     vì "sửa cho đúng tên" sẽ lệch 7 giờ so với dữ liệu Veloca đang có.
// ⚠️ Nguồn trả **hai tên cho một giá trị** ở cả hai bảng (`ContactDateUTC` = `ContactDTimeUTC`;
//   `Note` = `CusCare72hRemark`) — cùng thói quen đã thấy ở `Table 8` (#362).
// ⚠️ Chính tả nguồn: `CusCare72hSatus` (thiếu chữ "t"). Giữ nguyên tên trường theo nguồn.
// ===== 🔴 #364 CỤM BẢO HIỂM gửi Veloca (`Table 15/16/17`) =====
// 🔴 `Table 15`: **hãng bảo hiểm được gửi sang Veloca NHƯ MỘT KHÁCH HÀNG** — các trường đều mang tiền tố
//   `Customer*` (`CustomerCode = InsNo`, `CustomerName = InsVieName`…) và `CustomerGender` đóng cứng
//   **`'TOCHUC'`** (tổ chức). ⇒ Bên Veloca, hãng bảo hiểm nằm chung danh mục KHÁCH HÀNG, không phải
//   danh mục riêng. Đừng port thành một master tách biệt.
// ⚠️ Nguồn đóng cứng RỖNG/NULL **không nhất quán trong cùng một câu lệnh**:
//   `CustomerMobilePhone = ''` · `ContactPhone = ''` nhưng `CustomerDateOfBirth = null` ·
//   `ContactName = null` · `ContactEmail = null`. Giữ đúng từng loại — chuỗi rỗng và NULL khác nhau
//   ở phía nhận.
//
// `Table 16` (hợp đồng bảo hiểm) và `Table 17` (ghép HĐBH–hãng–xe) **cùng dùng lại quy tắc hợp nhất mã
//   khách `SalesCusID`** của #362 (chú thích `20240401`) ⇒ ba bảng, một quy tắc; sửa một chỗ phải sửa cả ba.
// ⚠️ `Table 16` trả **BA TÊN cho MỘT giá trị**: `InsContractNoSys` = `InsContractNo` = `SealNo`
//   (đều là `sc.InsContractNo`) — mức trùng lặp cao hơn cả `Table 8`/`Table 18` (hai tên).
// Bộ lọc chung của 16/17: `InsContractNo is not null and <> ''` ⇒ xe chưa có số hợp đồng thì **không gửi**.
// ===== 🔴 #365 MASTER XE + KHÁCH + MAP gửi Veloca (`Table 4/5/6`) =====
// 🔴 `ContactPhone` — **WORKAROUND cho ràng buộc của HỆ NHẬN**:
//   `case when sc.ContMobile = sc.Mobile then '' else sc.ContMobile end`
//   `-- 20240203. HuongTTT: Vì luật check trùng sdt ở CustomerCenter`
//   ⇒ SĐT người liên hệ **TRÙNG** SĐT khách thì gửi **RỖNG**, vì bên CustomerCenter có luật chống
//     trùng số điện thoại. Bỏ qua bước này ⇒ **bản ghi bị hệ nhận từ chối**. Rất dễ port sót vì
//     nhìn vào chỉ thấy "gán ContMobile".
// 🔴 `CustomerGender`: `Sex = '0' → FEMALE` · `'1' → MALE` · **else `OTHER`** — bảng mã này CÓ nhánh
//   `else` (khác các bảng mã khác trong cùng API vốn ra NULL). ⇒ Nay đã biết nghĩa của guard giới tính
//   ở #332 (chỉ nhận rỗng/"0"/"1"): **1 = NAM, 0 = NỮ**.
// 🔴 `CustomerType` (`20240206`): `CusTypeID` rỗng/null **HOẶC** loại người = cá nhân ⇒ `CANHAN`, còn lại
//   `TOCHUC` — **thiếu thông tin cũng thành CÁ NHÂN**, không phải để trống.
// ⚠️ `BHInvoiceCTMCode = 'HTV'` đóng cứng (`20240220`: *"Xe con mặc định đơn vị bảo hành mã là HTV"*).
// ⚠️ `BankCode` và `BankName` **cùng lấy** `sc.Bank` — lại hai tên một giá trị (#362/#363/#364).
// ⚠️ `CustomerPhoneNo = Isnull(Tel, '')` ⇒ NULL hoá **chuỗi rỗng**, trong khi `CustomerMobilePhone`
//   giữ nguyên NULL. Cùng câu lệnh, hai cách xử lý NULL (cùng lệ #364).
// ⚠️ `Table 4`: `ProductGrpCode` = `'OTHER'` khi `ModelID` null **hoặc bằng 0**; `WarrantyDate` lấy
//   `WarrantyRegistrationDate` — chính cột đã vá ở #334, không có nó thì trường này luôn rỗng.
// 📌 Quy tắc mã khách `SalesCusID` (#362) xuất hiện ở **bốn** bảng: 5 · 6 · 8 · 16/17.
// ===== 🔴 #366 DANH MỤC gửi kèm lệnh sang Veloca (`Table 0/1/2/3`) =====
// Nguồn gửi **danh mục ĐI KÈM từng lệnh** (không phải đồng bộ master toàn bộ): chỉ hiệu xe/model/khoang/KTV
//   **liên quan tới lệnh đó**. ⇒ Veloca tự dựng danh mục từ dữ liệu đi kèm, nên **thiếu một dòng danh mục
//   là hỏng bản ghi tham chiếu tới nó**.
//
// 🔴 `Table 1` (model) là **UNION BA NHÁNH**, không phải một truy vấn:
//   (1) model của **XE**  (2) model của **LỆNH** — hai chỗ có thể KHÁC nhau nên phải lấy cả hai
//   (3) một dòng **`'OTHER'` tự sinh**, chỉ khi `ModelID` của xe `null` hoặc `= 0`
//   ⇒ Nhánh (3) tồn tại để khớp với `ProductGrpCode = 'OTHER'` mà `Table 4` gán cho xe không có model
//     (#365). **Bỏ nhánh này ⇒ Veloca nhận xe trỏ tới nhóm sản phẩm KHÔNG TỒN TẠI.**
// ⚠️ `ProductGrpCode` = `ProductGrpBUCode` (cùng `ModelID`) và `ProductGrpName` = `ProductGrpDesc`
//   (cùng `ModelName`) — hai cặp "hai tên một giá trị" nữa. `ProductGrpBUPattern` = `ModelID + '%'`
//   (mẫu LIKE, không phải mã).
//
// 🔴 `Table 2` (khoang): `CavityType` đổi sang **mã có cấu trúc của Veloca**:
//   `BDN → CABTYPNO.A01.00001` · `SCC → …00002` · `KHAC → …00003`
//   `KD → …00004` · `KS → …00005` · `BS → …00006`
//   ⇒ Không gửi mã nội bộ; Veloca có danh mục loại khoang riêng đánh số sẵn.
// ⚠️ `Table 3` (KTV): dùng `EngineerNo` (quyết định `20241204`, cùng #361) và **`Remark` cũng gán
//   `EngineerNo`** — trùng giá trị với chính khoá, giữ 1:1.
// ===== 🔴 #367 DANH MỤC SẢN PHẨM + KHUYẾN MẠI gửi Veloca (`Table 7` & `Table 20`) — HAI BẢNG CUỐI =====
// 🔴 `Table 7` (`Ser_Mst_Part` — tên bảng nói "phụ tùng") thực ra là **UNION phụ tùng + dịch vụ vào MỘT
//   danh mục SẢN PHẨM duy nhất**, phân biệt bằng `ProductType`: `'PRODUCT'` / `'SERVICE'`.
//   ⇒ Bên Veloca **không có danh mục dịch vụ riêng**; port thành hai master tách biệt là sai mô hình.
//   ⚠️ Đơn vị tính của nhánh dịch vụ đóng cứng `N'Lần'` (dịch vụ không có cột đơn vị).
// 🔴 `ProductNameEN` **KHÔNG phải tên tiếng Anh** — cả hai nhánh đều gán **MÃ** (`PartCode` / `SerCode`),
//   và `Remark` gán **lại chính mã đó**. Tên trường nói dối lần nữa (cùng lệ `…UTC` ở #363):
//   "sửa cho đúng nghĩa" bằng cách đưa tên tiếng Anh thật vào sẽ lệch dữ liệu Veloca đang có.
//   ⇒ Một dòng gửi đi mang mã ở BA ô: `ProductCodeUser` · `ProductNameEN` · `Remark`.
// 🔴 `Table 20` (`Ser_Campaign`) đọc từ **CSDL CommonCenter** (`[@strDBName_CommonCenter]`), không phải DB
//   đại lý — khuyến mại là danh mục DÙNG CHUNG toàn hệ. Lọc `CamID is not null and CamID <> ''` trên
//   **cả dòng dịch vụ lẫn dòng phụ tùng** (UNION hai nhánh, `distinct`).
//   ⇒ §12: đã thêm cột `CamID` vào CẢ HAI bảng dòng RO — trước lượt này MiniHTC không có ô nào ghi mã
//     khuyến mại, nên bảng 20 gửi sang Veloca sẽ **luôn rỗng mà không báo lỗi**.
// ⚠️ `EffDateEnd` lấy `FinishedDate` của chiến dịch (ngày KẾT THÚC chương trình) — trùng TÊN cột với
//   `FinishedDate` của LỆNH SỬA CHỮA vốn là "lúc sửa xong" (#340/#362). Cùng tên, hai nghĩa, hai bảng.
app.MapGet("/api/osveloca/ro/{roNo}/products", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (r is null) return Results.NotFound(new { roNo });

    var partCodes = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == r.Id)
        .Select(p => p.PartCode).Distinct().ToListAsync();
    var serCodes = await db.RoServiceItems.Where(s => s.OrgId == t.OrgId && s.RoId == r.Id)
        .Select(s => s.SerCode).Distinct().ToListAsync();

    // Nhánh PRODUCT — phụ tùng. Mã nằm ở BA ô, đúng nguồn.
    var products = (await db.ServiceParts.Where(x => x.OrgId == t.OrgId && partCodes.Contains(x.PartCode)).ToListAsync())
        .Select(x => new
        {
            roNo, x.DealerCode,
            productCodeUser = x.PartCode,
            productType = "PRODUCT",
            productName = x.PartName,
            productNameEN = x.PartCode,      // ⚠️ là MÃ, không phải tên tiếng Anh
            productBarCode = x.PartID,
            unitCode = x.Unit,
            remark = x.PartCode,             // ⚠️ lại là MÃ
        }).ToList<object>();

    // Nhánh SERVICE — dịch vụ, đơn vị đóng cứng "Lần".
    var services = (await db.ServiceItemMsts.Where(x => x.OrgId == t.OrgId && serCodes.Contains(x.SerCode)).ToListAsync())
        .Select(x => new
        {
            roNo, x.DealerCode,
            productCodeUser = x.SerCode,
            productType = "SERVICE",
            productName = x.SerName,
            productNameEN = x.SerCode,
            productBarCode = x.Id.ToString(),
            unitCode = "Lần",                // nguồn đóng cứng
            remark = x.SerCode,
        }).ToList<object>();

    var all = products.Concat(services).ToList();
    var foundPart = products.Count; var foundSer = services.Count;

    return Results.Ok(new
    {
        roNo, count = all.Count, products = all,
        oneCatalogNote = "Veloca dùng MỘT danh mục sản phẩm chung; phụ tùng và dịch vụ phân biệt bằng ProductType.",
        codeInThreeFieldsNote = "ProductCodeUser = ProductNameEN = Remark (đều là MÃ). Tên trường ProductNameEN nói dối.",
        // Thiếu một dòng danh mục ⇒ Veloca có dòng RO trỏ tới sản phẩm không tồn tại (cùng lệ #366).
        missingPartCodes = partCodes.Except(products.Select(p => (string)p.GetType().GetProperty("productCodeUser")!.GetValue(p)!)).ToList(),
        missingSerCodes = serCodes.Except(services.Select(s => (string)s.GetType().GetProperty("productCodeUser")!.GetValue(s)!)).ToList(),
        joinedByCodeNote = "Nguồn ghép theo PartID/SerID; MiniHTC lưu MÃ trên dòng RO nên ghép theo mã.",
        serviceBarCodeNote = foundSer == 0 ? null
            : "ProductBarCode của dịch vụ dùng khoá nội bộ (MiniHTC chưa có cột SerID riêng).",
        resolved = new { parts = foundPart, services = foundSer },
    });
}).RequireAuthorization();

// Khuyến mại (Table 20) — danh mục DÙNG CHUNG, nguồn đọc từ CSDL CommonCenter.
app.MapGet("/api/osveloca/ro/{roNo}/campaigns", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (r is null) return Results.NotFound(new { roNo });

    // UNION hai nhánh: mã khuyến mại trên dòng DỊCH VỤ và trên dòng PHỤ TÙNG.
    var fromSvc = await db.RoServiceItems.Where(s => s.OrgId == t.OrgId && s.RoId == r.Id && s.CamID != null && s.CamID != "")
        .Select(s => s.CamID!).ToListAsync();
    var fromPrt = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == r.Id && p.CamID != null && p.CamID != "")
        .Select(p => p.CamID!).ToListAsync();
    var camIds = fromSvc.Concat(fromPrt).Distinct().ToList();

    var cams = await db.Campaigns.Where(c => c.OrgId == t.OrgId && camIds.Contains(c.CamNo))
        .Select(c => new
        {
            prmCode = c.CamNo,
            prmName = c.CamName,
            prmDescription = c.Content,
            effDateStart = c.StartDate,
            effDateEnd = c.FinishDate,   // ngày KẾT THÚC chiến dịch — KHÁC FinishedDate của lệnh (#340)
        }).ToListAsync();

    return Results.Ok(new
    {
        roNo, count = cams.Count, campaigns = cams,
        sourceNote = "Nguồn đọc chiến dịch từ CSDL CommonCenter — danh mục dùng chung, không thuộc DB đại lý.",
        fromServiceLines = fromSvc.Distinct().Count(), fromPartLines = fromPrt.Distinct().Count(),
        missingCamIds = camIds.Except(cams.Select(c => c.prmCode)).ToList(),
        effDateEndNote = "EffDateEnd = FinishedDate của CHIẾN DỊCH; đừng nhầm với FinishedDate của lệnh (= lúc sửa xong).",
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/catalogs", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (r is null) return Results.NotFound(new { roNo });

    var car = r.Vin == null ? null
        : await db.ServiceCars.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.FrameNo == r.Vin);

    // Table 0 — hiệu xe của lệnh.
    var brandCode = car?.TradeMark ?? r.TradeMarkCode;
    var brands = brandCode == null ? new List<object>()
        // ServiceTradeMark cua MiniHTC KHONG co DealerCode (nguon Table 0 co) => lay cua LENH.
        : (await db.ServiceTradeMarks.Where(x => x.OrgId == t.OrgId && x.TradeMarkCode == brandCode)
            .Select(x => new { brandCode = x.TradeMarkCode, dealerCode = r.DealerCode, brandName = x.TradeMarkName })
            .ToListAsync()).Cast<object>().ToList();

    // Table 1 — model: UNION ba nhánh (model của XE, model của LỆNH, và dòng OTHER tự sinh).
    var modelCodes = new List<string>();
    if (!string.IsNullOrWhiteSpace(car?.ModelCode)) modelCodes.Add(car!.ModelCode!);
    if (!string.IsNullOrWhiteSpace(r.ModelID)) modelCodes.Add(r.ModelID!);
    modelCodes = modelCodes.Distinct().ToList();

    var models = (await db.ServiceModels.Where(m => m.OrgId == t.OrgId && modelCodes.Contains(m.ModelCode))
            .Select(m => new { m.ModelCode, m.ModelName, m.TradeMarkCode }).ToListAsync())
        .Select(m => new
        {
            productGrpCode = m.ModelCode, productGrpBUCode = m.ModelCode,
            productGrpBUPattern = m.ModelCode + "%",
            dealerCode = r.DealerCode, brandCode = m.TradeMarkCode,
            productGrpName = m.ModelName, productGrpDesc = m.ModelName,
            synthetic = false,
        }).ToList();

    // Nhánh (3): xe KHÔNG có model ⇒ tự sinh dòng OTHER để khớp ProductGrpCode = "OTHER" ở Table 4.
    var carHasNoModel = string.IsNullOrWhiteSpace(car?.ModelCode) || car!.ModelCode == "0";
    if (carHasNoModel && car is not null)
        models.Add(new
        {
            productGrpCode = "OTHER", productGrpBUCode = "OTHER",
            productGrpBUPattern = "OTHER%",
            dealerCode = car.DealerCode, brandCode = car.TradeMark,
            productGrpName = "OTHER", productGrpDesc = "OTHER",
            synthetic = true,
        });

    // Table 2 — khoang của các công đoạn trong lệnh; CavityType đổi sang mã có cấu trúc của Veloca.
    static string? CabinTypeOf(string? ct) => ct switch
    {
        "BDN" => "CABTYPNO.A01.00001", "SCC" => "CABTYPNO.A01.00002",
        "KHAC" => "CABTYPNO.A01.00003", "KD" => "CABTYPNO.A01.00004",
        "KS" => "CABTYPNO.A01.00005", "BS" => "CABTYPNO.A01.00006",
        _ => null,
    };
    var aw = await db.SerAssignmentWorks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    var cavityIds = aw is null ? new List<string>()
        : (await db.SerAssignmentWorkStages.Where(s => s.OrgId == t.OrgId && s.AssignmentWorkId == aw.Id)
            .Select(s => s.CavityId).ToListAsync()).Where(x => x != null).Select(x => x!).Distinct().ToList();
    var cavities = (await db.Cavities.Where(c => c.OrgId == t.OrgId).ToListAsync())
        .Where(c => cavityIds.Contains(c.Id.ToString()))
        .Select(c => new
        {
            repairCabinCode = c.CavityNo, c.DealerCode,
            repairCabinName = c.CavityName, description = c.Note,
            repairCabinTypeCode = CabinTypeOf(c.CavityType),
            sourceCavityType = c.CavityType,
        }).ToList();

    // Table 3 — KTV được phân công trong lệnh. Gửi EngineerNo (không phải mã nội bộ).
    var engNos = aw is null ? new List<string>()
        : await db.SerAssignmentWorkEngineers.Where(e => e.OrgId == t.OrgId && e.AssignmentWorkId == aw.Id)
            .Select(e => e.EngineerNo).Distinct().ToListAsync();
    var engineers = await db.ServiceEngineers.Where(e => e.OrgId == t.OrgId && engNos.Contains(e.EngineerNo))
        .Select(e => new { e.EngineerNo, e.DealerCode, remark = e.EngineerNo, e.EngineerName })
        .ToListAsync();

    return Results.Ok(new
    {
        roNo, brands, models, cavities, engineers,
        syntheticOtherModel = carHasNoModel,
        syntheticOtherNote = carHasNoModel
            ? "Xe không có model ⇒ tự sinh dòng nhóm sản phẩm OTHER; bỏ dòng này thì xe trỏ tới nhóm KHÔNG TỒN TẠI."
            : null,
        unmappedCavityTypes = cavities.Where(c => c.repairCabinTypeCode is null)
            .Select(c => c.sourceCavityType).Distinct().ToList(),
        catalogScopeNote = "Danh mục gửi ĐI KÈM lệnh (chỉ phần liên quan), không phải đồng bộ master toàn bộ.",
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/masters", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (r is null) return Results.NotFound(new { roNo });

    var car = r.Vin == null ? null
        : await db.ServiceCars.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.FrameNo == r.Vin);
    var cus = r.CusName == null ? null
        : await db.ServiceCustomers.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.CusName == r.CusName);

    var customerCode = !string.IsNullOrWhiteSpace(cus?.SalesCusID) ? cus!.SalesCusID : cus?.CusCode;

    // Table 4 — master XE.
    object? carRow = car is null ? null : new
    {
        plateNoSys = car.CarID, car.PlateNo, vin = car.FrameNo, car.ColorCode,
        brandCode = car.TradeMark, car.EngineNo,
        manufactureYear = car.ProductYear,
        // ModelID null HOẶC bằng 0 ⇒ "OTHER" (không phải để trống).
        productGrpCode = string.IsNullOrWhiteSpace(car.ModelCode) || car.ModelCode == "0" ? "OTHER" : car.ModelCode,
        warrantyDate = car.WarrantyRegistrationDate,   // cột vá ở #334
    };

    // Table 5 — master KHÁCH.
    string genderOf(string? sex) => sex == "0" ? "FEMALE" : sex == "1" ? "MALE" : "OTHER";
    // SĐT liên hệ TRÙNG SĐT khách ⇒ gửi RỖNG (luật chống trùng của CustomerCenter).
    var contactPhoneSuppressed = cus != null && !string.IsNullOrEmpty(cus.ContMobile) && cus.ContMobile == cus.Mobile;
    object? cusRow = cus is null ? null : new
    {
        customerCode,
        customerName = cus.CusName, customerNameEN = cus.CusName,
        customerGender = genderOf(cus.Sex),
        customerPhoneNo = cus.Tel ?? "",              // NULL ⇒ chuỗi RỖNG
        customerMobilePhone = cus.Mobile,             // giữ NULL — khác dòng trên, đúng nguồn
        customerAddress = cus.Address, customerEmail = cus.Email,
        customerDateOfBirth = cus.DOB,
        cus.TaxCode,
        bankCode = cus.Bank, bankName = cus.Bank,     // hai tên, một giá trị
        contactName = cus.ContName,
        contactPhone = contactPhoneSuppressed ? "" : cus.ContMobile,
        contactEmail = cus.ContEmail,
        cus.ProvinceCode, cus.DistrictCode,
        // Thiếu loại khách ⇒ CÁ NHÂN (không để trống).
        customerType = string.IsNullOrWhiteSpace(cus.CusTypeID) ? "CANHAN" : "TOCHUC",
        bhInvoiceCTMCode = "HTV",                     // đóng cứng: xe con mặc định đơn vị bảo hành HTV
        govIDCardNo = cus.IDCardNo,
    };

    // Table 6 — MAP khách ⇄ xe theo lệnh.
    object? mapRow = (car is null || cus is null) ? null : new
    {
        roNoSys = r.Id, roNo = r.RONo, plateNoSys = car.CarID, customerCode,
    };

    return Results.Ok(new
    {
        roNo, car = carRow, customer = cusRow, customerCarMap = mapRow,
        customerCodeSource = !string.IsNullOrWhiteSpace(cus?.SalesCusID) ? "SalesCusID" : "CusCode (CarSv)",
        contactPhoneSuppressed,
        contactPhoneNote = contactPhoneSuppressed
            ? "SĐT liên hệ TRÙNG SĐT khách ⇒ gửi RỖNG, theo luật chống trùng của CustomerCenter (20240203)."
            : null,
        genderNote = "Sex: 1 = NAM, 0 = NỮ, còn lại = OTHER (bảng mã này CÓ nhánh else).",
        customerTypeNote = "Thiếu CusTypeID ⇒ CANHAN, không để trống.",
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/insurance", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (r is null) return Results.NotFound(new { roNo });

    var car = r.Vin == null ? null
        : await db.ServiceCars.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.FrameNo == r.Vin);
    if (car is null) return Results.Ok(new { roNo, carResolved = false, insurer = (object?)null, contracts = Array.Empty<object>() });

    // Hãng bảo hiểm — gửi đi dưới dạng KHÁCH HÀNG tổ chức (Table 15).
    var ins = car.InsNo == null ? null
        : await db.ServiceInsurances.FirstOrDefaultAsync(i => i.OrgId == t.OrgId && i.InsNo == car.InsNo);
    object? insurer = ins is null ? null : new
    {
        customerCode = ins.InsNo,
        customerName = ins.InsVieName,
        customerNameEN = ins.InsEngName,
        customerGender = "TOCHUC",              // đóng cứng: hãng bảo hiểm là TỔ CHỨC
        customerPhoneNo = ins.Telephone,
        customerMobilePhone = "",               // nguồn đóng cứng chuỗi RỖNG
        customerAddress = ins.Address,
        customerEmail = ins.Email,
        customerDateOfBirth = (DateTime?)null,  // nguồn đóng cứng NULL (khác chuỗi rỗng ở trên)
        taxCode = ins.Taxcode,
        contactName = (string?)null,            // NULL
        contactPhone = "",                      // chuỗi RỖNG
        contactEmail = (string?)null,           // NULL
        fax = ins.Fax,
    };

    // Hợp đồng bảo hiểm (Table 16) + bản ghép (Table 17). Chỉ gửi khi CÓ số hợp đồng.
    var cus = r.CusName == null ? null
        : await db.ServiceCustomers.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.CusName == r.CusName);
    // Quy tắc hợp nhất mã khách — CÙNG quy tắc với #362 (Table 8).
    var customerCode = !string.IsNullOrWhiteSpace(cus?.SalesCusID) ? cus!.SalesCusID : cus?.CusCode;

    var hasContract = !string.IsNullOrWhiteSpace(car.InsContractNo);
    var contracts = !hasContract ? new List<object>() : new List<object>
    {
        new
        {
            car.DealerCode,
            insContractNoSys = car.InsContractNo,
            insContractNo = car.InsContractNo,
            sealNo = car.InsContractNo,          // BA tên, MỘT giá trị — đúng nguồn
            customerCode,
            plateNoSys = car.CarID,
            insCode = car.InsNo,
            insStartDate = car.InsStartDate,
            insEndDate = car.InsFinishedDate,
            customerBuyName = cus?.CusName,
        },
    };

    return Results.Ok(new
    {
        roNo, carResolved = true, insurer, contracts,
        customerCodeSource = !string.IsNullOrWhiteSpace(cus?.SalesCusID) ? "SalesCusID" : "CusCode (CarSv)",
        insurerAsCustomerNote = "Hãng bảo hiểm gửi sang Veloca dưới dạng KHÁCH HÀNG tổ chức (CustomerGender = TOCHUC).",
        contractSkipped = !hasContract,
        contractSkipNote = !hasContract
            ? "Xe chưa có số hợp đồng bảo hiểm ⇒ nguồn KHÔNG gửi bảng 16/17 (lọc InsContractNo <> rỗng)."
            : null,
        threeNamesOneValueNote = "InsContractNoSys = InsContractNo = SealNo — nguồn trả ba tên cho một giá trị.",
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/care72h", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var rows = await db.CustomerCares.Where(c => c.OrgId == t.OrgId && c.RONo == roNo).ToListAsync();

    // MiniHTC lưu nhãn tiếng Anh; ánh xạ sang từ vựng Veloca đúng bảng mã CHỮ của Table 18.
    static string? StatusOf(string? s) => s switch
    {
        "Pending" or "PEND" => "PENDING",
        "Contacted" or "CINFB" or "CIFB" => "CONTACTED",
        "Rejected" or "REJ" => "CANCEL",
        _ => null,   // nguồn không có nhánh else
    };

    var items = rows.Select(c => new
    {
        c.DealerCode, roNoSys = roNo,
        contactDateUTC = c.ContactDate,      // ⚠️ KHÔNG đổi UTC — đúng nguồn
        contactDTimeUTC = c.ContactDate,     // trùng contactDateUTC — đúng nguồn
        note = c.Note, cusCare72hRemark = c.Note,
        cusCare72hSatus = StatusOf(c.Status),   // giữ nguyên chính tả thiếu "t" của nguồn
    }).ToList();

    return Results.Ok(new
    {
        roNo, count = items.Count, care72h = items,
        utcSuffixIsMisleading = true,
        utcNote = "ContactDateUTC/ContactDTimeUTC mang GIỜ ĐỊA PHƯƠNG — nguồn không đổi UTC dù tên có hậu tố UTC.",
        statusCollapseNote = "CINFB (có phản hồi) và CIFB (không phản hồi) đều thành CONTACTED — Veloca không phân biệt được.",
        unmappedStatuses = rows.Select(c => c.Status).Where(x => StatusOf(x) is null).Distinct().ToList(),
    });
}).RequireAuthorization();

// Nhắc bảo dưỡng (Table 19) — mã trạng thái là SỐ, khác Table 18 dùng mã CHỮ.
app.MapGet("/api/osveloca/ro/{roNo}/maintenance-reminder", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var rows = await db.CustomerCareMaces.Where(c => c.OrgId == t.OrgId && c.RONo == roNo).ToListAsync();

    // Bảng mã SỐ của nguồn; MiniHTC lưu nhãn chữ nên chấp nhận cả hai.
    // ⚠️ Trạng thái thứ ba: nguồn `'2'` = CANCEL, còn MiniHTC đặt tên `NotContacted` — khác nghĩa,
    //   cùng ô. Ánh xạ theo nguồn và ghi rõ để không ai tưởng "chưa liên hệ" = "huỷ".
    static string? StatusOf(string? s) => s switch
    {
        "0" or "Pending" => "PENDING",
        "1" or "Contacted" => "CONTACTED",
        "2" or "NotContacted" => "CANCEL",
        _ => null,
    };

    var items = rows.Select(c => new
    {
        roNoSys = roNo,
        contactDateUTC = c.ContactDate,      // ⚠️ KHÔNG đổi UTC — đúng nguồn
        contactDTimeUTC = c.ContactDate,
        reminderRemark = c.Remark,
        reminderStatus = StatusOf(c.Status),
    }).ToList();

    return Results.Ok(new
    {
        roNo, count = items.Count, reminders = items,
        utcSuffixIsMisleading = true,
        statusVocabNote = "Table 19 dùng mã SỐ (0/1/2) trong khi Table 18 dùng mã CHỮ (PEND/CINFB/CIFB/REJ) "
            + "cho cùng ba trạng thái — không dùng chung hàm đổi mã.",
        thirdStateNote = "Nguồn: '2' = CANCEL (huỷ). MiniHTC đặt tên ô này là NotContacted (chưa liên hệ) — "
            + "hai cách gọi khác nghĩa cho cùng một ô, cần nghiệp vụ xác nhận.",
        unmappedStatuses = rows.Select(c => c.Status).Where(x => StatusOf(x) is null).Distinct().ToList(),
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (r is null) return Results.NotFound(new { roNo });

    var cus = r.CusName == null ? null
        : await db.ServiceCustomers.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.CusName == r.CusName);
    var car = r.Vin == null ? null
        : await db.ServiceCars.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.FrameNo == r.Vin);

    static string? Utc(DateTime? v) => v is null ? null : v.Value.AddHours(-7).ToString("yyyy-MM-dd HH:mm:ss");

    var svc = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && i.RoId == r.Id).ToListAsync();
    var prt = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == r.Id).ToListAsync();

    decimal svcAfterVat = svc.Sum(i => i.Factor * i.Price * (1m + i.Vat * 0.01m));
    decimal prtAfterVat = prt.Sum(p => p.Factor * p.UnitPrice * p.NeedQty * (1m + p.Vat * 0.01m));

    // Tách theo nguồn chi trả — dùng lại đúng phép tách đã port ở #357.
    decimal repairAfterVat = 0m, insAfterVat = 0m, warrantyAfterVat = 0m, localAfterVat = 0m;
    foreach (var p in prt)
    {
        var full = p.Factor * p.UnitPrice * p.NeedQty * (1m + p.Vat * 0.01m);
        var ip = p.InsurancePrice ?? 0m;
        switch (p.ExpenseType)
        {
            case "ROREPAIR": repairAfterVat += full; break;
            case "ROINSURANCE":
                if (ip > 0m) { repairAfterVat += ip; insAfterVat += full - ip; } else insAfterVat += full;
                break;
            case "ROWARRANTY": warrantyAfterVat += full; break;
            case "LOCAL": localAfterVat += full; break;
        }
    }

    var cusDebit = await db.CusDebits.Where(d => d.OrgId == t.OrgId && d.RONo == roNo).SumAsync(d => (decimal?)d.DebitAmount) ?? 0m;
    var insDebit = await db.InsDebits.Where(d => d.OrgId == t.OrgId && d.RONo == roNo).SumAsync(d => (decimal?)d.DebitAmount) ?? 0m;
    var deductible = r.InsuranceDeductible ?? 0m;
    var discOther = r.AmountDiscountOther ?? 0m;
    var fromCard = r.AmountFromMC ?? 0m;
    var roStatus = r.Status switch { "Paid" => "PAIDED", "Finished" => "FINISH", _ => (string?)null };

    // Ưu tiên mã KH Sales; rỗng thì mới dùng mã CarSv.
    var customerCode = !string.IsNullOrWhiteSpace(cus?.SalesCusID) ? cus!.SalesCusID : cus?.CusCode;

    return Results.Ok(new
    {
        roNoSys = r.Id, roNo = r.RONo, r.DealerCode,
        customerCode,
        customerCodeSource = !string.IsNullOrWhiteSpace(cus?.SalesCusID) ? "SalesCusID" : "CusCode (CarSv)",
        customerName = r.CusName, customerNameEN = r.CusName,   // nguồn dùng CÙNG tên cho cả hai
        customerAddress = r.CusAddress, customerMobilePhone = r.CusMobile, customerPhoneNo = r.CusTel,
        customerEmail = cus?.Email, customerContactName = cus?.ContName,
        customerContactPhone = cus?.ContMobile, customerContactEmail = cus?.ContEmail,
        plateNo = r.LicensePlate, vin = r.Vin, colorCode = r.ColorCode,
        brandCode = r.TradeMarkCode, engineNo = r.EngineNo,
        insCode = car?.InsNo,                                   // 20240205: lấy trên XE, không trên LỆNH
        planedDeliveryDTimeUTC = Utc(r.PlanedDeliveryDate),
        actualDeliveryDTimeUTC = Utc(r.ActualDeliveryDate),
        km = r.Km, r.ReminderMaintanceDate, r.ReminderMaintanceKm,
        r.WorkDoneSoon, r.TermsOfRepair,
        totalValAfterVATService = svcAfterVat,
        totalValAfterVATPart = prtAfterVat,
        totalValAfterVATRO = svcAfterVat + prtAfterVat,          // 20240124: KHÔNG trừ giảm trừ khác
        valPmtFromCard = fromCard,
        totalValEnd = svcAfterVat + prtAfterVat - discOther - fromCard,
        totalValPmt = svcAfterVat + prtAfterVat,
        totalValCusROAfterVAT = repairAfterVat + deductible - discOther - fromCard,
        totalValInsROAfterVAT = insAfterVat - deductible,
        totalValWarrantyROAfterVAT = warrantyAfterVat,
        totalValLocalROAfterVAT = localAfterVat,
        totalValDebit = cusDebit + insDebit,
        totalValCusPmt = repairAfterVat - cusDebit,              // bản active (bản cũ ghi "Sai", xem #357)
        createDTimeUTC = Utc(r.CreatedAt), createBy = r.Creator,
        roStatus, repairStatus = roStatus,                       // nguồn trả CÙNG giá trị cho hai trường
        flagRetry = r.IsReRepair,                                // cột port ở #343
        flagWashCar = r.CarWashRequested, flagGetOldPart = r.UseSHPart,
        cusPmtDateUTC = Utc(r.PaidCreatedDate),
        paidDTimeUTC = Utc(r.PaidCreatedDate),                   // trùng cusPmtDateUTC — đúng nguồn
        finishDTimeUTC = Utc(r.FinishedDate),                    // = lúc SỬA XONG (#340), không phải giao xe
        requestCustomer = r.CusRequest, valFeeInsurance = deductible,
        deductibleNote = "Miễn thường CỘNG vào phần KHÁCH trả và TRỪ khỏi phần bảo hiểm — khớp #342.",
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/engineers", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is null) return Results.NotFound(new { roNo });

    // Gộp 6→3 đúng `#tbl_Ser_ROServiceItems_WorkType`.
    static string? WorkTypeOf(string? roType) => roType switch
    {
        "BDD" or "PDI" or "SPK" or "SCC" => "SCC",
        "SCD" => "SCD", "SCS" => "SCS", _ => null,
    };

    var items = (await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && i.RoId == ro.Id)
            .Select(i => new { i.Id, i.ROType }).ToListAsync())
        .Select(i => new { i.Id, WorkType = WorkTypeOf(i.ROType) })
        .Where(i => i.WorkType != null).ToList();

    var aw = await db.SerAssignmentWorks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    var assigned = aw is null ? new List<(string EngineerNo, string? WorkType)>()
        : (await db.SerAssignmentWorkEngineers.Where(e => e.OrgId == t.OrgId && e.AssignmentWorkId == aw.Id)
            .Select(e => new { e.EngineerNo, e.WorkType }).ToListAsync())
          .Select(e => (e.EngineerNo, e.WorkType)).ToList();

    var names = (await db.ServiceEngineers.Where(e => e.OrgId == t.OrgId)
            .Select(e => new { e.EngineerNo, e.EngineerName }).ToListAsync())
        .GroupBy(e => e.EngineerNo).ToDictionary(g => g.Key, g => g.First().EngineerName);

    // Tích chéo theo WorkType — đúng phép nối của nguồn.
    var rows = (from i in items
                join e in assigned on i.WorkType equals e.WorkType
                select new
                {
                    roNoSys = roNo,
                    idxPrdService = i.Id,
                    engineerNo = e.EngineerNo,
                    engineerName = names.TryGetValue(e.EngineerNo, out var n) ? n : null,
                }).OrderBy(x => x.idxPrdService).ThenBy(x => x.engineerNo).ToList();

    return Results.Ok(new
    {
        roNo, count = rows.Count, engineers = rows,
        // 🔴 Số DÒNG là tích chéo (dòng dịch vụ × KTV cùng WorkType) — KHÔNG phải số KTV.
        distinctEngineerCount = rows.Select(x => x.engineerNo).Distinct().Count(),
        serviceItemCount = items.Count,
        crossJoinNote = "Số dòng = (dòng dịch vụ) × (KTV cùng WorkType). Đừng đếm dòng ra số KTV — "
            + "dùng distinctEngineerCount.",
        sourceNote = "KTV lấy từ PHÂN CÔNG (Ser_AssignmentWorkEngineer), không phải KTV gán theo dòng "
            + "dịch vụ — nguồn đã đổi bảng ngày 20240215. Mã gửi đi là EngineerNo, không phải mã nội bộ "
            + "(quyết định 20241204).",
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/parts", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is null) return Results.NotFound(new { roNo });

    static string? RepairTypeOf(string? roType) => roType switch
    {
        "BDD" => "BAODUONG", "SCC" => "SUACHUA", "SCD" => "SUACHUADONG",
        "SCS" => "SUACHUASON", "PDI" => "PDI", "SPK" => "PHUKIEN", _ => null,
    };
    static string? ObjectTypeOf(string? exp) => exp switch
    {
        "ROWARRANTY" => "BAOHANH", "ROINSURANCE" => "BAOHIEM",
        "ROREPAIR" => "KHACHHANG", "LOCAL" => "NOIBO", _ => null,
    };
    static string? VatCodeOf(decimal vat) => vat switch
    { 0m => "VAT0", 5m => "VAT5", 8m => "VAT8", 10m => "VAT10", _ => null };

    // Loại sửa chữa của MỌI dòng phụ tùng = loại của dòng DỊCH VỤ đầu tiên (ItemID nhỏ nhất).
    var firstService = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && i.RoId == ro.Id)
        .OrderBy(i => i.Id).Select(i => i.ROType).FirstOrDefaultAsync();
    var repairTypeForAllParts = RepairTypeOf(firstService);

    var parts = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == ro.Id).ToListAsync();
    var roStatusPart = ro.Status switch { "Paid" => "PAIDED", "Finished" => "FINISH", _ => (string?)null };

    var lines = parts.Select(p =>
    {
        var qty = p.NeedQty;
        var afterVat = p.Factor * p.UnitPrice * qty * (1m + p.Vat * 0.01m);
        var ip = p.InsurancePrice ?? 0m;
        var insAfterVat = p.ExpenseType != "ROINSURANCE" ? 0m : ip > 0m ? afterVat - ip : afterVat;
        return new
        {
            roNoSys = roNo,
            idxPrdPart = p.Id,
            productCodeUserPart = p.PartCode,
            productNamePart = p.PartName,
            unitCode = p.Unit,
            repairType = repairTypeForAllParts,   // từ dòng dịch vụ ĐẦU TIÊN, không phải dòng này
            objectType = ObjectTypeOf(p.ExpenseType),
            discountRate = p.Factor > 1m || p.Factor < 0m ? 0m : (1m - p.Factor) * 100m,
            up = p.Factor > 1m ? p.UnitPrice * p.Factor : p.UnitPrice,
            vat = p.Vat,
            qty,
            valPart = p.Factor > 1m ? p.UnitPrice * p.Factor * qty : p.UnitPrice * qty,
            valBeforeVATPart = p.UnitPrice * p.Factor * qty,
            valVATPart = p.UnitPrice * p.Factor * qty * p.Vat / 100m,
            valAfterVATPart = afterVat,
            valDisAfterVATPart = p.Factor >= 1m || p.Factor < 0m ? 0m
                : Math.Round(p.UnitPrice * qty * (1m + p.Vat / 100m)
                    - (p.UnitPrice * p.Factor * qty + p.UnitPrice * p.Factor * qty * p.Vat / 100m), 2),
            valInsAfterVATPart = insAfterVat,
            roStatusPart,
            vatRateCode = VatCodeOf(p.Vat),
            remark = p.Note,
        };
    }).ToList();

    return Results.Ok(new
    {
        roNo, count = lines.Count, parts = lines,
        // 🔴 Mọi dòng phụ tùng dùng CHUNG một loại sửa chữa — của dòng dịch vụ đầu tiên.
        repairTypeSource = "dòng DỊCH VỤ đầu tiên (ItemID nhỏ nhất)",
        repairTypeForAllParts,
        distinctServiceTypes = (await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && i.RoId == ro.Id)
            .Select(i => i.ROType).Distinct().ToListAsync()),
        repairTypeNote = "Nếu lệnh có NHIỀU loại dịch vụ, phụ tùng vẫn chỉ mang loại của dòng đầu — "
            + "đừng dùng số này để thống kê phụ tùng theo loại sửa chữa.",
        unmappedObjectTypes = parts.Select(p => p.ExpenseType).Where(x => ObjectTypeOf(x) is null).Distinct().ToList(),
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/services", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is null) return Results.NotFound(new { roNo });

    var items = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && i.RoId == ro.Id).ToListAsync();

    static string? RepairTypeOf(string? roType) => roType switch
    {
        "BDD" => "BAODUONG", "SCC" => "SUACHUA", "SCD" => "SUACHUADONG",
        "SCS" => "SUACHUASON", "PDI" => "PDI", "SPK" => "PHUKIEN",
        _ => null,   // nguồn không có else
    };
    static string? ObjectTypeOf(string? exp) => exp switch
    {
        "ROWARRANTY" => "BAOHANH", "ROINSURANCE" => "BAOHIEM",
        "ROREPAIR" => "KHACHHANG", "LOCAL" => "NOIBO",
        _ => null,
    };
    static string? VatCodeOf(decimal vat) => vat switch
    {
        0m => "VAT0", 5m => "VAT5", 8m => "VAT8", 10m => "VAT10", _ => null,
    };
    // Trạng thái lệnh quy sang từ vựng Veloca; trạng thái khác ⇒ NULL (nguồn không có else).
    var roStatusService = ro.Status switch { "Paid" => "PAIDED", "Finished" => "FINISH", _ => (string?)null };

    var lines = items.Select(i =>
    {
        var afterVat = i.Factor * i.Price * (1m + i.Vat * 0.01m);
        var ip = i.InsurancePrice ?? 0m;
        // #357: dòng bảo hiểm có giá duyệt ⇒ phần bảo hiểm = toàn dòng − giá duyệt; không có ⇒ toàn dòng.
        var insAfterVat = i.ExpenseType != "ROINSURANCE" ? 0m
            : ip > 0m ? afterVat - ip : afterVat;
        return new
        {
            roNoSys = roNo,
            idxPrdService = i.Id,
            productCodeUserService = i.SerCode,
            productNameService = i.SerName,
            unitCode = "Lần",                    // nguồn đóng cứng N'Lần'
            repairType = RepairTypeOf(i.ROType),
            objectType = ObjectTypeOf(i.ExpenseType),
            discountRate = i.Factor > 1m || i.Factor < 0m ? 0m : (1m - i.Factor) * 100m,
            up = i.Factor > 1m ? i.Price * i.Factor : i.Price,
            vat = i.Vat,
            valBeforeVATService = i.Price * i.Factor,
            valVATService = i.Price * i.Factor * i.Vat / 100m,
            valAfterVATService = afterVat,
            valDisAfterVATService = i.Factor >= 1m || i.Factor < 0m ? 0m
                : Math.Round(i.Price * (1m + i.Vat / 100m) - (i.Price * i.Factor + i.Price * i.Factor * i.Vat / 100m), 2),
            valInsAfterVATService = insAfterVat,
            roStatusService,
            servicesStatus = "REPAIRED",         // nguồn đóng cứng
            vatRateCode = VatCodeOf(i.Vat),
        };
    }).ToList();

    return Results.Ok(new
    {
        roNo, count = lines.Count, services = lines,
        // Mã lạ cho ra NULL (nguồn không có `else`) — trả ra để thấy ngay, không im lặng.
        unmappedRepairTypes = items.Select(i => i.ROType).Where(x => RepairTypeOf(x) is null).Distinct().ToList(),
        unmappedObjectTypes = items.Select(i => i.ExpenseType).Where(x => ObjectTypeOf(x) is null).Distinct().ToList(),
        unmappedVatRates = items.Select(i => i.Vat).Where(v => VatCodeOf(v) is null).Distinct().ToList(),
        factorNote = "Factor ≤ 1 = hệ số CHIẾT KHẤU (UP = giá gốc); Factor > 1 = hệ số NHÂN GIÁ (UP = Price×Factor).",
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/amounts", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is null) return Results.NotFound(new { roNo });

    var parts = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == ro.Id)
        .Select(p => new { p.ExpenseType, p.Factor, p.NeedQty, p.UnitPrice, p.Vat, p.InsurancePrice }).ToListAsync();

    decimal Full(decimal factor, decimal qty, decimal price, decimal vat) => factor * qty * price * (1m + vat * 0.01m);

    decimal repair = 0m, partialRepair = 0m, partialIns = 0m, fullIns = 0m, warranty = 0m, local = 0m;
    foreach (var p in parts)
    {
        var full = Full(p.Factor, p.NeedQty, p.UnitPrice, p.Vat);
        var ip = p.InsurancePrice ?? 0m;
        switch (p.ExpenseType)
        {
            case "ROREPAIR": repair += full; break;
            case "ROINSURANCE":
                if (ip > 0m) { partialRepair += ip; partialIns += full - ip; }
                else fullIns += full;
                break;
            case "ROWARRANTY": warranty += full; break;
            case "LOCAL": local += full; break;
        }
    }
    var repairAfterVat = repair + partialRepair;
    var insuranceAfterVat = partialIns + fullIns;

    // Nguồn: MỘT bảng `Ser_CusDebit` với `DebitType` 1/2. MiniHTC tách hai entity ⇒ cộng lại.
    var cusDebit = await db.CusDebits.Where(d => d.OrgId == t.OrgId && d.RONo == roNo)
        .SumAsync(d => (decimal?)d.DebitAmount) ?? 0m;
    var insDebit = await db.InsDebits.Where(d => d.OrgId == t.OrgId && d.RONo == roNo)
        .SumAsync(d => (decimal?)d.DebitAmount) ?? 0m;

    return Results.Ok(new
    {
        roNo,
        repairAmountAfterVAT = repairAfterVat,
        insuranceAmountAfterVAT = insuranceAfterVat,
        warrantyAmountAfterVAT = warranty,
        localAmountAfterVAT = local,
        totalValDebit = cusDebit + insDebit,          // TotalDebitAmount (cả hai loại)
        totalCusDebitAmount = cusDebit,               // DebitType = '1'
        totalInsDebitAmount = insDebit,               // DebitType = '2'
        // Bản ĐANG CHẠY của nguồn (bản cũ bị comment kèm ghi chú "Sai" — xem chú thích ở trên).
        totalValCusPmt = repairAfterVat - cusDebit,
        // 🔴 Cùng cột `InsurancePrice`, báo cáo này và #342 hiểu NGƯỢC nhau — cần người nghiệp vụ chốt.
        insurancePriceConventionConflict = partialRepair > 0m,
        insurancePriceNote = partialRepair > 0m
            ? "Ở đây InsurancePrice được tính vào phía SỬA CHỮA; ở #342 nó là số tiền BẢO HIỂM để ghi công nợ. "
              + "Hai quy ước ngược nhau — chưa tự thống nhất, chờ xác nhận nghiệp vụ."
            : null,
    });
}).RequireAuthorization();

app.MapGet("/api/osveloca/ro/{roNo}/schedule", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is null) return Results.NotFound(new { roNo });

    // (1) Loại công việc của LỆNH — gộp 6 → 3 đúng bảng `case` của nguồn.
    static string? GroupOf(string? roType) => roType switch
    {
        "BDD" or "PDI" or "SPK" or "SCC" => "SCC",
        "SCD" => "SCD",
        "SCS" => "SCS",
        _ => null,   // nguồn KHÔNG có nhánh else ⇒ mã lạ ra NULL
    };
    var roTypes = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && i.RoId == ro.Id)
        .Select(i => i.ROType).ToListAsync();
    var headerTypes = roTypes.Select(GroupOf).Where(g => g != null).Distinct().OrderBy(g => g).ToList();
    var unmappedRoTypes = roTypes.Where(x => GroupOf(x) is null).Distinct().OrderBy(x => x).ToList();

    // (2) Lịch công đoạn — từ phân công công việc của lệnh.
    var aw = await db.SerAssignmentWorks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    var stages = aw is null ? new List<SerAssignmentWorkStage>()
        : await db.SerAssignmentWorkStages.Where(x => x.OrgId == t.OrgId && x.AssignmentWorkId == aw.Id).ToListAsync();

    var cavityNos = (await db.Cavities.Where(c => c.OrgId == t.OrgId)
            .Select(c => new { c.Id, c.CavityNo }).ToListAsync())
        .ToDictionary(c => c.Id.ToString(), c => c.CavityNo);

    // Trừ cứng 7 giờ, KHÔNG theo múi giờ máy chạy.
    static string? Utc(DateTime? v) => v is null ? null
        : v.Value.AddHours(-7).ToString("yyyy-MM-dd HH:mm:ss");

    var replaced = 0;
    var full = stages.OrderBy(x => x.StageCode).Select(x =>
    {
        var g = x.StageCode;
        var inHeader = headerTypes.Contains(g);
        if (!inHeader && headerTypes.Count > 0) { g = headerTypes[0]; replaced++; }   // chọn XÁC ĐỊNH
        return new
        {
            roNoSys = roNo,
            groupRepairType = g,
            idxPrdSvType = "0",          // nguồn đóng cứng '0'
            repairCabinCode = x.CavityId != null && cavityNos.TryGetValue(x.CavityId, out var no) ? no : null,
            planStartDTimeUTC = Utc(x.PlanStart),
            planEndDTimeUTC = Utc(x.PlanFinish),
            actualStartDTimeUTC = Utc(x.ActualStart),
            actualEndDTimeUTC = Utc(x.ActualFinish),
            replacedType = !inHeader,
        };
    }).ToList();

    // ===== 🔴 #358 SỬA LỖI CỦA CHÍNH #356 — PHẢI GỘP KHOÁ, MỖI LOẠI CHỈ MỘT KHOANG =====
    // Chú thích nguồn (`20241118`) ghi lại một **SỰ CỐ THẬT** đã xảy ra:
    //   *"Trước thì đây chính là KQ để đồng bộ sang Veloca nhưng do TH 1 LoaiCV gan voi nhieu khoang
    //    dan den **duplicate key ben Veloca** nen xu ly moi LoaiCV chi lay 1 khoang"*
    // ⇒ Nguồn thêm hai bước: `_ReturnGrpBy` (`group by RONoSys, GroupRepairType, IdxPrdSvType`) rồi
    //   `_Return` (`select top 1 f.RepairCabinCode` cho mỗi khoá; bốn mốc thời gian cũng `top 1`).
    // 🔴 #356 của tôi trả **một dòng mỗi công đoạn** ⇒ **tái tạo đúng lỗi trùng khoá họ đã sửa**.
    //   Nay gộp theo đúng khoá của nguồn. Nguồn lấy `top 1` **không `order by`** ⇒ khoang/mốc là
    //   dòng bất kỳ trong nhóm; port chọn **xác định** (theo mã khoang) và trả `collapsed` để thấy
    //   trường hợp một loại công việc gắn nhiều khoang.
    var rows = full
        .GroupBy(x => new { x.roNoSys, x.groupRepairType, x.idxPrdSvType })
        .Select(g =>
        {
            var pick = g.OrderBy(x => x.repairCabinCode).First();
            return new
            {
                pick.roNoSys, pick.groupRepairType, pick.idxPrdSvType,
                pick.repairCabinCode,
                pick.planStartDTimeUTC, pick.planEndDTimeUTC,
                pick.actualStartDTimeUTC, pick.actualEndDTimeUTC,
                pick.replacedType,
                // Số khoang bị bỏ khi gộp — >0 nghĩa là một loại công việc gắn nhiều khoang.
                droppedCabins = g.Count() - 1,
            };
        })
        .OrderBy(x => x.groupRepairType).ToList();

    var collapsed = full.Count - rows.Count;

    return Results.Ok(new
    {
        roNo, serviceTypes = headerTypes, schedule = rows,
        // #358: số dòng bị gộp bỏ. Nguồn buộc phải gộp vì Veloca trùng khoá (sự cố 20241118).
        stageRowCount = full.Count, collapsed,
        collapsedNote = collapsed > 0
            ? "Một loại công việc gắn nhiều khoang — nguồn CHỈ gửi 1 khoang/loại để Veloca không trùng khoá."
            : null,
        // 🔴 Bốn loại (BDD/PDI/SPK/SCC) đều ra "SCC" ⇒ hạt của Veloca THÔ hơn KPI nội bộ.
        typeCollapseNote = "BDD/PDI/SPK/SCC đều báo là SCC; Veloca chỉ biết 3 nhóm.",
        // `case` không có `else` ⇒ mã ROType lạ cho ra NULL, không bị loại.
        unmappedRoTypes,
        // Nguồn thay loại bằng `top 1` không `order by`; web chọn xác định.
        replacedCount = replaced,
        replacedNote = replaced > 0
            ? "Có công đoạn không khớp loại công việc của lệnh; nguồn thay bằng loại BẤT KỲ (top 1 không order by), web chọn theo thứ tự chữ cái."
            : null,
        timeNote = "Mốc trừ CỨNG 7 giờ theo nguồn (DateAdd(hh,-7,…)), không theo múi giờ máy chạy.",
    });
}).RequireAuthorization();

// ===== Master kỳ khảo sát JD Power (JDPowerTerm — port 1:1 FrmJDPowerTermCreate/Search, TCMotor DMSCarSv) =====
app.MapGet("/api/jdpowerterms", async (AppDbContext db, ITenantContext t, string? q, bool? all) =>
{
    var qry = db.JDPowerTerms.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.JDPTermCode.Contains(q!) || x.JDPTermName!.Contains(q!));
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new { x.Id, x.JDPTermCode, x.JDPTermName, x.StartDate, x.EndDate, x.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/jdpowerterms", async (JDPowerTermDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.JDPTermCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(code)) return Results.BadRequest(new { error = "Chưa nhập mã kỳ khảo sát." });
    if (dto.StartDate.HasValue && dto.EndDate.HasValue && dto.EndDate < dto.StartDate) return Results.BadRequest(new { error = "Ngày kết thúc phải >= ngày bắt đầu." });
    var row = await db.JDPowerTerms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.JDPTermCode == code);
    if (row is null) { row = new JDPowerTerm { OrgId = t.OrgId, JDPTermCode = code }; db.JDPowerTerms.Add(row); }
    row.JDPTermName = dto.JDPTermName; row.StartDate = dto.StartDate; row.EndDate = dto.EndDate; row.UpdatedAt = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.JDPTermCode, row.JDPTermName, row.FlagActive });
}).RequireAuthorization();

app.MapPost("/api/jdpowerterms/{id}/toggle", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.JDPowerTerms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    row.FlagActive = row.FlagActive == "1" ? "0" : "1"; row.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.FlagActive });
}).RequireAuthorization();

// ===== Chi tiết thanh toán PDI theo xe (PdiStoragePayment — port 1:1 FrmSuaThanhToanPDI, 2010.HTC) =====
app.MapGet("/api/pdistoragepayments", async (AppDbContext db, ITenantContext t, string? vin, string? dealer) =>
{
    var q = db.PdiStoragePayments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.VIN.Contains(vin!.Trim().ToUpperInvariant()));
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    var items = (await q.OrderByDescending(x => x.Id).Take(500).Select(x => new {
        x.Id, x.VIN, x.ModelCode, x.SpecCode, x.ColorExtName, x.StorageCodeInit, x.DealerCode, x.StoreDate, x.DeliveryOutDate, x.UpdatedBy, x.UpdatedAt
    }).ToListAsync())
    .Select(x => new { x.Id, x.VIN, x.ModelCode, x.SpecCode, x.ColorExtName, x.StorageCodeInit, x.DealerCode, x.StoreDate, x.DeliveryOutDate, x.UpdatedBy, x.UpdatedAt,
        storageDays = (x.StoreDate.HasValue && x.DeliveryOutDate.HasValue) ? (int)(x.DeliveryOutDate.Value.Date - x.StoreDate.Value.Date).TotalDays : (int?)null }).ToList();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/pdistoragepayments/import", async (PdiPaymentImportDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có xe để cập nhật." });
    var dup = rows.GroupBy(r => r.VIN!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"VIN {dup.Key} bị trùng trong file." });
    foreach (var r in rows)
        if (r.StoreDate.HasValue && r.DeliveryOutDate.HasValue && r.DeliveryOutDate < r.StoreDate)
            return Results.BadRequest(new { error = $"VIN {r.VIN}: ngày xuất kho phải >= ngày nhập kho." });
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var vins = rows.Select(r => r.VIN!.Trim().ToUpperInvariant()).ToHashSet();
    var existing = await db.PdiStoragePayments.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN)).ToListAsync();
    var byVin = existing.ToDictionary(x => x.VIN, x => x);
    int added = 0, updated = 0; var now = DateTime.Now;
    foreach (var r in rows)
    {
        var vin = r.VIN!.Trim().ToUpperInvariant();
        if (!byVin.TryGetValue(vin, out var row)) { row = new PdiStoragePayment { OrgId = t.OrgId, VIN = vin }; db.PdiStoragePayments.Add(row); added++; } else updated++;
        row.ModelCode = r.ModelCode; row.SpecCode = r.SpecCode; row.ColorExtName = r.ColorExtName; row.StorageCodeInit = r.StorageCodeInit; row.DealerCode = r.DealerCode;
        row.StoreDate = r.StoreDate; row.DeliveryOutDate = r.DeliveryOutDate; row.UpdatedBy = by; row.UpdatedAt = now;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added, updated });
}).RequireAuthorization();

