    var dtc = (dto.DeviceTypeCode ?? "").Trim();
    var spec = (dto.SpecCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(dtc)) return Results.BadRequest(new { error = "Chưa nhập loại thiết bị." });
    if (string.IsNullOrWhiteSpace(spec)) return Results.BadRequest(new { error = "Chưa nhập Spec." });
    var row = await db.DeviceTypeSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DeviceTypeCode == dtc && x.SpecCode == spec);
    if (row is null) { row = new DeviceTypeSpec { OrgId = t.OrgId, DeviceTypeCode = dtc, SpecCode = spec }; db.DeviceTypeSpecs.Add(row); }
    row.DeviceTypeName = dto.DeviceTypeName; row.SpecDescription = dto.SpecDescription; row.UpdatedAt = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.DeviceTypeCode, row.SpecCode, row.FlagActive });
}).RequireAuthorization();

// ===== #188 Loại thiết bị theo Spec — `Mst_DeviceType_Spec_Update` + `_Delete` =====
// Nguồn: `TERP.BizHTC/DataWH/Biz.HTC.WH.cs` (csproj 272) — `_Delete` (204278), `_Update` (204414).
// BƯỚC 3B: `_Update` bắt đầu **KHÁC DÒNG** (laptop 204414 / máy 150 204419) — căn theo MỐC HÀM (luật #156),
//   vùng 162 dòng md5 `6b5517ff` KHỚP. Đã liệt kê ranh giới hàm: 204278 → 204413 → 204574.
// 🔴 TWIN: **CẢ HAI cụm** `Mst_DeviceType_Spec_*` và `Mst_DevicePrice_Spec_*` **CHỈ có ở WS 64-bit**;
//    WS 32-bit **không có hàm nào**.
//
// 🔴 Hàm thứ NĂM trong danh sách 36 hàm field-mask (#184). Bảng này chính là master mà #162 dùng để
//    **suy ra thiết bị của xe** khi lập packing list (`JOIN Mst_DeviceType_Spec` theo `ActualSpec`,
//    lọc `FlagActive='1'`) ⇒ sửa sai cờ ở đây là hỏng dữ liệu lắp thiết bị ở đó.
//
// 🔴 `_Update` — FIELD-MASK **một cột**: `Mst_DeviceType_Spec.FlagActive`.
//    Guard duy nhất: `CheckDB(..., Flag.Yes)` — bản ghi phải tồn tại; **không** có guard theo cột
//    (giống #185, khác #184/#187) — lại một biến thể nữa của bộ ba mask/guard/vị-trí-guard.
// ⚠️ KHÁC `/toggle` đã có: nguồn **ĐẶT** cờ theo giá trị truyền vào, **không đảo**.
//    `toggle` là thao tác mù (client không biết trạng thái cuối), `_Update` là **idempotent**.
//    Giữ cả hai: `/toggle` là tiện ích UI, `/update` mới là lệnh 1:1 với nguồn.
app.MapPost("/api/devicetypespecs/{id}/update", async (long id, DeviceTypeSpecUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var row = await db.DeviceTypeSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });

    var mask = (dto.FtColsUpd ?? "").ToUpperInvariant();
    var updFlag = mask.Contains("MST_DEVICETYPE_SPEC.FLAGACTIVE");

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (updFlag)
    {
        var f = (dto.FlagActive ?? "").Trim();
        if (f is not ("0" or "1"))
            return Results.BadRequest(new { error = "Cờ hiệu lực phải là \"0\" hoặc \"1\"." });
        row.FlagActive = f;      // ĐẶT theo giá trị, KHÔNG đảo như /toggle
    }
    row.UpdatedAt = DateTime.Now;
    row.LogLUDateTime = DateTime.Now; row.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.DeviceTypeCode, row.SpecCode, row.FlagActive,
        updatedFlagActive = updFlag, row.LogLUDateTime, row.LogLUBy });
}).RequireAuthorization();

// 🔴 `_Delete` (204278): XOÁ CỨNG (`dt.Rows[0].Delete()`), khoá là **cặp** `(DeviceTypeCode, SpecCode)`,
//    guard duy nhất là bản ghi phải tồn tại — nguồn **không** kiểm bảng nào đang dùng.
//    ⚠️ Vẫn chặn nếu spec đó đang có xe đã gắn thiết bị (`DeviceCar`) — **ĐÃ GHI NỢ**, không tự thêm:
//    nguồn không có guard này nên thêm vào là **chặt hơn nguồn**.
app.MapDelete("/api/devicetypespecs/{id}", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.DeviceTypeSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    db.DeviceTypeSpecs.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = new { row.DeviceTypeCode, row.SpecCode } });
}).RequireAuthorization();

app.MapPost("/api/devicetypespecs/{id}/toggle", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.DeviceTypeSpecs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    row.FlagActive = row.FlagActive == "1" ? "0" : "1"; row.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.FlagActive });
}).RequireAuthorization();

// ===== Chiết khấu TT duyệt theo VIN (PaymentReqDiscountVin — port 1:1 FrmImportExl_PaymentReqDiscount, 2010.HTC) =====
app.MapGet("/api/paymentreqdiscountvins", async (AppDbContext db, ITenantContext t, string? prd, string? vin) =>
{
    var q = db.PaymentReqDiscountVins.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(prd)) q = q.Where(x => x.PRDiscountNo.Contains(prd!));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.VIN.Contains(vin!.Trim().ToUpperInvariant()));
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new { x.Id, x.PRDiscountNo, x.VIN, x.AmountHTCAppr, x.UpdatedBy, x.UpdatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalApproved = items.Sum(x => x.AmountHTCAppr), items });
}).RequireAuthorization();

app.MapPost("/api/paymentreqdiscountvins/import", async (PRDiscountImportDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.PRDiscountNo) && !string.IsNullOrWhiteSpace(r.VIN)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dòng để cập nhật." });
    var dup = rows.GroupBy(r => (r.PRDiscountNo!.Trim().ToUpperInvariant(), r.VIN!.Trim().ToUpperInvariant())).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"Trùng (PR {dup.Key.Item1} × VIN {dup.Key.Item2}) trong file." });
    if (rows.Any(r => r.AmountHTCAppr < 0)) return Results.BadRequest(new { error = "Số tiền duyệt không được âm." });
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    int added = 0, updated = 0; var now = DateTime.Now;
    foreach (var r in rows)
    {
        var prd = r.PRDiscountNo!.Trim(); var vin = r.VIN!.Trim().ToUpperInvariant();
        var row = await db.PaymentReqDiscountVins.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PRDiscountNo == prd && x.VIN == vin);
        if (row is null) { row = new PaymentReqDiscountVin { OrgId = t.OrgId, PRDiscountNo = prd, VIN = vin }; db.PaymentReqDiscountVins.Add(row); added++; } else updated++;
        row.AmountHTCAppr = r.AmountHTCAppr; row.UpdatedBy = by; row.UpdatedAt = now;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added, updated });
}).RequireAuthorization();

// ===== Đề nghị chiết khấu TT theo VIN — header + duyệt 2 cấp (PaymentReqDiscount — port 1:1 FrmPayReDiscount/FrmMngPaymentReqDiscountDealer, 2010.HTC/Sales) =====
app.MapGet("/api/paymentreqdiscounts", async (AppDbContext db, ITenantContext t, string? q, string? status, string? dealer) =>
{
