// ===== Lệnh cân bằng/điều chuyển kho (StoRearCB — port 1:1 FrmMngRearCBSC, TCMotor/Sales/Logistic) =====
app.MapGet("/api/storearcbs", async (AppDbContext db, ITenantContext t, string? status, string? no, string? vin) =>
{
    var q = db.StoRearCBs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.RearCBStatus == status);
    if (!string.IsNullOrWhiteSpace(no)) q = q.Where(x => x.StoRearCBNo.Contains(no!));
    if (!string.IsNullOrWhiteSpace(vin))
    {
        var v = vin!.Trim().ToUpperInvariant();
        var ids = db.StoRearCBDtls.Where(c => c.OrgId == t.OrgId && c.VIN.Contains(v)).Select(c => c.StoRearCBId);
        q = q.Where(x => ids.Contains(x.Id));
    }
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new {
        x.Id, x.StoRearCBNo, x.CreatedDate, x.RearCBStatus, x.Remark, x.CreatedBy, x.ApprovedDate,
        cars = db.StoRearCBDtls.Count(c => c.OrgId == t.OrgId && c.StoRearCBId == x.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/storearcbs", async (StoRearCBDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có xe trong lệnh." });
    var dup = cars.GroupBy(c => c.VIN!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"VIN {dup.Key} bị trùng!" });
    var by = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var h = new StoRearCB { OrgId = t.OrgId, StoRearCBNo = "RCB" + DateTime.Now.ToString("yyMMddHHmmss"), CreatedDate = DateTime.Now, RearCBStatus = "P", Remark = dto.Remark, CreatedBy = by };
    db.StoRearCBs.Add(h); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.StoRearCBDtls.Add(new StoRearCBDtl { OrgId = t.OrgId, StoRearCBId = h.Id, VIN = c.VIN!.Trim().ToUpperInvariant(), SpecCode = c.SpecCode, EngineNo = c.EngineNo, ColorCode = c.ColorCode, StorageCodeFrom = c.StorageCodeFrom, StorageCodeTo = c.StorageCodeTo, ExpectedStartDate = c.ExpectedStartDate, ExpectedEndDate = c.ExpectedEndDate, CBReqNo = c.CBReqNo, TenLoaiThung = c.TenLoaiThung, Remark = c.Remark });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StoRearCBNo, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/storearcbs/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    var h = await db.StoRearCBs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StoRearCBNo == no);
    if (h is null) return Results.NotFound(new { no });
    var cars = await db.StoRearCBDtls.Where(c => c.OrgId == t.OrgId && c.StoRearCBId == h.Id)
        .Select(c => new { c.VIN, c.SpecCode, c.EngineNo, c.ColorCode, c.StorageCodeFrom, c.StorageCodeTo, c.ExpectedStartDate, c.ExpectedEndDate, c.CBReqNo, c.TenLoaiThung, c.Remark, c.RearCBDtlStatus,
            c.RearCBOutDate, c.RearCBEndDate, c.ConfirmDate, c.ConfirmBy }).ToListAsync();
    return Results.Ok(new { h.StoRearCBNo, h.RearCBStatus, count = cars.Count, cars });
}).RequireAuthorization();

app.MapPost("/api/storearcbs/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "reject")) return Results.BadRequest(new { error = "action = approve|reject" });
    var h = await db.StoRearCBs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StoRearCBNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.RearCBStatus != "P") return Results.BadRequest(new { error = $"Lệnh đang '{h.RearCBStatus}', chỉ duyệt khi 'P'." });

    // 🔴 Guard nguồn khi DUYỆT (Biz.HTC.WH.cs:117925-117940): chặn nếu các VIN của lệnh này
    // ĐÃ có yêu cầu vận tải (YCVT) còn hiệu lực — nguồn báo: "Đã tồn tại YCVT đóng thùng A".
    if (action == "approve")
    {
        var vinsRc = await db.StoRearCBDtls.Where(c => c.OrgId == t.OrgId && c.StoRearCBId == h.Id)
            .Select(c => c.VIN).ToListAsync();
        var clashTr = await db.TransportReqCars
            .Where(c => c.OrgId == t.OrgId && vinsRc.Contains(c.Vin))
            .Select(c => c.Vin).FirstOrDefaultAsync();
        if (clashTr != null)
            return Results.BadRequest(new { error = "Đã tồn tại YCVT đóng thùng A", vin = clashTr });
    }

    h.RearCBStatus = action == "approve" ? "A" : "R";
    h.ApprovedBy = user.Identity?.Name ?? "system";
    if (action == "approve") h.ApprovedDate = DateTime.Now;
    // Nguồn giữ trạng thái DÒNG riêng — đồng bộ theo header.
    foreach (var dtl in await db.StoRearCBDtls.Where(c => c.OrgId == t.OrgId && c.StoRearCBId == h.Id).ToListAsync())
        dtl.RearCBDtlStatus = h.RearCBStatus;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StoRearCBNo, h.RearCBStatus, h.ApprovedDate });
}).RequireAuthorization();

// ===== Giám sát phiên đăng nhập (AppSession — port 1:1 FrmMngSession, TCMotor) =====
// Liệt kê phiên đang mở + kill phiên hết hạn (theo thời gian truy cập cuối quá N phút).
app.MapGet("/api/sessions", async (AppDbContext db, ITenantContext t, string? user, int? expireMinutes) =>
{
    var mins = expireMinutes.GetValueOrDefault(30);
    var cutoff = DateTime.Now.AddMinutes(-mins);
    var q = db.AppSessions.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(user)) q = q.Where(x => x.UserCode.Contains(user!));
    var items = await q.OrderByDescending(x => x.DateTimeLastAccess).Take(500).Select(x => new {
        x.Id, x.SessionId, x.UserCode, x.DateTimeLogin, x.DateTimeLastAccess, x.LanguageCode, x.PartnerCode, x.PartnerUserCode, x.OtherInfo
    }).ToListAsync();
    var expired = items.Count(x => x.DateTimeLastAccess < cutoff);
    return Results.Ok(new { count = items.Count, expireMinutes = mins, expired, items });
}).RequireAuthorization();

app.MapPost("/api/sessions", async (AppSessionDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.UserCode)) return Results.BadRequest(new { error = "Chưa nhập UserCode." });
    var now = DateTime.Now;
    var s = new AppSession {
        OrgId = t.OrgId, SessionId = "S" + now.ToString("yyMMddHHmmssfff"), UserCode = dto.UserCode.Trim(),
        DateTimeLogin = now, DateTimeLastAccess = now, LanguageCode = dto.LanguageCode ?? "vi", PartnerCode = dto.PartnerCode, PartnerUserCode = dto.PartnerUserCode, OtherInfo = dto.OtherInfo
    };
    db.AppSessions.Add(s); await db.SaveChangesAsync();
    return Results.Ok(new { s.SessionId, s.UserCode });
}).RequireAuthorization();

app.MapPost("/api/sessions/kill-expired", async (AppDbContext db, ITenantContext t, int? expireMinutes) =>
{
    var cutoff = DateTime.Now.AddMinutes(-expireMinutes.GetValueOrDefault(30));
    var expired = await db.AppSessions.Where(x => x.OrgId == t.OrgId && x.DateTimeLastAccess < cutoff).ToListAsync();
    db.AppSessions.RemoveRange(expired);
    await db.SaveChangesAsync();
    return Results.Ok(new { killed = expired.Count });
}).RequireAuthorization();

app.MapPost("/api/sessions/{id}/kill", async (long id, AppDbContext db, ITenantContext t) =>
{
    var s = await db.AppSessions.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (s is null) return Results.NotFound(new { id });
    db.AppSessions.Remove(s); await db.SaveChangesAsync();
    return Results.Ok(new { killed = id });
}).RequireAuthorization();

