    var items = await q.OrderBy(x => x.ParamCode).Take(500)
        .Select(x => new { x.ParamCode, x.ParamName, x.ParamValue, updatedAt = x.UpdatedAt.ToString("yyyy-MM-dd HH:mm") }).ToListAsync();
