    var a2 = new CarAllocationByArea { OrgId = t.OrgId, ModelCode = md, SpecCode = sp, MBPercent = dto.MBPercent, MTPercent = dto.MTPercent, MNPercent = dto.MNPercent, FlagActive = "1" };
