// Gửi đề nghị sang ngân hàng (port 1:1 FrmQL_DeNghiGDNganHang btnSendToBank_Click / RQ_BankingTransactions_PushBank) — không yêu cầu trạng thái, khớp gốc.
// ===== 🔴 NGÂN HÀNG BÁO KẾT QUẢ VỀ — hệ `ERP.DMS.HTC.VPBank.WS` (CHỈ có trên máy 150) =====
// TWIN: WS gọi `HTVSalesBankTrans_BankTransactionUpdate_New20230710`, KHÔNG phải bản trần.
// Port cũ mới có chiều ĐẨY SANG ngân hàng (`/pushbank`); chiều **ngân hàng báo về** thì thiếu hẳn.
var bkTransBankStatusNames = new Dictionary<string, string>
{
    ["N"] = "Chưa gửi",
    ["P"] = "Chờ ngân hàng xử lý",
    ["A0"] = "Ngân hàng duyệt mức 0",
    ["A1"] = "Ngân hàng duyệt mức 1",
    ["A2"] = "Ngân hàng duyệt mức 2",
    ["A3"] = "Ngân hàng duyệt mức 3",
    ["A4"] = "Ngân hàng duyệt mức 4",
    ["A5"] = "Ngân hàng duyệt mức 5",
    ["F"] = "Hoàn tất",
    ["C"] = "Huỷ",
    ["R"] = "Từ chối",
};

app.MapGet("/api/bankingtrans/bankstatuses", () => Results.Ok(new
{
    bankStatuses = bkTransBankStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    bankCodes = new[] { "VieTin", "VIETINBANK" },
    note = "Trạng thái NỘI BỘ chỉ đồng bộ theo ngân hàng khi ngân hàng trả F, C hoặc R — mức duyệt A0..A5 KHÔNG đổi trạng thái nội bộ.",
})).RequireAuthorization();

app.MapPost("/api/bankingtrans/{no}/bank-update", async (
    string no, BankingTransUpdateDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var r = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (r is null) return Results.NotFound(new { no });

    var st = (dto.BkTransBankStatus ?? "").Trim();
    if (!bkTransBankStatusNames.ContainsKey(st))
        return Results.BadRequest(new { error = $"Trạng thái ngân hàng không hợp lệ: {st}." });

    r.BkTransBankStatus = st;
    r.BankRemark = dto.BankRemark;
    if (!string.IsNullOrWhiteSpace(dto.RefBankCode)) r.RefBankCode = dto.RefBankCode!.Trim();

    // 🔴 Đồng bộ trạng thái NỘI BỘ CÓ ĐIỀU KIỆN — chỉ khi ngân hàng trả F / C / R
    // (BizHTC.VPBank.cs:4028-4042). Mức duyệt A0..A5 của ngân hàng KHÔNG đổi trạng thái nội bộ.
    if (st == "F" || st == "C" || st == "R") r.BkTransStatus = st;

    // ⚠️ Guard "Số LDNo trống!" / "Số MDNo trống!" CÓ trong nguồn nhưng **đã bị COMMENT**
    // (BizHTC.VPBank.cs:224-236 và 310-322) ⇒ KHÔNG port thành bắt buộc; chỉ ghi khi khác rỗng.
    if (!string.IsNullOrWhiteSpace(dto.LDNo)) r.LDNo = dto.LDNo!.Trim();
    if (dto.DisbursementAmount.HasValue) r.AmountDisbursed = dto.DisbursementAmount.Value;
    if (dto.DisbursementDate.HasValue) r.DisbursementDate = dto.DisbursementDate;
    if (!string.IsNullOrWhiteSpace(dto.DisbursementTerm)) r.DisbursementTerm = dto.DisbursementTerm;
    if (dto.DisbursementInterestRate.HasValue) r.DisbursementInterestRate = dto.DisbursementInterestRate.Value;

    if (!string.IsNullOrWhiteSpace(dto.MDNo)) r.MDNo = dto.MDNo!.Trim();
    if (dto.GrtAmount.HasValue) r.GrtAmount = dto.GrtAmount.Value;
    if (dto.GrtDateStart.HasValue) r.GrtDateStart = dto.GrtDateStart;
    if (dto.GrtDateEnd.HasValue) r.GrtDateEnd = dto.GrtDateEnd;
    if (!string.IsNullOrWhiteSpace(dto.GrtTerm)) r.GrtTerm = dto.GrtTerm;
    if (dto.GrtFee.HasValue) r.GrtFee = dto.GrtFee.Value;
    if (dto.GrtLatePmtDate.HasValue) r.GrtLatePmtDate = dto.GrtLatePmtDate;

    if (!string.IsNullOrWhiteSpace(dto.LCNo)) r.LCNo = dto.LCNo!.Trim();
    if (dto.LCAmount.HasValue) r.LCAmount = dto.LCAmount.Value;
    if (dto.LCStartDate.HasValue) r.LCStartDate = dto.LCStartDate;
    if (dto.LCEndDate.HasValue) r.LCEndDate = dto.LCEndDate;

    r.BankUpdatedAt = DateTime.Now;

    // 🔴 File ngân hàng gửi kèm: nguồn CHỈ nhận khi trạng thái = "F",
    // HOẶC ngân hàng là VietinBank và trạng thái = "A4" (BizHTC.VPBank.cs:4000-4006).
    var files = dto.Files ?? new List<BankingTransFileDto>();
    var fileAccepted = st == "F"
        || (string.Equals(r.BankCode, "VieTin", StringComparison.OrdinalIgnoreCase) && st == "A4");
    var savedFiles = 0;
    if (files.Count > 0)
    {
        if (!fileAccepted)
            return Results.BadRequest(new { error = "Chỉ nhận file khi trạng thái ngân hàng là 'F', hoặc VietinBank ở mức 'A4'." });
        // 🔴 Tổng dung lượng file trong MỘT lần gọi API <= 10MB — giữ nguyên thông điệp gốc của nguồn.
        var total = files.Sum(f => f.FileSize);
        if (total > 10L * 1024 * 1024)
            return Results.BadRequest(new { error = "Tổng dung lượng các file trong 1 api là 10MB." });
        var idx = await db.BankingTransBankFiles.CountAsync(f => f.OrgId == t.OrgId && f.BankingTransId == r.Id);
        foreach (var f in files)
        {
            db.BankingTransBankFiles.Add(new BankingTransBankFile
            {
                OrgId = t.OrgId, BankingTransId = r.Id, FileIndex = ++idx,
                FileType = f.FileType, FilePath = f.FilePath, FileName = f.FileName ?? "",
                DocumentType = f.DocumentType, FileSize = f.FileSize, Remark = f.Remark,
                BkTransBankStatus = st,
                // 🔴 #192: mặc định `Stage.Pending` ("P") khi client không gửi — nếu để null thì guard
                //    "chỉ ký file đang chờ ký" của `/files/{index}/sign` không bao giờ mở được.
                SignStatus = string.IsNullOrWhiteSpace(f.SignStatus) ? "P" : f.SignStatus!.Trim(),
            });
            savedFiles++;
        }
    }

    await db.SaveChangesAsync();
    return Results.Ok(new { r.RQ_BankingTransNo, bankStatus = r.BkTransBankStatus, status = r.BkTransStatus,
        internalStatusSynced = st == "F" || st == "C" || st == "R", savedFiles });
}).RequireAuthorization();

// ===== 🔴 #275 NGÂN HÀNG LẤY FILE CHỜ KÝ và BÁO VỊ TRÍ Ô CHỮ KÝ =====
// Nguồn: `ERP.DMS.HTC.VPBank.WS/TERP.BizHTC/BizHTC.VPBank.cs` — hai hàm `GetTransBankFile` (:6144) và
//   `UpdateTransBankFile` (:6285), đều được `TERP.WSHTC/App_Code/WSHTC.cs` phơi ra làm `[WebMethod]`.
// 🔴 **Cây `ERP.DMS.HTC.VPBank.WS` CHỈ CÓ TRÊN MÁY 150** — laptop không có thư mục này, nên không đối
//   chiếu 2 máy thì không thấy cả cụm tích hợp ngân hàng (6849 dòng).
// ✅ TRACE TWIN: `BizHTC.VPBank.cs` có **BA** bản `HTVSalesBankTrans_BankTransactionUpdate`
//   (bản trần · `_New20221018` · `_New20230710`); WS gọi **`_New20230710`** ⇒ hai bản kia CHẾT.
//
// Luồng hai bước: ngân hàng gọi GET lấy các file `SignStatus = 'P'`, rồi gọi POST báo lại
//   **trang số mấy + toạ độ/kích thước ô ký** để hệ thống đặt chữ ký đúng chỗ.
// ===== 🔴 #276 VIB ĐẨY FILE CHỜ KÝ — `VIB_BankTransactionFile` (`BizHTC.VPBank.cs:5262`) =====
// Cây `ERP.DMS.HTC.VPBank.WS` **CHỈ CÓ TRÊN MÁY 150**. Là `[WebMethod]` sống (WSHTC.cs:201).
//
// 🔴 BẪY HẰNG: guard trạng thái ngân hàng là `strBkTransBankStatus.Equals(BkTransBankStatus.Approve)`,
//   mà `BkTransBankStatus.Approve = "A0"` (Const.Main.cs:732) — **CHỈ mức A0**, KHÔNG phải "đã duyệt nói
//   chung". A1..A5 cũng là các mức duyệt nhưng **KHÔNG** qua guard này. Đọc tên hằng mà không tra giá trị
//   là port sai ngay. (Trạng thái nội bộ thì `BkTransStatus.Approve = "A"` — hai bảng mã KHÁC nhau.)
//
// LUẬT `ReSign` (Y/N) — bốn nhánh, đối xứng nhau:
//   • `LoanType` của đề nghị **RỖNG** (VIB chưa từng đẩy) + `ReSign = "Y"`  ⇒ lỗi (ký lại cái chưa có).
//   • `ReSign = "N"` (đẩy lần đầu) mà **ĐÃ CÓ** file cùng `DocumentType` ở `SignStatus in ('P','A')` ⇒ lỗi.
//   • `ReSign = "Y"` (ký lại) mà **CHƯA CÓ** file như trên ⇒ lỗi.
//   • `ReSign = "Y"` hợp lệ ⇒ **HUỶ** mọi file P/A đó về `SignStatus = "R"` kèm ghi chú nguyên văn
//     *"Hủy file, VIB đẩy lại file chưa ký"*, rồi ghi `TransactionID`.
//
// ⚠️ Hai loại hồ sơ đi hai bảng khác nhau: `DISBURSEMENT` → `RQ_BankingTransPmt` (giải ngân) ·
//   `GUARANTEE` → `RQ_BankingTransGrt` (bảo lãnh). Mỗi nhánh đòi bảng tương ứng **phải có dòng**.
// ⚠️ Nguồn ném `CMyException.Raise("<câu tiếng Việt>")` — **chuỗi trần, không phải mã lỗi** (khác hẳn các
//   hàm quanh nó). Giữ NGUYÊN VĂN, kể cả hai chỗ sai chính tả: *"Trạnh thái Mã hồ sơ Bank không hợp lệ!"*
//   và *"File đẩy lần đầu.Trạng thái ReSign hợp lệ!"* (thiếu chữ "không").
app.MapPost("/api/bankingtrans/{no}/vib-file", async (
    string no, VibBankFileDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    if (no.Length == 0) return Results.BadRequest(new { error = "Thiếu số đề nghị giao dịch." });
    var refBankCode = (dto.RefBankCode ?? "").Trim();
    if (refBankCode.Length == 0) return Results.BadRequest(new { error = "Thiếu RefBankCode." });
    var transactionId = (dto.TransactionID ?? "").Trim();
    if (transactionId.Length == 0) return Results.BadRequest(new { error = "Thiếu TransactionID." });
    var loanType = (dto.LoanType ?? "").Trim().ToUpperInvariant();
    if (loanType.Length == 0) return Results.BadRequest(new { error = "Thiếu LoanType." });
    if (loanType is not ("DISBURSEMENT" or "GUARANTEE"))
        return Results.BadRequest(new { error = "LoanType phải là DISBURSEMENT | GUARANTEE." });
    var reSign = (dto.ReSign ?? "").Trim().ToUpperInvariant();
    if (reSign.Length == 0) return Results.BadRequest(new { error = "Thiếu ReSign." });
    if (reSign is not ("Y" or "N")) return Results.BadRequest(new { error = "ReSign chỉ nhận Y hoặc N." });

    var r = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (r is null) return Results.NotFound(new { no });

    // 🔴 CHỈ "A" (nội bộ) và CHỈ "A0" (ngân hàng) — xem chú thích bẫy hằng ở trên.
    if (r.BkTransStatus != "A" || r.BkTransBankStatus != "A0")
        return Results.BadRequest(new { error = "Trạnh thái Mã hồ sơ Bank không hợp lệ!",
            bkTransStatus = r.BkTransStatus, bkTransBankStatus = r.BkTransBankStatus });

    // LoanType hiện tại RỖNG = VIB chưa từng đẩy file ⇒ không thể là lần "ký lại".
    if (string.IsNullOrWhiteSpace(r.LoanType) && reSign == "Y")
        return Results.BadRequest(new { error = "File đẩy lần đầu.Trạng thái ReSign hợp lệ!", reSign });

    // Bảng chứng từ tương ứng phải có dòng.
    var hasDoc = loanType == "DISBURSEMENT"
        ? await db.RqBankingTransPmts.AnyAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no)
        : await db.RqBankingTransGrts.AnyAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (!hasDoc)
        return Results.BadRequest(new { error = loanType == "DISBURSEMENT"
            ? "Đề nghị không có loại khoản vay giải ngân!" : "Đề nghị không có loại khoản vay bảo lãnh!" });

    // File cùng loại chứng từ đang ở P hoặc A.
    var liveFiles = await db.BankingTransBankFiles
        .Where(f => f.OrgId == t.OrgId && f.BankingTransId == r.Id && f.DocumentType == loanType
                    && (f.SignStatus == "P" || f.SignStatus == "A"))
        .ToListAsync();

    if (reSign == "N" && liveFiles.Count > 0)
        return Results.BadRequest(new { error = "Đã từng đẩy file ký GN, loại ký không hợp lệ!", existing = liveFiles.Count });
    if (reSign == "Y" && liveFiles.Count == 0)
        return Results.BadRequest(new { error = "Chưa từng đẩy file ký GN, loại ký không hợp lệ!" });

    var actor = user.Identity?.Name ?? "system";
    var now = DateTime.Now;
    var cancelled = 0;
    if (reSign == "Y")
    {
        foreach (var f in liveFiles)
        {
            f.SignStatus = "R";
            f.Remark = "Hủy file, VIB đẩy lại file chưa ký";   // nguyên văn nguồn
            f.LogLUBy = actor; f.LogLUDateTime = now;
            cancelled++;
        }
    }

    // Ghi TransactionID lên MỌI dòng chứng từ của đề nghị (nguồn không lọc thêm điều kiện nào).
    var updatedDocs = 0;
    if (loanType == "DISBURSEMENT")
        foreach (var p in await db.RqBankingTransPmts.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
        { p.TransactionID = transactionId; p.LogLUBy = actor; p.LogLUDateTime = now; updatedDocs++; }
    else
        foreach (var g in await db.RqBankingTransGrts.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
        { g.TransactionID = transactionId; g.LogLUBy = actor; g.LogLUDateTime = now; updatedDocs++; }

    r.LoanType = loanType;
    r.RefBankCode = refBankCode;

    // File VIB gửi kèm — vào đúng bảng file như luồng ngân hàng khác, ở trạng thái CHỜ KÝ.
    var idx = await db.BankingTransBankFiles.CountAsync(f => f.OrgId == t.OrgId && f.BankingTransId == r.Id);
    var added = 0;
    foreach (var f in dto.Files ?? new List<BankingTransFileDto>())
    {
        db.BankingTransBankFiles.Add(new BankingTransBankFile
        {
            OrgId = t.OrgId, BankingTransId = r.Id, FileIndex = ++idx,
            FileType = f.FileType, FilePath = f.FilePath, FileName = f.FileName ?? "",
            DocumentType = loanType, FileSize = f.FileSize, Remark = f.Remark,
            BkTransBankStatus = r.BkTransBankStatus, SignStatus = "P",
            LogLUBy = actor, LogLUDateTime = now,
        });
        added++;
    }

    await db.SaveChangesAsync();
    return Results.Ok(new { rqBankingTransNo = no, loanType, reSign, transactionId,
        cancelledFiles = cancelled, updatedDocs, addedFiles = added });
}).RequireAuthorization();

app.MapGet("/api/bankingtrans/{no}/bank-files-pending", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    if (no.Length == 0) return Results.BadRequest(new { error = "Thiếu số đề nghị giao dịch (nguồn: ..._RQBankingTransNoEmpty)." });
    var r = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (r is null) return Results.NotFound(new { no });

    // Nguồn lọc `and t.SignStatus in ('P')` — CHỈ file đang chờ ký.
    var items = await db.BankingTransBankFiles
        .Where(f => f.OrgId == t.OrgId && f.BankingTransId == r.Id && f.SignStatus == "P")
        .OrderBy(f => f.FileIndex)
        .Select(f => new { f.FileIndex, f.FileType, f.FileName, f.FilePath, f.DocumentType, f.FileSize,
            f.SignStatus, f.PageIdx, f.ElementX, f.ElementY, f.ElementWidth, f.ElementHeight })
        .ToListAsync();
    return Results.Ok(new { rqBankingTransNo = no, count = items.Count, items });
}).RequireAuthorization();

// #275 Ngân hàng báo VỊ TRÍ ô chữ ký cho một file.
// ⚠️ Nguồn kiểm `PageIdx` bằng `IsInteger64` nhưng bốn giá trị toạ độ bằng `IsNumeric` (cho thập phân) —
//   **bất đối xứng có chủ ý**, giữ nguyên.
// ☠️ KHÔNG TÌM THẤY thì nguồn `goto MyCodeLabel_Done` — **COMMIT rồi trả về BÌNH THƯỜNG, không báo lỗi**;
//   lệnh `throw ..._RQBankingTransFileNotFound` nằm ngay đó nhưng **đã bị comment**, kèm chú thích của tác
//   giả: *"Nếu không phải là file chưa ký thì bỏ qua không làm gì cả"* ⇒ **im lặng là CỐ Ý**, không phải
//   sót. Port giữ đúng: trả 200 với `updated = false` (không trả 404), nhưng NÓI RÕ lý do để bên gọi biết.
app.MapPost("/api/bankingtrans/{no}/files/{index:int}/sign-placement", async (
    string no, int index, BankFileSignPlacementDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    if (no.Length == 0) return Results.BadRequest(new { error = "Thiếu số đề nghị giao dịch." });
    if (dto.PageIdx is null) return Results.BadRequest(new { error = "Thiếu PageIdx." });
    if (dto.ElementX is null) return Results.BadRequest(new { error = "Thiếu ElementX." });
    if (dto.ElementY is null) return Results.BadRequest(new { error = "Thiếu ElementY." });
    if (dto.ElementWidth is null) return Results.BadRequest(new { error = "Thiếu ElementWidth." });
    if (dto.ElementHeight is null) return Results.BadRequest(new { error = "Thiếu ElementHeight." });

    var r = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (r is null) return Results.NotFound(new { no });

    // Khoá tra của nguồn: (RQ_BankingTransNo, BFileIndex) **và** SignStatus in ('P').
    var f = await db.BankingTransBankFiles.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.BankingTransId == r.Id && x.FileIndex == index && x.SignStatus == "P");
    if (f is null)
        return Results.Ok(new { rqBankingTransNo = no, fileIndex = index, updated = false,
            note = "File không tồn tại hoặc không còn ở trạng thái chờ ký (P) — nguồn CỐ Ý bỏ qua, không báo lỗi." });

    f.PageIdx = dto.PageIdx; f.ElementX = dto.ElementX; f.ElementY = dto.ElementY;
    f.ElementWidth = dto.ElementWidth; f.ElementHeight = dto.ElementHeight;
    await db.SaveChangesAsync();
    return Results.Ok(new { rqBankingTransNo = no, fileIndex = index, updated = true,
        f.PageIdx, f.ElementX, f.ElementY, f.ElementWidth, f.ElementHeight });
}).RequireAuthorization();

app.MapGet("/api/bankingtrans/{no}/files", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var r = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (r is null) return Results.NotFound(new { no });
    // #275 §12: cột vị trí ô ký có mặt ở CẢ GET lẫn POST
    var files = await db.BankingTransBankFiles.Where(f => f.OrgId == t.OrgId && f.BankingTransId == r.Id)
        .OrderBy(f => f.FileIndex).Select(f => new
        { f.FileIndex, f.FileName, f.FileType, f.FilePath, f.DocumentType, f.FileSize, f.Remark, f.BkTransBankStatus, f.SignStatus,
          f.SerialNumber, f.LogLUBy, f.LogLUDateTime,   // #192 §12: cột mới phải chiếu ở CẢ GET
          f.PageIdx, f.ElementX, f.ElementY, f.ElementWidth, f.ElementHeight })   // #275 §12
        .ToListAsync();
    return Results.Ok(new { r.RQ_BankingTransNo, count = files.Count, totalSize = files.Sum(f => f.FileSize), files });
}).RequireAuthorization();

// ===== #192 KÝ SỐ FILE NGÂN HÀNG — `RQ_BankingTransactions_SignBankFile` (lệnh WS còn THIẾU HẲN) =====
// Nguồn: `TERP.BizHTC/BankIntergration/BizHTC.VietinBank.cs:21812` (27732 dòng).
// BƯỚC 3B: md5 CẢ FILE `2304e4333825a130d61e1510c6296ba2` KHỚP 2 máy, CÙNG dòng 21812
//   (laptop `ERP.V15.DataWH.Release.20220125` · máy 150 `ERP.V15.DataWH.Release.2025`).
// TWIN: WS 64-bit gọi (83298 → 83356 `_biz.RQ_BankingTransactions_SignBankFile`); WS 32-bit KHÔNG có lệnh nào
//   thuộc họ `RQ_*` ⇒ cụm 64-bit-only, không có bản sinh đôi để lệch.
//
// 🔴 ĐỐI CHỨNG với #191: cùng motif `*_CheckDB(..., strFlagExistToCheck, strStatusListToCheck, ...)` nhưng ở đây
//    nguồn dùng ĐÚNG: `Flag.Yes` vào ô Flag, hằng trạng thái vào ô status. ⇒ ba guard dưới đây SỐNG THẬT,
//    khác hai guard chết câm của cụm GrtClaimExt. (Sweep #192 toàn `TERP.BizHTC`: lớp "hằng trạng thái đổ vào
//    ô Flag" chỉ có ĐÚNG 2 chỗ, cả hai đã xử ở #191 — nợ này ĐÓNG.)
//
// Ba guard của nguồn, theo đúng thứ tự:
//  1. `SerialNumber` RỖNG ⇒ lỗi riêng `..._CheckDB_SerialNumberEmpty` (kiểm TRƯỚC khi tra DB).
//  2. `RQ_BankingTransactions_CheckDB(..., Flag.Yes, BkTransStatus.Approve, "")`:
//     đề nghị phải TỒN TẠI **và** đang ở trạng thái duyệt `"A"`; ô trạng thái NGÂN HÀNG để rỗng ⇒ không kiểm.
//  3. `RQ_BankingTransBankFile_CheckDB(..., BFileIndex, Flag.Yes, Stage.Pending)`:
//     dòng file phải TỒN TẠI **và** `SignStatus` đang `"P"` ⇒ **guard idempotent thật: ĐÃ KÝ KHÔNG KÝ LẠI**.
// Ghi: `SignStatus = Stage.Approved ("A")`, `SerialNumber`, `LogLUBy`, `LogLUDateTime` — trên ĐÚNG một dòng
//   khớp `(RQ_BankingTransNo, BFileIndex)`; ghi song song `_dbMain` và `_dbWH` (nợ dual-write).
//
// ⚠️ Nợ giữ nguyên: `UploadFileNewX` + `MoveFileNewX` (nhận base64, ghi thư mục Temp theo `DealerCode` rồi
//    CHUYỂN sang thư mục đích lấy từ `BFilePath` sẵn có) thuộc tầng lưu file — chưa có trong MiniHTC;
//    port nhận sẵn `FilePath` như các lượt trước, KHÔNG bịa tầng file.
// ⚠️ Nợ TỪ VỰNG (ghi sổ, không sửa ở lượt này vì chạm cả cụm): `BankingTrans.Status` trong MiniHTC đang dùng
//    Draft/Sent/Approved/Rejected/Cancelled, còn nguồn dùng `TConst.BkTransStatus` P/A/R/C. Guard dưới đây bám
//    từ vựng ĐANG DÙNG của cụm ("Approved") để không tạo lệch mới.
app.MapPost("/api/bankingtrans/{no}/files/{index:int}/sign", async (string no, int index,
    BankFileSignDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    // Guard 1 — SerialNumber rỗng: nguồn kiểm TRƯỚC mọi truy vấn.
    var serial = (dto.SerialNumber ?? "").Trim();
    if (serial.Length == 0)
        return Results.BadRequest(new { error = "Chưa có số serial chứng thư số (SerialNumber)." });

    no = no.Trim().ToUpperInvariant();
    var r = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (r is null) return Results.NotFound(new { no });

    // Guard 2 — đề nghị phải đang DUYỆT (`BkTransStatus.Approve`).
    if (r.BkTransStatus != "Approved")
        return Results.BadRequest(new { error = $"Đề nghị đang '{r.BkTransStatus}' — chỉ ký file khi đề nghị đã duyệt." });

    var f = await db.BankingTransBankFiles
        .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BankingTransId == r.Id && x.FileIndex == index);
    if (f is null) return Results.NotFound(new { no, fileIndex = index });

    // Guard 3 — chỉ ký dòng đang chờ ký (`Stage.Pending`): đã ký thì KHÔNG ký lại.
    if ((f.SignStatus ?? "") != "P")
        return Results.BadRequest(new { error = $"File #{index} đang '{f.SignStatus}' — chỉ ký file đang chờ ký (P)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    f.SignStatus = "A";                                   // `Constants.Stage.Approved`
    f.SerialNumber = serial;
    if (!string.IsNullOrWhiteSpace(dto.FilePath)) f.FilePath = dto.FilePath!.Trim();   // thay cho MoveFileNewX
    if (!string.IsNullOrWhiteSpace(dto.FileName)) f.FileName = dto.FileName!.Trim();
    f.LogLUBy = who; f.LogLUDateTime = now;

    await db.SaveChangesAsync();
    return Results.Ok(new { r.RQ_BankingTransNo, fileIndex = f.FileIndex, signStatus = f.SignStatus, f.SerialNumber, f.FilePath, f.LogLUBy, f.LogLUDateTime });
}).RequireAuthorization();

app.MapPost("/api/bankingtrans/{no}/pushbank", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var b = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (b is null) return Results.NotFound(new { no });
    b.BkTransBankStatus = "A1"; b.PushedToBankAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { b.RQ_BankingTransNo, b.BkTransBankStatus });
}).RequireAuthorization();

// 🔴 #193 HUỶ ĐỀ NGHỊ GD NGÂN HÀNG — port lại theo `RQ_BankingTransactions_Cancel`
// Nguồn: `BankIntergration/BizHTC.VietinBank.cs:11539` (md5 CẢ FILE `2304e433…` khớp 2 máy — xem #192).
// TWIN: WS64 gọi ở 82998; WS32 không có lệnh `RQ_*` nào ⇒ 64-bit-only.
//
// Port cũ chỉ đổi `Status = "Cancelled"` — ĐÚNG guard nhưng SAI hành vi: nguồn huỷ theo kiểu **CASCADE**,
// một lệnh chạm 11 bảng. Guard của nguồn (`_CheckDB(..., Flag.Active, "A", "A1,A2,A3")`) trùng với guard
// port cũ, nên lỗi này KHÔNG lộ qua đường kiểm trạng thái — chỉ lộ khi đọc phần ghi.
//
// Nguồn ghi trên HEADER `RQ_BankingTransactions`: `BkTransStatus = BkTransStatus.Cancel ("C")`,
//   **và cả** `BkTransBankStatus = BkTransBankStatus.Cancel ("C")` — nguồn chú thích thẳng trong SQL:
//   "Bank không đẩy lại trạng thái nên đổi trạng thái luôn"; kèm `CancelDate`, `CancelBy`, `LogLUDateTime`, `LogLUBy`.
//
// 🔴 CASCADE 10 BẢNG CON, mỗi bảng một TÊN CỘT TRẠNG THÁI KHÁC NHAU (chính vì khác tên nên port từng
//    nhánh riêng lẻ không ai thấy — cùng motif với #159):
//      RQ_BankingTransPmt → BkTransPmtStatus · PmtDtl → BkTransPmtDtlStatus
//      RQ_BankingTransPmtLC → BkTransPmtLCStatus · PmtLCDtl → BkTransPmtLCDtlStatus
//      RQ_BankingTransGrt → BkTransGrtStatus · GrtDtl → BkTransGrtDtlStatus
//      RQ_BankingTransWrt → BkTransWrtStatus · WrtDtl → BkTransWrtDtlStatus
//      RQ_BankingTransCtr → BkTransCtrStatus · WrtCtr → BkTransWrtCtrStatus
//    Mỗi bảng con còn được ghi `LogLUDateTime`/`LogLUBy`.
//
// ⚠️ GIỮ ĐÚNG NGUỒN, KHÔNG "sửa hộ": nguồn cascade **10** bảng, **BỎ SÓT `RQ_BankingTransGrtLC` và
//    `RQ_BankingTransGrtLCDtl`** — dù hai bảng này được `_SaveX_20220817` ghi bình thường (MiniHTC đã port
//    ở #137). Đúng cặp bảng mà nguồn cũng quên `drop table #input_…` trong khối "Clear for debug" (ghi ở #137).
//    Hai lần quên cùng một cặp bảng ⇒ nhiều khả năng là thiếu sót thật của nguồn, nhưng port 1:1 giữ nguyên
//    và ghi nợ để người nghiệp vụ quyết.
app.MapPost("/api/bankingtrans/{no}/cancel-request", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var b = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (b is null) return Results.NotFound(new { no });
    if (!(b.BkTransStatus == "Approved" && (b.BkTransBankStatus == "A1" || b.BkTransBankStatus == "A2" || b.BkTransBankStatus == "A3")))
        return Results.BadRequest(new { error = "Không thể hủy nếu 2 trạng thái khác 'A' - 'A1'/'A2'/'A3'!" });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    b.BkTransStatus = "Cancelled";
    b.BkTransBankStatus = "C";                       // nguồn đổi LUÔN trạng thái ngân hàng, không chờ bank đẩy lại
    b.CancelDate = now; b.CancelBy = who;
    b.LogLUDateTime = now; b.LogLUBy = who;

    var n = 0;
    foreach (var r in await db.RqBankingTransPmts.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransPmtStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransPmtDtls.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransPmtDtlStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransPmtLCs.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransPmtLCStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransPmtLCDtls.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransPmtLCDtlStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransGrts.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransGrtStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransGrtDtls.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransGrtDtlStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransWrts.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransWrtStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransWrtDtls.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransWrtDtlStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransCtrs.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransCtrStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    foreach (var r in await db.RqBankingTransWrtCtrs.Where(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no).ToListAsync())
    { r.BkTransWrtCtrStatus = "C"; r.LogLUDateTime = now; r.LogLUBy = who; n++; }
    // KHÔNG chạm RqBankingTransGrtLCs / RqBankingTransGrtLCDtls — đúng như nguồn (xem ghi chú trên).

    await db.SaveChangesAsync();
    return Results.Ok(new { b.RQ_BankingTransNo, status = b.BkTransStatus, bankStatus = b.BkTransBankStatus, b.CancelDate, b.CancelBy, cancelledDetailRows = n });
}).RequireAuthorization();

