app.MapPost("/api/bankingtrans/{no}/send", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var b = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (b is null) return Results.NotFound(new { no });
    if (b.BkTransStatus != "Draft") return Results.BadRequest(new { error = "Đề nghị đã gửi." });
    b.BkTransStatus = "Sent"; b.SentAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { b.RQ_BankingTransNo, status = b.BkTransStatus });
}).RequireAuthorization();

app.MapPost("/api/bankingtrans/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t) =>
{
    if (action is not ("approve" or "reject")) return Results.BadRequest(new { error = "action = approve|reject" });
    no = no.Trim().ToUpperInvariant();
    var b = await db.BankingTranses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RQ_BankingTransNo == no);
    if (b is null) return Results.NotFound(new { no });
    if (b.BkTransStatus != "Sent") return Results.BadRequest(new { error = "Chỉ duyệt/từ chối đề nghị đã gửi." });
    if (action == "approve") { b.BkTransStatus = "Approved"; b.ApprovedDate = DateTime.Now; }
    else b.BkTransStatus = "Rejected";
    await db.SaveChangesAsync();
    return Results.Ok(new { b.RQ_BankingTransNo, status = b.BkTransStatus });
}).RequireAuthorization();

// ===== Biên bản giao xe (DlvMinutes — port 1:1 FrmDealerNewDlvMinutes/FrmHTCNewDlvMinutes, 2010.HTC/Sales/DlvMinutes) =====
// ⛔ HỢP NHẤT NỢ ### C0 (treo từ #14, xử lý #60): cụm `/api/dlvminutes` trước đây ghi vào bộ
// `DlvMinutes` (bảng "DlvMinutesSet") RIÊNG, trong khi `/api/transpdlv` ghi vào
// `TranspDlvConfirm` + `TranspDlvConfirmCar` + `DlvMinutesCheckItem` — **cùng bảng nguồn `Sto_DlvMinutes`**.
// Hợp nhất theo kiểu BỔ KHUYẾT: giữ bộ có 2 phía duyệt F/T + checklist dạng BẢNG,
// và mang TUYẾN vận chuyển từ bộ cũ sang — nhưng đặt ở **DÒNG XE**, đúng mô hình nguồn.
// ===== #159: DUYỆT BIÊN BẢN GIAO XE — ghi ngược NGÀY XUẤT KHO lên chứng từ nguồn =====
// Nguồn: `Sto_DlvMinutes_Approve_New20190416` (DataWH/Biz.HTC.WH.cs:138340, csproj 272).
// BƯỚC 3B: vùng hàm md5 78160161 khớp 2 máy (laptop 138340 / máy 150 138345 — căn theo MỐC HÀM).
// TWIN: CẢ HAI WS đều gọi `_New20190416` ⇒ không lệch.
//
// 🔴 Đây là side-effect mà port cũ bỏ sót TRỌN VẸN: duyệt biên bản không chỉ đổi trạng thái biên bản,
//    mà còn ghi "ngày xuất kho" NGƯỢC lên **chứng từ nguồn** của từng xe. Bốn nhánh theo loại chứng từ,
//    mỗi nhánh một CỘT KHÁC TÊN — chính vì khác tên nên khi port từng màn riêng lẻ thì không ai thấy:
//      Car_DeliveryOrderDetail   → DeliveryOutDate    (lệnh giao xe)
//      Sto_StorageRearrangeDetail→ RearrangeOutDate   (điều chuyển kho)   — guard: dòng đang "A2" hoặc "F"
//      Sto_CarRetrieveDetail     → RetrieveOutDate    (thu hồi xe)
//      Sto_RearrangeCBDetail     → RearCBOutDate      (điều chuyển đóng thùng)
//                                   — chỉ khi TypeCB ≠ ChuaDongThung; guard: dòng đang "A" hoặc "F"
// 🔴 Trạng thái biên bản: nguồn đặt `Approved` khi duyệt, `Rejected` khi bỏ duyệt
//    (`bFromApprove = FlagUnapprove == "0"`).
app.MapPost("/api/dlvminutes/{no}/approve", async (string no, DlvMinutesApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var outDate = dto.DeliveryOutDate ?? now;
    var unapprove = (dto.FlagUnapprove ?? "0").Trim() == "1";

    // 🔴 #200 GUARD CÒN THIẾU — `// Check DlvMnNo:` (DataWH/Biz.HTC.WH.cs:138651-138675).
    //    Nguồn kiểm trên bảng tạm: `SDMDlvMnNo is null OR SMDFDlvMnStatus not in ('P')` ⇒ ném
    //    `Sto_DlvMinutes_Approve_InvalidTransportReqStatus`. Tức biên bản phải tồn tại VÀ đang ở "P".
    //    🔴 Guard này áp cho **CẢ HAI** nhánh: `strFromFlagUnapprove` chỉ quyết định ghi "A" hay "R",
    //    KHÔNG nới guard. Nghĩa là nhánh false là **TỪ CHỐI** (P → R), không phải "bỏ duyệt" (A → P).
    if (m.FDlvMnStatus != "P")
        return Results.BadRequest(new { error = "Biên bản bàn giao đã được phê duyệt", current = m.FDlvMnStatus });

    // nguồn: bFromApprove = (FlagUnapprove == Flag.Inactive) ⇒ Approved, ngược lại Rejected (TỪ CHỐI).
    m.FDlvMnStatus = unapprove ? "R" : "A";

    var vins = (dto.Vins ?? new()).Select(v => (v ?? "").Trim().ToUpperInvariant()).Where(v => v.Length > 0).ToList();
    if (vins.Count == 0)
        vins = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
            .Select(c => c.VIN).ToListAsync();   // khoá nối là Id, không phải số biên bản

    int doHit = 0, rearrHit = 0, retrHit = 0, cbHit = 0; var skipped = new List<string>();
    foreach (var vin in vins)
    {
        // (1) lệnh giao xe
        foreach (var x in await db.DeliveryOrderCars.Where(x => x.OrgId == t.OrgId && x.Vin == vin).ToListAsync())
        { x.DeliveryOutDate = outDate; doHit++; }

        // (2) điều chuyển kho — guard trạng thái dòng "A2"/"F" đúng như nguồn
        foreach (var x in await db.StorageRearrangeDetails.Where(x => x.OrgId == t.OrgId && x.VIN == vin).ToListAsync())
        {
            if (x.RearrangeDtlStatus is not ("A2" or "F")) { skipped.Add($"{vin}: điều chuyển kho đang \"{x.RearrangeDtlStatus}\""); continue; }
            x.RearrangeOutDate = outDate; rearrHit++;
        }

        // (3) thu hồi xe
        foreach (var x in await db.CarRetrieves.Where(x => x.OrgId == t.OrgId && x.Vin == vin).ToListAsync())
        { x.RetrieveOutDate = outDate; retrHit++; }

        // (4) điều chuyển đóng thùng — guard trạng thái dòng "A"/"F"
        foreach (var x in await db.StoRearCBDtls.Where(x => x.OrgId == t.OrgId && x.VIN == vin).ToListAsync())
        {
            if (x.RearCBDtlStatus is not ("A" or "F")) { skipped.Add($"{vin}: đóng thùng đang \"{x.RearCBDtlStatus}\""); continue; }
            x.RearCBOutDate = outDate; cbHit++;
        }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { dlvMinutesNo = no, status = m.FDlvMnStatus, deliveryOutDate = outDate, cars = vins.Count,
        updated = new { deliveryOrder = doHit, storageRearrange = rearrHit, carRetrieve = retrHit, rearrangeCB = cbHit },
        skipped });
}).RequireAuthorization();

app.MapGet("/api/dlvminutes", async (AppDbContext db, ITenantContext t, string? status, string? vin) =>
{
    var qy = db.TranspDlvConfirms.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(m => m.FDlvMnStatus == status);
    if (!string.IsNullOrWhiteSpace(vin))
    {
        var v = vin.Trim().ToUpperInvariant();
        qy = qy.Where(m => db.TranspDlvConfirmCars.Any(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id && c.VIN.Contains(v)));
    }
    var items = await qy.OrderByDescending(m => m.Id).Take(500).Select(m => new
    {
        m.DlvMinutesNo, m.TransporterCode, m.DealerCode, m.FDlvMnStatus, m.TDlvMnStatus,
        m.FApprovedDate, m.FApprovedBy, m.TApprovedDate, m.TApprovedBy, m.CreatedAt,
        m.CorrectDate, m.CorrectBy, m.TFValReal, m.TPValReal, m.TFInputDate, m.TFInputBy,
        m.TFVCode, m.TPValSys, m.TPVCode, m.GPSDvNo, m.DlvEndDateTime, m.DlvEndBy,
        cars = db.TranspDlvConfirmCars.Count(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id),
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dlvminutes", async (DlvMinutesDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.VIN)) return Results.BadRequest(new { error = "Cần VIN." });
    if (string.IsNullOrWhiteSpace(dto.TransporterCode)) return Results.BadRequest(new { error = "Cần đơn vị vận tải." });
    var no = "DLV" + DateTime.Now.ToString("yyMMddHHmmss");
    var m = new TranspDlvConfirm
    {
        OrgId = t.OrgId, DlvMinutesNo = no, TransporterCode = dto.TransporterCode.Trim(),
        FDlvMnStatus = "P", TDlvMnStatus = "P",     // hai phía duyệt ĐỘC LẬP (TConst.Stage)
        // #169: bản biểu phí áp cho biên bản — bước xác nhận đọc lại cột này để tra ExpectedDays.
        TFVCode = dto.TFVCode,
    };
    db.TranspDlvConfirms.Add(m); await db.SaveChangesAsync();

    // Tuyến đi theo XE (đúng mô hình nguồn), không nằm ở header.
    db.TranspDlvConfirmCars.Add(new TranspDlvConfirmCar
    {
        OrgId = t.OrgId, TranspDlvConfirmId = m.Id, VIN = dto.VIN.Trim().ToUpperInvariant(),
        FProvinceCode = dto.FProvinceCode, TProvinceCode = dto.TProvinceCode,
        FDistrictCode = dto.FDistrictCode, TDistrictCode = dto.TDistrictCode,
        DriverCode = dto.DriverCode, DlvStartDate = dto.DlvStartDate, DlvEndDate = dto.DlvEndDate,
    });

    // Checklist: bộ cũ lưu JSON, bộ giữ lưu thành BẢNG (DlvMinutesCheckItem) — ghi theo bảng.
    foreach (var kv in dto.Checklist ?? new Dictionary<string, bool>())
    {
        var parts = kv.Key.Split('.', 2);
        db.DlvMinutesCheckItems.Add(new DlvMinutesCheckItem
        {
            OrgId = t.OrgId, TranspDlvConfirmId = m.Id,
            ItemGroup = parts.Length == 2 ? parts[0] : "OS",
            ItemCode = parts.Length == 2 ? parts[1] : kv.Key,
            FStatus = kv.Value ? "1" : "0",
        });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, vin = dto.VIN.Trim().ToUpperInvariant() });
}).RequireAuthorization();

app.MapGet("/api/dlvminutes/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
