    if (dto.EndDate is null) return Results.BadRequest(new { error = "Chưa có thông tin ngày áp dụng đến." });
    if (dto.EndDate < dto.StartDate) return Results.BadRequest(new { error = "Ngày áp dụng đến phải >= ngày áp dụng từ." });
