    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.DlrContractNo, c.DlrContractNoUser, c.DealerCode, c.SalesManCode, c.SalesType, c.CustomerName, c.SignDate, c.Status,
        c.ApproveBy, c.ApproveDTime, c.CancelBy, c.CancelDTime, c.FinishBy, c.FinishDTime,
        lines = db.DlrContractDetails.Count(l => l.OrgId == t.OrgId && l.ContractId == c.Id),
        total = db.DlrContractDetails.Where(l => l.OrgId == t.OrgId && l.ContractId == c.Id).Sum(l => (decimal?)l.TotalAmountAfterVAT) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dlrcontracts", async (DlrContractDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DlrContractNoUser)) return Results.BadRequest(new { error = "Phải nhập số hợp đồng người dùng." });
    if (string.IsNullOrWhiteSpace(dto.SalesManCode)) return Results.BadRequest(new { error = "Hãy chọn nhân viên bán hàng." });
    if (string.IsNullOrWhiteSpace(dto.SalesType)) return Results.BadRequest(new { error = "Phải chọn kiểu bán lẻ." });
    if (string.IsNullOrWhiteSpace(dto.CustomerName)) return Results.BadRequest(new { error = "Hãy chọn khách hàng." });
    if (string.IsNullOrWhiteSpace(dto.IDCardNo)) return Results.BadRequest(new { error = "Khách hàng chưa có Số giấy tờ tùy thân." });
    if (string.IsNullOrWhiteSpace(dto.IDCardType)) return Results.BadRequest(new { error = "Khách hàng chưa có Loại giấy tờ tùy thân." });
    if (dto.DateOfBirth is null) return Results.BadRequest(new { error = "Khách hàng chưa có Ngày sinh nhật/ thành lập Công ty." });
    if (dto.SignDate is null) return Results.BadRequest(new { error = "Chưa chọn Ngày ký HĐ." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.ModelCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng model." });
    if (lines.Any(l => l.Qty <= 0)) return Results.BadRequest(new { error = "Số lượng phải > 0." });
    var no = "DLC" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new DlrContract
    {
        OrgId = t.OrgId, DlrContractNo = no, DlrContractNoUser = dto.DlrContractNoUser.Trim(), DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(),
        SalesManCode = dto.SalesManCode.Trim(), SalesType = dto.SalesType.Trim(), CustomerCode = (dto.CustomerCode ?? "").Trim().ToUpperInvariant(),
        CustomerName = dto.CustomerName.Trim(), IDCardNo = dto.IDCardNo.Trim(), IDCardType = dto.IDCardType.Trim(), DateOfBirth = dto.DateOfBirth.Value,
        SignDate = dto.SignDate.Value, BankCode = dto.BankCode
    };
    db.DlrContracts.Add(c); await db.SaveChangesAsync();
    var whoCtr = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var ctrCarSeq = 1;   // đếm chung toàn hợp đồng, đúng mẫu "{SốHĐ}.{j:00}" của nguồn
    // 🔴 #130: nguồn đặt MỐC PHIÊN BẢN ở phần đầu rồi ghi CÙNG giá trị đó vào mọi dòng lịch sử
    //    (Biz.HTC.WH.cs:93118 và 93290) ⇒ nhóm theo mốc này dựng lại được nguyên trạng từng phiên bản.
    var versionStamp = DateTime.Now;
    c.VersionDTimeCurr = versionStamp;

    // ===== 🔴 #348 CỤM PHIÊN BẢN mới điền MỘT NỬA + hai cột chưa có đường ghi =====
    // Nguồn `BizHTC.RetailContract.cs:1665-1678` (bản canonical `.Release.2025`, md5 giống hệt 2 máy):
    //   `TransactorCode`   = `strTransactorCode` — **giá trị thật** ngay lúc tạo;
    //   `FlagDealFinish`   = `TConst.Flag.Inactive` (**"0"**) — đóng cứng, bật ở bước khác;
    //   `VersionDTimeOld`  = `DBNull.Value` — hợp đồng mới thì **chưa có phiên bản cũ**.
    // ⚠️ `TransactorCode` **KHÁC** `SalesManCode`: cùng bảng nhưng hai vai trò khác nhau.
    //   Đường `Biz.HTC.WH.cs:92391` lại gán `TransactorCode = strDealerCode` ⇒ **hai đường ghi hai
    //   NGUỒN GIÁ TRỊ khác nhau** cho cùng một cột; port đường bán lẻ (nhận từ người dùng).
    c.VersionCount = 1;
    c.VersionUpdateBy = whoCtr;
    c.VersionDTimeOld = null;              // hợp đồng mới: chưa có phiên bản cũ
    c.TransactorCode = dto.TransactorCode; // người giao dịch, khác nhân viên bán
    c.FlagDealFinish = "0";                // Flag.Inactive — bật khi CHỐT giao dịch, xem endpoint dưới
    foreach (var l in lines)
    {
        var amountVat = l.Price * l.Qty * l.VAT / 100m;
        var totalAfter = l.Price * l.Qty + amountVat;
        // 🔴 #129 parity Dlr_ContractDtl: bổ sung khoá nghiệp vụ + loại cập nhật + dấu vết sửa
        //    (Biz.HTC.WH.cs:93222-93238, bản SellToDealer_New20230306).
        db.DlrContractDetails.Add(new DlrContractDetail
        {
            OrgId = t.OrgId, ContractId = c.Id,
            DlrContractNo = c.DlrContractNo,
            ContractUpdateType = null,          // nguồn để NULL khi tạo
            ModelCode = l.ModelCode.Trim(), SpecCode = l.SpecCode, ColorCode = l.ColorCode,
            Qty = l.Qty, DlvExpectedDate = l.DlvExpectedDate,
            Price = l.Price, VAT = l.VAT, AmountVAT = amountVat, TotalAmountAfterVAT = totalAfter,
            LogLUDateTime = DateTime.Now, LogLUBy = whoCtr,
        });

        // 🔴 #130 ghi lịch sử dòng (`Dlr_ContractDtlHis`, Biz.HTC.WH.cs:93285-93305): snapshot dòng
        //    theo PHIÊN BẢN — mang `VersionDTimeCurr` bằng đúng mốc của phần đầu. KHÔNG có cặp Old/New.
        //    `ContractUpdateType` để NULL vì đây là bản ghi lúc TẠO (chỉ hàm SỬA mới truyền giá trị).
        db.DlrContractDtlHiss.Add(new DlrContractDtlHis
        {
            OrgId = t.OrgId, VersionDTimeCurr = versionStamp,
            DlrContractNo = c.DlrContractNo,
            SpecCode = l.SpecCode, ModelCode = l.ModelCode.Trim(), ColorCode = l.ColorCode,
            Qty = l.Qty,
            ContractUpdateType = null,
            UpdateBy = whoCtr, DlvExpectedDate = l.DlvExpectedDate,
            LogLUDateTime = DateTime.Now, LogLUBy = whoCtr,
        });

        // 🔴 #129 NỞ DÒNG THEO TỪNG XE sang `Dlr_ContractCar` (Biz.HTC.WH.cs:93240-93280) —
        //    bảng này CHỈ có ở bản SellToDealer_New20230306 mà WS 64-bit gọi; bản 2018 (WS 32-bit) không có.
        //    Một dòng Dtl có Qty = 3 ⇒ sinh 3 dòng ở đây, `CtrCarId` = "<SốHĐ>.01/.02/.03" (2 chữ số).
        for (var j = 1; j <= l.Qty; j++)
            db.DlrContractCars.Add(new DlrContractCar
            {
                OrgId = t.OrgId, DlrContractNo = c.DlrContractNo,
                CtrCarId = $"{c.DlrContractNo}.{ctrCarSeq++:00}",
                SpecCode = l.SpecCode, ModelCode = l.ModelCode.Trim(), ColorCode = l.ColorCode,
                DlvExpectedDate = l.DlvExpectedDate,
                FlagCancel = "0", FlagDelivery = "0",   // TConst.Flag.Inactive
                LogLUDateTime = DateTime.Now, LogLUBy = whoCtr,
            });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrContractNo, c.CustomerName, lines = lines.Count });
}).RequireAuthorization();

// ===== PHIẾU HUỶ hợp đồng bán lẻ (Dlr_ContractCancel + Dtl + Car) =====
// Nguồn: `BizHTC.Contract.cs` — `Dlr_ContractCancel_SaveX_New20230306` (2375), ghi 3 bảng tại
// 2976 / 3010 / 3042; csproj `<Compile>` 110 ⇒ LIVE. md5 647641a1 khớp nguyên file 2 máy.
// 🔴 MỎ MỚI (#136): ba bảng này ghi bằng `insert into … select`, **KHÔNG qua `SaveData`** ⇒ lệnh kiểm kê
//    ở #117 không bắt được. Mỏ `insert…select` có **241 bảng chưa port**.
// 🔴 TWIN: cụm `Dlr_ContractCancel_*` **chỉ có ở WS 64-bit**; WS 32-bit chỉ có hàm cũ
//    `ContractDealerContractCancel_New20181119` → `_SaveX` (1726) **không ghi bảng `…CancelCar`**.
//    Ca thứ NĂM dạng "chỉ 64-bit", và lặp đúng mẫu #129: bản mới **ghi thêm cả một bảng**.
// 🔴 `ContractCancelStatus` lấy từ `TConst.ContractCancelStatus` ở **`Const.Main.DMS40.cs:140-145`**
//    ("P"/"A"/"C") — hằng nằm ở file DMS40, không phải `Const.Main.cs`.
// 🔴 Huỷ ở **MỨC TỪNG XE**: `…CancelCar.CtrCarId` trỏ về dòng xe của hợp đồng gốc (`Dlr_ContractCar`, #129),
//    trong khi `…CancelDtl` chỉ gộp nhóm theo model.
// ===== 🔴 #348 SỬA HỢP ĐỒNG ⇒ TĂNG PHIÊN BẢN (nơi `VersionDTimeOld` mới có nghĩa) =====
// Nguồn `BizHTC.RetailContract.cs:4951` ghi **bốn** cột thành một cụm, trong CÙNG một lần lưu:
//   `VersionDTimeOld  = strVersionDtimeOld`   ← chính là `VersionDTimeCurr` **trước khi sửa**
//   `VersionDTimeCurr = dtimeTDate` (`"yyyy-MM-dd HH:mm:ss"` — **giữ GIÂY**)
//   `VersionCount     = countVersion + 1`
//   `VersionUpdateBy  = strPartnerUserCode`
// ⇒ Nhờ cặp Old/Curr mà dựng lại được **chuỗi phiên bản**; thiếu `VersionDTimeOld` thì mỗi bản chỉ
//   biết mốc của chính nó, **không nối được với bản trước**.
app.MapPost("/api/dlrcontracts/{no}/amend", async (string no, DlrContractAmendDto dto,
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.DlrContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == no);
    if (c is null) return Results.NotFound(new { error = "Không có hợp đồng " + no });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var prev = c.VersionDTimeCurr;
    c.VersionDTimeOld = prev;                 // mốc CŨ = mốc hiện hành TRƯỚC khi sửa
    c.VersionDTimeCurr = DateTime.Now;        // giữ GIÂY, đúng nguồn
    c.VersionCount = c.VersionCount + 1;
    c.VersionUpdateBy = who;

    // Các trường cho sửa — chỉ ghi khi client có truyền (rỗng = GIỮ NGUYÊN).
    if (dto.BankCode is not null) c.BankCode = dto.BankCode;
    if (dto.SalesType is not null) c.SalesType = dto.SalesType;
    if (dto.SalesManCode is not null) c.SalesManCode = dto.SalesManCode;
    if (dto.TransactorCode is not null) c.TransactorCode = dto.TransactorCode;
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        no, c.VersionCount, versionDTimeOld = c.VersionDTimeOld, versionDTimeCurr = c.VersionDTimeCurr,
        c.VersionUpdateBy,
        firstAmend = prev is null,
    });
}).RequireAuthorization();

// ===== 🔴 #348 CHỐT GIAO DỊCH — bật `FlagDealFinish` =====
// Nguồn `BizHTC.DealerSales.cs:8161` bật bằng SQL `update dc set dc.FlagDealFinish = '1'`
//   (dạng ghi thứ 4, lệ #314 — máy quét theo `["X"] =` không thấy).
// ⚠️ Cờ này **TÁCH KHỎI** `Status`: hợp đồng có thể đã duyệt mà giao dịch **chưa** chốt.
app.MapPost("/api/dlrcontracts/{no}/dealfinish", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.DlrContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == no);
    if (c is null) return Results.NotFound(new { error = "Không có hợp đồng " + no });
    c.FlagDealFinish = "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { no, c.FlagDealFinish, status = c.Status,
        note = "FlagDealFinish tách khỏi Status — duyệt và chốt giao dịch là hai việc." });
}).RequireAuthorization();

app.MapGet("/api/dlrcontractcancels", async (AppDbContext db, ITenantContext t, string? contractCNo, string? dealerCode, string? status) =>
{
    var qy = db.DlrContractCancels.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(contractCNo)) qy = qy.Where(x => x.ContractCNo == contractCNo);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.ContractCancelStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.ContractCNo, x.DealerCode, x.ContractCancelStatus, x.Remark,
        x.CreatedDate, x.CreatedBy, x.LUDateTime, x.LUBy, x.ApprovedDate, x.ApprovedBy,
        x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    var nos = items.Select(i => i.ContractCNo).ToList();
    var dtls = await db.DlrContractCancelDtls.Where(d => d.OrgId == t.OrgId && nos.Contains(d.ContractCNo))
        .Select(d => new
        {
            d.ContractCNo, d.DlrContractNo, d.SpecCode, d.ModelCode, d.ColorCode,
            d.ContractUpdateType, d.Qty, d.ContractCancelDtlStatus, d.Remark, d.LogLUDateTime, d.LogLUBy,
        }).ToListAsync();
    var cars = await db.DlrContractCancelCars.Where(c => c.OrgId == t.OrgId && nos.Contains(c.ContractCNo))
        .Select(c => new
        {
            c.ContractCNo, c.DlrContractNo, c.SpecCode, c.ModelCode, c.ColorCode,
            c.CtrCarId, c.DlvExpectedDate, c.CtrCType, c.CtrCTDNo, c.Remark, c.LogLUDateTime, c.LogLUBy,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, details = dtls, cars });
}).RequireAuthorization();

app.MapPost("/api/dlrcontractcancels/save", async (DlrContractCancelSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.ContractCNo ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    if (no.Length < 1) return Results.BadRequest(new { error = "Số phiếu huỷ rỗng." });
    if (dealer.Length < 1) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    var head = await db.DlrContractCancels.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ContractCNo == no);
    if (head is not null && head.ContractCancelStatus != "P")
        return Results.BadRequest(new { error = $"Phiếu đang '{head.ContractCancelStatus}', chỉ sửa được khi 'P'." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var isNew = head is null;
    if (isNew)
    {
        head = new DlrContractCancel
        {
            OrgId = t.OrgId, ContractCNo = no, DealerCode = dealer,
            ContractCancelStatus = "P", CreatedDate = now, CreatedBy = who,
        };
        db.DlrContractCancels.Add(head);
    }
    head!.Remark = dto.Remark;
    head.LUDateTime = now; head.LUBy = who;
    head.LogLUDateTime = now; head.LogLUBy = who;

    // Thay thế trọn bộ dòng của phiếu (nguồn xoá rồi insert … select lại).
    db.DlrContractCancelDtls.RemoveRange(
        await db.DlrContractCancelDtls.Where(d => d.OrgId == t.OrgId && d.ContractCNo == no).ToListAsync());
    db.DlrContractCancelCars.RemoveRange(
        await db.DlrContractCancelCars.Where(c => c.OrgId == t.OrgId && c.ContractCNo == no).ToListAsync());

    foreach (var d in dto.Details ?? new())
        db.DlrContractCancelDtls.Add(new DlrContractCancelDtl
        {
            OrgId = t.OrgId, ContractCNo = no, DlrContractNo = (d.DlrContractNo ?? "").Trim(),
            SpecCode = d.SpecCode, ModelCode = d.ModelCode, ColorCode = d.ColorCode,
            ContractUpdateType = d.ContractUpdateType, Qty = d.Qty,
            ContractCancelDtlStatus = "P", Remark = d.Remark,
            LogLUDateTime = now, LogLUBy = who,
        });
    foreach (var c in dto.Cars ?? new())
        db.DlrContractCancelCars.Add(new DlrContractCancelCar
        {
            OrgId = t.OrgId, ContractCNo = no, DlrContractNo = (c.DlrContractNo ?? "").Trim(),
            SpecCode = c.SpecCode, ModelCode = c.ModelCode, ColorCode = c.ColorCode,
            CtrCarId = (c.CtrCarId ?? "").Trim(), DlvExpectedDate = c.DlvExpectedDate,
            CtrCType = c.CtrCType,      // loại huỷ — nguồn cho phép để trống (dòng 2725)
            CtrCTDNo = c.CtrCTDNo, Remark = c.Remark,
            LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();

    // ===== 🔴 #198 SIDE-EFFECT bị bỏ sót: HỢP ĐỒNG TỰ CHUYỂN "HOÀN THÀNH" =====
    // Nguồn: `TERP.BizHTC/BizHTC.Contract.cs` — khối `// Upd: Dlr_Contract.DlrCtrStatus.` (3244-3298)
    //   nằm BÊN TRONG `Dlr_ContractCancel_SaveX_New20230306` (2375).
    //   BƯỚC 3B: md5 cả file `647641a1`, md5 vùng hàm 2375-3310 `6c93a6b1` — KHỚP 2 máy.
    //
    // 🔴 `DlrCtrStatus = "F"` KHÔNG PHẢI một hành động người dùng bấm: đây là **chỗ DUY NHẤT** trong toàn
    //    `TERP.BizHTC` đặt giá trị "F" (đã grep: 3282 là hit duy nhất; các chỗ khác chỉ đặt P/A/C).
    //    Hợp đồng tự "hoàn thành" khi lưu phiếu huỷ xe mà SAU đó hợp đồng **không còn xe nào chưa xử lý**.
    //
    // Điều kiện của nguồn, dịch từ 3 bảng tạm:
    //   `#tblDlr_Contract`        = các `DlrContractNo` xuất hiện trong DANH SÁCH XE của phiếu vừa lưu;
    //   `#tblDlr_Contract_NotUpd` = trong số đó, HĐ nào CÒN ít nhất một xe `FlagCancel <> '1'`
    //                               **và** `FlagDelivery <> '1'` (xe chưa huỷ và cũng chưa giao);
    //   `#tblDlr_Contract_Upd`    = phần còn lại ⇒ set `DlrCtrStatus = 'F'` + `LogLUBy`/`LogLUDateTime`.
    //   ⇒ Chỉ xét các HĐ CÓ MẶT trên phiếu này, không quét toàn bảng.
    var finishedContracts = new List<string>();
    var ctrNos = (dto.Cars ?? new()).Select(c => (c.DlrContractNo ?? "").Trim())
                                    .Where(x => x.Length > 0).Distinct().ToList();
    foreach (var ctrNo in ctrNos)
    {
        var stillOpen = await db.DlrContractCars.AnyAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == ctrNo
                                                            && x.FlagCancel != "1" && x.FlagDelivery != "1");
        if (stillOpen) continue;
        var ctr = await db.DlrContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == ctrNo);
        if (ctr is null) continue;
        ctr.Status = "F";                       // `TConst.DlrCtrStatus1.Finish`
        ctr.LogLUDateTime = now; ctr.LogLUBy = who;
        finishedContracts.Add(ctrNo);
    }
    if (finishedContracts.Count > 0) await db.SaveChangesAsync();

    return Results.Ok(new { no, created = isNew, details = (dto.Details ?? new()).Count,
                            cars = (dto.Cars ?? new()).Count, finishedContracts });
}).RequireAuthorization();

// `ApproveMulti` / `CancelMulti` của nguồn — duyệt/huỷ NHIỀU phiếu trong một lệnh.
app.MapPost("/api/dlrcontractcancels/approvemulti", async (DlrContractCancelMultiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await DlrCancelSetStatus(dto, "A", db, t, user)).RequireAuthorization();

app.MapPost("/api/dlrcontractcancels/cancelmulti", async (DlrContractCancelMultiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await DlrCancelSetStatus(dto, "C", db, t, user)).RequireAuthorization();

// Thân chung: nguồn có hai hàm riêng nhưng chỉ khác giá trị đích ("A" vs "C"); cả hai đòi phiếu đang "P".
async Task<IResult> DlrCancelSetStatus(DlrContractCancelMultiDto dto, string target, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user)
{
    var nos = (dto.ContractCNos ?? new()).Select(x => (x ?? "").Trim()).Where(x => x.Length > 0).Distinct().ToList();
    if (nos.Count == 0) return Results.BadRequest(new { error = "Chưa chọn phiếu nào." });
    var rows = await db.DlrContractCancels.Where(x => x.OrgId == t.OrgId && nos.Contains(x.ContractCNo)).ToListAsync();
    var missing = nos.Except(rows.Select(r => r.ContractCNo)).ToList();
    if (missing.Count > 0) return Results.BadRequest(new { error = $"Không có phiếu: {string.Join(", ", missing.Take(10))}." });
    var bad = rows.Where(r => r.ContractCancelStatus != "P").Select(r => $"{r.ContractCNo}({r.ContractCancelStatus})").ToList();
    if (bad.Count > 0) return Results.BadRequest(new { error = $"Phiếu không ở 'P': {string.Join(", ", bad.Take(10))}." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    foreach (var r in rows)
    {
        r.ContractCancelStatus = target;
        r.ApprovedDate = now; r.ApprovedBy = who;   // nguồn ghi chung cột này cho cả duyệt lẫn huỷ
        r.LogLUDateTime = now; r.LogLUBy = who;
    }
    var dtls = await db.DlrContractCancelDtls.Where(d => d.OrgId == t.OrgId && nos.Contains(d.ContractCNo)).ToListAsync();
    foreach (var d in dtls) { d.ContractCancelDtlStatus = target; d.LogLUDateTime = now; d.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { count = rows.Count, status = target, detailsSynced = dtls.Count });
}

// ===== HẠNG MỤC gói bảo dưỡng (Mst_MaintainTaskItem) =====
// Port 1:1 cụm 4 hàm `_Create/_Update/_Delete/_Get_New20181119` (Biz.HTC.WH.cs:7236).
// TWIN: cả hai bit khớp hoàn toàn (5/5 hàm, kể cả `Mst_MaintainTask_Get` của bảng cha).
// ⚠️ Bảng cha `Mst_MaintainTask` CHỈ có hàm `_Get` ⇒ danh mục gói bảo dưỡng do DBA nạp; chỉ hạng mục
//    bên trong mới sửa được qua ứng dụng.
// 🔴 `FlagActive` nguồn LUÔN đặt "1" khi tạo, không nhận từ đầu vào.
app.MapGet("/api/maintaintaskitems", async (AppDbContext db, ITenantContext t, string? mtnTkCode, string? flagActive) =>
{
    var qy = db.MstMaintainTaskItems.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mtnTkCode)) qy = qy.Where(x => x.MtnTkCode == mtnTkCode);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
    var items = await qy.OrderBy(x => x.MtnTkCode).ThenBy(x => x.ViewIdx).Select(x => new
    { x.MtnTkCode, x.MtnTkItemCode, x.MtnTkItemName, x.ViewIdx, x.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/maintaintaskitems/create", async (MaintainTaskItemDto dto, AppDbContext db, ITenantContext t) =>
{
    var tk = (dto.MtnTkCode ?? "").Trim();
    var item = (dto.MtnTkItemCode ?? "").Trim();
    if (tk.Length < 1) return Results.BadRequest(new { error = "Mã gói bảo dưỡng rỗng." });
    if (item.Length < 1) return Results.BadRequest(new { error = "Mã hạng mục rỗng." });
    if (await db.MstMaintainTaskItems.AnyAsync(x => x.OrgId == t.OrgId && x.MtnTkCode == tk && x.MtnTkItemCode == item))
        return Results.BadRequest(new { error = $"Hạng mục {item} đã có trong gói {tk}." });
    db.MstMaintainTaskItems.Add(new MstMaintainTaskItem
    {
        OrgId = t.OrgId, MtnTkCode = tk, MtnTkItemCode = item,
        MtnTkItemName = dto.MtnTkItemName, ViewIdx = dto.ViewIdx,
        FlagActive = "1",   // nguồn luôn đặt Flag.Active khi tạo
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { mtnTkCode = tk, mtnTkItemCode = item });
}).RequireAuthorization();

app.MapPost("/api/maintaintaskitems/update", async (MaintainTaskItemDto dto, AppDbContext db, ITenantContext t) =>
{
    var tk = (dto.MtnTkCode ?? "").Trim();
    var item = (dto.MtnTkItemCode ?? "").Trim();
    var row = await db.MstMaintainTaskItems.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MtnTkCode == tk && x.MtnTkItemCode == item);
    if (row is null) return Results.NotFound(new { error = $"Gói {tk} không có hạng mục {item}." });
    row.MtnTkItemName = dto.MtnTkItemName;
    row.ViewIdx = dto.ViewIdx;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.MtnTkCode, row.MtnTkItemCode, row.ViewIdx, row.FlagActive });
}).RequireAuthorization();

app.MapPost("/api/maintaintaskitems/delete", async (MaintainTaskItemKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var tk = (dto.MtnTkCode ?? "").Trim();
    var item = (dto.MtnTkItemCode ?? "").Trim();
    var row = await db.MstMaintainTaskItems.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MtnTkCode == tk && x.MtnTkItemCode == item);
    if (row is null) return Results.NotFound(new { error = $"Gói {tk} không có hạng mục {item}." });
