app.MapPost("/api/support/contract-smcode", async (List<ContractSmFixDto> fixes, AppDbContext db, ITenantContext t) =>
{
    if (fixes is null || fixes.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào." });
