// ===== Công cụ sửa giá HĐ đại lý (Support — port 1:1 FrmSearchForUpdatePrice/FrmSupportUpdatePrice, 2010.HTC) =====
// Tra chi tiết xe trong HĐ đại lý theo số HĐ / VIN để sửa giá (giá sau VAT).
app.MapGet("/api/support/deal-prices", async (AppDbContext db, ITenantContext t, string? dealNo, string? vin) =>
{
    var q = from d in db.DealerDealDetails.Where(x => x.OrgId == t.OrgId)
            join h in db.DealerDeals.Where(x => x.OrgId == t.OrgId) on d.DealId equals h.Id
            select new { d.Id, h.DealNo, h.DealerCode, d.CarId, d.PriceAFVAT };
    if (!string.IsNullOrWhiteSpace(dealNo)) q = q.Where(x => x.DealNo.Contains(dealNo!));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.CarId.Contains(vin!));
    var rows = await q.OrderBy(x => x.DealNo).ThenBy(x => x.CarId).Take(500).ToListAsync();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

// Sửa giá hàng loạt theo id dòng chi tiết. Trả số dòng đã sửa + log giá cũ→mới.
app.MapPost("/api/support/deal-prices", async (List<DealPriceFixDto> fixes, AppDbContext db, ITenantContext t) =>
{
    if (fixes is null || fixes.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào." });
    int updated = 0; var changes = new List<object>();
    foreach (var f in fixes)
    {
        if (f.NewPrice < 0) { changes.Add(new { f.Id, error = "Giá âm." }); continue; }
        var d = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == f.Id);
        if (d is null) { changes.Add(new { f.Id, error = "Không tìm thấy dòng." }); continue; }
        if (d.PriceAFVAT == f.NewPrice) continue;
        changes.Add(new { d.Id, d.CarId, oldPrice = d.PriceAFVAT, newPrice = f.NewPrice });
        d.PriceAFVAT = f.NewPrice; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = fixes.Count, updated, changes });
}).RequireAuthorization();

app.MapGet("/api/dealerdeals", async (AppDbContext db, ITenantContext t, string? dealer, string? salesType, string? buyer) =>
{
    var q = db.DealerDeals.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(d => d.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(salesType)) q = q.Where(d => d.SalesType == salesType);
    if (!string.IsNullOrWhiteSpace(buyer)) q = q.Where(d => d.CustomerCodeBuyer == buyer);
    var items = await q.OrderByDescending(d => d.Id).Take(500).Select(d => new
    {
        d.DealNo, d.DealNoUser, d.DealerCode, d.CustomerCodeBuyer, d.SalesType, d.FlagPDI, d.DealDate,
        cars = db.DealerDealDetails.Count(c => c.OrgId == t.OrgId && c.DealId == d.Id),
        total = db.DealerDealDetails.Where(c => c.OrgId == t.OrgId && c.DealId == d.Id).Sum(c => (decimal?)c.PriceAFVAT) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/dealerdeals", async (DealerDealDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.CustomerCodeBuyer)) return Results.BadRequest(new { error = "Cần khách hàng người mua." });
    if (string.IsNullOrWhiteSpace(dto.SalesType)) return Results.BadRequest(new { error = "Chưa chọn kiểu bán lẻ." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.CarId)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa chọn xe." });
    var dupe = cars.GroupBy(c => c.CarId.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"Xe {dupe.Key} bị trùng!" });
    var flagPdi = dto.FlagPDI == "0" ? "0" : "1";
    if (flagPdi == "0" && string.IsNullOrWhiteSpace(dto.ReasonNotPDI)) return Results.BadRequest(new { error = "Không PDI phải nhập lý do." });
    var no = "DL" + DateTime.Now.ToString("yyMMddHHmmss");
    var d = new DealerDeal
    {
        OrgId = t.OrgId, DealNo = no, DealNoUser = dto.DealNoUser, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(),
        CustomerCodeBuyer = dto.CustomerCodeBuyer.Trim().ToUpperInvariant(), CustomerCodeDriver = dto.CustomerCodeDriver, CustomerCodeHolder = dto.CustomerCodeHolder,
        DlrContractNo = dto.DlrContractNo, SalesType = dto.SalesType.Trim(), FlagPDI = flagPdi, ReasonNotPDI = dto.ReasonNotPDI
    };
    db.DealerDeals.Add(d); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.DealerDealDetails.Add(new DealerDealDetail { OrgId = t.OrgId, DealId = d.Id, CarId = c.CarId.Trim().ToUpperInvariant(), CusInvoiceNo = c.CusInvoiceNo, CusInvoiceDate = c.CusInvoiceDate, PriceAFVAT = c.PriceAFVAT });
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DealNo, d.CustomerCodeBuyer, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/dealerdeals/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
    if (d is null) return Results.NotFound(new { no });
    var cars = await db.DealerDealDetails.Where(c => c.OrgId == t.OrgId && c.DealId == d.Id)
        .Select(c => new { c.CarId, c.CusInvoiceNo, c.CusInvoiceDate, c.PriceAFVAT, c.PlateNo }).ToListAsync();
    return Results.Ok(new { d.DealNo, d.CustomerCodeBuyer, d.CustomerCodeDriver, d.CustomerCodeHolder, d.SalesType, d.FlagPDI, d.CtmCareFlag, count = cars.Count, cars, total = cars.Sum(x => x.PriceAFVAT) });
}).RequireAuthorization();

// Sửa hàng loạt KH mua/lái/đứng tên trên các GD bán lẻ đã lập (port 1:1 FrmEditDeal_KHGD, 2010.HTC/SalesDealer)
app.MapPost("/api/dealerdeals/edit-khgd", async (EditDealKhgdDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var no = r.DealNo!.Trim();
        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
        if (d is null) { notFound.Add(no); continue; }
        if (r.CustomerCodeBuyer is not null) d.CustomerCodeBuyer = r.CustomerCodeBuyer;
        d.CustomerCodeHolder = r.CustomerCodeHolder;
        d.CustomerCodeDriver = r.CustomerCodeDriver;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Sửa kiểu bán lẻ hàng loạt (port 1:1 FrmEditDeal_SalesType/DealerSalesDealUpdateSalesTypeMulti gốc)
app.MapPost("/api/dealerdeals/edit-salestype", async (EditDealSalesTypeDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo) && !string.IsNullOrWhiteSpace(r.SalesType)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var no = r.DealNo!.Trim();
        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
        if (d is null) { notFound.Add(no); continue; }
        d.SalesType = r.SalesType!.Trim().ToUpperInvariant();
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// ===== 🔴 #196 DUYỆT KIỂM CHỨNG BÁN LẺ — `OSHCC_DLS_Deal_UpdCtmCareFlagX_New20260805` =====
// Nguồn: `TERP.BizHTC/HCC/BizHTC.HCC.cs` — hàm mới ở **3654**, call-site đã repoint (3398).
//
// 🔴 BƯỚC 3B — HÀM NÀY **CHỈ CÓ TRÊN MÁY 150**:
//   So đúng cặp `.Release.2025` ↔ `.Release.2025` (đúng luật `C0-ducentesimusoctogesimustertius`):
//   laptop `HCC/BizHTC.HCC.cs` 3651 dòng · máy 150 **3982 dòng (+331)**; bản 150 có thêm nguyên hàm
//   `..._New20260805` ("Nâng cấp Call sang Membership tạo hội viên khi Duyệt kiểm chứng bán lẻ", 2026-08-05)
//   và ĐỔI call-site sang gọi nó. Bản laptop vẫn gọi `OSHCC_DLS_Deal_UpdCtmCareFlagX` cũ.
//   `BizHTC.Common.cs` trên 150 cũng có thêm 8 biến cấu hình `_strUrlAPI_Loyalty*` phục vụ đúng hàm này.
//   ⇒ canonical cho cụm HCC = **máy 150**. (Ngược với #195, nơi canonical là laptop — mỗi FILE một chiều.)
//
// SÁU GUARD của nguồn, đúng thứ tự:
//  1. Deal phải TỒN TẠI (`myDealerSales_CheckDeal(..., Flag.Yes, "")`).
//  2. `CtmCareFlag` đang `Flag.Active` ⇒ lỗi `..._InvalidCtmCareFlag` (đã kiểm chứng rồi, không làm lại).
//  3. `DealerCodeBuyer` CÓ giá trị ⇒ lỗi `..._CannotUpdateDealWithAnotherDealer` (bán sang đại lý khác).
//  4. `DLS_DealDetail` phải có ít nhất 1 dòng ⇒ `..._TableDetailNotBlank`.
//  5. TỪNG dòng chi tiết: `CusInvoiceNo` ≠ rỗng · `CusInvoiceDate` ≠ null · `PlateNo` ≠ rỗng
//     (ba mã lỗi riêng: `..._CusInvoiceNoNotNull` / `..._CusInvoiceDateNotNull` / `..._PlateNoNotNull`).
//  6. `DLS_DealAttachFile` phải có ít nhất 1 dòng **`DlsFileType = 'BILL'`** — nguồn ghi chú thẳng:
//     *"Phải có ảnh hóa đơn mới được kiểm chứng 20180313"* ⇒ `..._TableAttachNotBlank`.
// GHI: `CtmCareFlag = "1"`, `CtmCareUpdDate`, `CtmCareUpdBy`, `CtmCareRemark` (ghi `_dbMain` và `_dbWH`).
//
// ⚠️ NỢ (không bịa): sau khi ghi, nguồn dựng một câu SQL gộp 6 bảng
//   (`DLS_Deal` × `DLS_DealerCustomer` × `Dls_DealDetail` × `Car_Car` × `Mst_CarModel`) rồi **gọi API Loyalty**
//   `Crd_Member_AddAndApprByDMS` để tạo + duyệt hội viên. MiniHTC chưa có tầng gọi API ngoài ⇒ endpoint này
//   TRẢ VỀ sẵn `loyaltyPayload` đúng các trường nguồn map (kể cả **đảo giới tính**: nguồn `Gender='0'` (Nam)
//   ⇒ gửi `MemberGender='1'`) để tầng tích hợp dùng, và ghi nợ phần gọi HTTP thật.
app.MapPost("/api/dealerdeals/{no}/verify-ctmcare", async (string no, VerifyCtmCareDto dto,
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
    if (d is null) return Results.NotFound(new { no });                                  // guard 1

    if ((d.CtmCareFlag ?? "") == "1")                                                    // guard 2
        return Results.BadRequest(new { error = "Hợp đồng đã được kiểm chứng rồi.", dealNo = no });

    if (!string.IsNullOrWhiteSpace(d.DealerCodeBuyer))                                   // guard 3
        return Results.BadRequest(new { error = "Hợp đồng bán cho đại lý khác — không kiểm chứng được.", dealerCodeBuyer = d.DealerCodeBuyer });

    var lines = await db.DealerDealDetails.Where(x => x.OrgId == t.OrgId && x.DealId == d.Id).ToListAsync();
    if (lines.Count == 0)                                                                // guard 4
        return Results.BadRequest(new { error = "Hợp đồng chưa có dòng chi tiết." });

    foreach (var l in lines)                                                             // guard 5
    {
        if (string.IsNullOrWhiteSpace(l.CusInvoiceNo))
            return Results.BadRequest(new { error = "Chưa có số hoá đơn khách hàng.", carId = l.CarId });
        if (l.CusInvoiceDate is null)
            return Results.BadRequest(new { error = "Chưa có ngày hoá đơn khách hàng.", carId = l.CarId });
        if (string.IsNullOrWhiteSpace(l.PlateNo))
            return Results.BadRequest(new { error = "Chưa có biển số xe.", carId = l.CarId });
    }

    // guard 6 — phải có ảnh hoá đơn ("BILL") mới được kiểm chứng.
    var hasBill = await db.DlsDealAttachFiles
        .AnyAsync(x => x.OrgId == t.OrgId && x.DealNo == no && x.DlsFileType == "BILL");
    if (!hasBill)
        return Results.BadRequest(new { error = "Chưa đính kèm ảnh hoá đơn (DlsFileType = 'BILL') — không kiểm chứng được." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    d.CtmCareFlag = "1";
    d.CtmCareUpdDate = now; d.CtmCareUpdBy = who;
    d.CtmCareRemark = (dto.Remark ?? "").Trim();
    await db.SaveChangesAsync();

    // Dữ liệu hội viên đúng phép map của nguồn — CHƯA gọi API (ghi nợ tầng tích hợp Loyalty).
    //
    // 🔴 #273 ĐỐI CHIẾU LẠI TỪNG TRƯỜNG với `objCrd_Member` của nguồn (`BizHTC.HCC.cs:3895-3915` —
    //   đọc được nhờ cách so 2 máy xác lập ở #269-#272). Nguồn gán **20 trường**, port cũ mới có 16
    //   ⇒ **THIẾU 6**: `VIN` · `ModelCode` · `ModelName` · `WarrantyExpiryDate` · `MemberActiveDate` ·
    //   `RegistrationDate`.
    //
    // 🔴 `RegistrationDate` và `MemberActiveDate` LẤY CÙNG MỘT CỘT `ddd.DeliveryDate` — nguồn select nó
    //   HAI LẦN với hai alias (`:3864-3865`). Không phải chép nhầm: hội viên **đăng ký và có hiệu lực**
    //   cùng thời điểm giao xe. Thiếu một trong hai thì bên Loyalty mất mốc tính kỳ.
    // ⚠️ Nguồn join `Car_Car cc on ddd.CarId = cc.CarId` rồi lấy `cc.VIN`/`cc.ModelCode` ⇒ ở nguồn
    //   `CarId` **KHÁC** VIN. MiniHTC lưu VIN ngay trong `DealerDealDetail.CarId` nên phép join co lại
    //   thành tra `CarVinMaster` theo VIN; tra không ra thì để `vin = CarId`, `modelCode/modelName = null`
    //   — **KHÔNG bịa giá trị**.
    // ⚠️ `carId` không có trong payload nguồn (nguồn chỉ dùng nó để join) — giữ lại, đánh dấu là trường THÊM.
    var cust = await db.DealerCustomers.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.CustomerCode == d.CustomerCodeBuyer);

    var carIds = lines.Select(x => x.CarId).Distinct().ToList();
    var vinRows = await db.CarVinMasters.Where(v => v.OrgId == t.OrgId && carIds.Contains(v.VIN)).ToListAsync();
    var vinMap = vinRows.GroupBy(v => v.VIN).ToDictionary(g => g.Key, g => g.First());
    var modelCodes = vinRows.Where(v => v.ModelCode != null).Select(v => v.ModelCode!).Distinct().ToList();
    var modelRows = await db.CarModelStds.Where(m => m.OrgId == t.OrgId && modelCodes.Contains(m.ModelCode)).ToListAsync();
    var modelMap = modelRows.GroupBy(m => m.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);

    var loyaltyPayload = lines.Select(l =>
    {
        var cv = vinMap.TryGetValue(l.CarId, out var v) ? v : null;
        var mCode = cv?.ModelCode;
        return new
        {
            dealNo = d.DealNo,
            customerCode = d.CustomerCodeBuyer,
            memberName = cust?.FullName,
            phoneNo = cust?.PhoneNo,
            memberGender = (cust?.Gender ?? "") == "0" ? "1" : "0",   // 🔴 nguồn ĐẢO cờ giới tính, giữ nguyên
            dateOfBirth = cust?.DateOfBirth,
            provinceCode = cust?.ProvinceCode,
            districtCode = cust?.DistrictCode,
            memAddress = cust?.Address,
            idCardNo = cust?.IDCardNo,
            carId = l.CarId,                                          // trường THÊM của port, nguồn không gửi
            carNo = l.PlateNo,
            vin = cv?.VIN ?? l.CarId,                                 // #273 cc.VIN
            tradeMarkCode = "HYUNDAI",                                // nguồn ghi CỨNG
            modelCode = mCode,                                        // #273 cc.ModelCode
            modelName = mCode != null && modelMap.TryGetValue(mCode, out var mn) ? mn : null, // #273 mcm.ModelName
            dlCodeRegis = d.DealerCode,
            warrantyExpiryDate = l.WarrantyExpiresDate,               // #273 ddd.WarrantyExpiresDate
            memberActiveDate = l.DeliveryDate,                        // #273 ddd.DeliveryDate (alias 1)
            registrationDate = l.DeliveryDate,                        // #273 ddd.DeliveryDate (alias 2 — CÙNG cột)
            invoiceDate = l.CusInvoiceDate,
        };
    }).ToList();

    return Results.Ok(new { d.DealNo, ctmCareFlag = d.CtmCareFlag, d.CtmCareUpdDate, d.CtmCareUpdBy, d.CtmCareRemark,
        detailRows = lines.Count, loyaltyPayload,
        note = "Chưa gọi API Loyalty Crd_Member_AddAndApprByDMS — MiniHTC chưa có tầng gọi API ngoài (nợ)." });
}).RequireAuthorization();

// Sửa cờ kiểm chứng CSKH hàng loạt (port 1:1 FrmEditDeal_KiemChung/DealerSalesDealUpdateCtmCareInfoMulti gốc)
app.MapPost("/api/dealerdeals/edit-ctmcare", async (EditDealCtmCareDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var no = r.DealNo!.Trim();
        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
        if (d is null) { notFound.Add(no); continue; }
        d.CtmCareFlag = r.CtmCareFlag;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Sửa biển số xe hàng loạt (port 1:1 FrmEditDeal_PlateNo/DealerSalesDealUpdatePlateNoMulti gốc) — khóa theo (DealNo, CarId)
app.MapPost("/api/dealerdeals/edit-platenumber", async (EditDealPlateNoDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo) && !string.IsNullOrWhiteSpace(r.CarId)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var no = r.DealNo!.Trim(); var carId = r.CarId!.Trim();
        var d = await db.DealerDeals.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
        if (d is null) { notFound.Add(no); continue; }
        var line = await db.DealerDealDetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealId == d.Id && x.CarId == carId);
