// ===== Đơn đặt hàng (SalesOrder/So — port 1:1 FrmOrder, DMSales.Foton) =====
app.MapGet("/api/salesorders", async (AppDbContext db, ITenantContext t, string? status, string? dealer, string? type) =>
{
    var query = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) query = query.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(type)) query = query.Where(o => o.OrderType == type);
    var items = await query.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.SoCode, o.OrderType, o.PayType, o.DealerCode, o.Status, o.CreatedAt, o.SentAt,
        o.SalesPolicy, o.ExpectedMonth, o.LatestDeliveryDate, o.Approved1At, o.Approved2At, o.RejectReason,
        lines = db.SalesOrderLines.Count(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id),
        qty = db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id).Sum(l => (int?)l.RequestedQuantity) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/salesorders", async (SalesOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần đại lý." });
    var type = (dto.OrderType ?? "Plan").Trim();
    if (type is not ("Plan" or "UnPlan")) return Results.BadRequest(new { error = "Loại đơn = Plan | UnPlan." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.ModelCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng model." });
    if (lines.Any(l => l.RequestedQuantity <= 0)) return Results.BadRequest(new { error = "Số lượng phải > 0." });
    var no = (type == "Plan" ? "SOP" : "SOU") + DateTime.Now.ToString("yyMMddHHmmss");
    var o = new SalesOrder { OrgId = t.OrgId, SoCode = no, OrderType = type, PayType = dto.PayType, // 🔴 Nguồn tạo đơn là "P" (chờ duyệt) NGAY — không có bước nháp/gửi.
    DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), Status = "P" };
    db.SalesOrders.Add(o); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.SalesOrderLines.Add(new SalesOrderLine { OrgId = t.OrgId, SalesOrderId = o.Id, ModelCode = l.ModelCode.Trim(), SpecCode = l.SpecCode, ContractType = l.ContractType, YearProduction = l.YearProduction, RequestedQuantity = l.RequestedQuantity, RequestedDate = l.RequestedDate, UnitPrice = l.UnitPrice, RemarkDL = l.RemarkDL, ColorCode = l.ColorCode, CarId = l.CarId });
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, o.OrderType, lines = lines.Count, status = o.Status });
}).RequireAuthorization();

app.MapGet("/api/salesorders/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id)
        .Select(l => new { l.ModelCode, l.SpecCode, l.ColorCode, l.ContractType, l.YearProduction, l.RequestedQuantity, l.RequestedDate, l.UnitPrice, l.RemarkDL, l.ApprovedQuantity, l.ApprovedDate, l.UnitPriceInit, l.MapVINRanking, l.Remark, l.CarId }).ToListAsync();
    return Results.Ok(new { o.SoCode, o.Status, count = lines.Count, lines, qty = lines.Sum(x => x.RequestedQuantity) });
}).RequireAuthorization();

// ⚠️ ĐÃ BỎ `/api/salesorders/{no}/send`: nguồn KHÔNG có bước "gửi đơn" — `OrderSOCreate_New20181119`
//    tạo thẳng `SOStatus = "P"`. "Draft"/"Sent" là hai trạng thái port cũ tự đặt.

// 🔴 HUỶ đơn hàng — `OrderSOCancel_New20181119` (Biz.HTC.WH.cs:24674-24782): chỉ từ "P", sang "C".
//    Nguồn phân biệt **Huỷ ("C")** với **Từ chối ("R")** là hai đường khác nhau; port cũ thiếu hẳn Huỷ.
app.MapPost("/api/salesorders/{no}/cancel", async (string no, SoRejectDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ huỷ được đơn đang chờ duyệt (P)." });
    o.Status = "C"; o.RejectReason = dto.Reason; o.RejectedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, status = o.Status, statusName = "Huỷ" });
}).RequireAuthorization();

// Duyệt cấp 1 (FrmOrderApprove): chính sách bán + tháng dự kiến/SX/ngày giao + SL duyệt từng dòng; mọi dòng phải có năm SX
app.MapPost("/api/salesorders/{no}/approve1", async (string no, SoApprove1Dto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt cấp 1 đơn đang chờ duyệt (P)." });
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && l.SalesOrderId == o.Id).ToListAsync();
    if (lines.Any(l => string.IsNullOrWhiteSpace(l.YearProduction)))
        return Results.BadRequest(new { error = "Có bản ghi chưa chọn năm sản xuất?" });

    // 🔴 Nguồn duyệt cấp 1 nhận TOÀN BỘ dòng chi tiết từ người duyệt và guard rất chặt
    //    (`OrderSOApprove1_new20181119`, Biz.HTC.WH.cs:25389-25485). Port cũ tự gán SL duyệt = SL yêu cầu.
    var inLines = dto.Lines ?? new();
    if (inLines.Count != lines.Count)
        return Results.BadRequest(new { error = $"Số dòng duyệt ({inLines.Count}) không khớp số dòng đơn hàng ({lines.Count})." });
    // Khoá đối chiếu ĐÚNG nguồn: |SOCode||SpecCode||ModelCode||ColorCode| — ColorCode là một phần khoá.
    static string LineKey(string so, string? spec, string model, string? color) => $"|{so}||{spec}||{model}||{color}|";
    var inByKey = new Dictionary<string, SoApprove1LineDto>();
    foreach (var il in inLines)
        inByKey[LineKey(o.SoCode, il.SpecCode, il.ModelCode ?? "", il.ColorCode)] = il;
    foreach (var l in lines)
    {
        if (!inByKey.TryGetValue(LineKey(o.SoCode, l.SpecCode, l.ModelCode, l.ColorCode), out var il))
            return Results.BadRequest(new { error = $"Dòng duyệt không khớp dữ liệu đơn hàng: {l.ModelCode}/{l.SpecCode}/{l.ColorCode}." });
        if (il.ApprovedQuantity < 0)
            return Results.BadRequest(new { error = $"Số lượng duyệt của {l.ModelCode} không hợp lệ." });
        // Nguồn bắt buộc UnitPriceInit **>= 1.0** (không phải chỉ > 0).
        if (il.UnitPriceInit < 1.0m)
            return Results.BadRequest(new { error = $"Đơn giá duyệt của {l.ModelCode} phải >= 1." });
        l.ApprovedQuantity = il.ApprovedQuantity;
        l.ApprovedDate = il.ApprovedDate;
        l.UnitPriceInit = il.UnitPriceInit;
        l.MapVINRanking = 5.0m;   // nguồn gán CỨNG 5.0, cố tình không lấy input (dòng `dr["MapVINRanking"] = 5.0;`)
        l.Remark = il.Remark;
    }
    o.SPCode = dto.SPCode; o.SalesPolicy = dto.SalesPolicy; o.ExpectedMonth = dto.ExpectedMonth;
    o.ProductionMonth = dto.ProductionMonth; o.LatestDeliveryDate = dto.LatestDeliveryDate;
    o.Status = "A1"; o.Approved1At = DateTime.Now;
    o.ApprovedBy1 = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, status = o.Status, statusName = "Duyệt cấp 1", approvedLines = lines.Count });
}).RequireAuthorization();

// Duyệt cấp 2 (duyệt cuối)
// 🔴 Duyệt cấp 2 — `OrderSOApprove2_New20181119` (Biz.HTC.WH.cs:25698-25813). Vào từ "A1".
//    Nguồn có **HAI ngả trong CÙNG một hàm**: mặc định → "A2"; nếu `strFlagUnapprove = Flag.Active`
//    thì **BỎ DUYỆT, trả đơn về "P"**. Port cũ thiếu hẳn ngả bỏ duyệt.
app.MapPost("/api/salesorders/{no}/approve2", async (string no, AppDbContext db, ITenantContext t, bool? unapprove) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    if (o.Status != "A1") return Results.BadRequest(new { error = "Đơn phải duyệt cấp 1 (A1) trước." });
    if (unapprove == true)
    {
        o.Status = "P"; o.Approved1At = null; o.Approved2At = null;
        await db.SaveChangesAsync();
        return Results.Ok(new { o.SoCode, status = o.Status, statusName = "Chờ duyệt (đã bỏ duyệt)" });
    }
    o.Status = "A2"; o.Approved2At = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, status = o.Status, statusName = "Duyệt cấp 2" });
}).RequireAuthorization();

app.MapPost("/api/salesorders/{no}/reject", async (string no, SoRejectDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    // 🔴 Nguồn (`OrderSOReject_New201811119`) guard `strSOStatusListToCheck = Stage.Pending` ⇒ **CHỈ từ "P"**.
    //    Port cũ cho từ chối cả đơn đã duyệt cấp 1 — guard RỘNG hơn nguồn (sai chiều).
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ từ chối được đơn đang chờ duyệt (P)." });
    o.Status = "R"; o.RejectReason = dto.Reason; o.RejectedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { o.SoCode, status = o.Status });
}).RequireAuthorization();

// ===== Duyệt tự động đơn hàng theo luật (D4OSORA — port 1:1 FrmDuyetTuDongDonHang, 2010.HTC/Sales/Upgrade) =====
string[] _d4OsoraRules = { "Rule1", "Rule2", "Rule2A", "Rule3", "RuleCancel" };
app.MapGet("/api/dms40/so-root-approvals", async (AppDbContext db, ITenantContext t) =>
{
    var items = await db.Dms40SoRootApprovals.Where(x => x.OrgId == t.OrgId).OrderByDescending(x => x.Id).Take(100)
        .Select(x => new { x.ApprovalNo, x.RuleType, x.AffectedCount, x.RunAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Khớp btnApprove_Click gốc: chọn luật rồi chạy 1 lượt — RuleCancel hủy hàng loạt SO đang chờ (Sent→Rejected);
// các luật khác duyệt tự động hàng loạt SO đang chờ (Sent→Approved2, bỏ qua Approved1).
app.MapPost("/api/dms40/so-root-approvals/run", async (Dms40ApproveDto dto, AppDbContext db, ITenantContext t) =>
{
    var rule = (dto.RuleType ?? "").Trim();
    if (!_d4OsoraRules.Contains(rule)) return Results.BadRequest(new { error = "Luật không hợp lệ (Rule1|Rule2|Rule2A|Rule3|RuleCancel)." });
    var pending = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && o.Status == "P").ToListAsync();
    var now = DateTime.Now;
    if (rule == "RuleCancel")
        foreach (var o in pending) { o.Status = "C"; o.RejectReason = "Hủy tự động (" + rule + ")"; o.RejectedAt = now; }
    else
        foreach (var o in pending) { o.Status = "A2"; o.Approved1At = now; o.Approved2At = now; }
    var no = "D4OSORA" + DateTime.Now.ToString("yyMMddHHmmss");
    var log = new Dms40SoRootApproval { OrgId = t.OrgId, ApprovalNo = no, RuleType = rule, AffectedCount = pending.Count, RunAt = now };
    db.Dms40SoRootApprovals.Add(log);
    await db.SaveChangesAsync();
    return Results.Ok(new { log.ApprovalNo, log.RuleType, affected = pending.Count });
}).RequireAuthorization();

// Đổi số đơn hàng SO (port 1:1 FrmOrderSOModify, DMSales.Foton/Sales). Chỉ đổi khi còn Draft; mã mới không được trùng.
app.MapPost("/api/salesorders/{no}/rename-code", async (string no, SoRenameDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.SalesOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SoCode == no);
    if (o is null) return Results.NotFound(new { no });
    var newCode = (dto.NewSoCode ?? "").Trim().ToUpperInvariant();
    if (string.IsNullOrWhiteSpace(newCode)) return Results.BadRequest(new { error = "Chưa nhập số đơn hàng mới." });
    if (o.Status != "P") return Results.BadRequest(new { error = "Chỉ đổi số đơn hàng khi đơn còn chờ duyệt (P)." });
    if (newCode != no && await db.SalesOrders.AnyAsync(x => x.OrgId == t.OrgId && x.SoCode == newCode))
        return Results.BadRequest(new { error = $"Số đơn hàng '{newCode}' đã tồn tại." });
    var oldCode = o.SoCode;
    o.SoCode = newCode;
    await db.SaveChangesAsync();
    return Results.Ok(new { oldCode, newCode = o.SoCode });
}).RequireAuthorization();

// ===== Packing List (PackingList/PL — port 1:1 FrmNewPL/FrmMngPL, DMSales.Foton) =====
// ===== #162: MỐC VÒNG ĐỜI XE THEO VIN (VIN_MyStatus) =====
// Nguồn: DataWH/Biz.HTC.WH.cs:33899 (csproj 272) — ContractPackingListCreate_New20190923, ghi tại 35533.
// BƯỚC 3B: hàm bắt đầu cùng dòng 33899 ở CẢ HAI máy, vùng 1767 dòng md5 d5407aae KHỚP.
app.MapGet("/api/vinmystatus", async (AppDbContext db, ITenantContext t, string? vin, string? pending) =>
{
    var q = db.VinMyStatuses.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.VIN == vin!.Trim().ToUpperInvariant());
    // "pending=1": xe đã dựng mốc nhưng CHƯA map VIN và CHƯA xuất kho — đúng trạng thái nguồn tạo ra.
    if (pending == "1") q = q.Where(x => x.MapDateTime == null && x.DeliveryOutDate == null);
    var items = await q.OrderByDescending(x => x.Id).Take(1000).Select(x => new {
        x.VIN, x.MapDateTime, x.DeliveryOutDate, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/packinglists", async (AppDbContext db, ITenantContext t, string? lc, string? port) =>
{
    var query = db.PackingLists.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(lc)) query = query.Where(p => p.LcNo == lc);
    if (!string.IsNullOrWhiteSpace(port)) query = query.Where(p => p.PortCode == port);
    var items = await query.OrderByDescending(p => p.Id).Take(500).Select(p => new
    {
        p.PLNo, p.LcNo, p.PortCode, p.PLType, p.ShippingDateStart, p.ShippingDateEndExpected, p.ShippingDateEnd, p.PLStatus, p.CreatedAt,
        vins = db.PackingListVins.Count(v => v.OrgId == t.OrgId && v.PLId == p.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/packinglists", async (PackingListDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.LcNo)) return Results.BadRequest(new { error = "Cần số LC." });
    if (dto.ShippingDateStart is null) return Results.BadRequest(new { error = "Chưa có thông tin ngày lên tàu." });
    if (dto.ShippingDateEndExpected is null) return Results.BadRequest(new { error = "Chưa có thông tin ngày DK đến cảng." });
    var vins = (dto.Vins ?? new()).Where(v => !string.IsNullOrWhiteSpace(v.Vin)).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "VIN trong danh sách không được trống!" });
    var dupe = vins.GroupBy(v => v.Vin.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "PL" + DateTime.Now.ToString("yyMMddHHmmss");
    var p = new PackingList { OrgId = t.OrgId, PLNo = no, LcNo = dto.LcNo.Trim(), PortCode = dto.PortCode, PLType = dto.PLType, ShippingDateStart = dto.ShippingDateStart.Value, ShippingDateEndExpected = dto.ShippingDateEndExpected.Value,
        // 🔴 #123 parity CT_PackingList: nguồn gán ngày đến cảng THỰC TẾ bằng ngày dự kiến ngay khi tạo
        // (Biz.HTC.WH.cs:34688-34689), và đặt PLStatus = Stage.Finished ("F") NGAY — nhánh đặt "P" theo
        // PLType != HTMV đã bị COMMENT ở nguồn (34691-34693).
        ShippingDateEnd = dto.ShippingDateEndExpected.Value, PLStatus = "F" };
    db.PackingLists.Add(p); await db.SaveChangesAsync();
    foreach (var v in vins)
        db.PackingListVins.Add(new PackingListVin { OrgId = t.OrgId, PLId = p.Id, Vin = v.Vin.Trim().ToUpperInvariant(), CrateType = v.CrateType });
    // ===== #162 side-effect: nguồn `ContractPackingListCreate_New20190923` ghi BỐN bảng =====
    //   CT_PackingList · Car_VIN · VIN_MyStatus · Mng_Device_Car — port cũ chỉ có hai bảng đầu.
    foreach (var v in vins)
    {
        var whoPl = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var nowPl = DateTime.Now;
        var vinUp = (v.Vin ?? "").Trim().ToUpperInvariant();
        // (1) dựng MỐC vòng đời cho VIN, hai mốc để NULL đúng như nguồn (điền ở bước sau).
        if (vinUp.Length > 0 && !await db.VinMyStatuses.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vinUp))
            db.VinMyStatuses.Add(new VinMyStatus { OrgId = t.OrgId, VIN = vinUp,
                MapDateTime = null, DeliveryOutDate = null, LogLUDateTime = nowPl, LogLUBy = whoPl });

        // (2) gắn THIẾT BỊ của xe: nguồn KHÔNG nhận từ đầu vào mà JOIN Mst_DeviceType_Spec
        //     theo Car_VIN.ActualSpec (lọc FlagActive='1') ⇒ suy ra theo SPEC THỰC TẾ của xe.
        var carVin = await db.CarVinMasters.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.VIN == vinUp);
        if (carVin is not null)
        {
            var devTypes = await db.DeviceTypeSpecs
                .Where(d => d.OrgId == t.OrgId && d.SpecCode == carVin.SpecCode && d.FlagActive == "1")
                .Select(d => d.DeviceTypeCode).Distinct().ToListAsync();
            foreach (var dt in devTypes)
            {
                if (await db.DeviceCars.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vinUp && x.DeviceTypeCode == dt)) continue;
                db.DeviceCars.Add(new DeviceCar { OrgId = t.OrgId, VIN = vinUp, ModelCode = carVin.ModelCode,
                    SpecCode = carVin.SpecCode, DeviceTypeCode = dt,
                    LogLUDateTime = nowPl, LogLUBy = whoPl });
            }
        }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PLNo, p.LcNo, vins = vins.Count });
}).RequireAuthorization();

// ===== 🔴 LỊCH SỬ DI CHUYỂN KHO của xe (Sto_StorageTransaction — 2010.HTC ERP.V15.DataWH) =====
// Port cũ THIẾU HOÀN TOÀN bảng này. Nguồn: Biz.HTC.WH.cs — Sto_StorageTransaction_AddX/_Check (bản máy 150).
var storageRefTypeNames = new Dictionary<string, string>
{
    ["PL"] = "Packing list",
    ["BBGN"] = "Biên bản giao nhận",
};

app.MapGet("/api/storagetransactions/reftypes", () => Results.Ok(new
{
    refTypes = storageRefTypeNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "FlagInDay bật khi xe rời kho ngay trong ngày vào — chỉ tính phí lưu kho ngày đó cho kho xuất.",
})).RequireAuthorization();

app.MapGet("/api/storagetransactions", async (
    AppDbContext db, ITenantContext t, string? vin, string? refNo, string? refType, string? storageCode) =>
{
    var qy = db.StorageTransactions.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) qy = qy.Where(x => x.Vin == vin);
    if (!string.IsNullOrWhiteSpace(refNo)) qy = qy.Where(x => x.RefNo == refNo);
    if (!string.IsNullOrWhiteSpace(refType)) qy = qy.Where(x => x.RefType == refType);
    if (!string.IsNullOrWhiteSpace(storageCode)) qy = qy.Where(x => x.StorageCode == storageCode || x.StorageCodeTo == storageCode);
    var items = await qy.OrderBy(x => x.Vin).ThenBy(x => x.DTimeFrom).Take(1000).Select(x => new
    {
        x.Id, x.Vin, x.RefNo, x.RefType, x.StorageCode, x.StorageCodeTo, x.DTimeFrom, x.DTimeTo,
        x.FlagInDay, x.Remark, x.CreatedBy, x.CreatedDTime,
        stillInStorage = x.StorageCodeTo == null,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, inStorage = items.Count(i => i.stillInStorage), items });
}).RequireAuthorization();

// Ghi giao dịch kho theo LÔ — port đủ chuỗi guard của Sto_StorageTransaction_AddX.
app.MapPost("/api/storagetransactions", async (
    List<StorageTransactionDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "Danh sách giao dịch kho trống." });

    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    var prepared = new List<StorageTransaction>();
    var actor = user.Identity?.Name ?? "system";

    foreach (var r in rows)
    {
        var vin = (r.Vin ?? "").Trim();
        // Guard nguồn: các trường BẮT BUỘC. StorageCodeTo/DTimeTo KHÔNG bắt buộc —
        // nguồn có sẵn 2 guard cho chúng nhưng đã COMMENT (luật "port dòng active").
        if (vin.Length == 0) return Results.BadRequest(new { error = "Có dòng thiếu số khung (VIN)." });
        var refNo = (r.RefNo ?? "").Trim();
        if (refNo.Length == 0) return Results.BadRequest(new { error = $"VIN {vin}: chưa nhập số chứng từ (RefNo)." });
        var refType = (r.RefType ?? "").Trim().ToUpperInvariant();
        if (refType.Length == 0) return Results.BadRequest(new { error = $"VIN {vin}: chưa nhập loại chứng từ (RefType)." });
        if (!storageRefTypeNames.ContainsKey(refType))
            return Results.BadRequest(new { error = $"VIN {vin}: loại chứng từ không hợp lệ (chỉ PL/BBGN)." });
        var storageCode = (r.StorageCode ?? "").Trim();
        if (storageCode.Length == 0) return Results.BadRequest(new { error = $"VIN {vin}: chưa nhập mã kho." });
        if (r.DTimeFrom is null) return Results.BadRequest(new { error = $"VIN {vin}: chưa nhập thời điểm vào kho." });

        // Guard nguồn: TRÙNG VIN trong cùng một lô input.
        if (!seen.Add(vin)) return Results.BadRequest(new { error = $"VIN {vin} bị lặp trong cùng một lô." });

        // Guard nguồn (Sto_StorageTransaction_Check, FlagExist = Inactive): cặp (VIN, RefNo) đã tồn tại thì CẤM ghi lại.
        var dup = await db.StorageTransactions.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin && x.RefNo == refNo);
        if (dup) return Results.BadRequest(new { error = $"VIN {vin} đã có giao dịch kho với chứng từ {refNo}." });

        // 🔴 Luật FlagInDay (ảnh hưởng TIỀN): có giao dịch trước của chính VIN này rời kho ĐÚNG TRONG NGÀY
        // xe vào kho mới, và kho ĐẾN của giao dịch cũ chính là kho ĐI của giao dịch mới.
        var day = r.DTimeFrom.Value.Date;
        var inDay = await db.StorageTransactions.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin
            && x.StorageCodeTo == storageCode && x.DTimeTo != null
            && x.DTimeTo.Value.Date == day);

        prepared.Add(new StorageTransaction
        {
            OrgId = t.OrgId, Vin = vin, RefNo = refNo, RefType = refType, StorageCode = storageCode,
            StorageCodeTo = string.IsNullOrWhiteSpace(r.StorageCodeTo) ? null : r.StorageCodeTo!.Trim(),
            DTimeFrom = r.DTimeFrom.Value, DTimeTo = r.DTimeTo,
            FlagInDay = inDay ? "1" : "0", Remark = r.Remark, CreatedBy = actor,
        });
    }

    db.StorageTransactions.AddRange(prepared);
    await db.SaveChangesAsync();
    return Results.Ok(new { created = prepared.Count, inDay = prepared.Count(x => x.FlagInDay == "1"),
        items = prepared.Select(x => new { x.Id, x.Vin, x.RefNo, x.RefType, x.StorageCode, x.FlagInDay }) });
}).RequireAuthorization();

// Sinh giao dịch kho từ PACKING LIST — port vùng đã sửa ở bản máy 150 (CarVINUpdateMulti_New20181119).
// 🔴 Guard MỚI của bản 150: KHÔNG gọi hàm ghi khi không còn dòng nào cần ghi.
// Bản laptop gọi thẳng ⇒ ghi kho với lô RỖNG.
app.MapPost("/api/packinglists/{no}/storage-transactions", async (
    string no, List<PackingListStorageDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var pl = await db.PackingLists.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PLNo == no);
    if (pl is null) return Results.NotFound(new { no });
    if (rows is null) rows = new List<PackingListStorageDto>();

    var plVins = await db.PackingListVins.Where(x => x.OrgId == t.OrgId && x.PLId == pl.Id)
        .Select(x => x.Vin).ToListAsync();
    var vinSet = new HashSet<string>(plVins, StringComparer.OrdinalIgnoreCase);

    var actor = user.Identity?.Name ?? "system";
    var prepared = new List<StorageTransaction>();
    var skippedNoStoreDate = 0; var skippedExisted = 0; var skippedNotInPl = 0;

    foreach (var r in rows)
    {
        var vin = (r.Vin ?? "").Trim();
        if (vin.Length == 0 || !vinSet.Contains(vin)) { skippedNotInPl++; continue; }
        // Nguồn chỉ ghi cho VIN CÓ ngày nhập kho (StoreDate).
        if (r.StoreDate is null) { skippedNoStoreDate++; continue; }
        // Nguồn chỉ ghi khi CHƯA có giao dịch (VIN, RefNo) — có rồi thì bỏ qua, KHÔNG báo lỗi.
        if (await db.StorageTransactions.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin && x.RefNo == no))
        { skippedExisted++; continue; }
        if (prepared.Any(x => string.Equals(x.Vin, vin, StringComparison.OrdinalIgnoreCase))) { skippedExisted++; continue; }

        var day = r.StoreDate.Value.Date;
        var storageCode = (r.StorageCodeCurrent ?? "").Trim();
        var inDay = storageCode.Length > 0 && await db.StorageTransactions.AnyAsync(x => x.OrgId == t.OrgId
            && x.Vin == vin && x.StorageCodeTo == storageCode && x.DTimeTo != null && x.DTimeTo.Value.Date == day);

        prepared.Add(new StorageTransaction
        {
            OrgId = t.OrgId, Vin = vin, RefNo = no,
            RefType = "PL",                       // TConst.Sto_StorageTransaction_RefType.PL
            StorageCode = storageCode,
            StorageCodeTo = null,                 // nguồn ghi DBNull — xe mới vào kho, chưa xuất
            DTimeFrom = r.StoreDate.Value,
            DTimeTo = null, Remark = null,
            FlagInDay = inDay ? "1" : "0", CreatedBy = actor,
        });
    }

    // 🔴 Chính là guard bản 150: không có dòng nào thì KHÔNG ghi gì cả.
    if (prepared.Count == 0)
        return Results.Ok(new { plNo = no, created = 0, skippedNoStoreDate, skippedExisted, skippedNotInPl,
            note = "Không có VIN nào cần ghi giao dịch kho — không gọi ghi (guard bản máy 150)." });

    db.StorageTransactions.AddRange(prepared);
    await db.SaveChangesAsync();
    return Results.Ok(new { plNo = no, created = prepared.Count, skippedNoStoreDate, skippedExisted, skippedNotInPl,
        items = prepared.Select(x => new { x.Vin, x.StorageCode, x.DTimeFrom, x.FlagInDay }) });
}).RequireAuthorization();

app.MapGet("/api/packinglists/{no}/vins", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.PackingLists.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PLNo == no);
