// ===== Hợp đồng ngoại (ForeignContract/CO — port 1:1 FrmNewCO/FrmMngCO, DMSales.Foton) =====
app.MapGet("/api/foreigncontracts", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var query = db.ForeignContracts.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(c => c.ContractNo.Contains(q));
    var items = await query.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.ContractNo, c.CreatedAt,
        lines = db.ForeignContractLines.Count(l => l.OrgId == t.OrgId && l.ContractId == c.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/foreigncontracts", async (ForeignContractDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ContractNo)) return Results.BadRequest(new { error = "Cần số hợp đồng ngoại." });
    var no = dto.ContractNo.Trim();
    if (await db.ForeignContracts.AnyAsync(c => c.OrgId == t.OrgId && c.ContractNo == no))
        return Results.BadRequest(new { error = $"Số hợp đồng {no} đã tồn tại!" });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.LcTemp)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa chọn LC_Temp nào." });
    var dupe = lines.GroupBy(l => (l.RefNo?.Trim() ?? "") + "|" + l.LcTemp.Trim()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = "Dòng LC_Temp bị trùng!" });
    var c = new ForeignContract { OrgId = t.OrgId, ContractNo = no };
    db.ForeignContracts.Add(c); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.ForeignContractLines.Add(new ForeignContractLine { OrgId = t.OrgId, ContractId = c.Id, RefNo = l.RefNo?.Trim() ?? "", LcTemp = l.LcTemp.Trim() });
    await db.SaveChangesAsync();
    return Results.Ok(new { c.ContractNo, lines = lines.Count });
}).RequireAuthorization();

app.MapGet("/api/foreigncontracts/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var c = await db.ForeignContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ContractNo == no);
    if (c is null) return Results.NotFound(new { no });
    var lines = await db.ForeignContractLines.Where(l => l.OrgId == t.OrgId && l.ContractId == c.Id)
        .Select(l => new { l.RefNo, l.LcTemp }).ToListAsync();
    return Results.Ok(new { c.ContractNo, count = lines.Count, lines });
}).RequireAuthorization();

// ===== Đề nghị giấy tờ xe (CarDocRequest/DR — port 1:1 FrmNewDR/FrmMngDR, DMSales.Foton) =====
app.MapGet("/api/cardocrequests", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var query = db.CarDocRequests.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(r => r.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) query = query.Where(r => r.DealerCode == dealer);
    var items = await query.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.RequestNo, r.DealerCode, r.ReceivedPerson, r.ReceivedAddress, r.Status, r.CreatedAt, r.DoneAt,
        cars = db.CarDocRequestCars.Count(c => c.OrgId == t.OrgId && c.RequestId == r.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/cardocrequests", async (CarDocRequestDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ReceivedPerson)) return Results.BadRequest(new { error = "Cần người nhận." });
    if (string.IsNullOrWhiteSpace(dto.ReceivedAddress)) return Results.BadRequest(new { error = "Cần địa chỉ nhận." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.CarId)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 xe." });
    var dupe = cars.GroupBy(c => c.CarId.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"Xe {dupe.Key} bị trùng!" });
    var no = "DR" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new CarDocRequest { OrgId = t.OrgId, RequestNo = no, DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant(), ReceivedPerson = dto.ReceivedPerson.Trim(), ReceivedAddress = dto.ReceivedAddress.Trim(), Status = "Draft" };
    db.CarDocRequests.Add(r); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.CarDocRequestCars.Add(new CarDocRequestCar { OrgId = t.OrgId, RequestId = r.Id, CarId = c.CarId.Trim().ToUpperInvariant(), Remark = c.Remark, DeliveryStartDate = c.DeliveryStartDate });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RequestNo, r.ReceivedPerson, cars = cars.Count, status = r.Status });
}).RequireAuthorization();

app.MapGet("/api/cardocrequests/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.CarDocRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestNo == no);
    if (r is null) return Results.NotFound(new { no });
    var cars = await db.CarDocRequestCars.Where(c => c.OrgId == t.OrgId && c.RequestId == r.Id)
        .Select(c => new { c.CarId, c.Remark, c.DeliveryStartDate }).ToListAsync();
    return Results.Ok(new { r.RequestNo, r.Status, count = cars.Count, cars });
}).RequireAuthorization();

app.MapPost("/api/cardocrequests/{no}/complete", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.CarDocRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.Status != "Draft") return Results.BadRequest(new { error = "Đề nghị đã hoàn tất." });
    r.Status = "Done"; r.DoneAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RequestNo, status = r.Status });
}).RequireAuthorization();

// ===== 🔴 #209 TỪ CHỐI THEO DÒNG — `CarDocReqDtlReject_New20181119` (DataWH/Biz.HTC.WH.cs:83426) =====
// BƯỚC 3B: căn theo **MỐC HÀM** (laptop 83426 / máy 150 83431 — file này lệch offset, xem luật #208):
//   md5 vùng hàm `634c0032` KHỚP 2 máy.
// TWIN FILE: hàm còn ở `Biz.HTC.WH.Rel.20230823.cs:79543` — file KHÔNG có trong csproj ⇒ FILE CHẾT.
//
// ⚠️ ĐÃ BỎ `POST /api/cardocrequests/{no}/reject` (từ chối theo HEADER): nguồn **không có** lệnh nào từ chối
//    cả đề nghị. Cả họ lệnh đều ở mức DÒNG — `CarDocReqDtlApprove2` · `CarDocReqDtlCancel` ·
//    `CarDocReqDtlReject` · `Car_DocReqDtlDelete`; mức đề nghị chỉ có `CarDocReqListCancel`/`...ListDelete`.
//
// BA GUARD của nguồn, đúng thứ tự:
//  1. DÒNG phải đang **"A2"** (đã duyệt cấp 2) — `myCar_CheckCar_DocReqDtl(..., "A2")`;
//  2. ĐỀ NGHỊ phải thuộc **"P,A1,A2,F"** — `myCar_CheckCarDocReq(..., "P,A1,A2,F")`;
//  3. 🔴 **GUARD CHÉO Normal ↔ SPECIAL**: nếu đề nghị là loại `Normal` mà chính VIN đó còn nằm trong một
//     đề nghị **SPECIAL khác** còn sống (`DRListStatus not in ('R','C')` **và** `DRDtlStatus not in ('R','C')`)
//     ⇒ chặn với `CarDocReqDtlReject_ExistAnotherSpecial` — *muốn huỷ ĐN Normal phải huỷ ĐN Special trước*.
//
// Nguồn ghi trên DÒNG: `DRDtlStatus = Stage.Rejected ("R")` · `RejectDate` · `RejectBy` · `Remark` · `LogLU*`.
// ⚠️ NỢ: `CarDocRequest.Status` của port đang dùng từ vựng `Draft/Done/Rejected` — nguồn dùng `DRListStatus`
//    với bộ P/A1/A2/F/R/C. Đổi sẽ lan ra nhiều endpoint ⇒ để lượt riêng (giữ "một biến").
app.MapPost("/api/cardocrequests/{no}/cars/{carId}/reject", async (string no, string carId,
    SoRejectDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant(); carId = carId.Trim().ToUpperInvariant();
    var r = await db.CarDocRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestNo == no);
    if (r is null) return Results.NotFound(new { no });
    var line = await db.CarDocRequestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RequestId == r.Id && x.CarId == carId);
    if (line is null) return Results.NotFound(new { no, carId });

    // guard 1 — dòng phải đã duyệt cấp 2.
    if ((line.DRDtlStatus ?? "") != "A2")
        return Results.BadRequest(new { error = $"Dòng xe {carId} đang '{line.DRDtlStatus}' — chỉ từ chối dòng đã duyệt cấp 2 (A2)." });

    // guard 3 — Normal mà VIN còn trong một ĐN SPECIAL khác còn sống thì chặn.
    if (string.Equals(line.CarDocReqTypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
    {
        var conflict = await db.CarDocRequestCars
            .Where(x => x.OrgId == t.OrgId && x.CarId == carId && x.RequestId != r.Id
                     && x.DRDtlStatus != "R" && x.DRDtlStatus != "C"
                     && x.CarDocReqTypeCRR == "SPECIAL")
            .Select(x => x.RequestId).FirstOrDefaultAsync();
        if (conflict != 0)
            return Results.BadRequest(new { error = $"Xe {carId} còn nằm trong một đề nghị SPECIAL khác — phải huỷ đề nghị SPECIAL trước.", conflictRequestId = conflict });
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    line.DRDtlStatus = "R";                      // TConst.Stage.Rejected
    line.RejectDate = now; line.RejectBy = who;
    if (!string.IsNullOrWhiteSpace(dto?.Reason)) line.Remark = dto!.Reason!.Trim();   // nguồn ghi vào `Remark`
    line.LogLUDateTime = now; line.LogLUBy = who;

    await db.SaveChangesAsync();
    return Results.Ok(new { r.RequestNo, line.CarId, drDtlStatus = line.DRDtlStatus, line.RejectDate, line.RejectBy, line.Remark });
}).RequireAuthorization();

// ===== Lệnh giao xe cho đại lý (DeliveryOrder — port 1:1 FrmNewDO/FrmMngDO, DMSales.Foton) =====
app.MapGet("/api/deliveryorders", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.DeliveryOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    var items = await q.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.DoNo, o.DealerCode, o.Status, o.CreatedAt, o.DeliveredAt, o.Approved1At, o.Approved2At, o.RejectReason,
        o.DeliveryAddress, o.TransportCompanyName, o.TransportCompanyPhoneNo, o.TransportCompanyFaxNo, o.D4CDONo, o.D4CDOType,
        cars = db.DeliveryOrderCars.Count(c => c.OrgId == t.OrgId && c.DoId == o.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/deliveryorders", async (DeliveryOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần DealerCode." });
    var vins = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.Vin)).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
    var dupe = vins.GroupBy(c => c.Vin.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "DO" + DateTime.Now.ToString("yyMMddHHmmss");
    // 🔴 Nguồn `CarDeliveryOrderCreate_New20181119` (Biz.HTC.WH.cs:49868) tạo lệnh là "P" ngay.
    var o = new DeliveryOrder { OrgId = t.OrgId, DoNo = no, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), Status = "P" };
    db.DeliveryOrders.Add(o); await db.SaveChangesAsync();
    foreach (var c in vins)
        db.DeliveryOrderCars.Add(new DeliveryOrderCar { OrgId = t.OrgId, DoId = o.Id, Vin = c.Vin.Trim().ToUpperInvariant(), ModelCode = c.ModelCode, ColorCode = c.ColorCode, StorageCode = c.StorageCode, DeliveryExpectDate = c.DeliveryExpectDate });
    await db.SaveChangesAsync();
    return Results.Ok(new { o.DoNo, o.DealerCode, cars = vins.Count, status = o.Status });
}).RequireAuthorization();

// ===== #175 TỰ SINH LỆNH GIAO XE HÀNG LOẠT — `DMS40_Car_DeliveryOrder_CreateAuto_New20190125` =====
// Nguồn: `TERP.BizHTC/DMS40/zTemp.0.31.Car.cs:4601` (csproj 280).
// BƯỚC 3B: md5 CẢ FILE `9a2ec524` KHỚP 2 máy. TWIN: WS 32-bit và 64-bit gọi CÙNG bản `_New20190125`.
//
// 🔴 Đây là lệnh CUỐI CÙNG còn thiếu của cụm `Car_DeliveryOrder` — MiniHTC đã có
//    Create/Approve1/Approve2/DetailUpdate/DetailDelete, chỉ thiếu bản TỰ SINH.
//
// Nghiệp vụ: từ một **đợt tự sinh** (`D4CDONo`) đã gom sẵn danh sách đại lý (`Auto_Car_DeliveryOrder_Dealer`)
// và danh sách xe theo đại lý (`Auto_Car_DeliveryOrder_Car`), hàm **duyệt TỪNG đại lý** và với mỗi đại lý:
//   1. xin một số lệnh giao mới (`SequenceGetForDMS_MyGet`, `SequenceTypeDMS.CarDeliveryOrder`);
//   2. lấy địa chỉ giao = `Mst_Dealer.DealerAddress01` (KHÔNG nhập tay);
//   3. lấy xe của đại lý đó, mỗi dòng gồm `CarId` + `StorageCode` = **`Car_VIN.StorageCodeCurrent`**
//      (kho HIỆN TẠI của xe, không phải kho khai báo) + `DeliveryVIN`, còn `DeliveryOutDate`/`DeliveryRemark`
//      để **NULL** (điền ở bước giao thực tế);
//   4. gọi liền chuỗi **Create → Approve1 → Approve2** ⇒ lệnh giao ra đời **đã duyệt cấp 2 ngay**.
//
// 🔴 `D4CDOType` bắt buộc (`CreateAuto_InvalidD4CDOType`) và chỉ nhận **"RULE1"** hoặc **"RULE2"**
//    (`TConst.D4CDOType`). Khác biệt: RULE1 dùng `CarDeliveryOrderCreateX`, RULE2 dùng
//    `CarDeliveryOrderCreate_Rule2X`; **cả hai nhánh đều duyệt tiếp 1 rồi 2**.
// ⚠️ Nguồn gọi Approve2 với `dtimeTDate.AddSeconds(2)` — cố ý để mốc duyệt cấp 2 SAU cấp 1, tránh hai
//    mốc trùng giây. Đã giữ.
app.MapPost("/api/deliveryorders/create-auto", async (DoCreateAutoDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var batchNo = (dto.D4CDONo ?? "").Trim().ToUpperInvariant();
    if (batchNo.Length == 0) return Results.BadRequest(new { error = "Chưa nhập số đợt tự sinh (D4CDONo)." });
    var ruleType = (dto.D4CDOType ?? "").Trim().ToUpperInvariant();
    if (ruleType is not ("RULE1" or "RULE2"))
        return Results.BadRequest(new { error = "Loại tự sinh chỉ nhận RULE1 hoặc RULE2." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    // Danh sách đại lý của đợt.
    var dealerCodes = await db.AutoDoDealers.Where(x => x.OrgId == t.OrgId && x.D4CDONo == batchNo)
        .Select(x => x.DealerCode).Distinct().ToListAsync();
    if (dealerCodes.Count == 0)
        return Results.BadRequest(new { error = $"Đợt {batchNo} chưa có đại lý nào.", d4cdoNo = batchNo });

    var created = new List<object>();
    foreach (var dealerCode in dealerCodes)
    {
        // Địa chỉ giao lấy từ MASTER đại lý, không nhập tay.
        var dlr = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealerCode);
        if (dlr is null) return Results.BadRequest(new { error = $"Đại lý {dealerCode} không tồn tại.", dealerCode });

        var cars = await db.AutoDoCars.Where(x => x.OrgId == t.OrgId && x.D4CDONo == batchNo && x.DealerCode == dealerCode).ToListAsync();
        if (cars.Count == 0) continue;   // đại lý không có xe trong đợt thì bỏ qua

        var doNo = "DO" + now.ToString("yyMMddHHmmss") + created.Count.ToString("00");
        var o = new DeliveryOrder
        {
            OrgId = t.OrgId, DoNo = doNo, DealerCode = dealerCode,
            DeliveryAddress = dlr.DealerAddress01,
            // chuỗi Create → Approve1 → Approve2 chạy liền ⇒ trạng thái cuối là "A2"
            Status = "A2", CreatedAt = now,
            Approved1At = now, ApprovedBy1 = who,
            Approved2At = now.AddSeconds(2), ApprovedBy2 = who,   // nguồn cộng 2 giây, giữ nguyên
            // Ba cot don vi van chuyen: nguon truyen vao CarDeliveryOrderCreateX qua tham so.
            TransportCompanyName = dto.TransportCompanyName, TransportCompanyPhoneNo = dto.TransportCompanyPhoneNo,
            TransportCompanyFaxNo = dto.TransportCompanyFaxNo,
            D4CDONo = batchNo, D4CDOType = ruleType,
        };
        db.DeliveryOrders.Add(o);
        await db.SaveChangesAsync();

        foreach (var c in cars)
        {
            // `StorageCode` lấy từ `Car_VIN.StorageCodeCurrent` — kho HIỆN TẠI của xe.
            var vinRow = await db.CarVinMasters.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.VIN == c.VIN);
            db.DeliveryOrderCars.Add(new DeliveryOrderCar
            {
                OrgId = t.OrgId, DoId = o.Id, Vin = c.VIN, CarId = c.CarId,
                StorageCode = vinRow?.StorageCodeCurrent ?? c.StorageCode,
                DeliveryOutDate = null, DeliveryRemark = null,   // nguồn để NULL, điền ở bước giao thực tế
                ConfirmStatus = "P",
            });
        }
        await db.SaveChangesAsync();
        created.Add(new { doNo, dealerCode, cars = cars.Count });
    }

    return Results.Ok(new { d4cdoNo = batchNo, d4cdoType = ruleType, dealers = dealerCodes.Count,
        ordersCreated = created.Count, orders = created });
}).RequireAuthorization();

