app.MapPost("/api/campaigns", async (CampaignDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.CamNo) || string.IsNullOrWhiteSpace(dto.CamName))
        return Results.BadRequest(new { error = "Cần CamNo và CamName." });
    // #250: `FrmCampaignCreate.cs` kiểm `regex.IsMatch(txtCamNo.Text)` (bản đồ regex #249).
    if (HasSpecialChar(dto.CamNo.Trim()))
        return Results.BadRequest(new { error = "Mã chương trình không được phép chứa các ký tự đặc biệt" });
    if (dto.StartDate is null) return Results.BadRequest(new { error = "Cần StartDate." });
    if (dto.FinishDate is DateTime fd && fd < dto.StartDate.Value)
        return Results.BadRequest(new { error = "Ngày kết thúc phải ≥ ngày bắt đầu." });   // guard gốc FrmCampaignCreate
    var no = dto.CamNo.Trim().ToUpperInvariant();
    if (await db.Campaigns.AnyAsync(x => x.OrgId == t.OrgId && x.CamNo == no))
        return Results.BadRequest(new { error = $"Mã chiến dịch {no} đã tồn tại." });
    var c = new Campaign { OrgId = t.OrgId, CamNo = no, CamName = dto.CamName, StartDate = dto.StartDate.Value, FinishDate = dto.FinishDate, Content = dto.Content, Status = "1" };
    db.Campaigns.Add(c); await db.SaveChangesAsync();
    foreach (var ct in dto.Contacts ?? new())
        if (!string.IsNullOrWhiteSpace(ct.PlateNo) || !string.IsNullOrWhiteSpace(ct.CusName))
            db.CampaignContacts.Add(new CampaignContact
            {
                OrgId = t.OrgId, CampaignId = c.Id,
                PlateNo = ct.PlateNo, CusName = ct.CusName, Address = ct.Address,
                ContactStatus = "Pending",   // nguồn FrmCamp_CustomerList đặt Status="2" = "Chưa liên hệ"
                // GAP đã vá: 12 cột lưới FrmCamp_CustomerList trước đây bị bỏ sót
                CusID = ct.CusID, CarID = ct.CarID, DOB = ct.DOB,
                TradeMarkCode = ct.TradeMarkCode, ModelName = ct.ModelName,
                Mobile = ct.Mobile, Email = ct.Email,
                ContName = ct.ContName, ContTel = ct.ContTel, ContMobile = ct.ContMobile, ContEmail = ct.ContEmail,
                Remark = ct.Remark
            });
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CamNo, c.CamName, contacts = (dto.Contacts ?? new()).Count });
}).RequireAuthorization();

app.MapGet("/api/campaigns/{no}/contacts", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.Campaigns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CamNo == no);
    if (c is null) return Results.NotFound(new { no });
    var contacts = await db.CampaignContacts.Where(x => x.OrgId == t.OrgId && x.CampaignId == c.Id)
        .Select(x => new
        {
            x.Id, x.PlateNo, x.CusName, x.Address, x.ContactStatus,
            // GAP đã vá: 12 cột lưới gốc trước đây không được trả về
            x.CusID, x.CarID, x.DOB, x.TradeMarkCode, x.ModelName, x.Mobile, x.Email,
            x.ContName, x.ContTel, x.ContMobile, x.ContEmail, x.ContactDate, x.Remark
        }).ToListAsync();
    return Results.Ok(new { c.CamNo, count = contacts.Count, contacts });
}).RequireAuthorization();

app.MapPost("/api/campaigns/contacts/{id:long}/contacted", async (long id, AppDbContext db, ITenantContext t) =>
{
    var ct = await db.CampaignContacts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (ct is null) return Results.NotFound(new { id });
    ct.ContactStatus = "Contacted";
    await db.SaveChangesAsync();
    return Results.Ok(new { ct.Id, status = ct.ContactStatus });
}).RequireAuthorization();

// ===== Nhóm sửa chữa (Ser_GroupRepair — port 1:1 FrmGroupRepairCreate) =====
app.MapGet("/api/grouprepairs", async (AppDbContext db, ITenantContext t) =>
{
    var items = await db.GroupRepairs.Where(g => g.OrgId == t.OrgId).OrderBy(g => g.GroupRCode)
        .Select(g => new { g.GroupRCode, g.GroupRName, g.Note, g.Status, engineers = db.ServiceEngineers.Count(e => e.OrgId == t.OrgId && e.GroupRCode == g.GroupRCode) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/grouprepairs", async (GroupRepairDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.GroupRCode) || string.IsNullOrWhiteSpace(dto.GroupRName))
        return Results.BadRequest(new { error = "Cần GroupRCode và GroupRName." });
    // #249: `FrmGroupRepairCreate.cs:92` `regex.IsMatch(txtGroupRNo.Text)`
    if (HasSpecialChar(dto.GroupRCode.Trim()))
        return Results.BadRequest(new { error = "Mã nhóm sửa chữa không được phép chứa các ký tự đặc biệt" });
    var code = dto.GroupRCode.Trim().ToUpperInvariant();
    var g = await db.GroupRepairs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GroupRCode == code);
    if (g is null) { g = new GroupRepair { OrgId = t.OrgId, GroupRCode = code }; db.GroupRepairs.Add(g); }
    g.GroupRName = dto.GroupRName; g.Note = dto.Note; g.Status = dto.Status ?? "1"; g.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { g.GroupRCode, g.GroupRName });
}).RequireAuthorization();

// ===== Kỹ thuật viên (Ser_Engineer — port 1:1 FrmEngineerCreate) =====
app.MapGet("/api/engineers", async (AppDbContext db, ITenantContext t, string? group, string? q) =>
{
    var query = db.ServiceEngineers.Where(e => e.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(group)) query = query.Where(e => e.GroupRCode == group);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(e => e.EngineerName.Contains(q) || e.EngineerNo.Contains(q.ToUpper()));
    var items = await query.OrderBy(e => e.EngineerNo).Take(500)
        .Select(e => new { e.EngineerNo, e.EngineerName, e.GroupRCode, e.Note, e.Status, e.EngineerType, e.StartWorkDate, e.FinishWorkDate }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/engineers", async (EngineerDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.EngineerNo) || string.IsNullOrWhiteSpace(dto.EngineerName))
        return Results.BadRequest(new { error = "Cần EngineerNo và EngineerName." });
    var no = dto.EngineerNo.Trim().ToUpperInvariant();
    // 🔴 #250 PATTERN SAI: guard này dùng `[^a-zA-Z0-9_-]` — **THIẾU dấu chấm**. Pattern thật của nguồn
    //    (`FrmMdiBase.cs:46`) là `[^a-zA-Z0-9._-]` ⇒ mã có dấu chấm (vd `NV.01`) bị chặn NHẦM.
    //    Nay dùng helper chung `HasSpecialChar` để mọi nơi cùng một pattern.
    if (HasSpecialChar(no)) return Results.BadRequest(new { error = "Mã nhân viên không được nhập ký tự đặc biệt." });
    if (dto.StartWorkDate.HasValue && dto.FinishWorkDate.HasValue && dto.FinishWorkDate < dto.StartWorkDate)
        return Results.BadRequest(new { error = "Ngày bắt đầu làm việc không được lớn hơn ngày kết thúc làm việc." });
    var e = await db.ServiceEngineers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.EngineerNo == no);
    if (e is null) { e = new ServiceEngineer { OrgId = t.OrgId, EngineerNo = no }; db.ServiceEngineers.Add(e); }
    e.EngineerName = dto.EngineerName; e.GroupRCode = dto.GroupRCode?.Trim().ToUpperInvariant(); e.Note = dto.Note; e.Status = dto.Status ?? "1";
    e.EngineerType = dto.EngineerType; e.StartWorkDate = dto.StartWorkDate; e.FinishWorkDate = dto.FinishWorkDate; e.UpdatedAt = DateTime.Now;
    e.DealerCode = dto.DealerCode?.Trim().ToUpperInvariant();   // #338 §12
    await db.SaveChangesAsync();
    return Results.Ok(new { e.EngineerNo, e.EngineerName, e.GroupRCode, e.EngineerType, e.StartWorkDate, e.FinishWorkDate, e.DealerCode });
}).RequireAuthorization();

// ===== Yêu cầu báo giá phụ tùng (Req_PartPrice — port 1:1 FrmReq_PartPrice/Mng) =====
// ===== 🔴 #238 XIN BÁO GIÁ PHỤ TÙNG — parity `Req_PartPrice` + `Req_PartPriceDtl` (DMSCarSv/TST) =====
// Tầng ghi `Req_PartPriceService.cs:254` `Req_PartPrice_Save` gửi: ReqPartPriceNo · DealerCode · Description
//   + bộ dòng, kèm **HAI cờ**: `strFlagIsDelete` và `strFlagIsCheck` (cờ thứ hai chưa port — ghi nợ).
// BƯỚC 3B: POCO header md5 `35f57589` · POCO dòng `bf24ceeb` · Service `6fd0af13` — KHỚP 2 máy.
// 🔴 Dòng có `DMSPartCode` và `TSTPartCode` là HAI mã KHÁC NHAU — chính là mục đích của màn (ánh xạ mã).
app.MapGet("/api/reqpartprices", async (AppDbContext db, ITenantContext t, string? dms, string? tst) =>
{
    var q = db.ReqPartPrices.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dms)) q = q.Where(r => r.DMSStatus == dms);
    if (!string.IsNullOrWhiteSpace(tst)) q = q.Where(r => r.TSTStatus == tst);
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.ReqNo, r.DMSStatus, r.TSTStatus, r.CreatedAt, r.QuotedAt,
      // #238: 14 cột bổ sung của đầu phiếu
      r.DealerCode, r.Description, r.TSTReqPartPriceID, r.TSTSentDate, r.IsUpdatePrice,
      r.CreateBy, r.ApprDTime, r.ApprBy, r.FinishDTime, r.FinishBy, r.LUDTime, r.LUBy,
      r.LogLUDateTime, r.LogLUBy,
        lines = db.ReqPartPriceLines.Count(l => l.OrgId == t.OrgId && l.ReqId == r.Id),
        quotedTotal = db.ReqPartPriceLines.Where(l => l.OrgId == t.OrgId && l.ReqId == r.Id).Sum(l => (decimal?)(l.ReqQty * l.QuotedPrice)) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴 #241 SAVE BA VAI cho `Req_PartPrice_Save` + giải nợ cờ `FlagIsCheck` =====
// Nguồn `BizCarSv.SuggestPrice.cs:604-1180` (md5 8aafd84f, 4213 dòng — khớp 2 máy).
// Áp cùng khuôn đã port ở #240 cho đơn đặt PT, NHƯNG đã ĐỌC LẠI từng dòng — luật khác nhau:
//  · Guard trạng thái ở đây là `DMSReqPartPriceStatus` phải `Pending` (không phải OrderPartStatus).
//  · Nguồn còn `Mst_Dealer_CheckDB(Exist=Yes, Active)` ⇒ **đại lý phải tồn tại VÀ đang hoạt động**
//    (đơn đặt PT ở #240 KHÔNG có guard này — chớ suy sang nhau).
//  · Guard TỪNG DÒNG: `Mst_DeliveryForm_CheckDB(Exist=Yes, Active)` cho mỗi dòng, và `DMSPartCode` rỗng
//    ⇒ "Mã vật tư không được để trống!". Dòng mới đặt `ReqPartPriceDtlStatus = Pending`.
//
// 🔴 GIẢI NỢ `strFlagIsCheck` (ghi ở #238) — và nó là một cái bẫy TÊN BIẾN:
//     `bool bIsCheck = StringEqual(objFlagIsCheck, TConst.Flag.No);`   (:605)
//   ⇒ `bIsCheck` bật khi cờ = **"N"**, KHÔNG phải "Y". Tên biến ngược nghĩa giá trị.
//   Khối `if (!bIsDelete && bIsCheck)` (:1140) kiểm: có dòng nào mà `DMSPartCode` khớp
//   `TST_Mst_Part.TSTPartCode` **và `TSTPrice > 0`** thì ném
//   "Mã vật tư/Giá bán đã có trong hệ thống bạn kiểm tra lại thông tin!"
//   ⇒ nghiệp vụ: **không cho xin báo giá thứ ĐÃ CÓ GIÁ**.
app.MapPost("/api/reqpartprices", async (ReqPartPriceDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var isDelete = string.Equals(dto.FlagIsDelete, "Y", StringComparison.OrdinalIgnoreCase);
    var reqNoIn = (dto.ReqPartPriceNo ?? "").Trim().ToUpperInvariant();

    ReqPartPrice? existing = reqNoIn.Length == 0 ? null
        : await db.ReqPartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo == reqNoIn);

    // Xoá thứ chưa tồn tại ⇒ nguồn goto Done = THÀNH CÔNG im lặng (không 404).
    if (existing is null && isDelete)
        return Results.Ok(new { reqNo = reqNoIn, deleted = true, note = "YC không tồn tại — xoá coi như thành công (đúng nguồn)." });

    // Đã tồn tại ⇒ chỉ đụng được khi DMS còn "P".
    if (existing is not null && existing.DMSStatus != "P")
        return Results.BadRequest(new { error = "Chỉ sửa/xoá được YC báo giá đang Mới tạo.", dmsStatus = existing.DMSStatus });

    if (isDelete)
    {
        var oldL = await db.ReqPartPriceLines.Where(l => l.OrgId == t.OrgId && l.ReqId == existing!.Id).ToListAsync();
        db.ReqPartPriceLines.RemoveRange(oldL);
        db.ReqPartPrices.Remove(existing!);
        await db.SaveChangesAsync();
        return Results.Ok(new { reqNo = reqNoIn, deleted = true, removedLines = oldL.Count });
    }

    // Đại lý phải tồn tại + đang hoạt động (Mst_Dealer_CheckDB, :669).
    if (!string.IsNullOrWhiteSpace(dto.DealerCode))
    {
        var dlr = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dto.DealerCode!.Trim());
        if (dlr is null) return Results.BadRequest(new { error = $"Đại lý {dto.DealerCode} không tồn tại." });
        if (dlr.FlagActive != "1") return Results.BadRequest(new { error = $"Đại lý {dto.DealerCode} đang ngừng hoạt động." });
    }

    // ===== 🔴 #258 MÔ TẢ > 400 — `MSG_WARNING_REMARK` =====
    // `FrmReq_PartPriceMng.cs:846-853` kiểm `Req_PartPrice.Description` dài **> 400** khi sửa trên lưới.
    // Port cũ (#238/#241) KHÔNG có guard nào cho `Description` của YC báo giá ⇒ GAP, nay vá.
    //
    // ⚠️ MÂU THUẪN NGƯỠNG trong chính nguồn — đã kiểm cả 4 nơi dùng `MSG_WARNING_REMARK`:
    //   · `Req_PartPrice.Description`            : **400** (FrmReq_PartPriceMng:852)      ← port ở đây
    //   · `Ser_OrderComplain.Description`        : **400** ở lưới (FrmSer_OrderComplainMng:781)
    //     nhưng **256** ở form chi tiết (#233, `iLength`) ⇒ giữ **256** (chặt hơn, đã port đúng).
    //   · `Ser_SupplierPayment.Description`      : **400** ở lưới (FrmSer_SupplierPaymentMng:760)
    //     nhưng **1000** ở form nhập (#237) ⇒ giữ **1000** (đường nhập chính, đã port đúng).
    //   · `Ser_Order_PartDtl.Remark`             : **400** (FrmSer_SupplierPayment:1426)
    //   ⇒ nguồn có HAI đường nhập cho cùng cột với NGƯỠNG KHÁC NHAU; API là một cửa duy nhất nên giữ
    //     ngưỡng của **đường nhập chính**, không tự siết xuống mức của lưới sửa nhanh.
    if (!string.IsNullOrEmpty(dto.Description) && dto.Description!.Trim().Length > 400)
        return Results.BadRequest(new { error = "Ghi chú không được > 400 ký tự" });

    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode) && l.ReqQty > 0).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Lưới thông tin vật tư trống" });

    // ===== 🔴 #248 GUARD TỪNG DÒNG của FORM — `FrmReq_PartPrice_Detail.checkForm()` =====
    // Nguồn `Views/TST/FrmReq_PartPrice_Detail.cs:337-416` (md5 `f0de0f9a` — KHỚP 2 máy).
    // #241 mới port guard của BIZ (mã rỗng + hình thức giao hàng tồn tại). Form còn **5 guard nữa**
    // mà biz KHÔNG có — đúng lớp "hai tầng lệch nhau" (luật `C0-trecentesimusseptuagesimusseptimus`):
    //   · `DMSPartCode`: ký tự đặc biệt · **> 24** ký tự
    //   · `VieName`: **> 192** (chỉ kiểm khi CÓ nhập)
    //   · `VINCode`: ký tự đặc biệt · **> 24** (chỉ kiểm khi CÓ nhập)
    //   · `Remark`: **> 254** (chỉ kiểm khi CÓ nhập)
    // ⚠️ Ba ngưỡng 24/192/254 là của RIÊNG màn này — không suy sang màn khác
    //    (luật `C0-trecentesimussexagesimus`).
    // ⚠️ Lưới rỗng ⇒ "Lưới thông tin vật tư trống" (nguồn :415) — port cũ báo câu khác, nay giữ đúng nguồn
    //    ở guard đếm dòng phía trên.
    // Guard TỪNG DÒNG (nguồn quét vòng for, biz :872-905 + form :341-408).
    foreach (var l in lines)
    {
        if (string.IsNullOrWhiteSpace(l.PartCode))
            return Results.BadRequest(new { error = "Mã vật tư không được để trống!" });
        var pc = l.PartCode.Trim();
        if (HasSpecialChar(pc))
            return Results.BadRequest(new { error = "Mã vật tư không được phép chứa các ký tự đặc biệt", partCode = pc });
        if (pc.Length > 24)
            return Results.BadRequest(new { error = "Mã vật tư không được > 24 ký tự", partCode = pc });
        if (!string.IsNullOrWhiteSpace(l.PartName) && l.PartName!.Trim().Length > 192)
            return Results.BadRequest(new { error = "Tên vật tư không được > 192 ký tự", partCode = pc });
        if (!string.IsNullOrWhiteSpace(l.VINCode))
        {
            var vin = l.VINCode!.Trim();
            if (HasSpecialChar(vin))
                return Results.BadRequest(new { error = "Số VIN không được phép chứa các ký tự đặc biệt", partCode = pc });
            if (vin.Length > 24)
                return Results.BadRequest(new { error = "VIN không được > 24 ký tự", partCode = pc });
        }
        if (!string.IsNullOrWhiteSpace(l.Remark) && l.Remark!.Trim().Length > 254)
            return Results.BadRequest(new { error = "Ghi chú không được > 254 ký tự", partCode = pc });

        // 🔴 Form BẮT BUỘC hình thức đặt hàng ở TỪNG DÒNG (:377-381) — biz chỉ kiểm khi có giá trị.
        if (string.IsNullOrWhiteSpace(l.DeliveryFormCode))
            return Results.BadRequest(new { error = "Chưa chọn hình thức đặt hàng", partCode = pc });
        if (!string.IsNullOrWhiteSpace(l.DeliveryFormCode))
        {
            var dfc = l.DeliveryFormCode!.Trim().ToUpperInvariant();
            var df = await db.Masters.FirstOrDefaultAsync(m => m.OrgId == t.OrgId && m.Category == "DeliveryForm" && m.Code == dfc);
            if (df is null || df.Status != "1")
                return Results.BadRequest(new { error = $"Hình thức giao hàng {dfc} không tồn tại hoặc đã ngừng.", partCode = l.PartCode });
        }
    }

    // 🔴 Cờ FlagIsCheck: bật kiểm khi giá trị = "N" (đúng nguồn, tên biến ngược nghĩa).
    if (string.Equals(dto.FlagIsCheck, "N", StringComparison.OrdinalIgnoreCase))
    {
        var codes = lines.Select(l => l.PartCode.Trim().ToUpperInvariant()).ToList();
        var priced = await db.TstParts
            .Where(p => p.OrgId == t.OrgId && codes.Contains(p.TSTPartCode) && p.TSTPrice > 0)
            .Select(p => new { p.TSTPartCode, p.TSTPrice })
            .FirstOrDefaultAsync();
        if (priced is not null)
            return Results.BadRequest(new
            {
                error = "Mã vật tư/Giá bán đã có trong hệ thống bạn kiểm tra lại thông tin!",
                dmsPartCode = priced.TSTPartCode, tstPrice = priced.TSTPrice,
            });
    }

    var no = existing?.ReqNo ?? (reqNoIn.Length > 0 ? reqNoIn : "RQ" + DateTime.Now.ToString("yyMMddHHmmss"));
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var r = new ReqPartPrice
    {
        OrgId = t.OrgId, ReqNo = no,
        DMSStatus = "P", TSTStatus = "1",   // nguồn set TST=1 (Chờ duyệt) ngay khi tạo
        // #238: 3 trường mà `Req_PartPrice_Save` gửi lên + vết ghi
        DealerCode = dto.DealerCode, Description = dto.Description,
        CreateBy = who, LogLUDateTime = DateTime.Now, LogLUBy = who,
    };
    if (existing is not null)
    {
        // SỬA: giữ NGUYÊN CreateDTime/CreateBy của bản ghi cũ (:656-657), thay trọn bộ dòng.
        r.Id = existing.Id;
        r.CreatedAt = existing.CreatedAt;
        r.CreateBy = existing.CreateBy;
        db.Entry(existing).CurrentValues.SetValues(r);
        var oldL = await db.ReqPartPriceLines.Where(l => l.OrgId == t.OrgId && l.ReqId == existing.Id).ToListAsync();
        db.ReqPartPriceLines.RemoveRange(oldL);
        await db.SaveChangesAsync();
        r = existing;
    }
    else { db.ReqPartPrices.Add(r); await db.SaveChangesAsync(); }
    foreach (var l in lines)
        db.ReqPartPriceLines.Add(new ReqPartPriceLine
        {
            OrgId = t.OrgId, ReqId = r.Id, ReqPartPriceNo = no,
            PartCode = l.PartCode.Trim().ToUpperInvariant(), PartName = l.PartName,
            ReqQty = l.ReqQty, QuotedPrice = 0,
            // #238: 6 cột bổ sung của dòng. ⚠️ `TSTPartCode`/`DateEffect` do phía TST điền khi báo giá,
            //    KHÔNG nhận lúc tạo (giống `QuotedPrice` vốn để 0).
            DeliveryFormCode = l.DeliveryFormCode, VINCode = l.VINCode, Remark = l.Remark,
            ReqPartPriceDtlStatus = "P",
            LogLUDateTime = DateTime.Now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReqNo, lines = lines.Count, dmsStatus = r.DMSStatus });
}).RequireAuthorization();

app.MapGet("/api/reqpartprices/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.ReqPartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo == no);
    if (r is null) return Results.NotFound(new { no });
    var lines = await db.ReqPartPriceLines.Where(l => l.OrgId == t.OrgId && l.ReqId == r.Id)
        .Select(l => new { l.PartCode, l.PartName, l.ReqQty, l.QuotedPrice,
                           // #238: 8 cột bổ sung của dòng
                           l.ReqPartPriceNo, l.TSTPartCode, l.DeliveryFormCode, l.VINCode,
                           l.DateEffect, l.Remark, l.ReqPartPriceDtlStatus,
                           l.LogLUDateTime, l.LogLUBy,
                           lineTotal = l.ReqQty * l.QuotedPrice }).ToListAsync();
    return Results.Ok(new { r.ReqNo, r.DMSStatus, r.TSTStatus, count = lines.Count, lines, quotedTotal = lines.Sum(x => x.lineTotal) });
}).RequireAuthorization();

// DMS gửi (P→A)
// 🔴 Trạng thái YC báo giá PT theo ĐÚNG nguồn. Mã TST là SỐ NHẢY, **KHÔNG có mã 3**.
// ⚠️ Nguồn dùng lớp hằng `DMSSuggestPriceStatus`/`TSTSuggestPriceStatus` cho chính Req_PartPrice
//    (trùng nội dung với `DMS/TSTReqPartPriceStatus`) — hai bộ hằng song trùng, KHÔNG phải màn riêng.
var reqPartPriceTstNames = new Dictionary<string, string>
{
    ["1"] = "Chờ duyệt",
    ["2"] = "Đã duyệt, chờ hoàn thiện",
    ["4"] = "Đã hoàn thiện",
};
var reqPartPriceDmsNames = new Dictionary<string, string>
{
    ["P"] = "Mới tạo", ["A"] = "Đã gửi", ["F"] = "Hoàn thiện", ["R"] = "Từ chối",
};

// Ánh xạ giá trị port CŨ → mã nguồn, giữ dữ liệu đã tạo đọc được.
var reqPartPriceLegacyTstMap = new Dictionary<string, string>
{
    ["Pending"] = "1", ["Quoted"] = "2", ["Finished"] = "4",
};

app.MapGet("/api/reqpartprices/statuses", () => Results.Ok(new
{
    dmsStatuses = reqPartPriceDmsNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    tstStatuses = reqPartPriceTstNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    legacyTstMap = reqPartPriceLegacyTstMap.Select(kv => new { legacy = kv.Key, code = kv.Value }),
    note = "Mã TST nhảy số 1/2/4 — KHÔNG có mã 3. DMS có nhánh R (từ chối)."
})).RequireAuthorization();

app.MapPost("/api/reqpartprices/{no}/send", async (string no, SentTstDto? dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.ReqPartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.DMSStatus != "P") return Results.BadRequest(new { error = "Chỉ gửi YC Mới tạo." });

    // ===== 🔴 #239 GỬI SANG TST — `Req_PartPrice_SentTST` (BizCarSv.SuggestPrice.cs:1220) =====
    // BƯỚC 3B: `BizCarSv.SuggestPrice.cs` md5 `8aafd84f` (4213 dòng) — KHỚP 2 máy.
    //
    // 🔴 "Gửi TST" KHÔNG phải đổi một cờ. Nguồn làm ba việc, port cũ chỉ có việc thứ ba:
    //  1. **Gọi API Bravo thật**: `GetToken` → `CallBravo(url, token, guid, json)` với
    //     `JsonConvert.SerializeObject(objRQ_SuggestPriceHdr)`.
    //  2. **Chỉ khi phản hồi `Status == "OK"`** mới ghi. Phản hồi rỗng hoặc khác "OK" ⇒ ném
    //     `Req_PartPrice_SentTST_SyncFail` và **KHÔNG đổi trạng thái** (rollback cả transaction).
    //  3. Update đặt **BẢY cột cùng một mốc `dtimeSys`** (:1436-1446), không phải một:
    //     `DMSReqPartPriceStatus` · `ApprDTime` · `ApprBy` · `LUDTime` · `LUBy` · `LogLUDTime` · `LogLUBy`.
    //  ⚠️ Ghi **BA DB**: `_dbMain` + `_dbWH` + `_dbDealer` (khi có) — nợ dual-write fleet-wide, chưa port.
    //  ⚠️ NGHI VẤN đã ghi nợ: SQL dùng cột `t.LogLUDTime` trong khi POCO khai `LogLUDateTime`.
    //     Hai tên khác nhau — KHÔNG tự chọn bên nào, cần soi schema DB thật.
    //
    // Ở đây chưa có tầng gọi Bravo (nợ chung của MiniHTC: lớp tích hợp ngoài), nên port ĐÚNG phần ghi
    // và giữ nguyên **thứ tự phụ thuộc**: chỉ ghi khi "đồng bộ thành công". Client báo kết quả đồng bộ
    // qua `syncStatus`; mặc định "OK" để đường gọi cũ không vỡ.
    var syncOk = string.IsNullOrWhiteSpace(dto?.SyncStatus) || string.Equals(dto!.SyncStatus, "OK", StringComparison.OrdinalIgnoreCase);
    if (!syncOk)
        return Results.BadRequest(new
        {
            error = "Đồng bộ sang TST thất bại — không đổi trạng thái.",   // ` Req_PartPrice_SentTST_SyncFail
            syncStatus = dto?.SyncStatus, description = dto?.SyncDescription,
        });

    var whoSend = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var nowSend = DateTime.Now;              // nguồn dùng CÙNG MỘT dtimeSys cho cả 7 cột
    r.DMSStatus = "A";                       // TConst.DMSReqPartPriceStatus.Approved
    r.ApprDTime = nowSend; r.ApprBy = whoSend;
    r.LUDTime = nowSend; r.LUBy = whoSend;
    r.LogLUDateTime = nowSend; r.LogLUBy = whoSend;
    r.TSTSentDate = nowSend;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReqNo, dmsStatus = r.DMSStatus, r.ApprDTime, r.ApprBy, r.LUDTime, r.LUBy,
                            r.LogLUDateTime, r.LogLUBy, r.TSTSentDate });
}).RequireAuthorization();

// TST báo giá (điền QuotedPrice từng dòng) → TSTStatus "2" (đã duyệt, chờ hoàn thiện).
app.MapPost("/api/reqpartprices/{no}/quote", async (string no, ReqQuoteDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.ReqPartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.DMSStatus != "A") return Results.BadRequest(new { error = "DMS chưa gửi YC." });
    if (r.DMSStatus == "R") return Results.BadRequest(new { error = "YC đã bị từ chối." });
    var tstCurrent = reqPartPriceLegacyTstMap.TryGetValue(r.TSTStatus, out var mappedTst) ? mappedTst : r.TSTStatus;
    if (tstCurrent == "4") return Results.BadRequest(new { error = "Đã hoàn thiện." });
    var quotes = (dto.Quotes ?? new()).ToDictionary(x => (x.PartCode ?? "").Trim().ToUpperInvariant(), x => x.QuotedPrice);
    var lines = await db.ReqPartPriceLines.Where(l => l.OrgId == t.OrgId && l.ReqId == r.Id).ToListAsync();
    int filled = 0;
    foreach (var l in lines)
        if (quotes.TryGetValue(l.PartCode, out var price)) { l.QuotedPrice = price; filled++; }
    r.TSTStatus = "2"; r.QuotedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReqNo, tstStatus = r.TSTStatus, tstStatusName = reqPartPriceTstNames["2"], filled });
}).RequireAuthorization();

// DMS chấp nhận → TST "4" (đã hoàn thiện) + DMS "F".
app.MapPost("/api/reqpartprices/{no}/finish", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.ReqPartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo == no);
    if (r is null) return Results.NotFound(new { no });
    var tstCurrent = reqPartPriceLegacyTstMap.TryGetValue(r.TSTStatus, out var mappedFinish) ? mappedFinish : r.TSTStatus;
    if (tstCurrent != "2") return Results.BadRequest(new { error = "Chưa được báo giá (TST phải ở trạng thái 2)." });
    r.TSTStatus = "4"; r.DMSStatus = "F";
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReqNo, dmsStatus = r.DMSStatus, tstStatus = r.TSTStatus });
}).RequireAuthorization();

// 🔴 TỪ CHỐI yêu cầu báo giá (DMSStatus "R") — nhánh port cũ thiếu hẳn.
app.MapPost("/api/reqpartprices/{no}/reject", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.ReqPartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.DMSStatus == "F") return Results.BadRequest(new { error = "YC đã hoàn thiện, không từ chối được." });
    if (r.DMSStatus == "R") return Results.BadRequest(new { error = "YC đã bị từ chối." });
    r.DMSStatus = "R";
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReqNo, dmsStatus = r.DMSStatus, dmsStatusName = reqPartPriceDmsNames["R"] });
}).RequireAuthorization();

// ===== Thanh toán nhà cung cấp (Ser_SupplierPayment — port 1:1 FrmSer_SupplierPayment) =====
// ===== 🔴 #244 TRA PHỤ TÙNG ĐỂ LẬP PHIẾU THANH TOÁN — `Ser_Mst_Part_GetForSupplierPayment` =====
// Màn: `Views/TST/FrmSer_SupplierPayment_Part_Search.cs` (471 dòng, DMSCarSv/TST) — chọn PT **đã nhập kho**
//   để đưa vào phiếu thanh toán NCC. Biz `BizCarSv.Inventory.StockOut.cs:14890` (md5 8e73ba77, khớp 2 máy).
//
// Nguồn join `Ser_Inv_StockIn` × `Ser_Inv_StockInDetail` × `Ser_MST_Part` và:
//  🔴 `and si.Status = '3'` — **CHỈ phiếu nhập ĐÃ KẾT THÚC**. Đây là hard-code định nghĩa màn,
//     KHÔNG phải bộ lọc tuỳ chọn: chưa kết thúc nhập thì chưa có gì để trả tiền.
//     (mã "3" = Kết thúc theo `TConst.Ser_Inv_StockIn` — xem chú thích `PartStockIn.Status`.)
//  · Lọc CHÍNH XÁC: `DealerCode` · `SupplierID` · khoảng `StockInDate`.
//  · Lọc CHỨA: `PartCode` · `StockInNo` (nguồn nối chuỗi `like '%…%'`).
//  ⚠️ Form nối `" 23:59:59"` vào ngày ĐẾN ⇒ bao TRỌN ngày; bản port dùng `< ngày+1` cho tương đương.
//  ⚠️ Nguồn chạy trên `_dbDealer` (DB đại lý), không phải DB Main — nợ dual-DB fleet-wide.
//  ⚠️ Nguồn nối chuỗi thẳng vào SQL (`like '%" + pattern + "%'`) ⇒ **có bề mặt SQL injection**;
//     bản port dùng LINQ tham số hoá, CỐ Ý không port lỗi này.
app.MapGet("/api/supplierpayments/parts-search", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? supplierId, string? partCode, string? stockInNo,
    DateTime? stockInDateFrom, DateTime? stockInDateTo) =>
{
    var qy = from si in db.PartStockIns.Where(x => x.OrgId == t.OrgId && x.Status == "3")
             join l in db.PartStockInLines.Where(x => x.OrgId == t.OrgId) on si.Id equals l.StockInId
             select new { si, l };

    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.si.DealerCode == dealerCode!.Trim());
    if (!string.IsNullOrWhiteSpace(supplierId)) qy = qy.Where(x => x.si.SupplierID == supplierId!.Trim());
    if (stockInDateFrom is not null) qy = qy.Where(x => x.si.StockInDate >= stockInDateFrom);
    // ngày ĐẾN bao trọn ngày (nguồn nối " 23:59:59")
    if (stockInDateTo is not null) qy = qy.Where(x => x.si.StockInDate < stockInDateTo.Value.Date.AddDays(1));
    if (!string.IsNullOrWhiteSpace(partCode))
        qy = qy.Where(x => x.l.PartCode.ToLower().Contains(partCode!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(stockInNo))
        qy = qy.Where(x => x.si.StockInNo.ToLower().Contains(stockInNo!.Trim().ToLower()));

    var items = await qy.OrderByDescending(x => x.si.StockInDate).ThenBy(x => x.l.PartCode).Take(1000)
        .Select(x => new
        {
            x.si.DealerCode,
            x.l.PartCode, vieName = x.l.PartName, x.l.Unit,
            x.l.Quantity, x.l.Price, x.l.VAT,
            x.si.StockInNo, x.si.StockInDate, x.si.TSTRequestNo, x.si.BillNo,
        }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        note = "Chỉ phiếu nhập Status=3 (Kết thúc) — hard-code của nguồn, không phải bộ lọc.",
    });
}).RequireAuthorization();

// ===== 🔴 #237 THANH TOÁN NCC — parity `Ser_SupplierPayment` + `Ser_SupplierPaymentDtl` (DMSCarSv/TST) =====
// Màn ghi: `Views/TST/FrmSer_SupplierPayment.cs` (:723 Save, :838 Appr); màn tra `FrmSer_SupplierPaymentMng.cs`.
// BƯỚC 3B: Service md5 `b3a175a1` · POCO header `0c9f1037` · POCO dòng `84053d99` — KHỚP 2 máy.
//
// 🔴 `Ser_SupplierPayment_Save` (:140) gửi **8 trường**: SupplierPaymentNo · DealerCode · SupplierID ·
//    Address · PaymentType · TSTRequestNo · OrderPartNo · Description (+ bộ dòng + FlagIsDelete).
// ⚠️ BẪY COMMENT: dòng truyền `PaymentDTime` bị **comment cố ý** ở service (:167) dù form CÓ gán nó vào
//    object (:691) ⇒ **ngày thanh toán KHÔNG do client gửi**, server tự đặt. Không nhận từ DTO.
// ⚠️ `Ser_SupplierPayment_Appr` (:181) chỉ gửi **SupplierPaymentNo** — KHÁC hẳn `Ser_Order_Part_Appr` (#234)
//    vốn gửi 7 trường. Khẳng định: phải ĐO chữ ký từng hàm, không suy từ màn anh em.
// ⚠️ Nguồn **không có** cột tổng tiền ở đầu phiếu; `Amount` của bản port là tổng tính từ dòng (ghi rõ để
//    lượt sau không đi tìm cột tương ứng — bài học #236).
var supplierPaymentTypeNames = new Dictionary<string, string>
{
    ["PMT"] = "Thanh toán", ["PMC"] = "Cấn trừ", ["PMA"] = "Điều chỉnh",
};

app.MapGet("/api/supplierpayments/types", () => Results.Ok(new
{
    paymentTypes = supplierPaymentTypeNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    statuses = new[] { new { code = "P", name = "Mới tạo" }, new { code = "A", name = "Đã duyệt" } },
    note = "TConst.PaymentType (Const.Main.cs:100) + TConst.SupplierPaymentStatus (:603).",
})).RequireAuthorization();

app.MapGet("/api/supplierpayments", async (AppDbContext db, ITenantContext t, string? status, string? supplier,
    string? dealerCode, string? paymentType) =>
{
    var q = db.SupplierPayments.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.Status == status);
    if (!string.IsNullOrWhiteSpace(supplier)) q = q.Where(p => p.SupplierCode == supplier);
    if (!string.IsNullOrWhiteSpace(dealerCode)) q = q.Where(p => p.DealerCode == dealerCode!.Trim());
    if (!string.IsNullOrWhiteSpace(paymentType)) q = q.Where(p => p.PaymentType == paymentType!.Trim().ToUpperInvariant());
    var items = await q.OrderByDescending(p => p.Id).Take(500).Select(p => new
    { p.PaymentNo, p.SupplierCode, p.OrderPartNo, p.DealerCode, p.Amount, p.PaymentDate, p.Status, p.ApprovedAt,
      // #237: 10 cột bổ sung của đầu phiếu
      p.SupplierID, p.Address, p.TSTRequestNo, p.PaymentType, p.Description,
      p.PaymentBy, p.CreateBy, p.ApprBy, p.LogLUDTime, p.LogLUBy,
      lines = db.SupplierPaymentLines.Count(l => l.OrgId == t.OrgId && l.PaymentNo == p.PaymentNo) }).ToListAsync();
    return Results.Ok(new { count = items.Count, total = items.Sum(x => x.Amount), approved = items.Where(x => x.Status == "A").Sum(x => x.Amount), items });
}).RequireAuthorization();

// ===== 🔴 #243 SAVE BA VAI cho `Ser_SupplierPayment_Save` + SỬA lỗi `PaymentDate` của #237 =====
// Nguồn `BizCarSv.Inventory.StockOut.cs:15633` → hàm làm việc thật `Ser_SupplierPayment_SaveX` (:15782).
// BƯỚC 3B: md5 `8e73ba77` — KHỚP 2 máy.
//
// Ba vai giống #240/#241/#242, guard trạng thái ở đây là `SupplierPaymentStatus` phải `Pending`.
// 🔴 KHÁC BIỆT phải ghi: hàm này **KHÔNG có `Mst_Dealer_CheckDB`** — giống đơn đặt PT (#240),
//    khác YC báo giá (#241) và khiếu nại (#242) vốn bắt đại lý phải tồn tại + đang hoạt động.
//    Bốn hàm cùng khuôn, hai hàm có guard đại lý, hai hàm không ⇒ tuyệt đối không suy sang nhau.
//
// 🔴 SỬA LỖI CỦA #237: bảng `MyBuildDBDT_Common` của nguồn (:15925-15935) ghi
//      `null, // PaymentDTime`   và   `null, // PaymentBy`
//    ⇒ **lúc lưu, ngày/người thanh toán để RỖNG**. #237 tôi đặt `PaymentDate = DateTime.Now` với lý do
//    "server tự đặt" — SAI: server cũng KHÔNG đặt. Và `Ser_SupplierPayment_Appr` (:16578) chỉ ghi
//    `ApprDTime`/`ApprBy`/`SupplierPaymentStatus=Approved`, **cũng không** chạm hai cột đó.
//    ⇒ Trong vùng đã đọc, `PaymentDTime`/`PaymentBy` **không được ghi ở đâu cả** — để NULL và ghi nợ,
//      KHÔNG tự đoán mốc (luật `C0-trecentesimussexagesimusquintus`).
app.MapPost("/api/supplierpayments", async (SupplierPaymentDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var isDeleteP = string.Equals(dto.FlagIsDelete, "Y", StringComparison.OrdinalIgnoreCase);
    var payNoIn = (dto.SupplierPaymentNo ?? "").Trim().ToUpperInvariant();

    SupplierPayment? existingP = payNoIn.Length == 0 ? null
        : await db.SupplierPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PaymentNo == payNoIn);

    if (existingP is null && isDeleteP)
        return Results.Ok(new { paymentNo = payNoIn, deleted = true, note = "Phiếu không tồn tại — xoá coi như thành công (đúng nguồn)." });

    if (existingP is not null && existingP.Status != "P")
        return Results.BadRequest(new { error = "Chỉ sửa/xoá được phiếu thanh toán đang Mới tạo.", status = existingP.Status });

    if (isDeleteP)
    {
        var oldPl = await db.SupplierPaymentLines.Where(l => l.OrgId == t.OrgId && l.PaymentNo == payNoIn).ToListAsync();
        db.SupplierPaymentLines.RemoveRange(oldPl);
        db.SupplierPayments.Remove(existingP!);
        await db.SaveChangesAsync();
        return Results.Ok(new { paymentNo = payNoIn, deleted = true, removedLines = oldPl.Count });
    }

    // Guard của nguồn (FrmSer_SupplierPayment.cs:664/:740) — giữ nguyên thông điệp.
    if (string.IsNullOrWhiteSpace(dto.SupplierCode)) return Results.BadRequest(new { error = "Chưa chọn nhà cung cấp" });
    // :746 — ngưỡng 1000, KHÁC 256 của khiếu nại (#233) và 200 của địa điểm giao hàng (#232).
    if ((dto.Description ?? "").Length > 1000) return Results.BadRequest(new { error = "Mô tả không được vượt quá 1000 ký tự" });
    if (!string.IsNullOrWhiteSpace(dto.PaymentType) && !supplierPaymentTypeNames.ContainsKey(dto.PaymentType!.Trim().ToUpperInvariant()))
        return Results.BadRequest(new { error = "Loại phiếu hợp lệ: PMT (Thanh toán) · PMC (Cấn trừ) · PMA (Điều chỉnh)." });
    decimal amount = dto.Amount;
    string? orderNo = null;
    if (!string.IsNullOrWhiteSpace(dto.OrderPartNo))
    {
        orderNo = dto.OrderPartNo.Trim().ToUpperInvariant();
        var order = await db.OrderParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == orderNo);
        if (order is null) return Results.BadRequest(new { error = $"Không tìm thấy đơn đặt {orderNo}." });
        // 🔴 #237 GUARD CHẾT CÂM thứ hai (cùng nguyên nhân): chặn MỌI phiếu thanh toán vì không đơn nào
        //    còn mang giá trị "Finished" sau #234.
        if (order.OrderPartStatus != "F") return Results.BadRequest(new { error = "Chỉ thanh toán đơn đã Hoàn thành." });
        // amount mặc định = tổng đơn nếu không nhập
        if (amount <= 0)
            amount = await db.OrderPartLines.Where(l => l.OrgId == t.OrgId && l.OrderPartId == order.Id).SumAsync(l => (decimal?)(l.OrderQty * l.Price)) ?? 0;
    }
    // Có chi tiết thì TIỀN PHIẾU = TỔNG CÁC DÒNG, đúng nguồn (Ser_SupplierPaymentDtl):
    //   Amount dòng = QtyPay * Price * (1 + VAT*0.01)
    // ⚠️ QtyPay là SỐ LƯỢNG THANH TOÁN, khác số lượng xuất kho — một lần xuất có thể trả nhiều đợt.
    var paymentLines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode)).ToList();
    // ===== 🔴 #260 BỐN GUARD cho `QtyPay` — `FrmInvCode_Location.cs:314-362` =====
    // BƯỚC 3B: md5 `b5ed70db` — KHỚP 2 máy. Thứ tự và thông điệp giữ NGUYÊN của nguồn:
    //  1. rỗng            ⇒ `MSG_WARNING_EMPTY_VALUE` = "Không được trống"
    //  2. không phải số   ⇒ `MSG_WARNING_NOT_NUMERIC` = "Không phải là số"
    //  3. `<= 0`          ⇒ "Số lượng trả phải > 0"
    //  4. 🔴 `> InStockQuantity` ⇒ "Số lượng trả phải <= Số lượng có thể trả"
    // ⇒ #237 chỉ có guard 3 (và thông điệp tự chế). Guard 4 — **không cho trả quá tồn theo VỊ TRÍ** —
    //   bị thiếu hoàn toàn; đây là chốt chặn tiền, thiếu thì trả vượt số hàng thực có.
    // ⚠️ Guard 4 so với `InStockQuantity` (tồn theo VỊ TRÍ), **KHÔNG** phải `QtyInventory` (tồn tổng).
    // ⚠️ Guard 1/2 ở nguồn là ràng buộc Ô LƯỚI (chuỗi); qua API kiểu đã là `decimal` nên chỉ còn nghĩa
    //   khi client bỏ trống ⇒ kiểm `null` ở DTO là đủ, giữ nguyên thông điệp.
    foreach (var l in paymentLines)
    {
        if (l.QtyPay <= 0)
            return Results.BadRequest(new { error = "Số lượng trả phải > 0", partCode = l.PartCode });
        if (l.InStockQuantity is not null && l.QtyPay > l.InStockQuantity)
            return Results.BadRequest(new
            {
                error = "Số lượng trả phải <= Số lượng có thể trả",
                partCode = l.PartCode, qtyPay = l.QtyPay, inStockQuantity = l.InStockQuantity,
            });
    }
    if (paymentLines.Count > 0) amount = paymentLines.Sum(l => l.QtyPay * l.Price * (1 + l.Vat / 100m));

    if (amount <= 0) return Results.BadRequest(new { error = "Cần số tiền > 0." });
    var no = existingP?.PaymentNo ?? (payNoIn.Length > 0 ? payNoIn : "SP" + DateTime.Now.ToString("yyMMddHHmmss"));
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var p = new SupplierPayment
    {
        OrgId = t.OrgId, PaymentNo = no,
        SupplierCode = dto.SupplierCode.Trim().ToUpperInvariant(),
        OrderPartNo = orderNo, DealerCode = dto.DealerCode, Amount = amount,
        // 🔴 #243 SỬA #237: nguồn ghi `null` cho `PaymentDTime` VÀ `PaymentBy` lúc lưu
        //    (MyBuildDBDT_Common, BizCarSv.Inventory.StockOut.cs:15925-15935), và bước duyệt cũng
        //    KHÔNG chạm hai cột đó. #237 tôi đặt DateTime.Now là SAI. Để NULL, ghi nợ.
        PaymentDate = null,
        Status = "P",
        SupplierID = dto.SupplierID, Address = dto.Address, TSTRequestNo = dto.TSTRequestNo,
        PaymentType = string.IsNullOrWhiteSpace(dto.PaymentType) ? "PMT" : dto.PaymentType!.Trim().ToUpperInvariant(),
        Description = dto.Description,
        CreateBy = who, LogLUDTime = DateTime.Now, LogLUBy = who,
    };
    if (existingP is not null)
    {
        // SỬA: giữ NGUYÊN CreateDTime/CreateBy của bản ghi cũ (:15891-15892), thay trọn bộ dòng.
        p.Id = existingP.Id;
        p.CreatedAt = existingP.CreatedAt;
        p.CreateBy = existingP.CreateBy;
        db.Entry(existingP).CurrentValues.SetValues(p);
        var oldPl2 = await db.SupplierPaymentLines.Where(l => l.OrgId == t.OrgId && l.PaymentNo == no).ToListAsync();
        db.SupplierPaymentLines.RemoveRange(oldPl2);
        await db.SaveChangesAsync();
        p = existingP;
    }
    else db.SupplierPayments.Add(p);
    foreach (var l in paymentLines)
        db.SupplierPaymentLines.Add(new SupplierPaymentLine
        {
            OrgId = t.OrgId, PaymentNo = no,
            PartCode = l.PartCode!.Trim().ToUpperInvariant(), PartName = l.PartName,
            QtyPay = l.QtyPay, Price = l.Price, Vat = l.Vat,
            Amount = l.QtyPay * l.Price * (1 + l.Vat / 100m),   // = PriceAfterVAT của nguồn
            // #237: 8 cột bổ sung mà form gửi lên (FrmSer_SupplierPayment.cs:702-718)
            PartID = l.PartID, Unit = l.Unit,
            StockInID = l.StockInID, StockInNo = l.StockInNo,
            QtyInventory = l.QtyInventory, LocationID = l.LocationID,
            // #260: 3 cột bổ sung
            InStockQuantity = l.InStockQuantity, LocationCode = l.LocationCode, LocationName = l.LocationName,
            SupplierPaymentDtlStatus = "P",
            LogLUDTime = DateTime.Now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PaymentNo, p.SupplierCode, p.OrderPartNo, p.Amount, lines = paymentLines.Count, status = p.Status });
}).RequireAuthorization();

// Chi tiết phụ tùng của một phiếu thanh toán nhà cung cấp.
app.MapGet("/api/supplierpayments/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.SupplierPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PaymentNo == no);
    if (p is null) return Results.NotFound(new { no });
    var lines = await db.SupplierPaymentLines.Where(l => l.OrgId == t.OrgId && l.PaymentNo == no)
        .Select(l => new { l.PartCode, l.PartName, l.QtyPay, l.Price, l.Vat, l.Amount,
                           // #237: 9 cột bổ sung của dòng
                           l.PartID, l.Unit, l.StockInID, l.StockInNo, l.QtyInventory, l.LocationID,
                           l.InStockQuantity, l.LocationCode, l.LocationName,   // #260
                           l.SupplierPaymentDtlStatus, l.LogLUDTime, l.LogLUBy }).ToListAsync();
    return Results.Ok(new { p.PaymentNo, p.SupplierCode, p.DealerCode, p.Status, p.Amount, p.ApprovedAt, count = lines.Count, lines });
}).RequireAuthorization();

app.MapPost("/api/supplierpayments/{no}/approve", async (string no, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var p = await db.SupplierPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PaymentNo == no);
    if (p is null) return Results.NotFound(new { no });
    if (p.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt phiếu Mới tạo." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var nowAppr = DateTime.Now;   // nguồn dùng CÙNG một dtimeSys cho mọi cột dưới đây
    p.Status = "A"; p.ApprovedAt = nowAppr; p.ApprBy = who;
    p.LogLUDTime = nowAppr; p.LogLUBy = who;

    // ===== 🔴 #244 GIẢI NỢ `PaymentDTime`/`PaymentBy` (ghi nợ ở #243) =====
    // Quét toàn biz tìm nơi GHI hai cột (không chỉ nơi select): `BizCarSv.Inventory.StockOut.cs:16839-16840`
    //   `, t.PaymentDTime = f.ApprDTime`
    //   `, t.PaymentBy   = f.ApprBy`
    // ⇒ **ngày/người thanh toán = ngày/người DUYỆT**, đặt tại bước duyệt chứ không phải lúc lưu.
    //   Kết luận ở #243 ("không ai ghi cả") là do mới đọc HAI hàm; quét cả file mới ra.
    p.PaymentDate = nowAppr;
    p.PaymentBy = who;
    // Dòng có trạng thái RIÊNG (SupplierPaymentDtlStatus) — đồng bộ theo đầu phiếu.
    var payLines = await db.SupplierPaymentLines.Where(l => l.OrgId == t.OrgId && l.PaymentNo == no).ToListAsync();
    foreach (var l in payLines) { l.SupplierPaymentDtlStatus = "A"; l.LogLUDTime = DateTime.Now; l.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PaymentNo, status = p.Status });
}).RequireAuthorization();

// ===== Khiếu nại đơn đặt phụ tùng (Ser_OrderComplain — port 1:1 FrmSer_OrderComplain/Mng) =====
app.MapGet("/api/ordercomplains", async (AppDbContext db, ITenantContext t, string? dms, string? tst, string? order) =>
{
    var q = db.OrderComplains.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dms)) q = q.Where(c => c.DMSStatus == dms);
    if (!string.IsNullOrWhiteSpace(tst)) q = q.Where(c => c.TSTStatus == tst);
    if (!string.IsNullOrWhiteSpace(order)) q = q.Where(c => c.OrderPartNo.Contains(order.ToUpper()));
    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    { c.ComplainNo, c.OrderPartNo, c.ComplainType, c.Content, c.DMSStatus, c.TSTStatus, c.Resolution, c.CreatedAt,
      // #233: 16 cột bổ sung — §12 yêu cầu có mặt ở CẢ GET lẫn POST.
      c.DealerCode, c.PartCode, c.VieName, c.Quantity, c.VINCode, c.RequestOrderNo,
      c.TSTOrderComplainNo, c.TSTEmployeeCode,
      c.DeliveryDateTime, c.DeliveryBy, c.TransportUnit, c.DeliveryLocation,
      c.ReceiveBy, c.AssembleDateTime, c.AssembleBy,
      c.CreateBy, c.LogLUDTime, c.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴 #233 KHIẾU NẠI ĐƠN PHỤ TÙNG — parity với `FrmSer_OrderComplain_Detail.cs` (875 dòng, DMSCarSv/TST)
// Tầng ghi: `Ser_OrderComplainService.Ser_OrderComplain_Save` (:104) gửi lên **17 trường**.
// BƯỚC 3B: `FrmSer_OrderComplain_Detail.cs` md5 `5dd58edf` và `Ser_OrderComplainService.cs` md5 `5ef43541`
//          — KHỚP laptop (V20.2023.Release.V2) và máy 150 (V20.2023.Release).
//
// 🔴 Port cũ chỉ có 4 trường nghiệp vụ (OrderPartNo/ComplainType/Content + 2 trạng thái) ⇒ thiếu 16 cột,
//    trong đó có **trọn khối GIAO NHẬN + LẮP ĐẶT** (7 cột) — cả một mảng nghiệp vụ biến mất.
//
// MƯỜI HAI guard của `checkForm()` (FrmSer_OrderComplain_Detail.cs:373-493) — port đủ, đúng thứ tự:
//  phân loại · ngày tạo (rỗng/sai định dạng) · mã vật tư · tên vật tư ·
//  số lượng (rỗng / không phải số / phải > 0) · VIN · số yêu cầu giao hàng · đơn hàng đặt hàng ·
//  tình trạng hỏng (rỗng / **> 256 ký tự**) · ngày giao nhận (rỗng/sai định dạng) · người giao nhận ·
//  đơn vị vận tải.
// ⚠️ BẤT ĐỐI XỨNG cố ý: `DeliveryLocation` · `ReceiveBy` · `AssembleDateTime` · `AssembleBy` **KHÔNG** bị kiểm
//    dù cùng khối giao nhận — form chỉ bắt buộc 3 trường đầu. Giữ nguyên, không "siết cho đều".
// ⚠️ `TSTOrderComplainNo` · `TSTEmployeeCode` · `TSTSolution` · hai cột trạng thái KHÔNG nằm trong
//    `Ser_OrderComplain_Save` ⇒ client **không gửi được**; phía NCC/TST ghi. Không nhận từ DTO.
// ===== 🔴 #242 SAVE BA VAI cho `Ser_OrderComplain_Save` + guard của BIZ (khác guard của FORM) =====
// Nguồn `BizCarSv.SuggestPrice.cs:2756-2872` (md5 8aafd84f, 4213 dòng — khớp 2 máy).
// #233 đã port 12 guard của `checkForm()` phía client. Lượt này đọc **tầng BIZ** — và biz có guard RIÊNG:
//  · Ba vai như #240/#241: `bIsDelete` · chưa tồn tại + đang xoá ⇒ `goto MyCodeLabel_Done` (thành công
//    im lặng) · đã tồn tại ⇒ `DMSOrderComplainStatus` **phải là `Pending`** ⇒ khiếu nại đã gửi
//    KHÔNG sửa/xoá được. Khi sửa: giữ NGUYÊN `CreateDTime`/`CreateBy`.
//  · `Mst_Dealer_CheckDB(Exist=Yes, **Active**)` — giống YC báo giá (#241), KHÁC đơn đặt PT (#240 không có).
//  · 🔴 `if (dblQuantity < 1)` ⇒ "Số lượng vật tư phải lớn hơn 0!" — **ngưỡng là `< 1`, KHÔNG phải `<= 0`**.
//    Số lượng lẻ (0.5) bị CHẶN dù thông điệp chỉ nói "lớn hơn 0". Form (#233) chỉ kiểm `> 0` ⇒ **hai tầng
//    lệch nhau**; biz mới là chốt chặn cuối, port theo BIZ.
//  · `VINCode` rỗng ⇒ "Số VIN không được để trống!" (biz kiểm lại, không tin form).
app.MapPost("/api/ordercomplains", async (OrderComplainDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var isDelete = string.Equals(dto.FlagIsDelete, "Y", StringComparison.OrdinalIgnoreCase);
    var cmpNoIn = (dto.ComplainNo ?? "").Trim().ToUpperInvariant();

    OrderComplain? existingC = cmpNoIn.Length == 0 ? null
        : await db.OrderComplains.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ComplainNo == cmpNoIn);

    if (existingC is null && isDelete)
        return Results.Ok(new { complainNo = cmpNoIn, deleted = true, note = "Khiếu nại không tồn tại — xoá coi như thành công (đúng nguồn)." });

    if (existingC is not null && existingC.DMSStatus != "P")
        return Results.BadRequest(new { error = "Chỉ sửa/xoá được khiếu nại đang Mới tạo.", dmsStatus = existingC.DMSStatus });

    if (isDelete)
    {
        var oldFiles = await db.OrderComplainAttachments.Where(a => a.OrgId == t.OrgId && a.ComplainNo == cmpNoIn).ToListAsync();
        db.OrderComplainAttachments.RemoveRange(oldFiles);
        db.OrderComplains.Remove(existingC!);
        await db.SaveChangesAsync();
        return Results.Ok(new { complainNo = cmpNoIn, deleted = true, removedFiles = oldFiles.Count });
    }

    if (string.IsNullOrWhiteSpace(dto.OrderPartNo)) return Results.BadRequest(new { error = "Cần OrderPartNo." });
    var orderNo = dto.OrderPartNo.Trim().ToUpperInvariant();
    var exists = await db.OrderParts.AnyAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == orderNo);
    if (!exists) return Results.BadRequest(new { error = $"Không tìm thấy đơn đặt {orderNo}." });

    // Guard của BIZ: đại lý phải tồn tại VÀ đang hoạt động.
    if (!string.IsNullOrWhiteSpace(dto.DealerCode))
    {
        var dlrC = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dto.DealerCode!.Trim());
        if (dlrC is null) return Results.BadRequest(new { error = $"Đại lý {dto.DealerCode} không tồn tại." });
        if (dlrC.FlagActive != "1") return Results.BadRequest(new { error = $"Đại lý {dto.DealerCode} đang ngừng hoạt động." });
    }

    // --- 12 guard của checkForm(), giữ NGUYÊN THÔNG ĐIỆP tiếng Việt của nguồn ---
    if (string.IsNullOrWhiteSpace(dto.ComplainType)) return Results.BadRequest(new { error = "Chưa chọn phân loại khiếu nại" });
    if (string.IsNullOrWhiteSpace(dto.PartCode)) return Results.BadRequest(new { error = "Mã vật tư không được trống" });
    if (string.IsNullOrWhiteSpace(dto.VieName)) return Results.BadRequest(new { error = "Tên vật tư không được trống" });
    if (dto.Quantity is null) return Results.BadRequest(new { error = "Số lượng không được trống" });
    if (dto.Quantity <= 0) return Results.BadRequest(new { error = "Số lượng > 0" });
    // 🔴 Guard của BIZ chặt hơn form: `if (dblQuantity < 1)` (BizCarSv.SuggestPrice.cs:2846).
    //    Thông điệp nói "lớn hơn 0" nhưng ngưỡng thật là **>= 1** ⇒ 0.5 bị chặn. Giữ nguyên cả hai.
    if (dto.Quantity < 1) return Results.BadRequest(new { error = "Số lượng vật tư phải lớn hơn 0!" });
    if (string.IsNullOrWhiteSpace(dto.VINCode)) return Results.BadRequest(new { error = "VIN không được trống" });
    if (string.IsNullOrWhiteSpace(dto.RequestOrderNo)) return Results.BadRequest(new { error = "Số yêu cầu giao hàng không được trống" });
    var content = (dto.Content ?? "").Trim();
    if (content.Length == 0) return Results.BadRequest(new { error = "Tình trạng hỏng và NN ban đầu không được trống" });
    // 🔴 Ngưỡng 256 lấy từ biến `int iLength = 256` (dòng 451), KHÔNG phải 200 như Mst_DeliveryLocation.
    if (content.Length > 256) return Results.BadRequest(new { error = "Tình trạng hỏng và NN ban đầu không được > 256 ký tự" });
    if (dto.DeliveryDateTime is null) return Results.BadRequest(new { error = "Ngày giao nhận không được trống" });
    if (string.IsNullOrWhiteSpace(dto.DeliveryBy)) return Results.BadRequest(new { error = "Người giao nhận không được trống" });
    if (string.IsNullOrWhiteSpace(dto.TransportUnit)) return Results.BadRequest(new { error = "Đơn vị vận tải không được trống" });

    var no = existingC?.ComplainNo ?? (cmpNoIn.Length > 0 ? cmpNoIn : "CMP" + DateTime.Now.ToString("yyMMddHHmmss"));
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var c = new OrderComplain
    {
        OrgId = t.OrgId, ComplainNo = no, OrderPartNo = orderNo,
        ComplainType = dto.ComplainType, Content = content,
        DMSStatus = "P", TSTStatus = "1",   // nguồn set TSTStatus=1 (Chờ duyệt) NGAY khi tạo, không để rỗng
        DealerCode = dto.DealerCode,
        PartCode = dto.PartCode, VieName = dto.VieName, Quantity = dto.Quantity, VINCode = dto.VINCode,
        RequestOrderNo = dto.RequestOrderNo,
        DeliveryDateTime = dto.DeliveryDateTime, DeliveryBy = dto.DeliveryBy, TransportUnit = dto.TransportUnit,
        // 4 trường không bắt buộc của khối giao nhận/lắp đặt
        DeliveryLocation = dto.DeliveryLocation, ReceiveBy = dto.ReceiveBy,
        AssembleDateTime = dto.AssembleDateTime, AssembleBy = dto.AssembleBy,
        CreateBy = who, LogLUDTime = DateTime.Now, LogLUBy = who,
    };
    if (existingC is not null)
    {
        // SỬA: giữ NGUYÊN CreateDTime/CreateBy của bản ghi cũ (:2827-2828).
        c.Id = existingC.Id;
        c.CreatedAt = existingC.CreatedAt;
        c.CreateBy = existingC.CreateBy;
        db.Entry(existingC).CurrentValues.SetValues(c);
        await db.SaveChangesAsync();
        c = existingC;
    }
    else { db.OrderComplains.Add(c); await db.SaveChangesAsync(); }
    return Results.Ok(new { c.ComplainNo, c.OrderPartNo, dmsStatus = c.DMSStatus, tstStatus = c.TSTStatus,
                            c.DealerCode, c.PartCode, c.VieName, c.Quantity, c.VINCode, c.RequestOrderNo,
                            c.DeliveryDateTime, c.DeliveryBy, c.TransportUnit, c.DeliveryLocation,
                            c.ReceiveBy, c.AssembleDateTime, c.AssembleBy, c.CreateBy });
}).RequireAuthorization();

// DMS gửi (P→A); TST tiếp nhận/xử lý/giải quyết
// 🔴 Trạng thái khiếu nại theo ĐÚNG nguồn. Mã TST là SỐ NHẢY (1/15/21/31), KHÔNG liên tục.
// Kết cục PHÂN ĐÔI: 21 = KHÔNG chấp thuận · 31 = CHẤP THUẬN — port cũ gộp thành một "Resolved".
var complainTstStatusNames = new Dictionary<string, string>
{
    ["1"] = "Chờ duyệt",
    ["15"] = "Đang xử lý",
    ["21"] = "Không chấp thuận khiếu nại",
    ["31"] = "Chấp thuận khiếu nại",
};

// Ánh xạ giá trị port CŨ → mã nguồn, để dữ liệu đã tạo vẫn đọc được.
var complainLegacyTstMap = new Dictionary<string, string>
{
    [""] = "1",
    ["Processing"] = "1",
    ["Pending"] = "15",
    ["Resolved"] = "31",   // port cũ chỉ có MỘT kết cục ⇒ quy về "chấp thuận"
};

app.MapGet("/api/ordercomplains/statuses", () => Results.Ok(new
{
    dmsStatuses = new[] { new { code = "P", name = "Mới tạo" }, new { code = "A", name = "Đã gửi" } },
    tstStatuses = complainTstStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    legacyTstMap = complainLegacyTstMap.Select(kv => new { legacy = kv.Key, code = kv.Value }),
    note = "Mã TST nhảy số 1/15/21/31; nguồn set '1' NGAY KHI TẠO, không có trạng thái rỗng."
})).RequireAuthorization();

app.MapPost("/api/ordercomplains/{no}/{action}", async (string no, string action, OrderComplainActDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("send" or "process" or "approve" or "reject"))
        return Results.BadRequest(new { error = "action = send|process|approve|reject" });
    no = no.Trim().ToUpperInvariant();
    var c = await db.OrderComplains.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ComplainNo == no);
    if (c is null) return Results.NotFound(new { no });

    // Quy trạng thái port cũ về mã nguồn trước khi xét.
    var tst = complainLegacyTstMap.TryGetValue(c.TSTStatus, out var mappedTst) ? mappedTst : c.TSTStatus;

    if (action == "send")
    {
        if (c.DMSStatus != "P") return Results.BadRequest(new { error = "Chỉ gửi khiếu nại Mới tạo." });

        // ===== 🔴 #239 GỬI SANG TST — `Ser_OrderComplain_SentTST` (BizCarSv.SuggestPrice.cs:3535) =====
        // Cùng khuôn với `Req_PartPrice_SentTST`: gọi API Bravo → chỉ ghi khi `Status == "OK"`,
        // khác thì ném `Ser_OrderComplain_SentTST_SyncFail` và KHÔNG đổi trạng thái.
        //
        // 🔴 KHÁC BIỆT quan trọng so với YC báo giá: update của khiếu nại đặt **CẢ HAI** trạng thái
        //    (:3757-3758) — `DMSOrderComplainStatus = Approved` **VÀ**
        //    `TSTOrderComplainStatus = Pending` ⇒ **ĐẶT LẠI trạng thái TST về "1" ngay lúc gửi**.
        //    Port cũ chỉ chạm DMS ⇒ khiếu nại từng bị xử lý dở (TST=15) rồi gửi lại sẽ giữ nguyên 15,
        //    trong khi nguồn kéo về "chờ duyệt". Nay port đúng.
        //    Nguồn chỉ đặt `LogLUDTime`/`LogLUBy` ở đây — KHÔNG có ApprDTime/ApprBy như YC báo giá.
        var syncOkC = string.IsNullOrWhiteSpace(dto?.SyncStatus) || string.Equals(dto!.SyncStatus, "OK", StringComparison.OrdinalIgnoreCase);
        if (!syncOkC)
            return Results.BadRequest(new
            {
                error = "Đồng bộ khiếu nại sang TST thất bại — không đổi trạng thái.",
                syncStatus = dto?.SyncStatus, description = dto?.SyncDescription,
            });

        var whoC = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
        var nowC = DateTime.Now;
        c.DMSStatus = "A";
        tst = "1";                  // 🔴 nguồn ĐẶT LẠI TSTOrderComplainStatus = Pending
        c.LogLUDTime = nowC; c.LogLUBy = whoC;
    }
    else
    {
        if (c.DMSStatus != "A") return Results.BadRequest(new { error = "DMS chưa gửi khiếu nại." });
        if (action == "process")
        {
            if (tst != "1") return Results.BadRequest(new { error = "Chỉ chuyển sang Đang xử lý khi đang Chờ duyệt." });
            tst = "15";
        }
        else
        {
            // Kết cục: CHẤP THUẬN (31) hoặc KHÔNG chấp thuận (21) — hai đường riêng, không gộp.
            if (tst is not ("1" or "15")) return Results.BadRequest(new { error = "Khiếu nại đã có kết luận." });
            if (string.IsNullOrWhiteSpace(dto.Resolution))
                return Results.BadRequest(new { error = "Phải ghi nội dung kết luận." });
            tst = action == "approve" ? "31" : "21";
            c.Resolution = dto.Resolution;
        }
        c.TSTStatus = tst;
    }

    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        c.ComplainNo, dmsStatus = c.DMSStatus, tstStatus = c.TSTStatus,
        tstStatusName = complainTstStatusNames.TryGetValue(c.TSTStatus, out var tstName) ? tstName : c.TSTStatus
    });
}).RequireAuthorization();

// ===== Đơn đặt phụ tùng từ NCC (Ser_Order_Part — port 1:1 FrmSer_Order_Part) =====
// ===== 🔴 #235 CÔNG THỨC GIÁ DÒNG ĐƠN ĐẶT PHỤ TÙNG — `Ser_Order_PartDtl` =====
// Nguồn: `FrmSer_Order_Part_Detail.cs:1088-1114` (khối tính trong `bandedGridView`).
// 🔴 BẪY DÒNG COMMENT: ngay cạnh hai dòng ACTIVE có hai dòng bị comment dùng `QtyOrd`:
//      `//dTPBeforeDc = dQtyOrd * dUPBeforeDc;`   ← CHẾT
//      `dTPBeforeDc = dQtyAppr * dUPBeforeDc;`    ← SỐNG
//    ⇒ thành tiền tính theo **SỐ LƯỢNG DUYỆT (`QtyAppr`)**, KHÔNG phải số lượng đặt.
//    Port nhầm sang `QtyOrd` thì đơn duyệt thiếu vẫn tính đủ tiền — sai tiền, im lặng.
// ⚠️ Khối tính chỉ chạy khi `!isTST` (phía TST không tính lại) — bản port tính ở server cho mọi đường ghi
//    của đại lý, vì đó là nơi duy nhất còn giữ được ràng buộc.
static void RecalcOrderPartLine(OrderPartLine l)
{
    var qtyAppr = l.QtyAppr ?? 0m;          // 🔴 QtyAppr, KHÔNG phải OrderQty
    var upBefore = l.UPBeforeDc ?? 0m;
    var discountRate = l.DiscountRate ?? 0m;
    var vat = l.VAT ?? 0m;

    l.TPBeforeDc = qtyAppr * upBefore;
    l.UPAfterDc = upBefore * (1 - discountRate / 100m);
    l.TPAfterDc = qtyAppr * l.UPAfterDc.Value;
    l.ValVAT = l.TPAfterDc.Value * (vat / 100m);
    l.TPAfterVAT = l.TPAfterDc.Value + l.ValVAT.Value;
}

// ===== 🔴 #236 SỬA SUY LUẬN SAI CỦA #235 — tổng đầu đơn =====
// #235 tôi đoán `ValDiscount` = tổng tiền chiết khấu và tính `Sum(TPBeforeDc − TPAfterDc)`. **SAI.**
// Đối chiếu biz `BizCarSv.A.02.OrderPart.cs` (md5 72e6623f, 5014 dòng — khớp 2 máy):
//  • :1050-1074 gom từ dòng rồi `update Ser_Order_Part` **ĐÚNG BA cột**:
//      `TotalValOrderBeforeDc = Sum(TPBeforeDc)` · `TotalValOrderAfterDc = Sum(TPAfterDc)`
//      · `TotalValOrderAfterVAT = Sum(TPAfterVAT)`
//  • :4891/:4913 — tham số `objValDiscount` của `Ser_Order_PartDtl_Create` được ghi vào cột
//      `DiscountRate` **CỦA DÒNG** ⇒ `ValDiscount` chỉ là TÊN THAM SỐ, không phải tổng của đầu đơn.
// ⇒ Bỏ hẳn phép tính `ValDiscount`; bổ sung 2 cột tổng thật. Muốn biết tiền chiết khấu của đơn thì lấy
//   hiệu `TotalValOrderBeforeDc − TotalValOrderAfterDc` (bản port trả sẵn ở GET, KHÔNG lưu thành cột).
static void RecalcOrderPartTotals(OrderPart o, List<OrderPartLine> lines)
{
    o.TotalValOrderBeforeDc = lines.Sum(x => x.TPBeforeDc ?? 0m);
    o.TotalValOrderAfterDc = lines.Sum(x => x.TPAfterDc ?? 0m);
    o.TotalValOrderAfterVAT = lines.Sum(x => x.TPAfterVAT ?? 0m);
    // ⚠️ KHÔNG gán o.ValDiscount ở đây — xem chú thích lớp OrderPart.
}

// ===== 🔴 #234 ĐƠN ĐẶT PHỤ TÙNG — parity `Ser_Order_Part` (DMSCarSv/TST) =====
// Màn: `Views/TST/FrmSer_Order_PartMng.cs` (1290 dòng) + `FrmSer_Order_Part_Detail.cs` (1466 dòng).
// Tầng ghi `Ser_Order_PartService.cs`: `_Save` (:141) gửi **9 trường**, `_Appr` (:182) gửi **7 trường**
//   — hai bộ KHÁC NHAU (xem chú thích ở endpoint duyệt).
// BƯỚC 3B: `Ser_Order_PartService.cs` md5 `a5dd9a0f` · `Entities/TST/Ser_Order_Part.cs` md5 `bc2a2708` ·
//   `TERP.Constants/Const.Main.cs` md5 `84bb208f` — cả ba KHỚP laptop và máy 150.
//
// 🔴 GAP TRẠNG THÁI: port cũ lưu chuỗi dài ở header nhưng mã 1 ký tự ở dòng chi tiết ⇒ hai bộ mã lệch nhau.
//    Nay header dùng `TConst.OrderPartStatus` = "P"/"A"/"F"/"R"; bộ lọc chấp nhận CẢ tên cũ (ánh xạ dưới).
var orderPartLegacyStatusMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
{
    ["Pending"] = "P", ["Approved"] = "A", ["Finished"] = "F", ["Rejected"] = "R",
};

var orderPartStatusNames = new Dictionary<string, string>
{
    ["P"] = "Mới tạo", ["A"] = "Đã duyệt / gửi NCC", ["F"] = "Hoàn thành", ["R"] = "Từ chối",
};

// 🔴 Trạng thái phía NCC là CỘT RIÊNG, mã SỐ NHẢY (TConst.SupplierStatus, Const.Main.cs:544) — không có 3/5/6.
var orderPartSupplierStatusNames = new Dictionary<string, string>
{
    ["1"] = "Chờ duyệt",
    ["2"] = "Đã duyệt, chờ hoàn thiện",
    ["4"] = "Đã hoàn thiện",
    ["7"] = "Đơn lỗi, chờ kinh doanh điều chỉnh",
};

app.MapGet("/api/orderparts/statuses", () => Results.Ok(new
{
    orderPartStatus = orderPartStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    supplierStatus = orderPartSupplierStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    orderPartType = new[] { "TST", "OTHER" },
    legacyMap = orderPartLegacyStatusMap.Select(kv => new { legacy = kv.Key, code = kv.Value }),
    note = "Mã NCC nhảy 1/2/4/7 — KHÔNG liên tục; đừng suy ra 3/5/6.",
})).RequireAuthorization();

app.MapGet("/api/orderparts", async (AppDbContext db, ITenantContext t, string? status, string? supplier,
    string? dealerCode, string? supplierStatus, string? orderPartType) =>
{
    var q = db.OrderParts.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status))
    {
        // chấp nhận cả tên dài của port cũ lẫn mã 1 ký tự của nguồn
        var code = orderPartLegacyStatusMap.TryGetValue(status.Trim(), out var mapped) ? mapped : status.Trim();
        q = q.Where(o => o.OrderPartStatus == code);
    }
    if (!string.IsNullOrWhiteSpace(supplier)) q = q.Where(o => o.SupplierCode == supplier);
    if (!string.IsNullOrWhiteSpace(dealerCode)) q = q.Where(o => o.DealerCode == dealerCode!.Trim());
    if (!string.IsNullOrWhiteSpace(supplierStatus)) q = q.Where(o => o.SupplierStatus == supplierStatus!.Trim());
    if (!string.IsNullOrWhiteSpace(orderPartType)) q = q.Where(o => o.OrderPartType == orderPartType!.Trim().ToUpperInvariant());
    var items = await q.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.OrderPartNo, o.SupplierCode, o.WarehouseCode, o.OrderPartStatus, o.CreatedAt, o.SentAt, o.FinishedAt,
        // #234: 22 cột bổ sung (§12 — có mặt ở cả GET lẫn POST)
        o.DealerCode, o.SupplierID, o.PartGroupID, o.DeliveryFormCode, o.DeliveryLocationCode,
        o.EstimatedDeliverDate, o.VIN, o.Remark,
        o.RequestSuppierDate, o.ResponseSuppierDate, o.OrderSuppierNo,
        o.SupplierStatus, o.OrderPartType, o.TSTID, o.SupplierLUDTime,
        o.TotalValOrderBeforeDc, o.TotalValOrderAfterDc, o.TotalValOrderAfterVAT, o.ValDiscount,
        o.CreateBy, o.ApprBy, o.FinishBy, o.LogLUDateTime, o.LogLUBy,
        lines = db.OrderPartLines.Count(l => l.OrgId == t.OrgId && l.OrderPartId == o.Id),
        total = db.OrderPartLines.Where(l => l.OrgId == t.OrgId && l.OrderPartId == o.Id).Sum(l => (decimal?)(l.OrderQty * l.Price)) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴 #240 SAVE = UPSERT + XOÁ, và 8 GUARD của `Ser_Order_Part_Save` =====
// Nguồn: `TERP.BizCarSv/BizCarSv.A.02.OrderPart.cs:193-405` (md5 72e6623f, 5014 dòng — khớp 2 máy).
// Port cũ coi POST là "luôn tạo mới": tự sinh `OrderPartNo`, không có đường sửa, không có đường xoá,
// và chỉ kiểm 2 điều kiện. Nguồn thì `Ser_Order_Part_Save` là **một hàm ba vai**:
//
//  A. `bIsDelete = (FlagIsDelete == "Y")` (:235).
//  B. `Ser_Order_Part_CheckDB` → **CHƯA tồn tại**:
//       · đang XOÁ ⇒ `goto MyCodeLabel_Done` = **THÀNH CÔNG im lặng** (xoá thứ không có = idempotent,
//         KHÔNG báo lỗi 404). Giữ đúng.
//       · không xoá ⇒ tạo mới.
//  C. **ĐÃ tồn tại** ⇒ 🔴 `OrderPartStatus` **phải là `Pending`**, khác ⇒ `Save_InvalidOrderPartStatus`.
//       ⇒ đơn đã duyệt/hoàn thành/từ chối thì **không sửa và không xoá được**.
//  D. Khi sửa: `CreateDTime`/`CreateBy` **giữ NGUYÊN của bản ghi cũ** (:293-294), không ghi đè.
//
// TÁM guard, giữ nguyên thông điệp tiếng Việt của nguồn:
//  1. `PartGroupID` rỗng ⇒ "Phân nhóm vật tư không được để trống!" (:336)
//  2. `SupplierID` rỗng ⇒ "Nhà cung cấp không được để trống!" (:350)
//  3. `SupplierID` không có trong `Ser_Mst_Supplier` ⇒ **CÙNG thông điệp** "Nhà cung cấp không được để trống!"
//     (:375 — nguồn dùng lại đúng câu đó dù nghĩa là "không tồn tại"; giữ nguyên, không "sửa cho đúng").
//  4-5. Khi `OrderPartType == "TST"`: `Mst_DeliveryForm_CheckDB(Exist=Yes, Active)` ⇒ hình thức giao hàng
//     phải TỒN TẠI và ĐANG HOẠT ĐỘNG.
//  6. 🔴 `DeliveryFormCode == TConst.DeliveryFormCode.BAOHANH` ⇒ **VIN bắt buộc**:
//     "Hình thức Bảo hành VIN bắt buộc nhập!" — ⚠️ hằng `BAOHANH` có giá trị **"2"**, KHÔNG phải chuỗi
//     "BAOHANH" (Const.Main.cs:628-631). So sánh nhầm bằng tên hằng = guard chết câm.
//  7-8. Hai guard sẵn có (nhà cung cấp, ít nhất 1 dòng).
//
// ⚠️ KHÔNG port guard `EstimatedDeliverDate >= hôm nay`: cả khối bị **COMMENT** ở nguồn (:390-403).
// ===== 🔴 #346 HAI CỘT SWEEP BÁO "CHẾT" nhưng **KHÔNG PHẢI GAP** — kết luận sau khi tra nguồn =====
// `OrderPart.TSTID` / `OrderPartLine.TSTID`: trong toàn `TERP.BizCarSv` chỉ xuất hiện ở **mệnh đề tra**
//   (`and t.TSTID = @objTSTID`); **mọi câu GHI đều bị comment** (`A.02.OrderPart.cs:3334/3344`)
//   ⇒ hệ TST ghi thẳng vào CSDL, không qua tầng biz này. Không tự bịa đường ghi (lệ #299).
// `OrderPart.ValDiscount`: nguồn **KHÔNG có cột này**. `objValDiscount` chỉ là **TÊN THAM SỐ**, và
//   nó được gán vào cột `DiscountRate` của bảng CHI TIẾT:
//   `dt_OrderPart_Detail.Rows[0]["DiscountRate"] = objValDiscount;` (`:4913`)
//   ⇒ `ValDiscount` là cột **ma** do port đặt theo tên tham số. Giữ nguyên (xoá cột là đổi lược đồ
//     ngoài phạm vi lượt này) nhưng ghi rõ để không ai đi tìm đường ghi cho nó nữa.
app.MapPost("/api/orderparts", async (OrderPartDto dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    var isDelete = string.Equals(dto.FlagIsDelete, "Y", StringComparison.OrdinalIgnoreCase);
    var reqNo = (dto.OrderPartNo ?? "").Trim().ToUpperInvariant();

    // (B) tra bản ghi cũ theo số đơn (trống = tạo mới)
    OrderPart? existing = reqNo.Length == 0 ? null
        : await db.OrderParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == reqNo);

    if (existing is null && isDelete)
        // Xoá đơn chưa tồn tại: nguồn goto Done ⇒ THÀNH CÔNG im lặng, không 404.
        return Results.Ok(new { orderPartNo = reqNo, deleted = true, note = "Đơn không tồn tại — xoá coi như thành công (đúng nguồn)." });

    // (C) đã tồn tại thì chỉ đụng được khi còn "P"
    if (existing is not null && existing.OrderPartStatus != "P")
        return Results.BadRequest(new { error = "Chỉ sửa/xoá được đơn đặt đang Mới tạo.", orderPartStatus = existing.OrderPartStatus });

    if (isDelete)
    {
        var oldLines = await db.OrderPartLines.Where(l => l.OrgId == t.OrgId && l.OrderPartId == existing!.Id).ToListAsync();
        db.OrderPartLines.RemoveRange(oldLines);
        db.OrderParts.Remove(existing!);
        await db.SaveChangesAsync();
        return Results.Ok(new { orderPartNo = reqNo, deleted = true, removedLines = oldLines.Count });
    }

    if (string.IsNullOrWhiteSpace(dto.SupplierCode)) return Results.BadRequest(new { error = "Cần SupplierCode (nhà cung cấp)." });

    // guard 1: phân nhóm vật tư
    if (string.IsNullOrWhiteSpace(dto.PartGroupID))
        return Results.BadRequest(new { error = "Phân nhóm vật tư không được để trống!" });
    // guard 2 + 3: nhà cung cấp — CÙNG thông điệp cho cả "rỗng" lẫn "không tồn tại" (đúng nguồn)
    if (string.IsNullOrWhiteSpace(dto.SupplierID))
        return Results.BadRequest(new { error = "Nhà cung cấp không được để trống!" });
    var supId = dto.SupplierID!.Trim();
    // Nguồn kiểm bằng `select * from Ser_Mst_Supplier where SupplierID = @strSupplierID`
    //   ⇒ đúng bảng `SerMstSuppliers` của MiniHTC (khoá lưu ở cột `SupplierCode`).
    if (!await db.SerMstSuppliers.AnyAsync(s => s.OrgId == t.OrgId && s.SupplierCode == supId))
        return Results.BadRequest(new { error = "Nhà cung cấp không được để trống!", supplierId = supId });

    var opType = string.IsNullOrWhiteSpace(dto.OrderPartType) ? null : dto.OrderPartType!.Trim().ToUpperInvariant();
    if (opType == "TST")
    {
        // guard 4-5: hình thức giao hàng phải tồn tại + đang hoạt động (Mst_DeliveryForm nằm trong catalog chung)
        var dfCode = (dto.DeliveryFormCode ?? "").Trim().ToUpperInvariant();
        if (dfCode.Length == 0)
            return Results.BadRequest(new { error = "Chưa chọn hình thức giao hàng." });
        var df = await db.Masters.FirstOrDefaultAsync(m => m.OrgId == t.OrgId && m.Category == "DeliveryForm" && m.Code == dfCode);
        if (df is null || df.Status != "1")
            return Results.BadRequest(new { error = $"Hình thức giao hàng {dfCode} không tồn tại hoặc đã ngừng.", deliveryFormCode = dfCode });

        // guard 6: 🔴 mã BẢO HÀNH là "2" (TConst.DeliveryFormCode.BAOHANH), KHÔNG phải chuỗi "BAOHANH"
        if (dfCode == "2" && string.IsNullOrWhiteSpace(dto.VIN))
            return Results.BadRequest(new { error = "Hình thức Bảo hành VIN bắt buộc nhập!" });
    }

    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode) && l.OrderQty > 0).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng phụ tùng (PartCode + OrderQty > 0)." });

    // ===== 🔴 #259 GHI CHÚ DÒNG > 1000 — `Ser_Order_PartDtl.Remark` =====
    // `FrmSer_Order_Part_Detail.cs:1274-1278` (md5 `51b5a41f` — KHỚP 2 máy):
    //     `int maxlength_Remark = 1000;`
    //     `e.ErrorText = string.Format("Ghi chú không được > {0} ký tự", maxlength_Remark);`
    // ⚠️ MÂU THUẪN NGƯỠNG lần thứ hai (tiếp #258) cho **cùng cột** `Ser_Order_PartDtl.Remark`:
    //   · **1000** ở màn chi tiết đơn đặt PT (đường nhập chính) ← port theo mức này
    //   · **400** ở lưới trong màn thanh toán NCC (`FrmSer_SupplierPayment.cs:1424`, md5 `98b8c976`)
    //   Theo luật đã chốt ở #258: giữ ngưỡng của ĐƯỜNG NHẬP CHÍNH, không siết xuống mức lưới sửa nhanh.
    // ⚠️ Nguồn dùng `string.Format` với chính biến ngưỡng ⇒ thông điệp luôn khớp số; port giữ nguyên dạng đó.
    foreach (var l in lines)
        if (!string.IsNullOrEmpty(l.Remark) && l.Remark!.Length > 1000)
            return Results.BadRequest(new { error = "Ghi chú không được > 1000 ký tự", partCode = l.PartCode });
    var no = existing?.OrderPartNo ?? (reqNo.Length > 0 ? reqNo : "OP" + DateTime.Now.ToString("yyMMddHHmmss"));
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    // ⚠️ Chỉ gán 9 trường mà `Ser_Order_Part_Save` thực sự gửi (+ vết ghi). Ba trường ngày/số đơn NCC
    //    KHÔNG gán ở đây — nguồn chỉ nhận chúng ở bước DUYỆT (`_Appr`).
    var o = new OrderPart
    {
        OrgId = t.OrgId, OrderPartNo = no,
        SupplierCode = dto.SupplierCode.Trim().ToUpperInvariant(),
        WarehouseCode = dto.WarehouseCode,
        OrderPartStatus = "P",
        DealerCode = dto.DealerCode, SupplierID = dto.SupplierID, PartGroupID = dto.PartGroupID,
        DeliveryFormCode = dto.DeliveryFormCode, DeliveryLocationCode = dto.DeliveryLocationCode,
        EstimatedDeliverDate = dto.EstimatedDeliverDate, VIN = dto.VIN, Remark = dto.Remark,
        OrderPartType = string.IsNullOrWhiteSpace(dto.OrderPartType) ? null : dto.OrderPartType!.Trim().ToUpperInvariant(),
        SupplierStatus = "1",   // TConst.SupplierStatus.SS_1 — chờ NCC duyệt
        CreateBy = who, LogLUDateTime = DateTime.Now, LogLUBy = who,
    };
    if (existing is not null)
    {
        // (D) SỬA: nguồn GIỮ NGUYÊN CreateDTime/CreateBy của bản ghi cũ (:293-294), chỉ thay phần còn lại.
        o.Id = existing.Id;
        o.CreatedAt = existing.CreatedAt;
        o.CreateBy = existing.CreateBy;
        db.Entry(existing).CurrentValues.SetValues(o);
        var oldLines = await db.OrderPartLines.Where(l => l.OrgId == t.OrgId && l.OrderPartId == existing.Id).ToListAsync();
        db.OrderPartLines.RemoveRange(oldLines);   // Save thay TRỌN bộ dòng
        await db.SaveChangesAsync();
        o = existing;
    }
    else { db.OrderParts.Add(o); await db.SaveChangesAsync(); }
    var newLines = new List<OrderPartLine>();
    foreach (var l in lines)
    {
        var line = new OrderPartLine
        {
            OrgId = t.OrgId, OrderPartId = o.Id,
            PartCode = l.PartCode.Trim().ToUpperInvariant(), PartName = l.PartName,
            OrderQty = l.OrderQty, Price = l.Price,
            // #235: khối giá + ngữ cảnh phụ tùng
            PartID = l.PartID, Unit = l.Unit, MinQuantity = l.MinQuantity,
            // 🔴 #259: chuẩn hoá đúng như nguồn làm ở nhánh hợp lệ (StandardizedString).
            Remark = StandardizeText(l.Remark),
            // ⚠️ Lúc TẠO chưa có số duyệt: nguồn khoá ô `QtyAppr` ở lưới tạo và chỉ mở khi duyệt.
            //    Mặc định lấy bằng số đặt để tổng tiền không ra 0; bước duyệt sẽ ghi đè.
            QtyAppr = l.QtyAppr ?? l.OrderQty,
            UPBeforeDc = l.UPBeforeDc ?? l.Price, DiscountRate = l.DiscountRate, VAT = l.VAT,
            // #307 §12: đơn vị nhập kho + tỷ lệ quy đổi phải GÁN được (đây LÀ cột thật của nguồn).
            UnitStockIn = l.UnitStockIn, ExchangeRate = l.ExchangeRate,
            // 🔴 #312 KHÔNG gán TotalQuantityIn / TotalQuantityInExchangeRate từ client nữa.
            //   Hai cột đó là DẪN XUẤT (SUM dòng phiếu nhập Status='3' theo OrderPartNo+PartID).
            //   #307 cho ghi qua DTO ⇒ client gửi gì cũng thành "đã nhập", sai lệch số liệu kho mà build
            //   vẫn xanh. Nay endpoint TÍNH lại khi đọc; DTO giữ hai trường cho tương thích nhưng BỎ QUA.
            LogLUDateTime = DateTime.Now, LogLUBy = who,
        };
        RecalcOrderPartLine(line);
        db.OrderPartLines.Add(line);
        newLines.Add(line);
    }
    RecalcOrderPartTotals(o, newLines);
    await db.SaveChangesAsync();
    return Results.Ok(new { o.OrderPartNo, o.SupplierCode, lines = lines.Count, status = o.OrderPartStatus });
}).RequireAuthorization();

app.MapGet("/api/orderparts/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var o = await db.OrderParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == no);
    if (o is null) return Results.NotFound(new { no });
    // ===== 🔴 #307 ĐƠN VỊ ĐẶT ≠ ĐƠN VỊ NHẬP KHO, và TỶ LỆ QUY ĐỔI phụ thuộc LOẠI ĐƠN =====
    // Nguồn `Ser_Order_Part_Get` (`A.02.OrderPart.cs:1782-1818`) — LIVE, WS gọi thẳng bản trần.
    //   `part_Unit` (đơn vị ĐẶT):  TST ⇒ `ISNULL(tmeu.TSTUnit, part.Unit)` · OTHER ⇒ `part.Unit`
    //   `part_UnitStockIn`:        **LUÔN** `part.Unit` — kho vẫn nhập bằng đơn vị lẻ của master
    //   `ExchangeRate`:            OTHER ⇒ **hằng 1.0** · TST ⇒ `ISNULL(tmeu.ExchangeRate, 1.0)`
    // ⚠️ Cả ba khối `case` đều **KHÔNG có `else`** ⇒ `OrderPartType` ngoài {TST, OTHER} cho ra **NULL**,
    //   KHÔNG phải rơi về giá trị của OTHER. Giữ đúng (whitelist).
    var lineRows = await db.OrderPartLines.Where(l => l.OrgId == t.OrgId && l.OrderPartId == o.Id).ToListAsync();

    // ===== 🔴 #312 ĐÍNH CHÍNH #307: SL ĐÃ NHẬP là **DẪN XUẤT**, không phải cột lưu =====
    // Nguồn `Ser_Order_Part_Get` (`A.02.OrderPart.cs:1717-1770`) dựng `TotalQuantityIn` bằng cách
    //   **SUM dòng phiếu NHẬP KHO** của các phiếu **`Status = '3'` (Kết thúc)**, gom theo
    //   (`OrderPartNo`, `PartID`) — KHÔNG đọc cột nào trên dòng đơn đặt.
    // #307 đã thêm hai cột lưu + cho ghi qua DTO ⇒ giá trị chỉ là thứ client gửi, không phản ánh kho.
    //   Nay TÍNH LẠI; cột lưu chỉ dùng làm **dự phòng** khi chưa có dữ liệu nhập (dữ liệu cũ).
    //
    // 🔴 CỘT L = **PHÉP CHIA**: `TST ⇒ TotalQuantityIn / ExchangeRate` · `OTHER ⇒ TotalQuantityIn`.
    //   ⚠️ **NGƯỢC CHIỀU** với cột M (SL chưa về ĐV bán) vốn **NHÂN** tỷ lệ (#307). Cùng một màn, cùng một
    //     tỷ lệ, hai phép ngược nhau: N→L là *quy về đơn vị ĐẶT*, Q→M là *quy sang đơn vị BÁN*.
    //   ⚠️ Khối `case` **không có `else`** ⇒ loại đơn ngoài {TST, OTHER} cho ra **NULL**.
    var stockInIds = await db.PartStockIns
        .Where(s => s.OrgId == t.OrgId && s.OrderPartNo == o.OrderPartNo && s.Status == "3")
        .Select(s => s.Id).ToListAsync();

    // ===== 🔴 #315 "NGÀY NHẬP CUỐI" (`StockInDateLastest`) — hai bất thường phải giữ nguyên =====
    // Nguồn `Ser_Order_Part_Get` (`A.02.OrderPart.cs:1819-1830`):
    //   `select top 1 pf.StockInDate from Ser_Inv_StockInDetail pt`
    //   `  inner join Ser_Inv_StockIn pf on pt.StockInID = pf.StockInID`
    //   `where pt.PartID = <dòng>.PartID and pf.OrderPartNo = <đơn>.OrderPartNo`
    //   `order by pf.CreatedDate desc`
    //
    // 🔴 BẤT THƯỜNG 1 — LỆCH TRỤC: sắp theo `CreatedDate` (giờ NHẬP LIỆU) nhưng lấy `StockInDate`
    //   (ngày NGHIỆP VỤ). Tên cột hứa `MAX(StockInDate)` nhưng thực ra trả **ngày nhập của phiếu được TẠO
    //   gần nhất**. Phiếu lùi ngày nhưng nhập liệu sau sẽ thắng ⇒ kết quả có thể **nhỏ hơn** max thật.
    //   (Đúng lớp `C0-quingentesimustricesimusnonus`: SELECT là GIÁ TRỊ, không phải KHOÁ ⇒ khả nghi thật,
    //    khác trường hợp `top 1 sr.ROID order by ActualDeliveryDate` ở #308 vốn hợp lệ.)
    //
    // 🔴 BẤT THƯỜNG 2 — KHÔNG LỌC TRẠNG THÁI, trong khi cột SỐ LƯỢNG ngay cạnh thì CÓ:
    //   `TotalQuantityIn` đi qua `#tbl_Ser_Inv_StockIn_Filter` có `and t.Status = '3'` (Kết thúc);
    //   `StockInDateLastest` **không có** điều kiện đó ⇒ tính cả phiếu nháp/huỷ.
    //   ⇒ Trên cùng một dòng lưới: "đã nhập 0" nhưng "ngày nhập cuối" vẫn có ngày. Bất nhất CÓ THẬT.
    //
    // Port giữ **nguyên cả hai bất thường** (luật 1:1) nhưng trả kèm giá trị đối chiếu để lộ ra:
    //   `stockInDateLastest`      — đúng nguồn (mọi trạng thái, theo CreatedDate)
    //   `stockInDateMaxFinished`  — `MAX(StockInDate)` chỉ phiếu Kết thúc (thứ người dùng thường TƯỞNG)
    var allStockIns = await db.PartStockIns
        .Where(s => s.OrgId == t.OrgId && s.OrderPartNo == o.OrderPartNo)
        .Select(s => new { s.Id, s.StockInDate, s.CreatedAt, s.Status })
        .ToListAsync();
    var allStockInIds = allStockIns.Select(s => s.Id).ToList();
    var allInLines = allStockInIds.Count == 0
        ? new List<(long StockInId, string PartCode)>()
        : (await db.PartStockInLines
                .Where(l => l.OrgId == t.OrgId && allStockInIds.Contains(l.StockInId))
                .Select(l => new { l.StockInId, l.PartCode })
                .ToListAsync())
            .Select(x => (x.StockInId, x.PartCode)).ToList();
    var stockInById = allStockIns.ToDictionary(s => s.Id, s => s);
    var inByPart = stockInIds.Count == 0
        ? new Dictionary<string, decimal>()
        : (await db.PartStockInLines
                .Where(l => l.OrgId == t.OrgId && stockInIds.Contains(l.StockInId))
                .ToListAsync())
            .GroupBy(l => l.PartCode).ToDictionary(g => g.Key, g => g.Sum(x => x.Quantity));
    var tstCodes = lineRows.Select(l => l.PartCode).Distinct().ToList();
    var tmeuMap = (await db.TstExchangeUnits
            .Where(x => x.OrgId == t.OrgId && tstCodes.Contains(x.TSTPartCode) && x.FlagActive == "1")
            .ToListAsync())
        .GroupBy(x => x.TSTPartCode).ToDictionary(g => g.Key, g => g.First());

    var lines = lineRows.Select(l =>
    {
        var isTst = o.OrderPartType == "TST";
        var isOther = o.OrderPartType == "OTHER";
        var tmeu = tmeuMap.TryGetValue(l.PartCode, out var m0) ? m0 : null;

        // đơn vị ĐẶT — không có else ⇒ null khi loại đơn lạ
        string? unitOrder = isTst ? (tmeu?.TSTUnit ?? l.Unit) : (isOther ? l.Unit : null);
        // tỷ lệ quy đổi — không có else ⇒ null khi loại đơn lạ
        decimal? rate = isTst ? (tmeu?.ExchangeRate ?? 1.0m) : (isOther ? 1.0m : (decimal?)null);

        var qtyAppr = l.QtyAppr ?? 0m;

        // #315 "ngày nhập cuối": lọc theo MÃ PT của dòng, KHÔNG lọc trạng thái phiếu (đúng nguồn),
        //   rồi sắp theo CreatedAt giảm dần và lấy StockInDate của phiếu đầu tiên.
        var partStockIns = allInLines.Where(x => x.PartCode == l.PartCode)
            .Select(x => stockInById.TryGetValue(x.StockInId, out var s) ? s : null)
            .Where(s => s is not null).Select(s => s!).ToList();
        DateTime? stockInDateLastest = partStockIns
            .OrderByDescending(s => s.CreatedAt)      // ⚠️ sắp theo giờ NHẬP LIỆU — đúng nguồn
            .Select(s => (DateTime?)s.StockInDate)    // ⚠️ nhưng LẤY ngày NGHIỆP VỤ
            .FirstOrDefault();
        // Giá trị đối chiếu: MAX ngày nghiệp vụ, chỉ phiếu Kết thúc — thứ người dùng thường TƯỞNG.
        DateTime? stockInDateMaxFinished = partStockIns.Where(s => s.Status == "3")
            .Select(s => (DateTime?)s.StockInDate).DefaultIfEmpty(null).Max();

        // #312: cột N TÍNH từ phiếu nhập; cột lưu của #307 chỉ là dự phòng cho dữ liệu cũ.
        decimal? totalIn = inByPart.TryGetValue(l.PartCode, out var qin) ? qin : l.TotalQuantityIn;
        // #312: cột L = N **CHIA** tỷ lệ (chỉ TST); OTHER giữ nguyên N; loại đơn lạ ⇒ null (không có else).
        decimal? totalInExch = isOther ? totalIn
            : (isTst
                ? (totalIn.HasValue
                    ? totalIn.Value / ((tmeu?.ExchangeRate ?? 1.0m) == 0m ? 1.0m : (tmeu?.ExchangeRate ?? 1.0m))
                    : (decimal?)null)
                : (decimal?)null);
        var inQty = totalInExch ?? 0m;
        // Cột Q — SL chưa về tính theo ĐƠN VỊ ĐẶT.
        var remain = qtyAppr - inQty;
        // Cột M — SL chưa về theo ĐƠN VỊ BÁN. ⚠️ Nguồn CHỈ nhân tỷ lệ cho TST; OTHER giữ nguyên số Q.
        decimal? remainExchange = isOther ? remain
            : (isTst ? remain * (tmeu?.ExchangeRate ?? 1.0m) : (decimal?)null);

        return new
        {
            l.PartCode, l.PartName, l.OrderQty, l.Price, l.OrderPartStatusDtl,
            // #235: 17 cột bổ sung (§12 — có ở cả GET lẫn POST)
            l.PartID, l.Unit, l.MinQuantity, l.Remark, l.QtyAppr,
            l.UPBeforeDc, l.DiscountRate, l.VAT,
            l.TPBeforeDc, l.UPAfterDc, l.TPAfterDc, l.ValVAT, l.TPAfterVAT,
            l.OrderSuppierNo, l.TSTID, l.LogLUDateTime, l.LogLUBy,
            lineTotal = l.OrderQty * l.Price,
            // #307 §12: bốn cột mới + ba giá trị TÍNH của nguồn
            partUnit = unitOrder,                                  // part_Unit — đơn vị ĐẶT
            unitStockIn = l.UnitStockIn ?? l.Unit,                 // part_UnitStockIn — LUÔN đơn vị master
            exchangeRate = rate,
            totalQuantityIn = totalIn,                             // cột N — TÍNH từ phiếu nhập (#312)
            totalQuantityInExchangeRate = totalInExch,             // cột L — N CHIA tỷ lệ (#312)
            totalQuantityInStored = l.TotalQuantityIn,             // cột lưu cũ (#307) — chỉ để đối chiếu
            // #315 "Ngày nhập cuối" — xem hai bất thường ở chú thích đầu endpoint.
            stockInDateLastest,
            stockInDateMaxFinished,
            stockInDateMismatch = stockInDateLastest != stockInDateMaxFinished,
            totalQuantityRemain = remain,                          // cột Q — ĐV đặt
            totalQuantityRemainExchangeRate = remainExchange,      // cột M — ĐV bán
        };
    }).ToList();
    return Results.Ok(new { o.OrderPartNo, o.SupplierCode, o.OrderPartStatus, o.OrderPartType,
                            stockInDateNote = "stockInDateLastest theo ĐÚNG nguồn: sắp theo giờ NHẬP LIỆU, lấy ngày NGHIỆP VỤ, "
                                            + "và KHÔNG lọc trạng thái phiếu (khác cột số lượng vốn chỉ tính phiếu Kết thúc). "
                                            + "stockInDateMaxFinished là MAX ngày nghiệp vụ của phiếu Kết thúc — dùng để đối chiếu.",
                            unitNote = "part_Unit = đơn vị ĐẶT (TST lấy theo hãng); unitStockIn = đơn vị NHẬP KHO (luôn của master). "
                                     + "OrderPartType ngoài {TST, OTHER} ⇒ đơn vị và tỷ lệ quy đổi trả NULL (nguồn không có else).",
                            count = lines.Count, lines,
                            total = lines.Sum(x => x.lineTotal),
                            // #235: tổng THẬT của nguồn là tiền sau VAT, tính từ SL DUYỆT.
                            totalAfterVAT = lines.Sum(x => x.TPAfterVAT ?? 0m),
                            o.TotalValOrderBeforeDc, o.TotalValOrderAfterDc, o.TotalValOrderAfterVAT,
                            // Tiền chiết khấu của đơn = HIỆU hai cột tổng — nguồn KHÔNG lưu thành cột riêng.
                            valDiscountOfOrder = (o.TotalValOrderBeforeDc ?? 0m) - (o.TotalValOrderAfterDc ?? 0m),
                            o.ValDiscount });
}).RequireAuthorization();

// Gửi NCC (approve) / Hoàn thành (finish) / TỪ CHỐI (reject) — nguồn TConst.OrderPartStatus: P → A → F, và R.
// 🔴 Port cũ thiếu hẳn `Rejected`(R) ⇒ không có đường từ chối đơn đặt phụ tùng.
// Thao tác ở header ĐỒNG BỘ xuống trạng thái từng dòng, đúng cách nguồn ghi OrderPartStatusDtl.
// 🔴 #234 DUYỆT NHẬN THÊM DỮ LIỆU: `Ser_Order_Part_Appr` (Ser_Order_PartService.cs:182) gửi
//    `EstimatedDeliverDate` · `RequestSuppierDate` · `ResponseSuppierDate` · `OrderSuppierNo` · `Remark`,
//    trong đó **ba trường giữa KHÔNG có trong `_Save`** ⇒ chỉ nhập được lúc DUYỆT. Port cũ coi duyệt là
//    thao tác "đổi trạng thái trơn" nên mất hẳn bước nhập số đơn NCC và hai mốc ngày.
//    (đúng lớp lỗi đã ghi: "Save→Approve split rớt bước hậu-duyệt")
app.MapPost("/api/orderparts/{no}/{action}", async (string no, string action, OrderPartActionDto? dto,
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "finish" or "reject")) return Results.BadRequest(new { error = "action = approve|finish|reject" });
    no = no.Trim().ToUpperInvariant();
    var o = await db.OrderParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == no);
    if (o is null) return Results.NotFound(new { no });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    string lineStatus;
    if (action == "approve")
    {
        if (o.OrderPartStatus != "P") return Results.BadRequest(new { error = "Chỉ gửi NCC đơn Mới tạo." });

        // ===== 🔴 #246 DUYỆT = GỬI ĐƠN HÀNG SANG NCC QUA BRAVO, không phải đổi cờ =====
        // Nguồn `Ser_Order_Part_Appr` (BizCarSv.A.02.OrderPart.cs:2691), khối gọi API tại :3258-3320.
        // BƯỚC 3B: md5 `72e6623f` (5014 dòng) — KHỚP 2 máy (đo ở #236).
        // Phát hiện bằng sweep "hàm nào gọi `CallBravo`": toàn `TERP.BizCarSv` chỉ có **5 hàm**, và
        //   `Ser_Order_Part_Appr` là hàm tôi đã port ở #234 mà **không biết** nó gọi Bravo.
        //
        // Nguồn dựng `RQ_SalesOrderHdr` gồm **header + TOÀN BỘ DÒNG** (Unit · ItemName · RequestQuantity ·
        //   EstimatedTimeDelivery · Remark — :3230-3248), `GetToken` → `CallBravo`, rồi:
        //   · phản hồi RỖNG  ⇒ ném `Ser_Order_Part_Appr_SentTST_SyncFail`
        //   · `Status != "OK"` ⇒ cũng ném `..._SyncFail`
        //   ⇒ **đơn KHÔNG được duyệt** khi NCC chưa nhận. #234 tôi cho duyệt vô điều kiện — GAP đã vá.
        //
        // ⚠️ KHÔNG port khối update `t.OrderSuppierNo` / `t.TSTID` từ phản hồi: cả khối **BỊ COMMENT**
        //    ở nguồn (:3331-3348). Vì thế `OrderSuppierNo` vẫn do người duyệt NHẬP TAY (đúng như #234).
        var syncOkOp = string.IsNullOrWhiteSpace(dto?.SyncStatus)
                       || string.Equals(dto!.SyncStatus, "OK", StringComparison.OrdinalIgnoreCase);
        if (!syncOkOp)
            return Results.BadRequest(new
            {
                error = "Gửi đơn hàng sang NCC thất bại — đơn KHÔNG được duyệt.",   // ` Appr_SentTST_SyncFail
                syncStatus = dto?.SyncStatus, description = dto?.SyncDescription,
            });

        o.OrderPartStatus = "A"; o.SentAt = DateTime.Now; o.ApprBy = who; lineStatus = "A";
        o.SupplierStatus = "2";   // SS_2: đã duyệt, chờ NCC hoàn thiện
        // 5 trường mà _Appr gửi lên (chỉ ghi khi client có truyền — không xoá dữ liệu cũ)
        if (dto?.EstimatedDeliverDate is not null) o.EstimatedDeliverDate = dto.EstimatedDeliverDate;
        if (dto?.RequestSuppierDate is not null) o.RequestSuppierDate = dto.RequestSuppierDate;
        if (dto?.ResponseSuppierDate is not null) o.ResponseSuppierDate = dto.ResponseSuppierDate;
        if (!string.IsNullOrWhiteSpace(dto?.OrderSuppierNo)) o.OrderSuppierNo = dto!.OrderSuppierNo!.Trim();
        if (!string.IsNullOrWhiteSpace(dto?.Remark)) o.Remark = dto!.Remark;

        // 🔴 #235: `Ser_Order_Part_Appr` gửi kèm CẢ BỘ DÒNG (`ds_Ser_Order_PartDtl`) — duyệt là lúc nhập
        //    `QtyAppr` / `UPBeforeDc` / `DiscountRate` / `VAT` rồi tính lại 5 cột dẫn xuất.
        //    (lưới của nguồn KHOÁ `QtyOrd` và `Price`, chỉ mở đúng mấy ô này — `_lstColNotAllowEdit`,
        //     FrmSer_Order_Part_Detail.cs:505)
        if (dto?.Lines is { Count: > 0 })
        {
            var byCode = await db.OrderPartLines.Where(x => x.OrgId == t.OrgId && x.OrderPartId == o.Id).ToListAsync();
            foreach (var d in dto.Lines)
            {
                if (string.IsNullOrWhiteSpace(d.PartCode)) continue;
                var code = d.PartCode.Trim().ToUpperInvariant();
                var line = byCode.FirstOrDefault(x => x.PartCode == code);
                if (line is null) continue;
                if (d.QtyAppr is not null) line.QtyAppr = d.QtyAppr;
                if (d.UPBeforeDc is not null) line.UPBeforeDc = d.UPBeforeDc;
                if (d.DiscountRate is not null) line.DiscountRate = d.DiscountRate;
                if (d.VAT is not null) line.VAT = d.VAT;
                if (!string.IsNullOrWhiteSpace(d.Remark)) line.Remark = StandardizeText(d.Remark);
                line.OrderSuppierNo = o.OrderSuppierNo;
                line.LogLUDateTime = DateTime.Now; line.LogLUBy = who;
                RecalcOrderPartLine(line);
            }
            RecalcOrderPartTotals(o, byCode);
        }
    }
    else if (action == "finish")
    {
        if (o.OrderPartStatus != "A") return Results.BadRequest(new { error = "Chỉ hoàn thành đơn Đã gửi NCC." });
        o.OrderPartStatus = "F"; o.FinishedAt = DateTime.Now; o.FinishBy = who; lineStatus = "F";
        o.SupplierStatus = "4";   // SS_4: đã hoàn thiện
    }
    else
    {
        // Từ chối được khi đơn CHƯA hoàn thành.
        if (o.OrderPartStatus == "F") return Results.BadRequest(new { error = "Đơn đã hoàn thành, không từ chối được." });
        if (o.OrderPartStatus == "R") return Results.BadRequest(new { error = "Đơn đã bị từ chối." });
        o.OrderPartStatus = "R"; lineStatus = "R";
        o.SupplierStatus = "7";   // SS_7: đơn lỗi, chờ kinh doanh điều chỉnh
    }
    // ===== 🔴 #346 ĐÓNG DẤU `SupplierLUDTime` mỗi khi `SupplierStatus` đổi =====
    // Nguồn `Ser_Order_Part_ApprTST` (`BizCarSv.A.02.OrderPart.cs:3403`) cập nhật CÙNG MỘT CỤM:
    //   `t.SupplierStatus = f.SupplierStatus` · `t.DeliveryFormCode = f.DeliveryFormCode`
    //   · `t.SupplierLUDTime = f.SupplierLUDTime`
    // ⇒ Ba trường đi liền nhau; port cũ đổi `SupplierStatus` ở **ba** chỗ mà không hề đóng dấu mốc
    //   ⇒ không truy được **khi nào** phía nhà cung cấp đổi trạng thái.
    // (Ghi bằng SQL `update … set` nên máy quét theo `["X"] =` không thấy — dạng ghi thứ 4, lệ #314.)
    o.SupplierLUDTime = DateTime.Now;
    o.LogLUDateTime = DateTime.Now; o.LogLUBy = who;

    // Đồng bộ trạng thái từng dòng (nguồn ghi OrderPartStatusDtl trong cùng thao tác).
    var lines = await db.OrderPartLines.Where(l => l.OrgId == t.OrgId && l.OrderPartId == o.Id).ToListAsync();
    foreach (var l in lines) l.OrderPartStatusDtl = lineStatus;

    await db.SaveChangesAsync();
    return Results.Ok(new { o.OrderPartNo, status = o.OrderPartStatus, linesUpdated = lines.Count });
}).RequireAuthorization();

// Duyệt / từ chối TỪNG DÒNG đơn đặt — khả năng nguồn có nhờ cột OrderPartStatusDtl riêng của dòng.
app.MapPost("/api/orderparts/{no}/lines/{partCode}/status", async (
    string no, string partCode, OrderPartLineStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    partCode = partCode.Trim().ToUpperInvariant();
    var o = await db.OrderParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == no);
    if (o is null) return Results.NotFound(new { no });
    var line = await db.OrderPartLines.FirstOrDefaultAsync(l => l.OrgId == t.OrgId && l.OrderPartId == o.Id && l.PartCode.ToUpper() == partCode);
    if (line is null) return Results.NotFound(new { no, partCode });

    string[] lineStatuses = { "P", "A", "F", "R" };
    var target = (dto.ToStatus ?? "").Trim().ToUpperInvariant();
    if (!lineStatuses.Contains(target))
        return Results.BadRequest(new { error = "ToStatus = P (mới tạo) | A (đã duyệt) | F (hoàn thành) | R (từ chối)" });

    line.OrderPartStatusDtl = target;
    await db.SaveChangesAsync();
    return Results.Ok(new { o.OrderPartNo, line.PartCode, lineStatus = line.OrderPartStatusDtl });
}).RequireAuthorization();

// ===== Khách hàng dịch vụ (Ser_Customer — port 1:1 FrmCustomerInfo) =====
// ===== 🔴 #316 SỐ ĐIỆN THOẠI HIỂN THỊ: `isnull(Tel, Mobile)` — port cũ THIẾU =====
// Nguồn dùng luật này ở **34 chỗ** trên 6 file (`Customer` · `Debit` · `Inventory.Quote` ·
//   `Inventory.StockOut` · `Service.Report` · `WH`), alias đủ kiểu: `CusPhone` · `Phone` · `phone` ·
//   `cusphone` · `CusTel` — và **KHÔNG có lấy một chỗ nào theo chiều ngược** (`isnull(Mobile, Tel)`).
//   ⇒ Đây là luật **thống nhất toàn hệ**: ĐIỆN THOẠI BÀN đứng trước, DI ĐỘNG là dự phòng.
//   Port cũ trả `Mobile` và `Tel` thành hai cột rời, không có cột "số để gọi" ⇒ client tự chọn, dễ chọn
//   ngược với WinForm.
//
// ⚠️ BIẾN THỂ **BA CẤP** ở 4 chỗ (`Appointment.cs:1496/1691` · `TVO.cs:958` · `WH.cs:3227`):
//   `isnull(cus.Tel, isnull(cus.mobile, cus.contTel))` — thêm ĐT người liên hệ làm cấp 3.
//
// 🔴 KHÔNG ÁP DỤNG CHO PAYLOAD ĐỐI TÁC — luật ở đó KHÁC HẲN, đã kiểm:
//   `ZTemp.cs:15666`  : `Isnull(sc.Tel, '')`  ⇒ **chỉ Tel**, hết thì CHUỖI RỖNG, không rơi sang Mobile.
//   `Inventory.StockIn.cs:8960/9436` và `StockOut.cs:18959/19635` : `'' CustomerPhoneNo` ⇒ **hằng rỗng**,
//     payload xuất kho **không gửi số điện thoại** chút nào.
//   `HCC_Appointment_AddOSX` (**máy 150**, `BizCarSv.HCC.cs:83`) : `cus.Mobile CustomerPhone` ⇒ **chỉ Mobile**,
//     ngược hẳn luật lưới. (#317 bổ sung — #316 ghi "ba luật" là **THIẾU MỘT**.)
//   ⇒ **BỐN** luật khác nhau cho cùng khái niệm "số điện thoại khách". Đừng gom một helper dùng chung.
//
// ⚠️ BẪY ĐẶT TÊN của nguồn: `Inventory.Quote.cs:2047` đặt alias là **`cusMobile`** cho giá trị
//   `isnull(cus.Tel, cus.mobile)` — tên nói "mobile" nhưng giá trị **ưu tiên Tel**. Đọc tên mà suy ra cột
//   là sai (cùng lớp `C0-…tricesimusoctavus`).
// ⚠️ `Customer.cs:17839` còn bọc `Replace(…, ' ', '')` — **bỏ khoảng trắng** trong số, chỉ ở chỗ đó.

// Số điện thoại HIỂN THỊ theo nguồn: bàn trước, di động sau.
static string? CusDisplayPhone(string? tel, string? mobile)
    => !string.IsNullOrWhiteSpace(tel) ? tel : (!string.IsNullOrWhiteSpace(mobile) ? mobile : null);
// Biến thể BA CẤP (lịch hẹn / TVO / WH): thêm ĐT người liên hệ làm dự phòng cuối.
static string? CusDisplayPhone3(string? tel, string? mobile, string? contTel)
    => CusDisplayPhone(tel, mobile) ?? (!string.IsNullOrWhiteSpace(contTel) ? contTel : null);

app.MapGet("/api/servicecustomers", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var query = db.ServiceCustomers.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q))
        query = query.Where(c => c.CusName.Contains(q) || c.CusCode.Contains(q.ToUpper())
            || (c.Mobile != null && c.Mobile.Contains(q)) || (c.Tel != null && c.Tel.Contains(q)) || (c.TaxCode != null && c.TaxCode.Contains(q)));
    var rows = await query.OrderBy(c => c.CusName).Take(500).ToListAsync();
    var items = rows.Select(c => new
    { c.CusCode, c.SalesCusID, c.CusName, c.CusTypeID, c.Address, c.Mobile, c.Tel, c.Email, c.TaxCode, c.Sex, c.DOB, c.ContName, c.ContMobile,
      // #221 §12: 15 trường mới phải chiếu ở CẢ GET
      c.DealerCode, c.ProvinceCode, c.DistrictCode, c.Fax, c.Website, c.IDCardNo, c.Bank, c.BankAccountNo,
      c.OrgTypeID, c.IsNormal, c.IsContact, c.ContAddress, c.ContFax, c.ContSex, c.Note,
      // #316: số ĐỂ GỌI theo đúng nguồn (bàn trước, di động sau) + biến thể 3 cấp.
      cusPhone = CusDisplayPhone(c.Tel, c.Mobile),
      cusPhone3 = CusDisplayPhone3(c.Tel, c.Mobile, c.ContTel),
      // Bỏ khoảng trắng — nguồn chỉ làm ở MỘT chỗ (Customer.cs:17839), trả riêng để không đổi cột chính.
      cusPhoneNoSpace = CusDisplayPhone(c.Tel, c.Mobile)?.Replace(" ", ""),
    }).ToList();
    return Results.Ok(new { count = items.Count,
        phoneNote = "cusPhone = isnull(Tel, Mobile) — luật hiển thị của nguồn (34 chỗ, không có chiều ngược). "
                  + "KHÔNG dùng cho payload đối tác: ZTemp dùng isnull(Tel,'') và payload xuất/nhập kho gửi rỗng.",
        items });
}).RequireAuthorization();

// ===== 🔴 #226 DANH SÁCH KHÁCH HÀNG KÈM XE (phân trang) — `SerCustomerCarGetPagingALL` =====
// Màn gốc: `Views/Customer/FrmCustomerList.cs` (825 dòng, DMSCarSv) — 6 handler, phân loại theo luật
//   `C0-trecentesimusquadragesimusquartus`:
//     lệnh thật → `btnSearch` (861) · `btnRefresh` · `gridPCLaoDong_Click` (nạp chi tiết 1 KH)
//     điều hướng → `btnNhapMoi` (mở form nhập mới) · `btnExportExcel` (xuất file tại client)
//     bỏ qua → `btnThoat`
// Tầng service: `MstCustomerService.cs:861`; biz `BizCarSv.Customer.cs:1885` (`Ser_CustomerCar_GetAllDL`).
// BƯỚC 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy.
//
// 🔴 KHÁC #224 (`SerCustomerGetPaging`): màn này tra **KHÁCH HÀNG KÈM XE** nên có thêm 4 ô lọc theo XE
//    (`PlateNo` · `FrameNo` · `EngineNo`) và 2 ô giấy tờ (`IDCardNo` · `TaxCode`), cộng cờ `IsActive`.
//    ⇒ Không dùng lại endpoint #224; đây là hai màn khác nhau (luật `C0-ducentesimusvicesimussecundus`:
//      hai báo cáo/màn cùng cụm có thể lọc khác nhau, không suy từ cái đã port).
//
// 🔴 Bọc `%…%`: tầng service bọc **8 ô** (CusName · Phone · Address · PlateNo · FrameNo · EngineNo ·
//    IDCardNo · TaxCode) ⇒ so khớp CHỨA. Riêng `strCusID` và `strIsActive` **không bọc** ⇒ khớp CHÍNH XÁC.
// 🔴 Phân trang y như #224: cắt ở tầng client, trang đánh số từ **1**, tổng số dòng lấy từ bảng
//    `Ser_Customer_Summary` ⇒ trả `totalRows`/`totalPages`.
app.MapGet("/api/servicecustomers/cars-search", async (AppDbContext db, ITenantContext t,
    string? cusId, string? cusName, string? phone, string? address,
    string? plateNo, string? frameNo, string? engineNo, string? idCardNo, string? taxCode,
    string? isActive, int pageSize = 20, int currentPage = 1) =>
{
    if (pageSize <= 0) pageSize = 20;
    if (currentPage <= 0) currentPage = 1;

    // Ghép khách hàng × xe theo CusID (nguồn join Ser_Customer với Ser_Car).
    var qy = from c in db.ServiceCustomers.Where(x => x.OrgId == t.OrgId)
             join car in db.ServiceCars.Where(x => x.OrgId == t.OrgId) on c.CusCode equals car.CusID into gj
             from car in gj.DefaultIfEmpty()
             select new { c, car };

    // khớp CHÍNH XÁC (nguồn không bọc %…%)
    if (!string.IsNullOrWhiteSpace(cusId)) qy = qy.Where(x => x.c.CusCode == cusId!.Trim());
    if (!string.IsNullOrWhiteSpace(isActive)) qy = qy.Where(x => x.car != null && x.car.FlagActive == isActive!.Trim());

    // khớp CHỨA (nguồn bọc %…% ở tầng service)
    if (!string.IsNullOrWhiteSpace(cusName)) qy = qy.Where(x => x.c.CusName != null && x.c.CusName.ToLower().Contains(cusName!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(address)) qy = qy.Where(x => x.c.Address != null && x.c.Address.ToLower().Contains(address!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(phone)) qy = qy.Where(x => (x.c.Mobile != null && x.c.Mobile.Contains(phone!.Trim())) || (x.c.Tel != null && x.c.Tel.Contains(phone!.Trim())));
    if (!string.IsNullOrWhiteSpace(idCardNo)) qy = qy.Where(x => x.c.IDCardNo != null && x.c.IDCardNo.Contains(idCardNo!.Trim()));
    if (!string.IsNullOrWhiteSpace(taxCode)) qy = qy.Where(x => x.c.TaxCode != null && x.c.TaxCode.Contains(taxCode!.Trim()));
    if (!string.IsNullOrWhiteSpace(plateNo)) qy = qy.Where(x => x.car != null && x.car.PlateNo != null && x.car.PlateNo.ToLower().Contains(plateNo!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(frameNo)) qy = qy.Where(x => x.car != null && x.car.FrameNo.ToLower().Contains(frameNo!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(engineNo)) qy = qy.Where(x => x.car != null && x.car.EngineNo != null && x.car.EngineNo.ToLower().Contains(engineNo!.Trim().ToLower()));

    var totalRows = await qy.CountAsync();          // ` bảng Ser_Customer_Summary của nguồn
    var startRow = (currentPage - 1) * pageSize;    // nguồn đánh số trang từ 1

    var items = await qy.OrderBy(x => x.c.CusName).ThenBy(x => x.car != null ? x.car.FrameNo : "")
        .Skip(startRow).Take(pageSize)
        .Select(x => new
        {
            x.c.CusCode, x.c.CusName, x.c.Mobile, x.c.Tel, x.c.Address, x.c.IDCardNo, x.c.TaxCode, x.c.DOB,
            frameNo = x.car != null ? x.car.FrameNo : null,
            plateNo = x.car != null ? x.car.PlateNo : null,
            engineNo = x.car != null ? x.car.EngineNo : null,
            modelCode = x.car != null ? x.car.ModelCode : null,
            colorCode = x.car != null ? x.car.ColorCode : null,
            flagActive = x.car != null ? x.car.FlagActive : null
        }).ToListAsync();

    return Results.Ok(new
    {
        totalRows,
        totalPages = totalRows == 0 ? 0 : (int)Math.Ceiling(totalRows / (double)pageSize),
        pageSize, currentPage, startRow, count = items.Count, items,
        note = "Khách hàng LEFT JOIN xe — khách chưa có xe vẫn lên danh sách (nguồn dùng Ser_Customer × Ser_Car)."
    });
}).RequireAuthorization();

// ===== 🔴 #224 TÌM KHÁCH HÀNG CÓ PHÂN TRANG — `SerCustomerGetPaging` → `Ser_Customer_Get` =====
// Màn gốc: `Views/Customer/FrmCustomerInfoSearch.cs` (305 dòng, DMSCarSv) — hai nút `bntPrivous` · `btnNext`
//   (lưu ý: nút "Previous" trong nguồn viết SAI CHÍNH TẢ là `bntPrivous` — grep theo `btn` sẽ trượt).
// Tầng service: `TERP.HTCServiceClient/DbServices/MstCustomerService.cs:708`; biz `BizCarSv.Customer.cs:423`.
// BƯỚC 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy.
//
// 🔴 BA CHI TIẾT của cơ chế phân trang nguồn:
//  1. **Phân trang ở TẦNG CLIENT**: biz `Ser_Customer_Get` trả về TOÀN BỘ kết quả; service tự cắt trang bằng
//     `startRow = (CurrentPage - 1) * PageSize` ⇒ trang bắt đầu từ **1**, không phải 0.
//  2. Nguồn trả kèm bảng **`Ser_Customer_Summary`** chứa **tổng số dòng** (`myRowCount`) — client dùng để
//     tính số trang. Port trả trường `totalRows` + `totalPages` đúng vai trò đó.
//  3. Ba ô tìm kiếm được service **tự bọc `%…%`** trước khi gửi (`strCusNamePattern`, `strAddressPattern`,
//     `strPhonePattern`) ⇒ so khớp CHỨA; ô `strCusID` thì KHÔNG bọc ⇒ so khớp **chính xác**.
//     Giữ đúng sự bất đối xứng này.
app.MapGet("/api/servicecustomers/search", async (AppDbContext db, ITenantContext t,
    string? cusId, string? cusName, string? address, string? phone, int pageSize = 20, int currentPage = 1) =>
{
    if (pageSize <= 0) pageSize = 20;
    if (currentPage <= 0) currentPage = 1;   // nguồn đánh số trang từ 1

    var qy = db.ServiceCustomers.Where(c => c.OrgId == t.OrgId);
    // ô mã KH: so khớp CHÍNH XÁC (nguồn không bọc %…%)
    if (!string.IsNullOrWhiteSpace(cusId)) qy = qy.Where(c => c.CusCode == cusId!.Trim());
    // ba ô còn lại: nguồn bọc %…% ⇒ CHỨA
    if (!string.IsNullOrWhiteSpace(cusName))
        qy = qy.Where(c => c.CusName != null && c.CusName.ToLower().Contains(cusName!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(address))
        qy = qy.Where(c => c.Address != null && c.Address.ToLower().Contains(address!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(phone))
        qy = qy.Where(c => (c.Mobile != null && c.Mobile.Contains(phone!.Trim()))
                        || (c.Tel != null && c.Tel.Contains(phone!.Trim())));

    // tương ứng bảng `Ser_Customer_Summary` của nguồn
    var totalRows = await qy.CountAsync();
    var startRow = (currentPage - 1) * pageSize;

    var items = await qy.OrderBy(c => c.CusName).Skip(startRow).Take(pageSize)
        .Select(c => new { c.CusCode, c.CusName, c.CusTypeID, c.Address, c.Mobile, c.Tel, c.Email, c.TaxCode,
                           c.Sex, c.DOB, c.DealerCode, c.ProvinceCode, c.DistrictCode, c.IDCardNo })
        .ToListAsync();

    return Results.Ok(new
    {
        totalRows,
        totalPages = totalRows == 0 ? 0 : (int)Math.Ceiling(totalRows / (double)pageSize),
        pageSize, currentPage, startRow,
        count = items.Count, items
    });
}).RequireAuthorization();

app.MapPost("/api/servicecustomers", async (ServiceCustomerDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.CusName)) return Results.BadRequest(new { error = "Cần CusName." });
    if (string.IsNullOrWhiteSpace(dto.Mobile) && string.IsNullOrWhiteSpace(dto.Tel)) return Results.BadRequest(new { error = "Cần SĐT di động hoặc cố định." });
    var code = string.IsNullOrWhiteSpace(dto.CusCode) ? "CUS" + DateTime.Now.ToString("yyMMddHHmmss") : dto.CusCode.Trim().ToUpperInvariant();
    var c = await db.ServiceCustomers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CusCode == code);
    if (c is null) { c = new ServiceCustomer { OrgId = t.OrgId, CusCode = code }; db.ServiceCustomers.Add(c); }
    c.CusName = dto.CusName; c.CusTypeID = dto.CusTypeID; c.Address = dto.Address; c.Mobile = dto.Mobile; c.Tel = dto.Tel;
    c.Email = dto.Email; c.TaxCode = dto.TaxCode; c.Sex = dto.Sex; c.DOB = dto.DOB;
    // #362 §12: khong co dong nay thi SalesCusID la COT CHET — dung benh #337/#342.
    c.SalesCusID = dto.SalesCusID;
    c.ContName = dto.ContName; c.ContMobile = dto.ContMobile; c.ContTel = dto.ContTel; c.ContEmail = dto.ContEmail; c.UpdatedAt = DateTime.Now;
    // ===== #221 parity: 15 trường còn thiếu của `CustomerCreate`/`CustomerUpdate` =====
    c.DealerCode = dto.DealerCode;
    c.ProvinceCode = dto.ProvinceCode;
    c.DistrictCode = dto.DistrictCode;
    c.Fax = dto.Fax;
    c.Website = dto.Website;
    c.IDCardNo = dto.IDCardNo;
    c.Bank = dto.Bank;
    c.BankAccountNo = dto.BankAccountNo;
    c.OrgTypeID = dto.OrgTypeID;
    c.IsNormal = dto.IsNormal;
    c.IsContact = dto.IsContact;
    c.ContAddress = dto.ContAddress;
    c.ContFax = dto.ContFax;
    c.ContSex = dto.ContSex;
    c.Note = dto.Note;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CusCode, c.CusName });
}).RequireAuthorization();

// Nhập khách hàng hàng loạt từ Excel (port 1:1 FrmImportCustomer) — tái dùng ServiceCustomer.
// ===== 🔴 #332 TẠO KHÁCH **KÈM DANH SÁCH XE** trong một lời gọi (kênh máy tính bảng) =====
// Nguồn `CarSv_Ser_CustomerCar_Create_*` (`BizCarSv.Tab.cs`). MiniHTC vốn chỉ có hai cổng RỜI
//   (`POST /api/servicecustomers` và `POST /api/servicecars`) ⇒ thiếu cổng gộp mà máy tính bảng dùng.
//
// 🔴 TRACE TWIN — **HAI đường LIVE gọi HAI bản KHÁC NHAU**, không phải một bản thắng:
//   `Ser_CustomerService.cs:54`  (đi qua WS, **máy tính bảng**) → WS `WSCarSvTab.asmx.cs:1972`
//                                                              → `…_New20190924`
//   `Ser_CustomerService.cs:142` (gọi `biz` **trực tiếp, tại chỗ**) → `…_New20220926`
//   Bản trần `CarSv_Ser_CustomerCar_Create` (`:13123`) KHÔNG ai gọi ⇒ CHẾT.
//   ⇒ Không thể chọn "bản mới nhất" làm bản đúng: **cả hai đều đang chạy**, khác nhau theo ĐƯỜNG GỌI.
//
// 🔴 ĐỘ LỆCH giữa hai bản LIVE — đo bằng tập cột ghi, đúng **MỘT** cột: **`PlateColorCode`**.
//   Khách + xe đều ghi y hệt nhau; chỉ bản 2022 nhận thêm `strPlateColorCode` và gọi
//   `SerCarCreateX20220926` thay cho `SerCarCreateX` (helper cũng chỉ hơn đúng cột đó).
//   ⇒ **Xe tạo từ MÁY TÍNH BẢNG mất phân loại màu biển**; xe tạo tại chỗ thì có. Cùng bảng `Ser_Car`.
//   MiniHTC không chia hai đường ⇒ port **đường đầy đủ (2022)**, và trả `plateColorNote` để chỗ nào
//   đối chiếu với máy tính bảng còn biết vì sao dữ liệu web đầy hơn.
//
// ⚠️ BƯỚC 3B: `BizCarSv.Tab.cs` **md5 KHÁC nhau** giữa laptop và máy 150 (15341 vs 15323 dòng) —
//   nhưng năm hàm của cụm này dịch đều **+18 dòng** và md5 của trọn vùng `12431-13847` (laptop) ≡
//   `12449-13865` (150) ⇒ **vùng này giống hệt**; chênh lệch nằm ở đoạn trên (đã xử lý ở #319).
//   Ghi lại vì file khác md5 mà vùng cần đọc lại giống nhau là trường hợp dễ kết luận vội cả hai chiều.
//
// 🔴 GUARD GIỚI TÍNH — bạch danh sách đúng HAI giá trị:
//   `if (!IsNullOrEmpty(strGender) && strGender != Flag.Active && strGender != Flag.Inactive) throw`
//   ⇒ `Sex` nhận **rỗng · "1" · "0"** (KHÔNG phải "M"/"F"), rỗng vẫn hợp lệ.
//   ⚠️ Guard này chỉ có ở họ `*_CustomerCar_*Create` (Tab · Sales · MBS), **KHÔNG** có ở
//     `Ser_Customer_Create` trần ⇒ **không** thêm guard vào `POST /api/servicecustomers` đang có
//     (lệ #299: không tự chế luật cho cổng mà nguồn không chặn).
app.MapPost("/api/servicecustomers/with-cars", async (CustomerWithCarsDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.CusName)) return Results.BadRequest(new { error = "Cần CusName." });
    var dealer = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    if (dealer.Length == 0) return Results.BadRequest(new { error = "Cần DealerCode." });

    var gender = (dto.Gender ?? "").Trim();
    if (gender.Length > 0 && gender != "1" && gender != "0")
        return Results.BadRequest(new { error = "Giới tính không hợp lệ: chỉ nhận rỗng, \"1\" hoặc \"0\".", gender });

    var now = DateTime.Now;
    var cusId = "TAB" + now.ToString("yyMMddHHmmssfff");
    var c = new ServiceCustomer
    {
        OrgId = t.OrgId, CusCode = cusId, DealerCode = dealer,
        CusName = dto.CusName!.Trim(), Address = dto.Address, Mobile = dto.Mobile,
        ContName = dto.ContName, ContAddress = dto.ContAddress, ContTel = dto.ContPhone,
        ProvinceCode = dto.ProvinceCode, DistrictCode = dto.DistrictCode,
        Sex = gender.Length == 0 ? null : gender,
        // Nguồn ghi `IDCardNo` ở ĐÂY — ngược hẳn kênh TVO (#331) vốn nhận rồi bỏ rơi.
        //   Cùng một trường, hai kênh đối xử khác nhau ⇒ không suy từ kênh này sang kênh kia.
        IDCardNo = dto.IDCardNo,
        IsContact = "1", FlagActive = "1", UpdatedAt = now,
    };
    db.ServiceCustomers.Add(c);

    // Nguồn chuẩn hoá đúng 6 trường mỗi dòng xe (`StdDataInTable`) và truyền `null` cho mọi trường còn
    //   lại của helper (EngineNo · ProductYear · NgàyMua · Km · Bảo hiểm · SalesCarID · Note).
    //   ⇒ cổng máy tính bảng CHỈ ghi được 6 trường xe + `IsActive="1"`; không tự mở rộng.
    var made = new List<object>();
    foreach (var row in dto.Cars ?? new List<CustomerWithCarsCarDto>())
    {
        var frame = (row.FrameNo ?? "").Trim().ToUpperInvariant();
        if (frame.Length == 0) continue;
        var carId = "TABC" + now.ToString("yyMMddHHmmssfff") + made.Count.ToString("00");
        db.ServiceCars.Add(new ServiceCar
        {
            OrgId = t.OrgId, CarID = carId, CusID = cusId, DealerCode = dealer,
            FrameNo = frame, PlateNo = row.PlateNo, PlateColorCode = row.PlateColorCode,
            ModelCode = row.ModelID, ColorCode = row.ColorCode, TradeMark = row.TradeMarkCode,
            CusName = dto.CusName!.Trim(), CusMobile = dto.Mobile,
            FlagActive = "1",
        });
        made.Add(new { carId, frameNo = frame, row.PlateNo, row.PlateColorCode });
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        cusId, cusCode = cusId, dealerCode = dealer, cars = made,
        plateColorNote = "Cổng này ghi PlateColorCode (đường biz 2022). Máy tính bảng của nguồn đi qua WS "
            + "gọi bản 2019 nên KHÔNG ghi được cột này — chênh lệch duy nhất giữa hai đường LIVE.",
    });
}).RequireAuthorization();

app.MapPost("/api/servicecustomers/import", async (ServiceCustomerImportDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = dto.Rows ?? new();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào để nhập." });
    var errors = new List<object>();
    var seen = new HashSet<string>();
    var seenPlate = new HashSet<string>();   // #258: bắt trùng BIỂN SỐ trong cùng file nhập
    int created = 0, updated = 0;
    for (int i = 0; i < rows.Count; i++)
    {
        var r = rows[i]; var line = i + 1;
        if (string.IsNullOrWhiteSpace(r.CusName)) { errors.Add(new { line, error = "Thiếu tên khách hàng." }); continue; }

        // ===== 🔴 #255 BỐN GUARD của `FrmImportCustomer.cs:220-247` (md5 `fb5df1f7` — KHỚP 2 máy) =====
        // Dùng `StringUtils.ValidateSpecialCharacter` (chỉ cấm `(` `)` và xuống dòng — xem helper).
        // Mỗi trường một THÔNG ĐIỆP riêng, và **đều kèm tên khách hàng** để tra được dòng nào.
        // ⚠️ Bản `Views/Insurance/ExcelUtil/FrmImportCustomer.cs` **KHÔNG có** khối này (khác 34 dòng)
        //    ⇒ hai màn import khách hàng có luật KHÁC nhau; port theo bản `ExcelUtil` (chặt hơn).
        if (HasParenOrNewline(r.CusName))
        { errors.Add(new { line, error = "Tên khách hàng không được chứa ký tự đặc biệt. Tên khách hàng: " + r.CusName }); continue; }
        if (HasParenOrNewline(r.Address))
        { errors.Add(new { line, error = "Địa chỉ không được chứa ký tự đặc biệt. Tên khách hàng: " + r.CusName }); continue; }
        if (HasParenOrNewline(r.ContName))
        { errors.Add(new { line, error = "Họ tên người liên hệ không được chứa ký tự đặc biệt. Tên khách hàng: " + r.CusName }); continue; }
        if (HasParenOrNewline(r.ContAddress))
        { errors.Add(new { line, error = "Địa chỉ người liên hệ không được chứa ký tự đặc biệt. Tên khách hàng: " + r.CusName }); continue; }

        // ===== 🔴 #258 BIỂN SỐ — GAP: import khách hàng của nguồn CÓ cột biển số và kiểm nó =====
        // `FrmImportCustomer.cs:141-160`: mỗi dòng có `TblSerCar.PlateNo`, kiểm HAI mẫu regex rồi
        //   kiểm **trùng biển số trong file** ⇒ `MSG_WARNING_DUPLICATE_PLATENO` = "Biển số xe trùng nhau".
        // ⚠️ Ngay giữa hai guard đó có khối regex ký tự đặc biệt **BỊ COMMENT** (:150-154) ⇒ KHÔNG port
        //    (giống `FrmImportPart` ở #256).
        // Port cũ không có cột biển số nào trong import khách hàng ⇒ mất cả xe lẫn hai guard.
        if (!string.IsNullOrWhiteSpace(r.PlateNo))
        {
            var plate = r.PlateNo!.Trim();
            if (!IsValidPlateNo(plate))
            { errors.Add(new { line, plateNo = plate, error = "Biển số không hợp lệ" }); continue; }
            if (!seenPlate.Add(plate))
            { errors.Add(new { line, plateNo = plate, error = "Biển số xe trùng nhau" }); continue; }
        }
        if (string.IsNullOrWhiteSpace(r.Mobile) && string.IsNullOrWhiteSpace(r.Tel)) { errors.Add(new { line, name = r.CusName, error = "Cần SĐT di động hoặc cố định." }); continue; }
        var code = string.IsNullOrWhiteSpace(r.CusCode) ? "CUS" + DateTime.Now.ToString("yyMMddHHmmssfff") + line : r.CusCode.Trim().ToUpperInvariant();
        if (!seen.Add(code)) { errors.Add(new { line, code, error = "Mã khách hàng bị trùng trong file nhập." }); continue; }
        var c = await db.ServiceCustomers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CusCode == code);
        if (c is null) { c = new ServiceCustomer { OrgId = t.OrgId, CusCode = code }; db.ServiceCustomers.Add(c); created++; }
        else updated++;
        c.CusName = r.CusName; c.Mobile = r.Mobile; c.Tel = r.Tel; c.Address = r.Address; c.Email = r.Email; c.UpdatedAt = DateTime.Now;
        // #255: hai cột người liên hệ mà nguồn CÓ kiểm nhưng import cũ không nhận/không gán (§12).
        c.ContName = r.ContName; c.ContAddress = r.ContAddress;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = rows.Count, created, updated, errorCount = errors.Count, errors });
}).RequireAuthorization();

// ===== Chăm sóc khách hàng (Ser_CustomerCare — port 1:1 FrmCustomerCare) =====
// #220 parity: mã loại phiếu CSKH đúng `TConst.SerCareType` (Const.Main.cs:349) — viết THƯỜNG.
string[] _careTypes = { "24h", "72h", "dob", "man" };
string[] _maceStatuses = { "Pending", "Contacted", "NotContacted" };
// ===== 🔴 #278 PARITY với bản TỔNG ĐÀI iCIC (`50.Source/ERP.ICIC` — hệ CHỈ CÓ TRÊN LAPTOP) =====
// ⚠️ #211 ĐÃ port bảng `Ser_CustomerCare72h` (kể cả `Survey1..28`) từ **DMSCarSv** ⇒ lượt này chỉ ĐỐI CHIẾU
//   thêm với bản của hệ iCIC và vá LUẬT LỌC còn thiếu, KHÔNG dựng bảng/endpoint mới.
// TRACE TWIN: `Ser_CustomerCare_Get72h` có **BẢY** bản; WS `WSCarSv_ICIC.cs:1598` gọi `_New20230315`
//   (`ZTemp.cs:3170`) ⇒ 6 bản chết. Bản `_New20161029` nằm **CUỐI FILE**: chọn "hàm cuối" là lấy bản CŨ NHẤT.
//
// BỐN ĐIỀU KIỆN LỌC của nguồn (`ZTemp.cs:3325-3345`) mà endpoint này THIẾU:
//   1. IsReRepair = "0" — loại lệnh SỬA LẠI (khách quay lại vì lỗi cũ ⇒ không phải ca chăm sóc mới).
//   2. ROType != "PDI" **hoặc ROType is null** — loại PDI nhưng vế null VẪN ĐƯỢC LẤY.
//   3. Danh sách đại lý bị loại áp cho **CẢ BA** bảng (tt/cus/car) — lọc một bảng là chưa đủ.
//   4. IsROFinish phải đúng "1"/"0" (rỗng cũng không nhận) ⇒ nguồn ném `..._IsRoFinish`.
//      Ở đây tham số để **tuỳ chọn** cho khỏi vỡ lời gọi cũ; đã truyền thì phải đúng — sai lệch CỐ Ý.
// ⚠️ KHÔNG port khối `CheckUpdateCusCare(...)` đầu hàm nguồn — **đã bị comment**; port vào thì API ĐỌC
//   danh sách lại đi GHI trạng thái.
// 📌 NỢ: bản iCIC sau khi ghi còn gọi ngược **WS CarSv của chính đại lý** (`_strConfig_OS_URLWSCarSv` thay
//   `@strDealerCode`) — iCIC là tổng đài TẬP TRUNG, ghi xuống hệ từng đại lý.
app.MapGet("/api/customercares", async (AppDbContext db, ITenantContext t, string? type, string? status, string? plate,
    string? isRoFinish, string? rejectDealers) =>
{
    if (!string.IsNullOrWhiteSpace(isRoFinish) && isRoFinish != "1" && isRoFinish != "0")
        return Results.BadRequest(new { error = "IsROFinish chỉ nhận 1 hoặc 0.", isRoFinish });

    var q = db.CustomerCares.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(type)) q = q.Where(c => c.CareType == type);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(c => c.PlateNo != null && c.PlateNo.Contains(plate.ToUpper()));

    // Điều kiện 3 — đại lý bị loại (MiniHTC gộp một cột trên phiếu; nguồn tách ba bảng).
    var reject = (rejectDealers ?? "").Split(new[] { ',', '|' }, StringSplitOptions.RemoveEmptyEntries)
        .Select(s => s.Trim().ToUpperInvariant()).Where(s => s.Length > 0).ToList();
    if (reject.Count > 0) q = q.Where(c => c.DealerCode == null || !reject.Contains(c.DealerCode));

    // Điều kiện 1 + 2 — tra sang ĐẦU lệnh sửa chữa. ⚠️ KHÔNG dùng `RoServiceItem.ROType`: cùng tên cột
    //   nhưng là loại công việc TỪNG DÒNG; join sang đó thì một lệnh 5 dòng bị xét 5 lần.
    var roOk = await db.RepairOrders.Where(r => r.OrgId == t.OrgId
            && (r.IsReRepair == null || r.IsReRepair == "0")
            && (r.ROType == null || r.ROType != "PDI"))
        .Select(r => r.RONo).ToListAsync();
    q = q.Where(c => c.RONo == null || roOk.Contains(c.RONo));

    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    { c.CareNo, c.CareType, c.RONo, c.PlateNo, c.CusName, c.CusPhone, c.ContactDate, c.Status, c.Result, c.ContactedAt,
      c.IsCall, c.IsFeedback, c.CusFeedback, c.IsSendmail, c.Note, c.DealerCode }).ToListAsync();   // #210 §12 · #278
    // "Chưa liên hệ" nhận cả mã nguồn PEND lẫn giá trị Pending của dữ liệu tạo trước khi vá mã trạng thái.
    return Results.Ok(new { count = items.Count, pending = items.Count(x => x.Status is "PEND" or "Pending"), items });
}).RequireAuthorization();

app.MapPost("/api/customercares", async (CustomerCareDto dto, AppDbContext db, ITenantContext t) =>
{
    // #220: mã nguồn viết thường ⇒ chuẩn hoá về LOWER, không phải UPPER.
    var type = string.IsNullOrWhiteSpace(dto.CareType) ? "24h" : dto.CareType.Trim().ToLowerInvariant();
    if (!_careTypes.Contains(type)) return Results.BadRequest(new { error = "CareType = 24h|72h|dob|man" });
    if (string.IsNullOrWhiteSpace(dto.PlateNo) && string.IsNullOrWhiteSpace(dto.CusPhone))
        return Results.BadRequest(new { error = "Cần biển số hoặc SĐT khách." });
    var no = "CC" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new CustomerCare
    {
        OrgId = t.OrgId, CareNo = no, CareType = type, RONo = dto.RONo, PlateNo = dto.PlateNo?.Trim().ToUpperInvariant(),
        CusName = dto.CusName, CusPhone = dto.CusPhone, ContactDate = dto.ContactDate,
        Status = "PEND"   // mã nguồn SerCareStatus.Pending
    };
    db.CustomerCares.Add(c); await db.SaveChangesAsync();
    return Results.Ok(new { c.CareNo, c.CareType, status = c.Status });
}).RequireAuthorization();

// ===== 🔴 #210 LIÊN HỆ KHÁCH — `Ser_CustomerCare_Update` (BizCarSv.Customer.cs:11958) =====
// Nguồn: hệ **TCMotor DMSCarSv**, bản `V20.2023.Release.V2` (laptop) ≡ `V20.2023.Release` (máy 150) —
//   md5 `44c7c87b`, 22241 dòng, GIỐNG HỆT, chỉ khác TÊN THƯ MỤC. (`V20` là bản cũ 18081 dòng.)
//
// 🔴 Nguồn KHÔNG ghi `Status` trong lệnh sửa: trạng thái là **tổ hợp hai cờ** `IsCall` + `IsFeedback`,
//   khớp đúng taxonomy `TConst.SerCareStatus` (Const.Main.cs:357):
//     PEND  = chưa liên hệ            (IsCall != "1")
//     CINFB = đã liên hệ, CHƯA phản hồi (IsCall = "1", IsFeedback != "1")
//     CIFB  = đã liên hệ, ĐÃ phản hồi   (IsCall = "1", IsFeedback  = "1")
//     REJ   = không cần liên hệ, bỏ qua
//   Từ vựng `Pending/Contacted/Closed` của port cũ KHÔNG có ở nguồn ⇒ đã đổi + migration.
//
// ⚠️ NỢ: lệnh đầy đủ `Ser_CustomerCare72h_UpdateStatus_New20180622` (15728) còn nhận **bộ khảo sát**
//   (`Survey1..9`, `FyourCSSH`, `WFBasicNeeds`, `YourCarProblem`, `YourRIWN`, `YourSatisfyQSv`,
//   `YourHopeOfOur`) — cụm khảo sát CSKH 72h, để lượt riêng, KHÔNG bịa cột ở đây.
app.MapPost("/api/customercares/{no}/contact", async (string no, CareContactDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.CustomerCares.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (c.Status == "REJ") return Results.BadRequest(new { error = "Phiếu đã đánh dấu KHÔNG cần liên hệ (REJ)." });

    var now = DateTime.Now;
    c.IsCall = "1";                                     // đã gọi
    c.CusFeedback = dto.Result;                         // nguồn ghi nội dung phản hồi vào `CusFeedback`
    c.Result = dto.Result;                              // giữ cột cũ của port cho tương thích
    c.IsFeedback = string.IsNullOrWhiteSpace(dto.Result) ? c.IsFeedback : "1";
    // Trạng thái = tổ hợp hai cờ, đúng SerCareStatus.
    c.Status = c.IsFeedback == "1" ? "CIFB" : "CINFB";
    c.ContactedAt = now;

    await db.SaveChangesAsync();
    return Results.Ok(new { c.CareNo, status = c.Status, c.IsCall, c.IsFeedback, c.CusFeedback, c.ContactedAt });
}).RequireAuthorization();

// 🔴 #210: nguồn KHÔNG có bước "đóng phiếu". Mã cuối của `SerCareStatus` là **REJ = "không cần liên hệ,
//   bỏ qua"** — nguồn ghi nó ở `Ser_CustomerCareStatusUpdate` (13199) và loại khỏi danh sách cần gọi
//   (`and t.Status not in ('REJ')`, dòng 10545). Đây là **bỏ qua**, không phải "kết thúc sau khi đã liên hệ",
//   nên guard cũ (chỉ đóng phiếu ĐÃ liên hệ) là ngược nghĩa: REJ đặt được từ phiếu CHƯA gọi.
//   Giữ đường dẫn `/close` cho client cũ (như #203/#204), đổi ngữ nghĩa bên dưới cho đúng nguồn.
app.MapPost("/api/customercares/{no}/close", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.CustomerCares.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (c.Status == "REJ") return Results.BadRequest(new { error = "Phiếu đã ở trạng thái REJ." });
    c.Status = "REJ";                                   // TConst.SerCareStatus.Reject
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CareNo, status = c.Status, note = "REJ = không cần liên hệ (đúng nguồn), không phải 'đã đóng sau khi liên hệ'." });
}).RequireAuthorization();

/// <summary>
/// Chuẩn hoá ngày sinh nhật về NĂM HIỆN TẠI đúng như nguồn.
/// 🔴 Luật ngày nhuận: sinh nhật 29/02 mà năm nay KHÔNG nhuận thì lùi về 28/02
/// (nguồn dùng `date.AddDays(-1).Day`). Thiếu luật này thì dựng DateTime 29/02 của năm thường sẽ NÉM LỖI.
/// </summary>
static DateTime NormalizeBirthdayToCurrentYear(DateTime birthday)
{
    var currentYear = DateTime.Today.Year;
    if (birthday.Month == 2 && birthday.Day == 29 && !DateTime.IsLeapYear(currentYear))
        return new DateTime(currentYear, 2, birthday.AddDays(-1).Day);
    return new DateTime(currentYear, birthday.Month, birthday.Day);
}

// ===== CSKH nhân dịp SINH NHẬT (Ser_CustomerCareBth — port 1:1 FrmCSCCustomerCareDOB, TCMotor DMSCarSv/Customer) =====
// TWIN: WS gọi Ser_CustomerCareBth_Get / _Create / _Update / _Delete (bản trần, không hậu tố ngày).

// Trạng thái liên hệ RIÊNG của luồng sinh nhật — KHÁC bộ PEND/CINFB/CIFB/REJ của CSKH sau dịch vụ.
var birthdayCareStatusTexts = new Dictionary<string, string>
{
    ["0"] = "Chưa liên hệ",
    ["1"] = "Đã liên hệ",
    ["2"] = "Không liên hệ",
};

app.MapGet("/api/customercarebirthdays", async (
    AppDbContext db, ITenantContext t, string? cusId, string? dealer, string? status, DateTime? from, DateTime? to) =>
{
    var q = db.CustomerCareBirthdays.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(cusId)) q = q.Where(x => x.CusId == cusId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    // Nguồn chỉ lấy dòng CÓ ngày sinh nhật (`AND t.DateBth is not null`).
    q = q.Where(x => x.DateBth != null);
    if (from.HasValue) q = q.Where(x => x.DateBth >= from);
    if (to.HasValue) q = q.Where(x => x.DateBth <= to);

    var rows = await q.OrderBy(x => x.DateBth).Take(1000).ToListAsync();
    var items = rows.Select(x => new
    {
        x.CareBthId, x.CusId, x.DealerCode, x.DateBth, x.Status,
        statusText = birthdayCareStatusTexts.TryGetValue(x.Status, out var text) ? text : x.Status,
        x.ContactDate, x.Remark, x.CreatedDate,
        x.CreatedBy, x.LogLuDateTime, x.LogLUBy   // #217 §12
    }).ToList();
    // Nguồn trả bảng tóm tắt ("…_Sumary") BÊN CẠNH danh sách chi tiết ⇒ trả cả hai.
    return Results.Ok(new
    {
        count = items.Count,
        summary = birthdayCareStatusTexts.Select(kv => new
        {
            status = kv.Key, statusText = kv.Value, count = items.Count(i => i.Status == kv.Key)
        }),
        items
    });
}).RequireAuthorization();

app.MapPost("/api/customercarebirthdays", async (
    CustomerCareBirthdayDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var cusId = (dto.CusId ?? "").Trim();
    if (cusId.Length == 0) return Results.BadRequest(new { error = "Chưa chọn khách hàng." });
    var status = (dto.Status ?? "0").Trim();
    if (!birthdayCareStatusTexts.ContainsKey(status))
        return Results.BadRequest(new { error = "Trạng thái chỉ có thể là 0 (chưa liên hệ), 1 (đã liên hệ) hoặc 2 (không liên hệ)." });

    var actor = user.Identity?.Name;
    var now = DateTime.Now;

    var careBthId = (dto.CareBthId ?? "").Trim();
    CustomerCareBirthday? row;
    if (careBthId.Length > 0)
    {
        row = await db.CustomerCareBirthdays.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareBthId == careBthId);
        if (row is null) return Results.NotFound(new { error = $"Không tìm thấy phiếu '{careBthId}'." });
    }
    else
    {
        careBthId = "CBT" + now.ToString("yyMMddHHmmssfff");
        // #354: `CreatedBy` nằm trong danh sách cột nguồn chép sang WH nhưng port cũ bỏ trống.
        row = new CustomerCareBirthday { OrgId = t.OrgId, CareBthId = careBthId, CreatedDate = now, CreatedBy = actor };
        db.CustomerCareBirthdays.Add(row);
    }

    row.CusId = cusId;
    row.DealerCode = dto.DealerCode;
    row.Status = status;
    // Ghi chú / ngày liên hệ để TRỐNG thì nguồn set NULL (xoá giá trị cũ), không giữ nguyên.
    row.Remark = string.IsNullOrWhiteSpace(dto.Remark) ? null : dto.Remark;
    row.ContactDate = dto.ContactDate;
    row.DateBth = dto.DateBth.HasValue ? NormalizeBirthdayToCurrentYear(dto.DateBth.Value) : null;
    row.UpdatedAt = now;
    row.UpdatedBy = actor;

    // ===== 🔴 #354 ĐÓNG DẤU `LogLu*` — cột NGUỒN thật sự mang, port cũ chỉ có `UpdatedAt/By` riêng =====
    // Nguồn `Ser_CustomerCareBth_Update` (`BizCarSv.Customer.cs:14982`) chép Main→WH bằng **SQL INSERT
    //   THUẦN** — dạng ghi **thứ NĂM**, ngoài bốn dạng đã ghi ở #314:
    //   `insert into Ser_CustomerCareBth (CareBthId, CreatedDate, ContactDate, Status, Remark,`
    //   `LogLuDateTime, LogLUBy, DealerCode, CusID, DateBth, CreatedBy) VALUES (@…)`
    //   ⇒ máy quét đếm theo `["X"] =` **không thấy** ⇒ suýt kết luận nhầm là cột port tự đặt.
    // ⚠️ CHÍNH TẢ CỦA NGUỒN KHÔNG NHẤT QUÁN ngay trong **một câu lệnh**: `LogL**u**DateTime` (chữ u
    //   thường) đứng cạnh `LogL**U**By` (chữ U hoa). Entity giữ nguyên cách viết của nguồn — đừng
    //   "sửa cho đẹp", vì tên cột phải khớp lược đồ.
    // ⚠️ `UpdatedAt`/`UpdatedBy` là quy ước RIÊNG của MiniHTC, KHÔNG thay được `LogLu*`: bản ghi chép
    //   sang kho dữ liệu (WH) đọc đúng hai cột `LogLu*` này.
    row.LogLuDateTime = now;
    row.LogLUBy = actor;

    await db.SaveChangesAsync();
    return Results.Ok(new { row.CareBthId, row.CusId, row.DateBth, row.Status, statusText = birthdayCareStatusTexts[status],
        row.CreatedBy, row.LogLuDateTime, row.LogLUBy });   // #354 §12
}).RequireAuthorization();

app.MapDelete("/api/customercarebirthdays/{careBthId}", async (string careBthId, AppDbContext db, ITenantContext t) =>
{
    careBthId = careBthId.Trim();
    var row = await db.CustomerCareBirthdays.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareBthId == careBthId);
    if (row is null) return Results.NotFound(new { careBthId });
    db.CustomerCareBirthdays.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = careBthId });
}).RequireAuthorization();

// ===== Khảo sát CSKH sau dịch vụ (Ser_CustomerCare24h/72h — port 1:1 FrmCSCCustomerCare24h/72h, TCMotor DMSCarSv/Customer) =====
// Bộ 6 câu hỏi + 3 nút kết thúc: "Đã liên hệ, chưa phản hồi" / "Đã liên hệ, đã phản hồi" / "Không liên hệ".
// Cả 3 nút gọi CÙNG một hàm biz Ser_CustomerCare24h, chỉ khác mã trạng thái truyền vào.

// Mã trạng thái CSKH đúng nguồn (TERP.Constants SerCareStatus) — KHÔNG gộp, vì "chưa phản hồi"
// và "đã phản hồi" là hai kết quả nghiệp vụ khác nhau dùng để chấm chất lượng dịch vụ.
var careSurveyStatusTexts = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
{
    ["PEND"]  = "Chưa liên hệ",
    ["CINFB"] = "Đã liên hệ, chưa phản hồi",
    ["CIFB"]  = "Đã liên hệ, đã phản hồi",
    ["REJ"]   = "Không liên hệ",
};

// Đáp án hợp lệ của từng câu hỏi — đúng danh sách RadioGroupItem mà form nạp từ SerCusCare72hQA.
// Form gốc chỉ cho chọn trong danh sách nên không thể nhập bừa; API phải tự kiểm ở server.
var careSurveyAnswerOptions = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
{
    ["YourCarProblem"] = new[] { "YourCarProblem_Yes", "YourCarProblem_No" },
    ["YourSatisfyQSv"] = new[] { "YourSatisfyQSv_Yes", "YourSatisfyQSv_No", "YourSatisfyQSv_Consider" },
    ["FyourCSSH"]      = new[] { "FyourCSSH_OK", "FyourCSSH_Nomarl", "FyourCSSH_No", "FyourCSSH_Other" },
    ["YourRIWN"]       = new[] { "YourRIWN_Yes", "YourRIWN_No" },
    ["WFBasicNeeds"]   = new[] { "WFBasicNeeds_OK", "WFBasicNeeds_Nomarl", "WFBasicNeeds_No", "WFBasicNeeds_Other" },
};

app.MapGet("/api/customercares/{no}/survey", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var care = await db.CustomerCares.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (care is null) return Results.NotFound(new { no });
    var survey = await db.CustomerCareSurveys.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    // #211 §12: trả về nguyên bản khảo sát (đã gồm 33 cột mới) thay vì chiếu tay từng cột.
    return Results.Ok(new
    {
        care.CareNo, care.CareType, care.RONo, care.PlateNo, care.CusName, care.CusPhone,
        status = care.Status,
        statusText = careSurveyStatusTexts.TryGetValue(care.Status, out var text) ? text : care.Status,
        survey = survey is null ? null : new
        {
            survey.RONo, survey.FinishedDate, survey.ContactDate,
            survey.YourCarProblem, survey.YourSatisfyQSv, survey.FyourCSSH,
            survey.YourRIWN, survey.WFBasicNeeds, survey.YourHopeOfOur,
            survey.Note, survey.CreatedBy, survey.CreatedAt, survey.UpdatedAt
        }
    });
}).RequireAuthorization();

// Lưu khảo sát + chốt trạng thái liên hệ (3 nút của form gộp về 1 endpoint, phân biệt bằng Status).
app.MapPost("/api/customercares/{no}/survey", async (
    string no, CareSurveyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var care = await db.CustomerCares.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (care is null) return Results.NotFound(new { no });

    // Chỉ 3 kết quả mà form cho bấm; PEND là trạng thái khởi tạo, không phải kết quả khảo sát.
    var newStatus = (dto.Status ?? "").Trim().ToUpperInvariant();
    if (newStatus is not ("CINFB" or "CIFB" or "REJ"))
        return Results.BadRequest(new { error = "Status = CINFB (đã liên hệ, chưa phản hồi) | CIFB (đã liên hệ, đã phản hồi) | REJ (không liên hệ)" });

    // Form vô hiệu hoá đúng cái nút ứng với trạng thái hiện tại ⇒ không thể chốt lại y nguyên trạng thái cũ.
    if (string.Equals(care.Status, newStatus, StringComparison.OrdinalIgnoreCase))
        return Results.BadRequest(new { error = $"Phiếu đã ở trạng thái '{careSurveyStatusTexts[newStatus]}'." });

    // ===== 🔴 #225 GUARD NGÀY LIÊN HỆ — bất đối xứng theo nhánh =====
    // Nguồn: `Views/Customer/FrmCSCCustomerCare72h.cs` (455 dòng, DMSCarSv) — 5 nút:
    //   `btnThoat` · `btnContactedIFeedB` · `btnContactedINoFB` · `btnReject` · `btnMakeAppointment`.
    // 🔴 Hai handler ĐÃ LIÊN HỆ (`btnContactedIFeedB` 284, `btnContactedINoFB` 331) mở đầu bằng
    //   `if (GetDateEditStringValue(dedContactDate) == "") { … dedContactDate.Focus(); return; }`
    //   ⇒ **BẮT BUỘC** có ngày liên hệ mới cho lưu.
    //   Handler `btnReject` (377) **KHÔNG** có guard đó — từ chối liên hệ thì không cần ngày.
    //   ⇒ Guard áp cho CINFB/CIFB, KHÔNG áp cho REJ. Giữ đúng bất đối xứng này.
    // ⚠️ `btnMakeAppointment` chỉ MỞ form `FrmQuotationApp` (điều hướng), không gọi service ⇒ không phải
    //   một lệnh ghi, không port thành endpoint.
    if (newStatus is "CINFB" or "CIFB" && dto.ContactDate is null)
        return Results.BadRequest(new { error = "Phải nhập ngày liên hệ trước khi ghi nhận đã liên hệ.", field = "ContactDate" });

    // Bỏ trống được (form có thể chưa chọn), nhưng đã nhập thì phải thuộc danh sách đáp án của câu đó.
    foreach (var (questionKey, allowedAnswers) in careSurveyAnswerOptions)
    {
        var answer = questionKey switch
        {
            "YourCarProblem" => dto.YourCarProblem,
            "YourSatisfyQSv" => dto.YourSatisfyQSv,
            "FyourCSSH"      => dto.FyourCSSH,
            "YourRIWN"       => dto.YourRIWN,
            _                => dto.WFBasicNeeds,
        };
        if (!string.IsNullOrWhiteSpace(answer) && !allowedAnswers.Contains(answer.Trim()))
            return Results.BadRequest(new { error = $"Đáp án câu '{questionKey}' không hợp lệ. Cho phép: {string.Join(", ", allowedAnswers)}" });
    }

    var actor = user.Identity?.Name;
    var now = DateTime.Now;

    // Upsert theo CareNo — nguồn đọc "top 1 * where CusCareID" rồi insert hoặc update chính bản ghi đó.
    var survey = await db.CustomerCareSurveys.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    var isNewSurvey = survey is null;
    if (survey is null)
    {
        survey = new CustomerCareSurvey { OrgId = t.OrgId, CareNo = no, CreatedBy = actor, CreatedAt = now };
        db.CustomerCareSurveys.Add(survey);
    }
    survey.RONo = string.IsNullOrWhiteSpace(dto.RONo) ? care.RONo : dto.RONo.Trim();
    survey.FinishedDate = dto.FinishedDate;
    survey.ContactDate = dto.ContactDate;
    survey.YourCarProblem = dto.YourCarProblem?.Trim();
    survey.YourSatisfyQSv = dto.YourSatisfyQSv?.Trim();
    survey.FyourCSSH = dto.FyourCSSH?.Trim();
    survey.YourRIWN = dto.YourRIWN?.Trim();
    survey.WFBasicNeeds = dto.WFBasicNeeds?.Trim();
    // Nguồn ghi cùng một giá trị ô ghi chú vào cả Note lẫn YourHopeOfOur (câu 6 tự luận) — giữ nguyên hành vi.
    survey.Note = dto.Note;
    survey.YourHopeOfOur = dto.Note;
    // ===== #211 bộ câu hỏi trắc nghiệm + hồ sơ khảo sát (Ser_CustomerCare72h) =====
    survey.CusCareType = dto.CusCareType?.Trim() ?? care.CareType;
    survey.OrderID = no;                      // 🔴 nguồn gán OrderID = CusCareID, KHÔNG phải mã đơn hàng
    survey.Remark = dto.Remark;
    survey.SurveyGmail = dto.SurveyGmail?.Trim();
    survey.SurveyDateTime = now;              // nguồn đặt = thời điểm lưu
    survey.Survey1 = dto.Survey1;
    survey.Survey2 = dto.Survey2;
    survey.Survey3 = dto.Survey3;
    survey.Survey4 = dto.Survey4;
    survey.Survey5 = dto.Survey5;
    survey.Survey6 = dto.Survey6;
    survey.Survey7 = dto.Survey7;
    survey.Survey8 = dto.Survey8;
    survey.Survey9 = dto.Survey9;
    survey.Survey10 = dto.Survey10;
    survey.Survey11 = dto.Survey11;
    survey.Survey12 = dto.Survey12;
    survey.Survey13 = dto.Survey13;
    survey.Survey14 = dto.Survey14;
    survey.Survey15 = dto.Survey15;
    survey.Survey16 = dto.Survey16;
    survey.Survey17 = dto.Survey17;
    survey.Survey18 = dto.Survey18;
    survey.Survey19 = dto.Survey19;
    survey.Survey20 = dto.Survey20;
    survey.Survey21 = dto.Survey21;
    survey.Survey22 = dto.Survey22;
    survey.Survey23 = dto.Survey23;
    survey.Survey24 = dto.Survey24;
    survey.Survey25 = dto.Survey25;
    survey.Survey26 = dto.Survey26;
    survey.Survey27 = dto.Survey27;
    survey.Survey28 = dto.Survey28;
    if (!isNewSurvey) survey.UpdatedAt = now;

    // Đồng bộ trạng thái phiếu CSKH (nguồn: Ser_CustomerCareStatusUpdate).
    // Ngày liên hệ để trống thì XOÁ ngày trên phiếu, không giữ ngày cũ.
    care.Status = newStatus;
    care.ContactDate = dto.ContactDate;
    if (newStatus != "REJ") care.ContactedAt = now;

    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        care.CareNo,
        status = care.Status,
        statusText = careSurveyStatusTexts[newStatus],
        surveyCreated = isNewSurvey
    });
}).RequireAuthorization();

// ===== Chăm sóc KH chương trình MACE hãng (CustomerCareMace — port 1:1 FrmCustomerCareMace/Update/ApointDate, TCMotor DMSCarSv/Customer) =====
app.MapGet("/api/customercaremaces", async (AppDbContext db, ITenantContext t, string? maceType, string? status, string? vin) =>
{
    var q = db.CustomerCareMaces.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(maceType)) q = q.Where(c => c.MaceType == maceType);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(c => c.Vin != null && c.Vin.Contains(vin.ToUpper()));
    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    { c.CareNo, c.MaceType, c.RONo, c.Vin, c.CusName, c.Status, c.ContactDate, c.ApointDate, c.MaceRecomentDate, c.Remark }).ToListAsync();
    return Results.Ok(new { count = items.Count, pending = items.Count(x => x.Status == "Pending"), items });
}).RequireAuthorization();

// Tạo bản ghi MACE (WinForm gốc chỉ search vì nguồn phát sinh từ hãng — thêm POST để nhập tay tương đương)
// ===== 🔴 #219 BÁO CÁO TỔNG HỢP CSKH (5 nhóm) — `Ser_CustomerCareRpt` =====
// Màn gốc: `Views/Customer/FrmCustomerCareReport.cs` (178 dòng, DMSCarSv) — 2 nút `btnSearch` · `btnThoat`.
// Nguồn: `TERP.BizCarSv/BizCarSv.Customer.cs:17534`. 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy.
//
// Nguồn đếm 4 chỉ tiêu (`Total` · `Pending` · `IsContact` · `IsNotContact`) cho **5 nhóm** CSKH.
// 🔴 MỖI NHÓM DÙNG **BẢNG MÃ KHÁC NHAU** — đây là chỗ dễ port sai nhất, đã đối chiếu từng dòng SQL:
//     `#tblCustomerCareMace` (bảo dưỡng) : Pending=`'0'` · IsContact=`'1'` · IsNotContact=`'2'`
//     `#tblCustomerCareBth`  (sinh nhật) : Pending=`'0'` · IsContact=`'1'` · IsNotContact=`'2'`
//     `#tblCustomerCare72h`             : Pending=`'PEND'` · IsContact=`'CINFB' OR 'CIFB'` · IsNotContact=`'REJ'`
//     `#tblCustomerCare24h`             : (giống 72h)
//     `#tblCustomerCareCamp` (chiến dịch): 🔴 **Pending=`'2'` · IsContact=`'1'` · IsNotContact=`'3'`**
//        ⇒ nhóm chiến dịch **ĐẢO** so với Mace/Bth: mã `'2'` ở đây là "chưa liên hệ", không phải "không liên hệ".
//
// ⚠️ MiniHTC lưu 24h/72h trên CÙNG bảng `CustomerCares`, phân biệt bằng `CareType` (#220: mã nguồn `24h`/`72h`)
//    ⇒ tách hai nhóm bằng CareType, đúng ngữ nghĩa nguồn (nguồn tách bằng hai bảng tạm).
app.MapGet("/api/report/customercare-summary", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, string? dealerCode) =>
{
    var from = fromDate?.Date;
    var to = toDate?.Date;

    // --- nhóm 1+2: 24h / 72h trên bảng CustomerCares (mã PEND / CINFB|CIFB / REJ) ---
    var cares = await db.CustomerCares.Where(x => x.OrgId == t.OrgId).ToListAsync();
    if (from.HasValue) cares = cares.Where(x => x.ContactDate == null || x.ContactDate.Value.Date >= from.Value).ToList();
    if (to.HasValue) cares = cares.Where(x => x.ContactDate == null || x.ContactDate.Value.Date <= to.Value).ToList();

    object CareGroup(string label, IEnumerable<CustomerCare> src)
    {
        var l = src.ToList();
        return new
        {
            group = label,
            total = l.Count,
            pending = l.Count(x => x.Status == "PEND"),
            isContact = l.Count(x => x.Status == "CINFB" || x.Status == "CIFB"),
            isNotContact = l.Count(x => x.Status == "REJ")
        };
    }

    var g24 = CareGroup("24h", cares.Where(x => x.CareType == "24h"));
    var g72 = CareGroup("72h", cares.Where(x => x.CareType == "72h"));

    // --- nhóm 3: nhắc bảo dưỡng (mã 0/1/2) ---
    var maces = await db.CustomerCareMaces.Where(x => x.OrgId == t.OrgId).ToListAsync();
    if (from.HasValue) maces = maces.Where(x => x.ContactDate == null || x.ContactDate.Value.Date >= from.Value).ToList();
    if (to.HasValue) maces = maces.Where(x => x.ContactDate == null || x.ContactDate.Value.Date <= to.Value).ToList();
    var gMace = new { group = "MACE", total = maces.Count,
        pending = maces.Count(x => x.Status == "0"),
        isContact = maces.Count(x => x.Status == "1"),
        isNotContact = maces.Count(x => x.Status == "2") };

    // --- nhóm 4: sinh nhật (mã 0/1/2) ---
    var bths = await db.CustomerCareBirthdays.Where(x => x.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(dealerCode)) bths = bths.Where(x => x.DealerCode == dealerCode).ToList();
    if (from.HasValue) bths = bths.Where(x => x.ContactDate == null || x.ContactDate.Value.Date >= from.Value).ToList();
    if (to.HasValue) bths = bths.Where(x => x.ContactDate == null || x.ContactDate.Value.Date <= to.Value).ToList();
    var gBth = new { group = "BIRTHDAY", total = bths.Count,
        pending = bths.Count(x => x.Status == "0"),
        isContact = bths.Count(x => x.Status == "1"),
        isNotContact = bths.Count(x => x.Status == "2") };

    // --- nhóm 5: chiến dịch — 🔴 bảng mã ĐẢO: 2 = chưa liên hệ, 1 = đã liên hệ, 3 = không liên hệ ---
    var camps = await db.CampaignContacts.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var gCamp = new { group = "CAMPAIGN", total = camps.Count,
        pending = camps.Count(x => x.ContactStatus == "2"),
        isContact = camps.Count(x => x.ContactStatus == "1"),
        isNotContact = camps.Count(x => x.ContactStatus == "3") };

    var groups = new List<object> { g24, g72, gMace, gBth, gCamp };
    return Results.Ok(new { fromDate = from, toDate = to, groups,
        note = "Mỗi nhóm dùng bảng mã RIÊNG (24h/72h: PEND/CINFB|CIFB/REJ · Mace+Bth: 0/1/2 · Campaign: 2/1/3 — đảo).",
        skipped = "Nguồn lọc thêm theo DealerCode cho mọi nhóm; MiniHTC chỉ có DealerCode trên nhóm sinh nhật, các nhóm khác chưa lưu ⇒ KHÔNG bịa." });
}).RequireAuthorization();

// ===== 🔴 #218 NHẮC BẢO DƯỠNG theo phiếu CSKH — `Ser_CustomerCareMaintance` =====
// Màn gốc: `Views/Customer/FrmCSCCustomerCareMaintance.cs` (238 dòng, DMSCarSv) —
//   bốn nút: `btnThoat` · `btnContactedIFeedB` · `btnContactedINoFB` · `btnReject`.
// Nguồn: `TERP.BizCarSv/BizCarSv.Customer.cs:16472`. 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy.
//
// 🔴 BẪY ĐẶT TÊN NÚT — ba nút map sang ba mã theo HẰNG, KHÔNG theo tên nút:
//     `btnContactedIFeedB`  → `SerCareStatus.ContactedINeedFB` = **CINFB** (đã liên hệ, CHƯA phản hồi)
//     `btnContactedINoFB`   → `SerCareStatus.ContactedIFNoB`   = **CIFB**  (đã liên hệ, ĐÃ phản hồi)
//     `btnReject`           → `SerCareStatus.Reject`           = **REJ**
//   Tên nút và tên hằng NGƯỢC nhau về nghĩa (IFeedB ↔ INeedFB, INoFB ↔ IFNoB) ⇒ phải bám hằng.
//
// 🔴 MỘT THAO TÁC CHẠM HAI BẢNG:
//   1. `Ser_CustomerCareMaintance` — **upsert** theo `CusCareID`, ghi 3 cột `DateAppointment`/`ContactDate`/`Note`;
//   2. gọi `Ser_CustomerCareStatusUpdate` đặt `Status` (+ `ContactDate`) trên PHIẾU CHÍNH `Ser_CustomerCare`.
//   Bỏ bước 2 thì phiếu vẫn ở "PEND" dù đã ghi nhận liên hệ — lỗi âm thầm.
//
// ⚠️ Khác #217: `ContactDate` ở đây **chỉ ghi khi có giá trị** (`if (!IsEmpty(strConatctDate))`) — để trống thì
//   GIỮ NGUYÊN giá trị cũ, không set NULL. Giữ đúng khác biệt này.
app.MapPost("/api/customercares/{no}/maintance", async (string no, CareMaintanceDto dto,
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var care = await db.CustomerCares.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (care is null) return Results.NotFound(new { no });

    var status = (dto.Status ?? "").Trim().ToUpperInvariant();
    if (status is not ("CINFB" or "CIFB" or "REJ"))
        return Results.BadRequest(new { error = "Trạng thái chỉ nhận CINFB (chưa phản hồi) | CIFB (đã phản hồi) | REJ (không liên hệ)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    // (1) upsert bảng nhắc bảo dưỡng
    var row = await db.CustomerCareMaintances.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    var isNew = row is null;
    if (row is null) { row = new CustomerCareMaintance { OrgId = t.OrgId, CareNo = no, CreatedAt = now }; db.CustomerCareMaintances.Add(row); }
    row.DateAppointment = dto.DateAppointment;
    if (dto.ContactDate.HasValue) row.ContactDate = dto.ContactDate;   // rỗng ⇒ GIỮ giá trị cũ (đúng nguồn)
    row.Note = dto.Note;
    if (!isNew) { row.UpdatedAt = now; row.UpdatedBy = who; }

    // (2) side-effect: cập nhật trạng thái trên PHIẾU CHÍNH
    care.Status = status;
    if (dto.ContactDate.HasValue) { care.ContactDate = dto.ContactDate; care.ContactedAt = now; }
    if (status == "CINFB") { care.IsCall = "1"; care.IsFeedback = "0"; }
    else if (status == "CIFB") { care.IsCall = "1"; care.IsFeedback = "1"; }

    await db.SaveChangesAsync();
    return Results.Ok(new { care.CareNo, status = care.Status, care.IsCall, care.IsFeedback,
                            row.DateAppointment, row.ContactDate, row.Note, created = isNew });
}).RequireAuthorization();

