app.MapPost("/api/stockouts/{no}/post", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockOuts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockOutNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.Status != "2") return Results.BadRequest(new { error = "Chỉ kết thúc được phiếu đang ở trạng thái Tiến hành (2)." });
    var lines = await db.PartStockOutLines.Where(l => l.OrgId == t.OrgId && l.StockOutId == h.Id).ToListAsync();
    // kiểm tồn đủ trước
    foreach (var l in lines)
    {
        var loc = l.Location ?? "";
        var stock = await db.PartStocks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.WarehouseCode == h.WarehouseCode && x.PartCode == l.PartCode && (x.Location ?? "") == loc);
        var onhand = stock?.OnHand ?? 0;
        if (onhand < l.Quantity)
            return Results.BadRequest(new { error = $"Tồn không đủ cho {l.PartCode}@{loc}: cần {l.Quantity}, còn {onhand}." });
    }
    // trừ tồn
    foreach (var l in lines)
    {
        var loc = l.Location ?? "";
        var stock = await db.PartStocks.FirstAsync(x => x.OrgId == t.OrgId && x.WarehouseCode == h.WarehouseCode && x.PartCode == l.PartCode && (x.Location ?? "") == loc);
        stock.OnHand -= l.Quantity; stock.UpdatedAt = DateTime.Now;
    }
    // ⚠️ KHÔNG gán lại StockOutDate: luật "ngày = thời điểm duyệt" chỉ có ở phiếu NHẬP, nguồn phiếu XUẤT không có.
    h.Status = "3"; h.PostedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockOutNo, status = h.Status, statusName = "Kết thúc", postedLines = lines.Count });
}).RequireAuthorization();

// Hủy phiếu xuất kho (port 1:1 FrmSOReject, TCMotor DMSCarSv/Inventory). Chỉ hủy khi còn Draft.
// #291 XOÁ phiếu XUẤT — cùng luật với phiếu nhập (xem chú thích ở `DELETE /api/stockins/{no}`).
// Guard nguồn: `CheckStockOutForDelete` (`StockOut.cs:184`) — chỉ `Status` ∈ { "1", "5" }.
// #292 SỬA phiếu XUẤT — thiết kế guard KHÁC màn nhập (xem chú thích ở `PUT /api/stockins/{no}`).
app.MapPut("/api/stockouts/{no}", async (string no, StockOutUpdateDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockOuts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockOutNo == no);
    if (h is null) return Results.NotFound(new { no });

    if (string.IsNullOrWhiteSpace(dto.StockOutNo)) return Results.BadRequest(new { error = "Chưa nhập số phiếu xuất." });
    if (string.IsNullOrWhiteSpace(dto.WarehouseCode)) return Results.BadRequest(new { error = "Chưa chọn kho." });

    // 🔴 KHÔNG guard trạng thái HIỆN TẠI. Chỉ khi client GỬI Status thì mới kiểm — và chỉ nhận "1"/"5".
    var newStatus = (dto.Status ?? "").Trim();
    if (newStatus.Length > 0 && newStatus != "1" && newStatus != "5")
        return Results.BadRequest(new { error = "Status gửi lên chỉ được là Mới tạo (1) hoặc Huỷ (5).", status = newStatus });

    h.StockOutNo = dto.StockOutNo!.Trim().ToUpperInvariant();
    h.WarehouseCode = dto.WarehouseCode!.Trim().ToUpperInvariant();
    h.StockOutType = dto.StockOutType;
    if (dto.StockOutDate.HasValue) h.StockOutDate = dto.StockOutDate.Value;
    if (newStatus.Length > 0) h.Status = newStatus;      // không gửi ⇒ KHÔNG đụng
    h.Description = dto.Description; h.UserCode = dto.StaffID;
    h.DriverName = dto.DriverName; h.DrivingLicense = dto.DrivingLicense;
    h.DriverID = dto.DriverID; h.TruckNo = dto.TruckNo; h.CusID = dto.CusID;
    h.AdjustmentBy = dto.AdjustmentBy; h.AdjustmentDate = dto.AdjustmentDate; h.AdjustmentNote = dto.AdjustmentNote;
    h.OldStockOutID = string.IsNullOrWhiteSpace(dto.OldStockOutID) ? null : dto.OldStockOutID!.Trim();

    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockOutNo, status = h.Status, statusChanged = newStatus.Length > 0 });
}).RequireAuthorization();

app.MapDelete("/api/stockouts/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockOuts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockOutNo == no);
    if (h is null) return Results.NotFound(new { no });

    if (h.Status != "1" && h.Status != "5")
        return Results.BadRequest(new { error = "Chỉ xoá được phiếu xuất ở trạng thái Mới tạo (1) hoặc Huỷ (5).",
            status = h.Status, statusName = stockOutStatusNames.TryGetValue(h.Status ?? "", out var sn) ? sn : null });

    string? warn = null;
    if (!string.IsNullOrWhiteSpace(h.OldStockOutID))
    {
        var oldExists = await db.PartStockOuts.AnyAsync(x => x.OrgId == t.OrgId && x.StockOutNo == h.OldStockOutID);
        if (!oldExists) warn = "Không tìm thấy phiếu xuất gốc " + h.OldStockOutID + " mà phiếu này điều chỉnh.";
    }

    var lines = await db.PartStockOutLines.Where(x => x.OrgId == t.OrgId && x.StockOutId == h.Id).ToListAsync();
    db.PartStockOutLines.RemoveRange(lines);
    db.PartStockOuts.Remove(h);
    await db.SaveChangesAsync();
    return Results.Ok(new { stockOutNo = no, deletedLines = lines.Count, warning = warn });
}).RequireAuthorization();

app.MapPost("/api/stockouts/{no}/reject", async (string no, StockRejectDto dto, AppDbContext db, ITenantContext t, HttpContext http) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockOuts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockOutNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (string.IsNullOrWhiteSpace(dto.Reason)) return Results.BadRequest(new { error = "Bạn chưa nhập lý do hủy phiếu xuất." });
    var who = http.User.Identity?.Name ?? http.User.FindFirst("email")?.Value ?? "system";
    h.Status = "5"; h.RejectReason = dto.Reason!.Trim(); h.RejectedBy = who; h.RejectedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockOutNo, status = h.Status });
}).RequireAuthorization();

// ===== Phiếu nhập kho phụ tùng (Ser_Inv_StockIn — port 1:1 FrmStockInCreate) + tồn kho PartStock =====
// ⚠️ KHÔNG khai lại `/api/stockdocs/statuses` ở đây: endpoint đó ĐÃ CÓ (~Program.cs:5817) phục vụ cụm
//    `ServiceStockIn` — và cụm đó port **CÙNG một bảng nguồn `Ser_Inv_StockIn`** với `PartStockIn` dưới đây
//    (`TblSerInvStockIn` chỉ là lớp hằng TÊN CỘT phía client, không phải bảng thứ hai).
//    ⇒ Nợ GỘP 2 entity trùng, đã ghi sổ; không gộp vội vì nhiều báo cáo đang đọc `ServiceStockIn`.
// ===== 🔴 #265 NHẬP KHO — `TblSerInvStockIn` (DbDefine.cs:1122-1160) =====
// md5 `d373e758` — KHỚP 2 máy; tìm qua sweep `sweep_tblconst_tail.js` (#261).
//
// VOCABULARY TRẠNG THÁI (:1150-1160) — **5 mã, đều có cặp Value+Text**:
//   "1" Mới tạo · "2" Tiến hành · "3" Kết thúc · "4" Đã điều chỉnh · "5" Đã hủy
// ⚠️ KHÁC phiếu XUẤT (#264): phiếu xuất còn có `StatusNewValue = "0"` (không có Text); phiếu nhập **không có**
//    mã 0. Hai bảng gần giống nhưng bộ mã KHÔNG bằng nhau — đừng dùng chung bảng nhãn.
// ⚠️ Nguồn viết `StatusAdjusmentValue` (thiếu chữ "t": Adjus**ment**) — lỗi chính tả của nguồn, giữ nguyên
//    khi grep; giá trị vẫn là "4".
var stockInStatusNames = new Dictionary<string, string>
{
    ["1"] = "Mới tạo", ["2"] = "Tiến hành", ["3"] = "Kết thúc",
    ["4"] = "Đã điều chỉnh", ["5"] = "Đã hủy",
};

app.MapGet("/api/stockins/vocab", () => Results.Ok(new
{
    statuses = stockInStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Phiếu NHẬP không có mã \"0\" (phiếu XUẤT thì có, xem /api/stockouts/vocab).",
})).RequireAuthorization();

app.MapGet("/api/stockins", async (AppDbContext db, ITenantContext t, string? status, string? warehouse) =>
{
    var q = db.PartStockIns.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(s => s.Status == status);
    if (!string.IsNullOrWhiteSpace(warehouse)) q = q.Where(s => s.WarehouseCode == warehouse);
    var items = await q.OrderByDescending(s => s.Id).Take(500).Select(s => new
    {
        s.StockInNo, s.StockInDate, s.StockInType, s.WarehouseCode, s.Staff, s.Status, s.PostedAt,
        // #265 §12: cột bổ sung có mặt ở CẢ GET lẫn POST
        s.StockInID, s.StatusText, s.Description, s.UserCode,
        s.DriverName, s.DrivingLicense, s.DriverID, s.TruckNo, s.StockOutNo,
        s.IsAdjustment, s.AdjustmentBy, s.AdjustmentDate, s.AdjustmentNote, s.OldStockInID,
        s.OrderPartId, s.OrderPartNo, s.FlagOrderNCC,
        s.DealerCode, s.SupplierID, s.TSTRequestNo, s.BillNo,
        lines = db.PartStockInLines.Count(l => l.OrgId == t.OrgId && l.StockInId == s.Id),
        total = db.PartStockInLines.Where(l => l.OrgId == t.OrgId && l.StockInId == s.Id).Sum(l => (decimal?)(l.Quantity * l.Price)) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/stockins", async (StockInDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.WarehouseCode)) return Results.BadRequest(new { error = "Cần WarehouseCode." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode) && l.Quantity > 0).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng phụ tùng (PartCode + Quantity > 0)." });
    var no = "SI" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new PartStockIn
    {
        OrgId = t.OrgId, StockInNo = no, StockInDate = dto.StockInDate ?? DateTime.Now,
        StockInType = dto.StockInType, WarehouseCode = dto.WarehouseCode.Trim().ToUpperInvariant(),
        Staff = dto.Staff, Status = "1",
        // #265: nhãn lưu kèm mã, đúng như nguồn (StatusText).
        StatusText = stockInStatusNames.TryGetValue("1", out var si1) ? si1 : null,
        Description = dto.Description, UserCode = dto.UserCode,
        DriverName = dto.DriverName, DrivingLicense = dto.DrivingLicense,
        DriverID = dto.DriverID, TruckNo = dto.TruckNo, StockOutNo = dto.StockOutNo,
        // mắt xích về đơn đặt phụ tùng (cụm TST)
        OrderPartId = dto.OrderPartId, OrderPartNo = dto.OrderPartNo, FlagOrderNCC = dto.FlagOrderNCC,
        DealerCode = dto.DealerCode, SupplierID = dto.SupplierID,
        TSTRequestNo = dto.TSTRequestNo, BillNo = dto.BillNo,
    };
    // #305: phiếu nhập mới luôn ở trạng thái CHƯA đồng bộ Veloca (đối xứng chiều xuất, #304).
    h.FlagSyncVeloca = "0"; h.SyncVelocaDTime = null;
    db.PartStockIns.Add(h); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.PartStockInLines.Add(new PartStockInLine { OrgId = t.OrgId, StockInId = h.Id, PartCode = l.PartCode.Trim().ToUpperInvariant(), PartName = l.PartName, Location = l.Location, Quantity = l.Quantity, Price = l.Price, VAT = l.VAT });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockInNo, h.WarehouseCode, lines = lines.Count, status = h.Status });
}).RequireAuthorization();

// ===== 🔴 #305 ĐỒNG BỘ PHIẾU NHẬP SANG VELOCA (`OSVeloca_Ser_Inv_StockIn_*`) — chưa từng port =====
// Đóng nốt trục Veloca mở ở #304 (chiều XUẤT). TRACE TWIN: WS `:15286` gọi
//   `..._GetByStockInID_**New20240606**` ⇒ bản `_GetByStockInID` (`StockIn.cs:8691`) CHẾT.
//
// 🔴 ĐIỀU KIỆN LỌC CỨNG của nguồn (`StockIn.cs:8586`): **`and sisi.Status = '3'`** — CHỈ phiếu nhập ở
//   trạng thái **Kết thúc** mới được đẩy sang Veloca. Đây là điều kiện KHÔNG THAM SỐ HOÁ, luôn áp.
// ⚠️ Ngay trên nó có `--and sisi.StockInType = '1'` **đã bị comment**, kèm chú thích của tác giả:
//   *"20240203. HuongTTT: Chị Đông không quan tâm đến Loại nhập kho nữa."* ⇒ **ĐỪNG khôi phục** bộ lọc
//   loại nhập kho; đây là quyết định nghiệp vụ có ghi lý do (lệ #275).
//
// ⚠️ Mọi bộ lọc dùng thành ngữ `( '' = @p or col = @p )` ⇒ **rỗng nghĩa là LẤY TẤT**, không phải bỏ lọc
//   một cách tình cờ. Riêng `FlagSyncVeloca` vì thế có **ba** trạng thái đầu vào: "0" · "1" · "" (cả hai).
//
// 📌 Đã kiểm và KHÔNG phải lỗi: khối `//, "@strFlagSyncVeloca", …` bị comment chỉ là danh sách thay thế
//   lúc DỰNG câu (`StringUtils.Replace`); tham số thật vẫn được bind ở `ExecQuery` (`StockIn.cs:8636`).
//   (Nếu không đọc tiếp sẽ tưởng là bẫy [BAKE-PARAM-MIX] guard-chết-câm.)
app.MapGet("/api/stockins/veloca-pending", async (AppDbContext db, ITenantContext t,
    string? flagSync, string? stockInNo, string? supplier, string? userCode,
    DateTime? stockInDateFrom, DateTime? stockInDateTo,
    DateTime? syncFrom, DateTime? syncTo) =>
{
    // Điều kiện CỨNG: chỉ phiếu đã Kết thúc.
    var qy = db.PartStockIns.Where(x => x.OrgId == t.OrgId && x.Status == "3");
    if (!string.IsNullOrEmpty(flagSync)) qy = qy.Where(x => x.FlagSyncVeloca == flagSync);
    if (!string.IsNullOrWhiteSpace(stockInNo)) qy = qy.Where(x => x.StockInNo == stockInNo);
    if (!string.IsNullOrWhiteSpace(supplier)) qy = qy.Where(x => x.SupplierID == supplier);
    if (!string.IsNullOrWhiteSpace(userCode)) qy = qy.Where(x => x.UserCode == userCode);
    if (stockInDateFrom.HasValue) qy = qy.Where(x => x.StockInDate >= stockInDateFrom);
    if (stockInDateTo.HasValue) qy = qy.Where(x => x.StockInDate <= stockInDateTo);
    if (syncFrom.HasValue) qy = qy.Where(x => x.SyncVelocaDTime >= syncFrom);
    if (syncTo.HasValue) qy = qy.Where(x => x.SyncVelocaDTime <= syncTo);

    var rows = await qy.OrderByDescending(x => x.Id).Take(500).ToListAsync();
    return Results.Ok(new
    {
        count = rows.Count,
        note = "CHỈ phiếu Status=3 (Kết thúc) mới đủ điều kiện đẩy Veloca — điều kiện cứng của nguồn. "
             + "flagSync rỗng ⇒ lấy CẢ đã và chưa đồng bộ.",
        items = rows.Select(x => new
        {
            x.Id, x.StockInNo, x.DealerCode, x.WarehouseCode, x.SupplierID, x.UserCode,
            x.StockInDate, x.Status, x.FlagSyncVeloca, x.SyncVelocaDTime,
            velocaInvCode = VelocaInvCode(velocaDealerInv, x.DealerCode),
        }),
    });
}).RequireAuthorization();

// #305 Payload đẩy MỘT phiếu nhập sang Veloca (`..._GetByStockInID_New20240606`).
// ⚠️ Cùng bản đồ đại lý → kho gõ CỨNG như chiều XUẤT (#304) — **dùng lại**, không chép đôi.
//   Nguồn phải lặp khối `case` tới **6 lần** trong một câu (SQL không có biến); port gom một `Dictionary`.
// 🔴 Nguồn dựng **BA cấp** kho: cấp 2 = KHO (`InvCode` = mã kho ánh xạ), cấp 3 = VỊ TRÍ
//   (`InvCode` = `LocationCode`, `InvCodeParent` = kho ánh xạ, `InvBUCode` = `I.<kho>.<vị trí>`).
// 🔴 `InvCodeIn` (thêm 20240606) = kho ĐÍCH của phiếu nhập.
app.MapGet("/api/stockins/{id:long}/veloca-payload", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { stockInId = id });
    var inv = VelocaInvCode(velocaDealerInv, h.DealerCode);
    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId && l.StockInId == h.Id).ToListAsync();

    return Results.Ok(new
    {
        // cấp 2 — KHO
        inventory = new
        {
            h.DealerCode, InvCode = inv, InvCodeParent = "I",
            InvBUCode = "I." + inv, InvBUPattern = "I." + inv + "%",
            InvLevel = "2", InvName = inv,
            InvAddress = (string?)null, InvContactName = (string?)null,
            InvContactPhone = (string?)null, InvContactEmail = (string?)null, Remark = (string?)null,
            FlagIn_Out = "1", FlagActive = "1",
        },
        // cấp 3 — VỊ TRÍ trong kho (nguồn lấy từ Ser_Mst_Location của từng dòng)
        locations = lines.Where(l => !string.IsNullOrWhiteSpace(l.Location))
            .Select(l => l.Location!).Distinct().Select(loc => new
            {
                InvCode = loc, InvCodeParent = inv,
                InvBUCode = "I." + inv + "." + loc, InvBUPattern = "I." + inv + "." + loc + "%",
                InvLevel = "3", InvName = loc,
            }),
        stockIn = new
        {
            h.Id, h.StockInNo, h.DealerCode, h.WarehouseCode, h.SupplierID, h.Status,
            InvCodeIn = inv,                    // 20240606: kho ĐÍCH
            CreateBy = h.UserCode, ApprBy = h.UserCode,
            // 🔴 giờ UTC của trục Veloca = giờ địa phương − 7 (xem #304; trục HCC KHÔNG trừ)
            CreateDTimeUTC = VelocaUtc(h.CreatedAt),
            ApprDTimeUTC = VelocaUtc(h.PostedAt ?? h.CreatedAt),
            h.FlagSyncVeloca, h.SyncVelocaDTime,
        },
        lineCount = lines.Count,
    });
}).RequireAuthorization();

// #305 Đánh dấu ĐÃ đồng bộ (`OSVeloca_Ser_Inv_StockIn_UpdFlagSyncVeloca`).
// ⚠️ Nguồn ghi CỜ **và** MỐC THỜI GIAN, nhưng **cố ý KHÔNG** đụng `LogLUDateTime`/`LogLUBy`
//   (hai dòng đó bị comment ngay trong câu `update`) ⇒ đẩy sang đối tác **không tính là người dùng sửa**.
app.MapPost("/api/stockins/{id:long}/veloca-synced", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { stockInId = id });
    h.FlagSyncVeloca = "1";
    h.SyncVelocaDTime = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.StockInNo, h.FlagSyncVeloca, h.SyncVelocaDTime });
}).RequireAuthorization();

app.MapGet("/api/stockins/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });
    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId && l.StockInId == h.Id)
        .Select(l => new { l.PartCode, l.PartName, l.Location, l.Quantity, l.Price, l.VAT, lineTotal = l.Quantity * l.Price }).ToListAsync();
    return Results.Ok(new { h.StockInNo, h.WarehouseCode, h.Status, count = lines.Count, lines });
}).RequireAuthorization();

// Ghi sổ: tăng tồn PartStock (integration thật)
// 🔴 TIẾN HÀNH "1"→"2" — bước trung gian BẮT BUỘC của nguồn, port cũ THIẾU HẲN.
app.MapPost("/api/stockins/{no}/execute", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.Status != "1") return Results.BadRequest(new { error = "Chỉ chuyển Tiến hành từ phiếu Mới tạo (1)." });
    h.Status = "2";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockInNo, status = h.Status, statusName = "Tiến hành" });
}).RequireAuthorization();

// 🔴 LÙI trạng thái "2"→"1" (nhánh `strIsRevert == Flag.Active` của nguồn) — port cũ THIẾU.
// ⚠️ Nguồn phiếu NHẬP dùng `CheckStockInNotPending` vốn chấp nhận **cả "1" LẪN "5" (Hủy)** ⇒ lùi được sang Hủy.
//    Phiếu XUẤT thì KHÔNG (`CheckStockOutNotPending` chỉ nhận "1") — luật LỆCH giữa 2 màn, giữ nguyên.
app.MapPost("/api/stockins/{no}/revert", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.Status != "2") return Results.BadRequest(new { error = "Chỉ lùi được phiếu đang Tiến hành (2)." });
    h.Status = "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockInNo, status = h.Status, statusName = "Mới tạo" });
}).RequireAuthorization();

app.MapPost("/api/stockins/{no}/post", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });
    // 🔴 Nguồn CHỈ cho Kết thúc từ "2" Tiến hành (`CheckStockInNotPendingExecuting` + nhánh
    //    `strCurrentStatus == Executing` ⇒ `CheckStockInNotFinished`) — KHÔNG có đường 1→3 thẳng.
    if (h.Status != "2") return Results.BadRequest(new { error = "Chỉ kết thúc được phiếu đang ở trạng thái Tiến hành (2)." });
    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId && l.StockInId == h.Id).ToListAsync();
    foreach (var l in lines)
    {
        var loc = l.Location ?? "";
        var stock = await db.PartStocks.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.WarehouseCode == h.WarehouseCode && x.PartCode == l.PartCode && (x.Location ?? "") == loc);
        if (stock is null) { stock = new PartStock { OrgId = t.OrgId, WarehouseCode = h.WarehouseCode, PartCode = l.PartCode, PartName = l.PartName, Location = l.Location, OnHand = 0 }; db.PartStocks.Add(stock); }
        stock.OnHand += l.Quantity; stock.PartName = l.PartName ?? stock.PartName; stock.UpdatedAt = DateTime.Now;
    }
    // 🔴 Luật nguồn 2025-01-24 (dongnt, StockIn.cs:4605-4609): khi Kết thúc thì **StockInDate lấy theo
    //    THỜI ĐIỂM DUYỆT**, không giữ ngày nhập lúc lập phiếu. Chỉ phiếu NHẬP có luật này, phiếu XUẤT không.
    h.Status = "3"; h.StockInDate = DateTime.Now; h.PostedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockInNo, status = h.Status, statusName = "Kết thúc", postedLines = lines.Count });
}).RequireAuthorization();

// Hủy phiếu nhập kho (port 1:1 FrmSIReject, TCMotor DMSCarSv/Inventory). Chỉ hủy khi còn Draft.
// ===== 🔴 #291 XOÁ phiếu kho — `SerStockInDelete` / `SerStockOutDelete` =====
// 🆕 Tìm ra bằng sweep `_audit/sweep_verb_pair.js` (sinh từ #290): quét **747 hàm WS sống** của
//   `WSCarSv.asmx.cs`, tìm cùng một GỐC màn mà có **CẶP ĐỘNG TỪ GẦN NGHĨA** ⇒ đúng **4 cặp**:
//     `Email_ConfigSendAuto_Cancel + _Delete` (đã xử lý #290) · `Email_TempEmail_Cancel + _Delete` (nợ) ·
//     **`SerStockInReject + SerStockInDelete`** · **`SerStockOutReject + SerStockOutDelete`**
//   ⇒ hai màn kho ĐÃ PORT nhưng **chỉ có `reject`, THIẾU hẳn `delete`**. Hai việc khác nhau:
//     `reject` = đổi trạng thái sang "5" (huỷ, **giữ phiếu**) · `delete` = **XOÁ HẲN** cả dòng chi tiết.
//
// 🔴 GUARD XOÁ (giống nhau ở cả hai màn): chỉ xoá được khi `Status` ∈ { `"1"` Mới tạo, `"5"` Huỷ }.
//   Nguồn: `CheckStockInNotPending` (`StockIn.cs:348`) và `CheckStockOutForDelete` (`StockOut.cs:184`).
//   ⚠️ TÊN GUARD ĐÁNH LỪA: `CheckStockInNotPending` nghe như "kiểm tra KHÔNG phải Pending", thực tế nó ném
//     khi **không phải Pending VÀ không phải Reject** — tức **BẮT BUỘC** phải là một trong hai.
//   ⇒ phiếu đang Tiến hành/Kết thúc/Điều chỉnh (2/3/4) **KHÔNG xoá được** — phải huỷ (`reject`) trước.
//
// ⚠️ Nguồn xoá **DÒNG CHI TIẾT TRƯỚC** rồi mới xoá đầu phiếu (`SerStockInDetailDelete` → `delete from`
//   `Ser_Inv_StockIn`), và ghi vào **BA** DB (`_dbMain`, `_dbWH`, `_dbDealer` khi không phải WS Main).
//   MiniHTC một DB ⇒ xoá một lần, giữ đúng THỨ TỰ chi tiết → đầu phiếu.
// 📌 Nguồn còn kiểm `OldStockInID`/`OldStockOutID` có tồn tại không (phiếu điều chỉnh trỏ về phiếu gốc) —
//   chỉ để **báo lỗi nếu phiếu gốc biến mất**, không chặn xoá; port giữ đúng: cảnh báo, không chặn.
// ===== 🔴 #292 SỬA phiếu kho — `SerStockInUpdate` / `SerStockOutUpdate` (port cũ THIẾU HẲN) =====
// 🆕 Tìm ra bằng cách **đếm WebMethod cùng gốc** (mở rộng sweep #291): gốc `SerStockIn*`/`SerStockOut*` có
//   43 hàm WS sống, MiniHTC mới có 9+9 endpoint ⇒ soát ra `Update` **chưa port**: màn chỉ TẠO được,
//   không SỬA được.
//
// ☠️ TRACE TWIN — bẫy "bản mới nhất": có `SerStockInUpdate_New20240115` (**2024-01-15**, mới nhất theo tên)
//   nhưng WS `WSCarSv.asmx.cs:14562` gọi **bản TRẦN** `SerStockInUpdate` ⇒ bản 2024 **CHẾT**.
//   (Tương tự `SerStockOutUpdate_New20240115` ở `:16350`.) Ngày trong tên mới tới đâu cũng không thay được
//   việc trace lời gọi.
//
// 🔴 HAI MÀN, HAI THIẾT KẾ GUARD KHÁC HẲN — đọc kỹ kẻo áp nhầm:
//   • **NHẬP** (`UpdateStockIn`): guard trên **TRẠNG THÁI HIỆN TẠI** — `CheckStockInNotPendingExecuting`
//     ⇒ chỉ sửa được khi phiếu đang `"1"` Mới tạo hoặc `"2"` Tiến hành. Và **KHÔNG ghi cột `Status`**:
//     sửa phiếu không đổi trạng thái.
//   • **XUẤT** (`UpdateStockOut`): **KHÔNG** guard trạng thái hiện tại. Thay vào đó, nếu client **có gửi**
//     `Status` thì mới kiểm — và kiểm bằng `CheckStockOutNotPending` (Pending `"1"` / Reject `"5"`) —
//     rồi **GHI** cột `Status`. Không gửi ⇒ không kiểm, không ghi.
//     ⇒ ở màn xuất, `Status` gửi lên chỉ được đặt về `"1"` hoặc `"5"`.
//
// ⚠️ `OldStockInID`: nguồn ghi giá trị khi khác rỗng, **ngược lại ghi DBNull** ⇒ gửi rỗng là **XOÁ** liên kết
//   phiếu gốc, không phải "bỏ qua". Port giữ đúng.
app.MapPut("/api/stockins/{no}", async (string no, StockInUpdateDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });

    // Guard TRẠNG THÁI HIỆN TẠI: chỉ "1" Mới tạo hoặc "2" Tiến hành.
    if (h.Status != "1" && h.Status != "2")
        return Results.BadRequest(new { error = "Chỉ sửa được phiếu nhập ở trạng thái Mới tạo (1) hoặc Tiến hành (2).",
            status = h.Status });

    // CheckStockInFieldEmpty — nguồn bắt buộc các trường này.
    if (string.IsNullOrWhiteSpace(dto.StockInNo)) return Results.BadRequest(new { error = "Chưa nhập số phiếu nhập." });
    if (string.IsNullOrWhiteSpace(dto.SupplierID)) return Results.BadRequest(new { error = "Chưa chọn nhà cung cấp." });
    if (string.IsNullOrWhiteSpace(dto.WarehouseCode)) return Results.BadRequest(new { error = "Chưa chọn kho." });

    h.StockInNo = dto.StockInNo!.Trim().ToUpperInvariant();   // nguồn ToUpper
    h.SupplierID = dto.SupplierID; h.WarehouseCode = dto.WarehouseCode!.Trim().ToUpperInvariant();
    h.StockInType = dto.StockInType;
    if (dto.StockInDate.HasValue) h.StockInDate = dto.StockInDate.Value;
    h.Description = dto.Description; h.UserCode = dto.StaffID;
    h.DriverName = dto.DriverName; h.DrivingLicense = dto.DrivingLicense;
    h.DriverID = dto.DriverID; h.TruckNo = dto.TruckNo; h.BillNo = dto.BillNo;
    h.AdjustmentBy = dto.AdjustmentBy; h.AdjustmentDate = dto.AdjustmentDate; h.AdjustmentNote = dto.AdjustmentNote;
    // Rỗng ⇒ XOÁ liên kết phiếu gốc (nguồn ghi DBNull), không phải bỏ qua.
    h.OldStockInID = string.IsNullOrWhiteSpace(dto.OldStockInID) ? null : dto.OldStockInID!.Trim();
    // ⚠️ KHÔNG ghi Status — nguồn không đụng tới.

    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockInNo, status = h.Status, note = "Sửa phiếu KHÔNG đổi trạng thái (đúng nguồn)." });
}).RequireAuthorization();

app.MapDelete("/api/stockins/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });

    if (h.Status != "1" && h.Status != "5")
        return Results.BadRequest(new { error = "Chỉ xoá được phiếu nhập ở trạng thái Mới tạo (1) hoặc Huỷ (5).",
            status = h.Status, statusName = stockInStatusNames.TryGetValue(h.Status ?? "", out var sn) ? sn : null });

    // Phiếu điều chỉnh trỏ về phiếu gốc: nguồn CHỈ kiểm tra phiếu gốc còn không, KHÔNG chặn xoá.
    string? warn = null;
    if (!string.IsNullOrWhiteSpace(h.OldStockInID))
    {
        var oldExists = await db.PartStockIns.AnyAsync(x => x.OrgId == t.OrgId && x.StockInNo == h.OldStockInID);
        if (!oldExists) warn = "Không tìm thấy phiếu nhập gốc " + h.OldStockInID + " mà phiếu này điều chỉnh.";
    }

    // Nguồn xoá DÒNG CHI TIẾT trước, rồi mới xoá đầu phiếu.
    var lines = await db.PartStockInLines.Where(x => x.OrgId == t.OrgId && x.StockInId == h.Id).ToListAsync();
    db.PartStockInLines.RemoveRange(lines);
    db.PartStockIns.Remove(h);
    await db.SaveChangesAsync();
    return Results.Ok(new { stockInNo = no, deletedLines = lines.Count, warning = warn });
}).RequireAuthorization();

app.MapPost("/api/stockins/{no}/reject", async (string no, StockRejectDto dto, AppDbContext db, ITenantContext t, HttpContext http) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartStockIns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.StockInNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (string.IsNullOrWhiteSpace(dto.Reason)) return Results.BadRequest(new { error = "Bạn chưa nhập lý do hủy phiếu nhập." });
    // 🔴 Nguồn (`StockIn.cs:6476-6489`) chỉ `CheckExistStockIn` rồi gán Reject — **KHÔNG chặn trạng thái**.
    // Port cũ chặn `!= "Draft"` là guard CHẶT HƠN nguồn (sai chiều). Đã bỏ để đúng 1:1.
    // ⚠️ Hệ quả nguồn: huỷ phiếu đã Kết thúc KHÔNG hoàn lại tồn kho — đã ghi C0-bug4 để người quyết.
    var who = http.User.Identity?.Name ?? http.User.FindFirst("email")?.Value ?? "system";
    h.Status = "5"; h.RejectReason = dto.Reason!.Trim(); h.RejectedBy = who; h.RejectedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockInNo, status = h.Status });
}).RequireAuthorization();

// Tồn kho phụ tùng (Ser_Inv_PartStock — báo cáo tồn, đọc bởi FrmPartStockSearch/ReportStockBalance)
app.MapGet("/api/partstock", async (AppDbContext db, ITenantContext t, string? warehouse, string? part) =>
{
    var q = db.PartStocks.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(warehouse)) q = q.Where(s => s.WarehouseCode == warehouse);
    if (!string.IsNullOrWhiteSpace(part)) q = q.Where(s => s.PartCode.Contains(part.ToUpper()));
    var items = await q.OrderBy(s => s.PartCode).Take(1000).Select(s => new { s.WarehouseCode, s.PartCode, s.PartName, s.Location, s.OnHand }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴 #271 LSC CHỜ ĐỒNG BỘ SANG VELOCA =====
// Nguồn: `BizCarSv.ZTemp.cs:17199` (tìm danh sách) và `:17556` (lấy một LSC).
// 🔴 **THAY ĐỔI 20260323 CHỈ CÓ TRÊN MÁY 150** — bản laptop vẫn là dòng cũ, dòng cũ nay bị comment lại:
//     cũ : `Status not in ('CRE', 'REJ', 'NORE', 'PAID', 'FNS')`
//     mới: `Status not in ('CRE', 'REJ', 'NORE',         'FNS')`   // 20260323
//   ⇒ **LSC ĐÃ THANH TOÁN (`PAID`) NAY ĐƯỢC ĐỒNG BỘ**, trước đây bị loại. Đây là nới điều kiện nghiệp vụ,
//     không phải sửa lỗi cú pháp — port theo bản 150 (canonical, xem #269).
// ⚠️ Bốn mã bị loại KHÔNG phải "trạng thái xấu": `FNS` (đã giao xe) bị loại vì đã xong hẳn, còn `CRE`
//   (mới tạo) vì chưa có gì để đồng bộ. Đừng suy từ tên trạng thái.
// ⚠️ Cờ `SyncVelocaFlag` CHỈ được lọc ở nhánh LẤY MỘT LSC (chống đồng bộ lặp), nhánh tìm danh sách
//   **không** lọc — giữ đúng sự bất đối xứng đó, tham số `unsynced` để chọn.
app.MapGet("/api/repairorders/veloca-pending", async (AppDbContext db, ITenantContext t,
    string? ro, DateTime? checkInFrom, DateTime? checkInTo, bool? unsynced) =>
{
    // Bốn mã bị loại — nguyên văn nguồn bản 150 (KHÔNG còn PAID).
    var excluded = new[] { "Created", "Rejected", "NotResponding", "Finished" };
    var qy = db.RepairOrders.Where(x => x.OrgId == t.OrgId && !excluded.Contains(x.Status));
    if (!string.IsNullOrWhiteSpace(ro)) qy = qy.Where(x => x.RONo == ro!.Trim().ToUpperInvariant());
    if (checkInFrom.HasValue) qy = qy.Where(x => x.CheckInDate >= checkInFrom.Value);
    if (checkInTo.HasValue) qy = qy.Where(x => x.CheckInDate <= checkInTo.Value);
    // Chống đồng bộ lặp: chỉ nhánh lấy một LSC của nguồn mới có điều kiện này.
    if (unsynced == true) qy = qy.Where(x => x.SyncVelocaFlag == null || x.SyncVelocaFlag == "0");

    var items = await qy.OrderBy(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.RONo, x.LicensePlate, x.Vin, x.CusName, x.Status, x.CheckInDate, x.SyncVelocaFlag,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, excludedStatuses = excluded, items });
}).RequireAuthorization();

// #271 Đánh dấu đã đồng bộ Veloca (bộ đồng bộ gọi lại). Nguồn không có hàm riêng — cờ được ghi trong
//   chính luồng đồng bộ; MiniHTC chưa port tầng gọi Veloca (đã ghi nợ) nên tách ra một endpoint.
app.MapPost("/api/repairorders/{no}/veloca-synced", async (string no, AppDbContext db, ITenantContext t) =>
{
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no.Trim().ToUpperInvariant());
    if (r is null) return Results.NotFound(new { no });
    r.SyncVelocaFlag = "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RONo, r.SyncVelocaFlag });
}).RequireAuthorization();

// ===== Phiếu tiếp nhận xe dịch vụ (Ser_ReceptionF — port 1:1 FrmSerReceptionFMng) =====
app.MapGet("/api/receptions", async (AppDbContext db, ITenantContext t, string? status, string? plate) =>
{
    var q = db.Receptions.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(r => r.PlateNo.Contains(plate.ToUpper()));
    var rows = await q.OrderByDescending(r => r.Id).Take(500).ToListAsync();

    // ===== 🔴 #310 MỘT PHIẾU TIẾP NHẬN có thể sinh NHIỀU LỆNH SỬA CHỮA =====
    // Nguồn `Ser_ReceptionF_Delivery` (`Tab.cs:8487`) KHÔNG đọc một cột lệnh đã lưu; nó TÍNH:
    //   `select top 1 t_ro.RONo from Ser_RO t_ro where t.ReceptionFNo = t_ro.ReceptionFNo`
    //   `order by t_ro.CreatedDate desc`
    // ⇒ màn giao xe luôn hiện **lệnh TẠO GẦN NHẤT** của phiếu, không phải lệnh được gắn tay lần cuối.
    // ⚠️ Dòng đọc thẳng `--, ro.RONo` nằm ngay trên và **đã bị comment** — luật B: port dòng ĐANG CHẠY.
    // 🆕 Tìm ra nhờ sweep `top 1` lệch trục (#308) sau khi **sửa regex bắt `order by` xuống dòng** (#310).
    // ⚠️ `RONO` (cột cũ, gắn tay qua `/linkro`) GIỮ LẠI để không vỡ client; `roNoLatest` mới là số nguồn hiện.
    var recNos = rows.Select(r => r.ReceptionFNo).ToList();
    var roByReception = (await db.RepairOrders
            .Where(x => x.OrgId == t.OrgId && x.ReceptionFNo != null && recNos.Contains(x.ReceptionFNo))
            .Select(x => new { x.ReceptionFNo, x.RONo, x.CreatedAt })
            .ToListAsync())
        .GroupBy(x => x.ReceptionFNo!)
        // #310d: giữ CẢ NHÓM, không chỉ dòng đầu — vì quan hệ là 1-NHIỀU thì số lượng cũng là thông tin.
        .ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreatedAt).ToList());

    var items = rows.Select(r => new
    {
        r.ReceptionFNo, r.PlateNo, r.ModelName, r.CusName, r.CusPhoneNo, r.CusRequest,
        r.RONO, r.AppNo, r.Status, r.CreatedAt, r.DeliveredAt,
        // ⚠️ #310d: `roCount` phải là SỐ THẬT. Bản đầu tôi trả 0/1 theo "có mặt trong Dictionary" —
        //   tên trường hứa một phép ĐẾM mà giá trị chỉ là cờ tồn tại (đúng lớp lỗi C0-…tricesimusoctavus).
        roNoLatest = roByReception.TryGetValue(r.ReceptionFNo, out var lr) ? lr[0].RONo : null,
        roCount = roByReception.TryGetValue(r.ReceptionFNo, out var all) ? all.Count : 0,
    }).ToList();
    return Results.Ok(new { count = items.Count, pending = items.Count(x => x.Status == "Pending"),
        note = "roNoLatest = lệnh TẠO GẦN NHẤT của phiếu (đúng nguồn); RONO là cột gắn tay cũ, giữ cho client cũ.",
        items });
}).RequireAuthorization();

app.MapPost("/api/receptions", async (ReceptionDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.PlateNo)) return Results.BadRequest(new { error = "Cần biển số (PlateNo)." });
    var no = "RCP" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new Reception
    {
        OrgId = t.OrgId, ReceptionFNo = no, PlateNo = dto.PlateNo.Trim().ToUpperInvariant(), ModelName = dto.ModelName,
        CusName = dto.CusName, CusAddress = dto.CusAddress, CusPhoneNo = dto.CusPhoneNo, CusRequest = dto.CusRequest, Status = "Pending",
        AppNo = string.IsNullOrWhiteSpace(dto.AppNo) ? null : dto.AppNo!.Trim(),
    };
    db.Receptions.Add(r);

    // 🔴 #271 ĐÓNG LỊCH HẸN Ở HCC — nguồn gọi `HCC_Appointment_FinishOSX` ngay trong hàm tiếp nhận,
    //   **có điều kiện `if (!IsNullOrEmpty(strAppId))`** ⇒ khách vãng lai (không hẹn trước) không đẩy gì.
    //   Đây là vế ĐÓNG của cặp mở/đóng: mở khi tạo lịch hẹn (#270), đóng khi xe thật sự tới.
    string? appPush = null;
    if (r.AppNo is not null)
    {
        var app = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == r.AppNo);
        if (app is null) return Results.BadRequest(new { error = "Không tìm thấy lịch hẹn: " + r.AppNo });
        app.HCCFinishStatus = "P";      // chờ đẩy lệnh đóng sang HCC
        appPush = app.HCCFinishStatus;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReceptionFNo, r.PlateNo, status = r.Status, r.AppNo, hccFinishStatus = appPush });
}).RequireAuthorization();

// Gắn RO (kiểm tra RO tồn tại — tích hợp RepairOrder)
app.MapPost("/api/receptions/{no}/linkro", async (string no, ReceptionLinkDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.Receptions.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReceptionFNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (string.IsNullOrWhiteSpace(dto.RONO)) return Results.BadRequest(new { error = "Cần RONO." });
    var roNo = dto.RONO.Trim().ToUpperInvariant();
    var roExists = await db.RepairOrders.AnyAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (!roExists) return Results.BadRequest(new { error = $"Không tìm thấy RO {roNo}." });
    r.RONO = roNo;
    // #310: ghi CẢ CHIỀU NGƯỢC lên lệnh — nguồn tra theo `Ser_RO.ReceptionFNo`, không theo cột trên phiếu.
    //   Thiếu bước này thì `roNoLatest` luôn rỗng dù đã gắn lệnh.
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is not null) ro.ReceptionFNo = r.ReceptionFNo;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReceptionFNo, r.RONO, linkedOnRo = ro is not null });
}).RequireAuthorization();

// Giao xe (Approved) — cần đã gắn RO
app.MapPost("/api/receptions/{no}/deliver", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.Receptions.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReceptionFNo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.Status != "Pending") return Results.BadRequest(new { error = "Chỉ giao xe cho phiếu Tiếp nhận." });
    // #310: "đã có lệnh" xét theo NGUỒN (có lệnh nào mang ReceptionFNo này) chứ không chỉ theo cột gắn tay.
    var latest = await db.RepairOrders
        .Where(x => x.OrgId == t.OrgId && x.ReceptionFNo == r.ReceptionFNo)
        .OrderByDescending(x => x.CreatedAt).FirstOrDefaultAsync();
    if (string.IsNullOrWhiteSpace(r.RONO) && latest is null)
        return Results.BadRequest(new { error = "Chưa gắn RO, không thể giao xe." });
    r.Status = "Approved"; r.DeliveredAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.ReceptionFNo, status = r.Status, roNoLatest = latest?.RONo, r.RONO });
}).RequireAuthorization();

// ===== Phiếu xuất kho phụ tùng cho RO (Ser_RO_StockRequisition — port 1:1 FrmROStockRequisition) =====
// GAP parity đã vá (đối chiếu BizCarSv.Inventory.cs Ser_ROStockRequisition_Get + FrmROStockRequisition.txtNo_KeyDown):
// nguồn BỎ TIỀN TỐ "LS-" (số LSC) / "PX-" (số phiếu xuất) / "BG-" (số báo giá) TRƯỚC khi khớp theo RONo.
// Trước khi vá, tìm bằng "LS-VNN054-..." hoặc "PX-..." luôn ra rỗng vì so thẳng chuỗi có tiền tố.
app.MapGet("/api/stockreqs", async (AppDbContext db, ITenantContext t, string? status, string? ro) =>
{
    var q = db.StockReqs.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(s => s.Status == status);
    if (!string.IsNullOrWhiteSpace(ro))
    {
        var key = ro.Trim().ToUpperInvariant().Replace("LS-", "").Replace("PX-", "").Replace("BG-", "").Trim();
        q = q.Where(s => s.RONo.Contains(key));
    }
    var items = await q.OrderByDescending(s => s.Id).Take(500).Select(s => new
    {
        s.ReqNo, s.RONo, s.Status, s.CreatedAt, s.IssuedAt,
        lsNo = "LS-" + s.RONo,                                  // ô txtLSNo của form gốc
        s.DealerCode, s.Assistant, s.PlateNo, s.FrameNo, s.Note, // GAP đã vá: 5 cột form gốc bị bỏ sót
        lines = db.StockReqLines.Count(l => l.OrgId == t.OrgId && l.ReqId == s.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Tạo phiếu; nếu FromRO=true tự kéo phụ tùng của RO (tích hợp thật với RepairOrder)
app.MapPost("/api/stockreqs", async (StockReqDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.RONo)) return Results.BadRequest(new { error = "Cần RONo." });
    var roNo = dto.RONo.Trim().ToUpperInvariant();
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (ro is null) return Results.NotFound(new { error = $"Không tìm thấy RO {roNo}." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode)).ToList();
    List<StockReqLine> pulled = new();
    if (dto.FromRO)
    {
        var roParts = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == ro.Id).ToListAsync();
        pulled = roParts.Select(p => new StockReqLine { OrgId = t.OrgId, PartCode = p.PartCode, PartName = p.PartName, Quantity = p.NeedQty, Unit = p.Unit }).ToList();
    }
    if (lines.Count == 0 && pulled.Count == 0) return Results.BadRequest(new { error = "Không có dòng phụ tùng (đặt fromRO=true để kéo từ RO, hoặc gửi lines)." });
    var no = "PX-" + roNo;
    var h = new StockReq
    {
        OrgId = t.OrgId, ReqNo = no, RONo = roNo, Status = "Draft",
        // GAP đã vá: nhận 5 trường form gốc; không gửi thì kế thừa từ RO (đúng nguồn: join Ser_RO/Ser_Customer)
        DealerCode = dto.DealerCode,
        Assistant = dto.Assistant,
        PlateNo = dto.PlateNo ?? ro.LicensePlate,   // Ser_Customer.PlateNo ↔ RepairOrder.LicensePlate
        FrameNo = dto.FrameNo ?? ro.Vin,            // Ser_Customer.FrameNo ↔ số khung/VIN
        Note = dto.Note
    };
    db.StockReqs.Add(h); await db.SaveChangesAsync();
    foreach (var l in pulled) { l.ReqId = h.Id; db.StockReqLines.Add(l); }
    foreach (var l in lines)
        db.StockReqLines.Add(new StockReqLine { OrgId = t.OrgId, ReqId = h.Id, PartCode = l.PartCode.Trim(), PartName = l.PartName, Location = l.Location, Quantity = l.Quantity <= 0 ? 1 : l.Quantity, Unit = l.Unit });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.ReqNo, h.RONo, lines = pulled.Count + lines.Count, status = h.Status });
}).RequireAuthorization();

app.MapGet("/api/stockreqs/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.StockReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo.ToUpper() == no);
    if (h is null) return Results.NotFound(new { no });
    var lines = await db.StockReqLines.Where(l => l.OrgId == t.OrgId && l.ReqId == h.Id)
        .Select(l => new { l.PartCode, l.PartName, l.Location, l.Quantity, l.Unit }).ToListAsync();
    return Results.Ok(new { h.ReqNo, h.RONo, h.Status, count = lines.Count, lines });
}).RequireAuthorization();

app.MapPost("/api/stockreqs/{no}/issue", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.StockReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReqNo.ToUpper() == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.Status != "Draft") return Results.BadRequest(new { error = "Chỉ xuất được phiếu Draft." });
    h.Status = "Issued"; h.IssuedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.ReqNo, status = h.Status });
}).RequireAuthorization();

// ===== Lệnh sửa chữa RO (Ser_RO — port 1:1 FrmRepairOrder, TCMotor DMSCarSv) =====
// Luồng chính của lệnh sửa chữa (6 bước đi thẳng).
string[] _roFlow = { "HasRO", "InGarage", "Repaired", "CheckEnd", "Paid", "Finished" };

// 🔴 Bộ trạng thái ĐẦY ĐỦ của nguồn (TConst.Ser_ROStatus) — port cũ mới có 6/12.
// Sáu trạng thái NGOÀI luồng thẳng nhưng có thật trong nghiệp vụ xưởng:
//   Created (CRE) · PrintedQuote (PRT) · Wait4Part (W4P) · HasPart (HPA) · Rejected (REJ) · NotResponding (NORE)
// Thiếu chúng thì KHÔNG diễn tả được: RO mới tạo chưa lập lệnh, RO chờ phụ tùng, và đặc biệt là HUỶ RO.
var roStatusSourceCodes = new Dictionary<string, string>
{
    ["Created"] = "CRE",            // Mới tạo
    ["PrintedQuote"] = "PRT",       // In báo giá
    ["Wait4Part"] = "W4P",          // Đợi phụ tùng
    ["HasPart"] = "HPA",            // Đã có phụ tùng
    ["HasRO"] = "HRO",              // Lập lệnh sửa chữa
    ["Rejected"] = "REJ",           // Huỷ
    ["InGarage"] = "INGA",          // Vào sửa chữa
    ["CheckEnd"] = "CEND",          // Kiểm tra cuối cùng
    ["Repaired"] = "RPRD",          // Sửa xong
    ["Paid"] = "PAID",              // Đã thanh toán
    ["Finished"] = "FNS",           // Đã hoàn thành
    ["NotResponding"] = "NORE",     // Chưa dùng
};

// Nhóm trạng thái dùng để TÌM KIẾM (TConst.Ser_RO_Stage4Search) — KHÔNG suy được từ luồng:
// ⚠️ "Sửa xong" gồm CẢ `Paid`; và nhóm "Hủy, Hẹn lại" gồm Wait4Part/HasPart/NotResponding
//    nhưng KHÔNG gồm `Rejected` — đúng nguyên văn nguồn, không tự sắp lại cho "hợp lý".
var roStage4Search = new Dictionary<string, string[]>
{
    ["Wait4Repair"] = new[] { "Created", "PrintedQuote", "HasRO" },   // Chờ sửa (CRE,PRT,HRO)
    ["Repairing"] = new[] { "InGarage" },                             // Đang sửa (INGA)
    ["Repaired"] = new[] { "Repaired", "Paid" },                      // Sửa xong (RPRD,PAID)
    ["Finished"] = new[] { "Finished" },                              // Đã giao xe (FNS)
    ["Cancel"] = new[] { "Wait4Part", "HasPart", "NotResponding" },    // Hủy, Hẹn lại (W4P,HPA,NORE)
};

/// <summary>
/// RO được coi là ĐÃ HOÀN TẤT (căn cứ sinh chăm sóc khách hàng, thống kê xe đã làm dịch vụ).
/// Nguồn dùng đúng cặp `ro.Status in ('PAID','FNS')` — KHÔNG phải chỉ mỗi "Finished".
/// </summary>
string[] roCompletedStatuses = { "Paid", "Finished" };

// Danh mục trạng thái RO + nhóm tìm kiếm, để client dựng bộ lọc đúng như WinForm.
// ===== 🔴 #284 NHÃN HIỂN THỊ TRẠNG THÁI LSC — `StatusName` (khác NHÓM TÌM KIẾM đã port) =====
// Nguồn: `DMSCarSv/TERP.BizCarSv/BizCarSv.Service.RO.cs:1327-1340`, viết THẲNG trong SQL của
//   `Ser_RO_GetStatusList02_GetClaimX_New20230220`.
// 🆕 Tìm ra nhờ **sweep luật che `ELSE '******'`** (sinh từ #283): quét cả DMSCarSv + 2010.HTC được
//   **24 hit** (sau khi loại file chết) — tất cả thuộc họ `Ser_RO_GetStatusList02*`, tức **cùng một màn**
//   với cái iCIC đã port ở #283. Nhánh 2010.HTC `ERP.V15.DataWH.Release.2025`: **0 hit**.
// ✅ TRACE TWIN: WS `WSCarSv.asmx.cs:10149` gọi `Ser_RO_GetStatusList02_New20230220` ⇒ bản trần
//   (`Service01.cs:1214`) và `_WH` (`WH.cs:30391`) CHẾT.
//
// 🔴 HAI BẢNG PHÂN NHÓM KHÁC NHAU cho HAI mục đích — port cũ mới có một:
//   • `roStage4Search` (đã có): nhóm để **TÌM KIẾM**, gộp `Repaired + Paid` vào "Sửa xong".
//   • `roStatusDisplayNames` (MỚI): nhãn để **HIỂN THỊ**, **TÁCH RIÊNG** `PAID` = "Thanh toán xong".
//     Nguồn ghi chú ngay tại dòng: *"Issue 981: [Trạng thái báo giá] - thêm trạng thái thanh toán xong"*
//     ⇒ việc tách là **thay đổi nghiệp vụ có số hiệu**, không phải trùng lặp.
// ⚠️ `REJ` = "Lệnh hủy" đứng RIÊNG, còn "Hủy, Hẹn lại" là `W4P/HPA/NORE` — khớp đúng điều đã ghi trong sổ:
//   nhóm "Hủy, Hẹn lại" **KHÔNG** gồm `Rejected`.
// ⚠️ Bản CŨ dùng hàm SQL `dbo.ROStatus_GetStatusNameByCode(ro.Status)`; bản LIVE **viết thẳng CASE** ⇒
//   bảng nhãn chuẩn nay nằm trong code, không nằm trong DB.
// ===== 🔴 #286 ĐÍNH CHÍNH #284: nhãn trạng thái LSC là **THEO MÀN**, KHÔNG có bảng toàn cục =====
// #284 dựng MỘT bảng nhãn dùng chung — SAI. Quét lại nhãn của riêng mã `W4P` trên toàn cây (đã loại file
// chết) ra **BA giá trị khác nhau ở BA màn**, cả ba đều LIVE:
//   • `Ser_RO_HomeX` (`BizCarSv.Tab.cs:1379`, WS **Tab** `WSCarSvTab.asmx.cs:4048` → `Home_Get`) → "Đợi phụ tùng"
//   • `Ser_RO_GetStatusList02_GetClaimX` (`Service.RO.cs`, WS CarSv)                              → "Hủy, Hẹn lại"
//   • báo cáo XUẤT KHO (`Inventory.StockOut.cs:18584`, WS CarSv)                                  → "Không dùng"
// ⇒ cùng một mã, ba nhãn; dùng chung một bảng là hiển thị SAI ở hai trong ba màn.
//
// ⚠️ Bảng của màn Tab là bảng **CHI TIẾT NHẤT** (phân biệt CRE/PRT/HRO thành ba nhãn khác nhau, trong khi
//   hai màn kia gộp cả ba thành "Chờ sửa") — nhưng KHÔNG được lấy nó làm bảng chung.
// ☠️ Bảng Tab có LỖI NGUỒN: `when 'REJ' then N'Lập lệnh sửa chữa'` — lặp y nguyên nhãn của `HRO` ngay
//   dòng trên; `REJ` là **huỷ**, không thể là "Lập lệnh sửa chữa". Giữ NGUYÊN VĂN (màn Tab đang hiện vậy),
//   đánh dấu rõ để không ai đọc nhãn rồi suy ngược ra nghiệp vụ.
var roStatusDisplayNamesByScreen = new Dictionary<string, Dictionary<string, string>>
{
