app.MapGet("/api/repairorders", async (AppDbContext db, ITenantContext t, string? status, string? plate, string? stage) =>
{
    var q = db.RepairOrders.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    // Lọc theo NHÓM trạng thái tìm kiếm của nguồn (Wait4Repair/Repairing/Repaired/Finished/Cancel).
    if (!string.IsNullOrWhiteSpace(stage) && roStage4Search.TryGetValue(stage, out var stageStatuses))
        q = q.Where(r => stageStatuses.Contains(r.Status));
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(r => r.LicensePlate.Contains(plate.ToUpper()));
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.RONo, r.LicensePlate, r.Vin, r.CusName, r.Km, r.CheckInDate, r.PlanedDeliveryDate, r.CusWaiting, r.Status, r.RejectNote,
        r.CusAddress, r.CusTel, r.CusTaxCode, r.ModelID, r.IsReRepair, r.ROType,   // #343 §12
        // #266 §12: 10 cột thẻ hội viên / điểm
        r.FlagCardExist, r.FlagIsDLQuery, r.Creator,   // #283 §12
        r.CardNoInv, r.CardTypeInv, r.CardTypeExpectInv,
        r.PointEndInv, r.PointRankTotalInv, r.PointConsumptionPrm,
        r.MemberNo, r.PointVoucher,
        services = db.RoServiceItems.Count(s => s.OrgId == t.OrgId && s.RoId == r.Id),
        parts = db.RoPartItems.Count(p => p.OrgId == t.OrgId && p.RoId == r.Id),
        total = db.RoServiceItems.Where(s => s.OrgId == t.OrgId && s.RoId == r.Id).Sum(s => (decimal?)s.Amount) ?? 0
              + (db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == r.Id).Sum(p => (decimal?)(p.NeedQty * p.UnitPrice)) ?? 0)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/repairorders", async (RepairOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.LicensePlate)) return Results.BadRequest(new { error = "Cần biển số (LicensePlate)." });
    var no = "RO" + DateTime.Now.ToString("yyMMddHHmmss");
    // ===== 🔴 #343 SÁU CỘT `Ser_RO` có entity nhưng CHƯA CÓ ĐƯỜNG GHI =====
    // Tìm bằng `_audit/sweep_dead_column.js` (viết ở lượt này, tổng quát hoá cách dò tay của #337/#342).
    //   Sweep đã **TỰ KIỂM**: chạy trên cây trước #337 thì tìm ra đúng hai cột `RoPartItem.ExpenseType`
    //   và `RoServiceItem.ExpenseType` — hai ca trước đây phải dò tay ⇒ sweep bắt được ca đã biết.
    // Đối chiếu nguồn, đếm số chỗ ghi vào **đúng bảng `dt_Ser_RO`**:
    //   `CusAddress` 14 · `CusTel` 14 · `IsReRepair` 14 · `ROType` 10 · `CusTaxCode` 2 · `ModelID` 2
    //
    // ⚠️ `IsReRepair` (**sửa chữa lại**) chính là dữ liệu mà KPI cần cho chỉ tiêu "số lượt sửa chữa lại",
    //   nhưng nguồn **ĐÓNG CỨNG 0** cho chỉ tiêu đó (`, 0 CountSCCLocal_SCL` — xem #335).
    //   ⇒ Cột CÓ dữ liệu mà báo cáo KHÔNG dùng. Port cột theo nguồn; **không** tự tính chỉ tiêu (lệ #299).
    // ⚠️ `ROType` ở **cấp LỆNH** khác `RoServiceItem.ROType` ở **cấp DÒNG**; KPI đếm theo cấp DÒNG (#335).
    //   Hai cột trùng tên, khác cấp — đừng dùng thay cho nhau.
    // 📌 KHÔNG port `FlagIsDLQuery` và `PointVoucher`: grep nguồn ra **0** chỗ ghi vào `Ser_RO`
    //   ⇒ nghi là cột do chính port tự thêm. Để nguyên, không bịa đường ghi.
    var r = new RepairOrder
    {
        OrgId = t.OrgId, RONo = no, LicensePlate = dto.LicensePlate.Trim().ToUpperInvariant(), Vin = dto.Vin, CusName = dto.CusName, Km = dto.Km,
        CheckInDate = dto.CheckInDate ?? DateTime.Now, PlanedDeliveryDate = dto.PlanedDeliveryDate, CusRequest = dto.CusRequest,
        CarStatus = dto.CarStatus, CusWaiting = dto.CusWaiting, Status = "HasRO",
        // 4 cột phục vụ màn Lịch sử dịch vụ (FrmServiceHistory); DealerCode là khoá của luật CanShowDetail
        DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(),
        TrademarkNameModel = dto.TrademarkNameModel, ColorCode = dto.ColorCode, Assistant = dto.Assistant,
        // #266 §12: nhóm thẻ hội viên / điểm.
        //  ⚠️ Nhóm hậu tố `Inv` là SNAPSHOT lúc lập hoá đơn ⇒ CHỈ nhận `MemberNo`/`FlagCardExist` lúc tạo LSC;
        //     các cột `*Inv` và `PointVoucher` do luồng LẬP HOÁ ĐƠN (`FrmInvoice`) chốt — chưa port,
        //     KHÔNG cho client tự đặt (tránh sửa được số liệu đã chốt trên hoá đơn).
        MemberNo = dto.MemberNo,
        ReceptionFNo = string.IsNullOrWhiteSpace(dto.ReceptionFNo) ? null : dto.ReceptionFNo!.Trim().ToUpperInvariant(),   // #310 §12
        // #320 §12: gán 27 cột của bản LIVE.
        AdvisoryCode = dto.AdvisoryCode, AdvisoryPhone = dto.AdvisoryPhone, CarID = dto.CarID,
        CarWashRequested = dto.CarWashRequested, CusTypeID = dto.CusTypeID, DlrPDIReqNo = dto.DlrPDIReqNo,
        EngineerID = dto.EngineerID, FlagOnlyPoint = dto.FlagOnlyPoint, FlagPause = dto.FlagPause,
        IDCardNo = dto.IDCardNo, InsNo = dto.InsNo, InsuranceDeductible = dto.InsuranceDeductible,
        InvoiceBy = dto.InvoiceBy, LevelOfInspection = dto.LevelOfInspection,
        ModifyBy = dto.ModifyBy, ModifyDate = dto.ModifyDate, PayByCard = dto.PayByCard,
        PlanedDuration = dto.PlanedDuration, ReminderMaintanceDate = dto.ReminderMaintanceDate,
        ReminderMaintanceKm = dto.ReminderMaintanceKm, ServiceStatus = dto.ServiceStatus,
        TermsOfRepair = dto.TermsOfRepair, UseSHPart = dto.UseSHPart, WorkDoneSoon = dto.WorkDoneSoon,
        CreatedBy = dto.CreatedBy, LogLUBy = dto.LogLUBy, LogLUDateTime = dto.LogLUDateTime, FlagCardExist = dto.FlagCardExist,
        // #343 §12 — sáu cột trước nay không đường nào ghi.
        CusAddress = dto.CusAddress, CusTel = dto.CusTel, CusTaxCode = dto.CusTaxCode,
        ModelID = dto.ModelID, IsReRepair = dto.IsReRepair, ROType = dto.ROType
    };
    db.RepairOrders.Add(r); await db.SaveChangesAsync();
    foreach (var s in dto.Services ?? new())
    {
        if (string.IsNullOrWhiteSpace(s.SerCode)) continue;
        // Tiền hạng mục DỊCH VỤ theo nguồn: Factor * Price * (1 + VAT*0.01) — KHÔNG có cột Quantity riêng.
        // Client cũ vẫn truyền thẳng Amount; có Price thì tính lại cho đúng công thức nguồn.
        var serviceAmount = s.Price > 0 ? s.Factor * s.Price * (1 + s.Vat / 100m) : s.Amount;
        db.RoServiceItems.Add(new RoServiceItem { OrgId = t.OrgId, RoId = r.Id, SerCode = s.SerCode.Trim(), SerName = s.SerName, Cause = s.Cause, Engineer = s.Engineer, Amount = serviceAmount, ROType = s.ROType, Factor = s.Factor, Price = s.Price, Vat = s.Vat, ActManHour = s.ActManHour, ExpenseType = s.ExpenseType, InsurancePrice = s.InsurancePrice, CamID = s.CamID });
    }
    foreach (var p in dto.Parts ?? new())
    {
        if (string.IsNullOrWhiteSpace(p.PartCode)) continue;
        // Tiền dòng PHỤ TÙNG theo nguồn: Factor * Quantity * Price * (1 + VAT*0.01).
        var partQty = p.NeedQty <= 0 ? 1 : p.NeedQty;
        var partAmount = p.Factor * partQty * p.UnitPrice * (1 + p.Vat / 100m);
        db.RoPartItems.Add(new RoPartItem { OrgId = t.OrgId, RoId = r.Id, PartCode = p.PartCode.Trim(), PartName = p.PartName, Unit = p.Unit, NeedQty = partQty, UnitPrice = p.UnitPrice, Factor = p.Factor, Vat = p.Vat, Amount = partAmount, Note = p.Note, ExpenseType = p.ExpenseType, FlagAccessory = p.FlagAccessory ?? "0", InsurancePrice = p.InsurancePrice, CamID = p.CamID });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RONo, r.LicensePlate, status = r.Status });
}).RequireAuthorization();

// Bảng theo dõi tiến độ RO (Ser_RO_Stage — port 1:1 FrmTrackingProcess): kanban theo trạng thái
app.MapGet("/api/repairorders/board", async (AppDbContext db, ITenantContext t) =>
{
    var flow = new[] { "HasRO", "InGarage", "Repaired", "CheckEnd", "Paid", "Finished" };
    var ros = await db.RepairOrders.Where(r => r.OrgId == t.OrgId).OrderByDescending(r => r.Id).Take(1000)
        .Select(r => new { r.RONo, r.LicensePlate, r.CusName, r.Km, r.PlanedDeliveryDate, r.CusWaiting, r.Status }).ToListAsync();
    var columns = flow.Select(st => new
    {
        status = st,
        count = ros.Count(r => r.Status == st),
        items = ros.Where(r => r.Status == st).Select(r => new { r.RONo, r.LicensePlate, r.CusName, r.Km, r.PlanedDeliveryDate, r.CusWaiting }).ToList()
    }).ToList();
    return Results.Ok(new { total = ros.Count, columns });
}).RequireAuthorization();

app.MapGet("/api/repairorders/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });
    var services = await db.RoServiceItems.Where(s => s.OrgId == t.OrgId && s.RoId == r.Id)
        .Select(s => new { s.SerCode, s.SerName, s.Cause, s.Result, s.Engineer, s.ROType, s.Factor, s.Price, s.Vat, s.ActManHour, s.Amount, s.ExpenseType, s.InsurancePrice, s.CamID }).ToListAsync();   // #280 §12 + #342 + #367
    var parts = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == r.Id)
        .Select(p => new { p.PartCode, p.PartName, p.Unit, p.NeedQty, p.UnitPrice, p.Factor, p.Vat, lineTotal = p.Amount, p.Note, p.CamID }).ToListAsync();
    return Results.Ok(new
    {
        r.RONo, r.LicensePlate, r.Vin, r.CusName, r.Km, r.CheckInDate, r.PlanedDeliveryDate, r.CusRequest, r.CarStatus, r.CusWaiting, r.Status,
        services, parts,
        total = services.Sum(s => s.Amount) + parts.Sum(p => p.lineTotal)
    });
}).RequireAuthorization();

// Gán kỹ thuật viên cho 1 dòng công việc trong RO (port 1:1 FrmSerItemEngineerList — picker 2 lưới chuyển qua lại,
// TCMotor DMSCarSv/Services): lưu danh sách KTV đã chọn thành chuỗi "no1,no2,..." vào RoServiceItem.Engineer.
app.MapPost("/api/repairorders/{no}/services/{serCode}/engineers", async (string no, string serCode, RoEngineersDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });
    var item = await db.RoServiceItems.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.RoId == r.Id && s.SerCode == serCode);
    if (item is null) return Results.NotFound(new { serCode });
    var codes = (dto.EngineerNos ?? new List<string>()).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct().ToList();
    item.Engineer = codes.Count == 0 ? null : string.Join(",", codes);
    await db.SaveChangesAsync();
    return Results.Ok(new { no, serCode, engineers = codes });
}).RequireAuthorization();

// Chuyển trạng thái theo đúng chuỗi Ser_RO_Stage
app.MapPost("/api/repairorders/{no}/advance", async (string no, RoAdvanceDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });
    if (r.Status == "Rejected") return Results.BadRequest(new { error = "Lệnh đã bị từ chối, không thể chuyển trạng thái." });
    var target = (dto.ToStatus ?? "").Trim();
    var curIdx = Array.IndexOf(_roFlow, r.Status);
    var tgtIdx = Array.IndexOf(_roFlow, target);
    if (tgtIdx < 0) return Results.BadRequest(new { error = "ToStatus không hợp lệ. Chuỗi: HasRO→InGarage→Repaired→CheckEnd→Paid→Finished" });
    // ===== 🔴 #341 BƯỚC `InGarage` CÓ **BA** TIỀN NHIỆM, không phải một =====
    // Nguồn (`Service01.cs:9507`): ném lỗi chỉ khi trạng thái cũ **không thuộc** ba mã
    //   `Create` (**CRE** — lập báo giá) · `Print` (**PRT** — in báo giá) · `HasRO` (**HRO** — lập lệnh).
    //   ⇒ Xe có thể vào xưởng thẳng từ lúc **mới lập / đã in báo giá**, không bắt buộc qua "Lập lệnh".
    // Luồng thẳng `_roFlow` chỉ cho `HasRO → InGarage` ⇒ chặn nhầm hai lối vào có thật.
    var inGarageFrom = new[] { "Created", "PrintedQuote", "HasRO" };
    var okStep = target == "InGarage"
        ? inGarageFrom.Contains(r.Status)
        : tgtIdx == curIdx + 1;
    if (!okStep)
        return Results.BadRequest(new
        {
            error = target == "InGarage"
                ? $"Vào xưởng chỉ được từ {string.Join(" / ", inGarageFrom)} — hiện tại {r.Status}."
                : $"Chỉ tiến 1 bước từ {r.Status} sang {_roFlow[Math.Min(curIdx + 1, _roFlow.Length - 1)]}.",
        });

    // ===== 🔴 #341 GUARD TẠM DỪNG ở bước `Repaired` =====
    // Nguồn: `if (StringEqualIgnoreCase(Constants.Flag.Inactive, strFlagPause)) throw …InvalidFlagPause`
    //   ⇒ ném lỗi khi `FlagPause == "0"`. ⚠️ **Chiều cờ ngược trực giác** ("Inactive" mà lại CHẶN),
    //     nhưng đó đúng là điều kiện nguồn viết ⇒ port **NGUYÊN VĂN**, không tự đảo cho "hợp lý".
    if (target == "Repaired" && string.Equals(r.FlagPause, "0", StringComparison.OrdinalIgnoreCase))
        return Results.BadRequest(new
        {
            error = "Lệnh đang ở trạng thái tạm dừng (FlagPause = \"0\") — không chuyển sang Sửa xong được.",
            flagPause = r.FlagPause,
        });

    r.Status = target;

    // ===== 🔴 #341 BẢN ĐỒ MỐC ⇄ BƯỚC (đo bằng tập cột ghi của `SerROStatusUpdate`) =====
    //   `InGarage` → `StartDate` · `CheckEnd` → `CheckEndDate` · `Repaired` → `FinishedDate` + `TotalActHours`
    //   `Finished` → `ActualDeliveryDate` · `Paid` → `PaidCreatedDate` + `IsCusPaymentAll`
    // ✅ ĐÃ SO hai đường vào: `SerROStatusUpdate` (:9415) và `SerROStatusUpdateForAssignmentWork` (:9805)
    //   — **tập cột ghi từng bước TRÙNG KHÍT**. Ghi lại vì lệch giữa hai đường là điều đã gặp ở
    //   #332/#333/#334; lần này kiểm ra không lệch, nên không cần tách nhánh theo kênh.
    // Cat GIAY, dung "yyyy-MM-dd HH:mm" cua nguon. (`ToMinute` o endpoint khac la local function
    //   cua lambda do nen khong dung lai duoc o day.)
    static DateTime CutSec(DateTime v) => new DateTime(v.Year, v.Month, v.Day, v.Hour, v.Minute, 0);
    if (target == "InGarage") r.StartDate = CutSec(dto.StatusDate ?? DateTime.Now);
    if (target == "CheckEnd") r.CheckEndDate = CutSec(dto.StatusDate ?? DateTime.Now);
    // ===== 🔴 #340 SỬA NGỮ NGHĨA HAI MỐC — #326 đóng dấu `FinishedDate` SAI BƯỚC =====
    // TRACE TWIN: **HAI** WebMethod cùng sống trong codebehind `WSCarSv.asmx.cs`, khác hẳn việc chúng làm:
    //   `SerROToFinishedStatus` (:11358) → `_biz.SerROToFinishedStatus` (`Service01.cs:11394`) — bản TRẦN,
    //     chỉ là vỏ mỏng gọi `SerROStatusUpdate(…, Finished, "", "")` ⇒ **KHÔNG** kèm việc phụ nào.
    //   `SerROToFinishedStatusAndUpdateCusCare` (:11603) → `…_New20190621` (`ZTemp.cs:11622`) — bản ĐẦY ĐỦ,
    //     kèm 3 việc phụ đã port ở #326/#327.
    //   ⇒ Cùng một nghiệp vụ "giao xe" có **hai cổng vào với hệ quả khác nhau**; chọn cổng nào là do client.
    //
    // 🔴 `Ser_RO.FinishedDate` **KHÔNG** được ghi ở bước giao xe — **cả hai** bản LIVE đều không đụng tới nó.
    //   Nó được ghi ở `case Ser_RO_Stage.**Repaired**` (`Service01.cs:9648`):
    //     `dtRO.Rows[0]["FinishedDate"] = Convert.ToDateTime(strStatusDate).ToString("yyyy-MM-dd HH:mm");`
    //   ⇒ **`FinishedDate` = lúc SỬA XONG, KHÔNG phải lúc GIAO XE.** Tên cột gây hiểu nhầm;
    //     mốc giao xe là `ActualDeliveryDate`. #326 gán `FinishedDate` tại bước Finished ⇒ **SAI**,
    //     làm "lịch sử dịch vụ" (`order by ro.finisheddate desc`) sắp xếp theo nhầm sự kiện.
    //   ⚠️ Các dòng `["FinishedDate"] =` trong `_New20190621` thuộc bảng **`Ser_CustomerCare72h`**,
    //     KHÔNG phải `Ser_RO` — trùng tên cột giữa hai bảng, rất dễ đọc nhầm thành "có ghi".
    //
    // ⚠️ Nguồn lưu cả hai mốc dạng `"yyyy-MM-dd HH:mm"` ⇒ **CẮT GIÂY** (cùng lệ #328/#331).
    if (target == "Repaired")
    {
        // Bước SỬA XONG mới là chỗ đóng dấu `FinishedDate` (kèm `TotalActHours` — chưa port, xem nợ).
        var fin = dto.StatusDate ?? DateTime.Now;
        r.FinishedDate = new DateTime(fin.Year, fin.Month, fin.Day, fin.Hour, fin.Minute, 0);
        // `TotalActHours` chỉ ghi khi KHÁC RỖNG ⇒ rỗng = GIỮ NGUYÊN (khác nhóm "rỗng = xoá" #334).
        if (dto.TotalActHours is not null) r.TotalActHours = dto.TotalActHours;
    }
    if (target == "Finished")
    {
        // 🔴 GHI ĐÈ VÔ ĐIỀU KIỆN, không phải `??=`: bản trần gán thẳng `DateTime.Now`, còn bản đầy đủ
        //   gán từ tham số client và **rỗng ⇒ DBNull** (`else … = DBNull.Value`) — cả hai đều KHÔNG
        //   giữ giá trị cũ. Port cũ dùng `??=` nên lần giao xe sau không cập nhật được mốc.
        var del = dto.StatusDate ?? DateTime.Now;
        r.ActualDeliveryDate = new DateTime(del.Year, del.Month, del.Day, del.Hour, del.Minute, 0);
    }

    // ===== 🔴 #328 BƯỚC THANH TOÁN ghi **13 cột**, port cũ chỉ đổi `Status` =====
    // Nguồn `SerROStatusUpdatePaid_New20230228` (`Service.RO.cs:5736`) — TRACE TWIN: WS `:11483` gọi bản này;
    //   bản `_New20230220` ở WS `:11428` **đã bị comment**. Cụm có **7 bản**, hai trong số đó là định nghĩa
    //   **bị comment cả hàm** (`ZTemp.cs:8946/9753`) ⇒ sweep bỏ qua đúng, nhưng vẫn phải đọc WS mới chắc.
    //
    // 🔴 GUARD MỘT-TIỀN-TRẠNG-THÁI: nguồn bắt buộc `strOldStatus == Ser_RO_Stage.CheckEnd`, khác thì NÉM LỖI
    //   kèm `Status.Valid = CheckEnd`. ⇒ Chỉ đi từ **Kiểm tra cuối cùng** sang **Thanh toán**, không từ đâu
    //   khác. Luồng `_roFlow` của port cũ cũng cho đúng bước đó, nhưng KHÔNG ghi 12 cột dữ liệu kèm theo.
    if (target == "Paid")
    {
        // ⚠️ Nguồn cắt GIÂY: `Convert.ToDateTime(strStatusDate).ToString("yyyy-MM-dd HH:mm")`.
        var paidAt = dto.StatusDate ?? DateTime.Now;
        r.PaidCreatedDate = new DateTime(paidAt.Year, paidAt.Month, paidAt.Day, paidAt.Hour, paidAt.Minute, 0);

        // Nhóm ghi **VÔ ĐIỀU KIỆN** (không guard rỗng) — đúng nguồn: gửi rỗng là XOÁ giá trị cũ.
        r.IsCusPaymentAll = dto.IsCusPaymentAll;
        r.AmountFromMC = dto.AmountFromMC;
        r.PointTotal = dto.PointTotal;                       // điểm tích XÉT HẠNG
        r.AmountDiscountOther = dto.AmountDiscountOther;
        r.MemberNo = dto.MemberNo;
        r.CardNoInv = dto.CardNoInv;
        r.CardTypeInv = dto.CardTypeInv;
        r.CardTypeExpectInv = dto.CardTypeExpectInv;
        r.PointEndInv = dto.PointEndInv;
        r.PointRankTotalInv = dto.PointRankTotalInv;         // điểm tích TIÊU DÙNG — KHÁC PointTotal
        r.PointConsumptionPrm = dto.PointConsumptionPrm;
        r.LogLUDateTime = DateTime.Now; r.LogLUBy = dto.LogLUBy;
    }

    // ===== 🔴 #326 GIAO XE KÉO THEO **BA** VIỆC NỮA — port cũ chỉ đóng dấu mốc =====
    // Nguồn `SerROToFinishedStatusAndUpdateCusCare_New20190621` (`ZTemp.cs:11622`).
    //   TRACE TWIN: WS `:11603` gọi bản `_New20190621` ⇒ bản trần (`Service01.cs:11421`) CHẾT.
    //   Sweep #320 xếp đúng thứ tự lần này (bản LIVE nhiều cột nhất) — nhưng vẫn phải trace mới chắc.
    //
    // Ngoài việc đặt `Status = Finished` + `ActualDeliveryDate`, nguồn còn:
    //   (1) **CẬP NHẬT XE**: `Ser_Car.CurrentKm = RO.Km` · `CurrentServiceDate = RO.FinishedDate` (`:12209`).
    //       ⚠️ `CurrentServiceDate` chính là khoá của job NoShow (#269) ⇒ **không cập nhật thì job NoShow
    //         hiểu sai là khách chưa quay lại**.
    //   (2) **MỞ PHIẾU CHĂM SÓC**: nếu RO chưa có `Ser_CustomerCare` thì tạo mới ở `Status = Pending`,
    //       kèm dòng `Ser_CustomerCare72h` (`FinishedDate` lưu **CHỈ NGÀY** `"yyyy-MM-dd"`).
    //       ⚠️ Guard "chưa có thì mới tạo" ⇒ **idempotent**, gọi lại không sinh phiếu trùng.
    //   (3) **GHI NỢ HÃNG BẢO HIỂM** khi `strIsCusPaymentAll` ∈ { "0", "", null } — chú thích nguồn:
    //       *"neu khach hang khong dong y tra toan bo - se ghi no cho hang bao hiem"*.
    //       ⚠️ Ba giá trị được coi NHƯ NHAU; **thiếu tham số = khách KHÔNG trả hết** (mặc định ghi nợ).
    //       📌 NỢ ĐÃ KHAI: MiniHTC chưa có sổ công nợ bảo hiểm ⇒ lượt này chỉ **đánh dấu cờ** trên lệnh,
    //         chưa sinh bút toán. Ghi rõ để không tưởng đã làm xong.
    string? careNoCreated = null; bool carUpdated = false;
    int partPriceRefreshed = 0;
    if (target == "Finished")
    {
        // ===== 🔴 #327 (hoàn tất #326) LÀM MỚI GIÁ PHỤ TÙNG TỪ DANH MỤC KHI GIAO XE =====
        // Nguồn cùng hàm `SerROToFinishedStatusAndUpdateCusCare_New20190621` (`ZTemp.cs:11740-11795`):
        //   lấy `ser_mst_part.Price` / `.VAT` (**chỉ phụ tùng `IsActive = '1'`**) rồi ghi đè
        //   `Ser_ROPartItems.PartPrice` / `.PartVAT` ⇒ **giá trên lệnh được ĐỒNG BỘ LẠI tại thời điểm giao xe**,
        //   không giữ giá lúc lập lệnh. #326 mới port 3 việc kia, còn thiếu việc này.
        //
        // 🔴 LỖI THẬT CỦA NGUỒN — vòng lặp ghi nhầm chỉ số:
        //     for (int i = 0; i < dtUpd.Rows.Count; i++) {
        //         dtUpd.Rows[**0**]["PartPrice"] = dtUpd.Rows[**0**]["PartPriceUpd"];   // đáng lẽ Rows[i]
        //         dtUpd.Rows[**0**]["PartVAT"]   = dtUpd.Rows[**0**]["PartVATUpd"];
        //     }
        //   ⇒ lặp N lần nhưng **luôn ghi DÒNG ĐẦU** ⇒ chỉ dòng phụ tùng thứ nhất được làm mới giá,
        //     các dòng sau **giữ giá cũ**. Tác giả **không** giải thích ⇒ đây là lỗi gõ, không phải luật.
        //   ⇒ Theo lệ #272/#275: **KHÔNG bắt chước lỗi câm**. Port làm mới **MỌI dòng**, và trả
        //     `partPriceRefreshed` để ai đối chiếu WinForm biết vì sao số tiền lệch.
        //
        // 📌 Đã kiểm và KHÔNG phải lỗi: mệnh đề `--and t.ROID = '@ROID'` ở câu cuối bị comment trông như
        //   thiếu bộ lọc, nhưng phép `inner join` đi qua `#tblSer_ROPartItems` (vốn đã lọc theo ROID) nên
        //   kết quả vẫn chỉ gồm dòng của lệnh này ⇒ điều kiện đó **thừa**, không phải bug.
        var roParts = await db.RoPartItems.Where(pi => pi.OrgId == t.OrgId && pi.RoId == r.Id).ToListAsync();
        if (roParts.Count > 0)
        {
            var codes = roParts.Select(pi => pi.PartCode).Distinct().ToList();
            var master = (await db.ServiceParts
                    .Where(mp => mp.OrgId == t.OrgId && codes.Contains(mp.PartCode) && mp.FlagActive == "1")
                    .ToListAsync())
                .GroupBy(mp => mp.PartCode).ToDictionary(g => g.Key, g => g.First());
            foreach (var pi in roParts)
            {
                if (!master.TryGetValue(pi.PartCode, out var mp)) continue;   // không có trong danh mục ACTIVE ⇒ bỏ qua
                pi.UnitPrice = mp.Price;
                pi.Vat = mp.VAT ?? pi.Vat;
                partPriceRefreshed++;
            }
        }

        // (1) cập nhật XE theo số km và ngày hoàn tất của LỆNH
        if (!string.IsNullOrWhiteSpace(r.Vin))
        {
            var car = await db.ServiceCars.FirstOrDefaultAsync(c => c.OrgId == t.OrgId && c.FrameNo == r.Vin);
            if (car is not null)
            {
                if (decimal.TryParse(r.Km, out var km)) car.CurrentKm = km;
                car.CurrentServiceDate = r.FinishedDate;
                carUpdated = true;
            }
        }

        // (2) mở phiếu chăm sóc nếu LỆNH này chưa có (idempotent, đúng guard của nguồn)
        var hasCare = await db.CustomerCares.AnyAsync(c => c.OrgId == t.OrgId && c.RONo == r.RONo);
        if (!hasCare)
        {
            var careNo = "CC" + DateTime.Now.ToString("yyMMddHHmmss");
            db.CustomerCares.Add(new CustomerCare
            {
                OrgId = t.OrgId, CareNo = careNo, CareType = "24h", RONo = r.RONo,
                PlateNo = r.LicensePlate, CusName = r.CusName,
                CusPhone = CusDisplayPhone(r.CusTel, r.CusMobile),   // #316: bàn trước, di động sau
                // Nguồn lưu FinishedDate của bảng 72h ở dạng CHỈ NGÀY.
                ContactDate = r.FinishedDate?.Date,
                Status = "Pending",
            });
            careNoCreated = careNo;
        }
    }

    // ===== 🔴 #342 SINH BÚT TOÁN CÔNG NỢ BẢO HIỂM — nợ khai từ #326, nay trả =====
    // Nguồn `SerROToFinishedStatusAndUpdateCusCare_New20190621` (`ZTemp.cs:12138`):
    //   `if (strIsCusPaymentAll == "0" || == "" || == null)` ⇒ khách KHÔNG trả hết thì **ghi nợ hãng bảo hiểm**.
    //   (Ba giá trị như nhau — **thiếu tham số = khách không trả hết**, mặc định ghi nợ.)
    //
    // 🔴 SỐ TIỀN = `InsuranceAmount − InsuranceDeductible`, trong đó
    //   `InsuranceAmount = ServiceAmount + PartAmount` của **riêng các dòng `ExpenseType = 'ROINSURANCE'`**,
    //   mỗi dòng rẽ hai nhánh theo `InsurancePrice`:
    //     `InsurancePrice > 0`  ⇒ lấy **NGUYÊN** giá duyệt (không Factor, không VAT);
    //     ngược lại            ⇒ dòng công: `Factor×Price×(1+VAT%)` · dòng phụ tùng: `Factor×Qty×Price×(1+VAT%)`.
    //   ⚠️ Dòng phụ tùng có thêm `Quantity` so với dòng công — cùng lệ #337.
    //
    // 🔴 HAI GUARD của nguồn, cả hai đều NÉM LỖI (không phải bỏ qua):
    //   (1) Có tiền bảo hiểm mà xe **không gắn đơn bảo hiểm** ⇒ `SerROInsuranceNotFound`.
    //   (2) **Mức khấu trừ > số tiền bảo hiểm** ⇒ `…_InvalidDebitAmount` (nợ âm là vô nghĩa).
    bool insuranceDebtDue = target == "Finished"
        && (string.IsNullOrWhiteSpace(dto.IsCusPaymentAll) || dto.IsCusPaymentAll == "0");
    string? insuranceDebtNo = null; decimal? insuranceDebtAmount = null;
    if (insuranceDebtDue)
    {
        var insSvc = await db.RoServiceItems
            .Where(s => s.OrgId == t.OrgId && s.RoId == r.Id && s.ExpenseType == "ROINSURANCE").ToListAsync();
        var insPart = await db.RoPartItems
            .Where(p => p.OrgId == t.OrgId && p.RoId == r.Id && p.ExpenseType == "ROINSURANCE").ToListAsync();

        var amount = insSvc.Sum(s => s.InsurancePrice > 0m
                ? s.InsurancePrice!.Value
                : s.Factor * s.Price * (1m + s.Vat * 0.01m))
            + insPart.Sum(p => p.InsurancePrice > 0m
                ? p.InsurancePrice!.Value
                : p.Factor * p.NeedQty * p.UnitPrice * (1m + p.Vat * 0.01m));

        if (amount > 0m)
        {
            // Đơn bảo hiểm lấy từ XE (nguồn: `ins.InsNo = car.InsNo and car.DealerCode = ins.DealerCode`).
            var insNo = (await db.ServiceCars
                .Where(c => c.OrgId == t.OrgId && c.FrameNo == r.Vin)
                .Select(c => c.InsNo).FirstOrDefaultAsync());
            if (string.IsNullOrWhiteSpace(insNo))
                return Results.BadRequest(new
                {
                    error = "Lệnh có tiền bảo hiểm nhưng xe chưa gắn đơn bảo hiểm — không ghi nợ được.",
                    insuranceAmount = amount,
                });

            var deductible = r.InsuranceDeductible ?? 0m;
            if (deductible > amount)
                return Results.BadRequest(new
                {
                    error = "Mức khấu trừ lớn hơn số tiền bảo hiểm — số nợ sẽ âm.",
                    insuranceAmount = amount, insuranceDeductible = deductible,
                });

            insuranceDebtAmount = amount - deductible;
            insuranceDebtNo = "ID" + DateTime.Now.ToString("yyMMddHHmmss");
            db.InsDebits.Add(new InsDebit
            {
                OrgId = t.OrgId, DebitNo = insuranceDebtNo, InsNo = insNo, RONo = r.RONo,
                DebitAmount = insuranceDebtAmount.Value, PaidAmount = 0m,
                // Nguồn ghi ngày dạng "yyyy-MM-dd" (CHỈ NGÀY) và ghi chú cố định "Công nợ bảo hiểm".
                DebitDate = DateTime.Now.Date, Note = "Công nợ bảo hiểm",
                Status = "Open",
            });
        }
    }

    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        r.RONo, status = r.Status, r.FinishedDate, r.ActualDeliveryDate,
        // #340: nói rõ mốc nào thuộc bước nào để chỗ đối chiếu không hiểu nhầm theo tên cột.
        r.StartDate, r.CheckEndDate, r.TotalActHours,   // #341 §12
        finishedDateMeaning = "Lúc SỬA XONG (bước Repaired) — KHÔNG phải lúc giao xe.",
        actualDeliveryDateMeaning = "Lúc GIAO XE (bước Finished).",
        // #326: các việc kéo theo, trả về để đối chiếu với WinForm.
        carUpdated, careNoCreated,
        // #328 §12: dữ liệu bước THANH TOÁN có mặt ở CẢ POST lẫn kết quả.
        r.PaidCreatedDate, r.IsCusPaymentAll, r.AmountFromMC, r.PointTotal, r.AmountDiscountOther,
        r.MemberNo, r.CardNoInv, r.CardTypeInv, r.CardTypeExpectInv,
        r.PointEndInv, r.PointRankTotalInv, r.PointConsumptionPrm,
        // #327: số dòng phụ tùng đã được làm mới giá từ danh mục.
        partPriceRefreshed,
        partPriceRefreshedNote = partPriceRefreshed > 1
            ? "Port làm mới MỌI dòng; nguồn có lỗi vòng lặp (Rows[0] thay vì Rows[i]) nên CHỈ làm mới dòng đầu "
              + "⇒ tổng tiền web có thể khác WinForm. Khác biệt CÓ CHỦ ĐÍCH, xem chú thích #327."
            : null,
        insuranceDebtDue, insuranceDebtNo, insuranceDebtAmount,
        note = target == "Finished"
            ? "Giao xe: đã cập nhật CurrentKm/CurrentServiceDate của xe (khoá job NoShow #269) và mở phiếu "
              + "chăm sóc nếu chưa có. Ghi nợ hãng bảo hiểm CHƯA port — mới chỉ trả cờ insuranceDebtDue."
            : null,
    });
}).RequireAuthorization();

// Chuyển sang trạng thái NGOÀI luồng thẳng (nguồn có nhưng port cũ thiếu hẳn):
//   Wait4Part / HasPart  — chờ và đã có phụ tùng (RO tạm dừng giữa chừng)
//   Rejected             — HUỶ lệnh sửa chữa
//   NotResponding        — hẹn lại / chưa phản hồi
// Tách khỏi /advance vì đây KHÔNG phải bước tiến trong chuỗi mà là rẽ nhánh.
app.MapPost("/api/repairorders/{no}/setstatus", async (
    string no, RoAdvanceDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });

    var target = (dto.ToStatus ?? "").Trim();
    string[] offFlowStatuses = { "Created", "PrintedQuote", "Wait4Part", "HasPart", "Rejected", "NotResponding" };
    if (!offFlowStatuses.Contains(target))
        return Results.BadRequest(new { error = $"Trạng thái ngoài luồng hợp lệ: {string.Join(", ", offFlowStatuses)}. Muốn tiến theo chuỗi thì dùng /advance." });

    // Đã huỷ hoặc đã hoàn tất thì không rẽ nhánh nữa.
    if (r.Status == "Rejected") return Results.BadRequest(new { error = "Lệnh đã bị từ chối, không thể chuyển trạng thái." });
    if (r.Status == "Finished") return Results.BadRequest(new { error = "Lệnh đã hoàn thành, không thể chuyển trạng thái." });

    r.Status = target;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RONo, status = r.Status, sourceCode = roStatusSourceCodes[target] });
}).RequireAuthorization();

// Từ chối lệnh sửa chữa (port 1:1 FrmROReject, TCMotor DMSCarSv): set Rejected + ghi lý do.
app.MapPost("/api/repairorders/{no}/reject", async (string no, RoRejectDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });
    if (string.IsNullOrWhiteSpace(dto.Note)) return Results.BadRequest(new { error = "Chưa nhập lý do từ chối." });
    if (r.Status is "Finished" or "Rejected") return Results.BadRequest(new { error = "Lệnh đã kết thúc/đã từ chối, không thể từ chối." });
    r.Status = "Rejected"; r.RejectNote = dto.Note.Trim(); r.RejectedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RONo, r.Status, r.RejectNote });
}).RequireAuthorization();

// ===== Giá bán xe TCG theo spec (Mst_TCGCarSalePrice — port 1:1 FrmMstTCGCarSalePrice) =====
app.MapGet("/api/tcgsaleprices", async (AppDbContext db, ITenantContext t, string? spec) =>
{
    var q = db.TcgSalePrices.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(spec)) q = q.Where(p => p.SpecCode.Contains(spec.ToUpper()));
    var items = await q.OrderBy(p => p.SpecCode).Take(1000).Select(p => new { p.SpecCode, p.UnitPrice, p.Status }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/tcgsaleprices", async (TcgPriceDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.SpecCode)) return Results.BadRequest(new { error = "Cần SpecCode." });
    var spec = dto.SpecCode.Trim().ToUpperInvariant();
    var p = await db.TcgSalePrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SpecCode == spec);
    if (p is null) { p = new TcgSalePrice { OrgId = t.OrgId, SpecCode = spec }; db.TcgSalePrices.Add(p); }
    p.UnitPrice = dto.UnitPrice; p.Status = dto.Status ?? "1"; p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.SpecCode, p.UnitPrice, p.Status });
}).RequireAuthorization();

// Điều chỉnh hạn mức (FrmAdjustQuota — bản WinForm là STUB rỗng; implement thật: cộng/trừ delta vào Qty của Quota)
app.MapPost("/api/quotas/adjust", async (QuotaAdjustDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode) || string.IsNullOrWhiteSpace(dto.ModelCode) || string.IsNullOrWhiteSpace(dto.Period))
        return Results.BadRequest(new { error = "Cần DealerCode, ModelCode và Period." });
    var q = await db.Quotas.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.DealerCode == dto.DealerCode.Trim().ToUpperInvariant() && x.ModelCode == dto.ModelCode.Trim().ToUpperInvariant() && x.Period == dto.Period.Trim());
    if (q is null) return Results.NotFound(new { error = "Chưa có hạn mức để điều chỉnh." });
    var newQty = q.Qty + dto.DeltaQty;
    if (newQty < q.UsedQty) return Results.BadRequest(new { error = $"Hạn mức mới ({newQty}) < đã dùng ({q.UsedQty})." });
    q.Qty = newQty; q.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { q.DealerCode, q.ModelCode, q.Period, q.Qty, q.UsedQty, remain = q.Qty - q.UsedQty });
}).RequireAuthorization();

// ===== Giá thiết bị theo spec (Mst_DevicePrice_Spec — port 1:1 FrmMst_DevicePrice_Spec) =====
app.MapGet("/api/deviceprices", async (AppDbContext db, ITenantContext t, string? spec, string? device) =>
{
    var q = db.DevicePrices.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(spec)) q = q.Where(d => d.SpecCode == spec);
    if (!string.IsNullOrWhiteSpace(device)) q = q.Where(d => d.DeviceCode.Contains(device.ToUpper()));
    var items = await q.OrderBy(d => d.SpecCode).ThenBy(d => d.DeviceCode).Take(1000).Select(d => new
    { d.SpecCode, d.SpecDescription, d.DeviceTypeCode, d.DeviceCode, d.DeviceName, d.Price, d.VAT, d.PriceVAT, d.EffectiveDate, d.Status }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/deviceprices", async (DevicePriceDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.SpecCode) || string.IsNullOrWhiteSpace(dto.DeviceCode))
        return Results.BadRequest(new { error = "Cần SpecCode và DeviceCode." });
    if (string.IsNullOrWhiteSpace(dto.DeviceTypeCode))
        return Results.BadRequest(new { error = "Cần DeviceTypeCode." });
    var spec = dto.SpecCode.Trim().ToUpperInvariant();
    var dev = dto.DeviceCode.Trim().ToUpperInvariant();
    var ed = dto.EffectiveDate?.Date;
    // upsert theo (spec + device + ngày hiệu lực)
    var d = await db.DevicePrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SpecCode == spec && x.DeviceCode == dev && x.EffectiveDate == ed);
    if (d is null) { d = new DevicePrice { OrgId = t.OrgId, SpecCode = spec, DeviceCode = dev, EffectiveDate = ed }; db.DevicePrices.Add(d); }
    d.SpecDescription = dto.SpecDescription; d.DeviceTypeCode = dto.DeviceTypeCode; d.DeviceName = dto.DeviceName;
    d.Price = dto.Price; d.VAT = dto.VAT; d.PriceVAT = Math.Round(dto.Price * (1 + dto.VAT / 100m), 2);   // tính PriceVAT
    d.Status = dto.Status ?? "1"; d.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { d.SpecCode, d.DeviceCode, d.Price, d.VAT, d.PriceVAT });
}).RequireAuthorization();

// ===== Biểu chiết khấu/phạt theo ngày hiệu lực (Mst_Discount — port 1:1 FrmDiscount) =====
app.MapGet("/api/discounts", async (AppDbContext db, ITenantContext t, string? onDate) =>
{
    var q = db.Discounts.Where(d => d.OrgId == t.OrgId);
    var items = await q.OrderByDescending(d => d.EffectiveDate).Take(500).Select(d => new
    { d.EffectiveDate, d.DiscountPercent, d.PenaltyPercent, d.PenaltyPercentTCKT, d.FnExpPercent, d.PmtDsTCGPercent, d.Status }).ToListAsync();
    // biểu áp dụng cho 1 ngày = bản hiệu lực mới nhất ≤ ngày đó
    object? applicable = null;
    if (DateTime.TryParse(onDate, out var od))
        applicable = items.Where(x => x.EffectiveDate <= od).OrderByDescending(x => x.EffectiveDate).FirstOrDefault();
    return Results.Ok(new { count = items.Count, applicable, items });
}).RequireAuthorization();

app.MapPost("/api/discounts", async (DiscountDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.EffectiveDate is null) return Results.BadRequest(new { error = "Cần EffectiveDate." });
    var ed = dto.EffectiveDate.Value.Date;
    var d = await db.Discounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.EffectiveDate == ed);
    if (d is null) { d = new Discount { OrgId = t.OrgId, EffectiveDate = ed }; db.Discounts.Add(d); }
    d.DiscountPercent = dto.DiscountPercent; d.PenaltyPercent = dto.PenaltyPercent; d.PenaltyPercentTCKT = dto.PenaltyPercentTCKT;
    d.FnExpPercent = dto.FnExpPercent; d.PmtDsTCGPercent = dto.PmtDsTCGPercent; d.Status = dto.Status ?? "1"; d.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { d.EffectiveDate, d.DiscountPercent, d.PenaltyPercent });
}).RequireAuthorization();

// audit 2026-09-03: btnDelDb_Click gốc đánh dấu dòng DELETE rồi gộp vào Apply — port trước thiếu hoàn toàn thao tác xoá.
app.MapDelete("/api/discounts/{effectiveDate}", async (DateTime effectiveDate, AppDbContext db, ITenantContext t) =>
{
    var ed = effectiveDate.Date;
    var d = await db.Discounts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.EffectiveDate == ed);
    if (d is null) return Results.NotFound(new { effectiveDate = ed });
    db.Discounts.Remove(d);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = ed });
}).RequireAuthorization();

// ===== Xe kho bảo dưỡng gia hạn (StoF_MaintainMain — port 1:1 FrmMaintenanceWarehouse) =====
// ⛔ #B06 HỢP NHẤT THỰC THỂ SONG TRÙNG (ca sau #56 `RD_ReqInvoice`, #60 `Sto_DlvMinutes`):
//    cụm này trước đây ghi vào `MaintainExt` RIÊNG, trong khi `StoFMaintainMain` cũng port
//    **cùng bảng nguồn `StoF_MaintainMain`**. Giữ `StoFMaintainMain` (đúng khoá + có `MtnStatusMain`,
//    `UserCodeMtn`, kho đầu/hiện tại) và mang trọn nhóm `MtnExt*` sang. `MaintainExt` NGƯNG ghi.
// Trace twin LIVE: `btnSave_Click` → `MaintenanceService.StoF_MaintainMain_UpdMtnExtIn` → WS
//   (`WSHTC.asmx.cs:16546`) → **`_biz.StoF_MaintainMain_UpdMtnExtIn_New20181115`**
//   (`BizHTC.StorageFG.Frm.cs:2139`); `btnOutWarehouse_Click` → `…_UpdMtnExtOut_New20181115` (:2414).
//   Bản CHẾT: `Delete.BizHTC.Report.cs:160877/161149` (WS không gọi).
app.MapGet("/api/maintext", async (AppDbContext db, ITenantContext t, string? status, string? storage, string? sfMtnNo) =>
{
    var q = db.StoFMaintainMains.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(m => m.MtnExtStatusMain == status);
    // Nguồn `StoF_MaintainMain_Get(cboStorage)` lọc theo KHO HIỆN TẠI của xe.
    if (!string.IsNullOrWhiteSpace(storage)) q = q.Where(m => m.StorageCodeCurrent == storage);
    if (!string.IsNullOrWhiteSpace(sfMtnNo)) q = q.Where(m => m.SfMtnNo == sfMtnNo);
    var rows = await q.OrderByDescending(m => m.Id).Take(500).ToListAsync();
    var slipNos = rows.Select(r => r.SfMtnNo).Distinct().ToList();
    // 🔴 Luật HIỂN THỊ của nguồn (`FrmMaintenanceWarehouse.cs:99`): `MtnExtStartDTime` bị GHI ĐÈ bằng
    //    `APPROVEEVALDATETIME` của phiếu bảo trì cùng `SF_MtnNo` — KHÔNG phải giờ bấm nút.
    var slips = await db.StoFMaintains.Where(s => s.OrgId == t.OrgId && slipNos.Contains(s.SfMtnNo))
        .Select(s => new { s.SfMtnNo, s.ApproveEvalDateTime }).ToListAsync();
    var items = rows.Select(m => new
    {
        sfMtnNo = m.SfMtnNo, vin = m.VIN, m.MtnTp, m.ModelCode,
        m.StorageCodeInit, m.StorageCodeCurrent, m.UserCodeMtn, m.UserCodeMtnExt,
        mtnExtStartDTime = slips.FirstOrDefault(s => s.SfMtnNo == m.SfMtnNo)?.ApproveEvalDateTime ?? m.MtnExtStartDTime,
        mtnExtStartDTimeStored = m.MtnExtStartDTime,     // giá trị THẬT trong DB, tách khỏi giá trị hiển thị
        m.MtnExtEndDTime, m.MtnExtRemark,
        // rỗng ⇒ ép "NG" (FrmMaintenanceWarehouse.cs:95-96)
        mtnExtStatusMain = string.IsNullOrWhiteSpace(m.MtnExtStatusMain) ? "NG" : m.MtnExtStatusMain,
        m.MtnStatusMain, m.BeforeMtnStatusMain, m.AfterMtnStatusMain,
        m.MapLatitude, m.MapLongitude, m.Remark, m.LogLUDateTime, m.LogLUBy
    }).ToList();
    return Results.Ok(new
    {
        count = items.Count,
        inProgress = items.Count(x => x.mtnExtStatusMain == "IN"),
        done = items.Count(x => x.mtnExtStatusMain == "OUT"),
        items
    });
}).RequireAuthorization();

app.MapPost("/api/maintext", async (MaintExtDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Vin)) return Results.BadRequest(new { error = "Cần Vin." });
    if (string.IsNullOrWhiteSpace(dto.SfMtnNo)) return Results.BadRequest(new { error = "Cần SfMtnNo — nguồn khoá theo cặp (SF_MtnNo, VIN)." });
    var vin = dto.Vin.Trim().ToUpperInvariant();
    var no = dto.SfMtnNo!.Trim().ToUpperInvariant();
    var m = await db.StoFMaintainMains.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SfMtnNo == no && x.VIN == vin);
    if (m is null)
    {
        var slip = await db.StoFMaintains.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.SfMtnNo == no);
        m = new StoFMaintainMain { OrgId = t.OrgId, SfMtnNo = no, VIN = vin, StoFMaintainId = slip?.Id ?? 0, MtnExtStatusMain = "NG" };
        db.StoFMaintainMains.Add(m);
    }
    m.ModelCode = dto.ModelCode; m.StorageCodeCurrent = dto.StorageCode;
    // `gvMaintenanceWarehouse_ShowingEditor` chỉ cho sửa tay 3 cột: UserCodeMtnExt / MtnExtStatusMain / MtnExtRemark.
    m.MtnExtRemark = dto.MtnExtRemark; m.UserCodeMtnExt = dto.UserCodeMtnExt;
    m.LogLUDateTime = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { m.SfMtnNo, vin = m.VIN, status = m.MtnExtStatusMain });
}).RequireAuthorization();

// Vào (MtnExtIn) / Ra (MtnExtOut) bảo dưỡng gia hạn — port guard của
// `StoF_MaintainMain_UpdMtnExtIn_New20181115` (:2244-2263) và `…Out…` (:2515-2536).
app.MapPost("/api/maintext/{vin}/{action}", async (string vin, string action, MaintExtActionDto? dto, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("in" or "out")) return Results.BadRequest(new { error = "action = in|out" });
    vin = vin.Trim().ToUpperInvariant();
    var no = (dto?.SfMtnNo ?? "").Trim().ToUpperInvariant();
    if (no.Length == 0) return Results.BadRequest(new { error = "Cần SfMtnNo — nguồn khoá theo cặp (SF_MtnNo, VIN)." });
    var m = await db.StoFMaintainMains.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SfMtnNo == no && x.VIN == vin);
    // `StoF_MaintainMain_CheckDB(..., strFlagExistToCheck = Flag.Yes)`
    if (m is null) return Results.NotFound(new { sfMtnNo = no, vin });
    // `strMtnStatusMainToCheck = TConst.MtnStatus.Approve` ⇒ chỉ dòng đã DUYỆT bảo trì ("A").
    if (m.MtnStatusMain != "A") return Results.BadRequest(new { error = "Dòng bảo trì chưa duyệt (MtnStatusMain phải = 'A')." });
    // `strAfterMtnStatusMainToCheck = TConst.Flag.Inactive` ⇒ trạng thái SAU bảo trì phải = "0".
    if ((m.AfterMtnStatusMain ?? "0") != "0") return Results.BadRequest(new { error = "AfterMtnStatusMain phải = '0'." });
    // 🔴 CẢ HAI hàm (In lẫn Out) đều ném `…_UpdMtnExtOut_InvalidMtnExtEndDTime` khi DB **đã có** `MtnExtEndDTime`.
    if (m.MtnExtEndDTime is not null)
        return Results.BadRequest(new { error = $"Xe đã có ngày ra bảo dưỡng gia hạn ({m.MtnExtEndDTime:yyyy-MM-dd}) — không thao tác tiếp được." });

    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    if (action == "in")
    {
        if (m.MtnExtStatusMain == "IN") return Results.BadRequest(new { error = "Xe đang trong BD gia hạn." });
        m.MtnExtStatusMain = "IN";
        // Nguồn nhận mốc từ LƯỚI (client) chứ không tự đặt; không gửi thì lấy `now`.
        m.MtnExtStartDTime = dto?.MtnExtStartDTime ?? now;
        m.MtnExtEndDTime = null;
    }
    else
    {
        if (m.MtnExtStatusMain != "IN") return Results.BadRequest(new { error = "Xe chưa vào BD gia hạn (IN)." });
        m.MtnExtStatusMain = "OUT";
        m.MtnExtEndDTime = dto?.MtnExtEndDTime ?? now;
    }
    if (!string.IsNullOrWhiteSpace(dto?.UserCodeMtnExt)) m.UserCodeMtnExt = dto!.UserCodeMtnExt;
    if (!string.IsNullOrWhiteSpace(dto?.MtnExtRemark)) m.MtnExtRemark = dto!.MtnExtRemark;
    // 7 cột của `zzB_Update_StoF_MaintainMain_ClauseSet_zzE` (:2325-2333) — LogLU* nằm trong đó.
    m.LogLUDateTime = now; m.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { m.SfMtnNo, vin = m.VIN, status = m.MtnExtStatusMain, m.MtnExtStartDTime, m.MtnExtEndDTime, m.UserCodeMtnExt, m.LogLUDateTime, m.LogLUBy });
}).RequireAuthorization();

// ===== Bảo dưỡng xe tồn kho theo kỳ (VIN_MaintainPeriodHist — port 1:1 FrmMaintenanceHistory) =====
app.MapGet("/api/carmaintenances", async (AppDbContext db, ITenantContext t, string? vin, string? type, string? storage) =>
{
    var q = db.CarMaintenances.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(m => m.Vin.Contains(vin.ToUpper()));
    if (!string.IsNullOrWhiteSpace(type)) q = q.Where(m => m.MtnType == type);
    if (!string.IsNullOrWhiteSpace(storage)) q = q.Where(m => m.StorageCode == storage);
    var items = await q.OrderByDescending(m => m.Id).Take(1000).Select(m => new
    { m.Vin, m.StorageCode, m.ModelCode, m.MtnType, m.MtnTimes, m.MtnDate, m.MtnNextDate, m.UserCode, m.Remark }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Ghi 1 lần bảo dưỡng; MtnTimes = lần thứ n theo VIN+loại; MtnNextDate = MtnDate + chu kỳ (mặc định 90 ngày)
app.MapPost("/api/carmaintenances", async (CarMtnDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Vin)) return Results.BadRequest(new { error = "Cần Vin." });
    var type = string.IsNullOrWhiteSpace(dto.MtnType) ? "MAINTAINANCE" : dto.MtnType.Trim().ToUpperInvariant();
    if (type is not ("MAINTAINANCE" or "EXT")) return Results.BadRequest(new { error = "MtnType = MAINTAINANCE|EXT" });
    var vin = dto.Vin.Trim().ToUpperInvariant();
    var lastTimes = await db.CarMaintenances.Where(m => m.OrgId == t.OrgId && m.Vin == vin && m.MtnType == type)
        .Select(m => (int?)m.MtnTimes).MaxAsync() ?? 0;
    var mtnDate = dto.MtnDate ?? DateTime.Now;
    int cycle = dto.CycleDays is int c && c > 0 ? c : 90;
    var m = new CarMaintenance
    {
        OrgId = t.OrgId, Vin = vin, StorageCode = dto.StorageCode, ModelCode = dto.ModelCode, MtnType = type,
        MtnTimes = lastTimes + 1, MtnDate = mtnDate, MtnNextDate = mtnDate.AddDays(cycle), UserCode = dto.UserCode, Remark = dto.Remark
    };
    db.CarMaintenances.Add(m); await db.SaveChangesAsync();
    return Results.Ok(new { m.Vin, m.MtnType, m.MtnTimes, m.MtnDate, m.MtnNextDate });
}).RequireAuthorization();

// ===== NVBH đại lý (Mst_DlSalesMan — port 1:1 FrmMngSalesManHTC/FrmMngSalesManApproved) =====
string[] _smStatuses = { "THUVIEC", "CHINGTHUC", "CTVIEN", "NGHIVIEC" };
app.MapGet("/api/dlsalesmen", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? approved) =>
{
    var q = db.DlSalesMen.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(s => s.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(s => s.SMStatus == status);
    if (approved == "1") q = q.Where(s => s.SMHyundaiCode != null && s.SMHyundaiCode != "");
    else if (approved == "0") q = q.Where(s => s.SMHyundaiCode == null || s.SMHyundaiCode == "");
    var items = await q.OrderBy(s => s.SMCode).Take(500).Select(s => new
    { s.SMCode, s.SMName, s.DealerCode, s.SMHyundaiCode, s.SMStatus, s.SMGender, s.DateOfBirth, s.SMPhoneNo, s.IdentityCardNo, s.StartDate, s.EndDate, s.SMReason, s.SMDesc,
      s.BDHStatus, s.ChallengeStartDate, s.ChallengeEndDate, s.QualityRank, s.AccountHTA }).ToListAsync();
    return Results.Ok(new { count = items.Count, approved = items.Count(x => !string.IsNullOrEmpty(x.SMHyundaiCode)), items });
}).RequireAuthorization();

// Sửa hàng loạt lý do/mô tả lịch sử công tác (port 1:1 FrmQuanLyLSCongTac, 2010.HTC/Admin/Product)
app.MapPost("/api/dlsalesmen/workhistory", async (DlWorkHistoryDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.SMCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Dữ liệu không thay đổi!" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var code = r.SMCode!.Trim().ToUpperInvariant();
        var s = await db.DlSalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SMCode == code);
        if (s is null) { notFound.Add(code); continue; }
        s.SMReason = r.SMReason; s.SMDesc = r.SMDesc; s.UpdatedAt = DateTime.Now;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

app.MapPost("/api/dlsalesmen", async (DlSalesManDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.SMCode) || string.IsNullOrWhiteSpace(dto.SMName))
        return Results.BadRequest(new { error = "Cần SMCode và SMName." });
    var code = dto.SMCode.Trim().ToUpperInvariant();
    var s = await db.DlSalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SMCode == code);
    if (s is null) { s = new DlSalesMan { OrgId = t.OrgId, SMCode = code }; db.DlSalesMen.Add(s); }
    s.SMName = dto.SMName; s.DealerCode = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    s.SMGender = dto.Sex; s.DateOfBirth = dto.DateOfBirth; s.SMPhoneNo = dto.PhoneNo; s.IdentityCardNo = dto.IdentityCardNo;   // #204: cột đúng nguồn SMGender/SMPhoneNo
    if (!string.IsNullOrWhiteSpace(dto.SMStatus))
    {
        var st = dto.SMStatus.Trim().ToUpperInvariant();
        if (!_smStatuses.Contains(st)) return Results.BadRequest(new { error = "SMStatus = THUVIEC|CHINGTHUC|CTVIEN|NGHIVIEC" });
        s.SMStatus = st;
    }
    // audit 2026-09-03: guard đúng nguồn FrmMngSalesManHTC.btnImportExcel_Click
    if (!string.IsNullOrWhiteSpace(dto.BDHStatus) && dto.BDHStatus != "CHALLENGE" && dto.BDHStatus != "APPOINT")
        return Results.BadRequest(new { error = "Trạng thái BĐH trong excel không hợp lệ!" });
    if (dto.ChallengeStartDate is not null && dto.ChallengeEndDate is not null && dto.ChallengeStartDate > dto.ChallengeEndDate)
        return Results.BadRequest(new { error = "Ngày kết thúc thử thách trong excel trước ngày bắt đầu thử thách!" });
    if (!string.IsNullOrWhiteSpace(dto.QualityRank) && dto.QualityRank != "LV0" && dto.QualityRank != "LV1" && dto.QualityRank != "LV2" && dto.QualityRank != "LV3")
        return Results.BadRequest(new { error = "Xếp loại chất lượng trong excel không hợp lệ!" });
    if (!string.IsNullOrWhiteSpace(dto.AccountHTA) && dto.AccountHTA != "1" && dto.AccountHTA != "0")
        return Results.BadRequest(new { error = "Tài khoản HTA trong excel không hợp lệ!" });
    s.BDHStatus = dto.BDHStatus; s.ChallengeStartDate = dto.ChallengeStartDate; s.ChallengeEndDate = dto.ChallengeEndDate;
    s.QualityRank = dto.QualityRank; s.AccountHTA = dto.AccountHTA;
    s.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { s.SMCode, s.SMName, s.SMStatus, s.SMHyundaiCode });
}).RequireAuthorization();

// Duyệt = cấp mã Hyundai. audit 2026-09-03: KHÔNG lần được nguồn thật cho tính năng "duyệt cấp mã" —
// FrmMngSalesManApproved.cs (đã đọc trọn) thực ra chỉ là màn báo cáo đọc-chốt-tháng (read-only), không có
// nút/logic duyệt nào; FrmMngSalesManHTC.cs (đã đọc trọn) cũng không có. SMHyundaiCode thật ra được SINH TỰ ĐỘNG
// lúc tạo mới NV (FrmCreateSalesMan.GetSequenceGetForSMHyundaiCode), không phải cấp sau qua bước duyệt riêng.
// Giữ nguyên endpoint này như 1 tính năng đơn giản hoá hợp lý (không xoá vì không có bằng chứng nó SAI, chỉ là
// KHÔNG XÁC MINH ĐƯỢC nguồn) — không suy diễn thêm, không tự tin đây là "khớp 1:1".
app.MapPost("/api/dlsalesmen/{code}/grant", async (string code, DlGrantDto dto, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var s = await db.DlSalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SMCode == code);
    if (s is null) return Results.NotFound(new { code });
    if (string.IsNullOrWhiteSpace(dto.SMHyundaiCode)) return Results.BadRequest(new { error = "Cần SMHyundaiCode để duyệt." });
    if (!string.IsNullOrEmpty(s.SMHyundaiCode)) return Results.BadRequest(new { error = $"NV đã có mã Hyundai {s.SMHyundaiCode}." });
    s.SMHyundaiCode = dto.SMHyundaiCode.Trim().ToUpperInvariant();
    if (s.SMStatus == "THUVIEC") s.SMStatus = "CHINGTHUC";   // duyệt → chuyển chính thức
    s.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { s.SMCode, s.SMHyundaiCode, s.SMStatus });
}).RequireAuthorization();

