    var g = new GpsClaim { OrgId = t.OrgId, GpsClaimNo = no, GpsDvNo = dto.GpsDvNo.Trim().ToUpperInvariant(), BeforeFixRemark = dto.BeforeFixRemark, Remark = dto.Remark, ClaimStatus = "Pending" };
