        .Select(c => new { c.Vin, c.StorageCode, c.DtlStatus, c.TranspReqType, c.RefOrdNo, c.CarId, c.LogLUDateTime, c.LogLUBy }).ToListAsync();
    return Results.Ok(new { r.TranspReqNo, r.Status, count = cars.Count, cars });
